INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685033', '보안솔루션의이해', '정보과학대학', '정보과학대학', 0, 3, '전선', '김한수', '컴퓨터 과학의 기초를 기본 원리부터 최신 기술에 이르기까지 폭넓게 학습한다. 융합과학수사학과 1학년 학생들에게 과학수사, 정보 보안 및 디지털 포렌식의 기초가 되며 현대 사회를 살아가는데 필수적인 컴퓨터와 그 시스템의 전반적인 지식을 쌓도록 한다. 컴퓨터 를 다루는 이들은 물론이고 건강한 사회인이 되기 위해 기본적으로 알아야 할 네트워크, 데이터베이스, 이진수, 논리 회로 등에 관한 핵심 내용을 학습하며, 4차 산업혁명, 빅데이터, 사물인터넷, 블록체인, 메타버스, NFT, 인공지능 등의 최신 주제를 다룬다. 모든 과정 은 생성형AI를 활용하여 학습하고, 다양한 prompting을 통해 최신 AI 기술을 직접 경험하게 한다. 보안 솔루션 및 컴퓨터과학의 기본 이해: 컴퓨터의 역사부터 최신 기술 동향까지를 이해하고, 컴퓨터과학의 주요 개념과 원리를 숙지 한다. 생성형 AI의 활용 및 주요 기술 이해: 단순 사용에 그치지 않고 다양한 prompting 및 engineering을 통해 자연어 처리 모델 및 생성형 AI의 기본 원리와 활용방안을 두루 익힌다. 네트워크와 통신 이해: 네트워크의 기본 원리와 동작 방식에 대한 이해를 통해 학생들은 현대 사회에서 중요한 역할을 하는 컴퓨터 네트워크와 통신 기술을 파악한다. 데이터베이스 및 빅데이터 처리: 데이터의 저장, 관리, 분석에 대한 핵심 개념을 이해하고, 실제 상황에서 데이터베이스와 빅데이터 기술을 활용하는 능력을 갖춘다. 멀티미디어 및 최신 기술 탐험: 오디오, 이미지, 동영상 등 다양한 형태의 멀티미디어에 대한 이해를 통해, 최신 기술 동향을 파악하고 활용하는 능력을 키운다.', '{"컴퓨터","데이터베이스","빅데이터","네트워크","AI","사물인터넷","과학","보안","컴퓨터과학","동향","처리","통신","파악","멀티미디어","prompting","인공지능","자연어처리","컴퓨터네트워크"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('605000', '정보과학개론', '정보과학대학', '정보과학대학', 0, 1, '공통전선', '최종환', 'SW·AI 계열 또는 자유전공학부 신입생 이외에는 수강신청할 수 없는 교과목입니다  - 본 과목은 SW·AI계열 및 자유전공학부 신입생을 대상으로 하며, 현대 정보과학의 광범위한 스펙트럼을 탐험하고 향후 2학년 진입 시 자신에게 적합한 세부 전공을 주체적으로 결정할 수 있는 학문적 기반 마련을 목표로 함 - 거대언어모델(LLM)을 활용한 신약 개발 및 화학정보학, AI 기반 실내 위치 인식 시스템, 그리고 뇌공학과 생체신호처리가 결합된 의 료 인공지능 등 인공지능 기술이 바이오·헬스케어 및 인류의 삶(AI for Human)에 기여하는 융합적 사례를 심층적으로 살펴봄 - 정보보안의 근간인 암호학과 블록체인부터 영상처리 기반의 AI 보안 및 멀티미디어 보안 기술을 학습하며, 차세대 6G 무선통신과 AI의 상호 결합(AI for Communications), 그리고 가상현실(VR/AR)과 디지털 트윈이 창조하는 미래형 시뮬레이션 환경의 동작 원리를 파악함 - 뇌 계산 모델링을 통한 개인맞춤형 진료(디지털 트윈), 법률 문서 자동 분석을 위한 에이전트 기반 지능형 시스템 등 최신 AI 기술이 전문가 의사결정을 지원하는 실제 연구 현장을 접함으로써, 기술적 원리를 넘어선 정보과학의 실질적 가치를 이해함 - 각 분야를 선도하는 교수진의 옴니버스식 강의와 연구실(Lab) 소개를 통해 추상적이었던 전공 이미지를 구체화하고, 매주 진행되는 퀴즈와 전공 탐색 레포트를 통해 신입생으로서의 소속감 고취 및 자기주도적인 진로 로드맵 설계 역량을 배양함 SW·AI 계열 또는 자유전공학부 신입생 이외에는 수강신청할 수 없는 교과목입니다  본 교과목은 SW·AI 계열 또는 자유전공학부 신입생들이 첨단 정보과학의 방대한 세계를 탐험하고, 각 분야 전문가인 교수진의 연구 실(Lab) 현장을 생생하게 접함으로써, 자신에게 꼭 맞는 세부 전공과 진로를 확신을 가지고 설계할 수 있는 역량을 갖추는 것을 목표 로 합니다. 2. 교과 목표', '{"AI","전공","계열","SW","자유","학부","기반","정보과학","목표","지능","보안","정보보안","신호처리","가상현실","수강신청","탐험","시스템"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('511601', '선형대수', '정보과학대학', '정보과학대학', 1, 3, '공통전선', '신범주', '행렬, 행렬식, 역행렬, 선형연립방정식 해법, 벡터 내적, 외적, 벡터공간, 고유값, 고유벡터 등 선형대수학 관련 수학점 개념을 익힌다. 선형대수학 내용을 python으로 실습을 진행해본다. 선형대수학이 머신러닝, 딥러닝에 어떻게 적용되는지 파악한다. 행렬, 행렬식, 역행렬, 선형연립방정식 해법, 벡터 내적, 외적, 벡터공간, 고유값, 고유벡터 등 선형대수학 관련 수학점 개념을 익힌다. 위의 지식 내용을 바탕으로 다양한 문제를 풀수있는 능력을 키운다. 선형대수학이 머신러닝, 딥러닝등의 실무에서 어떻게 활용되는지 파악한다.', '{"선형대수학","러닝","행렬","행렬식","역행렬","선형","방정식","해법","벡터","내적","외적","벡터공간","고유값","고유벡터","학점","머신","파악","머신러닝","딥러닝","선형대수"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506819', '자바프로그래밍Ⅰ', '정보과학대학', '정보과학대학', 1, 3, '공통전선', '김진', '본 과목은 대표적인 객체 지향 프로그래밍 언어인 자바에 대해 학습함으로서 자바를 이용한 프로그램 개발 역량을 키운다. - 프로그래밍 언어에 대해 이해한다. - 프로그램 작성 환경과 실행 환경을 이해한다. - 프로그램 작성 절차와 원하는 처리 결과를 얻기 위한 연산 제어를 할 수 있다. - 객체지향 프로그래밍 구조를 이해하고 자바를 이용해 객체를 설계하고 작성할 수 있다. - 자바를 이용해 기초적인 응용 프로그램을 작성할 수 있다. - 오픈소스 소프트웨어를 이용하여 프로그램을 작성하고 실행 할 수 있다. 본 교과목을 통해 학습자는 객체지향적 프로그래밍 방법을 이해하고 이를 이용해 저학년에서는 다양한 프로그램 작성 방법을 익히고 고학년에서는 다양한 분야에서의 응용프로그램 개발 및 활용할 수 있다. 본 교과목을 이수함으로써 학습자는 프로그램을 작성할 수 있는 능력을 배양할 수 있음. 구체적으로 -프로그램을 개발하는 절차와 방법을 이해한다. -객체지향의 개념과 객체지향 프로그램의 구조와 특징을 이해한다. -실습과 과제를 통해 문제 해결 능력을 향상시킨다. -자바를 이용한 프로그램을 작성할 수 있다.', '{"프로그램","작성","객체지향","자바","객체","프로그래밍","개발","언어","환경","실행","절차","구조","학습자","저장","과목","지향","역량"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506820', '자바프로그래밍Ⅱ', '정보과학대학', '정보과학대학', 1, 3, '공통전선', '이은주', '자바 프로그래밍1에서 프로그래밍의 개념과 이해를 정립하였다면 본 강좌에서는 자바언어가 객체 지향 언어로서 가지는 특성을 깊 이있게 학습하여 현실 세계의 문제 해결을 위한 프로그램 작성 시 객체 지향 특성을 활용할 수 있도록 하는 것을 목표로 한다. 이러한 목표를 이루기 위해 자바 프로그래밍2 에서 다룰 내용은 다음과 같다. - 자바 프로그래밍 1 복습: 클래스와 객체, 상속 - 인터페이스와 람다식 - 예외처리와 Thread - 제네릭과 컬렉션 - 파일 입출력 - 자바 API - 자바 프로그래밍1에서 학습한 기초 문법을 기반으로 클래스를 구현할 수 있으며 이러한 과정을 통하여 클래스 구조와 객체에 대한 이해를 명확하게 한다. - 상속과 다형성 및 예외처리, 파일 입출력, 자바API 등 심화된 객체 지향 방법을 학습한 후 객체 지향 프로그래밍 기법을 문제 해결에 적용하여 프로그램을 설계하고 구현할 수 있는 능력을 높인다.', '{"자바","객체","프로그래밍","클래스","지향","언어","특성","해결","프로그램","목표","상속","예외처리","파일","입출력","구조","패키지","API","객체지향","정립","강좌"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506808', 'C++프로그래밍', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '양은샘', 'C++ 언어에 대한 문법과 적용을 학습한 후 그 지식을 바탕으로 객체지향 프로그램의 흐름을 이해하고 기본적인 C++ 응용프로그램 을 구현 할 수 있도록 한다. 1) C언어와 C++언어의 공통점과 차이점을 이해할 수 있다 2) C++ 언어가 가지는 고유한 특징을 이해하고 활용할 수 있다 3) 이론과 실습을 통해 클래스 구현과 객체 생성, 상속, 다형성, 연산자 오버로딩, 예외처리, template, STL library 등 객체지향적 설계 를 적용한 응용 프로그래밍으로 소프트웨어 개발에 대한 역량을 강화할 수 있다. <교육방법> - 이 교과목은 [혼합형학습 수업유형] 교과목이다. - 이론수업(스마트리드를 이용한 동영상 수업)과 실습수업(대면수업)을 병행한다. 1) C++ 언어와 다른 객체 지향 언어의 차이점을 이해할 수 있다. 2) C++ 언어만 가지는 문법 구조를 응용 프로그램 개발에 활용할 수 있다. 3) 실습과제를 해결하고 이를 통해 문제 해결 능력을 키울 수 있다. 4) C++ 언어의 고급기능을 자유롭게 활용할 수 있다.', '{"언어","C++","적용","객체지향","객체","프로그래밍","문법","프로그램","차이점","개발","해결","STL","AI","Template","지식","흐름","응용프로그램","공통점"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('511644', 'C프로그래밍', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '김진환', '- 본 교과목은 C언어가가 가진 특성을 이해하고 프로그래밍 설계에 활용할 수 있는 기초 능력 배양을 목표로 한다. - C언어의 전반적인 내용(개요, 제어문, 자료형, 변수, 식, 배열과 문자열, 함수, 포인터, 구조체, 파일입출력)을 정확히 이해하고 이를 이용한 다양한 프로그래밍 기법들을 실습한다. 교과목을 이수함으로써 학습자는 C언어 프로그램을 작성할 수 있는 능력을 배양할 수 있다. - 프로그램을 개발 하는 절차와 방법을 이해한다. - C언어의 구조와 특징을 이해한다. - 실습과 과제를 통해 문제 해결 능력을 향상한다. - C 언어를 이용한 프로그램 작성을 할 수 있다.', '{"언어","프로그램","프로그래밍","배양","작성","특성","목표","개요","어문","자료형","변수","배열","문자열","함수","포인터","구조체","파일"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('511215', '논리설계및실험', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '이선우', '본 과목은 컴퓨터 하드웨어의 기본이 되는 디지털 회로의 기초(수 체계, 코드, 논리게이트, 불 대수, 조합논리회로, 순차논리회로 등) 를 학습한다. 본 과목의 수강을 통해 우리 일상생활의 거의 모든 부문에서 사용되는 컴퓨터 하드웨어를 구성하는 디지털 논리 시스템 의 이해와 분석, 설계에 필요한 기초 개념을 배운다. 본 수업을 통해 다음의 역량을 가질 수 있다. -디지털의 개념을 이해하여 아나로그와의 차이점을 이해함 -기초적인 수 체계를 이해함. 특히 2진수를 이용한 정수와 부동소수의 표현 방법을 이해하고 다양한 진법으로 수를 표현하고 변환하 는 능력을 가짐 -AND, OR, XOR 등의 여러 논리게이트의 종류 및 특성을 이해하고 이를 활용하여 논리 시스템을 설계할 수 있다. -불 대수(Boolean algebra)의 법칙과 논리식 표현 방법을 이해하고, 이를 활용하여 복잡한 논리식을 간소화할 수 있다. -조합논리회로(Combinatorial logic circuit)를 설계하고 구성하는 방법을 이해한다. 특히 가감산기, 비교기 등을 이해하고 구현할 수 있다. -순서논리회로(Sequential logic circuit)를 설계하고 구성하는 방법을 이해한다. 특히 플립플롭의 동작 원리를 이해하고 이를 이용하 여 카운터를 구현할 수 있다.', '{"논리회로","디지털","구성","표현","과목","컴퓨터","하드웨어","체계","논리게이트","대수","조합","논리","시스템","논리식","logic","circuit","회로","코드","순차"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603126', '데이터사이언스기초', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '김유섭', '1) 데이터 핸들링 및 정제 : 가공되지 않은 데이터를 분석 가능한 형태로 구조화하고 품질을 높이는 엔지니어링 역량을 키운다. 2) 통계적 추론 및 EDA: 탐색적 데이터 분석을 통해 데이터 뒤에 숨겨진 패턴을 발견하고, 통계적 근거를 바탕으로 유의미한 가설을 설정하는 분석 역량을 키운다. 3) 모델링 파이프라인 이해 : 회귀와 분류 등 머신러닝의 기초 알고리즘을 활용하여 예측 모델을 구축하고 성과를 평가하는 시스템적 사고력을 키운다. 4) 윤리 및 책임감 : 인공지능 개발자로서 데이터를 다룰 때 반드시 지켜야 할 개인정보 보호 원칙과 윤리적 판단력을 키운다. 원천 데이터(Raw Data)로부터 유의미한 가설을 도출하고, 이를 검증하기 위한 시각화 및 기초 머신러닝 모델을 스스로 구현할 수 있 으며, 이 모든 과정에서 데이터 윤리를 실천하는 준비된 AI 엔지니어로 성장한다.', '{"데이터","사이언스","역량","통계","윤리","의미","가설","머신","러닝","모델","기말고사","머신러닝","인공지능","정보보호","핸들링","정제","가공","형태","구조","품질"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603119', '소프트웨어개론', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '김진환', '본 과목은 소프트웨어의 전반적인 기술범위와 사용범위에 대한 개론으로 소프트웨어를 개발하기 앞서 필요 지식 습득을 목표로 한 다. 모든 응용소프트웨어(모바일 앱, 웹, 데이터베이스, 네트워킹 등)는 운영체제의 도움과 관리하에 동작된다. 또한 대부분의 소프트 웨어는 데이터베이스 시스템의 도움을 받아 데이터를 검색, 수정, 생성, 저장 관리한다. 그리고 소프트웨어의 모든 신호와 데이터를 송·수신하기 위해 네트워킹 시스템의 도움을 받는다. 즉 모든 소프트웨어가 동작하기 위해서는 운영체제, 데이터베이스 시스템, 그리고 네트워킹 시스템의 도움이 절대적으로 필요하다. 본 과목에서는 이 세 가지 구성요소들의 기본 개념을 중심으로 설명한다. 소프트웨어의 전반적인 기술범위와 사용범위에 대한 개론으로 소프트웨어를 개발하기 앞서 필요 지식 습득을 목표로 한다.', '{"소프트웨어","데이터베이스","범위","도움","시스템","운영체제","네트워킹","과목","개론","개발","지식","습득","목표","관리","동작","데이터"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603121', '신호및시스템', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '박지현', '- 신호와 시스템에 관한 지식은 전자공학을 비롯한 공학 전반의 기본적인 요소이다. 이 과목에서는 신호를 해석하는 기본적인 원리와 방법을 배운다 - 구체적으로 연속적인 신호와 이산 시간 신호의 시간 영역 표현법과 주파수 영역 표현법을 배운다. 또한 신호를 해석하는 방법 가운 데 주파수 해석 방법이 매우 중요한데 연속/이산 신호 중에서 각 주기/비주기 신호를 주파수 영역으로 변환하는 도구인 푸리에 전개 및 푸리에 변환의 기본 원리와 활용 능력을 배운다 - 이 과목에서는 공학용 도구인 파이썬과 관련 라이브러리를 이용하여 신호를 해석하는 방법도 함께 배운다 이 강의를 수강한 후에 학생들은 - 이산시간/연속시간 신호의 수학적 표현 방법을 이해할 수 있어야 한다. - 신호의 주파수 영역 분석 방법을 이해할 수 있어야 한다.', '{"신호","시간","영역","주파수","해석","연속","이산","표현","시스템","공학","과목","주기","변환","도구","푸리","푸리에변환","지식","전자공학"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506702', '웹프로그래밍', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '신미영', '본 수업은 프로그래밍 기초 과정을 이수한 후 프런트 엔드 프로그래밍 과정을 이해하고 최신 경향의 웹 프로그래밍 기술을 구현할 수 있는 가이드를 제시하는 것을 목적으로 합니다. 이를 위해 프런트 엔드 프로그래밍의 표준이 되는 CSS, JavaScript와 React 기술에 대 해 학습하게 됩니다. CSS에서는 선택자와 웹 디자인을 위한 기술을 학습하고 JavaScript는 React 라이브러리를 학습하기위해 필요한 ES6에 추가된 기능과 DOM, 이벤트처리를 다룹니다. React에서는 JSX, 컴포넌트, 훅 등을 학습하며 이를 활용하여 효율적인 웹 프로 그램 개발을 할 수 있습니다. 웹 프로그래밍 구현과 실습과정에서 생성형 AI를 도구로 활용합니다 본 교과 과정을 통하여 학습자들은 1) 웹 브라우저를 통한 자료 검색 및 분석 능력이 강화됩니다. 2) 웹 프로그램의 제작과정과 설계 과정을 이해하게 되고, 웹 프로그램의 전반적인 흐름을 파악하게 되어 웹의 기술적 프로세스 설계 와 웹 프런트엔드 개발 역량이 강화됩니다. 3) 과제 수행을 통하여 개발 역량을 강화합니다. 4) 웹 표준을 이해하고 이를 활용할 수 있습니다', '{"프로그래밍","개발","React","프런트","엔드","표준","강화","프로그램","역량","CSS","JavaScript","DOM","웹프로그래밍","이수","경향","가이드","제시","목적","선택","디자인"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603146', '인공지능생체시스템개론', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '안재목', '1. 인공지능 기초와 이론 -인공지능의 역사 및 기본개념 -기계학습 및 신경망의 기본 원리 -심화 신경망 아키텍처 2.생체신호처리 -EEG, ECG, EOG등 생체신호처리방법론 -뇌-컴퓨터 인터페이스 3.세포수준의 생체신호 -전기생리학 4.인공지능의 윤리적, 사회적 영향 -인공지능의 기본원리와 기술을 이해하고, 생체시스템과의 관계를 학습한다. -기계학습, 생체전기신호 발생 등의 의공학적 기술을 학습한다. -생체신호처리와 인공지능의 상호작용을 학습한다. -인종지능의 다양한 실용적 응용 사례를 분석하고 이해한다. -인공지능의 윤리적, 사회적 영향을 고찰한다.', '{"지능","인공","생체","신호처리","기계학습","신경망","신호","윤리","영향","인공지능","역사","아키텍처","방법론","컴퓨터","인터페이스","세포","수준","전기생리학","시스템","관계"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('511643', '자료구조', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '엄상용', '컴퓨터로 문제를 해결하기 위하여 먼저 알고리즘을 설계하며, 컴퓨터 프로그래밍은 이 알고리즘의 구현이다. 프로그래밍을 통하여 알 고리즘을 구현할 때, 프로그램의 매우 중요한 요소인 자료구조를 선택해야 한다. 이 과목에서는 자료구조의 기본 개념과 종류, 특징, 구현 등에 대해서 학습한다. 어떠한 문제를 해결함에 있어 서로 다른 자료구조를 사용할 때, 자료구조가 알고리즘 혹은 프로그램의 효율에 미치는 영향을 이해한다. 이번 학기에는 주로 선형자료구조인 선형리스트를 중심으로 학습한다. 선형리스트의 특별한 형태인 스택, 큐 등에 대해서도 학습한다 . 이 과목의 핵심은 자료구조에 관한 개념들을 이해하고, 실제 프로그램밍을 통해서 필요한 자료구조를 구현할 수 있는 능력을 향상시 키는 것이다. 문제 해결을 위한 알고리즘 개발 능력을 배양한다. 동일한 문제일지라도 선택한 자료구조에 따라서 알고리즘의 성능이 큰 차이를 보일 수 있으므로, 이러한 알고리즘의 성능의 차이를 메모리 공간과 CPU 사용 시간의 관점에서 비교 분석한다. 또한 문제에 따라서 가장 적절한 자료구조를 선택하는 능력을 함양한다. 가장 중요한 목표는 주어진 알고리즘을 구체적인 프로그래밍언어 (특히 Java 언어)로 구현하는 능력을 향상시키는 것이다.', '{"자료구조","알고리즘","해결","프로그램","선택","선형","컴퓨터","프로그래밍","과목","리스트","향상","성능","차이","리즘"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603108', '파이썬과학프로그래밍기초', '정보과학대학', '정보과학대학', 2, 3, '공통전선', '김병정', '온라인과 오프라인 혼합 블랜딩 수업으로 진행이 된다. 공학 분석 툴로 널리 사용되고 있는 MATLAB의 대체 툴인 파이썬에 대해 강의한다. 수학 계산, 분석, 영상 처리, 제어 등 여러 공학영역에서 사용하고 있는 다양한 파이썬 시뮬레이션 툴의 이해와 사용법에 대해 강의하 고 실제 프로그래밍을 통해 적용 능력을 키운다. 선형대수, 수치해석, 데이터사이언스, 신호해석, DSP, IoT머신러닝, 데이터베이스,인공지능의 선수 과목이다. 파이썬 프로그램의 기초 문법을 빠르게 복습하며, 다차원 데이터에 대한 효과적인 처리 방법 및 정량적 데이터 표현 방법을 배운다.', '{"파이썬","데이터","데이터베이스","선형대수","공학","처리","환경","머신러닝","인공지능","영상처리","온라인과","오프라인","혼합","블랜딩","진행","대체","수학"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509520', '농구(기초)', '자연과학대학', '자연과학대학', 0, 1, '전선', '한승백', '이 강좌는 대표적인 구기 스포츠인 농구의 실기실습 수업이다. 기초 강좌이니 만큼 농구 경기의 기본 기술 및 운동능력을 익히는데 그 목적이 있다. 패스, 드리블, 슛, 수비에 관한 기초 기술을 익히고, 각종 드릴을 활용해 연습할 기회를 갖는다. 농구의 규칙 습득 농구의 기초 기술 습득 농구의 응용 기술 습득 농구 경기를 위한 능력 배양', '{"간의","경기","패스","드리블","농구의","기술","농구","규칙의","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('602106', 'IOT네트워크', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '김의직', '본 강의에서는 IoT 네트워크의 개념을 이해하며, 대표적인 사물인터넷 네트워크 프로토콜인 CoAP(Constrained Application Protocol) 및 MQTT(Message Queuing Telemetry Transport)의 메시지 포맷, 전송 모델, 확장 프로토콜에 대해 학습한다. 오픈소스 프로젝트를 활용한 CoAP 및 MQTT 어플리케이션 실습을 통해 IoT 네트워크에 대한 실무 지식을 학습한다. IoT 네트워크의 개념을 이해하며, 대표적인 사물인터넷 네트워크 프로토콜인 CoAP(Constrained Application Protocol) 및 MQTT(Mes sage Queuing Telemetry Transport)의 메시지 포맷, 전송 모델, 확장 프로토콜에 대해 학습한다. 오픈소스 프로젝트를 활용한 CoAP 및 MQTT 어플리케이션 실습을 통해 IoT 네트워크에 대한 실무 지식을 학습한다.', '{"네트워크","프로토콜","IoT","CoAP","MQTT","사물인터넷","메시지","포맷","전송","모델","확장","오픈소스","어플리케이션","실무","지식","Constrained","Application","Protocol"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('601108', '가상현실과증강현실', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '김선정', '상용게임엔진인 유니티3D를 이용하여 3차원 가상/증강현실 콘텐츠를 제작하는 방법을 학습한다. 가상현실 HMD 장비를 활용하는 VR 콘텐츠와 모바일 기기를 활용하는 AR 콘텐츠를 제작한다. 기말 프로젝트를 제안하고 구현한다. * 목표: Unity3D를 이용한 VR/AR 콘텐츠를 제작할 수 있다. * 지식: 가상현실과 증강현실의 원리를 이해하고 습득한다. * 기술: 가상/증강현실 어플을 구현하기 위한 프로그래밍 능력을 기른다.', '{"증강현실","콘텐츠","가상현실","제작","가상","상용","게임엔진","유니티","차원","장비","모바일","기기","제안","목표","지식","습득","어플","프로그래밍","HMD"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603128', '계산이론', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '주한규', '컴퓨터공학의 기초 이론이 되는 계산이론의 기본적인 개념을 공부한다. 언어와 이를 인식하는 오토마타 등을 배우며 이 강좌에서 습득된 이론은 여러 분야 - 프로그래밍 언어, 소프트웨어 공학, 컴파일러 구 성 등 - 의 기초가 된다. 언어, 문법, 정규언어, 문맥 자유 언어 등의 언어와 오토마타에 이해한다. 이를 통하여 문제해결 능력을 얻도록 한다.', '{"언어","오토마타","컴파일러","Context","Free","소프트웨어공학","컴퓨터공학","계산이론","공부","인식","강좌","습득","프로그래밍","소프트웨어","공학","문법","정규","문맥","자유"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('600001', '데이터마이닝', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '박성미', '데이터마이닝 수업은 데이터 처리와 분석의 기본 개념부터 고급 기법까지 포괄적으로 학습하며, 실무에서의 데이터 분석 역량을 배 양하는 과목이다. 이 강의는 데이터 전처리, 데이터 분석, 모델링, 평가 등 데이터마이닝 과정 전반을 Python과 관련 라이브러리(Pan das, NumPy, Matplotlib 등)를 활용해 실습하며, SQL과 데이터 시각화를 포함한 데이터 핸들링 기술을 심화한다. 다양한 예제 데이터 기반의 실습과 edX 강의를 활용한 심화 학습을 병행하며, 프로젝트를 통해 윤리적 데이터 크롤링, 텍스트 데이터 분석, SQL 기반 데 이터 처리 등의 실무 사례를 경험한다. 또한, GPT와 같은 대형언어모델(LLM)을 데이터 분석에 접목하여 데이터마이닝과 인공지능 기 술의 융합 능력을 키우는 것을 목표로 한다. 이를 통해 학생들은 데이터를 효율적으로 처리하고 분석할 수 있는 실력을 갖추며, 실제 데이터 기반 문제를 해결하고 프로젝트를 수 행할 수 있는 실무적 역량을 강화하게 된다. 이 교과목은 데이터 처리와 분석의 기본 원리를 이해하고, Python과 SQL을 활용한 데이터마이닝 기술을 학습하는 것을 목표로 한다. 학생들은 데이터 전처리, 탐색적 데이터 분석(EDA), 모델링, 평가 등 데이터마이닝 과정 전반을 실습하며, 언어모델을 활용한 텍스트 데이터 분석 등 최신 AI 기술을 프로젝트에 적용한다.', '{"데이터","데이터마이닝","처리","실무","기반","SQL","역량","모델링","텍스트","언어","모델","목표","Python","인공지능","데이터시각화","기법","포괄","과목","라이브러리"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('600007', '데이터베이스시스템', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '최종환', '- 본 과목은 관계형 데이터 모델과 SQL 등 기초 지식을 갖춘 학생들을 대상으로 하며, 단순한 데이터베이스 사용자를 넘어 데이터베 이스 관리시스템(DBMS)의 내부 설계 원리와 동작 매커니즘을 심도 있게 학습하는 것을 목표함 - 데이터가 하드 디스크(HDD) 및 SSD에 물리적으로 저장되는 구조를 이해하고, 대규모 데이터 환경에서 검색 성능을 극대화하기 위 한 B+-트리, 확장성 해싱(Extendable Hashing), 그리고 쓰기 최적화된 LSM 트리 등 다양한 인덱싱 기법의 비용과 효율성을 분석함 - 사용자가 작성한 SQL 문이 관계 대수(Relational Algebra)로 변환되어 실행되는 과정을 파싱, 변환, 최적화 단계별로 학습함. 특히 통계 정보 기반의 비용 기반 최적화(Cost-based Optimization) 절차를 통해 가장 효율적인 실행 계획(Execution Plan)을 수립하는 논 리를 습득함 - 다중 사용자 환경에서 데이터의 무결성을 보장하기 위한 ACID 속성을 이해하고, 2단계 잠금 규약(2PL) 및 교착 상태(Deadlock) 탐 지 기범을 통해 시스템의 고립성과 일관성을 유지하는 기술적 방안을 학습함 - 전통적인 관계형 데이터베이스를 넘어, 최근 AI 애플리케이션의 핵심인 벡터 데이터베이스(Vector Database) 및 RAG(Retrieval-Aug mented Generation) 기법의 원리를 파악하여 현대적 데이터 관리 역량을 배양함 본 교과목은 수강생들이 데이터베이스 시스템의 핵심인 관계형 모델의 심화 이론을 학습하고, DBMS 내부의 물리적 구조와 실행 메 커니즘을 이해함으로써 고도화된 데이터 관리 역량을 갖춘 데이터베이스 관리자(DBA) 및 시스템 아키텍트로 성장하는 것을 목표함 ● 지식 영역 - 물리적 저장 장치 및 시스템 구조 이해: HDD와 SSD의 기계적·전기적 특성 차이를 파악하고, SATA, NVMe 등 인터페이스 규격과 R AID 수준별(0, 1, 5, 6, 10) 신뢰성 및 성능 지표를 비교 설명할 수 있다. - 데이터 저장 구조 및 버퍼 관리 최적화: 슬롯 페이지 구조(Slotted Page Structure)와 가변 길이 레코드 저장 방식을 이해하고, 디스 크 I/O 최소화를 위한 버퍼 관리자의 교체 정책(LRU 등)이 시스템 성능에 미치는 영향을 분석할 수 있다. 2. 교과 목표', '{"데이터","데이터베이스","관계","시스템","구조","최적화","관리","저장","사용자","목표","물리","성능","변환","실행","통계","기반","모델","지식","내부","환경"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('600008', '데이터시각화', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '이재영', '1. 본 과목은 빅데이터에 관한 기본적인 데이터를 그래프로 표시하는 방법을 다루는 과목으로써, 수강생이 빅데이터 전문가가 되기 위한 기초과정으로 공공 데이터를 수집하여 분석한 결과를 시각적으로 이해하기 쉽게 여러 가지 도표나 그래프 등으로 나타내는 기 술을 배운다. 이 과목을 이수하면 데이터를 다양한 도표와 그래프를 사용하여 이해하기 쉽게 시각화할 수 있고, 추가로 데이터를 분석한 후 나온 결과 데이타를 시각화 할 수 있다.', '{"데이터","시각","빅데이터","과목","그래프","도표","데이터시각화","표시","수강생","전문가","공공","수집","이수","추가","데이타","화의","개요"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506209', '머신러닝', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '안재목', '머신러닝의 과목은 학생들에게 머신러닝의 기본 개념과 모델구축, 다양한 머신러닝 알고리즘에 대해서 소개한다. 학생들은 머신러닝 의 실습을 통해 데이터 준비, 학습, 성능평가, 예측 등 머신러닝과 관련된 알고리즘 구축에 필요한 실전능력을 학습한다. -데이터 전처리 능력 향상 -머신러닝의 기본개념 이해 -머신러닝 알고리즘 구축 및 평가 능력 향상 -머신러닝 모델을 구축하여 실제문제 해결 능력 향상', '{"머신","러닝","구축","알고리즘","향상","모델","데이터","머신러닝","과목","준비","성능","예측","실전","처리","실제","해결"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('602107', '모바일센서공학', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '안재목', '모바일센서공학 수강자들은 본 강의를 통해 센서의 이해력을 높이고 센서를 쉽게 응용할 수 있는 능력을 갖추도록 한다. 스마트폰은 우리 삶의 일부로 자리 잡고 있는 첨단 시대에 센서의 기술은 미래의 엔지니어들이 반드시 갖추어야 할 필수적인 지식이다. 소프트웨 어 엔지니어들도 센서의 전기적인 특성의 지식을 갖춘다면 고급 프로그래밍의 능력자로 인정받을 수 있을 것이다. 4차산업혁명의 시 대는 인간의 6번째 감각을 구현하는 기술이 중요하기 때문에 센서의 응용은 무한하다고 할 수 있습니다. 본 수업을 마친 학생은 다음의 능력을 갖게 된다. - 스마트 센서의 종류, 물리적 특성, 모바일 및 자동차 응용 등을 이해하게 된다. - 센서의 전기적 특징의 이해를 바탕으로 입력전압 vs 출력전압의 관계, 노이즈 해결 및 센서용 전치증폭기 설계를 할 수 있다. - 센서의 작동원리를 이해하여 센서의 활용능력을 갖추게 된다.', '{"센서","기적","특성","모바일","엔지니어","지식","물리","전압","모바일센서","센서공학","공학","이해력","스마트폰","일부","자리","잡고","첨단","시대"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603139', '보안인증기술', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '김재성', '본 수업은 포스트 코로나 시대에 급증하는 비대면 디지털 사회에서 정보보호의 중요성이 부각되면서 사이버 공간에서의 경제활동을 위해 필수적인 사용자 인증기술인 패스워드(지식기반), OTP·QR코드(소지기반), 바이오인식(생체기반) 등 전반적인 보안인증기술에 대 한 개론과 함께 특히, 출입통제·모바일 결제·디지털 헬스케어·문서인증 등 생활속에 실재로 널리 사용되고 있는 바이오인식기술의 기 본원리, 상용기술, 차세대 융합기술과 더불어 국내외 표준화에 대하여 폭넓게 다루고자 합니다. 1) 실생활 속에서 널리 사용되고 있는 보안인증기술에 대한 전반적인 이해와 함께 앞으로 다가올 비대면 디지털 환경에서 부각되는 바이오인식기술에 대한 광범위한 이해를 증진하고 상용기술에 현주소를 파악하여, 미래지향적인 정보보호 역량을 강화하고자 합니 다. 2) 폭넓은 이론과 상용화기술에 대한 강의, 연구보고서에 대한 리포팅과제, 개별적인 발표와 토론을 통한 이론과 소통연습을 통하여 정보보안 나노 디그리 교육과정을 통하여 사회현업에 바로 적응할 수 있는 실무형 인재를 양성하기 위함입니다.', '{"인증","바이오인식","정보보호","디지털","기반","상용","정보보안","비대","부각","보안","보안인증","포스트","코로나","시대","급증","중요성","사이버"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603127', '소프트웨어특강Ⅰ', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '박승용', '본 강의는 산학연계교과목으로 운영되며, 다양한 IT 분야의 산업체에서 SW가 어떻게 사용되고 있는 지를 산업체 전문가를 통해서 살 펴 본다. 강사는 우리 나라의 유수한 IT 업체의 CEO, 이사, 개발자 및 연구원 등으로 구성된다. 매주 2명씩 산업체 강사가 강의를 진행한다. 매 시간 특강은 50분의 발표와 25분간의 학생들의 질의&답변으로 구성된다. 학생들은 강사가 소속된 업체들의 비전, 일반 현황, 주요사업, 재정상태, 주요 아이템 등을 조사하여야 하며, 각 기업체에 대해서 질문 을 1-2개씩 준비해야 한다. (특이사항) 게임, AI, IoT, SI, XR 등의 다양한 분야의 업체에 근무하는 한림대학교 졸업생으로 특강 강사진이 구축되어 있습니다. - 재학생들에게 취업을 준비시키기 위함이다. 기업체의 건강상태 등을 파악하는 능력을 향상 시킨다. - 기업체에서 관리자 혹은 개발자 등의 구성원으로서의 자세 등을 배우게 한다. - 취업을 준비하기 위해서 재학 중에 어떠한 준비를 해야 할 지를 깨닫게 한다.', '{"업체","준비","과목","강사","발표","기업체","산학","계교","운영","개발자","구성","진행","특강","상태","취업","IT","전문가","나라"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506714', '영상처리프로그래밍', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '정태경', '○ 본 과목은 ICT 기술의 발전으로 시각지능에 대한 많은 연구와 발전이 있는 가운데 우리 생활에 깊숙이 침투한 디지털 영상처리 기 술에 대하여 학습하도록 한다. 이를 통한 영상처리 프로그램의 시스템과 알고리즘에 대한 기본 지식을 배우고 ICT 기술의 활용을 이 룰 수 있도록 교육의 목표를 이루게 된다. ○ 영상처리 프로그래밍의 기본을 이해하고 이를 영상처리 필터에서 주파수 변환에 이루기까지 학습을 기본적으로 시행하게 된다. 이를 기반으로 기본적 로봇에 관련된 영상처리 프로그래밍 방법, 타 영상과의 차이점, 나아가서 패턴인식 기술을 다루게 된다. 본 강 좌를 통하여 로봇 기술 입문을 이루며 나아가서는 영상처리 프로그래밍의 기초를 완성하도록 한다.', '{"상처리","프로그래밍","발전","로봇","ICT","영상처리","과목","지능","가운데","생활","침투","디지털","프로그램","시스템","알고리즘","지식","교육"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('514126', '컴퓨터네트워크', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '박찬영', '본 과목에서는 컴퓨터 네트워크 구조, 원리 및 네트워크 계층 모델에 대해서 학습한다. 특히, 네트워크 계층별 특징, 프로토콜, 동작원 리 등에 대해서 학습한다. 리눅스 시스템에서 다양한 네트워크 툴을 직접 활용하고, 프로그래밍 실습을 통해 네트워크 프로그램을 개 발한다. - 네트워크 계층 모델에 대한 이론 지식 학습 및 이를 바탕으로 네트워크 동작 원리 이해 - 네트워킹 프로토콜에 대한 이론 지식 학습 - 네트워크 소켓 프로그래밍 구현 기술 습득 - 네트워크 진단 도구 사용 기술 습득', '{"네트워크","계층","모델","프로토콜","동작","프로그래밍","지식","습득","기말고사","컴퓨터네트워크","과목","컴퓨터","구조","특징","리눅스","시스템","프로그램"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506314', '운영체제', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '고영웅', '운영체제는 컴퓨터시스템의 가장 중요한 부분으로, 프로그램이 실행되기 위한 메모리 관리, 프로세스 관리, 입출력 관리, 파일시스템 관리, 네트워크 관리, 사용자 인터페이스 제공 등의 주요 기능을 담당한다. 본 교과목은 운영체제를 구성하는 주요 요소들의 구조를 학습하고, 사례 연구(UNIX, Windows, LINUX)를 통해 여러 운영체제의 특징을 비교한다. 또한 운영체제에 대한 이해를 높이기 위해서 리눅스 운영체제 상에서 프로젝트를 수행하여 실무적인 지식을 배운다. 본 교과목을 통하여 운영체제 전반의 기본 지식 및 운영체제의 주요 실습 내용들에 대해서 이해도를 높인다.', '{"운영체제","관리","시스템","입출력","구조","리눅스","지식","컴퓨터","부분","프로그램","실행","메모리","프로세스","파일","네트워크","사용자","인터페이스","제공","기능"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603135', '웹서버구축', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '김은주', '본 수업은 웹 사이트의 전 제작 과정을 이해하고 최신 경향의 모바일과 동적 웹 프로그래밍 기술로 나아가기 위한 고급 과정으로 웹 서버 구축을 위한 웹서버의 설정, 서버 프로그래밍을 위한 JSP 인터페이스의 설계와 구현 과정, 데이터베이스 연동을 통한 통합 웹 응용 프로그램을 설계 및 구현하게 됩니다. JSP는 간단한 스크립트에서 대규모 웹 프로젝트의 개발까지 폭 넓게 이용되는 자바의 서버 기반 웹 프로그래밍 방식으로, JSP를 활 용한 인터페이스 설계 , SQL을 이용한 데이터 베이스 설계, JDBC 관계형 데이베이스의 활용, 게시판 및 자료실 작성 등 전사적인 웹 서버를 구축하는데 좋은 인터페이스 역할을 합니다. ----------[주요 수업 방향]------------------------------------------------------------- 본 수업은 웹 개발자로서의 역량과 프로젝트 개발 경험을 통한 사회와의 협업과 소통을 목적으로 아래의 수행과정을 목표로 진행됩 니다. 1. 웹 시스템의 이해와 활용 2. 웹 클라이언트 및 서버 사이드 개발 언어의 특징과 이해 3. HTML+CSS+JavaScript+Query 웹 개발 프레임워크 활용 및 다양화 설계 4. 아파트 웹 서버 설정 + JSP 인터페이스 설계 + JAVA 비즈니스 모델 설계 + 데이터베이스 설계 5. SQL과 JSP와의 연동 및 웹 MVC 모델을 적용한 응용 소프트웨어 개발 6. 협업과 협동을 키우기 위한 팀원 구성 + 팀원과의 소통 문제 해결 본 과목은 소프트웨어 개발 전 과정을 소프트웨어 공학 원리에 의하여 설계 및 구현하는 과정으로, 각 단계별 기술적 프로세스에 따 라 체계적으로 학습함으로써 웹 개발 역량을 강화하는데 있습니다.', '{"개발","서버","JSP","인터페이스","데이터베이스","프로그래밍","설정","기반","소프트웨어","웹서버","구축","연동","베이스","역량","협업","소통","모델","SQL"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506703', '윈도우프로그래밍', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '이세영', '기본적인 C# 문법과 객체지향 프로그래밍(OOP)을 익힌 후, Windows Forms를 이용해 윈도우 환경에서 실행되는 응용 소프트웨어 개 발 방법을 학습한다. 1) C# 언어가 가지는 고유한 특징 및 .NET 개발환경을 이해할 수 있다. 2) 윈도우 폼을 이용해 GUI를 설계하고 구성현하는 실습을 진행한다. 3) 배운 내용으로 실제 윈도우 애플리케이션을 설계하고 개발하는 능력을 키운다. 1) C# 언어의 기초를 이해하고, 기본 문법 및 객체지향 프로그래밍(OOP)을 활용하여 효율적인 코드 작성이 가능하다. 2) Windows Forms를 이용한 GUI 애플리케이션 개발 능력을 함양한다. 3) 이벤트 기반 프로그래밍을 이해하고, UI 컨트롤(버튼, 텍스트박스, 리스트박스 등)을 활용하여 사용자 친화적인 인터페이스를 설계 하고 구현할 수 있다. 4) 파일 입출력 및 멀티스레드 기법을 이해하고, 실제 프로그램에 적용할 수 있다. 5) 실전 프로젝트를 통해 실제 애플리케이션을 설계하고 구현하는 경험을 제공하여 문제 해결 능력과 팀워크를 배양한다.', '{"객체지향","프로그래밍","윈도우","개발","실제","애플리케이션","C#","문법","환경","언어","이벤트","박스","입출력","OOP","Windows","Forms","GUI","실행","소프트웨어"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('515103', '정보보호론', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '김한수', '본 강의는 정보보호 및 정보보안의 핵심 이론과 기초를 다지며, 최신 트렌드와 실제 사례를 통해 실무 역량을 강화하는 데 중점을 둔 다. 정보보호의 기본 원칙, 암호학, 네트워크 보안, 시스템 보안 등 주요 주제를 다루며, 자격증(정보보안기사 등) 및 공무원/공공기관 시험 대비에 필요한 내용을 포함한다. 최신 보안 위협과 대응 방안을 학습하며, 윤리적 해커의 관점에서 문제를 분석하는 능력을 기 른다. 또한, 공공기관 및 기업의 요구 사항에 맞춘 실무 중심의 학습을 통해 정보보호 전문가로 성장할 수 있도록 돕는다. 최종적으로, 이론과 실습을 균형 있게 병행하여 정보보호 분야의 핵심 전문가로서의 기본기를 다진다. 이 교과목은 정보보호 분야의 기본 이론과 실무를 아우르는 종합적 역량을 배양하는 데 목표를 둔다. 학습자는 정보보호의 핵심 원리 와 최신 기술을 이해하고, 이를 문제 해결 및 실무 환경에 적용할 수 있는 기술적 역량을 갖춘다. 최신 보안 위협 및 동향을 분석하고 효과적인 대응 방안을 수립할 수 있는 분석 및 전략 수립 역량을 강화한다. 또한, 자격증 및 공무원/공공기관 시험 준비를 통해 학문 적·직업적 역량을 함께 기른다. 윤리적 사고와 협업 능력을 바탕으로 정보보호 전문가로서 요구되는 책임감과 실천적 역량을 배양한 다.', '{"정보보호","역량","정보보안","실무","보안","공공기관","전문가","자격증","공무원","시험","위협","대응","방안","윤리","요구","배양","수립","네트워크보안","시스템보안"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506419', '컴퓨터그래픽스', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '김선정', '3차원 컴퓨터 그래픽스의 원리에 대해 공부하고, 이에 대해 프로그래밍 실습을 한다. 3차원 객체를 생성하는 모델링 기술부터, 객체에 입체감을 위해 채색과 명암을 입히는 렌더링 기술을 배우고, 최종적으로 프로그래밍을 이용하여 컴퓨터 그래픽스 이론들을 구현하고 3차원 장면을 제작한다. 본 교과목은 (주)더픽트와 공동운영하는 산학연계교과목으로, 우수 기말프로젝트 출품자는 (주)더픽트에 견학가서 발표할 예정입니 다. 본 교과목에서는 3차원 장면이 어떠한 파이프라인을 거쳐서 2차원 화면에 출력되는지 그 과정을 공부한다. 또한 3차원 장면 생성과 출력을 도와주는 그래픽 라이브러리 이용한 프로그래밍을 공부하며, 기말프로젝트로 자신만의 3차원 장면을 제작하여 발표한다.', '{"차원","장면","공부","프로그래밍","컴퓨터","그래픽스","객체","제작","더픽트","발표","출력","컴퓨터그래픽스","모델링","체감","채색","명암","렌더링","최종"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506319', '프로그래밍어론', '정보과학대학', '정보과학대학', 3, 3, '공통전선', '김진환', '본 교과목의 이론에서는 프로그래밍 언어의 역사적 발전과정, 설계방법, 프로그래밍 언어의 속성을 강의 한다. 또한, 실습시간에는 C언어를 기반으로 프로그램 언어의 속성을 확인하고 다양한 언어의 구조를 이해한다. 이 교과목은 프로그래밍 언어가 갖고 있는 속성을 세부적으로 분석 및 실제 사용 예를 강의하고, 이를 실습을 통하여 숙지함으로써 보다 효과적인 프로그래밍 작성 방법을 익힌다.', '{"언어","프로그래밍","속성","설명","시간","프로그램","작성","역사","발전","기반","확인","구조","실제","숙지","효과","학기","동안","개요"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506836', 'HCI', '정보과학대학', '정보과학대학', 4, 3, '공통전선', '김선정', '전통적으로 Human Computer Interaction은 사람들이 편리하게 사용할 수 있는 컴퓨터 시스템을 개발하는 원리 및 방법을 연구하는 학문이었다. 그러나 현대에는 다양한 디지털 시스템과 사람들 사이의 사용자 경험을 중점적으로 연구한다. 본 교과목에서는 "디지털 제품이나 서비스를 이용해 작업을 수행하거나 문제를 해결하는 과정에서 사용자들에게 최적의 경험"을 제 공할 수 있도록 기본적인 원리와 사용자 경험 분석, 인터페이스 디자인 등에 대한 내용을 학습한다. HCI와 사용자 경험에 대해 이해하고, HCI의 궁극적인 목적인 "최적의 사용자 경험"을 제공하기 위한 원리와 방법에 대해 학습한다.', '{"사용자","경험","사람","시스템","디지털","최적","HCI","전통","컴퓨터","개발","학문","사이","중점","제품","서비스","작업","수행"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603144', '강화학습', '정보과학대학', '정보과학대학', 4, 3, '공통전선', '최종환', '- 본 과목은 기초적인 파이썬 프로그래밍 및 기계학습에 대한 이해를 갖춘 학생들을 대상으로 하며, 단순한 모델 학습을 넘어 스스로 환경과 상호작용하며 최적의 해답을 찾아가는 강화학습(Reinforcement Learning)의 핵심 원리와 알고리즘 체계를 심도 있게 학습하 는 것을 목표함 - 에이전트(Agent)가 환경(Environment) 내에서 행동(Action)하고 보상(Reward)을 받는 상호작용 과정을 마르코프 결정 과정(MDP)의 관점에서 이해하고, 복잡한 벨만 방정식(Bellman Equation)의 수학적 구조를 동적 계획법(Dynamic Programming) 및 반복적 연산을 수행하는 파이썬 코드로 치환하여 직관적으로 습득함 - 전통적인 가치 기반(Value-based) 학습을 넘어, 현대 강화학습의 주류인 정책 경사(Policy Gradient) 계열의 REINFORCE 알고리즘부 터 시작하여, 안정적인 학습을 보장하는 Actor-Critic 구조 및 PPO(Proximal Policy Optimization) 등 최신 알고리즘의 내부 동작 매커 니즘을 분석하고 구현함 - 이론 학습에 머물지 않고 PyTorch 기반의 실무 프로그래밍 실습을 병행하며, 교수자의 세밀한 코드 리뷰(Code Review)를 통해 단순 한 라이브러리 활용 능력을 넘어 알고리즘의 기저 로직을 최적화된 소스코드로 설계할 수 있는 역량을 배양함 본 교과목은 수강생들이 강화학습(Reinforcement Learning)의 핵심 원리와 알고리즘을 심도 있게 이해하고, 이를 실무에 적용할 수 있는 역량을 배양하는 것을 목표로 한다. 구체적으로 (1) 마르코프 결정 과정(MDP)과 벨만 방정식의 수학적 구조를 이해하고, (2) 가치 기반 학습(Value-based)부터 정책 경사(Policy Gradient), Actor-Critic, PPO 등 최신 알고리즘의 동작 원리를 분석하며, (3) PyTorch 기반 프로그래밍 실습을 통해 알고리즘을 직접 구현하고 최적화할 수 있는 능력을 기른다.', '{"환경","강화","알고리즘","파이썬","프로그래밍","상호작용","목표","에이전트","행동","구조","코드","기반","라이브러리","Policy","머신러닝","강화학습","과목","기계학습","대상","모델"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603130', '시스템보안', '정보과학대학', '정보과학대학', 4, 3, '공통전선', '문서연', '본 수업은 디지털 컴퓨팅 환경의 핵심인 운영체제(OS)와 단말/서버 시스템의 보안 메커니즘을 심도 있게 다룹니다. 전반기에는 국내 정보보안기사의 "시스템 보안 Part"를 바탕으로 실질적으로 도움이 되는 지식을 쌓고, 후반기에는 국내외 침해사고 사례를 기술적으 로 분석하여 공격 기법과 방어 전략을 학습합니다. 마지막으로 최근 인공지능 기술 보편화에 따른 정보보안 분야의 이슈와 솔루션도 다룹니다. 이를 통해 학생들에게 의미있는 이론적 지식 습득과 실무 기술적용 및 인공지능 시대의 정보보안 역량을 가질 수 있도록 합니다. 1) 시스템 보안 아키텍처 이해: Windows, Linux 및 모바일 OS의 보안 구조를 이해하고 시스템 요새화(Hardening) 기술을 습득한다. 2) 취약점 분석 및 탐지 능력: 메모리 오염 공격 및 최신 APT 공격의 원리를 파악하고, 로그 분석을 통해 침입 징후를 탐지하는 역량 을 배양한다. 3) 실무적 문제 해결 (Case-based Learning): 국내 주요 침해사고 사례를 분석하여 사고의 근본 원인을 파악하고 재발 방지 대책을 수 립하는 실전적 사고력을 기른다. 4) 국가 기술 자격 취득: 정보보안기사 시험의 시스템 보안 과목을 완벽히 소화하여 졸업 후 전문 자격을 갖춘 인재로 성장한다.', '{"보안","정보보안","시스템","공격","운영체제","국내","기사","지식","침해사고","사례","인공","지능","습득","실무","역량","탐지","파악","로그","자격","OS"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('603132', '통신네트워크시스템', '정보과학대학', '정보과학대학', 4, 3, '공통전선', '이용업', '4차 산업 혁명 시대에 스마트폰의 이동통신 기술, 와이파이, 블루투스 등의 무선통신, 컴퓨터 동작에 대한 기초 동작 원리 이해가 당 연히 필요하다. 이 강의는 선행 지식이 없는 일반 전공자, IT 전공자를 대상으로 한다. 이해를 높이기 위해 일반 통신 기초 개념을 제공하는 기초 강의를 제공한다. 심화 강의에서는 와이파이/블루투스 무선통신 네트워크 시스템의 기초 개념, 스마트폰인 실외 이 동통신 네트워크 시스템 기초 원리를 강의한다. 인공지능 로봇, 6G 통신이 실현될 4차 산업 혁명 시대에 적응하기 위해, 당연히 스마트폰, 와이파이, 블루투스와 같은 이동/무선통신 의 기초 지식, 원리 이해 등 이 필요하다. 이 강의는 스마트폰, 와이파이, 블루투스의 이동/무선 통신 네트워크 시스템 기술의 기초 지 식을 선수학습 없이, 반드시 알아야 하는 주요 핵심 개념만을 다루고 쉽게 이해시키는 IT 전공 입문 교육이다.', '{"스마트폰","와이파이","블루투스","통신","시스템","무선통신","네트워크","산업","혁명","시대","동작","지식","전공자","제공","이동","다중접속","IT","인공지능","이동통신","컴퓨터"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204506', '미시경제학I', '사회과학대학', '사회과학대학', 0, 3, '전필', '유한욱', '- 본 과목은 경제학 전공필수 과목으로서 미시경제학의 기본 개념 및 분석 이론을 소개하고 응용 지식을 전달하는 것을 주요 목적으 로 함. - 강의의 주요 내용은 경제학 기초, 소비자 이론, 생산자 이론, 완전경쟁시장 및 독점시장으로 구성할 계획 경제학 전공 학생들에게 미시경제학 분야에 대한 흥미를 유발시키고 미시경제학의 주요 방법론을 소개', '{"연습문제","소비자선택","생산자이론","수요와","공급","공급곡선","수요공급모형의","독점과","가격전략","경제학","응용","또는","미시경제학의","수요곡선","시장균형과","균형의","변화","탄력성","한계","선호와"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('005073', '기초생명과학및실험', '자연과학대학', '자연과학대학', 0, 3, '전선', '이원용', '생명과학의 다양한 분야에 대한 기초 개념을 이해하고 지식을 습득하여 상급 학년에서 만나게 될 전문 분야의 공부를 위한 기초를 쌓 는 강의입니다. 기본적인 생화학으로부터 세포의 구조와 대사, 생물의 유전 등 현대 생명과학을 공부하는 데 가장 기본이 되는 개념 을 공부하여 이해하고, 이 지식을 실험 실습을 통해 구체적으로 체득하면서 동시에 현대 생명과학 연구의 기초적인 방법론을 배워 학 생들이 초보적인 실험 수행 능력을 얻는 것을 목표로 합니다. 이 과목의 목표는 첫째, 학생들이 현대 생명과학이 쌓아올린 지식의 기초를 습득하여 자연에서 나타나는 다양한 생명 현상을 이해하 고 설명할 수 있는 역량을 갖추게 하는 것입니다. 둘째, 강의에서 배운 지식을 실습을 통해 구체적으로 체득하고, 동시에 현대 생명과 학 연구에 필요한 가장 기초적인 실험 기법을 배워 초보적인 실험 수행 역량을 갖도록 합니다.', '{"이해한다","실험","과정과","중요성을","세포의","구조와","구성하는","기능을","유전자","생명과학의","개념을","지식을","오리엔테이션","이해하고","습득하여","기초를","가장","실습을","구체적으로","동시에"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207201', '헌법II', '사회과학대학', '사회과학대학', 0, 3, '전선', '홍일선', '헌법총론에서 다룬 헌법의 기본이론을 바탕으로, 우리헌법의 기본권을 이해한다. 기본권론은 다음과 같은 두 부분으로 구성된다. 첫 째, 기본권일반이론에서는 기본권의 의의, 성격, 주체, 효력 등의 문제를 다룬다. 둘째, 개별기본권론에서는 인간의 존엄과 가치 및 행 복추구권, 평등권, 자유권적 기본권, 정치적 기본권, 청구권적 기본권, 사회적 기본권, 국민의 기본의무 등을 다룬다. 기본권의 의미와 내용을 이해한다.', '{"기본권의","자유","자유의","기본권","제한","신체의","사생활의","내용과","자유와","자유권","언론출판의","청구권적","기본권은","비밀과","거주이전의","통신의","제한문제","효력","인간의","존엄과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207214', '형법총론II', '사회과학대학', '사회과학대학', 0, 3, '전선', '이건호', '형법총론 1에 이어서 형법을 해석하기 위한 총칙규정의 해석 도그마틱을 강의한다. 주로 책임론과 범죄행위의 변형된 특수형태들인 미수론, 공범론, 과실범, 부작위범 및 형벌론과 죄수론에 대해서 강의한다. 책임론은 범죄성립요건의 제3단계로서 주로 행위자에 대한 비난가능성을 판단하는 단계이다. 범죄행위는 예비 음모와 실행의 착수를 거쳐 범죄가 완결되어 종결되는데, 완결되지 못한 범죄행 위의 해석론을 다루는 것이 미수론이다. 공범론은 범죄행위에 2인 이상의 다수자가 참가한 형태에 대해서 다루게 된다. 과실범과 부 작위범론은 고의작위범에 대응되는 범죄행위의 형태들을 다룬다.. 캠퍼스 생활을 통해서 사회진출의 기반 마련', '{"책임의","형법총론교과서","형법전","행위","위법성의","원인에","자유로운","파악한다","책임고의와","책임능력","행위와","동시존재","있어서","인식","착오","형법","요건과","효과","강요된","비난가능성을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207222', '물권법', '사회과학대학', '사회과학대학', 0, 3, '전선', '허명국', '물권법은 민법 제2편 물권을 주된 탐구 대상으로 한다. 민법 제2편 물권(제185조-제372조)에는 총칙, 점유권, 소유권, 지상권, 지역권, 전세권, 유치권, 질권, 저당권의 9 개의 장, 188개 조문으로 구성되어 있다. 총칙은 주로 물권적 법률관계의 통칙적 규정으로 구성되 어 있고, 점유권은 물권 질서의 유지를 위한 물건의 사실적 지배를 하나의 물권으로 인정하는 제도이며, 소유권은 물건의 전면적 지 배를 목적으로 하나는 가장 대표적 물권이다. 그밖에 지상권, 지역권, 전세권은 모두 타인의 부동산을 일정한 범위에서 사용수익할 것 으로 목적으로 하는 용익물권이고, 유치권, 질권, 저당권은 물권을 채권의 담보로 확보하는 담보물권이다. 본강좌에서는 물권 내용과 공시 그리고 이들 물권의 득실변경을 체계적으로 이해하는 것을 목표로 한다. 물권법의 기본이론 및 점유권과 소유권에 대한 이해를 목표로 함', '{"보충일","물권의","효력","취득","총설","소멸","물권","변동","의한","소유권의","저당권의","지상권","지역권","유치권","질권","법률행위에","물권변동","동산물권변동","권리자로부터","무권리자로부터"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('904605', '전공탐색프로젝트', '자유전공학부', '자유전공학부', 0, 3, '전필', '김선정', '본 수업은 생성형 AI을 매개로 지역 사회가 직면한 현실 문제를 탐구하고 AI 활용을 통해 사회적, 문화적 가치 창출 방안을 모색하는 PBL 교과목이다. 자유전공학부 학생들은 인문사회, 의료바이오, AI 융합클러스터의 학문 범주 아래 ‘AI는 지역의 문제를 어떻게 해결할 수 있을까?’라 는 질문을 중심으로 데이터 분석, 리빙랩, 문화콘텐츠 개발 등 다학제적 프로젝트를 수행한다. 이 과목을 통해 수강생은 전공을 선택하기 전 단계에서 AI의 사회적 응용 가능성과 한계를 직접 체험함으로써 향후 자신의 학문적 방 향에 대해 긍정적 탐색 방향성을 얻을 것이다. - 생성형 AI의 기술적 원리와 응용 구조를 이해하고, 이를 사회문제 해결에 적용한다. - 지역사회 문제를 비판적으로 분석하고, AI 기반 해결 가능성을 탐색한다. - 인문사회학적 통찰, 데이터 분석, 디자인 사고를 결합한 융합적 문제 해결 프로젝트를 수행한다. - 지역 리빙랩과 연계한 실천적 학습을 통해 윤리적 감수성과 공동체 의식을 기른다.', '{"지역","프로젝트","피드백","제작","데이터","사례","도구","리포트","초안","인터뷰","설계","아이디어","시각화","콘텐츠","팀별","완성","기획","윤리적","생성형","사회적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507321', '인간과미생물', '자연과학대학', '자연과학대학', 0, 3, '전선', '박종국', '생명과학 계열 학과를 졸업하고 장차 의료, 보건, 제약관련 분야에 진출하려는 학생을 위한 학과목으로 질병과 관련된 미생물의 병원 성, 질병을 일으키는 작용, 감염을 예방 또는 치료하는 백신과 화학요법에 대해 관하여 학습한다. 생명이란 무엇인가에 대해 생명과학분야의 과거, 현재, 미래의 관점에서 살펴보며, 다양한 학문분야에서 생명을 바라보는 다양한 관 점들을 살펴봄으로써 다각적 사고능력과 분석능력을 함양한다.', '{"필요시","부교재","이용","중간고사","대해","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('904606', '전공탐색프로젝트', '자유전공학부', '자유전공학부', 0, 3, '전필', '김명준', '본 교과목은 의료바이오, 인문사회, AI융합 분야를 통합한 융합형 PBL 수업으로, 디지털 헬스케어 기술이 인간의 생명, 건강, 존엄성, 지역 사회 복지에 어떤 영향을 미치는지를 다각도로 탐구한다. 학생들은 공공의료 데이터, AI기반 건강관리 기술, 생명윤리적 사고를 결합하여 ‘기술이 인간과 지역 사회에 어떻게 기여할 수 있는가?’라는 질문을 중심으로 학문 간 협력 프로젝트를 수행한다. 특히 인제 군을 포함한 강원 지역은 건강지표(예시: 고위험음주율, 비만율, 걷기실천율 등)가 전국에서 가장 열악한 지역적 특성을 지니고 있어 서 지역사회에서 건강증진을 위한 건강돌봄(Health Care)의 사회생태적 근거기반 프로그램을 설계하고 개발하는 내용을 포함한다. * 팀 티칭 수업: 이강 교수, 김명준 교수 가. 디지털 헬스케어 기술 이해: AI 기반 진단, 원격의료, 건강데이터 활용 원리를 학습한다. - 지역사회 건강증진을 위한 건강돌봄(Health Care)의 사회생태적 근거기반 프로그램을 설계하고 개발 방법을 학습한다. 나. 생명윤리 및 기술윤리 적용: 의료데이터의 활용과 인간 존엄성의 균형을 탐구한다. 다. 지역사회 문제해결 실습: 강원 지역 건강 불평등·고령화 문제에 대한 실질적 해결안을 제시한다. 라. 융합적 사고와 실무 기획 능력 향상: 정책·서비스·콘텐츠 기획 역량을 기른다. 마. 세부 학습 목표 - 지식: 디지털 헬스케어의 개념, 주요 기술(AI 진단·웨어러블·원격의료 등)의 원리 이해 - 기술: 공공 건강 데이터를 수집·분석하고, 시민에게 이해하기 쉬운 데이터 시각화 콘텐츠로 제작 - 태도: 생명과 기술의 경계에서 인간 존엄성과 사회적 책임 인식', '{"데이터","서비스","헬스케어","디지털","디자인","기반","정책","기술","사례","작성","윤리","리포트","초안","건강","지역","건강돌봄","사회생태적","근거기반","인간","워크숍"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207223', '채권총론이다', '사회과학대학', '사회과학대학', 0, 3, '전선', '신동현', '재산법의 중요한 한 부분을 담당하고 있는 채권법 중 채권 일반에 관한 통칙을 대상으로 하는 것이 채권총론이다. 본 강의에서는 주 로 채권의 변경과 소멸 등과 관련되는 법률관계를 다루게 될 것이며, 구체적으로는 채권의 목적과 효력, 다수당사자의 채권관계 및 채권양도, 채무인수, 채권의 소멸 등에 관하여 공부함으로써 채권법 전반에 대하여 체계적인 이해를 돕는 것을 목표로 한다. 채권의 목적과 효력, 다수당사자의 채권관계 및 채권양도, 채무인수, 채권의 소멸 등에 관하여 공부함으로써 채권법 전반에 대하여 체 계적인 이해를 돕는 것을 목표로 한다.', '{"교재","채권의","채권양도","총설","소멸","효력","다수당사자의","채권관계","채무인수","목적","채권자지체","보증채무","채권법","개관","목적과","등에","관하여","공부함으로써","전반에","대하여"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('904607', '전공탐색프로젝트', '자유전공학부', '자유전공학부', 0, 3, '전필', '전진희', '본 교과목은 관광을 매개체로 문화콘텐츠, 지역 사회, 청년 정책의 융합을 주제로 한 지역 실천형 PBL 수업이다. 수강생은 강원 정선을 중심으로 문화콘텐츠가 관광산업을 통하여 지역 청년의 삶과 정주를 어떻게 연결될 수 있는가를 탐구한다. 이를 위해 지역의 역사·문화·공간·청년 이슈를 통합적으로 분석하고 관광을 위한 디지털 스토리맵, 로컬 다큐멘터리 시나리오 제작 등 의 창의적 산출물을 제작하고 관광산업 육성을 통하여 청년들을 위한 인프라 발전과 정책실행에 기여할 수 있는 방법을 모색한다. 본 교과목은 지역 리빙랩(G-Lab) 활동을 통해 현장 기반의 사회문제 해결형 학습을 수행한다. 가. 로컬 문화콘텐츠 이해와 활용: 지역 정체성 정립, 관광, 청년정주의 관계를 분석한다. 나. 정주(定住) 문제 탐색: 청년이 머물고 싶은 지역을 만들기 위한 문화적·사회적 조건을 탐구한다. 다. 콘텐츠 기획 및 제작: 관광을 위한 디지털 콘텐츠 (디지털 스토리맵, 다큐 시나리오)와 청년정주 정책 제안서 등 창의적 산출물을 제작한다. 라. 지역 실천 및 정책 연계: G_Lab과 연계하여 실제 현장 기반의 제안을 수행한다.', '{"지역","청년정책","콘텐츠","정책","관광과","경제","관광이","지역경제재생에","미치는","관광트랜드","도출","아이디어","설계","피드백","관광을","지역의","디지털","이해와","정주","제안서"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207229', '회사법1', '사회과학대학', '사회과학대학', 0, 3, '전선', '조지현', '자본주의의 핵심역할을 하는 회사와 관련된 법이론을 공부하는 과목이다. 회사와 관련된 법률은 상법 제3편에 규정되어 있는데, 이를 중심으로 상법의 핵심부분인 회사법에 관한 법규정 및 법이론을 공부하고 사례풀이를 통해 이를 복습함으로써 기업 취업을 원하는 학생들에게 필요한 법지식을 갖추도록 하는 것을 목표로 한다. 회사에 취업을 하거나 회사법 관련 자격증 취득을 목표로 하는 학생에게 필요한 법지식을 습득하게 하는 것을 목표로 함.', '{"대해","알아본다","회사의","주식회사의","알아보고","주식의","하는","관련된","제한되는","경우를","여러","기준에","따른","종류","주식회사","따라","주주들이","살펴본다","중요한","목표로"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101102', '국어학개론', '인문대학', '인문대학', 0, 3, '전선', '이병기', '국어학개론은 국어학 전공 분야 강의의 기본적인 내용을 종합하여 공부하는 강좌이다. 한국어의 문자, 음운론, 문법론, 의미론, 역사 등 국어학 각 영영별 기본 개념과 기본적인 사항을 이해함으로써 한국어에 대한 기본적 인 이해를 하고 이후 다른 국어학 강좌를 수강할 수 있는 기본 소양을 갖출 수 있다. 나아가 일상에 대한 관심을 국어학적으로 확대할 수 있는 소양을 갖추도록 한다. 한국어의 문자, 음운론, 문법론, 의미론, 역사 등 국어학 각 영영별 기본 개념과 기본적인 사항을 이해함으로써 한국어에 대한 기본적 인 이해를 한다. 나아가 이 강의를 통해 이후 다른 국어학 강좌를 수강할 수 있는 기본 소양을 갖춘다.', '{"한국어의","이해한다","언어","요약","한국의","대하여","설명","한국어","국어학","단어의","선어말어미","기본적인","문자","역사","사항을","한글","음운","체계","구조","주차"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207311', '사회보장법', '사회과학대학', '사회과학대학', 0, 3, '전선', '김경태', '사회보장법은 넓은 의미에서는 ‘모든 국민의 물질적·정신적·사회적 기본 욕구를 해결함으로써 인간다운 생활을 영위케 하는 공사(公 私)의 제반 사회적 서비스와 관련된 법령’을 의미하며, 좁은 의미에서는 ‘신체적·정신적·사회적인 불리한 여건으로 인해 정상적인 일상 생활을 영위하기 힘든 국민에게 정상적인 생활을 위해서 필요한 급여를 제공하는 것’을 내용으로 하는 법이다. 자본주의가 발달되어 감에 따라 우리의 일상생활에서 사회보장법이 가지는 중요성은 더해갈 수밖에 없으며 현재 대부분의 국가에서 는 사회보장제도가 가장 핵심적인 정부 정책의 하나로 자리매김 하고 있으며, 한편으로는 가까운 장래에 저출산·고령화의 문제가 본 격적으로 영향을 미칠 것으로 예상되는 가운데, 우리나라의 사회보장제도가 해결해야 할 문제점들 또한 결코 작지 않을 것으로 생각 된다. 현실적인 측면에서 볼 때, 우리 학생들은 졸업과 동시에 자동적으로 소위 ‘4대 보험’이라 불리우는 현행 사회보험제도의 적용을 받게 되며, 그 문제점들의 영향또한 직·간접적으로 받게 될 것으로 예상된다. 한편 우리나라가 직면한 ‘고령화’의 문제는 현재 및 미래의 세 대를 포함하여 우리 국민 모두에게 큰 영향을 미칠 것으로 예상되는 가운데, ‘노령’을 보장의 대상 중 하나로 하고 있는 사회보장법의 내용 및 역할을 전면적으로 재설정해야 한다는 주장도 현재 강하게 제기되고 있다. 이와 같은 문제의식 하에서 본 강의는 사회보장제도의 기반이 되는 사회보장법의 개념과 생성과정, 체계 등을 헌법적 기초, 특히 사 회적 기본권(생존권)과 관련하여 총론적으로 살펴본 후, 개별 사회보장제도의 내용 및 문제점들을 사회보험법을 중심으로 살펴보는 것을 강의의 내용으로 한다. 특히 본 강의는 이론적인 측면에서 벗어나 영화 등의 동영상 자료 등 다양한 미디어를 최대한 활용하여 수업을 진행하도록 한다. 2. 교과 목표 ■ 교과목표 본 강의는 수강생들이 우리의 현실 생활과 밀접한 관련을 가지는 사회보장제도, 특히 사회보험제도들이 어떠한 법령 아래에서 수행 되어지는가를 확인하고, 그 원리를 이해함으로써 현행 사회보장(사회보험)제도의 내용과 쟁점을 법리적으로 해석하고 적용할 수 있 는 능력을 가지게 하는 것을 그 목표로 한다. 더불어 고령화 사회로의 진입에 따라 발생하는 다양한 사회적 문제의 본질을 올바르게 이해하고, 합리적인 대안을 제시할 수 있도록 하는 데에 부차적인 목표를 둔다.. 수업의 방법과 관련해서는 단순히 이론적인 강의에서 벗어나 영화 등 동영상 자료, 언론 보도 등 다양한 미디어를 활용하여 강의 내 용에 대한 이해도를 높이도록 한다. 수업의 방법과 관련해서는 단순히 이론적인 강의에서 벗어나 영화 등 동영상 자료, 언론 보도 등 다양한 미디어를 활용하여 강의 내 용에 대한 이해도를 높이도록 한다.', '{"있다","설명할","개념을","국민건강보험법","사회보장법","설명한다","있는","ㆍ강의","ㆍ김경태","사회적","중심으로","현행","내용을","특징을","법적","국민연금법","특히","살펴본다","하는","설명하고"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207329', '형사소송법I', '사회과학대학', '사회과학대학', 0, 3, '전선', '이건호', '형사소송법은 국가의 형벌권 행사를 위해서 범죄피의자의 범죄혐의를 수사하고 수사과정을 통해서 수집된 증거에 기반하여 재판절 차를 통해서 유무죄 여부를 확정하는 소송의 절차를 정하고 있는 규범이다. 본 강의는 우선 형사송송절차의 선행단계인 수사절차와 검사의 기소절차에 대해서 강의한다. 형사소송절차가 형사피의자와 피고인을 그 대상으로 삼는 만큼 그들의 기본적 권리를 보장함과 동시에 범죄피해자의 침해된 권리를 확인하는 과정이 법치주의의 원칙에 따라서 이류어질 것이 요구된다. 또한 그만큼 형사소송법 규정은 기본권 보장의 측면과 실치적 진실발견이라는 두 가지 목적을 추구하게 된다. 특히 수사절차는 범죄피의자에 대해서 법률상 가능한 강제적 수단을 동원하여 범죄혐의를 밝히는 절차이므로 피의자의 기본권이 부당하게 침해되지 않도록 해석하고 적용되어야 한다. 또한 수사절차의 적법성 여부는 이후 형사소송단계에서 그 수사절차에서 수집된 증거가 법관에 의해서 채택될 수 있는 자격을 갖춘 것인가의 증거능력의 문제와도 밀접하게 관련되어 있음에 주의하여야 한다. 이런 점들을 계속적으로 기억하면서 강의를 수강하 면 형사소송법 1 강의가 추구하는 강의목표를 달성하게 될 것이다. 지식: 형법총론과 형법각론을 통해서 배운 범죄성립에 대한 판단지식을 기초로 하여 수사기관이나 법원이 범죄의 성립여부를 어떻 게 판단하고 증거를 통해서 유무죄를 판정하는 절차를 배우게 된다. 피의자와 피고인의 기본권과 권리를 절차규정을 통해서 보장하 게 된다는 점을 배우며 국가에 의한 시민의 권리보장이 형사소송절차를 통해 구체적으로 어떻게 이루어지는가를 배우게 된다. 기술: 형사소송절차를 통해서 국가에 의한 권리제한에 대응하는 법규정들을 알게 되며 민주적 시민이 보장받게 되는 기본권의 구체 적 실현상황을 알게 된다. 또한 범죄행위자인 피의자의 인신을 어떤 권한으로 확보하며 어떤 절차로 범죄증거들을 수집하고 재판절 차를 통해서 유무죄가 가려지는 소송절차의 실질을 알게 된다. 태도: 형사소송법을 수강한 후에는 수사기관이 어떤 법적 권한에 의거하여 피의자의 인신을 확보하고 증거를 수집하는가에 대한 구 체적 지식을 얻게 된다. 검찰이 범죄수사에 대해 갖는 권한들과 판단과정들을 파악하며 증거수집을 통해서 범죄자의유죄를 입증하는 과정에 대한 기초지식을 갖게 된다. 구체적인 소송절차상 법원이 갖는 권한과 검사와 피고인의 법정에서의 변론을 통해서 증거입증 이 이루어지고 이에 대해 법원이 유무죄를 판단하는 과정에 대한 기초지식을 습득하게 된다.', '{"형사소송법","교과서","법전","피의자의","권리","공소제기의","수사상","구속영장의","피고인의","원칙","수사의","통해서","피의자와","절차","된다","검사","지위","피의자","강제수사의","체포"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207422', '개별적근로관계법', '사회과학대학', '사회과학대학', 0, 3, '전선', '정정국', '노동법은 자본주의 체제 아래 종속노동관계에 있는 근로자의 인간다운 생활을 보장하기 위한 법규범의 총체입니다. 현대사회에서 대부분의 국민은 노동력을 제공해 임금을 얻거나, 타인의 노동력을 활용해 재화를 생산하고 이를 판매하여 생활을 영 위합니다. 그 과정에서 노동법은 근로자의 입장에서는 자신의 권리를 보호하는 제도로, 사용자의 입장에서는 근로자를 사용함에 있어 서 원칙적 규제로 기능하게 됩니다. 결국 노동법은 우리 모두에게 반드시 필요한 법이며, 노동법에 대한 올바른 이해는 원활한 사회 생활을 위한 필수 소양입니다. 노동법은 크게 ‘개별적 근로관계’와 ‘집단적 노사관계’로 구분됩니다. 전자는 헌법상 근로기본권에 근거하여 사용자와 근로자 개인의 법률관계를 규율하며, 후자는 노동3권을 바탕으로 사용자(단체)와 노동조합 간의 관계를 다룹니다. 본 강의는 국가가 설정한 최저 근로기준을 통해 근로자를 보호하는 ‘개별적 근로관계법’에 초점을 맞춥니다. 특히 핵심 법령인 「근로 기준법」의 주요 법리와 판례 동향을 우리 사회의 노동 현실과 연계하여 심도 있게 고찰합니다. 현대 사회에서 ‘노동’은 생존을 위한 필수 활동인 동시에, 자아를 실현하는 인격적 가치의 핵심입니다. 따라서 이에 대한 법적 보호의 필요성은 아무리 강조해도 지나치지 않습니다. 이제 노동법은 자본주의 사회를 살아가는 시민이라면 누구나 갖추어야 할 필수적인 ‘ 생활 지식’이자 ‘기초 상식’입니다. 본 강의는 근대 시민사회의 구조적 모순을 극복하며 발전해 온 노동법의 이념과 체계를 폭넓게 학습합니다. 이를 통해 학생들이 졸업 후 마주할 근로관계에서 스스로의 권리를 당당히 확인하고, 나아가 우리 사회의 다양한 노동 현안을 통찰력 있게 바라보는 안목을 갖추도록 돕는 것에 목표를 둡니다.', '{"내용을","노동","있게","핵심","노동관계법령의","체계와","깊이","이해하고","실제","근로현장에서","발생하는","복합적인","사안을","법리적으로","분석하여","합리적인","해결책을","도출한다","한림대학교","배부하는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101312', '국어음운론', '인문대학', '인문대학', 0, 3, '전선', '신서인', '이 강의는 국어음운론의 기본개념을 익히고, 국어의 음운 체계와 음운 현상에 대한 이해를 바탕으로, 국어의 음운현상을 관찰하고 체 계적으로 설명할 수 있는 능력을 배양하는 것을 목표로 한다. 기본적으로 음운과 변이음의 개념을 익히고, 국어의 자음 체계 및 모음 체계와 음절 구조를 이해하고, 대치, 탈락, 첨가, 축약, 도치 등의 음운 현상을 이해한다. 이를 바탕으로 형태소의 교체와 기저형의 설 정에 대한 이해로 확장한다. 국어음운론의 기본 개념을 이해한다. 국어의 음운 체계와 음운 현상을 이해한다. 국어의 음운 현상을 관찰하고 체계적으로 설명할 수 있다.', '{"이해한다","쪽지시험","음운","음운론적","체계","변별적","대치","현상을","제약","개념을","현상","모음","음절","변이음","자질의","음절의","국어의","체계와","음운과","변이음의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207431', '헌법연습', '사회과학대학', '사회과학대학', 0, 2, '전선', '김현아', '국가의 최고 규범인 헌법의 기본이론과 기본권의 내용을 중심으로 헌법 규범이 구체적인 사회 현실 속에서 어떻게 적용·실현되는지 를 헌법재판소 판레 중심으로 탐구한다. 특히, 헌법 제8장에 등장하는 지방자치의 헌법적 의미와 구조를 살펴보고, 지방자치의 헌법적 보장과 한계를 둘러싼 주요 판례 및 실 제 사례를 분석함으로써 중앙권력과 지방자치단체 간의 권한 배분, 주민자치와 민주주의의 실질적 구현 문제를 검토한다. 헌법과 관련한 판례 및 사례를 이해한다.', '{"발표문","판례","발표내용","헌법의","헌법","개별기본권에","평등권에","평등권","중심으로","지방자치의","헌법적","사례를","이해한다","일반론","개념과","적용범위","교과서","기본원리에","관한","기본원리"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101314', '국어의미론', '인문대학', '인문대학', 0, 3, '전선', '신서인', '이 수업에서는 의미의 정의 및 유형을 이해하고, 의미론의 하위 분야인 어휘의미론, 문장의미론, 화용론의 연구 대상이 무엇인지 이해 한다. 어휘의미론에서는 의미 분절, 의미 구분, 의미 관계, 의미의 확장, 의미 변화 등에 대해 다루고, 문장의미론에서는 의미 논리, 지 시와 양화, 구문과 의미역, 시제/상/양태 등 문장 의미를 구성하는 요소들을 다룬다. 화용론에서는 전제, 화행, 함축, 공손성 등의 개념 들을 다룬다. 단어와 문장, 그리고 담화에 대한 이해를 바탕으로 언어 형식에 담긴 의미를 이해하고 자신의 의도를 효과적으로 표현 하는 능력을 기른다. - 국어 의미론의 기본 지식을 습득한다. - 국어 의미에 대한 심도있는 이해를 바탕으로 다채로운 표현 효과를 가진 문장을 구사할 수 있도록 한다. - 교과목표: 이 수업에서는 의미의 정의 및 유형을 이해하고, 의미론의 하위 분야인 어휘의미론, 문장의미론, 화용론의 연구 대상이 무 엇인지 이해한다. - 지식: 어휘의미론에서는 의미 분절, 의미 구분, 의미 관계, 의미의 확장, 의미 변화 등에 대해 이해하고, 문장의미론에서는 의미 논리, 지시와 양화, 구문과 의미역, 시제/상/양태 등 문장 의미를 구성하는 요소들을 이해한다. 화용론에서는 전제, 화행, 함축, 공손성 등 의 개념들을 이해한다. - 기술: 우리 주변의 다양한 텍스트와 발화에 나타나는 단어와 문장, 그리고 담화 차원의 의미를 이해할 수 있다. - 태도: 상대방의 발화의 의도를 정확하게 이해하고, 자신의 의도를 효과적으로 표현할 수 있다. - 핵심역량: 삶의 기술, 소통협력', '{"의미","이해한다","의미론","한국어","요약","대해","의미의","문장","이해하고","시제","지시와","유형을","분절","관계","확장","변화","양화","양태","의미를","전제"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207530', '보험법', '사회과학대학', '사회과학대학', 0, 3, '전선', '윤효영', '보험은 장래의 불확실성을 담보하기 위한 제도이다. 현대의 위험사회에서 일반인들의 보험 수요가 증가하고 보험시장이 확대되면서 보험 관련 분쟁 역시 증가한다. 본 강의에서는 보험 관련 기본 용어, 손해보험과 인보험의 종류와 특징, 보험계약의 성립, 보험계약에 따른 보험계약자와 보험회사의 권리와 의무, 의무 위반에 따른 법적 효과 등을 상법 보험편의 규정을 중심으로 학습한다. 이후 보험 관련 판례를 재구성한 사례를 통하여 이들 법규를 보험 분쟁에 적용하고 해결하는 과정으로 구성되어 있다. * 대부분 교수의 강의로 운영되나, 수업의 효율성을 위해 수업 중 일정한 사례나 주제를 두고 팀별 토의 시간을 가지는 방식이 추가되 는 경우가 있습니다. ** 이런 수업 방식은 부수적으로 그리고 편안하게 운영되어 대다수 학생에게 부담이 되지 않을 것으로 보이나, 반드시 이런 점을 유념 해서 수강 신청해 주기 바랍니다!(자세한 내용은 수업운영방법을 참고할 것) 본 과목은 다음과 같은 역량을 기르는 것을 목표로 한다. 1. 지식 - 보험계약의 요소(보험계약자, 보험의 목적, 피보험이익 등)와 개념을 이해한다. - 보험 사건의 주요 쟁점인 고지의무, 보험약관 교부설명의무, 손해보험과 보험금 산정, 타인의 사망보험 등에 대한 법 규정을 알아 보 고 기본 내용을 습득한다. 2. 기술 - 보험법규를 실제 보험 분쟁 사례에 적용하여 이에 대한 법적 판단을 도출할 수 있다. - 판결문에 나타난 보험법상의 주요 쟁점을 파악하고, 이에 대한 원피고의 주장 사실과 법원의 법규의 해석과 적용 과정을 요약할 수 있다., 3.태도 - 보험법 지식을 활용하여 각종 보험 상품의 주요 내용을 파악하고 분쟁에 대비할 수 있다. - 주요 쟁점에 관하여 대립하는 당사자(보험가입자와 보험회사)의 입장에서 각각의 논거를 검토해 봄으로써 이해관계를 조정하고 합 2. 교과 목표 ■ 교과목표 리적으로 해결하는 자세를 훈련한다.', '{"상법전","강의안","질응응답식","보험계약의","효과","손해보험","사례","보험","고지의무","의의와","의무","법적","요소","있다","보험의","종류","보험법의","개별","요건과","보험계약자의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207536', '기초법률용어', '사회과학대학', '사회과학대학', 0, 3, '전선', '허명국', '법학을 전공하기 위해서 필요한 가장 기본적인 법률개념을 이해하고 이를 바탕으로 법의 가장 기본적인 이념과 이론에 대한 이해를 강의의 목적으로 한다. 또한 법률세계에서 실제로 발생하는 사건에 추상적인 법규정을 적용하여 이를 합리적으로 해결하기 위한 논 리적인 사고방식을 익혀 추사적인 이론의 이해와 실질적인 문제해결의 기본이론을 익힘 법학을 전공하기 위해 필요한 기초적인 법률용어를 익힘', '{"법인의","행위능력","제한능력자","법학을","전공하기","필요한","가장","기본적인","이를","익힘","법률","공법과","사법","민법의","기본원칙","권리와","법률관계","권리능력","의사능력","미성년자의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101324', '문예창작비평론', '인문대학', '인문대학', 0, 3, '전선', '권민자', '문예창작비평론은 문예창작에 관한 기초 이론 및 90년대(1987년 이후) 이후의 한국문학 읽기와 감상을 통해 비평적 능력을 배양한다 . 한국문학을 둘러싼 역사적인 다양한 논의와 비평에 대한 양면적 이해가 동시에 필요하다. 시대 상황에 대한 문학적 대응과 문학 이 론, 비평적 과제, 최근 한국문학의 다양한 경향을 파악하여 새로운 관점을 얻도록 유도한다. 시 창작과 시비평, 소설 창작과 소설비평 을 통해 실제적인 창작이 이루어 질 수 있는 학습을 지향하기 위해 비평적 글쓰기 훈련과 연습을 병행한다. 문예창작비평론을 수업함 으로 한국문학의 감상, 비평, 창작 등의 능력을 배양한다. 1. 문예창작비평론은 학생들의 문예창작에 대한 이해와 비평 능력의 배양에 목표를 둔다. 90년대 이후부터 최근까지 한국문학의 전개 과정과 특징을 구체적인 작품의 독해를 통해 이해하고 감상한다. 2. 시의 기본적인 원리와 기법적인 특성을 이해한다. 소설의 기본적인 원리와 기법적인 특성을 이해한다. 그것을 작품의 분석에 응용 한다. 창작(시, 소설)에 관한 학습의 기초 소양을 배양하기 위해서 여러 시인과 소설가의 작품을 비교하며 강의를 진행할 것이다. 3. 사회, 문화적 맥락, 시대성 등이 문학과 어떤 관련을 맺는지 작품을 통해 이해한다. 작품을 읽고 토론하며 창작과 비평의 현장에서 논의 될 수 있는 쟁점을 찾고 사유한다. * 주별 강의 일정 및 내용은 수강인원과 수강생들의 의견에 따라 변동될 수 있습니다.', '{"소설","신춘문예","창비","평론","민음사","읽기","문학동네","조선일보","장정일","김영하","엘리베이터에","남자는","어떻게","되었나","문학과지성사","박상순","박민규","카스테라","김승일","김애란"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207539', '부동산행정법', '사회과학대학', '사회과학대학', 0, 3, '전선', '오유영', '행정법은 국가와 국민 간의 공법관계를 규율하는 법으로서, 현대 법치국가에서 행정작용의 적법성을 담보하고 국민의 권리를 보호하 는 중요한 역할을 수행한다. 본 강의는 법치행정의 핵심인 행정법의 기초이론을 정립하고, 행정주체가 국민에게 행하는 구체적인 법 적 수단인 행정작용을 체계적으로 고찰하고자 한다. 특히 공무원시험, 행정고시, 각종 자격시험을 준비하는 학생들을 위해 이론과 판 례를 균형 있게 다루며, 행정법의 기본원리부터 행정작용까지 체계적으로 학습하여 문제해결 능력을 배양하는 것을 목표로 한다. 본 강의는 행정법 총론의 기본이론을 체계적으로 학습하여, (1) 행정법의 법원과 일반원칙 등을 이해하고, (2) 행정법관계 및 행정작용 의 구조를 바탕으로 행정행위의 성립·효력·하자 및 재량통제 등의 법리와 판례를 파악·분석할 수 있는 능력을 배양하며 (3) 나아가 행 정절차의 핵심 내용을 습득하는 것을 목표로 한다. 이를 통해 다양한 행정법 관련 쟁점을 파악하고 문제를 해결할 수 있는 역량을 함 양한다.', '{"대해","이해한다","행정행위의","행정의","행위형식에","행정법의","행정법관계의","행정절차의","효력","하자","행정법","구별","법원의","행정법관계에","행정입법","종류","행정행위","공법상","행정지도","체계적으로"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101338', '훈민정음의이해', '인문대학', '인문대학', 0, 3, '전선', '이병기', '훈민정음은 우리 국민 대다수가 우리의 위대한 민족문화유산으로서 매우 자랑스럽게 생각한다. 하지만 막상 훈민정음이 왜 대단한 것인지 물어보면 “세종대왕이 창제하신 과학적이고 배우기 쉬운 글자” 정도의 피상적인 답변에 그치는 경우가 많다. 왜 과학적이고 배우기 쉬운지에 대한 설명까지는 하지 못하고 심지어 훈민정음의 창제와 반포, 훈민정음과 한국어를 혼동해서 잘못 이야기하는 경 우도 흔히 볼 수 있다. 이 강좌는 이렇게 우리가 잘 알고 있다고 생각하지만 제대로 알고 있지 못하는 훈민정음을 종합적으로 이해하 기 위한 목적을 가지며 강의의 상당 부분을 한문으로 기술된 <훈민정음> 해례본을 천천히 읽어나가는 데 할애한다. 우리의 대표적 문화 유산인 훈민정음을 종합적으로 이해햐고 소개할 수 있다. 기술 - 고전문헌을 처음 접했을 때 어떤 참고 수단을 이용하여 읽고 이해할 수 있는지 이해함. 태도 -총 108자로 된 훈민정음 어제 서문을 외우고 설명할 수 있어야 함 -옛 문자와 표기법으로 쓰인 글을 읽을 수 있어야 함. -엣 글을 읽고 해독할 수 있는 기초적인 방법을 익혀야 함-고어사전 이용 방법 포함 -고전소설, 고전시가 등을 원문의 느낌 그대로 이해할 수 있는 기초를 다짐.', '{"훈민정음","강독","이해한다","쓰기","국어사","자료","해례본","읽고","제자해","해례본을","어제","체계","해계본","훈민정음에","제자","일고","서문","제자해를","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204101', '경제학원론(거시)', '사회과학대학', '사회과학대학', 0, 3, '전선', '이충언', '국가경제의 구조 및 운용원리를 이해한다. 이를 위해 국가경제를 총소득, 총소비, 총투자, 순수출 등과 같은 집계적 변수로 구조화하 여, 경제성장, 저축, 투자, 물가, 고용량, 이자율, 국제수지 및 환율 등의 결정요인을 이해하고 나아가 재정정책 및 금융정책의 운용원 리 및 효과를 학습한다. - 국가경제의 운영 원리를 이해하기 위해 다음 세부 내용을 학습 국가경제를 대표하는 변수(자료)인 GDP와 물가 GDP(생산,소득,분배)의 결정 변수 및 경제성장 저축과 투자와 금융제도1 실업이 발생하는 원인과 대책 화폐와 통화제도 통화량과 인플레이션의 장기 관계 개방경제의 기본개념 단기경기변동을 설명하는 총수요과 총공급 모형 총수요과 총공급 모형으로 통화정책과 재정정책의 효과 인플레이션과 실업의 상충관계', '{"교재","용응문제","결정","장기","총공급","실물경제의","국가경제의","측정","자산","총수요와","화폐와","관계","물가","자료","물가의","장기적","단기경기변동의","저축","투자와","금융제도"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101403', '한국문학탐방III', '인문대학', '인문대학', 0, 1, '전선', '서은혜', '이 수업은 한국어와 한국문학과 관련된 실제 공간들 (작가 태생지, 문학관, 작품 배경지, 유적 등)을 답사하고 이를 통해 한국어와 한 국 문학에 대한 이해를 심화시키는 수업입니다. 한국어와 한국문학 관련 지역 답사를 통해 작가 생애, 문학 세계, 한국어사와 한국문 학사의 전개에 대한 이해와 설명 능력을 기릅니다. 다양한 한국문학 작품 속에 드러난 공간적 배경을 실제 답사를 통해 체험하고, 문학적 형상화의 원리에 대해 깊이 이해합니다. 한국어사와 한국문학사의 사적 전개에 대해 설명할 수 있습니다.', '{"답사자료집","실제","작가","초고","작성","작성합니다","한국어와","인용의","작품","한국문학","답사를","한국어사와","전개에","대해","답사지","작품세계","지역의","특성을","탐구합니다","조별로"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204102', '경제학원론(미시)', '사회과학대학', '사회과학대학', 0, 3, '전선', '유한욱', '- 학생들에게 "인간의 일상생활을 연구하는 학문"인 경제학을 접하게 함으로써, (1) 우리가 살고 있는 세계를 이해하고, (2) 경제활동에 보다 지혜롭게 참여하는 한편, (3) 정부의 각종 경제정책들이 어떻게 설계되고 운영되는지를 이해하게 함. - 경제학의 기본원리, 시장의 작동원리, 소비자/생산자의 의사결정, 산업조직, 노동시장, 공공경제학 등 미시경제학의 기본 요소들에 대한 지식을 습득하고 적용하는 것을 배움. 경제학과 신입생을 대상으로 "인간의 일상생활을 연구하는 학문"인 경제학을 접하게 하고 기초지식을 익히게 함.', '{"연습문제","시장의","수요","공급","그리고","균형","소비자의","선택","기업의","생산활동","완전경쟁시장","불완전경쟁시장","게임이론","생산요소시장","소득분배의","현실","정보경제이론","인간의","일상생활을","연구하는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101407', '고전소설강독', '인문대학', '인문대학', 0, 3, '전선', '남혜원', '본 수업은 한국 고전소설 작품을 중심으로 원문 텍스트를 정독하며, 고전소설이 한국문학사에서 차지하는 서사적 영향력과 그 위치 를 이해하는 것을 목표로 한다. 수업에서는 주요 고전소설을 강독하면서 작품의 서사 구조와 표현 방식, 주제 의식을 분석하고, 이를 통해 당대 독자들의 향유 방식과 삶의 감각을 폭넓게 살펴본다. 아울러 작품의 현대적 변용 과정을 검토함으로써, 고전소설이 오늘날 한국문화콘텐츠의 서사적 기반으로 작동하는 양상을 파악한다. - 한국 고전소설 작품을 원문 중심으로 강독하며, 텍스트에 대한 감상력과 분석력을 기른다. - 고전소설이 생산·유통·수용된 역사적·문화적 맥락을 살펴, 한국 서사 전통 전반에 대한 이해를 확장한다. - 작품의 현대적 의미와 변용 양상을 검토하여, 고전소설이 한국문화콘텐츠의 서사적 자원으로 활용될 가능성을 이해한다.', '{"원문","홍길동전","내용과","강독","고전소설","현대적","주제","원문을","강독하고","특징을","이해할","있다","특징에","재해석과","병행","춘향전","작품","고전소설이","고전소설에","고전소설의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204297', '경제와수학적분석', '사회과학대학', '사회과학대학', 0, 3, '전선', '한영욱', '경제학을 공부하는 방법들중 하나는 경제이론들과 경제현상들을 단순화하여 수학적인 개념과 공식을 이용하여 파악하고 설명하는 수학적 분석방법이다. 따라서, 경제학에서는 여러가지 경제현상들과 경제문제들을 설명하고 분석하기 위해서 수학의 주요분석개념들 인 함수관계, 행렬, 미분, 적분등을 사용하게 된다. 이에따라 본 과목에서는 학생들이 경제학을 공부하면서 자주 접하게 되는 여러가 지 기본적인 수학적 분석도구들과 모형들을 배우고 또한 필요한 기초적인 수학개념을 배우게 된다. 이러한 수학적인 방법을 통해서 경제이론들과 경제현상들에 대한 이해를 보다 다양하고 용이하게 함으로써 경제학을 폭넓게 공부하고자 한다. 여러 경제현상들과 경제이론들에 대한 분석과이해를 위해 필요한 기본적인 수학적 분석기법과 기술을 습득하는데 목표를 둔다', '{"연습문제","문제풀이","극소화","함수의","응용","경제학의","극대화","미분","행렬의","극한과","연속","미분법","다변수함수의","편도함수","전미분","극대화와","제약조건하의","극대","경제학을","수학적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101415', '한국어교육의이해', '인문대학', '인문대학', 0, 3, '전선', '이병기', '- 외국인어로서의 한국어를 교육하는 데 필요한 한국어 및 한국 문화에 대한 이해와 교육 방법에 대하여 이해한다. - 인문사회 육합인재양성사업(HUSS)과 연계하여 외국 학생들과의 소통 기회를 모색하고 실제 교육을 준비한다. - 한국어 및 한국문화에 대한 인문, 사회학의 통찰과 분석을 하고 이를 바탕으로 외국인 한국어 학습자들에게 한국어를 교수할 수 있 는 융합형 인재 양성. - 한국의 지역 문화와 외국 각 지역의 문화를 객관적으로 바라보고 외국인 한국어 학습자들에게 한국어를 교수할 준비를 하면서 HU SS 사업의 비전인 지역 가치 혁신과 지속 가능한 공유 네트워트 구축을 도모함. - HUSS 사업과 연계하여 외국 학생들과 언어를 매개로 소통할 수 있는 역량을 키움.', '{"한국어","교육","손에","잡히는","교육학","개론","교육에","공지","수업시간","문법","지역","문화적","화용적","현상","읽기","교안","기관","학습자의","어휘","실재"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101408', '중세시가론', '인문대학', '인문대학', 0, 3, '전선', '김명준', '이 수업은 상고부터 고려시대까지 한국고전시가를 이해하여 한국고전문학의 우수성을 확인하고 이를 바탕으로 현재 한국문화 창달 에 기여할 수 방안을 모색하도록 설계되었다. 상고가요, 향가, 고려속요, 경기체가 갈래 일반과 작품에 대한 이해를 제고한다. 이를 위 해 상고가요, 향가, 고려속요, 경기체가 등의 주요 시가에 대한 율격과 장르의 문제, 작품 내용에 대한 심층적 분석, 시가의 형성과 발 전에 관한 시대적인 변화 양상 및 해당 시인들에 대하여 탐구한다. 이를 통해 한국고전시가의 문화적 가치를 발견하고 구현 방안에 대해 모색한다. 1. 한국고전시가를 통해 자아와 세계, 과거와 현재를 이해하는 본질 탐구 역량 배양 2. 시가가 내재하고 있는 음악, 미술, 무용 등의 종합 예술의 수용 능력 함양 3. 본 강의를 바탕으로 문화콘텐츠적 요소를 발굴하고 구현할 수 있는 실용화 역량 개발 4. 한국 중세시가문학을 소재로 하여 대내외 현대인들의 삶에 긍정적 영향을 줄 수 있는 실용적 가치를 지닌 유무형의 콘텐츠 발굴 및 개발 역량 강화', '{"문화적","작품들에","가치를","대해","가능성을","이해하고","발견한다","발견할","방안을","시대적","배경","성과와","반성","가치","발견","모색","질문과","답변","찾아볼","활용하여"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101411', '현대소설강독', '인문대학', '인문대학', 0, 3, '전선', '서은혜', '이 과목은 한국 근현대소설사 중 시대별로 중요하게 평가되는 작품들을 선택하여 함께 읽어 나가는 수업입니다. 1910년대부터 현재 에 이르기까지, 개별 소설에 담긴 문제의식을 당대 시대적 배경과 연결하여 해석하는 능력을 기르는 것이 목적입니다. 또 소설 텍스 트를 발표 시점의 원문 형태로 단어 하나, 어구 하나서부터 주밀하게 읽는 연습을 통해 텍스트 분석과 해석의 기초능력을 기를 수 있 습니다. 수업 전반부 중 몇 주차는 근대소설을 되도록 잡지 연재 원문으로 함께 읽어, 근대소설 독해 기본 능력을 기릅니다. 중반부 이후에는 현대소설을 읽고 행간의 의미와 시대적 배경의 관련성, 소설의 구조와 특징에 대해 논의합니다. 이러한 과정을 통해 소설의 가치와 아름다움을 느끼고 공유하는 것이 목표입니다.', '{"년대","텍스트","형상화","광장","문학적","함께","소설의","이광수","무정","無情","연애","없는","밀실","어디로","기억과","철도","자아","내면","근대라는","신세계"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204313', '화폐금융론', '사회과학대학', '사회과학대학', 0, 3, '전선', '이충언', '국가경제를 원활히 순환시키는 화폐의 기능과 금융시장, 금융기관 및 금융현상을 배운다. 구체적으로 화폐의 기능, 금융시장, 금융상 품, 이자율, 자산가격결정이론, 이자율 결정이론, 효율시장가설, 우리나라의 금융제도, 금융중개기관이론, 화폐와 물가안정, 통화정책, 금융안정 등을 학습한다. 국가경제를 원활히 순환시키는 화폐의 기능과 금융시장, 금융기관 및 금융현상을 배운다', '{"연습문제","이자율의","금융기관","경제적","금융위기","화폐의","금융시장","효율시장가설","국가경제를","원활히","순환시키는","기능과","금융현상을","배운다","이자율","화폐와","금융시스템의","개관","화폐란","무엇인가"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204314', '재정학', '사회과학대학', '사회과학대학', 0, 3, '전선', '김승래', '- 현대 사회에서 필수적인 사회후생 극대화를 위한 정부 및 공공부문의 역할, 개인의 조세/재정 활동, 그리고 민간시장 개입에 대한 이론적 기초와 현실 응용을 학습한다. - 후생경제학 이론을 기초로 자원배분, 분배와 사회복지, 조세 및 재정 이론과 제도운영과 같은 다양한 주제를 배우며, 실제 민간시장 의 실패와 이를 보정하기 위해 경제현실에서 나타나는 정부와 정치 과정의 각종 제도와 정책에 대한 전문적 이해를 높인다. 본 수업을 통해 다음과 같은 내용을 할 수 있어야 한다. 글로벌 및 패러다임 전환 시대에 경제활동과 재정에 대한 이해 경제활동과 재정 분석을 위한 시장 및 경제주체의 행위 분석의 이해 경제활동 및 재정 분석의 방법론 습득 경제활동 및 재정의 성과 분석 및 평가', '{"유레카","일부","조세와","분석의","현대재정학","행위","재정","공공재의","응용과","사례","외부성의","비용","편익","중간고사","효율성","우리나라의","경제","후생경제학","조세","민간시장"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('101412', '현대시인론', '인문대학', '인문대학', 0, 3, '전선', '권민자', '한국시에 대한 이해를 바탕으로 현대시인론을 강의한다. 한국의 근대시는 서구, 근대라는 보편성의 추구와 근대 이후 이루어진 민족, 역사, 전통, 문화, 등의 자기 정체성에 대한 탐구로 이루어져 왔다. 따라서 한국 현대시인론 강의에서는 시를 둘러싼 역사적인 다양한 논의와 시론에 대한 이해가 필요하다. 시인의 시와 시인의 창작 경험에 바탕을 둔 시론을 동시에 공부한다. 토론과 발표를 통해 학생 이 스스로의 관점을 찾아가도록 돕는다. 1. 한국 현대시의 전개과정과 특징을 한국 현대시사에서 중요한 역할을 담당한 시인들을 집중적으로 조명함으로써 이해한다. 한국 현 대시사에 대한 총체적 안목을 기르고 한국 현대시인에 대해 깊이 이해하도록 하는 것을 목표로 한다. 2. 시에 관한 학습의 기초 소양 기르기와 시읽기 능력의 배양에 목표를 둔다. 시의 기본적인 원리와 기법적인 특성을 이해하여 그것을 시의 분석에 응용한다. 시에 관한 학습의 기초 소양을 배양하기 위해서 여러 시인의 시를 연구할 것이다. 3. 시인, 작품, 시대의 상관성을 시 읽기와 감상의 한 방법으로 접근하는 방식을 터득시킨다. 작품을 읽고 토론하며, 최종적으로는 자 율적 연구 능력을 갖추는 단계에 도달하는 것을 목표로 한다. *주별 강의 일정 및 내용은 수강인원과 수강생들의 의견에 따라 변동될 수 있습니다.', '{"시인","한국","백석","서정주","김수영","송기한","김윤정","박문사","전집","이후","정지용","년대","한용운","김재용","실천문학사","임화","이상","미당","문학사","상사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204316', '환율과국제금융', '사회과학대학', '사회과학대학', 0, 3, '전선', '한영욱', '먼저 개방거시경제학 측면에서 개방경제와 국민경제의 관게를 국제수지표를 이용하여 한 국가의 대외적인 경제활동인 국제무역과 국제금융 거래를 총괄적으로 분석하고, 이를 토대로 국제금융거래의 개괄적인 측면에서 다양한 금융시장들과 금융거래들에 대해 파 악하고 국제금융거래의 중요성을 알아본다. 또한 국제금융시장들 중에서 가장 중요한 국제금융시장인 국제외환시장에 대해서 개방 거시경제학 측면에서 국제 외환분야의 전반적인 현황 및 이론들을 살펴보고 특히 외환시장과 환율을 중심으로 환율의 주요 이론들 과 경제정책들 그리고 외환과 관련된 거시경제 변수들에 대해서 토의 하고 공부를 한다. 국제금융분야의 전반적인 현황 및 이론들을 알아보고 특히 외환시장과 환율을 중심으로 토의 하고 공부를 한다.', '{"강의노트","외환시장과","환율","국제거래조건과","금융시장균형","환율결정이론","환율과","거시경제정책","국민경제","개방경제와","국제금융의","정의","국제금융시장과","국제금융제도","측면에서","국제금융거래의","대해서","전반적인","이론들을","특히"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204399', '계량경제학', '사회과학대학', '사회과학대학', 0, 3, '전선', '김승래', '- 현대 경제학 및 경영학을 위한 통계 이론 기초와 다양한 현실 경제 현상을 계량적으로 접근하여 분석하는 유용한 분석 도구로서 통계분석 기법, A I 기법 및 기초 계량분석 기법의 추정, 가설 검정, 예측 등 방법론에 대하여 학습 - 머신러닝 및 빅데이터 시대에 필수적인 실제 경제 및 경영 관련 통계자료를 활용한 기초적 정량 분석의 이론 원리 학습 및 일부 실 습 병행 본 수업을 통해 다음과 같은 내용을 할 수 있어야 한다. 경제활동의 계량화를 위한 이론적 이해 경제활동 및 통계자료 분석을 위한 분석 방법론에 대한 기초 함양 경제활동 계량화 분석 및 응용을 위한 최신 실제 방법론 습득 계량경제 모형의 설계 및 분석 능력 제고', '{"연습문제","현실","응용","계량경제","통계학","단순회귀분석","다중회귀분석","회귀분석을","기본가정의","위배","검정","경제","기법","방법론에","실제","경제활동","이야기","수학","배경","회귀분석과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('701005', '데이터를읽는눈', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '박현숙', '데이터가 갖고 있는 융합적인 정보를 숫자와 그림으로 해석하는 사고력을 증진시키기 위하여 데이터를 읽을 때에 필요한 ''데이터문 해력'' 전공역량을 쉽게 시작하여 목표역량을 키움. 사례중심으로 데이터를 표와 그래프로 요약하는 방법을 이해하고, 그 정보를 해석 하는 시각과 통찰력을 길러 사회의 시사적 통계정보의 정확한 해석과 판단을 통해 의사결정을 할 수 있는 문제해결 능력을 키움 본 과목에서는 통계학이 더 이상 골치 아픈 수치만이 아니라 우리의 삶과 밀접한 아주 매력적인 학문임을 알게 될 것이며, 최근 기업 에서 인재선발에 반드시 필요한 데이터를 읽는 시각과 창의적 사고력을 훈련하는 역량과정을 목표로 함 “이 수업은 데이터를 잘 다루는 사람을 만드는 수업이 아니라, 데이터에 속지 않는 사람을 만드는 수업입니다.”', '{"빅데이터","데이터","교수자","발표횟수","데이터를","사례","통한","자신","동료","기출문제","일자리","변화","주어진","시각화","팀발표","점척도를","풀이","정보","기반","문제제기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204411', '노동시장론', '사회과학대학', '사회과학대학', 0, 3, '전선', '조동훈', '본 강의는 노동 경제학에 대한 기초적 주제를 이론적, 실증적 분석을 통해서 다루고자 한다. 기본이 되는 노둥공급과 수요에 대해서 구체적으로 공부하고, 여러 가지 다양한 노동경제학과 관련된 주제들을 최근 논문과 함께 다룰 것이다. 기본적인 미식경제학 지식외 에도 기본적 회귀분석에 대한 지식을 요구한다 (첫 수업시간에 간략히 다룰 것 임). 노동시장을 경제학적 사고로 이해하기', '{"노동공급과","추정","인적자본이론","다룰","노동공급이론","정부정책","생애주기","노동수요이론","노동시장의","완전경쟁균형","최저임금제","노동공급함수","노동수요","공급에","관한","논문고찰","리뷰","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('701009', '어드벤쳐디자인:공', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '한준희', '- 현대는 데이터는 넘쳐 나는데 그 데이터를 활요하는 방법을 모르는 경우가 허다하다 - 그 중 정부 3.0 등 여러 정책적인 이유등으로 방대한 양의 공공데이터가 쏟아지고 있다. - 중앙정부의 여러 기관들 뿐만아니라 지방정부, 비영리, 심지어 영리 단체에서도 다양한 정보와 형태를 가진 데이터를 공개하여 누 구 나 보고 활용할 수 있는 길을 터 놓고 있다. - 본 과목은 이렇게 넘쳐나는 다양한 공공데이터를 접해보고 어떻게 분석하고 이해를 할지 고민해본다 -지식 공공데이터에 어떤 종류가 있는지 알고, 그러한 데이터를 분석하는 방법과 결과를 해석하는 방법을 익힌다 - 기술 R등의 통계 분석툴을 이용하여 실제 분석을 해본다 - 태도 데이터 분석은 꼭 하나의 정답만 있지 않다는 사실을 인지하고 폭 넓은 사고를 바탕으로 여러가지 문제 해결방법을 제시해본다.', '{"데이터","공공데이터","중간고사","대체","강의노트","데이터출처","찾기","예시를","활용방법을","마크다운","공공의료","찾고","자료","학습자","스스로","관심있는","데이터를","익힌다","강의자료","방법을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('701021', '다변량분석', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '심송용', '다변량자료는 데이터과학에서 자주 접하는 자료이다. 이들 자료를 분석하기 위한 기초적인 분포 및 행렬이론 학습하고 이를 바탕으 로 거리측도, 평균벡터에 대한 이해, 다변량분산분석, 주성분 분석, 요인분석, 정준상관분석, 판별분석, 군집분석 등 다변량 자료에 대 한 분석 기법을 학습한다. 다변량 자료의 구조를 이해하고 이들 자료를 적절한 통계분석 방법을 사용하여 통계적으로 유의미한 결과를 도출할 수 있다.', '{"다변량","수업시간에","배포","중간고사","분산분석","일변량","검정","분포","다변량분산분석","행렬의","이들","자료를","거리측도","판별분석","자료의","교과목소개","자료","행렬대수","확률분포","정규분포"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204507', '미시경제학II', '사회과학대학', '사회과학대학', 0, 3, '전선', '김승래', '본 강의는 현대 미시경제이론의 기본적인 개념, 분석 방법론 및 다양한 응용에 관한 제반 지식을 전달함을 목적으로 하고 있다. 미시경제학 응용으로서 시장구조와 경쟁전략, 독점, 과점 등 시장지배력, 생산요소시장, 투자, 시간성 및 자본시장, 일반균형이론 및 효율성, 시장 실패와 정부 역할, 외부성 및 공공재 이론 등에 관하여 학습한다. 미시경제학에 대한 학문적 이론 원리를 이해하고 이를 현실 경제에 적용하여 활용할 수 있는 능력을 함양', '{"핀다이크","과점","효율성","응용","독점적","경쟁과","중간고사","일반균형과","경제적","시장지배력","생산요소시장","투자","시간성","자본시장","공공재","독점","공급독점과","수요독점","시장지배력을","이용한"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('701030', '설명가능인공지능', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '유재용', '인공지능 (AI) 모델의 투명성과 해석가능성을 높이는 방법에 중점을 둔 XAI (eXplainable AI)의 개념과 실습을 다룸 다양한 XAI의 긱법을 배우고, 실제 데이터를 활용하여 설명가능한 분석을 수행하는 경험을 쌓음. 설명가능한 인공지능(XAI)의 개념 및 필요성을 이해한다 실제 AI 모델에서 설명가능성 기법을 적용하고 해석하는 방법을 익힌다 SHAP, LIME, Grad-CAM 등의 주요 XAI 기법을 학습한다', '{"강의자료","알고리즘","기반","기초적인","회귀분석","모델","방법을","인공지능","실제","설명가능한","기법을","개요","기법에","기법에대한","중간고사","딥러닝","기반의","활용한"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204508', '거시경제학I', '사회과학대학', '사회과학대학', 0, 3, '전필', '이충언', '국가경제의 운영 원리를 이해한다. 이를 위해 주요 거시경제변수인 소득, 물가, 대외수지, 실업률, 경제성장률 등의 결정 원리를 이해 하고 국가간 이 값에서 차이가 발생하는 원인을 분석한다. 나아가 정부의 어떤 정책으로 이들 변수를 얼마만큼 향상시킬 수 있는가를 배운다. 국가경제의 운영 원리를 이해', '{"경제성장","거시경제학의","자료","국민소득","생산과","분배","화폐제도","정의","역할","인플레이션","원인","결과","사회적비용","개방경제","실업","자본축적과","인구증가","기술","경험","그리고"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('670000', '인공지능의이해', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '류세민', '본 과목은 인공지능 영역 중 기계학습에 필요한 기초 지식을 학생들이 이해할 수 있도록 하는 것을 핵심 목표로 하고 있음. 수강하는 학생은 다음의 내용을 본 수업을 통해 학습하게 된다. - 인공지능 개요 - Unsupervised learning : K-means clustering 등 - Supervised learning : Naive bayes, Desicion Tree, SVM, Perceptron 등 분류기 이해 및 설계 - 딥러닝의 근간이 되는 Neural networks 에 대한 이해 인공지능 시스템을 직접 제작해보도록 하여, 학생들이 인공지능 시대에 필요한 기술에 대한 감을 잡도록 한다. 인공지능 및 머신러닝의 개념을 습득하고, 다양한 머신러닝/딥러닝 알고리즘을 직접 구현해봄으로써 실용적 지식 학습 다양한 기기에 적용가능한 기계학습 모델을 구현하여 지식의 활용도를 높임', '{"인공지능","알고리즘","구현","필요한","학생들이","직접","중간고사","주차","구성요소","활용하기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('710000', '데이터분석과시각화', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '이종석', '본 교과목은 실제 자료를 기반으로 데이터 분석 및 시각화 기법을 학습함으로써, 현실 문제를 해력하는 능력을 배양하는 것을 목표로 한다. 이번 학기는 질병관리청에서 실시하는 국민건강영양조사(Korea National Health and Nutrition Examination Survey, KNHANE S) 원시자료를 활용해, 심혈관질환의 위험 요인으로서 LDL-콜레스테롤과 대사증후군을 관계를 분석하는 문제를 중심으로 진행하고 자 한다. 이를 통해 데이터 분석을 위한 통계적인 기법과 모델링 방법을 학습하고, 시각화를 통해 문제를 분석하는 능력을 배양하고 자 한다. 현장 문제 중심의 실제 자료에 기반한 데이터 분석과 시각화 역량을 배양함. 이번 학기는 심혈관질환 위험도 평가라는 현장의 문제를 중심으로 진행함', '{"엑셀","수업자료","도구","파이썬","이해하기","수업에서","제시되는","문제의","데이터","심혈관질환","워드","파워포인트","콜레스테롤","시각화","전처리","변수","위험요인으로서","측정에","비교","문제를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('204520', '미시경제학연습', '사회과학대학', '사회과학대학', 0, 3, '전선', '유한욱', '1. 본 강의는 미시경제학 분야 심화선택과목으로서 전통적인 소비자이론, 생산자이론과 함께 미시경제이론의 새로운 분야에 대한 전 공지식 전수를 목적으로 함. 2. 미시경제학 관련 타 전공선택과목에서 상세히 다루지 못하는 미시경제 이론 강의 및 관련 연습문제 풀이를 제공함. 본 강의는 미시경제학 분야에 대한 세부이론 습득 및 활용을 위해 이론강의 및 문제풀이를 제공함. 1. 미시경제학 주요 분야에 대한 이론 강의: 소비자이론, 생산자이론, 정보경제이론, 법경제이론, 금융시장이론, 행태경제이론 등 2. 관련 연습문제 풀이 및 해설', '{"주교재","정보경제이론","금융시장이론","미시경제학","분야에","법경제이론","행태경제이론","소비자의","강의는","소비자이론","연습문제","제공함","최적선택","소비자이론의","응용과","확장","불확실성하에서의","선택","기업과","생산기술"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729017', '확률통계기초', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '최가영', '본 과목은 통계학습 및 머신러닝에 필요한 기초 지식을 이해하는 것을 핵심목표로 하며, 데이터 분석을 위한 Python 및 MATLAB 프 로그램을 통해 데이터를 가공하거나 정제하고, 통계 분석 및 실제 머신러닝 분석에 활용 할 수 있도록 실습을 통해 실무적 현장에 효 과적으로 응용 할 수 있도록 지도한다. Python 및 MATLAB을 활용하여 인공지능을 위한 기초 통계에 대한 이론을 학습하고, 실제 데이터를 활용하여 실습함으로써 실무 통 계 및 머신러닝 프로그래밍에 대한 응용력을 기를 수 있다.', '{"배포","이해와","기술통계","확률과","확률분포","표본추출과","표본분포","통계적","가설검정","검정","검정에","분산분석","분산분석에","상관관계","통계","데이터를","실제","머신러닝","있도록","활용하여"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('720005', '공공기관의이해', '사회과학대학', '사회과학대학', 0, 3, '전선', '신수행', '공공기관은 정부 정책을 집행하고 국민에게 필수적인 공공서비스를 제공하는 핵심 조직이다. 동시에 공공성과 효율성을 함께 달 성해야 하는 특수한 운영 구조를 지니며, 성과관리와 경영평가, 책임성 확보 등 엄격한 제도적 틀 속에서 운영된다. 본 수업은 공공기관의 개념과 생성 배경을 출발점으로 하여 지정 제도, 지배구조, 조직과 인사, 예산과 재무, 성과관리와 경영평가 까지 운영 체계를 체계적으로 학습한다. 학생들은 공공기관이 무엇을 중요하게 관리하고 평가하는지 구조적으로 이해하게 되며, 공공 부문을 분석하는 기초 역량을 갖추게 된다. 아울러 본 수업은 공공기관 취업을 희망하는 학생을 위한 실질적 준비 과정으로 설계하였다. 채용 절차의 특징, 면접 평가 방식, 공 문서와 보고서 작성의 기본 원리를 사례와 실습을 통해 익힌다. 관심 기관을 직접 분석하고 자신의 진로 전략을 구체화하는 과정을 통해 막연한 준비에서 벗어나 체계적인 준비 수준에 도달하도록 한다. 이 과목은 공공기관을 이해하는 이론 수업을 넘어, 공공기관 취업을 준비하는 학생이라면 반드시 갖추어야 할 기본 구조와 사고 틀 을 제공하는 강의이다. 본 과목은 공공기관의 개념과 유형을 이해하고, 공공서비스 공급 과정에서 정부와 시장의 역할과 한계를 분석할 수 있는 기초 역 량을 기르는 것을 목표로 한다. 이를 바탕으로 공공기관의 생성 원리와 지정 제도, 지배구조, 조직과 인사, 예산과 재무, 성과관리와 경영평가 등 핵심 관리 체계를 체계적으로 이해한다. 또한 공공기관이 실제로 무엇을 관리하고 어떠한 기준에 따라 운영되는지를 분석함으로써, 공공부문 조직을 구조적으로 바라보 는 사고 능력을 함양한다. 이를 통해 학생들은 공공기관을 제도적·정책적 관점에서 종합적으로 설명할 수 있는 수준에 도달한다. 아울러 본 과목은 공공기관 취업을 희망하는 학생이 갖추어야 할 기본 역량 형성을 중요한 목표로 한다. 채용 절차의 구조와 평가 요소를 이해하고, 면접에서 요구되는 논리적 표현 능력과 공문서·보고서 작성의 기초 능력을 함양한다. 그 결과 학생들은 공공기관을 이해하는 지식 수준을 넘어, 실제 준비 단계에서 요구되는 실질적 역량을 갖추게 된다.', '{"공공기관의","공공기관","지배구조","조직과","재무","특강","성과관리와","경영평가","운영","개념과","지정","예산과","희망하는","효과","이해와","국민평가","인사관리","문서의","대응","노사관계"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('710004', '인공지능기술과경영', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '김항섭', '- 본 교과목은 인공지능 기술의 급격한 발전이 글로벌 경제와 산업에 미치는 영향을 여러관점에서 학생들이 쉽게 이해할 수 있고, AI시대의 기술과 경제 생태계를 체계적으로 이해하고 향후 자신의 미래 발전 전략을 수립할 수 있는 지식과 역량을 배양하게 됩니다. - 특히, 본 강의는 단순한 기술 이해를 넘어, AI가 창출하는 경제적, 기업적, 사회적, 개인적 영향까지 포괄적으로 다룹니다. PEST(정치, 경제,사회, 기술)분석 툴을 활용해서 AI 혁신을 조망합니다. 1. AI 기술의 핵심 요소(HBM, GPU, NPU)와 경제적 가치 창출 메커니즘을 이해하고 설명할 수 있다. 2. 주요 인물 및 기업의 전략적 의사결정을 분석하고 비평할 수 있다. 3. PEST 분석을 통한 AI 산업 환경을 체계적으로 분석할 수 있다. 4. 인문학적 관점에서 AI 기술의 사회적 영향을 성찰하고 논의할 수 있다. 5. 실증적 데이터 기반으로 비판적 사고와 창의적 문제해결 능력을 발휘할 수 있다.', '{"안다","퀴즈","영상","글로벌","기업의","기술","경쟁","반도체","직업","전략을","있다","자기성찰","사회적","조별토론","사례","테스트","모델과","전략","제로","투자"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('720021', '공공기관NCS이해', '사회과학대학', '사회과학대학', 0, 3, '전선', '최창현', '본 교과목은 공공기관 및 공기업뿐만 아니라 일반기업체의 국가직무능력표준(NCS)기반 채용에 대비하여 직무수행에 필요한 기초지 식을 함양하는 것을 목표로 한다. NCS 직업기초지식은 의사소통능력, 수리능력, 문제해결능력, 조직이해능력, 정보능력 등 10개의 모 듈로 구성되어 있다. 본 교과목에서는 이들 10개 영역에 대하여 각 능력단위별로 지식 및 기술체계와 직무태도에 대하여 학습한다. NCS 직업기초능력은 10개 영역으로 구성된다. 이 과목의 목표는 이 10가지 능력 함향에 도움을 주는 것이다. 1. 의사소통능력 문서를 이해하고 정보를 명확히 전달하는 능력 2. 자원관리능력 시간, 예산 등 자원을 효과적으로 관리하는 능력 3. 문제해결능력？ 직무 수행 중 발생하는 문제를 해결하는 능력 4. 정보능력 필요한 정보를 검색하고 활용하는 능력 5. 조직이해능력 조직의 목적과 목표를 이해하고 행동하는 능력 6. 수리능력 계산 및 수치 데이터를 처리하는 능력 7. 자기개발능력 자신의 경력을 개발하고 효율적으로 관리하는 능력 8. 대인관계능력 협력적이고 긍정적인 관계를 형성하는 능력 2. 교과 목표 ■ 교과목표 9. 기술능력 특정 직무 수행에 필요한 기술적 능력 10. 직업윤리 윤리적 판단을 바탕으로 직무를 수행하는 능력', '{"문제해결능력","조직이해능력","의사소통","자기개발능력","직업윤리","컴퓨터","활용능력","정보처리능력","필요한","기술능력","공공기관의","공공기관","의사소통능력","수리능력","정보능력","대하여","이해하고","정보를","관리하는","직무"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('710014', '인공지능기술경영', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '이용석', 'o ICBM(IoT, Cloud, Big Data, Mobile Network) 및 AI 기술을 기반으로 하는 4차 산업혁명사회 확산 소개 - ICBM 기술의 개념, 산업 및 고용구조, 비즈니스 모델 패러다임 등 경영환경의 변화 o AI 기술의 단계적 발전과정 설명 - Turing Test, 기호주의와 연결주의, 전문가 시스템(ES), 인공신경망(ANN) 등 - Maching Learning(지도학습, 비지도학습, 강화학습)과 Deep Learning(CNN, RNN, GAN)의 진화 등 o IT, ICBM 및 AI 등을 도입한 기업의 경영프로세스 혁신내용 학습 - 전사적 자원관리(ERP), 공급망관리(SCM) 및 고객관계관리(CRM) - Maching Learning과 Deep Learning의 경영 활용 사례 등 o AI 기술경영의 사회/경제적 환경 분석 - Digital Transformation, Data의 기업경쟁력, 공유경제 - Platform 경제, Block Chain 기술의 확산 등 o 비즈니스 모델 구조 이해 및 ICBM/AI 기반의 New 수익모델 학습 o ICBM 및 AI를 활용한 마케팅 패러다임의 고도화 설명 - 1차→4차 산업혁명시대까지 마케팅 패러다임의 변천 - ICBM/AI 기반의 개인맞춤형 마케팅 사례 등 o 세계적 경영 전문가들의 경제/경영 이론에 대한 소개 o 국가직무능력(NCS) 관련 취업역량 강화방안 등에 관한 특강 등 - 기업/공공기관의 NCS 기반 채용절차 안내 및 취업 준비방안 - 자기소개서 작성/필기？면접시험에 필요한 직무기초능력 설명 등 2. 교과 목표 ■ 교과목표 o IT, AI, 경영 및 정책 분야의 실무적 지식 및 현행 적용사례 학습을 통해 종합적이고 실천적인 문제해결 능력 보유 - 기술과 경영 관련 전문성을 습득함으로써 직무현장에서의 적응능력 제고 o 현대 기업업무에 기본적, 필수적인 경영 및 AI 지식 습득을 통해 업무역량의 강화 - 4차 산업혁명시대의 기술적 핵심기반인 ICBM과 AI에 대한 이해 - 비즈니스 모델구조, 경영정보시스템 및 ICBM/AI를 활용한 새로운 비즈니스 수익모델 학습 o 문/이과생에게 전공을 뛰어 넘는 융합적 역량 강화 지도 - 이과생의 경우에는 경영 이론과 기법을, 문과생에게는 IT, AI 등 기술 분야의 지식 학습 o 업무처리 순발력, 문제해결능력 등 제고 방법 지도 - 기술과 경영간 융합적 지식의 폭을 넓혀 업무 과제별 합리적, 효과적 해결책을 주도적으로 구현할 수 있는 역량 지도 o 대학 재학중 취업역량 강화를 위한 자기주도적 준비방향 Guideline 제시 및 국가직무역량(NCS) 활용방법 지도 ※ 기업 및 공공기관 취업에 있어서 NCS기반 준비는 필수', '{"대면강의","교재안","비즈니스","경영","모델","패러다임의","산업","변화","기술경영의","경제적","마케팅","확산","활용한","지도","시대","프로세스의","혁신","환경분석","설명","시스템"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('504149', '기업가정신과디자인씽킹', '경영대학', '경영대학', 0, 3, '전선', '김용근', '- 최근 기업(대/중/스타트업)과 공공기관 등에서는 급변하는 경영환경으로 인해 과거에 없던 새로운 문제도 해결할 수 있는 문해력( 문제해결력)을 보유한 인재를 필요로 하고 있다. - 이에 본 과목에서는 다양한 기업가에 대한 학습을 통해 기업가정신을 배양하고, 스탠포드 방법론에 기초한 디자인씽킹을 통해 문제 해결력을 강화하고자 한다. - 마침 학교는 글로컬대학 선정 및 RISE 사업 추진으로 지역에서 발굴된 다양한 현안 문제 해결에 대한 니즈가 높아 이를 접목한 프로 젝트도 진행할 것이다. - 이를 통해 학생들은 지역 이슈에 대한 실질적 이해와 문제해결력을 보유한 차별화된 인재로 향후 창업, 취업 등에서 차별화된 경쟁 력을 보유한 한림인이 될 수 있을 것이다. - 본 교과목은 창업에 대한 막연한 두려움을 갖고 있는 학생들에게 다양한 유형(학생, 청년, 장년 등)의 창업가에 대한 학습으로 자신 감을 가질 수 있도록 기업가 정신을 고취한다. - 창업에 기본이 되는 대표적 고객분석 방법론인 디자인씽킹 방법을 이해하고, 실제 사례를 기반으로 한 실습을 통해 창의적 문제해 결력을 갖게 한다. - 실제 지역 창업가와 함께 AI를 활용하여 새로운 비즈니스 모델로 재창업할 수 있는 기회를 제공', '{"팀별","결과","활동","자료","현장","재창업","특강","디자인","피드백","스탠포드","프로젝트","개별","미팅","창업에","기업가정신","정의","로컬","대표","씽킹","방법론"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('710025', '웨어러블센서와기술', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '정인철', '의료인공지능 3학년 1학기 전공과정으로 설계된 과목입니다. 의료인공지능전공 학생의 수강을 추천드리고 또한 디지털헬스케어 시 스템, 정밀의료시스템, 인공지능기술 의료기기시스템, 웨어러블 헬스케어 시스템에 관심있는 학생의 수강도 추천드립니다. 과목의 목표는 실질적인 웨어러블 헬스케어 시스템 관련 이론을 습득하고 학생 개인이 직접 실습을 진행해 봄으로써 (주당 이론 2시 간 실습 2시간으로 구성됩니다) 실제 헬스케어 필드에서 사용되고 있는 시스템을 이해하고 개발과정에 대해 살펴보며 학생개인의 아 이디어로 시스템을 업그레이드 할 수 있는 능력을 키우는데 있습니다. 실제 웨어러블 센서를 지급하여 이론과 실습을 진행할 예정이 며 직접 사용자가 학생 본인이 되어 습득된 데이터를 사용해보는 시간을 가질 것입니다. - 실제 의료기기로 인증된 웨어러블 센서의 구성을 이해한다. - 센서를 통한 생체 데이터 습득 방법과 습득된 데이터의 전처리 방법을 습득한다. - 전처리된 데이터를 이용한 특정정보 검출법에 관한 기술을 습득한다. - 데이터와 검출 정보를 바탕으로한 머신러닝 기술과 딥러닝 기술을 습득한다. - 데이터 무선통신 방식, 데이터 베이스 구축 방식을 이해한다.', '{"교수","습득한다","결과","웨어러블","기법을","데이터","직접","있는","딥러닝","습득된","기술을","검출","디바이스","적용해본다","대해","데이터의","관한","머신러닝","베이스","알아본다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('504150', '소셜비즈니스와스타트업', '경영대학', '경영대학', 0, 3, '전선', '곽진우', '이번 수업은 사회문제를 기반으로 비즈니스를 시도해보는 일련의 경험을 제공합니다. 본인의 진로와 창업 그리고 사회에 대한 진정성 있는 태도와 더불어 타인과의 비교가 아닌 자극으로 더 성장을 원하는 사람들이 함께 하기 희망합니다. 수업의 마지막에는 본인의 진로에 있어 창업에 대한 고민과 창업을 위해 고려해야하는 다양하고 기본적인 스킬들을 각자만의 방법으 로 익히고 떠나가길 희망합니다. 이번 기회로 지속적인 네트워크 형성도 기대합니다. 본인이 가진 역량과 자원을 바탕으로 사회문제를 비즈니스로 해결해보는 시도를 통해 전공지식간의 창의 융합 역량과 도전정신, 의 사소통능력, 문제해결 능력을 함양할 수 있음', '{"인터뷰","멘토링","공유","설정","검증","진단","사회문제","정의","고객","중간고사","어린이날","제품","채널","파트너에","전략","수익","개발","공유회","이번","사회문제를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('710045', '인공지능기술창업', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '이용석', 'o 본과목은 ① 스타트업 창업역량 제고와 함께 ② 기업근무시 현장 적응능력 및 업무역량을 향상시킬 수 있는 방향으로 강의 진행 - ICBM(IoT, Cloud, Big Data, Mobile Network) 및 AI 기술과 함께 경영학 이론 학습을 통해 융합적 지식 습득 o 4차산업혁명사회의 필수적 기술기반인 ICBM과 AI 기술에 대한 설명 - ICBM 기술의 개념과 특성 및 비즈니스 모델화 사례 - AI 기술의 단계적 발전과정 및 경영활용사례 설명 . 기호주의와 연결주의, 전문가 시스템(ES), 인공신경망(ANN) . Maching Learning(지도학습, 비지도학습, 강화학습)과 Deep Learning(CNN, RNN, GAN)의 진화 등 o System Thinking을 통한 사업구상, 수익모델 발굴, 마케팅 방안 등 창의적 아이디어 개발방법 학습 o 고객에게 어필할 수 있는 제품가치의 개발방법론 소개 o 소비자 니즈 등 관련 자료/정보 수집을 위한 시장 조사 및 자사의 역량 분석(SWOT 분석) 학습 o 비즈니스 모델 수립을 위한 구성요소 및 현 AI 시대의 New 수익 모델 사례 설명 o 가격 결정, 유통경로 설정 및 Promotion 전략의 이해 o ICBM/AI를 활용한 마케팅 패러다임의 고도화 사례(Data 기반의 개인맞춤형 마케팅) 설명 o 기업 경쟁력 제고를 위한 조직문화 육성방법(KMS:지식경영시스템 및 정부 지원프로그램의 활용 등 o 세계적 경영 전문가들의 경제/경영 이론에 대한 소개 o 국가직무능력(NCS) 등의 취업역량 강화방안 등에 관한 특강 등 - 기업/공공기관의 NCS 기반 채용절차 안내 및 취업 준비방안 - 자기소개서 작성, 필기/면접시험에 필요한 직무기초능력 지도 등 2. 교과 목표 ■ 교과목표 ① 스타트업 창업기회 발견 및 창업과정에 대한 전반적 지식 함양과 함께 기업 근무시 업무역량의 강화 - 4차 산업혁명시대의 기술적 핵심기반인 ICBM과 AI에 대한 이해 - 사업구상에 필요한 창의적 아이디어 개발 방법론 - 소비자 니즈를 충족시킬 수 있는 시장조사, 제품개발 및 자사의 역량 분석 방법론 - AI 시대에 있어서의 비즈니스 모델 수립 및 하이테크 마케팅방안 - 기업 성과 및 경쟁력 제고를 위한 조직 관리 - 연구개발 및 운영자금 조성을 위한 정부 지원프로그램의 활용 등 ② IT, ICBM, AI, 경영 및 정책 분야의 실무적 지식 학습을 통해 창업 및 직무현장에서의 적응능력 제고 - 기술과 경영을 동시 이해하는 종합적이고 실천적인 창업 능력 및 기업근무역량 육성 ③ 문/이과생에게 전공을 뛰어 넘는 융합적 역량 강화 지도 - 이과생의 경우에는 경영 이론과 분석기법을, 문과생에게는 IT, ICBM, AI 등 기술 분야의 지식 학습 ④ 순발력, 문제해결능력 등 함양 방법 지도 - 기술과 경영간 융합적 지식의 폭을 넓혀 업무 과제별 합리적, 효과적 해결책을 주도적으로 구현할 수 있는 역량 지도 ⑤ 대학 재학 중 취업역량 강화를 위한 자기주도적 준비방향 Guideline 제시 및 국가직무역량(NCS) 활용방법 지도 ※ 기업 및 공공기관 취업에 있어서 NCS기반 준비는 필수', '{"교재안","비즈니스","대면강의","대면","모델","개념과","소비자","지도","있는","창의적","경영","마케팅","패러다임의","기업","육성방법","관리","지식","설명","기술의","경쟁력"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('712030', '로봇개론', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '김항섭', '-본 교과목은 로봇의 정의, 종류, 구성요소를 이해하고 로봇 시장, 기술, 산업구조를 분석하여 로봇에 대한 종합적인 지식을 개관합니다. 수학적 모델 중심의 접근보다는 신 기술 동향과 산업 응용을 직관적으로 이해할 수 있도록 구성하였습니다. 특히, AI와 로봇의 융합이 가져올 미래 사회 변화를 탐구하고, 한국 로봇 산업의 전략적 방향을 모색합니다. -교육목표 .로봇의 정의, 역사, 종류, 핵심 구성요소(센서, 액추에이터, 제어기)를 정확히 설명할 수 있다 .로봇 산업의 가치사슬과 글로벌 시장 구조, 주요국 경쟁 전략을 이해한다 . 제조, 물류, 서비스, 헬스케어, 모빌리티 등 분야별 로봇 응용 현황을 파악한다 . 로봇 윤리, 규제, 정책의 쟁점과 한국 로봇 산업의 전략적 방향을 이해한다 지식 : 로봇에 대한 기초적인 용어 및 신기술 기획, 구현 사례를 통해서 로봇의 전체적인 지식을 개관한다. 기술 : 로봇에 적용되는 분야별 핵심기술을 세부적으로 이해할 수 있다. 태도 : 로봇을 시장, 기업, 기술을 알고 요소기술을 이해하므로써 산업적 측면에서 로봇전공의 기초적 방향성에 확신을 가지게 된다.', '{"로봇","로봇의","안다","조별활동","참여도","사례","이해한다","기술","미래","종류","서비스","영상","어떻게","돌봄","시장","산업","핵심","구성요소","글로벌","물류"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('714092', '사회적기업가정신', '경영대학', '경영대학', 0, 3, '전선', '강민정', '- 본 과목은 사회적 기업가정신에 대한 특성을 이해하도록 이론적인 내용을 다루는 동시에, 사회혁신과 관련하여 사회문제에 대한 혁 신 방안을 수립하고, 자신의 삶의 가치 속에서 이러한 혁신 방안을 실천해나갈 수 있는 각자의 사명과 action plan을 수립하기 위한 성찰적, 실천적인 경험을 제공한다. - 이러한 과정은 교수의 특정 주제에 대한 강의, 워크숍을 통한 학생 상호간 피드백, 실제 강의와 워크숍에 충분히 기여하는 데 있어 서 필요한 개인연구가 통합적으로 이루어질 때 가능하다. 학생들은 개인연구와 그룹 과제 수행을 통해, 사회혁신 방안을 수립하며, 사 회혁신 방안을 수립하는 과정에서 상호 피드백과 자기 성찰을 통해 사회혁신 방안과 자신의 소셜 미션을 정립해나간다. - 본 과목은 사회혁신을 실천하는 소셜 벤처인 Jump와 콰타드림랩 등과 연계하여 교육과정을 개발하고 진행하는 과목으로서, 현장 사회혁신가들의 참여와 만남 등이 이루어질 예정이다 - 본 과목은 하이브리드 유형인 e+프로젝트 과목으로 진행되며, 성적은 절대평가로 이루어진다. 월요일 수업은 강의실에서 워크숍과 토론을 진행하고, 수요일 수업은 주로 동 영상 강의가 upload되는 형식으로 진행된다. - 본 과목은 스타트업비즈니스전공 내의 나노디그리인 ''ESG스타업전공'' 과목 중 하나이며, ''사회적기업가정신'' 과목 이외에 ''ESG벤처 링 캡스톤디자인'', ''지속가능디자인 캡스톤디자인''을 수강하면 나노디그리를 이수할 수 있다. 1. 본 과목에서는 사회혁신과 사회적 경제에 대한 이론적 이해를 바탕으로, 사회문제 중 주목하는 사회 이슈에 대하여 어떤 사회혁신 의 대안을 제시할 수 있을지에 대하여 집중적으로 고민하고 대안을 모색한다. 그리고, 이러한 사회혁신 대안을 실현하기 위해서 각자 의 위치에서 어떤 실천을 해나갈 것인지에 대한 사명을 수립하는 것을 목표로 한다. 2. 이러한 과정은 교수의 특정 주제에 대한 강의, 워크숍을 통한 학생 상호간 피드백, 실제 강의와 워크숍에 충분히 기여하는 데 있어 서 필요한 개인 연구가 통합적으로 이루어질 때 가능하다. 학생들은 개인 연구와 그룹 과제 수행을 통해, 사회혁신 방안을 수립하며, 사회혁신 방안을 수립하는 과정에서 상호 피드백과 자기성찰을 통해 사회 혁신 방안과 자신의 소셜 미션을 정립해 간다.', '{"사회혁신","나의","어떤","사회적","삶의","대해","방안을","대하여","가치와","미래","사회혁신과","소셜","과목은","이러한","과정에서","협동조합","이해한다","방안","자신의","각자의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729020', '딥러닝', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '신철규', '- 주요 딥러닝 방법인 합성곱 신경망(CNNs), 순환 신경망 (RNNs), 그리고 Transformers 등에 대해서 다양한 예제를 통해 작동 원리를 학습한다. - Python을 활용한 실습을 동반하되, 이론과 수학적 접근을 기본으로 한다. - 다양한 분야에서 딥러닝의 활용의 이해를 높일 수 있다. - 딥러닝 주요 알고리즘에대한 이론적 기반과 원리를 습득하게 된다. - 프로그래밍을 통해서 딥러닝 알고리즘을 적용하는 방법을 배우고 실습하게 된다.', '{"딥러닝의","보충","딥러닝","개요","신경망","원리를","된다","중간고사","기간","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('714095', 'ESG벤처링캡스톤디자인', '경영대학', '경영대학', 0, 3, '전선', '강민정', '- 본 과목은 스타트업 전공을 통해 그동안 쌓아온 역량을 결집하여 실제로 ESG 기반 소셜 벤처 창업에 이르도록 하는 것이 목표이다. - 학생들은 실제 졸업 전 창업을 통해 소셜벤처가로서의 꿈을 현실화하고, ‘과정’으로서의 창업을 궤도에 올려 향후 창업 활동을 지 속 하거나, 혹은, 소셜 벤처 창업을 통해 스타트업 비즈니스 전공자로서 소셜 벤처 창업에 대한 이해와 경험 수준을 최대한으로 높혀 귀 중한 통 찰력과 문제해결 역량을 향상시킬 수 있다. - 이를 위하여, 소셜 미션 수립, 사업 아이디어 창출, 비즈니스 모델 수립, 고객과 시장 검증 등 체계적으로 창업 process를 밟게 되며, 이를 바탕으로 사업계획서를 작성하고 투자자에게 발표할 수 있는 수준의 IR (invester relation) Pitching을 준비하게 된다. - 본 과목은 스타트업비즈니스 전공 학생들 중 최고 학년의 과목이지만, 창업 주제를 명확히 가지고 있거나 창업 경험을 빠르게 가지 고싶 어하는 저학년 학생 혹은 소셜 벤처 창업에 관심있는 타 전공 학생들의 참가를 환영한다. - 본 과목은 하이브리드 유형인 플립러닝과목으로 진행되며, 절대평가가 이루어진다. 월요일 수업은 강의실에서 워크숍과 토론을 진 행하고, 금요일 수업은 주로 동영상 강의가 upload되는 형식으로 진행된다. - 본 과목은 소셜벤처 (주) 캐어유와의 협력을 통해 진행된다. - 본 과목은 스타트업비즈니스 전공을 통해 쌓아온 역량을 ESG 기반 창업에 결합하여 소셜벤처 (사회혁신기업) 창업에 이르도록 하 는 것이 목표이다.', '{"소셜","있다","소셜벤처","피드백","그룹과제","수행과","창업","검증","벤처","비즈니스","이를","바탕으로","고객","캔버스를","과목은","창업에","사업계획서를","사업계획서","창업을","창업팀"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729002', '인공지능융합기술개론', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '원동옥', '본 교과는 다양한 인공지능 모델 및 기술을 활용하여 원하는 응용 분야의 문제를 해결하는 능력을 키우는 교과목이다. 프로젝트 기반 학습(Project-Based Learning, PBL)을 수행하는 수업으로, 문제 제기, 문제 정의, 해결 방법, 실험, 결과 도출, 결과 분석, 결론에 이르는 과학적 문제 해결 과정을 훈련하고 학습한다 본 교과는 다양한 인공지능 모델 및 기술을 활용하여 원하는 응용 분야의 문제를 해결하는 능력을 키우는 교과목이다. 프로젝트 기반 학습(Project-Based Learning, PBL)을 수행하는 수업으로, 문제 제기, 문제 정의, 해결 방법, 실험, 결과 도출, 결과 분석, 결론에 이르는 과학적 문제 해결 과정을 훈련하고 학습한다.', '{"결과","프로젝트","도출","인공지능융합프로젝트","문제정의","작성","교과는","인공지능","모델","기술을","활용하여","원하는","응용","분야의","문제를","해결하는","능력을","키우는","교과목이다","기반"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('717042', '로컬임팩트비즈니스', '경영대학', '경영대학', 0, 3, '전선', '김용근', '- 춘천 및 강원지역을 중심으로 활동하는 로컬 창업가들의 실제 창업 경험을 탐구하고, 그들의 창업 스토리를 분석함으로써 로컬창업 생태계의 특성과 발전 가능성을 이해 - RISE 로컬창업큐브 연계 학생들이 직접 로컬 창업가를 인터뷰하며, 창업 과정에서의 의사결정, 자원활용, 지역관계형성, 그리고 지 속가능한 성장요인 등을 스토리텔링 형태로 정리 - 이 과정을 통해 학생들은 현장 중심의 창업 인사이트, 리더십, 지역문제 기반의 비즈니스 기획 역량을 동시에 함양하며 지역 창업가 로 성장할 수 있는 기반 마련 - 본 수업에 참여하는 학생들은 로컬 창업가들의 실전 경험을 분석하며 창업과정에서 도전, 회복탄력성, 지속가능성의 개념을 체득 - 창업 사례를 조사하고 인터뷰하여 내러티브형 창업 사례집을 기획하고 본인들이 작성한 사례집을 통해 실제 창업에 도전할 수 있는 역량 향상', '{"인터뷰","창업가","창업","일정","현장","설계","구성","워크숍","현장방문","팀별","자율","사진","촬영","기록","춘천","로컬","특강","질문","내러티브","기사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729015', '머신러닝프로그래밍', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '최종환', '- 본 과목은 파이썬 프로그래밍 기초가 다소 부족하거나 머신러닝을 처음 접하는 수강생들을 대상으로 하며, 단순한 이론적 이해를 넘어 데이터 전처리부터 모델 최적화까지의 전 과정을 scikit-learn 프레임워크 기반의 완성형 파이프라인으로 구현할 수 있는 실무 역량 확보를 목표함 - 데이터의 수집, 정제, 변환 과정을 NumPy와 Pandas 라이브러리를 통해 직접 코딩하며, 머신러닝의 핵심 메커니즘인 학습(fit)과 예 측(predict) 과정을 파이썬 논리로 치환하여 직관적으로 습득함. 특히, 모델의 일반화 성능을 담보하기 위한 교차 검증(Cross-Validatio n)과 과적합을 제어하는 정규화(Regularization) 기법을 실증적인 코드로 구현하며 모델의 안정성을 평가하는 안목을 기름 - 단일 알고리즘 활용에 그치지 않고, 특징 선택(Feature Selection) 및 그래디언트 부스팅(XGBoost, LightGBM) 등 최신 머신러닝 기 법의 내부 동작 원리를 분석하고 구현함. 이를 통해 데이터의 특성에 맞는 최적의 알고리즘을 선정하고, Grid Search를 활용하여 모델 의 성능을 극한으로 끌어올리는 최적화 프로세스를 내재화함 - 방대한 양의 실무 코드 작성(Live Coding)과 반복 실습을 병행하며, Scikit-learn의 Pipeline 객체를 활용함으로써, 단순 라이브러리 사용자를 넘어 스스로 문제를 진단하고 해결하는 능동적인 머신러닝 개발자로 성장하도록 유도함 본 교과목은 수강생들이 머신러닝의 핵심 알고리즘과 데이터 처리 메커니즘을 이해하고, 이를 Scikit-learn 프레임워크를 활용하여 견 고한 머신러닝 파이프라인으로 구현함으로써 실전 문제를 해결할 수 있는 실무 역량을 갖추는 것을 목표로 합니다. ● 지식 영역 - 데이터의 특성에 따른 지도 학습(회귀, 분류)과 비지도 학습(군집화, 차원 축소)의 차이를 명확히 구분하고, 각 알고리즘이 해결하고 자 하는 수학적 목적 함수와 최적화 원리를 설명할 수 있다. 2. 교과 목표 ■ 교과목표 - 교차 검증(Cross-Validation)을 통해 모델의 일반화 성능을 확인하고, Bias-Variance Trade-off 관점에서 과적합(Overfitting)을 진단 하며 이를 해결하기 위한 정규화(Ridge, Lasso)의 작동 기법을 코딩 논리로 해석할 수 있다. - 특징 선택(Feature Selection) 기법인 전진/후진 선택법의 차이를 이해하고, 데이터의 차원이 모델 성능 및 연산 복잡도에 미치는 영 향을 분석하여 효율적인 변수 조합을 도출할 수 있다. ● 기술 영역 - NumPy와 Pandas를 활용하여 원시 데이터(Raw Data)를 머신러닝 모델에 입력 가능한 형태로 정제 및 변환하고, 결측치 처리와 스 케일링 등 필수 전처리 과정을 독립적으로 수행할 수 있다. - Scikit-learn의 Pipeline 객체를 사용하여 전처리와 학습 과정을 하나로 묶어 자동화하고, GridSearchCV를 통해 하이퍼파라미터를 최 적화하여 모델의 성능을 극대화할 수 있다. ● 태도 영역 - 데이터셋의 특성을 다각도로 분석하여 문제 해결에 최적인 알고리즘을 선정하려는 데이터 기반의 의사결정 태도를 갖춘다. - 미니 프로젝트 및 경진대회를 통해 모델의 성능을 1%라도 더 높이기 위해 하이퍼파라미터를 세밀하게 조정하고 실험하는 집요하 고 분석적인 공학자적 자세를 갖춘다.', '{"제공되는","강의자료","참고","결과물","모델의","데이터","모델","성능을","머신러닝","검증","기법을","데이터를","과정을","회귀","있다","교차","활용하여","분류","성능","익힌다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('717043', '스타트업을위한디자인씽킹', '경영대학', '경영대학', 0, 3, '전선', '김성우', '이 과목은 스타트업 창업을 준비하거나 초기 단계에 있는 학생들을 대상으로 스타트업에서의 고객 경험(CX)이 사업 성공의 핵심 요 인임을 이해하고 실무에 적용할 수 있도록 설계된 실습 중심의 영어 강의이다. Design Thinking 방법론을 기반으로 상품의 사용자 경 험(UX, User Experience) 및 서비스 디자인(Service Experience Design)을 다루며, 이론 강의와 함께 텀 단위의 팀과제(term project)를 통해 학생들이 직접 고객 경험 전략을 수립하고 실행해볼 수 있는 기회를 제공한다. 특히 디지털 환경에서의 고객 접점 관리 및 CX 최적화 방법론을 중점적으로 다룬다. 이 과목의 목적은 스타트업 창업자가 제한된 자원 속에서도 차별화된 고객 경험을 창출하여 시장 경쟁력을 확보할 수 있는 실무 역량 을 배양하는 것입니다. 구체적인 학습 목표는 다음과 같습니다. 고객 중심적 설계(UCD - User-centered Design)의 사고(mindset)를 함양 Design Thinking 프로세스를 활용한 고객 문제 발견 및 해결 방법을 습득 UX/UI 디자인과 서비스 디자인의 핵심 원리와 도구를 이해 실제 스타트업 환경에서 적용 가능한 CX 전략을 수립하고 실행할 수 있는 능력을 함양', '{"팀활동","사용자","여부","작성","조사","고객","설계에","기반","정보를","제공하는","조사의","중요성과","결과물","수준","있는","주제","선정","완료","계획","스타트업"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729016', '파이썬프로그래밍', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '김은주', '본 교과목은 파이썬(Python) 프로그래밍의 기초문법부터 자료구조의 기본 사용 방법, 라이브러리 활용까지 단계적으로 학습하는 것을 목표로 합니다. 초기에는 파이썬 설치 및 개발 환경 설정과 기본 문법을 이해하고, 변수와 자료형, 출력 및 형 변환, 연산자, 조 건문, 반복문을 활용하여 기본 문제 해결 능력을 향상시키며 사용자 정의 함수와 전역변수 및 지역 변수의 인자 활용으로 함수형 프 로그래밍 기초를 다집니다. 리스트, 튜플, 딕셔너리, 집합 등 파이썬 기본 자료구조와 NumPy 배열까지 학습하여 데이터 처리 및 AI 활용의 기초 실무 능력을 갖추고자 합니다. --------------[주요 수업 방향]----------------- 1) 기초에서 응용까지 단계적 학습 구조 : 기본 문법-> 제어문-> 함수->자료구조-> 라이브러리 활용 2) 문제 해결 중심 수업 : 조건문과 반복문을 통한 알고리즘적 사고 강화 3) AI 도구를 연계한 학습 : AI 도구를 활용하여 연산자, 자료구조, 함수 설계와 같은 활동 포함 4) 실습 중심 수업 : 실습 자료 및 동영상 자료를 통한 반복 학습 구조 --------------[수업을 통해 얻을 수 있는 역량]----------------- 1) 전공 기술 역량 - 파이썬 기본 문법 및 프로그래밍 능력 및 조건문과 반복문을 이용한 프로그램 설계 능력 - 사용자 정의 함수 설계 및 활용 능력 - 리스트, 튜플, 딕셔너리, 집합 자료구조의 이해와 응용 능력 및 NumPy를 활용한 기초 데이터 처리 능력 - AI 도구와 프로그래밍을 연계하여 문제 해결에 적용하는 능력 2) 경험 기술 역량 - 실습 위주의 학습을 통해 문제 해결 경험 축적 - 팀 기반 학습을 통한 협업학습의 경험 및 결과물 공유를 통한 커뮤니케이션 역량 - 코드 디버깅 및 오류 해결 경험 - AI 활용 학습 경험을 통한 자기주도 학습 능력 강화 --------------[하이브리드 혼합형 수업 유형]----------------- 본 과정은 비대면과 대면수업의 하이브리드 혼합형으로 이루어지며, 팀원과의 개별 소통 능력을 향상시키고, 실습과 문제 해결 과 정을 통해 파이썬의 프로그램의 구조를 알고 응용 알고리즘을 설계하며 구현하는 전과정을 경험하게 됩니다. 따라서 [전공기술 역량] 과 [개발경험 역량]을 동시에 수행합니다. 부족한 이론 수업은 원격수업과 오프라인 수업으로 수행되며, 실습은 오프라인 수업으로 진 행됩니다. 1) 이론 : 온라인 수업 + 오프라인 수업 혼합 (중간시험 전후 총 9회 이상의 온라인 수업, 이외는 오프라인 수업으로 진행) 2) 실습 : 오프라인 수업, 총 15주(회)로 수업 3) 기타 : 팀(또는 개별)기반 수업, 문제 해결 과정을 위한 퀴즈와 수행 과제 경험 [지식 역량] - 파이썬의 기본 문법과 자료형에 대한 이론적 이해 - 연산자, 조건문, 반복문 등 제어 구조의 개념 이해 - 기본 자료구조(리스트, 튜플, 딕셔너리, 집합)의 특징과 차이 이해 - NumPy 배열 구조와 기본 연산 원리 이해 [기술 역량] - 파이썬 프로그램 작성 및 실행 능력 - 조건문과 반복문을 이용한 프로그램 구현 능력 - 사용자 정의 함수 설계 및 인자 활용 능력 - 자료구조를 이용한 데이터 처리 및 문제 해결 능력 - NumPy를 이용한 배열 연산 및 데이터 분석 초급 기술 [태도 역량] - 팀 구성을 통한 학습 능률 향상 - 팀 기반 문제 해결 및 코드 리뷰 참여 - 상호 피드백을 통한 학습 동기 증진 - 학생들 간 협업 능력 향상 및 책임감 있는 과제 수행 태도 - 협력적 의사소통과 존중의 학습 태도', '{"개수로","계산","있다","자료","온라인","실습수행과제","동영상","혼합형","강의와","대면","실습으로","문제해결","퀴즈","도구와","함께하는","연산자","반복문","파이썬","반복문을","데이터"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('717044', 'K-Food스타트업', '경영대학', '경영대학', 0, 3, '전선', '장우철', '본 교과목은 외식·K-Food 산업을 사례로 시장 분석, 운영 구조, 마케팅 전략, 손익 모델을 종합적으로 이해하고, 이를 개인 사업계획서 형태로 논리적으로 정리할 수 있는 경영학적 사업기획 역량을 함양하는 것을 목표로 함 본 교과목은 외식·K-Food 산업을 사례로 시장 분석, 운영 구조, 마케팅 전략, 손익 모델을 종합적으로 이해하고, 이를 개인 사업계획서 형태로 논리적으로 정리할 수 있는 경영학적 사업기획 역량을 함양하는 것을 목표로 함', '{"마케팅","데이터","운영","퍼포먼스","시장","전략","작성","매장","실제","기반","프로세스","현장","조리","성공사례","사업계획서","아이템","외식","구조","국내","서비스"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('717046', '스타트업투어링', '경영대학', '경영대학', 0, 3, '전선', '곽진우', '- 지역의 지속가능성을 높이기 위해서는 양질의 일자리가 만들어져야하며, 이를 위해 글로컬 사업의 일환으로 춘천을 중심으로 한 창 업생태계 조성을 위해 Station C 브랜드 런칭 - 춘천 각 지역에 Station C 브랜딩 창업공간을 조성하였고, 다양한 분야의 창업가들이 입주 및 활동하고 있어서 각 전공분야와 연계 된 다양한 창업가 Pool 조성(Ex, 춘천바이오산업진흥원, 강원정보문화산업진흥원, 커먼즈필드, 근화동396 등) - 본 교과목을 통해 Station C 라벨링된 창업 공간을 직접 방문하여 대표 창업가들을 만나보고 해당 전공을 활용한 창업 사례를 학습 하고 아이디어를 구체화할 수 있는 기회 제공 더하여 여러분들이 궁금해하는 진로와 창업에 대해 서로 이야기하고 함께 각자의 방향을 존중하는 시간을 만들어가고자 합니다. - 다양한 창업 사례 학습을 통해 창업에 대한 관심을 높이고, 본인 전공에 기반한 창업 아이디어를 구체화할 수 있도록 해당 분야 성 공 노하우 제공 및 창업 성공 가능성 향상 - Station C를 기반으로 한 다양한 창업 지원 인프라, 프로그램에 대한 이해를 통해 창업 동아리 참여 및 학생 창업에 도전할 수 있는 인재 양성', '{"창업","탐색","인프라","창업가","방문","팀별","인터뷰","탐방","사례","프로젝트","공유","선배","만남","변동가능","현장","진행상황","춘천","커먼즈필드","근화동","대표"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729023', '뇌공학입문', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '최가영', '본 과목은 뇌공학과 관련된 기초 지식을 학생들이 이해할 수 있도록 하는 것을 핵심 목표로 하고 있으며, 수강하는 학생은 다음의 내용을 본 수업을 통해 학습하게 된다. - 뇌공학 개요 - 뇌공학과 기계학습 - 뇌-컴퓨터 인터페이스 등 뇌공학과 관련된 전반적인 내용을 공부하여, 학생들이 인공지능 시대에 필요한 뇌공학에 대한 감을 잡도록 한다. 뇌공학의 개념을 습득하고, 뇌공학 관련 데이터 및 분석을 직접 진행해봄으로써 실용적 지식을 학습하고 활용도를 높임', '{"대표","패러다임","뇌신호","응용","뇌영상","뇌공학과","관련된","지식을","학생들이","내용을","뇌공학","발생원리","측정","특징의","수면","단계","분류","치매","예측","중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506001', '융합전공진로지도', '자연과학대학', '자연과학대학', 0, 1, '공통전선', '김헌기', '- 자연과학대학에 무전공으로 입학하는 65명 (2026학년도 기준)에 대하여 2학년 진급시 전공 및 복수전공의 선택을 위한 기초정보를 제공 - 자연과학대학 6개 학과와 3개 전공에서 선발된 교과목 담당교수가 학기 당 최소 1회 무전공입학 신입생에 대하여 해당 학과 또는 전공의 교과과정 및 교과의 특성을 소개 - 자연과학대학에 무전공으로 입학하는 학생들에 대한 자연과학대학의 특성 이해 - 해당 학생들이 주전공 및 복수전공을 선택하기 위하여 필요한 자연과학대학 내 각 학과 및 전공 에 대한 상세한 교과정보의 습득 - 자연과학대학 내 각 학과 및 전공을 선택하였을 때 선택가능한 직업군 등 진로에 대한 정보습득', '{"특강","학과","전공","전공의","대표교수","또는","내부강사","초청강사","설문조사","학년","진급시","자연과학대학","자연과학대학에","무전공으로","입학하는","대하여","교과목","해당","자연과학대학의","중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729027', '의학용어의이해', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '임만섭', '의료AI 전공에 필요한 의학, 의료에 대해 이해할 수 있다. AI를 포함한 여러 분야의 미래 의료 변화과정을 전반적으로 이해하고 예측할 수 있다. 의학용어를 익힘으로써 함께 연구, 개발해 나갈 의료진과의 의사소통을 원활하게 할 수 있다. 의학, 의료에 대해 시스템적으로 이해할 수 있다. 의학용어를 익힘으로 다른 의료진과의 공동연구에 원활한 소통을 할 수 있다. 다양한 분야의 미래의학 변화 추세를 이해하고 예측할 수 있다. 의료 AI 관련한 의료/연구윤리를 이해할 수 있다.', '{"의학용어","있다","의료생명윤리","의료","영상의학","이해할","의학","의료에","대해","분야의","이해하고","예측할","의학용어를","의료진과의","의사됨의","의사의","진로","내시경","호흡기","신경계"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729029', '건강과질병의측정', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '최용준', '학생은 이 수업을 통하여 역학(epidemiology)의 기초를 습득한다. 역학은 특정 인구 집단에서의 건강 관련 상태의 분포 및 결정요인 을 연구하고 해당 연구 결과를 건강 문제 관리에 적용함으로써 의학 발전과 건강증진을 촉진하는 견인차 노릇을 하여 왔다. 학생은 역학 지식의 바탕 위에서 의료 인공 지능 개발과 활용에 보탬이 되는 통찰력을 얻을 수 있을 것이다. - 역학의 개념과 쓰임새를 설명할 수 있다. - 건강과 질병 현상 측정에서의 기본 개념을 설명할 수 있다. - 주요 건강 지표를 산출할 수 있다. - 표나 그래프를 적절하게 작성할 수 있다. - 질병의 원인을 규명하는 주요 연구 종류의 특징을 열거할 수 있다. - 역학에서의 증거의 수준이라는 개념을 설명할 수 있다.', '{"있다","설명할","수업일","슬라이드","자료","퀴즈","주교재","개념을","방법을","역학의","특징을","역학","질병","해당","의료","부교재","사항","없음","중간고사","질환"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('768003', '의료영상처리', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '정태경', '본 교과목에서는 4차 산업혁명의 핵심기술인 인공지능을 통하여 자기공명영상장치(Magnetic resonance imaging), 초음파스캐너(Ultr asound scanner), CT(Computerized tomography) 등 각종 영상진단기기의 출력 영상에 대한 기초 지식과 이 영상을 해석하고 처리하 는 다양한 방법의 원리를 학습한다. 영상장비에 사용되는 영상재구성법에 대해서 이해하고, 각종 의학영상시스템으로 얻어진 영상을 처리하는 방법을 공부한다. ○ 본 교과목은 AI의료융합전공의 3수준의 전공 선택과목으로서 선수과목으로 사전에 디지털 영상처리를 수강한 학생에게만 수강을 권장한다. 본 강좌를 통하여 일반적인 디지털 영상처리에서 이야기하는 사항과 의료영상에서 이야기하는 사항을 구분하고 AI의료융 합과정에서 꼭 알아야 하는 사항을 다루기로 한다. 이에 따라 전공선택 과목 중에서 필수적인 사항을 숙지하고 수강하여야 한다. 본 교과목은 인공지능의 핵심적인 지식과 활용 방법을 습득하는 과정에서 자기공명영상장치(Magnetic resonance imaging), 초음 파스캐너(Ultrasound scanner), CT(Computerized tomography) 등 각종 영상진단기기의 출력 영상에 대한 기초 지식과 영상을 이해 하고 디지털 영상처리 방법론을 이해 한다. 본 강좌를 통하여 일반적인 디지털 영상처리에서 이야기 하는 사항과 의료영상에서 이야 기 하는 사항을 구분하도록 한다.', '{"디지털","영상","처리","사항을","한다","영상처리","필터링","주파수","도메인","영상분할","통하여","각종","지식과","영상을","하는","자기공명영상장치","영상진단기기의","출력","영상에","방법을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507004', '단백질생화학', '자연과학대학', '자연과학대학', 0, 3, '전선', '김대원', '모든 생명체에서 진행되는 생명 현상을 분자 또는 원자 수준에서 연구하는 학문임. 생명 현상을 분자 수준에서 규명하는 분자생물학의 방법론이 거의 모든 생명과학의 영역에서 기본 도구로 사용됨에 따라 화학과 생 물학을 전공하는 학생에게 필수적인 학문임 DNA, 단백질, 지질 등 생명의 근본이 되는 유기물질에 대한 이해를 하는 학문임 생명 현상을 조절하는 분자들에 대한 화학적 연구 세포 구성의 구조와 기능을 이해하고, 이의 근간이 되는 생명체 내 주요 생물학적 저분자와 거대분자들(small and biological macrom olecules)의 역할, DNA 유전 정보의 구성과 운영 및 진화 과정에서 변이와 선택의 역할 규명 생체 내 주요 생물학적 거대분자들은 탄수화물(carbohydrate), 단백질(proteins), 지방(fat), 핵산(nucleic acid: RNA, DNA) 등 네 가지 로 분류되며, 생화학에서는 이들 생물학적 거대분자를 생체에서 분리, 정제하고 이들의 기능을 규명 최근의 연구 경향은 DNA, RNA, 단백질의 합성, 세포막과 물질수송, 신호전달 체계 등 세포내 분자들의 모든 기능과 역할 규명', '{"동영상","모든","생명","현상을","학문임","생물학적","역할","규명","분자","수준에서","단백질","되는","기능을","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729030', '인체의구조와기능', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '서상원', '학생들은 인체의 구조와 기능 과정을 마치면 다음과 같은 일을 할 수 있어야 한다. 1. 기초의학에 필요한 기본적인 생물학적 현상과 기전을 이해하고 설명할 수 있다. 2. 기초의학과 관련된 기초이론을 설명할 수 있다. 3. 의학과 관련된 기본 용어를 설명할 수 있다 의료인공 지능학부 학생들의 기본적인 의학지식 습득', '{"이해한다","중간고사","인체의","구조와","과정을","한다","이해하고","설명할","있다","기본적인","관련된","우리몸의","기능에","관한","오리엔테이션","신경계통","신경계통을","내분비","계통을","순환계통을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507007', '기초생화학실험', '자연과학대학', '자연과학대학', 0, 2, '전선', '이찬희', '기초 생화학 과목에서 배우고 있는 지식을 실험에 적용하여 실험과정을 통해 기초 생화학 과목에서 배우고 있는 지식을 실험에 적용 하여 실험과정을 통해 실험방법, 실험의 원리, 실험 기구 사용법 등 직접 수행하여 이해하는 것을 목표로 한다. 이를 쉽게 이해하기 위 한 예로 기초적인 시약의 pH 측정법과, 생화학에 관련된 단백질 및 DNA등을 이용하여 이론과정을 직접 수행해보도록 한다. 이러한 실험이론과 실습을 통하여, 후에 취업을 하고자 할 때 여러가지 이론과 실험을 할 수 있는 기초적인 능력을 기르는데 목적을 두고 있 다. 생명과학의 기본이 되는 생화학에 대한 기초시험을 통하여 생체고분자인 단백질, 탄수화물, 지질, 핵산 등에 대한 특성 및 성질을 파 악하는데 목표가 있다.', '{"중간고사","배우고","특징을","스마트리드에","업로드된","강의자료","실험에","있는","실험의","실험","생화학","과목에서","지식을","실험과정을","직접","한다","기초적인","생화학에","단백질","통하여"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('729033', '인공지능데이터베이스', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '정일택', '- 인공지능(AI)과 데이터베이스(DB)에 대한 개념 - 인공지능 데이터베이스 발전 방향 - 인공지능 데이터베이스 개발 도구 - 데이터베이스에서 AI를 활용한 데이터 분석 - 빅데이터 분석을 위한 AI 알고리즘 - AI를 활용한 데이터베이스 관리 자동화 인공지능(AI) 데이터베이스를 활용한 데이터의 과학적 분석방법과 의사결정을 위한 시각화에 대한 지식을 습득하고 개발할 수 있는 능력을 배양한다', '{"주교재와","슬라이드","데이터베이스","인공지능","데이터","문법","만들고","사용하기","관계","모델","개체","만들기","내장함수와","방향과","개발도구","방향","활용한","과목에","전반적인","발전에"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507009', '유전생화학', '자연과학대학', '자연과학대학', 0, 3, '전선', '신민재', 'Mendel의 유전법칙에서 시작된 유전연구에 관한 정보가 거의 폭발단계에 이르렀다. 세포가 유전정보를 어떻게 저장하고 사용하며 전달하는가에 대한 정보가 계속해서 증가하고 있다. 또 지금까지도 생화학자들과 분자생물학자들은 유전정보의 본질적인 핵산의 기 능을 규명하고 있다. 재조합DNA 기술은 임상실험과 치료는 물론 생물체 내부의 상호작용에 관한 연구를 가능하게 하였다. 예를 들어 결함유전자를 정상유전자로 치환하는 유전자 치료법이 현재 활발하게 임상실험에 응용되고 있다. 현재 이러한 연구의 정확한 결과 를 예측하기는 어렵지만 그 치유 방법은 매우 획기적인 접근 방법이로서 암을 비롯한 유전병 치유에 새로운 전기를 만들 것임에 틀림 이 없다. 생명활동 또는 생식에 필요한 정보는 안전하게 저장되어 정확하고 유용하게 사용되어야 한다. 또한 정보가 유용하게 사용되 려면 효과적으로 전이될 수 있어야 한다. 생물은 이 문제를 두 분자 영역, 즉 DNA와 단백질(protein)을 분할 함으로서 해결하였다. D NA는 정보저장과 복제(duplication)를 극대화하는 구조적 특성을 갖고 있으며, 단백질은 정보전이를 극대화하는 다양하고 유연한 3 차 구조를 갖고 있다. DNA정보가 사용되는 모든 과정은 단백질에 의해 수행되는 분잡한 일련의 과정들로 이루어져있다. 이 강의에서 는 유전자인 DNA와 RNA의 구조 및 특징에 대하여 공부하고 DNA 복제(replication), DNA repair and recombination, Transcription, T ranslation(Protein synthesis), Gene expression and regulation등을 심도있게 강의하며, 또한 강의의 대한 효율적인 이해를 돕기 위한 예로 위의 여러가지 물질들의 특징이나 구조에 문제가 야기되었을 때 나타나는 생체질환이나 유전병에 대해서도 심도깊게 논의한다 . 생화학(Biochemistry)은 생명현상을 분자 수준에서 연구하는 학문이다. 본 강의의 목표는 오랫동안 생화학자들이 연구한 것을 근간으 로 생명현상과정을 화학적, 생물학적, 물리적 원리를 이용하여 이해하는 것을 목표로 한다. 특히 생명현상의 central dogma 라고 할 수 있는 DNA 복제(replication), DNA repair and recombination, Transcription, Translation(Protein synthesis), Gene expression and r egulation 공부를 통하여 생명현상을 분자수준에서 충분히 이해하는데 교육목표가 있다', '{"공부","저자","유전생화학","최수영","지음","중간시험","학기말시험","칠판에","적으면서","설명","있다","정보가","한다","복제","관한","현재","유용하게","또한","분자","극대화하는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('768001', '의료데이터베이스', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '원동옥', '본 과목은 데이터 모델과 SQL 구문의 연관성을 위해, 데이터 모델링의 기본지식을 바탕으로 데이터 모델을 이해하고, 데이터베이스 와 SQL의 기본 문법, 데이터 출력을 위한 SELECT 문의 기본 문법, 함수, 조인, 서브 쿼리등에 배울 예정임. 한 단계 나아가 데이터를 직접 조작하는데 사용되는 DML(Data Manipulation Language) 과 DDL (Data Define Language)의 핵심요소를 학습함. 또한, 의료현 장에서 사용되는 의료데이터 베이스에 대해 학습하고, 실제 보건의료 청구 자료 및 의료 데이터베이스를 활용하여 SQL의 문법들을 적용함으로써 의료데이터베이스에 대하여 활용성을 높이고자 한다. 사용되는 프로그램은 My-SQL. R, SAS등을 이용할 예정이다. 본 수업을 통해 데이터베이스와 SQL 쿼리 에 대한 기초 문법을 습득하고, 데이터를 출력하기 위해 사용되는 명령어인 SELECT문의 기 초 문법, 함수, 조인, ERD, 서브쿼리등을 자유롭게 적용할 수 있다. 또한, 데이터를 직접 조작하기 위한 DML과 DDL의 핵심요소를 학습하고, 이를 활용하여 실제 의료 데이터베이스에 대한 실습을 통해 복잡한 테이블 간의 연간관계에서 정확한 값을 도출 할 수 있을 것이다.', '{"데이터","문법","퀴즈","문법을","실제","데이터를","테이블","이해합니다","가져오기","조건에","의료데이터베이스를","데이터베이스","자유롭게","활용하여","학습합니다","문법들을","사용되는","의료","설치","하기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507114', '세포배양및세포조직공학', '자연과학대학', '자연과학대학', 0, 2, '전선', '이근욱', '본 강좌는 세포생물학 연구에서 사용되는 실험 기법들을 실습하는 과목으로서 동물세포배양, 세포주기 및 세포사멸 측정, 현미경 및 유세포 분석, 유전자 과발현 등 기초부터 첨단에 이르는 다양한 세포생물학적 실험 기법을 경험시키고자 함 동물세포 배양과 세포생물학 실험 및 분석 기법을 경험함으로써 이론 과목에서 배운 사실을 검증하는 실험을 디자인하고 실험 데이 터를 분석하는 능력을 배양함', '{"실험","중간고사","세포생물학","기법을","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('773001', '로봇신호처리', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '신철규', '- 로봇에서 신호처리의 역할 및 중요성을 이해한다. >여기서 ‘로봇’은 사람의 일을 대신 수행하는 모든 기계를 말함 (ex. 청소기, 자동차, 공장자동화 로봇 등) >선수과목인 ‘신호처리’에서 배운 이론들이 실제 로봇 공학에 어떻게 적용되는지 학습 - 신호처리의 이론적 접근을 기본으로 하되 관련된 SW 기술에 대한 실습을 동반한다. >신호의 시간 및 주파수 분석: 기초 이론 및 적용분야 실습 >디지털 필터: 기초 이론 및 적용분야 실습 >칼만 필터: 기초 이론 및 적용분야 실습 수업시간에 배운 신호처리 이론 및 SW 기술을 적용 및 심화하여 연구 결과물을 만들어 본다. - 수업시간에 배운 신호처리 이론 및 SW 기술을 적용 및 심화하여 연구 결과물을 만들어 본다. - 로봇 산업에서 필요로 하는 기술 분야를 이해한다. - 특히, 신호처리가 로봇 공학에 어떻게 활용될 수 있는지 이해한다. - 관련된 수학/공학적 지식을 습득하고, 심도 있는 이해를 통해 사고하고 연구할 수 있는 실력을 갖춘다.', '{"신호의","시간","주파수","프로젝트","칼만필터","로봇","디지털필터","보충","설계","이해한다","신호처리","배운","적용분야","신호처리의","공학에","어떻게","관련된","필터","수업시간에","기술을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507215', '유전자조작론', '자연과학대학', '자연과학대학', 0, 3, '전선', '이선민', '이 과목은 현대 분자유전학과 생명공학의 핵심 개념을 통합적으로 학습하는 전공 과목으로, 유전자의 구조와 기능, 재조합 DNA 기술 , 유전자 발현 조절, 및 응용 생명공학 기술의 원리와 실제적 응용을 다룬다. 학생들은 DNA, RNA, 단백질 간의 정보 흐름을 이해하고, 이를 기반으로 유전자 조작, 발현 시스템, 단백질 생산, 및 생명공학적 응용까지 폭넓게 탐구한다. 실험 방법론 강의. ** AI튜터 결합 과목- 한림대 AI튜터 활용 및 퀴즈 풀이 필수 1. 유전자의 구조·기능·조절에 대한 분자적 이해를 확립한다. 2. 재조합 DNA 기술의 원리와 응용을 습득한다. 3. 생명공학 실험기술(PCR, 클로닝, 발현, 정제, 분석)의 기초를 이해한다. 4. 유전자 조작 기술의 의학적·산업적 응용 사례를 비판적으로 분석한다.', '{"유전자","발현","기술의","유전자의","기능","재조합","응용","생명공학","원리와","응용을","단백질","조작","튜터","중간시험","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507311', '세포생물학', '자연과학대학', '자연과학대학', 0, 3, '전선', '이근욱', '세포생물학은 생명체의 기본단위인 세포의 구조와 기능에 대해 학습하는 의생명과학 분야의 기본 과목으로서, 본 강좌에서는 세포 대사, 세포 구성 물질의 구조와 기능, 유전자 발현 조절, 세포막 및 세포소기관의 구조와 기능, 세포 분열과 사멸 등의 이해를 통해 의 생명과학의 기초를 다지고자 함 세포의 구조와 기능에 대한 이해를 통해 의생명과학 관련 심화 강좌 수강에 필요한 기초를 제공하고, 졸업후 관련 전문 분야를 선택 하는 가이드라인을 제시함', '{"구조와","중간고사","세포","세포의","기능에","의생명과학","기능","이해를","기초를","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('904401', '의료인공지능', '정보과학대학', '정보과학대학', 0, 3, '공통전선', '최가영', '현재 인공지능 전문 인력은 대부분 이미지, 자연어처리 등의 분야에 집중되어 있어 의료 기반의 인공지능 전문가는 극소수에 불과함 . 그러나 의료 및 바이오는 차세대 핵심기술로 부상하고 있으며,특히 팬데믹 이후 디지털의료·헬스케어에 대한 관심과 필요성이 더욱 부각되고 있음. ''의료인공지능''은 인공지능에 대한 개괄적인 이해와 더불어 의료 분야에서 인공지능이 어떻게 활용되는가를 이해하고, 기술의 변화, 시장의 변화 속에서 무엇을 준비해야 하는지를 종합적으로 학습하고자 함 의료인공지능은 개인의 건강상태 모니터링을 비롯한 의료 진단 및 치료 보조 시스템, 플랫폼 개발 등 다양한 의료 데이터를 활용하는 분야에서 인공지능 기술의 활용 수준을 이해하고, 실제 데이터를 분석하며 인공지능 기술의 활용 개념을 습득한다.', '{"인공지능","데이터","의료","개괄적인","배포","기반","인공지능의","기술의","실제","분야에서","이해하고","변화","데이터를","의공학개론","의료공학에","의료와","융합의","필요성","향상을","머신러닝"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507317', '기초생화학', '자연과학대학', '자연과학대학', 0, 3, '전선', '이찬희', '1. 세포, 핵산 (DNA, RNA), 단백질, 바이러스, 박테리아 등과 생명체와 관련된 모든 것들을 생화학적 관점으로 배움. 2. 각 주제별로 관련된 내용 (구조, 기능, 조절과정, 관련질병, 최신활용법 등)을 모두 배울 수 있음. 3. 우리과를 졸업하려면 꼭 알아야 하고, 이해만 잘 하면 오랫동안 기억할 수 있는 부분을 중심으로 강의. 생명체를 구성하는 물질들의 구조와 기능, 조절 기전 등을 다양한 각도에서 배운다.', '{"단백질","세포생물학","세포분열","종류","원핵생물의","합성","핵산","바이러스","분자생물학","관련된","기능","원핵세포","진핵세포","유전정보","아미노산","이용한","유전자","변형","복제","전사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205201', '회계입문', '경영대학', '경영대학', 0, 3, '전선', '문성훈', '본 과목은 경영대학 신입생을 대상으로 회계의 기본 개념과 절차를 체계적으로 학습하는 입문 과목이다. 회계정보의 역할과 기본 요 소를 바탕으로 거래분석, 분개, 전기 및 시산표 작성 과정을 단계적으로 다루며, 수익·비용의 기간귀속, 수정·마감 절차, 재고자산·감가 상각·부채와 자본·현금흐름의 기본 개념까지 학습한다. 이를 통해 대차대조표와 손익계산서 중심의 회계시스템 작동 원리를 이해하고 기본적인 거래의 기록과 해석 능력을 기른다. 본 교과목의 목표는 회계의 기본 개념과 구조를 이해하고, 기업의 거래가 회계정보로 기록·요약되는 과정을 체계적으로 습득하는 데 있다. 이를 위해 회계의 기본 요소(자산·부채·자본·수익·비용)를 정확히 구분하고, 거래분석？분개？전기？시산표 작성의 흐름을 단계 적으로 학습한다. 또한 수익과 비용의 기간귀속, 수정·마감 절차, 재고자산·감가상각·부채와 자본·현금흐름의 기초 개념을 통해 재무제 표가 기업의 재무상태와 경영성과를 어떻게 반영하는지 이해하도록 한다. 궁극적으로 학생들이 회계정보를 읽고 기본적인 거래를 기 록·해석할 수 있는 기초 역량을 갖추는 것을 목표로 한다.', '{"흐름","절차","거래분석","분개","전기","시산표","기간귀속","마감","연습","수정분개","회계의","자본","해석","오개념","교정","수익","비용의","수정","재고자산","부채와"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205203', '인적자원관리', '경영대학', '경영대학', 0, 3, '전선', '김용근', '본 교과목은 AI 시대의 인적자원경영(HRM)과 하이브리드 워크플레이스에 대한 종합적인 이해를 목표로 합니다. "K-HRM: AI 시대를 선도하는 인적자원경영"과 "HR 메가트렌드 하이브리드 워크플레이스" 두 책을 기반으로, AI 기술의 발전이 HRM 에 미치는 영향과 하이브리드 근무 환경에서의 인적자원 관리 전략을 학습합니다. 또한 ''쿠팡 AI물류융합인재 나노디그리'' 과목으로 선진 물류기업의 인적자원관리 이슈를 체험하고 학습할 수 있는 기회를 제공합니다 . - AI 시대의 HRM 변화와 주요 개념을 이해하고 설명할 수 있다. - 하이브리드 워크플레이스의 특성과 관리 방안을 파악하고 적용할 수 있다. - AI 기술을 활용한 HRM 전략을 수립하고 평가할 수 있다. - 물류산업의 변화를 이해하고 근무 환경에 맞는 인재 관리 및 조직문화 구축 방안을 제시할 수 있다.', '{"하이브리드","팀별","워크플레이스","시대의","관리","인적자원관리","개념과","환경에서의","쿠팡","워크플레이스의","인적자원경영","근무","있다","중요성","디지털","변화","기업","이슈","성과관리","기반"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205204', '기업과사회', '경영대학', '경영대학', 0, 3, '전선', '한재훈', '본 과목은 최근 강조되고 있는 기업의 존재이유에 대해서 기존의 주주중심의 성과지향관점과 다르게 사회구성원으로서의 역할관점 에서 살펴보고자 한다. 특히 ESG활동, 사회적 책임, 윤리경영, 투명경영 및 지속가능경영 등 기업의 지속경영의 기본을 이해하고 학습 하는 것을 기본 목적으로 한다. 사회적 책임을 수행하며 동시에 기업의 성과를 기반으로 하는 지속 가능한 성장을 추구하는 바람직한 기업의 역할에 대해 연구한다. 기업 윤리, 투명경영 및 다양한 이해관계자와의 관계를 다루어 기업의 역할과 사회적 정당성의 문제 에 대한 이해의 폭을 넓히고자 한다. 마지막으로 기업에게 요구되고 기업가치의 핵심요소로 주목받고 있는 ESG(Enivronment, Society , Governacne)에 대하여서도 다루고자 한다. 기존의 기업은 존재이유를 이익창출에만 집중하는 구시대적 사고를 확장하여 디지털과 AI시대에 부합하는 기업의 사회 구성원으로서 존재이유를 생각하고 또한 바른 경영, 미래지향적인 기업활동에 대해 고민하는 시간을 갖고자 한다. 무엇보다도 본 수업은 학생 중심으로 발제와 토론을 통해서 자기주도적 학습으로 미래지향적 강의방식을 적용하고자 한다. - 지식 : 기업과 사회와의 관계를 통한 기업의 존재이유와 미래지향적 역할에 대해 이해할 수 있다. 최근 시장에서 주목받는 ESG 개념에 대한 이해와 기업사례에서 확인할 수 있다. AI 및 디지털 중심의 사회에서의 변화된 기업의 할일과 의무에 대한 생각해 볼수 있다. - 기술 : 주제별 필요한 자료를 탐색하고 취합한 자료를 정리하여 내용을 분석할 수 있다. 팀별로 학습한 내용을 다른 학우들에게 효과적으로 전달 하는 역량을 키울 수 있다. 자신의 생각이나 주장을 논리적으로 발표할 수 있다. - 태도 : 경청하고 자신의 생각 또는 주장을 예의있게 전달하는 미래지향적 자세를 지닌다. 팀별로 학습하고 팀내 의견을 조율하고 정리하는 태도를 익힌다. 팀활동 시 윤리적인 태도를 갖춘다.', '{"있다","질문","기업의","개인과제","횟수","수준","조별발표","기업과","이해하고","대해","사례","기말프로젝트","생각해","한다","관계를","이해할","기업사례","조별","따른","변화"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507510', '암생물학개론', '자연과학대학', '자연과학대학', 0, 3, '전선', '이근욱', 'This is a didactic lecture to introduce general concepts in initiation, progression, invasion, and metastasis of tumor. Topics range from molecular and cellular biology of cancer (especially on oncogenes and tumor suppressor genes) to novel concepts such as c ancer stem cells and targeted therapeutic approach. 1. To gain a basic understanding of the differences between normal and cancerous cells, and the progression from a normal cell to a neoplastic tumor cells 2. To understand fundamental principles about the mechanisms that underlie carcinogenesis of several different cancers 3. To understand the cellular and molecular basis of current strategies for cancer prevention and treatment', '{"주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205303', '마케팅원론', '경영대학', '경영대학', 0, 3, '전선', '김현식', '▷ 강의목적: 학습자가 마케팅의 기본 개념과 원리를 이해한 후 그 소양을 현실세계의 문제해결상황에서 발휘할 수 있도록 한다. 현 실세계의 문제해결상황 중에서 신제품 마케팅 기획 상황에 주안점을 두도록 한다. 신제품기획을 창업기획으로 연결하는 훈련을 한 다. ▷ 강의개요: 학기 전반에는 제품, 서비스, 가격, 유통, 촉진 등 마케팅의 주요 분야에 대한 기본 개념과 원리 습득에 주력하고, 학기 후반에는 신제품마케팅계획서 작성을 통해 마케팅의 개념과 원리를 현실세계의 문제에 적용해보는 현실적용력 함양에 주력한다. 신 제품기획을 창업기획으로 연결함으로써 지식재산이나 창업훈련 등 학습자 스펙 확장도 도모한다. 신제품기획과정에서 생성형AI를 적 극 활용할 수 있다. 학기 전반에는 제품, 서비스, 가격, 유통, 촉진 등 마케팅의 주요 분야에 대한 기본 개념과 원리를 습득한다. 학기 중반에는 창업으로 연결할 수 있는 개인별 신제품마케팅기획서를 작성&제출한다. 학기 후반에는 팀기반 신제품마케팅기획서 작성을 통해 마케팅의 개념과 원리를 현실세계의 문제에 적용해보는 현실적용력을 함양 한다.', '{"마케팅","신제품","프로젝트","완성","기획서","기획","마케팅의","촉진관리의사결정","시장세분화와","표적시장선정","포지셔닝","중간시험","학기","개념과","원리를","강의계획서","교재","핵심","개념들","제품관리의사결정"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('507512', '캡스톤디자인-의생명과학', '자연과학대학', '자연과학대학', 0, 3, '전선', '이찬희', '1. 한 학기 동안 연구실 생활을 수행하며 프로젝트를 진행함 2. 연구실에 따라 적절한 프로젝트를 부여받고 진행할 수 있으며, 연구실 소속 멤버들과의 교류를 통해 인맥을 쌓아갈 수 있음 3. 미리 교수님과 컨택하여 연구실을 결정한 후에 수강신청 해야함 연구실 생활을 배우고 본인의 적성에 맞는 연구를 개별적으로 진행함.', '{"연구실","생활","생활을","프로젝트를","진행함"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205414', '시장조사론(종합설계)', '경영대학', '경영대학', 0, 3, '전선', '김현식', '시장조사론은 마케팅 관리자의 의사결정 직전에 요구되는 데이터 수집, 분석, 해석을 위한 절차와 방법을 배우는 과목이다. 본 과목은 시장조사(마케팅조사)의 기본 지식을 함양하고 이를 현실세계에 응용할 수 있는 능력을 배양하는 데에 목표를 두고 있다. 본 과목은 이론학습과 함께 경영학 분야에서 가장 많이 사용하는 기초통계 프로그램인 SPSS의 실습을 병행한다. 본 과목을 통해 마케팅 관리 분야와 관련있는 사회조사분석사 2급 자격증 준비 효과를 부수적으로 얻을 것이다. 본 과목은 종합설계과목으로서 실제 기업에 대한 시장조사(마케팅조사) 보고서를 조별로 작성하여 발표함으로써 캡스톤디자인학습 을 병행한다. 본 과목은 지식재산(IP) 연결 등 차원에서 1인창업동아리 연계 과제를 추가 제출할 수 있는 기회를 제공한다. 본 과목은 산업체 문제 은행 중 시장조사기반 신제품기획 관련 적절한 주제가 있을 시 프로젝트 주제로 선택 가능한 산업체 연계 가 능 과목이다. 본 과목은 신제품기획 캡스톤디자인(종합설계) 프로젝트 진행 과정에 생성형AI툴을 접목하여 입체적인 신제품기획능력을 배양할 수 있도록 한다. 학습자는 시장조사(마케팅조사)의 기본 개념과 원리를 이해해야 한다. 학습자는 시장조사(마케팅조사)의 기본 개념과 원리를 현실세계의 문제해결상황에서 발휘할 수 있어야 한다. 시장조사(마케팅조사) 자료를 활용하는 신제품 마케팅 기획 문제를 해결해 봄으로써 자료 기반 신제품기획역량과 사업계획서작성역 량을 습득한다. 신제품기획 캡스톤디자인(종합설계) 프로젝트 진행 과정에 생성형AI툴을 접목하여 입체적인 신제품기획능력을 배양한다.', '{"강의노트","스마트캠퍼스","배포","시장조사","팀프로젝트","프롬프트","해보기","기반","신제품기획서","마케팅조사","가설검정","중간고사","과목은","발표자료","생성형","강의계획서","조사의","종류","자료와","측정"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531109', '공정양론', '자연과학대학', '자연과학대학', 0, 3, '전선', '김동진', '공정 공학(process engineering)을 특징으로 하는 화학공학(chemical engineering), 환경공학(environmental engineering), 생물 및 식 품공학(biological and food engineering) 등의 장치산업은 물질의 측정(measurement), 정량(quantitative calculation), 물질의 이동 현상(transport phenomena), 혼합(mixing), 물질의 반응(reaction)에 의한 전환, 상(phase) 변환(transition), 분리 정제(separation and purification), 분해(degradation) 등의 단위 공정(unit process)과 단위 조작(unit operation)이 결합된 복합공정으로 구현된다. 이러한 복합 공정계(complex process system)를 이해하고, 정량적으로 계산하고, 설계하기 위해서는 이의 공정 원리와 계산 방법을 학습할 필요가 있다. 이 과목에서는 PART 1 서론 (제1장 화학공학 그리고 생물공학이란 무엇인가? 제2장 기초개념: 공학계산의 기초(단위와 차원, 물질 량, 분석법과 측정법, 계산기준, 온도, 압력, 화학 반응식과 양론), PART 2 물질수지 (제3장 물질수지(material balance), 제4장 화학반 응 물질수지, 제5장 복합 장치계의 물질수지), PART 3 기체, 증기 및 액체 (제6장 이상기체와 실재기체, 제7장 다상계 평형)에 대해 학 습하게 된다. 상세한 강의 스케쥴은 주별 강의계획을 참고하기 바랍니다. 공정공학 및 물질의 물리화학적 성질, 차원과 단위를 이해하고 자유롭게 단위 환산을 할 수 있으며, 물리적 화학적 공정 시스템에 적 용되는 공학 계산과 물질수지를 작성하고 풀이할 수 있다. 자세하게는 다음과 같다. - 단위와 차원, 단위환산, 물질량, 밀도, 농도, 계산기준, 온도, 압력을 이해하고 자유롭게 활용할 수 있다. - 물질수지의 개념, 비반응 물질수지, 반응을 포함하는 물질수지, 복합-장치계에 대한 물질수지를 작성하고 풀이할 수 있다. - 이상기체와 실제기체 상태방정식, 다상계 평형을 이해하고 공학계산에 활용할 수 있다.', '{"물질수지","풀이","숙제","연습문제","다상계","있다","기초개념","물질량","밀도","농도","물질수지의","실제기체","공정","물질의","이해하고","계산기준","이상기체와","화학반응","중간고사","단위"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205305', '재무관리', '경영대학', '경영대학', 0, 3, '전선', '변희섭', '현대 자본주의 사회에서 경제주체(기업 또는 개인)는 다양한 재무적 의사결정에 직면한다. 기업의 재무적 의사결정의 핵심은 (1) 투자의 가치평가, (2) 자금조달, (3) 배당 및 자본구조 형성 등으로 구성되며, 이들은 궁극적으로 기업가치 극대화라는 공통의 목표를 바탕으로 최적의 상태로 수립되어야 한다. 특히, 기업의 측면에서 과연 보유한 투자안의 가치가 얼마나 될 것인지, 이를 실현하기 위해서는 얼마의 자금을 어떤 경로를 통해 조달해야 하는지를 사전에 판단해야만 경영활동의 지속 가능성을 확보할 수 있다. 따라서 재무적 의사결정은 경영활동의 시작을 결정짓는다는 점에서 그 중요성이 높다 할 수 있다. 뿐만 아니라 가계(개인)의 측면에서도 현금흐름의 유인과 유출을 고려한 안정적인 재무설계 방안을 수립해야만 발생 가능한 불확실성에 대비할 수 있어 점차 그 중요성이 확대되고 있다. 본 교과목에서는 먼저, 기업의 본질과 형태를 중심으로 기업가치 극대화의 의미와 재무관리의 목표에 대해 논의한다. 다음으로, 미래현금흐름의 유입과 자본비용을 고려한 투자가치 평가수단과 방법론을 습득한다. 더 나아가 자본시장에서 기업의 입장에서 주요한 자금조달 수단이자 가계(개인)의 입장에서 투자수단인 채권, 주식의 가치가 어떻게 결정되며, 이를 예측하기 위해서 사전에 고려되어야 하는 요인에 대해서도 논의한다. 마지막으로 위험과 수익의 상충관계를 근간으로 하는 자본시장의 본질에 대해 배우고, 이러한 본질을 바탕으로 기업의 측면에서 자 본비용을 최소화하는 방안, 가계(개인)의 측면에서 투자 수익률을 극대화하는 방안을 도출한다. 기업의 재무적 목표와 재무적 의사결정을 이해한다. 기업의 투자안의 가치 평가 수단과 방법론을 습득한다. 채권, 주식 등 다양한 금융상품의 가치를 측정한다.', '{"피드백","실시","가치평가","금융자산","강의노트와","녹화","컨텐츠를","활용한","사전학습","실무사례를","응용한","작성","설명","핵심내용","요약정","수강생과","상호작용을","통한","보충설명","수업운영"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531110', '환경화학', '자연과학대학', '자연과학대학', 0, 3, '전선', '김헌기', '환경오염의 성질과 상태, 시간, 공간, 기후조건에 따른 오염물질의 변화를 화학적으로 파악하고 오염물질이 자연환경과 인체에 미치 는 영향에 대하여 이해하기 위하여 수질환경, 대기환경, 토양환경, 중금속, 농약 및 각종 유해물질과 관련된 내용을 공부한다. - 환경공정에서 발생하는 화학변화를 이해하고 정량적으로 해석하는 능력', '{"질의응답을","필요한","경우","동영상","자료","연습문제","해당부분","기초개념","화학평형의","수질분석","물리화학의","열역학적","해석","분석방법","계산","많이","쓰이는","물리화학","분석자료의","알칼리도"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205314', '회계세무데이터분석', '경영대학', '경영대학', 0, 3, '전선', '박주형', '- 현재 기업과 사회에서는 플랫폼 및 분석형 도구를 이용한 의사결정 등 빅데이터를 활용한 기업 전략, 마케팅 활동을 다양하게 수행 하고 있음. - 본 교과목에서는 다양한 회계세무데이터와 통계프로그램을 이용하여 기업의 의사결정에 활용할 수 있는 다양한 분석방법을 학습함 . - 회계 및 세무 관련 전공지식이 필요하며, 기업 이해관계자의 의사결정에 대해 이해할 수 있음. 회계세무 데이터를 분석 및 해석하는 능력과 통찰력을 함양할 수 있음. - 통계 프로그램을 이용하여 다양한 의사결정 속 상황과 가정에 대해 알맞은 데이터를 추출할 수 있음. - 코딩 과정에 상상력과 인내심, 지구력이 요구됨.', '{"데이터","회계","세무","업로드","수강","어떤","주제를","추출","논의함","해석","통계","모두","주가수익률이","결과","기업","분석을","설명","프로그램","실습함","기업이"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205317', '무역실무', '경영대학', '경영대학', 0, 3, '전선', '한재훈', '본 수업은 플립러닝 교과목으로서 무역업무에 필요한 지식을 학생들이 습득하도록 한다. 무역이론에 대한 지식 습득보다는 실무에 필요한 지식과 어학능력을 갖추는 것을 목표로하는 과목이다. 수출입에 관련된 법규, 수출입 절차, 해상보험, 외환제도, 신용장 등을 다루며 무역업무에 꼭 필요한 무역서신 작성 및 인터넷 영어를 다루는 무역영어 부분으로 나누어 강의를 진행한다. 이를 통하여 무 역실무에 대한 기본지식을 습득하고 무역영어1급 자격증을 취득할 수 있는 기초를 다지고자 한다. 본 수업은 플립러닝의 수업방식읕 채택하여 목요일 수업은 비대면으로 화요일 수업을 위하여 미리 탑재한 온라인 동영상 강의를 학 습하여야 하며,화요일 대면수업은 미리 학습한 내용에 대한 심층토론, 발표 및 질의응답과 보완강의로 진행하고자 한다. 따라서 플립 러닝의 의의와 목표를 최대한 이루기 위하여 온라인콘텐츠 사전학습과 강의실에서 적극적인 참여가 필수적으로 요구된다. 무역실무와 관련한 지식 및 법률과 무역관련 영어 학습 무역영어 1급 자격증', '{"개인과제","강사에","의한","교재","스마트리드","목요일","플립러닝","온라인콘텐츠","자기주도학습","무역영어","작성","무역관련","무역실무","화요일","대면강의","무역운송","통관","무역클레임과","중간고사","투자"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('503203', '물리화학Ⅰ', '자연과학대학', '자연과학대학', 0, 3, '전선', '이호재', '화학에서의 열역학은 거시적인 화학적 시스템을 다루는 학문이다. 주요 주제는 열역학 법칙, 기체 및 용액의 특성, 화학 평형이다. 열역학을 통하여, 아주 작은 분자의 특성이 어떻게 상대적으로 엄청 큰 실생활 물질의 특성에 영향을 주는지 배울 수 있다. 화학적 열역학을 배우고, [열역학 법칙], [기체, 액체, 고체의 성질], 및 [화학 평형]을 이해한다.', '{"열역학","법칙","평형","화학","성질","화학적","기체","열역학을","기체의","중간고사","주차","구성요소","전이","혼합물","활동도"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531201', '환경학개론', '자연과학대학', '자연과학대학', 0, 3, '전선', '최성찬', '환경학의 기본원리를 체계적으로 강의하여 환경 제분야의 문제점과 실태를 파악하게 하고, 이후의 심화 전공교과목 수강에 필요한 전공기초지식을 습득토록한다. 구체적으로는 토양 황폐화의 원인과 보전방법, 생물종 다양성의 중요성과 보전방법, 수량과 수질의 안 정적 보전을 위한 기술적 방법, 폐기물의 생성과 처분, 방사능 물질의 위험성, 대기오염과 기후변화 등 환경오염 현상의 과학기술적 설명 뿐만 아니라 바람직한 해결방안을 체계적으로 다루게 된다. 이 교과목을 수강하게 되면 다양한 환경분야(수질, 수량, 토양, 대기, 폐기물, 방사능오염 등)에 대한 기본적인 이해를 높일 수 있다. 비 전공자의 경우 환경 이슈에 대한 critical thinking을 가능하게 해 주며, 전공자의 경우는 환경의 각 세부분야에 대한 기초지식의 습득 을 통해 심화학습의 기반을 다질 수 있다. 지식의 습득 뿐만 아니라 오염된 환경의 복원과 자연보전을 위해 어떤 노력을 통해 동참할 수 있는지에 대한 내용도 함께 다루어 실천적 지식이 되도록 지도하는 것이 본 교과목의 목표이다.', '{"학습자료","원인과","수자원","관한","생물종","다양성의","폐기물의","바람직한","수량","국지적","대기오염의","피해에","체계적으로","환경","토양","보전방법","뿐만","아니라","있다","전공자의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205320', '경영정보시스템(MIS)의이해', '경영대학', '경영대학', 0, 3, '전선', '민성환', '본 과목은 디지털 전환 시대에 기업의 경쟁력 강화를 위한 핵심 도구로 자리 잡은 경영정보시스템(MIS)의 기본 개념과 역할 및 최신 이슈에 대해 최신 이슈에 대해 살펴본다. 기업에서 정보시스템을 활용하여 어떻게 환경변화에 대응하고 경쟁우위를 확보하는지 사례를 통해 살펴보고, 정보시스템의 향후 발 전 추세에 대해서도 살펴본다. 본 과목은 캡스톤디자인 교과목으로 팀 과제를 수행해야 합니다. 캡스톤디자인 유형은 일반형으로 AIMR 중 주로 A, I 단계의 과제를 수행하게 됩니다. - 경영정보시스템(MIS)의 기본 개념 및 구성 요소, 주요 기능에 대한 이해 - 빅데이터, 인공지능 등 최신 정보기술의 발전 동향 파악 - 최신 정보기술이 기업 활동에 어떻게 응용되는지 사례 중심 학습 -정보기술을 활용한 기업 경쟁력 강화 및 경영혁신 전략 수립 방법 습득 - 기업의 경영 전략과 연계된 정보시스템 전략 수립 및 기획 절차에 대한 실무적 이해 - 정보시스템의 개발·운영·관리에 대한 개념적 이해 - 디지털 환경 변화에 대응할 수 있는 문제 해결력, 분석적 사고력, 기획력 강화', '{"데이터베이스","사례","최신","지식경영","팀과제","데이터","마이닝","경영정보시스템","정보기술의","정보시스템","과목은","디지털","기업의","경쟁력","이슈에","대해","살펴본다","어떻게","정보시스템의","캡스톤디자인"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531207', '대기오염제어', '자연과학대학', '자연과학대학', 0, 3, '전선', '박기태', '대기오염 물질의 정의와 분류, 오염물질의 배출원 및 영향, 광역대기오염, 실내공기오염, 대기오염물질 제어 방법 등에 관한 전문지식 을 향상 한다. 특히, 최근 우리 사회의 주요 이슈로 부각되고 있는 초미세먼지에 대한 문제의식과 해결책에 대해 고민한다. 대기 중 오염물질의 발생, 영향 및 제어 방법에 대한 이해', '{"자료","해당","사항","없음","주교재","오염물질","배출원","광역대기오염","실내공기오염","오염물질의","대기오염의","입자상","성분","중간고사","대기오염","대기오염물질","발생","오염","부교재","제어"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205398', '재무회계', '경영대학', '경영대학', 0, 3, '전선', '박주형', '- 사회 속에서 회계가 수행하는 역할과 공헌을 통해 회계의 중요성을 이해함 - 재무회계의 기초 지식 습득과 재무제표의 작성 및 이해 능력 제고 * 회계의 기초 개념 이해와 기본 용어 숙지 * 회계정보 산출방법(=회계보고서 작성방법)에 대한 이해를 통해 궁극적으로 회계정보 활용방법을 이해함 * 재무제표의 구성요소 학습, 주요 계정과목 별로 구체적인 회계처리를 이해함 - 사회 속에서 회계가 수행하는 역할과 공헌을 통해 회계의 중요성을 이해함 - 재무회계의 기초 지식 습득과 재무제표의 작성 및 이해 능력 제고 * 회계의 기초 개념 이해와 기본 용어 숙지 * 회계정보 산출방법(=회계보고서 작성방법)에 대한 이해를 통해 궁극적으로 회계정보 활용방법을 이해함 * 재무제표의 구성요소 학습, 주요 계정과목 별로 구체적인 회계처리를 이해함', '{"판서","위주","회계의","순환과정","거래의","문제풀이","이해함","재고자산","재무제표의","회계정보","구성요소","조정","속에서","회계가","수행하는","역할과","공헌을","중요성을","재무회계의","지식"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531222', '폐수처리공학I', '자연과학대학', '자연과학대학', 0, 3, '전선', '박진용', '도시 하수 및 공업 폐수의 특성을 이해하고, 물리적 단위조작, 화학적 단위 공정, 물리화학적 처리 및 생물학적 단위공정과 같은 일반 적인 폐수처리 방 법과 응용에 대하여 습득하고, 최근 환경규제의 강화로 부각되고 있는 고도 처리의 종류와 필요성에 대하여 알아보 고, 이러한 이론을 바탕으로 폐수의 특성과 용량에 적합한 폐수처리공정의 설계를 이해하도록 한다. 폐수처리공학 분야에 걸쳐 제기된 문제점, 해결 방안 등을 학습함으로써 폐수처리공학에 대한 폭 넓은 이해를 돕고 발표, 문제 제기 능력을 배양한다.', '{"성분","자료","하수","물리적","생물학적","무기성","비금속성분","산정","유량","성분질량부하","하수처리","하수의","혼합","유기물","개별","유기화합물","하수유량과","부하량의","발생원","하수량"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206320', '은퇴설계론', '경영대학', '경영대학', 0, 3, '전선', '이덕수', '- 고령화시대에 고령화 이슈와 은퇴환경을 이해하고 - 은퇴준비, 은퇴설계,은퇴소득 등 은퇴에 관해 정리한 후 - 연금,은퇴자산운용 등에 대해 공부하고 자신의 은퇴설계서를 직접 만들어 보고 성공적 은퇴생활에 대해 정리하는 시간을 갖는다. - 재무, 비재무 구분하여 비재무 등 은퇴와 관련된 여러 부분을 폭넓게 이해하고 은퇴관련 설계사로서의 자격과 능력을 키우는데 그 목적이 있다. 고령화와 은퇴설계에 관한 문제점을 도출하고 해결방법을 찾는 역량을 기르는 것을 목표로함', '{"교재","보강","은퇴","은퇴생활","과제부여","은퇴준비","은퇴설계","성공적","이해하고","대해","비재무","이해하기","위협요인","은퇴재무","은퇴자의","자산운용","프로세스","국민연금","중간고사","주차"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531224', '환경미생물학I', '자연과학대학', '자연과학대학', 0, 2, '전선', '최성찬', '본 강의는 환경생명공학이라는 학문을 공부하는데 있어서 빼 놓을 수 없는 미생물 분야의 지식을 습득하는데 그 목적이 있다. 미생 물은 자연환경에서 여러 가지 중요한 기능을 담당하고 있는데 환경 미생물학적 측면에서는 유기물 분해와 생물지구화학적 순환 등을 포함한 물질의 변환능력과 병원체 및 지표생물로서의 역할이 특히 중요하다. 환경오염물질의 전환과 관련된 분해자로서의 역할은 각종 폐수 및 폐기물 처리에 필수적이며, 따라서 환경오염을 해결하기 위해서는 미생물에 대한 이해가 필수적이다. 본 강의에서는 환경미생물학 II에서 본격적으로 다루게 될 환경미생물학의 응용분야를 이해하기 위한 환경미생물학의 기초적인 지식 습득을 도모하 고자 한다. 이 교과목을 수강하게 되면 다음과 같은 부문의 향상을 얻을 수 있다. - 환경미생물학 범위 및 역사에 대한 이해 - 세균세포의 구조에 대한 이해 및 분류체계 - 바이러스와 진핵미생물의 종류 - 환경미생물 관련 실험의 원리에 대한 이해 - 세포의 구성물질과 기능에 대한 이해 - 미생물의 에너지 생성 대사 및 생장관련 개념 이해', '{"강의식","미생물","미생물의","대사","실험","방법론","생체","구성물질","생장","환경미생물학","바이러스와","미생물학과","생태계의","있다","환경미생물학의","세균과","고균","세균의","동정과","분류"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531313', '공정설계', '자연과학대학', '자연과학대학', 0, 3, '전선', '김동진', '수처리, 폐기물 처리, 대기오염방지시설 등의 환경공정의 설계와 프로젝트 관리의 원리를 학습하고 이를 통하여 설계방법을 익히며 설계된 결과를 컴퓨터 simulation이나 실험을 통하여 평가하고 다시 설계에 반영하여 최적의 설계방법을 학습한다. 또한 환경공정의 설계에 필요한 data와 method를 개발하고 이를 설계에 반영하여 설계도와 설계보고서를 작성하여 실무 능력을 배양한다. 교과목표는 수처리, 폐기물 처리, 대기오염방지시설 등의 환경공정의 설계와 프로젝트 관리의 원리를 학습하고 이를 통하여 설계방법 을 익히며 설계된 결과를 컴퓨터 simulation이나 실험을 통하여 평가하고 다시 설계에 반영하여 최적의 설계방법을 학습한다. 또한 환경공정의 설계에 필요한 data와 method를 개발하고 이를 설계에 반영하여 설계도와 설계보고서를 작성하여 실무 능력을 배양한 다. 그 결과 설계 및 엔지니어링 전반에 대한 이해와 프로젝트 경험을 축적하여 환경공학 분야 직업능력을 향상한다. 환경 분야의 설 계사나 영향평가사, 엔지니어링 기업에 취업하고자 하는 학생은 반드시 수강하기를 권유한다.', '{"프로젝트","관리","관리기법","설계에","환경공정의","이를","통하여","반영하여","공정설계","중간고사","하폐수처리","공정","장치","설계방법을","수처리","폐기물","처리","대기오염방지시설","등의","설계와"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205416', '마케팅커뮤니케이션', '경영대학', '경영대학', 0, 3, '전선', '전호성', '기업이 지출하는 마케팅 비용중에서 가장 많은 비중을 차지하는 판촉활동을 IMC의 시각속에서 설명하고 이와 관련된 실제 광고캠페 인 사례들을 고찰함으로써 효과적인 광고기획과 매체계획을 수립하는데 필요한 지식을 제공하는데 강의의 목표가 있다. 그리고 본 교과목은 캡스톤디자인 Idea 유형의 수업이며 과제의 유형은 일반형 수업입니다. -지식: 마케팅커뮤니케이션에 대한 이해 -기술: 광고분석 능력 -태도: 자기주도적 학습태도', '{"광고","과제물","마케팅","관리","조별면담","수업시간","광고의","시장","프로포절","전략","캠페인","소비자의","반응","크리에이티브","커뮤니케이션과","역사와","조편성","공지","경제적","효과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205422', '경영학특강', '경영대학', '경영대학', 0, 3, '전선', '김용근', '- 마케팅, 전략, 회계, 인사조직, 비즈니스인텔리전스, 관광경영, 의료경영 등 기초적인 경영학 원론적 지식을 실무에 적용할 수 있는 능력 배양을 목표로 함 - 이를 위해 본 교과목에서는 경영학과 전임교원이 모두 한 주차씩 강의에 참여하여 각 전공분야의 기초지식을 강의함 - ''26년 1학기부터 ''쿠팡 AI물류융합인재 나노디그리'' 과목에 포함되어 물류산업에 대한 실무 전문가 특강도 추가됨 - 마케팅, 전략, 회계, 인사조직, 비즈니스인텔리전스, 관광경영, 의료경영 등 기초적인 경영학 원론적 지식을 실무에 적용할 수 있는 능력 배양을 목표로 함 - 쿠팡AI물류 융합인재 나노디그리 포함 과목으로 물류산업과 선진물류기업게 대한 이해를 목표로 함', '{"교수","김용근","쿠팡","주차","배양을","목표로","전문가","출결","경우","참고도서","구성요소","마케팅","전략","회계","인사조직","비즈니스인텔리전스","관광경영","의료경영","기초적인","경영학"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531335', '생물정화기술', '자연과학대학', '자연과학대학', 0, 2, '전선', '최성찬', '이 교과목은 일반미생물학 또는 환경미생물학을 수강한 학생들을 대상으로 현재 다양한 형태로 시도되고 있는 생물정화기술(biorem ediation)의 원리와 응용에 관해 심도있게 학습하는 것이 목적입니다. 환경오염물질과 미생물 간의 관계를 이론적인 부분 뿐만 아니 라 실제로 적용되는 정화기술과 함께 학습하면서, 전공수업에서 다루었던 각종 처리기술의 요약 정리 및 미생물학적 측면의 이해를 증진시키도록 수업이 구성되어 있습니다. 본 교과목 수강을 통해 다음과 같은 지식과 기술을 습득할 수 있습니다. - 오염물질의 생분해에 대한 정의 - 분해과정에서 나타나는 무독화 반응과 활성화반응의 종류 - 생분해과정의 정량적 평가를 위한 kinetics의 이해 - 환경오염물질의 생물학적 분해를 저해하는 다양한 요인들에 대한 고찰과 극복방안 - 화합물의 구조가 생물학적 분해에 미치는 영향 - 온도, pH 등 환경요인들이 오염물질의 생분해에 미치는 영향 - 생물정화기술의 원리와 실제 현장처리 적용', '{"설명식","화합물의생물학적","분해가","일어나지","않는","경우의","화합물의","생물학적","미치는","분해에","생물정화기술의","실제","생분해에","물리적","영향에","또는","무독화","구조가","원리와","있습니다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205423', '국제마케팅', '경영대학', '경영대학', 0, 3, '전선', '전호성', '마케팅의 원칙은 보편적이지만 각 국가의 사람들이 다르듯이 마케팅의 실천수단도 개별 국가에 따라 달라지는 것은 자연스러운 현상 이다. 한 국가에서 성공했던 마케팅 전략이 다른 나라에서 실패를 하게 되는 것은 국가에 따라 고객의 기호, 경쟁사, 유통경로, 매체 등이 다르기 때문이다. 이러한 점에서 국제 마케팅은 마케팅 계획과 프로그램의 경우 어디까지 표준화가 적절하며 어디부터는 현지 적응화가 필요한 것인가를 시장의 조사와 이해를 통해 학습하는 과목이다. 이러한 것을 통해 글로벌 마케팅 전략의 수립과 글로벌 마 케팅 믹스의 실천과 관련된 역량을 키우는 것을 강의의 목표로 두고 있다. -지식: 국제마케팅에 대한 이해 -기술: 해외시장분석 능력 -태도: 자기주도적 학습태도', '{"글로벌","과제물","마케팅의","마케팅","국가에","따라","것은","이러한","것을","경제환경","무역환경","사회문화","정치","법률","규제","환경","정보시스템과","시장조사","시장세분화","표적시장선택"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531347', '캡스톤디자인:환경', '자연과학대학', '자연과학대학', 0, 3, '전선', '박기태', '캡스톤 디자인 수업의 학부 과정에서 배운 전문 지식을 통합하여 실제 산업 현장이나 사회에서 필요로 하는 창의성, 실무능력, 의사 소통 능력을 키우기 위한 교과목입니다. 지도교수와 상의하여 연구주제를 정하고 함께 토론하면서 실험/연구를 통해 결과를 얻고, 토의하면서 보고서를 작성하게 됩니다 본 교과목은 전공교과과정을 이수하면서 익힌 기초적인 실험실습 테크닉을 기반으로 각 교수 실험실에 배정되어 개인 또는 팀별로 연구주제를 선정하여 문제를 해결해 나가는 과정에서 자연스럽게 학습이 이루어지도록 합니다', '{"실험","연구논문","메뉴얼","실시","교육","연구보고서","작성","중간고사","과정에서","연구주제를","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205425', '인터넷비즈니스(종합설계)', '경영대학', '경영대학', 0, 3, '전선', '민성환', '- 본 과목에서는 인터넷 비즈니스에 관해 조망하고, 관련 지식을 습득하며, 인터넷 비즈니스가 제공하는 새로운 기회들에 대해 살펴 본다. - 인터넷과 관련된 다양한 비즈니스 모델을 이해하고 변화된 기업 경영환경과 향후 새로운 기업 경영환경에 대해 조망해 본다. - 인터넷과 응용기술 및 최신 기술을 비즈니스적인 관점에서 조망해 본다. - 다양한 국내외 사례를 통해 인터넷 비즈니스를 이해하고 향후 인터넷 비즈니스를 조망해 본다. -본 과목은 캡스톤디자인 교과목으로 팀 과제를 수행해야 한다. (캡스톤디자인 유형은 일반형으로 AIMR 중 주로 A, I 단계의 과제를 수행) - 인터넷 비즈니스의 개념에 대한 이해 - 디지털 경제에 대한 이해 - 비지니스 모델에 대한 이해 - 최신 인터넷 비즈니스 동향 파악 - 기업의 정보시스템과 인터넷비즈니스 - 최신 기술 현황 및 미래 기술 동향 파악 및 기업 경영환경 변화에 대한 이해', '{"인터넷","비즈니스","사례","팀과제","본다","구성요소","기업","조망해","최신","비즈니스의","디지털","최종보고서","새로운","대해","인터넷과","이해하고","향후","비즈니스를","캡스톤디자인","과제를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('531351', '최근환경분석화학동향', '자연과학대학', '자연과학대학', 0, 3, '전선', '박진용', '물질을 검출 확인하고 분리하여 정량화하는 분야가 분석화학으로 본 강좌에서는 분석화학의 일반적인 원리와 무게 분석법 및 부피 분석법(적정법)을 다루고 기기 분석의 기본이 되는 전기화학의 원리와 전자기 복사선과 물질의 상호작용에 대하여 이해하고, 이러한 원리를 응용한 전위차법 및 전기분해법, 분광광도법, 원자분광법 등을 습득한다 물질을 검출 확인하고 분리하여 정량화하는 분야가 분석화학으로 본 강좌에서는 분석화학의 일반적인 원리와 무게 분석법 및 부피 분석법(적정법)을 다루고 기기 분석의 기본이 되는 전기화학의 원리와 전자기 복사선과 물질의 상호작용에 대하여 이해하고, 이러한 원리를 응용한 전위차법 및 전기분해법, 분광광도법, 원자분광법 등을 습득한다', '{"적정","화학","무게","분석법","산과","완충","검출","원리와","부피","연소","염기의","세기","강염기","작용","염기","다양성자","평형의","심층","균형","물질을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205501', '기술경영', '경영대학', '경영대학', 0, 3, '전선', '황정태', '기술경영은 기술혁신에 초점을 맞추어 수업을 진행하며 교과서의 제목처럼 전략기술경영이 주된 내용이라고 볼 수 있다. 현 사회에 서 특히 한국처럼 첨단제조업을 중심으로 성장한 나라에서 기업은 기술경영의 중요성을 더욱 절감하고 있다. 본 과목은 기술의 특징 과 패턴을 바탕으로 기술이 경쟁에서 가지는 의미와 시사점을 공부하고 기술로드맵과 같은 기술기획과 프로젝트 선택 그리고 기술의 보호전략 및 협력전략 등 광범위한 분야에 걸처 공부한다. 특히 주요 논문을 학습하고 발표하면서 경영학을 전공하는 학생들이 기술 경영의 주요 개념을 파악하고 나아가 기업에서 기술경영을 바탕으로 한 기획력을 확보하는 것을 목적으로 한다. 수강대상으로 경영 학 전공 이외에 복수전공을 희망하는 자연대 공대 학생에게도 도움이 되는 과목이다. 기술이 경제 및 경영에 미치는 영향과 의미를 파악 기술경영 특히 연구개발프로젝트의 선택 및 연구개발조직의 틀을 잡고 기술로드맵을 작성하기 위한 기본 지식 획득 자연계 복수전공학생에게는 경영개념을 형성하는데 도움', '{"숙제","학번이","끝나는","만점","특히","있다","기술의","바탕으로","기술이","선택","홀수로","맨뒤","토론문제","매주","장씩","진도를","나감","짝수로","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206412', '금융영어Ⅰ', '경영대학', '경영대학', 0, 3, '전선', '안동규', 'The purpose of this class is1) to deal with the financial basic Knowledge in various areas and 2) to teach students how to presen t the financial knowledge in the business presentation in english. This course helps students learn Business Communication and Business Presentation Skill. The purpose of this class is to teach students how to present the financial knowledge in the business presentation in english. Thi s course helps students learn Business Communication and Business Presentation Skill. Main text Professional English in Use "Finance", is used to cover the contents of the finance knowledge. It also emphasizes the te rminology of the text of the main text.', '{"중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('769024', '환경전과정평가(Life', '자연과학대학', '자연과학대학', 0, 3, '전선', '김동진', '환경전과정평가(Life Cycle Assessment, LCA)는 제품이나 공정, 서비스가 자원의 채취에서부터 생산, 사용, 폐기 및 재활용에 이르기 까지 전 생애주기 동안 환경에 미치는 영향을 정량적으로 평가하는 과학적 기법이다. 본 교과목은 ISO 14040 및 ISO 14044에서 제시하는 국제표준을 기반으로, LCA의 전과정 - 목적 및 범위 정의, 전과정목록분석(LCI), 전과정영향평가(LCIA), 전과정해석(Interpretation) - 을 단계별로 학습한다. 또한 학생들은 실제 산업 및 환경 분야 사례(예: 하수처리 공정, 자동차, 건축자재 등)를 통해 데이터 수집, 환경영향 평가, 정규화·가중화 및 결과 해석 과정을 실습함으로써 지속가능한 기술개 발, 탄소중립 전략 수립, 친환경 제품 설계 등에 LCA를 적용할 수 있는 실무 능력을 배양하게 된다. 본 교과목은 제품 및 공정의 전 생애주기(Life Cycle) 동안 발생하는 환경 부하를 정량적으로 평가하는 전과정평가(LCA: Life Cycle Ass essment) 기법을 학습하는 것을 목표로 한다. ISO 14040 및 14044 국제표준을 기반으로 전과정평가의 각 단계(목적 및 범위 정의, 목 록분석, 영향평가, 해석)의 절차를 이해하고, 이를 실제 사례에 적용하여 제품·공정의 환경성 개선 전략을 수립하는 능력을 배양한다. 학생들은 지속가능한 생산과 소비, 탄소중립 및 친환경 제품 설계(eco-design)에 LCA를 적용할 수 있는 역량을 습득한다. 기대효과: 1) LCA의 개념과 절차를 설명할 수 있다.2) 제품 및 공정의 전과정 흐름도를 작성하고 시스템 경계를 설정할 수 있다.3) LCI 데이터를 수집, 검증, 통합하여 환경영향을 분석할 수 있다.4) LCIA 결과를 정규화·가중화하여 환경이슈를 규명할 수 있다.5) LCA 결과를 기반으 로 지속가능한 기술 및 정책 제안을 수행할 수 있다.', '{"제품","데이터","전과정","정의","있다","목적","범위","환경","수집","정규화","해석","지속가능한","친환경","전과정사고","설정","품질","에너지","기준","선정","결과의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508102', '기초영양학', '자연과학대학', '자연과학대학', 0, 3, '전선', '박소현', '이 과목은 식품영양전공자들의 첫 영양학 입문 강의이다. 다량영양소와 미량영양소의 기본 개념에 대해 소개하고 체내 영양소 대사에 대한 기본적인 내용을 학습한다. 이러한 기본적인 이해를 바탕으로 건강한 식생활의 기본 원칙에 대해 학습한다. 또한 최근 영양관련 건강문제에 대해 생각하고 토론한다. 영양교사양성에 도움이 되는 기초적인 영양학을 배우고 실제 영양교사가 되어서 활용할 수 있도록 한다. 다량영양소와 미량영양소에 해당하는 물질에 대해 알고 각각의 특징에 대해 설명할 수 있다. 기초적인 체내 대사에 대해 설명할 수 있다. 건강한 식생활의 구성요소를 알고 실천할 수 있다. 최근 이슈가 되는 영양 문제, 영양 관련 건강 문제에 대한 영양학적 설명을 할 수 있다.', '{"있다","대해","슬라이드와","교과서","종류와","기능","질환에","기능에","비타민의","관련된","대사에","학습한다","최근","알고","설명할","슬라이드","이해할","탄수화물의","지질의","단백질의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205504', '비즈니스다이내믹스', '경영대학', '경영대학', 0, 3, '전선', '이견직', '주류 경영학에서의 의사결정은 주로 선형의 일방향이며 정적 상황을 가정하고 이루어진다. 이에 반해 현실은 비선형의 쌍방향이며 동적 상황을 이루고 있다. 본 강좌에서는 방법론 중심의 현실 제약적 환경에서 벗어나 현실 중심으로 문제를 이해하며 이를 반영한 방법론에 대해 학습한다. 이러한 접근은 피드백 순환의 급증으로 대변되는 초연결 사회에서 요구되는 창의적 사고를 형성하는 기반 을 제공할 것이며, 이를 통해 주류 경영학의 한계를 벗어나는 새로운 통찰력을 배양하는 기회가 될 것이다. 특히, 본 수업은 지속가능 하고 전체 최적화를 도모할 수 있는 시스템의 설계를 위하여 시스템의 개념, 특징, 관점 등을 살펴보고 시스템을 전체적이면서 세부 적인 이해를 제고하기 위해 학습한다. 이를 위해 시스템 사고 방법 및 이를 분석하기 위한 컴퓨터 시뮬레이션 모형의 개발과 다양한 시나리오 분석을 토대로 한 바람직한 전략 및 정책 지렛대를 도출하고 이를 적용한 경영혁신 사례에 대해 토의한다. 관련된 내용은 첨부파일을 통해 확인바랍니다.', '{"첨부된","참조","이를","주류","상황을","현실","대해","학습한다","시스템의","위해","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508202', '인체생리학', '자연과학대학', '자연과학대학', 0, 3, '전선', '이혜지', '본 교과목은 인체의 정상적인 구조와 기능을 통합적으로 이해하는 것을 목표로 하며, 항상성 유지 기전을 중심으로 신경계, 내분비계, 근육·골격계, 순환계, 호흡계, 소화계, 신장계 등 주요 생리 시스템의 작동 원리를 학습한다. 특히 영양소 섭취와 대사, 체액·전해질 균 형, 에너지 조절 등 영양학적 관점에서 인체 생리 현상을 해석할 수 있도록 구성하여, 향후 전공 교과목의 이해를 위한 기초 역량을 강화한다. 또한 본 교과목에서 다루는 핵심 개념과 용어는 영양사 국가고시에서 요구되는 생리학적 기초 지식과 밀접하게 연계되어 있어, 학생 들이 국가고시 대비에 필요한 개념 이해와 문제 해석 능력을 함께 기를 수 있도록 한다. 이를 통해 학생들은 단순 암기가 아닌, 임상 및 실무 상황에 적용 가능한 생리학적 사고 능력을 함양하는 것을 목표로 한다. 이 교과목은 인체의 정상적인 구조와 기능을 항상성 유지 관점에서 이해하고, 영양소 섭취 및 대사와 관련된 생리적 조절 기전을 체 계적으로 설명할 수 있는 역량을 기르는 것을 목표로 한다. 이를 통해 학생들은 인체생리학적 지식을 영양학적 문제 해결과 임상·실 무 상황에 적용할 수 있는 기초 역량을 함양하며, 전공 심화 교과목 및 영양사 국가고시 학습을 위한 기초 학문적 토대를 마련한다.', '{"구조와","이해한다","기능을","조절","설명할","있다","체액","항상성","호르몬","기전을","구조","인체의","구성","세포","혈액","면역","것을","목표로","원리를","역량을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('210108', '창의성과혁신', '경영대학', '경영대학', 0, 3, '전선', '한재훈', '본 교과목은 지역사회문제해결 PBL과목으로 이론수업(화11-13시)과 실습(목11-13시)을 각각 주당 2시간에 걸쳐 진행한다. 이에 15주 차에 걸쳐서 기업경영에 있어서 창의성과 혁신에 대한 개념과 이론, 그리고 기업경영 사례를 학습한다. 이와 동시에 기업실무현장을 경험하는 과정도 포함한다. 이를 통하여 기업경영 현장 또는 창업을 위한 실현가능하고 창의적이며 혁신적인 신제품/신서비스 사업 모델 수립하는 방법을 학습하고 지역특성과 기업실무에 대한 이해가 고려된 실무중심의 사업모델을 수립하는 역량을 습득한다. 본 교과목은 앞서 기술했듯이 지역사회 문제해결 PBL 교과목으로서 이번 학기에는 지역기업인 남이섬과 함께 진행하고자 한다. 남이섬 이 처한 문제를 수업 중 배우는 창의성과 혁신기법을 활용하여 해결하는 비즈니스 모델을 수립하는 것이 수업의 핵심목표이다. 최근 기업경영 환경은 개인과 조직의 창의성이 요구된다. 특히 디지털기술기반의 AI, IoT, 자동화 등이 인강의 역할을 대체하는 최근 사회에서 인간만의 고유역량을 극대화하여 디지털기술과 차별화하는 것은 반드시 필요하다. 본 강의는 창의성의 기본개념, 창의적 산 업과 기업에 대해 학습하고 경쟁력과 성공의 결정요인을 창의성에서 그 해답을 찾고자 한다. 그리고 이론과 개념으로 배운 내용을 남 이섬과 함께하는 실습을 통해서 구체화하고 지역기업에 실질적인 도움을 주고자 한다. 창의성 관련 이론과 개념을 학습하고 창의적 사고기법에 대한 소개와 실습, 그리고 창의적 기업에 대한 분석을 통하여 개인과 조직의 창의적인 역량을 구축하는 프로세스를 학습 하고자 합니다. 창의성과 혁신에 대한 논의를 경영학 관점에서 접근하고 해석하여 기업실무에 활용할 수 있는 역량과 프로세스를 학 습하는 것이 본 수업의 주요 목표이다. 기본적으로는 강의실(화요일)에서의 대면강의로 진행하지만, 목요일 실습시간에는 팀별로 강의실, 남이섬 또는 기타 장소에서 프로젝 트를 진행한다. 지난 코로나 펜데믹 시대에 경험한 비대면 수업의 장점을 활용하기 위하여 상황에 따라서 비대면 강의 또는 면담, 팀실습활동도 실시 하여 미래지향적이고 혁신적인 강의방법을 지향하고자 한다. 2. 교과 목표 ■ 교과목표 ● 개인수준과 조직수준의 창의성 및 혁신에 대한 개념 이해 ● 수업 중 학습한 이론을 바탕으로 하여 창의적이며 혁신적인 비즈니스 모델 수립 ● 기업의 문제점과 해결방안을 현장실무 중심으로 접근 및 분석 (지역기업인 남이섬에 대해 이해하고 기업실무에서의 문제점과 해 결 방안 고민) ● 기업경영실무 참여를 기반으로 기업문제 해결을 위한 현장중심의 지역특성이 고려된 사업모델 또는 전략 수립 ● 팀단위로 프로젝트를 진행하여 팀상호간 협업과 소통에 대해 경험 및 학습 ● 지역특성을 고려한 사업게획서 기반의 창업 준비와 다양한 상황 모의체험(창업을 위한 준비와 기본을 모의경험) ● 위와 같은 학습과 실습을 통하여 아이디어를 사업화 역량 습득 및 제고', '{"있다","창의성과","창의적","남이섬","학생발표","이해할","비즈니스모델","문제해결","발굴","수립","사례","제안서","창의성을","혁신기업","대해","혁신","혁신에","또는","혁신관련","프로젝트"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('503201', '유기화학I', '자연과학대학', '자연과학대학', 0, 3, '전선', '이정태', 'This course aims to help students understand that organic chemistry plays an important role in every aspect of everyday life. We will focus on chemical bonding, functional groups, stereochemistry, and nomenclature, as well as key reaction mechanisms su ch as SN1/SN2 and E1/E2. English for chemists will be practiced throughout the course. The textbook, PPT slides, and exams (which account for 70% of the course) are in English. There will be a minimum of three exams. All exams are cumulative!!! Students can describe the characteristics of the molecules, functional groups, acids and bases, SN reaction, E reactions, and stere ochemistry.', '{"chapter","lecture","ppt","and","exam","reactions","the","organic","chemistry","functional"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('215119', '병원경영분석', '경영대학', '경영대학', 0, 3, '전선', '최재영', '최근 의료기관의 경영환경은 점차 악화되고 있다. 의사의 양산과 병상수의 증가 등으로 수요에 비해 공급의 초과현상이 초래되고 있 고, 낮은 건강보험수가제도 틀 안에서 급격한 의료제도의 변화 등으로 병원은 재정적으로 매우 어려워지고 있다. 특히 일부 병원들은 경영난으로 도산하고 있는 실정이며, 도산비율은 해마다 증가추세에 있다. 이와 같이 열악한 병원경영 환경하에서 생존하기 위해서 는 내실있는 경영은 필수이며, 내실있는 경영을 위해서는 기본적으로 병원 관련 내부/외부자료를 분석함으로써 합리적인 의사결정 을 내려야 한다. 본 교과목의 수강을 통해 학생들은 병원의 재무/비재무 자료를 분석하고 의사결정을 하는 데 필요한 정보를 생산하는 지식, 능력, 기 술 등을 학습할 수 있다. 학생들은 산업체와 대학이 공동으로 운영하는 본 교과목의 수강을 통해 실제 현업에서 쓰이는 병원경영분석 역량을 배양하게 될 것이다. 본 교과목의 수강을 통해 학생들은 병원의 재무/비재무 자료를 분석하고 의사결정에 필요한 정보를 생산하는 기술, 지식, 능력, 태도 등 산업계 관점의 병원경영분석 역량을 함양할 수 있다.', '{"의의와","있다","병원의","병원경영분석의","병원재무비율의","주차","구성요소","손익분기점분석의","신용분석의","병원부실예측","병원부실의","교과목의","수강을","학생들은","등으로","내실있는","재무","비재무","자료를","분석하고"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508206', '임상영양학및실험', '자연과학대학', '자연과학대학', 0, 4, '전선', '박경호', '- 영양소의 소화, 흡수, 체내 기능 및 대사과정 이해 - 주요 인체 질환(당뇨병, 신장질환, 심혈관계질환 등)의 발병 기전 및 질환 개선에서 주요 영양소의 역할 이해 - 식이요법 교과목과의 강의 연계성 강화 - 세포 또는 동물을 이용한 실험 수업 병행 - 영양교사양성을 목적으로 함(교직이수 학생의 수강 권장) - 인체 질환의 발병 및 개선에서 영양소의 역할 이해할 수 있다 - 영양소 결핍, 과잉 혹은 대사 불균형에 의해 유발되는 영양문제 혹은 질병의 진단, 예방 및 식이치료의 방안 제시할 수 있다', '{"참여도","주교재","질환","주차","구성요소","대사성","스트레스","질환의","보충","췌장","심혈관계","치료의","비만","부족한","비만의","정의","원인의","보강","호흡기질환","내분비"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('636219', '레저산업론(종합설계)', '경영대학', '경영대학', 0, 3, '전선', '고태규', '- 교육목표 - 레저레크리에이션이론과 산업에 대한 이해로 관련 산업 진로 및 취업 기회 제고 - 핵심목표 - 현대 레저레크리에이션 이론에 대한 이해 제고 - 한국 레저레크리에이션산업에 대한 진로 소개 및 취업 기회 제고 - 레저레크리에이션에 대한 이해력 제도 - 레저레크리에이션산업에 대한 진로 및 취업 기회 제고', '{"유인물","레저서비스","없슴","그룹프로젝트","청소년","레저","레저서비스시스템","제고","레저의","역할","여성","현실","장애인","진로","취업","기회","레저레크리에이션산업에","정의에","현대적","정의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('636256', '관광경영론(종합설계)', '경영대학', '경영대학', 0, 3, '전선', '전진희', 'An introduction to tourism from local to international levels; overview of the characteristics of the industry; emphasis on develop ment of natural, social, cultural and heritage resources of tourism; and understanding of various aspects (e.g., economic, technolo gical and political) of tourism. By the completion of this semester, each student will have the opportunities to describe: 1. the scope of the travel and tourism system 2. the terminology used in the travel and tourism industry 3. the economicl, social, cultural and environmental factors which impact the tourism industry 4. the economicl, social, cultural and environmental factorsl impacts of tourism on the host community 5. the external and internal factors which influence person''s decision to travel By the completion of this semester, each student will show enthusiasm on learning economical, social, cultural and environmenta l factors which impact the tourism industry.', '{"중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508207', '생애주기영양학', '자연과학대학', '자연과학대학', 0, 3, '전선', '민경애', '인간의 각 생애주기(임신기,수유기,영아기,청소년기,성인기,노인기)별로 인체의 발달과 특성에 따른 필요 영양소를 이해하고 적절한 영양소를 균형있게 섭취하여 건강한 삶을 영위할수있도록 이해하고 적용할수있다. 또한 생애주기별 생리학적, 영양학적,생화학적 특 성을 이해하고 올바른 식생활의 목표를 이해한다. 생애주기별 인체 발달의 특성을 이해한다 생애주기별 영양학적 특성을 이해하고 필요영양소를 알수있다', '{"영양","수업참여도","노트","출석및","주교재및","임신기","영양의","영아기","수유기","이해하고","이해한다","특성을","성장과","발달","주교재","강의노트","특성이해","유아기","노년기","노년기영양의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('636333', '호텔경영관리', '경영대학', '경영대학', 0, 3, '전선', '김도희', 'The objective of the course is to increase student''s understanding of fundamental overview of the hospitality and tourism industr y and to develop their skills and capabilities to solve hotel business problems and exploit business opportunities. 1) To increase student''s understanding of fundamental overview of the hospitality and tourism industry 2) To develop their skills and capabilities to solve hotel business problems and exploit business opportunites', '{"and","the","business","restaurant","recreation","understanding","hospitality","tourism","hotel","classification"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508209', '단체급식관리및실습', '자연과학대학', '자연과학대학', 0, 3, '전선', '이혜지', '본 교과목은 단체급식의 개념과 목적을 이해하고, 급식 운영 전반에 필요한 이론과 실제를 학습하는 것을 목표로 한다. 급식 대상자 의 특성에 따른 급식 계획, 식단 작성, 식재료 구매 및 관리, 조리 및 위생·안전 관리, 급식 시설 및 인력 관리, 원가 및 품질 관리 등 단 체급식 운영의 핵심 요소를 체계적으로 다룬다. 이를 통해 학생들은 다양한 급식 현장에서 요구되는 실무적 사고력과 문제 해결 능력 을 함양하고, 급식관리자로서의 기본 역량을 갖출 수 있도록 한다. 또한 본 교과목은 영양사 국가고시의 단체급식 및 급식경영 관련 영역과 연계되어, 이론적 이해를 바탕으로 국가고시 대비에 필요한 기초 지식과 응용 능력을 함께 강화하는 것을 목표로 한다. 본 교과목은 단체급식의 기본 개념과 운영 원리를 이해하고, 급식 대상자의 특성과 급식 환경에 맞는 급식관리 능력을 함양하는 것을 목표로 한다. 식단 작성, 식재료 구매 및 관리, 조리 및 위생·안전 관리, 급식시설 및 인력 관리, 원가 및 품질 관리 등 단체급식 운영 전반에 필요한 이론과 실제를 체계적으로 학습함으로써, 다양한 급식 현장에서 요구되는 실무적 사고력과 문제 해결 능력을 기른다. 또한 단체급식 및 급식경영 관련 이론을 바탕으로, 영양사 국가고시에서 요구되는 기초 개념과 이해도를 함께 강화하여 예비 영양사 로서의 전공 역량을 갖추도록 한다.', '{"이해한다","급식","관리","원칙을","메뉴","개념과","작성","구매","조리","기준","메뉴개발","운영","한다","단체급식","단체급식의","인력","급식관리자의","메뉴의","메뉴계획","절차"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('902564', 'AI스마트워크', '경영대학', '경영대학', 0, 3, '전선', '황현석', '본 교재는 경영학과 3-4학년 학생들을 대상으로 개설된 '';AI 스마트 워크'' 강의(3학점)의 내용을 담고 있다. 담당 교수는 황현석 교수이며, 본 강의는 학생들이 기업 현장에서 마주할 다양한 업 무 과제를 최신 생성형 인공지능(Generative AI) 기술을 통해 보다 효율적이고 창의적으로 해결 하는 방법을 학습하는 데 그 목적이 있다. 디지털 전환이 가속화되고 AI 기술이 비즈니스의 핵심 동력으로 자리 잡은 오늘날, 기업은 단순 한 지식 암기 능력을 넘어, 기술을 활용하여 실제 문제를 해결할 수 있는 실무형 인재를 요구한 다. 본 강의는 이러한 시대적 요구에 부응하여, 학생들이 다양한 생성형 AI 도구를 직접 다루고 실습함으로써 실질적인 비즈니스 역량을 함양하는 것을 목표로 한다. 강의를 통해 학생들은 다음과 같은 역량을 얻을 수 있다: 최신 생성형 AI 도구 활용 능력 : 텍스트, 이미지, 영상, 음악 등 다양한 형태의 콘텐츠를 생성 하는 AI 도구에 대한 깊이 있는 이해와 실무 적용 능력을 기른다. 업무 2. 교과 목표 ■ 교과목표 생산성 향상 전략 : AI를 활용하여 보고서 작성, 시장 조사, 데이터 분석, 프레젠테이션 제작 등 반복적이고 시간이 많이 소요되는 업무를 자동화하고, 핵심적인 의사결정에 더 많은 시간을 할애할 수 있는 전략을 학습한다. 비즈니스 콘텐츠 제작 능력 : 기업의 마케팅, 홍보, 내부 커뮤니케이션에 필요한 카드 뉴스, 쇼츠 영상, 배경음악 등 고품질의 미디어 콘텐츠를 직접 제작하는 능력을 갖춘다. 문제 해결 및 창의적 솔루션 개발 : 주어진 비즈니스 문제에 대해 AI를 활용하여 데이터를 분 석하고, 창의적인 해결책을 도출하며, 이를 설득력 있는 비즈니스 제안으로 발전시키는 경험 을 한다. AI 시대의 커뮤니케이션 능력 : AI와의 효과적인 소통 방법(프롬프트 엔지니어링)을 익히고, AI가 생성한 결과물을 비판적으로 검토하고 개선하여 최종 결과물의 완성도를 높이는 커뮤 니케이션 역량을 강화한다', '{"자체","강의자료","활용하여","비즈니스","생성","생성형","활용한","같은","영상","기법을","습득한다","도구를","제작","방법을","이미지","쇼츠","이를","이해하고","하는","있는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508212', '식품미생물학및실습', '자연과학대학', '자연과학대학', 0, 3, '전선', '심재훈', '''발효와 부패의 차이를 알고 있나요?'' ''바이러스와 박테리아는 어떻게 다른가요?'' ''효소는 무엇이고 효모는 무엇인가요?'' ''식중독균을 제거 하려면 어떻게 해야 하나요?'' 식품을 전공하는 학생들이 이러한 간단한 질문도 대답 못한다면 안되겠지요. 이 과목에서는 일반 미생물학에서 습득한 지식을 기초로 식품 미생물을 이해하고 (미생물의 분류, 생리대사, 분자생물학) 응용하는데 필요한 기본 지식을 공부합니다. 또한, 식품관련 미생물에 대한 기본적인 지식을 갖추고 실험 실습을 통해 이를 활용하여 이 과목을 마무리 할 때는 적어도 미생물이 무엇이고, 발효가 어떠한 것인지 이해해서 식품전공자 또는 영양교사로서의 기본적을 역량을 갖추도록 할 예정입니다. 일반 미생물학에서 습득한 지식을 기초로 식품 미생물을 이해하고 활용하는데 필요한 기본 지식을 갖춤', '{"미생물의","실험실습","미생물","단백질","유전자","분리","정제","산업적","지식을","배지","주차","구성요소","활용법에","제한효소","이용","분자생물학","실험","어떻게","무엇이고","일반"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('902565', '비즈니스앱기획', '경영대학', '경영대학', 0, 3, '전선', '황현석', '비즈니스에 사용되는 앱을 코드없이 생성하는 것을 목표로 함 비즈니스에 발생하는 요구사항에 대한 분석과 앱을 통한 요구사항 해결을 경험함 앱의 주요 기능에 대한 기능요구 정의서 작성과 앱의 UI/UX 디자인에 대한 결과물 도출 앱의 프로토타입 생성과 팀원내 배포(교수자 포함) 지식: 앱의 기본 기능과 화면 구성 기술 : 데이터 베이스의 CRUD 기능 태도 : 앱 수용 자세', '{"교재","기반","기능","앱의","비즈니스","정의","만들기","아이디어","개발","보기","간단한","코딩","설계","콘텐츠","도출","기말과제","앱을","기회","프롬프트","활용한"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508214', '조리원리및실험', '자연과학대학', '자연과학대학', 0, 3, '전선', '임순성', '조리 및 식품영양관련 분야를 전공하는 학생들이 식품의 성분과 조리원리를 이해하고, 조리 과정에서 일어나는 식품의 물리·화학적 변화의 원리를 이해하고 실습으로 실기능력을 습득함으로서 영양사, 조리사 및 영양교사 양성에 도움이 될수 있도록 하며, 영양교사로서의 역량 함양을 목표로함. (구술시험을 통하여 한식조리사 확보를 목표로함) 조리 및 식품영양관련 분야를 전공하는 학생들이 식품의 성분과 조리원리를 이해하고, 조리 과정에서 일어나는 식품의 물리·화학적 변화의 원리를 이해하고 실습으로 실기능력을 습득함으로서 영양사, 조리사 및 영양교사 양성에 도움이 될수 있도록 한다. (구술시험을 통해 한식조리사 확보를 목표로함)', '{"관련동영상","시청","한식조리사를","요리실습","공모전","반죽과","썰기","조리","한식조리사","동영상","제작","주차","구성요소","식품의","이해하고","계획서","전분","당류","조리절차","암기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('205290', '경영분석(종합설계)', '경영대학', '경영대학', 0, 3, '전선', '조규성', '경영분석(종합설계)은 금융감독원 전자공시시스템(DART)에서 기업이 공시한 재무제표를 내려받아 기업의 경영상태를 분석하고 기업 가치를 평가하는 과목이다. 전자공시시스템(DART)에서 분석하고자 하는 기업의 6년간 재무제표를 내려받아 정리한다. 이 자료를 바 탕으로 기업에 대한 재무비율을 계산한 후 경쟁기업 및 산업평균 재무비율과 비교하여 대상기업의 경영상태를 분석한다. 그리고 주 가배수모형, 배당할인모형 및 잉여현금흐름할인모형을 이용하여 기업의 내재가치를 계산하고 현재 주식가격과 비교하여 매수, 중립, 또는 매도 의견을 제시한다. 기업이 실제로 발표한 재무제표를 이용하여 기업의 경영상태를 분석하고 기업가치를 평가함', '{"사례분석","자료","만들기","기업의","재무제표를","경영상태를","배당할인모형","전자공시시스템","에서","기업이","내려받아","분석하고","비교하여","이용하여","비교분석과","구조분석","추세분석","비율분석","분석과","종합비율분석"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509518', '전공축구', '자연과학대학', '자연과학대학', 0, 1, '전필', '유신환', '이 교과목은 현대생활에서의 건강과 체력에 대한 이해를 바탕으로 축구의 특성과 운동효과 등 이론과 실제적인 기술훈련, 전술훈련, 심판법 등을 체득하여 지도자로서의 자질을 향상시키는데 본 강의의 목적이 있다. 지도자로서 요구되는 축구의 이론과 실제를 체득함', '{"통한","시범","실기기능","설명","리프팅","드리블","인사이드","인프런트","인스텝","아웃사이드","위치선정","테클","심판법","등을","축구의","볼다루기","볼다투기","실습을","기능","설명및"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508301', '영양생화학I', '자연과학대학', '자연과학대학', 0, 3, '전선', '강일준', '식품 영양학의 기초가 되는 세포내 생명활동을 통제하는 기본적 메커니즘을 배우고 생체의 구성 물질, 대사의 기본개념과 에너지의 발생을 학습함으로서 식품성분/영양소와 인체대사와 관련된 생화학적 지식을 보다 체계적이며 정확히 이해하기 위한 목적으로 개설 됨. 본 수업에서는 생명 및 식품성분, 에너지 및 기초 대사 메커니즘을 통해 생화학의 전문성을 함양시킬 수 있고, 임상능력을 갖춘 영양 교사 역량 향상 및 양성에 기여함. 본 수업을 통해 다음과 같은 지식을 습득해야 한다. -유기생물체 분자의 작용기 및 생체분자에 대한 지식 -생화학과정 및 생화학반응에 대한 지식 -에너지 및 대사, 생물의 질서, 유전정보과정에 대한 지식 -살아있는 세포 및 동물세포구조에 대한 지식 -열역학 제 1, 2법칙, 자유에너지개념에 대한 지식 -표준 자유에너지 변화의 의미와 연관반응에 대한 지식 -ATP의 가수분해와 자유에너지, 인산기전이전위에 대한 지식 -대사의 기본개념에 대한 지식 -해당과정을 시작으로 탄수화물 중심의 대사과정에 대한 지식', '{"관해","이해한다","아미노산의","단백질의","연습문제풀이","습득한다","지식","메커니즘을","비대면","온라인","이해하고","에너지","대사","자유에너지","구조에","단당류의","반응과","개요","대해","살펴본다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508303', '식품가공학', '자연과학대학', '자연과학대학', 0, 3, '전선', '심재훈', '''인간이 식품을 가공하는 이유는 무엇일까요?'' 간단한 질문이지만 대답의 종류는 많고 정답을 찾기는 무척(!) 어렵습니다. 이 과목에서는 식품가공학 강의를 통하여, 식품원료처리, 가공에 대한 기초 및 응용적 접근방법을 전달하여. 학생들의 식품 및 식품산 업에 대한 전반적인 이해를 높이고자 합니다. 또한, 다양한 식품가공 및 저장관련 지식을 바탕으로 실생활에서의 활용 방안을 모색하 여, 한 학기 수강이후 학생들이 적어도 시중에 상용화된 가공식품에 대한 가공공정에 대하여 한번 더 생각할 수 있게할 예정입니다. 수업에 적극적으로 참여하는 학생들의 경우 식품전공자 또는 영양교사로서 스스로 시중 제품들의 문제점을 발견하고 해결하고자 아 이디어를 제시할 수 있는 역량을 갖추리라 기대합니다. - 식품원료처리, 가공에 대한 기초 및 응용적 접근방법을 전달하여. 학생들의 식품 및 식품산업에 대한 전반적인 이해를 높임 - 다양한 식품가공 및 저장관련 지식을 바탕으로 실생활에서의 활용 방안을 모색', '{"식품의","두류","식품가공법에","비가열적","처리","과채류의","활용방안","과일가공","활용에","식품가공학","학생들의","전반적인","수분활성도","식품원료처리","가공에","응용적","접근방법을","전달하여","식품","이해를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206102', '재무학원론', '경영대학', '경영대학', 0, 3, '전선', '박윤정', '본 과목은 금융재무학의 기초 과목으로, 재무적 의사 결정의 기초 이론과 적용에 대한 기본적인 이해를 돕고자 한다. 금융시장의 구조를 살펴보고, 재무 이론의 기초로 재무제표 및 현금흐름 분석 방법을 이해하고, 대표적인 금융상품인 주식과 채권의 개념과 가치평가에 대해 다룬다. 또한 투자의 가장 중요한 본질인 수익과 위험의 관계를 살펴보고, 그 측정 방법과 위험을 관리하는 방법에 대해 논의한다. * 향후 사회생활 및 실생활에 있어 금융시장, 기업재무 및 투자 관련 기초 정보에 대해 익숙한 태도를 습득 * 금융재무학 전공자로서의 기초적 지식의 배양 본 과목은 플립러닝으로 운영되므로 pre-class, in-class, post-class 세 단계로 나누어 진행된다. - pre-class : 학습주제에 대한 동영상 수강, 동영상에서 제공된 필기를 따라 쓰면서 이해력을 높이고자 하며 생소한 개념을 여러번 재 생시켜 보면서 이해할 수 있게 도울 것임. - in-class : 학습주제에 대한 심화학습, 실제 예제에 대한 이론 적용을 통해 이해도를 높이고자 함. - post-class : 학습한 내용을 퀴즈 및 과제 등을 통해 복습하고 학습 성취도를 점검.', '{"퀴즈","비대면","녹화강의","대면","학습자료","지참","대면강의","투자설계","재무관리","금융시장의","현금흐름","주차","구성요소","채권","풀이","주식","투자수익률과","위험","대해","마감"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206208', '재무관리론', '경영대학', '경영대학', 0, 3, '전선', '김태규', '본 과목에서는 재무관리의 기본 개념과 기업의 재무관리 의사결정에 대해 학습한다. 기업의 재무관리 의사결정은 투자의사결정과 자본조달결정으로 구분된다. 본 과목은 재무관리 입문 과목으로 기업의 투자의사결정 에 대해 논의한다. 이를 위한 선행 지식으로 먼저 가치평가에 대해 공부한다. 가치평가의 기초로 복리계산과 할인계산을 다루고 이를 바탕으로 현금흐 름의 할인에 의한 가치평가를 학습한다. 다음으로 학습한 현금흐름할인법을 자금조달을 위해 기업이 발행하는 장기 증권, 즉 채권과 주식의 가치평가에 적용하여 가치평가에 대한 이해를 제고한다. 이러한 재무관리 선행 지식을 바탕으로 기업의 투자의사결정에 대해 논의한다. 투자의사결정은 투자안의 현금흐름 파악과 투자안의 수익성 평가로 이루어진다. 투자안의 현금흐름 파악을 위해서는 기업의 재무제표에 대한 이해가 필요하다. 추정재무제표 작성을 통해 투자안의 미래 현금흐름을 추정하고 순현가법과 내부수익률법과 같은 투자평가방법으로 투자안의 수익성 을 평가하여 투자의사결정을 내리게 된다. 기업의 투자의사결정을 학습하기 위해서는 가치평가방법, 추정재무제표 작성방법, 투자안 평가방법 등 다양한 기법에 대한 종합적 이 해가 요구된다. * 현금흐름의 가치평가 원리 이해 * 기업의 자본예산에 대한 이해 제고', '{"강의실에서의","대면","질문","퀴즈","등을","통한","학습내용","점검","가치평가","현금흐름","기업의","투자안의","재무관리","채권의","세금","가치평가의","순현가법과","현금흐름의","대해","추정재무제표"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508321', '지역사회영양학', '자연과학대학', '자연과학대학', 0, 3, '전선', '박소현', '지역사회의 영양문제를 이해하고 지역사회 주민들의 건강증진을 위해 알아야하는 기초 개념과 방법론을 익힌다. 또한 실제 지역사회에서 일어나고 있는 다양한 사례학습을 통해 향후 자신의 영양프로그램과 정책을 개발할 수 있도록 다양한 강의 과 토론, 활동에 참여한다. 영양교사양성에 도움이 되는 기초적인 지역사회영양학을 배우고 실제 영양교사가 되어서 활용할 수 있도록 한다. 지역사회영양의 다양한 이슈들에 대해 학습하며, 지역사회 구성원의 영양문제를 해결할 수 있는 다양한 도구를 학습하고 적용할 수 있다.', '{"있다","지역사회영양","강의와","대해","활동에","필요한","지역사회","연구와","자료수집","양적","자료에","데이터","익숙해지기","정책","프로그램의","있는","프로그램과","건강이론","질적","국제영양"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508401', '영양사현장실습', '자연과학대학', '자연과학대학', 0, 3, '전선', '박경호', '영양사현장실습은 예비 영양사가 급식 및 영양관리 현장에서 요구되는 전문 직무를 실제로 경험하고, 이론 중심의 전공 지식을 실무 에 적용할 수 있도록 설계된 현장 중심 교과목이다. 본 교과목은 학교급식소, 병원, 산업체, 사회복지시설 등 다양한 급식·영양관리 현장을 기반으로 급식 운영, 식단 관리, 위생·안전 관리, 영양 상담 및 행정 업무 전반에 대한 실습을 수행하도록 한다. 학생은 현장 실습을 통해 영양사의 역할과 책임을 이해하고, 관련 법·제도 및 전문직 윤리를 체득한다. 이를 통해 학생은 급식 및 영양관리 업무 수행 능력, 현장 문제 해결 능력, 의사소통 및 협업 역량을 종합적으로 함양하며, 예비 전문 직 종사자로서의 직업 의식과 진로 방향을 구체화하는 것을 목표로 한다. 영양사현장실습은 영양사 면허 취득을 준비하는 학생을 대상으로, 급식 및 영양관리 현장에서 요구되는 전문 지식과 실무 능력을 실 제 환경에서 적용·체득하도록 하는 데 목적이 있다. 본 교과목은 학생이 급식 및 영양관리 현장의 운영 체계와 관련 법·기준을 이해하고, 위생·안전·영양관리 업무를 현장에서 직접 수행 함으로써 실무 역량을 강화하며, 전문직 영양사로서의 책임감, 윤리 의식, 협업 태도를 함양하도록 하는 것을 목표로 한다. 이를 통해 학생은 이론과 실무를 연계한 현장 적응 능력을 갖추고, 미래 영양사로서의 직무 수행 역량과 진로 의식을 종합적으로 완성하게 된다 .', '{"급식","영양관리","현장에서","전문","현장","요구되는","한다","학생은","능력을","영양사현장실습은","예비","교과목은","운영","관리","위생","안전","업무","실습을","이해하고","전문직"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206212', '재무경제학', '경영대학', '경영대학', 0, 3, '전선', '변희섭', '국가경제적 측면에서 금융시장은 자원의 효율적 배분과 지속 가능한 성장을 위해 중요하게 인식될 수 있다. 개인의 재무금융적 의사결정의 측면에서도 금융시장은 새로운 투자기회의 제공, 위험회피, 유동성 등을 제공하기 때문에 그 중요성이 강조되고 있다. 따라서, 금융시장이 어떤 요소로 구성되며, 어떻게 작동하는지를 이해하는 것은 다양한 금융거래, 경제현상 등을 이해하는데 유용하 다 할 수 있으며, 매순간 경제적, 재무적 의사결정에 직면하는 여러 경제주체에 있어 필수적이라 할 수 있다. 뿐만 아니라, 경제적 이론에 기초하여 금융시장과 경제현상을 이해하는 것은 논리적 사고의 개발에 큰 도움이 되며, 여타 금융재무 관련 교과목에 대한 기초지식을 쌓는 측면에서도 중요하다. 본 교과목은 금융시장 및 금융시스템에 대한 개관을 습득한다. 다음으로, 이자율의 위험구조와 기간구조에 기초하여 어떻게 금융시장의 균형이 도출되는지에 대한 이론 및 실무현상에 대해 논의한 다. 이에 더하여 대표적인 금융시장으로 주식시장의 가격 형성 원리에 대한 논의도 이루어진다. 다음으로 금융시스템을 구성하는 핵심적 요소로서 금융기관의 중요성과 금융규제(금융하부구조)의 필요성에 대한 경제적 분석을 제 공한다. 마지막으로, 통화정책의 목표와 수단들을 논의함으로써 국가의 재무금융적 의사결정이 실물경제에 어떻게 파급되는지를 습득한다. 경제학적 접근을 바탕으로 금융시장(채권시장, 주식시장 등)의 가격결정 과정을 이해 및 응용할 수 있다. 금융기관의 필요성과 금융제도의 유형을 이해할 수 있다. 통화정책의 종류와 작동원리를 이해할 수 있다.', '{"퀴즈","활용한","결과","확인","실무사례","조사","응시여부","참여도","강의노트와","녹화","컨텐츠를","사전학습","풀이를","통한","학업","추가설명","제시","지식을","핵심내용","요약정리"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206310', '금융기관론', '경영대학', '경영대학', 0, 3, '전선', '변희섭', '* 본 교과목은 생성형 AI 결합 교과목으로, 한림 AI 교육 솔루션(AI 조교)이 교과목 운영상 활용됩니다. ** 수강을 원하는 학생께서는 AI 활용 내역 제공에 필수적으로 동의해주셔야 합니다. 금융기관은 경제주체 간 자금흐름에 있어 중추적인 역할을 수행하기 때문에 금융시장의 가장 중요한 구성요인이며, 더 나아가 국민경제의 안정적인 발전을 위한 필수 불가결한 요소로 고려되고 있다. 금융기관은 위험과 수익의 상충관계에 기초한 금융상품을 다루어 여타 일반회사와 사업구조, 경영행태 등 다양한 측면의 특수성을 가지고 있다. 이러한 특성들을 감안할 때, 금융재무학은 물론, 더 나아가 금융시장에 대한 폭 넓은 이해를 위해서는 금융기관의 역할과 기능, 이들을 둘러싼 금융하부구조 등에 대한 지식의 습득이 중요하다 할 수 있다. 본 교과목은 은행, 보험회사, 증권회사, 저축은행 등의 금융시장 내 역할과 기능에 대해 이해하고, 규제산업으로서 금융산업의 미시건전성, 거시건전성 규제의 틀과 그 이유에 대한 제반지식을 습득하는데 주목적이 있다. 더불어 국민경제 내 금융기관이 수행하는 금융중개기능의 본질에 대한 이해를 바탕으로 다양한 금융기관의 형태 및 그들의 운영 상황을 인식하고, 금융시장에서 수행하는 각기 다른 역할 및 경영 상의 차이점에 대해서도 논의한다. 마지막으로 금융기관이 직면하는 다양한 리스크의 형태, 리스크를 관리하기 위해 활용되는 다양한 수단과 기법, 그리고 이러한 수단들을 활용한 최적의 리스크 관리 방법 등에 대한 논의도 제공될 것이다. 금융제도의 종류와 내용을 이해할 수 있다. 금융기관의 가치 및 경영성과를 평가할 수 있다. 금융기관의 위험관리 방안을 제시할 수 있다.', '{"금융기관의","담당교수의","수강학생의","토의","한림","교육","솔루션","조교","활용하여","생성한","위험관리","수업자료","가치평가","경영성과","있다","퀴즈","응시","금융제도의","금융감독","금융시장의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508416', '실험조리및식품평가', '자연과학대학', '자연과학대학', 0, 3, '전선', '강일준', '식품 분석법을 폭넓게 실습하면서 식품을 구성하고 있는 각종 성분분석에 관한 지식을 강의와 실험을 통해 습득하며, 식품의 신선도 평가 및 일반성분 분석을 통해 식품산업현장 실무에 응용, 활용할 수 있는 능력을 배양하기 위한 목적으로 개설되었음. 식품기사 자격증시험을 대비하며, 각종 식품의 성분분석을 통해 식품품질 및 식품평가 연구능력을 함양시킬 수 있고, 실무능력을 갖 춘 영양교사 양성에 기여함. 본 수업을 통해 다음과 같은 지식을 습득해야 한다. -수분, 단백질, 지질 등 일반성분의 이론 및 분석법에 대한 지식 -식품 중 유기산, 과산화물가 등 식품품질관리에 필요한 지식 및 분석능력 -식품의 화학적 변화에 대한 이론 및 실습 -신선도 검사 및 식품위생관련 미생물 이론 및 분석법에 대한 지식', '{"이해한다","실험","프로토콜","대해","핸드아웃","원리에","실험실습결과리포트","식품","실험실습결과에","따른","원리를","계산한다","비대면","온라인","정량","식품의","의한","한다","실험실습을","진행한다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508429', '영양교육및상담실습', '자연과학대학', '자연과학대학', 0, 3, '전선', '정사랑', '본 과목은 지역사회 주민의 식생활 행동 변화를 유도하기 위한 영양교육 및 상담 역량을 갖춘 영양교사·영양사를 양성하는 것을 목표 로 한다. 이를 위해 행동변화 이론을 기반으로 한 영양교육의 원리와 전략을 이해하고, 실제 현장에서 적용 가능한 영양교육 계획 수 립, 교육매체 활용, 교육방법 선택, 효과 평가 과정을 체계적으로 학습한다. 또한 영양상담 실습을 통해 대상자 특성에 따른 의사소통 기술을 익히고, 개인 및 집단을 대상으로 한 실천 중심의 영양교육·상담 수 행 능력을 함양함으로써 지역사회 영양상태 개선과 건강증진에 기여할 수 있는 전문성을 강화한다. 1. 지역사회 주민의 식생활 행동 변화를 유도하기 위한 영양교육 및 상담의 이론적 근거를 이해한다. 2. 행동변화 이론을 적용하여 대상자 중심의 영양교육 계획을 수립할 수 있다. 3. 다양한 영양교육 매체와 교육방법을 적절히 제작·선택·활용할 수 있다. 4. 영양교육 및 상담의 과정과 효과를 평가할 수 있는 능력을 함양한다. 영양상담 실습을 통해 의사소통 기술과 현장 적용 역량을 강화하여, 전문적인 영양교사·영양사로서의 실무 능력을 갖춘다.', '{"영양교육","교재","영양교육의","영양상담","대상자","사례","계획","매체와","상담","행동변화","상담의","식행동의","선택과","상담을","미디어의","영양상담의","생애주기별","영유아","어린이","청소년"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508510', '캡스톤디자인-식품영양학', '자연과학대학', '자연과학대학', 0, 3, '전선', '박경호', '캡스톤디자인？식품영양연구및실험II는 식품영양학 전공 지식을 바탕으로 학생이 희망하는 교수 연구실에 소속되어 실제 연구 프로 젝트에 참여함으로써, 연구 기획부터 실험·자료 분석·결과 도출·발표에 이르는 전 과정을 경험하도록 설계된 전공 심화 교과목이다. 본 교과목에서 학생은 지도교수의 연구 주제에 따라 실험 설계, 분석 기법, 연구 윤리, 결과 해석 등을 직접 수행하며, 이론 중심 학습 을 넘어 연구 기반 문제 해결 능력과 전공 실무 역량을 종합적으로 함양한다. 이를 통해 학부 수준의 연구 수행 능력을 완성하고, 대학원 진학 및 연구·산업 현장 진출을 위한 기초 연구 역량을 강화한다. 1. 식품영양학 분야의 전공 이론을 실제 연구 현장에 적용하여 연구 수행 역량을 강화한다. 2. 연구 기획, 실험 수행, 자료 분석, 결과 해석의 전 과정을 경험하여 문제 해결 중심의 실무 능력을 함양한다. 3. 연구 윤리와 협업을 기반으로 전문 연구자로서의 태도와 책임 의식을 확립한다.', '{"전공","실험","결과","역량을","식품영양학","실제","자료","과정을","해석","함양한다","능력을","강화한다","분야의","이론을","현장에","적용하여","기획"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206421', '계량재무분석', '경영대학', '경영대학', 0, 3, '전선', '박윤정', 'Decisions for financial management involve dealing with partial information in an uncertain environment. This course shall develo p a foundation of probability and statistics and introduce data analysis tools that can generate information useful in financial ma nagement. The objective of this course is to familiarize students with fundamental knowledge of mathematics and statistics related to financ ial management and to improve their quantitative analysis skills by practical application using the computer. Topics for this cours e include estimation, hypothesis testing, and simple linear regression model. 본 과목은 플립러닝으로 운영되므로 pre-class, in-class, post-class 세 단계로 나누어 진행된다. - pre-class : 학습주제에 대한 동영상 수강, 동영상에서 제공된 필기를 따라 쓰면서 이해력을 높이고자 하며 엑셀실습을 여러번 재생 시켜 보면서 따라해 볼 수 있게 함. - in-class : 학습주제에 대한 심화학습, 실제 예제에 대한 이론 적용을 통해 이해도를 높이고자 함. - post-class : 학습한 내용을 퀴즈 및 과제 등을 통해 복습하고 학습 성취도를 점검.', '{"대면","퀴즈","비대면","녹화강의","학습자료","지참","대면강의","따라","마감","학습주제에","높이고자","휴강에","목요일"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('508518', '식품화학Ⅰ', '자연과학대학', '자연과학대학', 0, 3, '전선', '임순성', '식품화학(食品化學, 영어: food chemistry)은 모든 생물학적, 비생물학적 음식 성분에 대한 화학구조와 성질들 그리고, 생체에서의 상 호 작용에 대한 학문이다. 생물학적 물질에는 고기, 새고기, 상추, 맥주, 젖 등을 예로 들 수 있으며, 수분, 탄수화물, 지질, 단백질, 비타 민, 무기질과 같은 주요 성분과 효소, 식품 첨가물, 향료, 착색제와 같은 부가적인 식품성분 영역을 아우른다. 식품에 구성 성분들의 화학적 성질을 파악함으로써 식품의 생산, 가공, 저장 간에 나타날 수 있는 변화를 예측하고 이에 대응할 이론적 근거를 익힘으로써 다양한 식품화학 문제에 적응할 수 있도록 원리 위주의 교육을 진행하며, 영양교사로서의 역량함양을 목표로한다. 식품화학의 기초적이고 전반적인 내용을 학습하는 것으로 식품을 구성하는 성분들에 대한 구조에 기반한 성질과 식품조리 과정에서 야기 될 수 있는 변화에 대한 이해를 각 성분별 순차적으로 힉습하는 것이 목표임.', '{"교재","구조","기능","특징","성질","단백질","단백질의","탄수화물","지질","성분들의","식품화학","탄수화물의","지질의","비타민","비타민의","전체","효소","생물학적","같은","있는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206422', '금융투자전략', '경영대학', '경영대학', 0, 3, '전선', '조규성', '이 과목에서 학생들은 채권, 선물, 스왑, 옵션에 대한 기본 개념을 이해하고 각 자산의 가격변동 위험을 관리하기 위한 투자전략을 공 부한다. 먼저 채권가격을 계산하는 방법을 공부한 후 채권포트폴리오의 가치를 지키기 위한 소극적 투자전략과 이자율 변화를 예측 하여 높은 수익을 얻기 위한 적극적 투자전략을 공부한다. 그 이후 선물 기초개념과 가격결정방법을 공부한 후 이를 이용하여 기초자 산의 위험을 헤지하는 방법과 포트폴리오의 위험을 관리하는 방법을 배운다. 스왑에서는 거래 당사자가 스왑을 이용하여 차입비용을 줄이는 방법을 공부한다. 옵션에서는 기초개념과 옵션을 이용한 다양한 투자전략을 공부한다. 마지막으로 옵션가격결정모형을 공부 하고 옵션가격결정모형을 이용한 동적자산배분전략을 공부한다. 첫째, 채권가격을 계산하는 방법과 채권투자전략을 이해함 둘째, 선물가격을 계산하는 방법과 위험관리 방법을 이해함 셋째, 스왑을 이용하여 차입비용을 줄이는 방법을 이해함 넷째, 옵션을 이용한 다양한 투자전략을 이해함', '{"이용한","방법을","투자전략을","공부한다","스왑을","이해함","투자관리","위험을","계산하는","소극적","적극적","이용하여","방법과","위험관리","선물","채권가격을","공부한","기초개념과","차입비용을","줄이는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509101', '육상I', '자연과학대학', '자연과학대학', 0, 1, '전선', '신근춘', '육상 경기종목은 트랙경기, 필드경기, 도로경기로 분류된다. 트랙경기는 트랙에서 이루어지는 달리기 경기이며, 필드경기는 멀리 또 는 높게 점프하는 도약경기, 공, 원반 창을 던지는 투척경기, 경기장 밖에서 이루어지는 마라톤 또는 경보와 같은 도로경기가 있다. 즉 육상 경기는 모든 스포츠의 기본이 되는 능력을 겨루는 스포츠이다. 본 수업을 통하여 육상 경기에서 실시되고 있는 각 종목(트랙과 필드)의 특성을 이해하고 종목별 훈련법, 과학적인 원리뿐만 아니라 기술지도 방법을 체득함으로서 유능한 지도자로서의 자질을 갖추도록 한다. 1.육상 경기의 종목(트랙, 필드, 도로)을 이해한다. 2.육상경기의 다양한 체력 훈련 방법을 습득한다. 3.육상경기의 종목별 훈련 방법과 전술을 이해한다. 4.육상경기의 종목별 심판 규칙과 심반법을 습득한다.', '{"영상","도약경기","높이뛰기","허들","훈련법","스타트","장애물","경기","넘기","곡선주로","달리기","자세","허들경기","허들링","종목별","육상경기의","육상","육상경기","기초훈련","단거리"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206423', '부동산설계론', '경영대학', '경영대학', 0, 3, '전선', '조규성', '부동산은 주거 및 사업을 위한 공간을 제공해 주는 자산이다. 한국에서 부동산은 개인이 보유한 자산 중에서 약 70~80%를 차지하여 다른 자산에 비하여 그 비중 매우 높다. 따라서 개인이 부동산에 대하여 잘 이해하고 효율적으로 관리하는 것이 중요하다. 이 과목에 서 부동산의 개념, 종류 및 특성을 살펴본 후 부동산경제 및 시장의 특성과 정부의 부동산 시장 개입을 알아본다. 그 이후 부동산의 권리관계, 매매 및 주택(상가)임대차보호법을 공부한다. 마지막으로 정부의 부동산 관련 정책, 건축규제, 주거환경정비법 및 부동산 투자에 대하여 공부한다. 첫째, 부동산 시장의 특징과 정부의 개입을 이해함 둘째, 부동산 권리관계와 임대차보호법을 이해함 셋째, 정부의 부동산 정책과 부동산 투자를 이해함', '{"부동산","부동산의","정부의","부동산경제","건축규제","주거환경정비법","이해함","부동산은","개인이","대하여","시장의","개입을","임대차보호법을","공부한다","부동산시장","부동산권리","부동산공부","경매와","공매","중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509102', '체조I', '자연과학대학', '자연과학대학', 0, 1, '전선', '신근춘', '- 체조를 통해서 신체를 균형있게 만들고 교정할수있다. - 다양한 체조(스트레칭, 국민,청소년 체조)의 도해를 이해 하고 실시할 수 있다 - 다양한 동작에 도전함으로써 신체와정신을 조절하고 통제하는 자기관리 능력을 함양 할수있다. - 전신을 움직이므로 신체기능과 체력을 향상할수있으며 동작의 과학적원리를 이해하고 실천하면서 성취감과 자신감을기를수있다 체조는 모든 종목의 기본입니다. 맨손 체조는 기구나 도구를 사용하지 않고 맨손으로 실시하며 신체의 균형과 조화, 자세교정, 기초체력 향상, 기초운동으로서의 유연 성을 습득하여 운동 시 상해를 예방할수있도록 하며, 맨몸체조는 몸 전체를 이용하여 탁월한 기술 구사 및 아름다움을 표현함으로써 신체를 조화롭게 발달시킬 수 있으며 몸을 보호하는 능력을 기를 수 있다. 다양한 종류의 체조의 이론과 실기를 통하여 학습하고 적 응 함으로써 일상생활에서 자연스럽게 활성화 하는 데 있다.', '{"체조를","있다","할수있다","체조","청소년","보조","실시한다","유의점을","맞추어","연습한다","동영상을","물구나무서기","앞구르기","스트레칭","이해하고","음악에","영상","뒤구르기","국민","도해를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509104', '스포츠융합과학론', '자연과학대학', '자연과학대학', 0, 2, '전선', '한승백', '본 과목은 체육학 및 스포츠 과학의 세계에 첫발을 내딛는 신입생들을 위한 입문 과정으로, 현대 사회에서 스포츠가 어떻게 다양한 학문적 영역과 융합하여 발전하고 있는지 그 지형도를 탐구한다. 단순히 운동 기술을 배우는 것을 넘어, 생리학·심리학·사회학·역학 등 전통적인 스포츠 과학의 기초를 다지고, 이를 데이터 과학·인공지능·ICT 등 미래 기술과 결합하여 스포츠의 새로운 가치를 창출하는 법을 학습한다. 본 강의는 크게 세 가지 핵심 축으로 구성된다. 1. 학문적 토대: 체육학의 역사적 배경과 철학적 기초를 이해하고, 운동 과학의 핵심 분과 학문들을 개관한다. 2. 융합과 확장: 스포츠가 심리, 사회, 경제, 그리고 공학적 요소와 어떻게 결합하여 현대인의 삶의 질을 높이고 산업적 가치를 창출하 는지 분석한다. 3. 미래와 비전: 급변하는 기술 환경 속에서 스포츠 과학이 나아갈 방향을 모색하며, 학생들이 향후 전공 심화 과정에서 자신만의 전 문 분야를 찾을 수 있도록 진로 탐색의 기회를 제공한다. 본 교과를 통해 학생들은 스포츠를 과학적·인문적·기술적 관점에서 통합적으로 바라볼 수 있는 안목을 기르며, 미래 스포츠 융합 전문 가로서 갖춰야 할 기본적인 소양을 습득하게 될 것이다. 체육 전반에 관해 이해를 높인다. 스포츠과학 전반에 관해 이해를 높인다. 스포츠에 관한 이해를 높인다.', '{"스포츠","운동","미래","가치","기술","체육학","과학의","스포츠가","움직임의","스포츠와","심리학","데이터","과학","스포츠의","철학적","심리","비전","융합","이해를","높인다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206425', '투자설계론', '경영대학', '경영대학', 0, 3, '전선', '조규성', '이 과목에서 학생들은 금융자산과 투자이론에 대하여 공부한다. 먼저 투자 대상이 되는 금융자산의 종류를 살펴본 후 금융거래제도 를 공부한다. 포트폴리오이론에서 분산투자효과를 공부하고 자산가격결정모형을 통하여 및 기대수익률과 체계적 위험의 관계를 이 해한다. 효율적 시장가설을 통하여 정보가 자산 가격에 반영되는 과정을 이해한 후 이 가설로 설명하기 힘든 시장이상현상에 대하여 공부한다. 그리고 행동재무학을 통하여 투자심리가 자산의 가격에 반영되는 과정과 기술적 분석을 통하여 투자시점을 결정하는 방법 을 공부한다. 마지막으로 주식의 내재가치를 계산하는 배당할인모형에 대하여 공부한다. 첫째, 금융시장과 금융자산에 대한 이해 둘째, 포트폴리오이론과 자산가격결정모형의 이해 셋째, 행동재무학과 기술적 분석의 이해 넷째, 가치평가와 기본적 분석의 이해', '{"공부한다","통하여","기술적","기업의","가치평가","대하여","효율적","금융시장과","행동재무학과","가격에","반영되는","분석의","금융자산","증권시장구조와","증권시장지수","투자신탁과","투자회사","위험과","수익률","포트폴리오이론"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206426', '보험설계론', '경영대학', '경영대학', 0, 3, '전선', '이덕수', '-개인과 기업이 직면하는 불확실성의 해결 및 관리를 위한 방편으로 위험 분산, 이전 등 보험의 개념을 정립하고, 현장에 적용하는 방법에 대해 공부한다. -따라서 위험의 개념과 위험관리, 보험계약, 그리고 보험상품과 보험제도 등을 다룬다. -다양한 보험상품에 대한 개념과 내용습득 -개인 및 기업의 위험설계 및 위험관리를 위해 필요한 보험이론의 이해와 현장적용 능력 함양', '{"보강","생명보험","손해보험","위험관리","보험계약","보험상품과","개념과","위험과","권리와","의무","유통채널","사회보험","상품","중간고사","주차","구성요소","제도","과제부여","언더라이팅","보험약관"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509206', '전공수영', '자연과학대학', '자연과학대학', 0, 1, '전필', '이연주', '전공학생으로서 수영의 자유형 100m와 네 영법(크롤,배영,평영,접영) 모두를 연결하여 100m이상 완영할 수 있는 것을 최소 목표로 한다. 전공과목 이수자는 전문가로서의 소양을 갖추기 위해 최소한 네 영법을 구사할 수 있어야 하며, 본 과목의 이수함으로써 학생 들은 전문적인 지도법을 익혀 나갈 토대를 갖추게 된다. 이 강의를 통해 수강생들은 수영 경영의 4가지 영법(크롤, 배영, 평영, 접영) 중 크롤, 배영, 평영을 구사할 수 있고, 자유형(크롤)으로 1 00미터를 완영할 수 있는 수준의 능력을 갖춘다.', '{"실기","수영용품","크롤","배영","발차기","팔젓기","종합동작","호흡","평영의","수영의","평영","오리엔테이션","수영","크롤의","연습","배우기","자유형","영법","접영","완영할"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206429', '실전투자에서', '경영대학', '경영대학', 0, 3, '전선', '안동규', '모든 사람이 선택을 하는 사람으로서 투자자라 할 수 있다는 사실에 이 과목은 기초를 두고 있다. 투자의 영역에서 어떻게 선택을 할 것인가를 배우는 것이다. 과목은 실전적 지식을 알고자 하는 것이다. 즉 현실 투자세계에서 발생하는 상황에서 알아야 할 것등을 습득하는 것이다.전문적이고 이론적인 재무론을 배우는 것이 아니라 투자와 관련된 통섭적 지식은 무엇인가? 투자자는 왜 자주 실패하는 가? 일반인들이 투자를 할 때 무엇이 필요한지를 시작으로 어떠한 지식이 실전투자에서 사용되는가? 투자 철학은 무엇인가? 투자의 경험에서 성공를 하기위한 실전적 공부를 하는 것이다 불확실성의 시대에서 의사결정을 하는 데 필요한 지식과 경험을 공부함. 실전투자로서 모의 투자에 참여함. 돈과 자산 그리고 시간을 어떻게 배분하는가? 통섭적 지식의 필요는 무엇인가? 상식적으로 투자하기 위해서 무엇이 필요한가? 돈이 란 과연 무엇인가? 등을 다룸', '{"요약","무엇인가","투자","페이지로","주식","교과서","자신의","페이지","대가들의","배우기","주식의","투자의","어떻게","만들기","하는","것이다","투자철학과","투자스타일","증권사","가치평가"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509238', '트레킹', '자연과학대학', '자연과학대학', 0, 1, '전선', '유신환', '최근 폭발적으로 성장하고 있는 레저활동 중에서 등산 및 야영활동에 필요한 이론적 지식과 실제적인 기술들을 익힘으로써 야외 할동 지도역량을 개발하고 향상시키는 것을 목표로 진행되는 현장실습중심 강좌이다. 야외 활동을 통해 체력을 향상시키고, 정신건강을 촉진한다. 자연과 지리 등 생태학적 관점을 가지고 환경 문제에 대한 이해를 심화한다. 수강학생들의 팀워크와 리더십 능력을 향상시키고, 문제 해결 능력을 기른다. 야외활동 프로그램을 계획하고 실행하는 역량을 개발한다.', '{"야영의","프로그램","야외활동","현장실습","체험","등산","야외활동의","백패킹","프레지","등산및","야외","향상시키고","능력을","유형","야외호라동","참가자","지도자","프레지등","계획","프포그램"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('206430', '금융학원론', '경영대학', '경영대학', 0, 2, '전선', '김태규', '본 과목에서는 금융에 대한 기본 개념과 원리에 대해 학습하는 것을 목표로 한다. 먼저 금융의 역할과 기능을 소개하고 실물거래와 금융거래의 차이를 이해한다. 다음으로 금융시장의 종류, 직접금융과 간접금융의 차이, 금융회사의 종류 등 금융시스템 전반에 대한 이해를 제고한다. 이를 바탕으로 은행과 예금취급기관, 저축, 대출, 부채관리에 대한 구체적 지식을 습득한다. 또한 금융투자와 관련하여 주식 및 채권투자, 재무제표, 증권분석 등에 대한 이해를 높이는데 중점을 둔다. * 금융시장, 금융상품, 금융거래, 금융회사 등 금융시스템에 대한 전반적 이해 * 저축상품 및 대출상품에 대한 지식 습득 * 주식 및 채권투자, 재무제표, 증권분석 등 금융투자에 대한 이해 제고', '{"종류","채권투자","재무제표","증권분석","금융유관기관","투자의","주식의","채권의","금융의","금융시장의","직접금융과","금융회사의","금융시장","저축상품","이해를","주식","금융거래","금융지표","이자율","환율"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509246', '운동상해', '자연과학대학', '자연과학대학', 0, 2, '전선', '이환곤', '운동 상해란 운동 시 발생하는 신체의 손상으로 과거에는 주로 운동선수들에게 국한되었지만, 오늘날 건강의 중요성에 대한 사회 전 반적인 인식 개선 및 여가 시간의 증가에 따라 다양한 스포츠 및 신체활동에 참여하는 대중들(유소년, 청장년층, 노인)의 수가 증가하 면서 일반인에게서도 운동 상해의 발생빈도가 점차 증가하고 있다. 이와 같은 사회적 현상에 대처하기 위해 의학 분야에서는 운동 상 해의 진단과 치료에 대한 관심이 높아지고 있으며, 체육학 분야에서는 의학적인 진단과 치료 이후에 일상생활 및 스포츠로의 복귀를 위한 운동 재활의 필요성이 확대되고 있다. 또한 손상이 발생한 후에 진단 및 치료, 재활을 수행하는 것보다는 사전에 운동 상해를 예 방하는 것이 더 중요하다는 인식이 확산됨에 따라 운동 상해의 예방을 위한 체육학 분야의 역할이 점차 중요해지고 있다. 따라서 본 교과목에서는 운동 상해의 예방 대책 및 위험 관리, 운동 상해의 기전 및 관리 기술, 운동 상해의 유형에 따른 재활 운동 등을 학습함 으로써, 관련 분야에서의 차별화된 전문가를 양성하고자 한다. 운동 상해에 대한 개념을 이해하고, 운동 상해의 예방 대책 및 위험 요인들의 관리 방법을 설명할 수 있다. ■ 운동 상해의 발생 기전을 해부학 및 생체역학적인 관점에서 설명할 수 있다. ■ 운동 상해 발생 시 응급처치 및 손상 평가(검사 및 진단)의 과정을 설명할 수 있다. ■ 운동 상해 발생 후 각 신체 부위별 재활 운동 및 예방 운동 프로그램을 구성할 수 있다.', '{"운동","있다","기술","설명할","수기식","재활","주교재","파워포인트","퀴즈","운동상해의","질의","응답","손상","프로그램의","위험","종류","손상의","운동상해에","의학적","팔꿈치"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685004', '디지털포렌식', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '장윤식', '이 수업의 주교재가 영어이므로 수업계획서의 주요 내용은 영어로 작성되었습니다. 하지만 실제 수업의 진행 및 강의자료(PPT) 등은 한글이 주로 활용됩니다. 디지털포렌식 분야의 기초수업으로 데이터와 컴퓨터구조 등 컴퓨터 관련 이해가 충분치 못한 학생들을 위한 기본적인 내용이 포함됩 니다. Digital forensics has been a professional field for many years, The growth of the Internet and the worldwide proliferation of com puters have increased the need for digital investigations. Computers can be used to commit crimes, and crimes can be recorded on computers, including company policy violations embezzlement, e-mail harassment, murder, leaks of proprietary information, a nd even terrorism. Law enforcement, network administrators, attorneys, and private investigators now rely on the skills of professi onal digital forensics experts to investigate criminal and civil cases. This course covers a solid foundation by introducing digital forensics to those who are new to the field. Fundamental skills and theories required for digital evidence h andling processes and professional knowledge including lab management, legal and ethical issues, and other agendas required t o work in the field will be discussed. By the end of this course, students should: - 제한적으로 디지털 서비스를 사용하여 저지른 범죄 식별 - 범죄 또는 사건 조사에서 디지털 포렌식 조사자의 역할 정의 - 디지털 서비스에 저장된 정보를 수집하고 분석하는 데 사용되는 도구 식별 및 기본적인 사용방법 습득 - 민사 또는 형사 소송을 위한 조사 중에 얻은 증거의 적절한 처리(Chain of Custody) 설명', '{"포렌식","리포트","디지털","구조","이해한다","절차를","수행한다","분석한다","도구","개요","프로젝트","식별","사례","퀴즈","윤리","있다","무결성","보고","디스크","이미징"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509305', '배드민턴', '자연과학대학', '자연과학대학', 0, 1, '전선', '정은희', '배드민턴의 경기방법, 규칙, 기술 등을 학습하고 실천하며 배드민턴 기초 실력과 체력 향상을 도모한다. 생활스포츠 지도자의 역량을 강화하기 위한 지도능력, 팀워크 향상, 리더십, 스포츠 정신 등을 실천하고 도입하여 생활 체육의 효과를 학습하여 국민건강 증진에 도움이 될 수 있는 인재로 성장한다. 또한 뉴스포츠 및 레크리에이션기법을 활용하여 다양한 대상에게 지도할 수 있는 방법을 배워본다. 1. 기술적인 측면 : 학생들은 배드민턴의 기본 기술들을 정확하게 이해하고 실행할 수 있을 것이다. 이에는 스윙, 서브, 스매시, 드롭샷 , 발리 등이 포함된다. 학생들은 기술적인 면에서의 개선을 통해 경기에서 높은 수준의 성과를 이룰 수 있을 것이다. 2. 전략적인 측면 : 학생들은 다양한 배드민턴 전략과 전술을 이해하고 경기 상황에 따라 적절한 전략을 선택할 수 있을 것이다. 3. 체력 및 민첩성 향상 : 학생들은 수업을 통해 체력과 민첩성을 향상시킬 것이다. 배드민턴은 빠른 이동과 민첩한 반응을 요구하므 로 이를 향상시키는 데 도움이 될 것이다. 4. 스포츠 정신과 팀워크 강화 : 학생들은 배드민턴을 통해 스포츠 정신을 배울 것이다. 공정한 경기, 상대방 존중, 승리와 패배에 대한 태도 등을 통해 스포츠 정신을 촉진시킬 것이다. 특히 팀워크 수업에서 학생들은 팀원들과의 협업을 통해 목표를 달성하는 능력을 강화할 것이다. 5. 자기 평가 및 성장 : 학생들은 수업 기간 동안 자기 기술을 지속적으로 평가하고, 필요한 부분에 대해 개선할 방법을 찾을 것이다. 6. 체육활동의 즐거움과 지속적인 참여 유도 : 학생들은 배드민턴을 통해 체육활동의 즐거움을 경험하고, 이를 통해 지속적으로 운동 에 참여할 동기를 찾을 것이다. 나아가 수업이 끝난 후에도 배드민턴을 즐겨하며 건강한 생활습관을 유지할 것이다.', '{"것이다","학생들은","경기","배드민턴","스포츠","규칙","기술","등을","팀워크","있을","스윙","서브","배드민턴을","배드민턴의","체력","도움이","있는","방법을","기술적인","이해하고"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685015', '범죄수사절차법1', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '박노섭', '형사 절차법을 중심으로 소개할 예정이며, 형사법 체계에서의 중요성과 개요.정의와 형사 재판에서의 함의, 범죄수사, 체포와 구속, 영 장없는 체포, 압수수색 등 수사절차에 대한 내용을 수강할 예정입니다. 수사가 종결된 이후 검사의 기소절차를 공부할 것이고, 기소이 후의 법관에 의한 재판절차를 여러분들은 배울 예정입니다. 또한 인공지능학습(GPT 혹은 공개 LLM)을 통한 자유로운 토론을 함께 활용할 예정에 있습니다. 본 과정에서는 구체적인 범죄 사건에 적용되는 실질법인 형법을 집행하기 위한 절차 규정인 형사 소송법에 대해 배움으로써, 실체적 진실 발견과 피의자, 피고인, 피해자의 인권 보호라는 사법 정의의 목적을 이해하는 것을 목표로 합니다. 특히, 형사 절차 관련 법의 최근 개정 사항과 주요 판례를 반영하여 범죄자, 피해자 보호 체계 등 특별 절차와 함께 범죄 피해 보상 절차를 검토합니다. 형사 소 송의 단계에 따라 국가 법 체계인 형사 소송법을 체계적이고 종합적으로 해석함으로써 전반적인 형사 절차에 대한 이해를 증진시키 고, 형사 재판 실무에 필요한 기본 지식을 함양하는 것이 본 과정의 주된 목적입니다.', '{"법적","사례","이해하기","재판","수사","수사의","절차","시나리오를","학생들이","임의","그리고","개념과","역할과","절차의","중요성","실제","관련된","학생들은","작성","증거의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509307', '전공테니스', '자연과학대학', '자연과학대학', 0, 1, '전필', '유신환', '평생스포츠로서의 테니스의 특성과 운동효과 등에 대한 이론과 실제적인 기술을 강의하며 지도자로서의 자질을 향상시키는데 필요 한 지식, 기술, 태도를 효과적으로 체득케 함을 목적으로 본 교과목을 운영하고자 한다. 테니스의 기초기술 및 응용기술을 익힘으로써 스포츠 지도자로서의 역량을 배양할 수 있음.', '{"테니스경기에","적합한","운동에","복장","착용","익히기","서브","테니스","규칙","게임방법","로브","테니스의","지도자로서의","그립잡기","준비자세","포핸드","백핸드","자세","운동공간과","라켓면"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685019', '사이버범죄와보', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '장윤식', '영어 70%, 국어 30% 과목입니다. 영어교재와 수업을 기본으로 하되 요약정리, 이해가 되지 않는 부분에 대한 보충, 법률 등 국내 자 료를 사용해야 하는 부분, 질문과 답변 등 필요한 경우 국어를 사용할 것입니다. This course introduces undergraduate students to the foundational concepts, key threats, and response mechanisms in the doma in of cybercrime and cybersecurity. As our personal, commercial, and governmental activities increasingly depend on digital netw orks, cyber threats have become one of the most urgent challenges of the 21st century. The course explores the evolving landscape of cybercrime―from system intrusions and online fraud to digital exploitation, cyber bullying, and cyberterrorism―while also covering the fundamental principles of cybersecurity and the technical, legal, and ethical responses to such threats. Emphasis will be placed on understanding the actors behind cybercrime (individuals, organized group s, and state-sponsored entities), the vulnerabilities they exploit, and how law enforcement and global institutions respond. Through a combination of lectures, case studies, and discussions, students will develop the analytical tools necessary to interpret cyber incidents, evaluate security risks, and understand the societal and legal implications of cybercrime. By the end of the cours e, students will be equipped with foundational knowledge to pursue further studies or careers in digital security, criminology, or public policy. By the end of this course, students will be able to: -Define the core concepts of cybercrime and cybersecurity, including key terminologies, classifications, and digital threat landscap es. -Identify and explain major types of cybercrime (e.g., hacking, fraud, cyberbullying, digital exploitation) and the actors involved. -Analyze how cybercriminals exploit technological and human vulnerabilities in various sectors. -Understand the fundamental principles of cybersecurity, including confidentiality, integrity, availability (CIA), and basic protection 2. Course Objectives ■ Course Objectives mechanisms. -Interpret basic digital forensic procedures and cyber-investigation steps related to digital evidence handling. -Evaluate national and international legal frameworks and cooperation models for combating cybercrime. -Critically reflect on ethical dilemmas in cybersecurity, such as privacy vs. surveillance, freedom of expression, and digital rights. -Apply conceptual knowledge to real-world case studies involving cyberattacks, digital fraud, or security failures.', '{"영어","국어","과목입니다","영어교재와","수업을","기본으로","하되","요약정리","이해가","되지"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509318', '전공태권도', '자연과학대학', '자연과학대학', 0, 1, '전필', '윤현기', '본 강의는 태권도의 역사적 배경 및 구성원리 등 이론적인 이해를 바탕으로 기본동작, 품새, 겨루기 및 경기규칙 등에 대한 실제적인 기술을 익힘으로써 투기 지도자로서의 역량과 자질을 향상시키고자 하는데 주안점을 두고 진행하는 실습중심교과목이다. "지식- 태권도의 형성과정(역사적 배경)과 구성원리의 이론적배경을 이해한다. 기술- 기본동작, 품새, 겨루기의 기본원리를 이해하고 실기를 연마한다. 태도- 태권도의 기본정신을 이해하고 심신을 수양하는 과정을 통하여 바른 인성을 기른다. "', '{"태극","겨루기","겨루기의","실제","기술","기본동작","돌려차기","발차기","익히기","서기","제자리","스텝","기본기술","경기기술","훈련의","실제와","응용","훈련","호구겨루기","태권도의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685021', '가상자산추적', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '구민우', '이 교과목은 가상자산(암호화폐)의 거래 구조, 블록체인 데이터의 특성, 그리고 범죄？규제？조세 등 다양한 분야에서의 온체인(온체 인 데이터 기반) 추적 및 분석 기법을 학습한다. 학생들은 실제 사례 기반의 데이터 분석 실습을 통해 불법 자금세탁, 사기, 해킹 등 주요 범죄유형을 파악하고, 추적 도구를 활용하여 자산의 흐름을 분석하는 역량을 기른다. 1. 블록체인 정의, 온체인데이터의 구조와 거래 흐름을 이해한다. 2. 가상자산의 자금세탁, 사기, 해킹 등 주요 불법유형을 식별하고 추적할 수 있다. 3. 국제 AML 기준(FATF 등)을 이해하고 실제 사례에 적용할 수 있다. 4. 공공기관 및 금융기관이 사용하는 온체인 분석 도구의 원리를 습득한다. 5. 정책, 규제 관점에서 디지털 자산의 추적과 감독 모델을 제시할 수 있다.', '{"추적","온체인","주소","사례","데이터","자금세탁","이론강의","구조","블록체인","규제","사기","해킹","정책","식별","단계별","프로젝트","실무형","있다","공공기관","가상자산"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509323', '전공골프', '자연과학대학', '자연과학대학', 0, 1, '전필', '곽창수', '체육학을 전공하는 학생들에게 골프의 기초지식을 이해함과 동시에 기술을 습득시켜 질높은 스포츠 활동을 제공하고 스포츠 현장에 서 골프지도자로서의 자질을 향상시키는데 그 목적이 있다. 1. 생활체육종목으로서 골프경기의 특징을 이해한다. 2. 골프의 기본기술을 습득한다. 3. 골프경기의 훈련방법과 경기전략을 이해한다. 4. 골프 규칙과 경기진행방법을 이해한다.', '{"익히기","골프스윙","연습","임팩트","정확한","백스윙","의한","동작","단계","준비자세","풀스윙에","세계적인","알아오기","그립법","어드레스","올바른","자세","다운스윙","피니쉬","이해한다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685030', '범죄학개론', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '안정현', '본 과목은 범죄와 형사 사법 체계에 대한 이해를 제공하는 것을 목표로 합니다. 학생들은 범죄학의 개념과 원리를 배우게 되며, 이에 는 범죄의 유형, 범죄자의 유형, 범죄의 요인, 그리고 인간 사회에서 범죄가 불가피한 이유를 설명하는 여러 이론들이 포함됩니다. 또 한, 형사 사법 시스템이 어떻게 작동하는지, 왜 그런 방식으로 작동하는지, 실제로 효과가 있는지에 대해 학습합니다. 실제 범죄에 학 습 내용을 적용해보는 다양한 사례 연구도 포함되어 있어, 형사 사법 분야에서 경력을 쌓고자 하는 학생들에게 도움이 될 것입니다. - 범죄, 범죄자 및 형사 사법 체계에 대한 이해 - 범죄의 원인과 결과에 대한 이해 - 범죄 이론을 적용하여 범죄 행위 및 트렌드 이해 - 형사 사법 분야의 경력에 대한 통찰력', '{"범죄","범죄의","사법","형사","유형","피해자","서비스","폭력","조직","심리","생물학적","장애","선택","중간고사","한계","경찰","법과학","교정","소년","심판"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509326', '운동건강심리학', '자연과학대학', '자연과학대학', 0, 3, '전선', '양은석', '본 교과목은 Online콘텐츠를 제작하여 e-Learning 유형의 사전학습과 학습자 중심의 학습인 강의실 활동(발표,토론, 문제해결, 프로젝 트 등)수업으로 진행하는 HA-FL 플립러닝이다. 따라서 3시간 中 75분은 Online상에서 ,75분은 Offline상에서의 강의와 팀 발표, 토론 그리고 Feedback강의로 수업이 진행되며 지향하는 교육역량은 아래와 같다. 1.체육 지도자로서 운동건강심리학에 관한 지식과 정보를 습득한다. 2.건강증진을 위한 운동의 심리`생리학적인 기전을 배운다. 3.운동상황에서의 개인의 태도 및 인지행동에 영향을 주는 사회적 요인을 이해한다. 4.생활습관병 예방과 운동, Stress와 정신건강, 신체이미지, 자아 존중감, 심리.생리적 반응, 운동의 지속적인 참가, 수행 및 대사반응 그리고 운동중독에 관한 문제를 운동심리학적 관점에서 이해한다. 1. ''A sound Mind in a sound Body'' & Monism(心身一元論)을 깊이 이해한다. 2. 뇌(brain)과학의 생리''심리적 기전을 이해한다. 3. 운동(Exercise)이 정신건강(mental health)에 미치는 영향을 이해한다. 4. 만병의 근원인 Stress에 대한 심리`생리적인 기전을 이해한다. 5. 우울증(Depression)의 개선과 치유 그리고 Sress의 효율적인 관리에 대한 과학적인 운동의 대체요법을 학습한다. 6. 생활습관병(Lifestyle Diseases)예방과 개선을 위한 운동 심리학적인 가치를 이해한다.', '{"운동","주차","주제발표","탑재","주제","시청","응시","강의록","운동의","영상","화상수업","제작","조의","청취","질의","사항","발췌","토의","요약지","게시판"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509330', '스포츠마케팅', '자연과학대학', '자연과학대학', 0, 3, '전선', '홍재승', 'Sport marketing is a subdivision of marketing which focuses both on the promotion of sports events and teams as well as the pr omotion of other products and services through sporting events and sports teams. It is a service in which the element promoted can be a physical product or a brand name. The goal is to provide the client with strategies to promote the sport or to promote something other than sport through sports. The purpose of this course is to expose students to the terminology, concepts, and elements of sport marketing & event. After t aking this course, students should have a greater appreciation for the role of sport marketing in organization, society, and count ry, and have a better understanding of how to plan, organize, control, analyze the sport marketing and solve the problems.', '{"the","see","attached","file","and","sport","marketing","sports","plan","which"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685036', 'THE LANGUAGE', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '배윤정', 'The goal of interviewing and interrogation is to gather accurate information while maintaining professionalism and respect. Succe ssful interviewers are not only good at asking questions―they are confident, self-assured, and aware of how their behavior affect s others. In many ways, interviewers are performers: how they speak, listen, move, and react shapes the interview. This course focuses on both language and behavior in interviews and interrogations. Students learn how word choice, tone, body language, and professional presence influence communication and outcomes. Through lectures and hands-on role-play activities , students practice real-world interview skills in realistic scenarios. The course is ideal for students interested in law enforcement, law, or criminal justice, as well as anyone who wants to build confi dence and strong communication skills for professional settings. 인터뷰와 수사 면담의 목적은 정확한 정보를 수집하며 그 과정에서 전문성과 존중을 유지하는 데 있다. 효과적인 인터뷰어는 질문을 잘하는 것에 그치지 않고, 자신감과 자기 통제력을 갖추며 자신의 행동이 상대방에게 미치는 영향을 인식한다. 이러한 점에서 인터뷰 어는 일종의 ‘연기자’라고 할 수 있으며, 말하는 방식, 듣는 태도, 몸짓, 반응 하나하나가 인터뷰의 흐름과 결과에 영향을 미친다. 본 교과목은 인터뷰와 수사 면담에서 사용되는 언어뿐만 아니라 행동과 태도에도 중점을 둔다. 학생들은 단어 선택, 말의 톤, 신체 언 어, 전문적인 태도가 의사소통과 결과에 어떠한 영향을 미치는지 학습하게 된다. 강의와 역할극 중심의 실습을 통해 실제 상황에 적 용 가능한 인터뷰 기술을 연습한다. 본 교과목은 경찰, 법학, 형사사법 분야에 관심 있는 학생뿐만 아니라, 전문적인 환경에서 자신감 있고 효과적인 의사소통 능력을 기 르고자 하는 학생들에게도 적합하다. This course aims to equip students with the skills to: - Use both verbal and behavioral language strategically to gather accurate and useful information during interviews and interrog ations. - Recognize and interpret verbal and non-verbal cues, including tone, body language, and behavioral signals. - Communicate clearly and professionally by structuring effective questions and responses in English. - Build rapport and trust through respectful language, confident behavior, and ethical communication practices. - Demonstrate active listening, critical thinking, and analytical skills to evaluate the credibility of information. - Manage tension and conflict during interviews using effective communication and behavioral strategies. 본 교과목은 학생들이 다음과 같은 역량을 갖추는 것을 목표로 한다. - 인터뷰와 수사 면담 상황에서 언어적, 행동적 표현을 전략적으로 활용하여 정확하고 유용한 정보를 수집할 수 있다. - 말의 톤, 신체 언어, 행동 신호 등 언어적, 비언어적 단서를 인식하고 해석할 수 있다. - 영어로 효과적인 질문과 응답을 구성하여 명확하고 전문적으로 의사소통할 수 있다. - 존중하는 언어 사용과 자신감 있는 태도, 윤리적인 의사소통을 통해 라포와 신뢰를 형성할 수 있다. - 적극적 경청, 비판적 사고, 분석적 사고를 바탕으로 정보의 신뢰성을 평가할 수 있다. - 효과적인 의사소통 및 행동 전략을 활용하여 인터뷰 과정에서 발생하는 긴장과 갈등을 관리할 수 있다.', '{"있다","효과적인","인터뷰와","수사","영향을","인터뷰","교과목은","정보를","과정에서","태도","결과에","아니라","말의","신체","전문적인","있는","자신감","의사소통","언어적","활용하여"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509401', '체육측정평가론', '자연과학대학', '자연과학대학', 0, 3, '전선', '권헌수', '체육학 및 스포츠과학 현장에서 측정과 평가이론의 적용은 필수적이다. 체육학 및 스포츠과학 현장에서 요구되는 측정과 평가이론에 대하여 이해하고, 습득하여 교육 및 지도현장에서 활용할 수 있는 능력을 배양하는데 그 목적이 있다. 또한 생활체육지도자가 갖추 어야할 요건 중의 하나는 교육 및 훈련에서 직/간접적으로 활용가능한 정보자료를 신속하게 수집(측정), 정리, 분석, 검증하고 그 결과 를 평가하여 실제의 교육 및 훈련에 활용할 수 있는 능력을 배양하는 것이다. 따라서 이 수업의 목표는 체육학 및 스포츠과학 현장에 서 생활체육지도자의 역할을 효과적으로 수행하는데 기본적으로 요구되는 측정 및 평가능력을 습득하여, 교육 및 훈련에 적용하는 것이다. 교과목표는 다음과 같다. 첫째, 체육학 및 스포츠과학 현장에서 요구되는 측정과 이론평가에 대하여 이해하고, 습득하여 교육 및 지도현장에서 활용할 수 있는 능력을 배양하는데 목표가 있다. 둘째, 생활체육지도자로서 교육 및 지도현장에서 정보자료를 신속하게 수집(측정), 정리, 분석, 검증하고 그 결과를 토대로 훈련에 활 용할 수 있는 능력을 배양하는데 있다. 셋째, 체육학 및 스포츠과학 현장에서 생활체육지도자의 역할을 효과적으로 수행하는데 기본적으로 요구되는 측정 및 평가능력을 습 득하는 것이며, 이를 교육 및 훈련에 적용하는데 있다.', '{"있다","정리퀴즈","프레젠테이션","사용","자체제작","유인물","대해서","알아보고","이해하는데","특징을","측정과","검사의","평가를","교육","측정","수행하기","양호도에","평가의","신체구성의","체육학"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509411', '스포츠경영학', '자연과학대학', '자연과학대학', 0, 3, '전선', '홍재승', 'Sport management is a field of education concerning the business aspect of sport. Some examples of sport managers include th e front office system in professional sports, college sports managers, recreational sport managers, sports marketing, event manag ement, facility management, sports economics, sport finance, and sports information. Many colleges and universities offer bachel ors and masters degrees in sport management The purpose of this course is to expose students to the terminology, concepts, and elements of sport management. After taking this course, students should have a greater appreciation for the role of sport management in organization, society, and country, and have better understanding of how to plan, organize, control, analyze the sport management skill and solve the problems.', '{"the","see","attached","file","sport","and","management","sports","managers","plan"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685039', '범죄데이터분석고급', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김지온', '？ 다양한 범죄정보의 연관관계를 통합적으로 분석하는 범죄연결망분석(Criminal Network Aanlysis) 원리를 이해하고 분석방법론을 학습합니다. ？ 범죄연결망분석에 활용되는 사회 연결망 분석원리(Social Network Analysis)와 AI 기반의 그래프신경망(Graph Neural Network) 원 리를 이해하고 범죄분석에 활용할 수 있는 실증적 학습을 진행합니다. ？ 범죄 수사시 취득하는 대용량 수사정보에 대한 전처리, 데이터베이스 기반의 분석과 보고서를 작성하는 학습을 진행합니다. ？ 범죄정보분석 프로그램인 i2와 데이터베이스인 i-base, 사회연결망분석 전용 프로그램인 넷마이너를 활용하여 실습을 진행합니다. ？ 다양한 범죄정보의 연관관계를 통합적으로 분석하는 범죄연결망분석(Criminal Network Aanlysis) 원리를 이해하고 분석방법론을 적용할 수 있다. ？ 범죄연결망분석에 활용되는 사회 연결망 분석원리(Social Network Analysis)와 AI 기반의 그래프신경망(Graph Neural Network) 원 리를 이해하고 범죄분석에 활용할 수 있다. ？ 범죄 수사시 취득하는 대용량 수사정보에 대한 전처리, 데이터베이스 기반의 분석과 보고서 작성을 할 수 있다.', '{"데이터베이스","수사정보","범죄연결망분석","이해하고","기반의","네트워크","수사정보분석","전문가","특강","진행합니다","있다","범죄정보의","연관관계를","통합적으로","분석하는","원리를","분석방법론을","범죄연결망분석에","활용되는","연결망"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509412', '운동기술분석', '자연과학대학', '자연과학대학', 0, 3, '전선', '곽창수', '본 강의는 스포츠 기술을 분석하는데 필요한 분석이론, 측정방법, 자료처리 방법, 분석방법 등을 익힘으로써 스포츠 기술을 더 쉽게 이해함은 물론 경경기지도자 및 생활체육지도자로서의 자질을 배양하는데 그 목적이 있다. 또한 장차 국가공인자격증으로서 새로 신 설되는 "운동기술분석사" 자격증을 취득하는데 결정적으로 도움이 되는 내용을 다룸으로써 보다 쉽게 국가공인자격증을 취득할 수 있게 한다. 1. 운동기술분석에 대한 전반적인 과정을 이해한다. 2. 운동기술분석방법의 적용법을 이해한다. 3. 영상분석법을 이해한다. 4. 힘측정법을 이해한다. 5. EMG측정법을 이해한다.', '{"영상분석의","조별","실시","결과","해석","시간분석","간단한","실험","자료처리","이해한다","기자재","운동기술의","발달","차원영상분석법","영상분석","차원영상분석법의","지면","반력측정","측정방법","태능선수촌"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685040', '치안AI응용실무', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '박노섭', '치안 AI 실무는 치안 현장에서 발생하는 다양한 문제를 데이터와 인공지능 기술을 활용해 분석하고, 실제 업무에 적용 가능한 해결책 을 설계·평가하는 실무 중심 교과목이다. 학생들은 이 수업을 통해 치안 데이터의 특성과 한계(민감정보, 편향, 오류, 누락 등)를 이해 하고, 범죄 예방·수사 지원·위험 예측·자원 배치 등 치안 의사결정에 활용되는 AI 기법의 기본 원리와 적용 방식을 탐구하게 된다. 본 과목은 사례 기반 학습과 프로젝트 실습을 중심으로 진행되며, 이를 통해 학생들은 치안 문제를 구조화하여 질문을 만들고, 검증 가능한 방식으로 데이터를 분석하며, 결과를 현장 의사결정과 연결해 설명·보고할 수 있는 비판적 사고 및 실무 적용 능력을 함양하 는 것을 목표로 한다. 치안 AI 실무 교과과정은 치안 현장의 문제를 데이터와 AI로 분석·해결할 수 있는 실무 역량을 기르는 것을 목표로 합니다. 수강 후 학 습자는 (1) 치안 데이터의 특성과 AI/ML·NLP 기본 개념을 이해하고, (2) 문제정의？지표설정？모델 평가(F1 등)？오류분석을 통해 결 과의 신뢰도와 위험을 판단할 수 있습니다. 또한 (3) 분석 결과를 의사결정과 연결해 보고서·발표로 명확히 전달하며, (4) 데이터 준비 →분석→검증→적용 시나리오 설계까지의 실무 절차를 수행할 수 있습니다. 마지막으로 (5) 개인정보 보호, 공정성, 설명가능성 등 윤 리·법적 쟁점을 고려해 생성형 AI를 “검증 가능한 방식”으로 활용하는 역량을 갖추게 됩니다.', '{"증거","치안","법과학","작성","증거목록","요약","가설","한계","피드백","데이터","체크리스트","템플릿","감정","스케치","비교","초안","사례","결과를","사례기반","기록"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509430', '스포츠윤리', '자연과학대학', '자연과학대학', 0, 2, '전선', '권헌수', '스포츠 상황에서 발생하는 비윤리적 상황을 탐색하고, 페어플레이와 윤리적인 스포츠란 무엇인가에 대해 알아보고자 한다. 이러한 스 포츠윤리는 스포츠에서 당면하고 있는 윤리적 제 문제에 있어서, 이론적 접근을 통해 실제적인 스포츠의 윤리적 행위를 실천하기 위 함이다. 이를 위해 시대 변화와 삶의 질에 따른 문화의 특성을 살펴보고, 스포츠에서 발생할 수 있는 도덕윤리적 행위에 대한 제 문제 들을 철학적 관점에서 탐색하고자 한다. 이를 통해 스포츠의 고유한 가치와 본질을 재인식하고, 올바른 스포츠 행위를 지향함에 목적 이 있다. 교과목표는 다음과 같다. 첫째, 스포츠에서의 윤리적 제 문제에 대하여, 이론적 접근을 통해 윤리적 판단을 시도한다. 둘째, 비윤리적 행위에 대한 실제적 가치와 윤리적 행위를 이해함으로써, 스포츠의 올바른 시각을 가진다. 셋째, 도덕적 운동수행을 위한 방법을 부여한다.', '{"있다","정리퀴즈","프레젠테이션","사용","자체제작","유인물","스포츠에서","알아보고","대해서","이해하는데","주차_스포츠와","스포츠의","윤리","윤리의","윤리적","스포츠와","나타나는","심판","윤리학의","특징을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('685042', '정보통신개론', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '이용태', '정보통신기술(ICT)은 오늘날 사회 전반에 걸쳐 필수적인 기반 기술로 자리 잡고 있습니다. 경제, 교육, 의료, 치안, 안전, 국방, 문화 등 다양한 분야에서 정보의 생성, 전달, 저장, 활용은 핵심적인 역할을 하며, 이를 가능하게 하는 것이 바로 정보통신기술입니다. 따라서 이러한 기술의 기본 개념과 원리를 이해하는 것은 현대 사회를 살아가는 데 필요한 기본 소양이라 할 수 있습니다. 본 강좌는 담당 교 수의 전문 분야인 정보통신기술(ICT: Information and Communication Technology)의 기초 개념과 원리를 중심으로, 유선 및 무선 통 신 시스템의 구조와 기능, 그리고 인터넷, 이동통신, 디지털방송 등 다양한 기술 동향과 관련 서비스 사례를 함께 분석합니다. 본 교과의 목표는 정보통신기술(ICT: Information and Communication Technology)의 기초 개념과 원리를 공부하여 인공지능, 빅데 이터, 사물인터넷(IoT), 클라우드 등 ICT 융합 기술에 대한 이해를 높이는 데 중점을 두고 있으며 학습목표는 다음과 같습니다. 1. 정보통신의 기본 개념과 원리를 설명할 수 있다. 2. 유선 및 무선 통신 시스템의 구조와 기능을 이해한다. 3. 인터넷, 이동통신, 디지털방송 등의 기술 동향을 파악한다. 4. ICT가 사회, 산업, 일상생활에 미치는 영향을 이해한다', '{"기술","인터넷","통신","서비스","개념과","원리를","유선","시스템의","이동통신","디지털방송","디지털","아날로그","구성요소","전송","기술들","정보통신기술","정보의","클라우드","있습니다","무선"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('775003', '경찰실무1', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '윤성혜', '1. 생활안전, 수사, 경비, 교통, 정보, 안보, 외사 등 경찰의 실무적인 활동을 개괄적으로 학습한다. 2. 실제 사례를 중심으로 다양한 이슈를 함께 논의하면서 실질적인 경찰활동의 모습에 대한 이해력을 기른다 3. 학생들의 수강 목적에 맞는 구체적 목표를 함께 설정하고 필요한 역량을 갖출 수 있도록 도움을 준다. 1. 학습자는 경찰의 실제 활동을 이해할 수 있다 2. 경찰 실무의 구체적 사례와 관련하여 문제를 분석하고 해결방안을 모색할 수 있다 3. 경찰이 나아가야 할 바람직한 방향을 제시할 수 있다 4. 자신의 학습 목표에 맞는 역량을 기를 수 있다', '{"있다","경찰활동","사례","생활안전","수사","경비","교통","정보","안보","외사","교재","퀴즈","경찰의","활동을","실제","함께","수강","맞는","구체적","역량을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509431', '운동과노화', '자연과학대학', '자연과학대학', 0, 3, '전선', '유신환', '고령화 시대의 건강한 삶은 노화를 바르게 이해하는 것으로부터 시작되며, 노년기의 독립성을 유지할 수 있는 바람직한 생활방식과 신체활동에 대하여 살펴본다. 아울러 개인차가 심해지는 노년기에 안전하고 효과적인 신체활동 프로그램을 운영할 수 있는 역량을 개발하는 것을 본 강의의 목적으로 한다. 인구 고령화는 개인과 사회 그리고 국가의 관심과 문제점에 대한 다각적인 시도와 지속가능한 방안을 요구한다. 아울서 삶의 질이 중 시되는 현 시점에서 노화를 바르게 이해하고 올바른 생활방식과 신체활동을 통해 노년기의 독립성을 유지하고 건강한 일상생활을 수 행하는 것은 매우 중요한 일이다. 따라서 본 강의에서는 노화의 이해와 노화의 속도를 늦추고 건강을 증진할 수 있는 적절한 신체활 동에 대한 개괄적인 지식을 제공하고자 한다. 노화와 노인의 이해 노인의 신체활동 효과 및 건강증진 활동 역량 강화', '{"신체활동에","노인과","노화의","운동협응","운동제어","운동기술","그리고","신체활동","개요","노인질환과","운동처방","운동","운동과","노인의","양적","질적인","신체조직과","지구력의","변화","주차"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509437', '건강교육론', '자연과학대학', '자연과학대학', 0, 3, '전선', '정동식', '본 교과는 건강한 삶을 영위하는 데 필요한 건강 관리 지식과 방법을 이해하고 실생활에 활용하는 능력을 함양하는 데 목표를 두고 있다. 현대인들의 건강을 위협하는 질환들의 종류와 분류에 따른 건강 피해를 탐구하며, 그 중에서도 현대사회에서 만연한 운동 부 족, 스트레스 과다, 영양 과잉과 불균형, 흡연과 음주 등으로 인해 발병하는 생활 습관병의 발생 추이, 원인과 피해, 예방법을 탐구하 고, 건강 관리에 활용하기 위한 방안을 주로 모색한다. 1. 건강의 개념과 영역, 건강을 해치는 질환의 종류와 발생 추이, 질환의 발생 원인과 예방법 등을 이해하여 실생활에 적용하는 능력 배양 2. 스트레스의 개념과 증상, 스트레스와 건강의 관계, 스트레스의 원인과 관리 방안 등을 이해하여 건강 관리에 적용하는 능력 배양 3. 노화의 개념과 원인, 노화와 질환의 관계, 항노화 대책 등을 이해하여 건강 관리에 적용하는 능력 배양 4. 운동이 건강에 미치는 영향, 건강 증진 운동의 원리와 방법 등을 이해하여 건강 관리 운동 프로그램을 구성하고 적용하는 능력 배 양', '{"건강","관리","통한","이해하고","자료","방법을","실생활에","파워포인트","적용한다","건강의","운동을","관계","노화","원리와","운동","근력","근지구력","스트레스","개념과","자신의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('775004', '경찰학개론', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김택근', '한국 경찰의 역사를 포함하여 경찰에 대한 개괄적 이해를 통하여, 경찰 행정법, 경찰행정학 등에 대한 이해를 증진하고 경찰 업무 집 행시 발생할 수 있는 문제점 및 경찰 권한을 통제할 수 있는 경찰통제 등을 학습하여, 우리나라의 경찰공무원으로서의 기본 자질을 배양하는데 중점을 둘 예정 한국 경찰의 조직법인 국가경찰과자치경찰의 조직 및 운영에 관한 법률(경찰법)에 규정되어 있는 경찰의 책무인 국민의 생명과 재산 의 보호 및 공공의 안녕질서 유지의 정확한 개념을 정립하고, 국민과의 협업을 통한 경찰활동 등을 이해시키는 것임', '{"경찰의","한국","경찰","역사","경찰법의","경찰상","등에","등을","의미의","한계","요건","있는","경찰통제","조직법인","통한","경찰에","개괄적","이해를","형식적","경찰과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509438', '건강.체력평가', '자연과학대학', '자연과학대학', 0, 2, '전선', '유신환', 'This lecture is an examination and application of the principles of exercise prescription in primary disease prevention. Students wi ll advance their knowledge in the exercise preparticipation health screening and preexercise evaluation processes. Students will d evelop exercise prescriptions for healthy adults and adults with multiple cardiovascular disease risk factors and/or special conside rations. Student will learn how to adjust an exercise prescription that affect the exercise response and learn behavioral strategies to improve exercise adherence. This course was offered in conjunction with center for sports science in gangwon. - Examine and apply the ACSM the principles of exercise testing and prescription to healthy, adult populations. - Examine and apply the ACSM principles of exercise testing and prescription to adults with multiple cardiovascular disease risk f actors and/or with special considerations. - Complete self-assessments of your state of overall health as part of the exercise preparticipation health screening process. 2. 교과 목표 ■ 교과목표', '{"보충일","추석연휴","한글날","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('775006', '범죄수사학1', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김택근', '경찰의 임무는 범죄예방과 범죄수사를 통하여 국민의 생명과 재산을 보호하는 것이므로, 두가지 경찰의 역할 중 범죄수사 활동에 대 한 이해를 통해 범죄수사 기법에 대한 이해를 증진하고, 범죄수사를 통해 범죄예방을 할 수 있는 역량까지 배양 경찰의 수사활동과 실제 수사사례를 통하여 범죄 발생시 대처하는 요령을 습득하고 적법절차를 준수한 증거수집 등을 통한 사법경찰 의 영역 이해', '{"임의수사와","사례","수사의","실제","수사사례를","범죄의","수사기관","범죄수사의","강제수사","기본원칙인","특정한","경우의","강제수사에","수사","설명","증거채취","실수","수사실패","교훈","익히기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509444', '병태생리학', '자연과학대학', '자연과학대학', 0, 3, '전선', '최보영', '웰니스, 건강, 체력 등 핵심용어에 대한 개념과 상호관련성을 탐구해 보고 웰니스와 건강을 지속하는데 필요한 신체활동(운동)을 생애 주기별, 특정질환별로 살펴봄으로서 효과적이고 안전한 신체활동 프로그램을 제공할 수 있는 전문적인 역량을 개발하는 것을 본 강 의의 목적으로 한다. 인체의 구조와 기능에 대한 이해 인체가 자극에 반응하고 적응하는 과정의 이해 인체의 비정상적인 반응과 적응에 대한 이해', '{"웰니스","건강","체력","건강한","생활방식에","질의","응답","운동","심혈관질환자를","신체활동","인체의","적극적","상담모델","의뢰인","동기유발","의뢰인중심","건강검사","처방원리","젊은이를","임산부를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('503311', '유기화학III', '자연과학대학', '자연과학대학', 0, 3, '전선', '이정태', 'This course is only for the students who took organic chemistry 1 and 2. Students will learn the applications of organic chemistry in the field of medicine and the synthetic application of organic chemist y to these molecules. The chemistry of carboxylic acids and their derivatives, aldehydes and their derivatives and amines will be covered. This is 70% English Class. The textbook, PPT slides, exams are in English! Exams are cumulative!!! Characteristics and reactions of the carboxylic acids and their derivatives, aldehydes and their derivatives, and amines and their d erivatives.', '{"중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509521', '운동재활론', '자연과학대학', '자연과학대학', 0, 3, '전선', '최보영', '체육학을 전공하는 학생들이 운동상해 및 만성질환으로 나타나는 신체장애의 치료 및 개선에 도움을 줄 수 있는 운동재활에 대한 기 초 및 전문지식을 습득하고 이를 통하여 실제적인 여러 유형의 체육현장에서 적절한 운동처방을 하는데 필요한 운동재활의 이론적 배경을 터득하게 하고자 한다. 또한 현장맞춤형 인력 양성 및 교육의 질 향상을 위해 스타팅무브트레이닝센터(경기도 용인시 기흥구 구성3로28번길 14, 5층 502호), (주)밸류어블라이프(춘천시 석사동 880-3, 301호), 슬기로운정형외과(춘천시 경춘로 2364 2층)와의 연 계교육과정을 편성하여 실습 및 과제 수행을 실시한다. 현장실무 능력 향상을 위한 산업체 방문 2회(밸류어블라이프&슬기로운정형 외과)와 교과목과 연계한 산업체 특강 4회를 통하여 학생들이 실제 업무 환경에서 일하는 방식과 기술을 배울 수 있으며 스포츠 재활 현장에서 실제 문제를 해결할 수 있는 능력을 함양하고자 한다. 1. 운동재활의 과학적 이론을 습득한다. 2. 운동재활치료의 원리를 이해하고 기초과학 지식을 함양한다. 3. 질환별 재활운동의 형태 및 운동 시 손상 부위별 운동재활의 적용에 대한 지식을 습득한다. 4. 운동재활 지식을 바탕으로 운동상해 및 신체장애의 치료와 개선에 도움을 줄 수 있는 적절한 운동 프로그램을 설계할 수 있다.', '{"있다","유인물","질의","응답","대해","재활","운동재활","이해할","설명할","구성요소","있고","운동재활의","재활치료","구조와","방법을","습득할","운동재활치료의","기초과학","지식을","목적의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('503417', '유기합성실험', '자연과학대학', '자연과학대학', 0, 2, '전선', '이정태', '유기화학에서 배운 화합물들의 합성방법을 이용하여 실제로 다양한 화합물들의 합성에 적용한다. 합성에 관련된 기초지식과 실험과 정을 숙지한 후 화합물을 합성하고 그 결과분석을 통해 화합물의 구조를 이해하도록 한다. 유기화학적 지식을 바탕으로 유기합성 실험을 진행한다.', '{"합성","중간고사","반응","화합물들의","합성에","학회참가로","인해","수업없음","주차","구성요소","물리적","이해하기와","축합"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509522', '필라테스', '자연과학대학', '자연과학대학', 0, 1, '전선', '정나래', '잘못된 생활습관, 운동부족으로 인한 몸의 불균형과 통증을 깨닫고 필라테스를 통해 운동을 할 때뿐만 아니라 일상에서 신체 정렬을 도와 통증을 완화하고, Block System 교육으로 정해진 시간 안에 운동의 효과를 극대화 한다. 1. 필라테스에 대한 흥미를 높인다. 2. 필라테스를 통해 몸의 건강을 추구한다. 3. 신체의 바른 사용으로 정확한 필라테스 동작을 습득한다. 4. 전신근육을 바르게 사용하여 신체정렬, 운동능력을 향상시킨다.', '{"이용하여","한다","필라테스","이용한","있는가","하는","방법을","배운다","소도구","운동한","뭉친곳을","풀어준다","근육의","안다","운동을","이미지트레이닝을","사용방법을","써클링을","미니볼을","짐스틱을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('503508', '분석화학I', '자연과학대학', '자연과학대학', 0, 3, '전선', '김경호', '분석화학의 기초 개념부터 실제 정량분석 기법까지 다룬다. 분석 데이터의 통계 처리로 신뢰도와 오차를 이해하고, 화학 평형과 활성 도를 바탕으로 용액 내 반응을 해석한다. 또한 산염기 적정, EDTA 적정, 산화환원 적정의 원리와 응용을 학습하여 정량분석 능력을 기 른다. 분석화학의 기본 원리를 이해하고 다양한 측정에 적용하는 것을 목표로 한다.', '{"중간고사","분석화학의","정량분석","이해하고","적정","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509525', '웨이트트레이닝론', '자연과학대학', '자연과학대학', 0, 3, '전선', '이환곤', '삶의 질 향상과 평균 수명의 연장에 따라 운동을 통한 건강 관리에 대중들의 관심이 집중되고 있는 시대의 조류에 발맞추어, 일반인 의 건강 및 체력과 전문체육인의 스포츠 수행 능력 향상을 위한 실력 있는 전문지도자를 교육 및 양성하고자 한다. 졸업 후, 학생들이 생활체육 전문지도자뿐만 아니라, 엘리트 스포츠 지도자로서 현장에서 탁월한 기량을 발휘할 수 있도록 우수한 웨이트트레이닝 관 련 전문지도자의 양성을 목적으로 수업 방향을 설정하여 학습하도록 지도한다. 웨이트트레이닝은 건강 및 체력의 향상, 운동 재활, 스 포츠 경기 수행 능력 향상 등의 다양한 분야에서 효용 가치를 인정받고 있기 때문에, 학술 분야에서의 연구와 사회적 관심도가 증가 하는 추세에 있다. 따라서, 체육을 전공하는 학생들이 웨이트트레이닝의 중요성 및 필요성을 인지하고, 체육 및 스포츠 현장에서의 올 바른 적용을 위해, 웨이트트레이닝과 관련된 학문적 지식과 다양한 실제적 기술 및 방법들을 학습함으로써, 실사구시(實事求是)에 입 각한 배움을 추구한다. 교육과정은 웨이트트레이닝과 관련된 이론과 실습을 병행하여 진행되며, 학습된 내용을 토대로 학습자 개개인 이 실제 관련 영역에서 웨이트트레이닝의 적용이 가능하도록 역량을 배양한다. 수업내용은 웨이트트레이닝과 관련된 과학적 기초지 식과 기능해부학 및 운동생리학, 운동역학적인 지식 등을 다루어 웨이트트레이닝에 대한 전반적인 이해를 도모하며, 운동영양학과 트 레이닝방법론, 운동처방론, 운동상해 및 운동재활 등의 보다 전문적이고 심도있는 지식의 습득을 통해, 차별화된 전문가의 양성을 추 구한다. 인체의 움직임과 관련된 근골격계통의 구조와 기능을 해부학적으로 설명할 수 있다. ■ 트레이닝의 원리를 기반으로 웨이트트레이닝 프로그램을 구성할 수 있다. ■ 웨이트트레이닝과 관련된 다양한 훈련 방법 및 기술들을 생리학적/해부학적/역학적으로 설명할 수 있으며, 정확한 자세로 시범을 보일 수 있다. ■ 웨이트트레이닝을 체육 및 생활스포츠/엘리트스포츠 현장에서 다양하게 적용 및 활용할 수 있다.', '{"있다","웨이트트레이닝","웨이트트레이닝의","설명할","기술","관련된","스포츠","구조와","주교재","체육","웨이트트레이닝과","질의","응답","파워포인트","수기식","퀴즈","기술을","신체부위별","지도","건강"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('504244', '분자면역학', '자연과학대학', '자연과학대학', 0, 3, '전선', '전성호', '생명체의 자기방어 시스템에 대한 이해와 더불어 우리 몸의 면역체계에 대한 유전학적, 생화학적, 세포 및 분자생물학적인 분석을 통 하여 전반적인 면역현상을 이해함. 바이러스 감염에 대한 방어에서부터 암 및 자가면역질환의 발병 원리와 이에 대한 면역시스템의 작용기전을 설명함. 면역학의 개념을 이해하고, 우리 몸의 다양한 형태의 방어 기전에 대해 학습한다.', '{"자료","개요","항체의","중간고사","세포","우리","몸의","원리와","병원체의","종류","사이토카인과","염증반응","보체시스템의","작용기전","적응면역반응","구조와","기능","주차","구성요소","다양성과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506515', '기초화학및실험I', '자연과학대학', '자연과학대학', 0, 4, '전선', '이우람', '본 과목은 화학 전공자 및 자연과학, 공학 분야를 학습하는 학생들을 위한 첫 번째 전공 기초 과정으로, 물질의 본질과 구조, 그리고 물질 간의 상호작용을 이해하는 데 필요한 화학의 핵심 기본 원리를 다룹니다. 주요 학습 주제로는 화학 양론(Stoichiometry), 원자의 전자 구조와 주기적 성질, 화학 결합의 원리 및 분자 구조, 기체·액체·고체의 상 태, 그리고 열화학(Thermochemistry) 등이 포함됩니다. 학생들은 본 강의를 통해 미시적 관점에서 물질의 특성을 이해하고 거시적인 화학 현상을 정량적으로 분석하는 방법을 학습하며, 향 후 무기화학, 유기화학, 물리화학 등 심화 전공 과목을 이수하기 위한 탄탄한 기초 학업 역량과 과학적 문제 해결 능력을 배양하게 됩 니다. 본 교과목을 성공적으로 이수한 학생은 다음과 같은 핵심 학업 역량을 달성할 수 있습니다. 화학적 언어와 기초 원리 습득: 명명법, 화학식, 화학 반응식을 정확하게 이해하고 작성하며, 화학 양론(Stoichiometry)을 활용하여 반 응물과 생성물의 양적 관계 및 수득률을 정량적으로 계산할 수 있다. 미시적 구조와 주기성 이해: 양자역학적 관점에서의 원자 구조와 오비탈(Orbital) 개념을 설명하고, 주기율표에 나타난 원소들의 물리 적·화학적 주기성(이온화 에너지, 전자 친화도, 전기 음성도 등)을 예측하고 분석할 수 있다. 화학 결합과 분자 구조 해석: 이온 결합, 공유 결합, 금속 결합의 형성 원리를 이해하고, 루이스(Lewis) 구조, 원자가 결합 이론(VBT), 분자 오비탈 이론(MOT)을 적용하여 분자의 3차원적 기하 구조와 극성을 예측할 수 있다. 물질의 상태와 분자 간 상호작용 분석: 기체 법칙(이상 기체 및 실제 기체)을 적용하여 기체의 행동을 설명하고, 분자 간 상호작용(Int ermolecular forces)을 바탕으로 액체와 고체의 거시적인 물리적 특성을 미시적 관점에서 해석할 수 있다. 2. 교과 목표 ■ 교과목표 열화학 및 에너지 변화 이해: 열역학 제1법칙과 엔탈피(Enthalpy)의 개념을 이해하고, 헤스의 법칙(Hess''s Law) 등을 활용하여 화학 반 응에 수반되는 에너지 변화를 계산하고 분석할 수 있다. 심화 전공 학습 기반 확립: 무기화학, 물리화학, 분석화학 등 향후 이어지는 심화 전공 과목들을 이수하는 데 필수적인 과학적 추론 능 력과 문제 해결 능력을 갖춘다.', '{"화학","결합","기체","용액의","분자","있다","전공","구조","구조와","열화학","이해하고","주기성","화학량론","물질의","화학의","미시적","원자","에너지","이온","공유"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('509528', '하계스포츠', '자연과학대학', '자연과학대학', 0, 1, '전선', '홍재승', '레저스포츠로 각광 받고 있는 수상스키의 이론적인 배경 및 기술을 강의 하며 기술과 기능의 실제적인 체득을 통하여 지도자로서의 자질을 배양함을 목적으로 강의한다.수상레저와 관련된 응급 상황이나 안전 사고를 예방하고 대처하는 능력을 배양한다. 수상스키 기본기술 습득', '{"파일","참조","레저스포츠로","각광","받고","있는","수상스키의","이론적인","배경","기술을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('520001', '바이오헬스케어개', '자연과학대학', '자연과학대학', 0, 3, '전선', '정효석', '4차 산업혁명시대를 주도할 바이오헬스케어 서비스 시대와 함께 고령화가 가속됨에 따라 의료비 급증, 치료에서 예방중심으로 의료 서비스 패러다임의 변화, 삶의 질에 대한 관심을 증가시키고 있다. 이와 같은 시대의 변화에 따라 본 과정에서는 - 4차 산업혁명의 핵심기술 및 바이오헬스케어 산업에 대한 이해 - 글로칼대학 사업 및 RISE(지역혁신중심 대학지원체계)에 따른 강원도 지역육성산업분야에 따른 지자체별 특화산업분야 이해 - 지역육성산업분야인 천연물바이오소재를 활용한 기능성 소재 및 제품 개발 기업인 (주)단정바이오를 포함한 산업체의 특강 및 산 업체 견학 - 바이오헬스케어 기술에 관련된 기술분야인 의약품, 의료기기, 디지털헬스케어, 화장품, 식품을 포함하는 바이오헬스케어 관련 최신 기술과 산업 분야에 대한 산업환경, 핵심기술 및 제품들에 대하여 폭넓게 이해하고자함 21세기는 4차 산업혁명 시대의 핵심기술인 바이오헬스케어 분야 기슬의 이해를 통한 - 4차 산업혁명 핵심기술에 연계할 헬스케어 기술의 국내외 동향 및 미래 전망 파악 - 융복합 헬스케어 분야의 과학기술을 선도할 수 있는 융합 인재 양성 - 인류 건강 증진에 기여할 수 있는 헬스케어 전문가 양성 - 고부가가치 헬스케어 산업 분야를 견인할 수 있는 글로벌 인재 양성 - 미래 첨단 바이오헬스케어 기술의 산업화에 대한 이해를 통한 취업역량 강화 및 취업 기회 창출', '{"교재","자료","토의","바이오헬스케어","개발","개발현황","산업체","지역육성산업분야인","특강","분야","통한","미래","산업의","바이오헬스케어산업의","지역육성산업분야의","지역기업의","활용한","견학","헬스케어","영상"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506516', '기기분석화학', '자연과학대학', '자연과학대학', 0, 3, '전선', '이우람', '이 강좌는 기기분석에 있어서 필수적인 기초이론과 장비의 원리 및 구조에 대하여 이해하여 실제 연구 및 산업 현장에서 사용할 수 있는 능력을 키우는 것을 목표로 한다. 기기분석 강좌는 분광분석의 기본이론과 함께 분석기법으로는 원자분광법으로 흡수, 형광 및 방출 분광법, 질량분광법, 및 X-선 분광 법 등을 다루며, 분자분광법으로서 UV/Visible, 적외선 분광법을 주로 다룬다. 이 강좌는 기기분석에 있어서 필수적인 기초이론과 장비의 원리 및 구조에 대하여 이해하여 실제 연구 및 산업 현장에서 사용할 수 있는 능력을 키우는 것을 목표로 한다.', '{"분광법","기기분석","학습한다","그레인저의","핵심","단원별","원자","강좌는","흡수","방출","적외선","기기분석에","있어서","필수적인","기초이론과","장비의","구조에","대하여","이해하여","실제"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('520019', '임상시험개론', '자연과학대학', '자연과학대학', 0, 3, '전선', '박종국', '임상시험은 사람에게 사용되는 모든 의약품, 의료기기, 화장품, 건강기능식품 등에 대한 안전성, 유효성을 평가하는 과정이고, 인/허 가 과정을 수행하는데에 필수적으로 사용된다. - 고령화 사회에 임상시험에 대한 수요는 급격히 증가하고 있으며 - 특히 강원도의 글로벌혁신특구사업, 항체클러스터 등 주력 사업과, 학교의 글로컬대학, RISE사업 등과 긴밀한 연계성을 가지고 있고 , - 임상시험을 수행하는 CRO(임상시험수탁기관)가 직접 참여하여 산학 공동과정으로 운영되는 교과목이다. 학교와 업무협약을 맺은 JNPMEDI Inc.에서 임상시험 현장 전문가 교수 여러명이 직접 수업에 참여하며, 이를 통해 임상시험 전문가 를 양성하여 취업 기회를 제공하고자 한다. 1. 임상시험 과정에 대한 이해 2. 임상시험에 필요한 분야 및 기술에 대한 이해 3. 임상시험의 윤리적 제약에 대한 이해 4. 임상시험 규정과 관련 기관 (제약회사, 임상시험수탁회사, 병원) 간의 관계에 대한 이해', '{"임상시험","강의교안","임상시험의","데이터","디지털","임상시험에","프로세스","모니터링","방법과","역할_","품질과","무결성을","보장하기","위해","수행되는","모니터링의","개념과","방법을","또한","모니터링을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('506530', '나노소재화학', '자연과학대학', '자연과학대학', 0, 3, '전선', '이호재', '1980년대에 들어와서 현미경 기술에서 획기적인 발전이 있었다. STM이나 AFM과 같은 현미경들은 우리가 분자를 심지어 원자를 직 접 보고 조작할 수 있게 해주었다. 막역히 상상만 하던 분자들의 모습을 눈으로 직접 보게 되었고, 이들의 행동에 대해 직관적인 이해가 가능해진 것이다. 그 전에는 볼 수 없었던 화합물과 재료들의 세계, 즉 나노세계가 우리 눈앞에 펼쳐진 것이다. 나노 세계의 물질과 재료의 성질과 행동에 대한 직관적인 이해를 목표로 한다.', '{"나노소재","나노","응용을","행동에","직관적인","것이다","나노소재의","합성과","금속","나노입자와","플라즈모닉스","반도체","나노입자","나노다공성","소재","촉매","이차원","자기조립","단분자막과","표면화학"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('520027', '커뮤니티헬스케어', '자연과학대학', '자연과학대학', 0, 3, '전선', '정은희', '본 교과목은 초고령사회로의 진입에 따른 보건의료 패러다임의 변화를 이해하고, 병원 중심의 치료(Medical Care)에서 벗어나 지역사 회 중심의 통합적 건강 돌봄(Life-based Care)을 실천하기 위한 이론적 토대와 실무 역량을 학습하는 과목입니다. 수업에서는 공중보건, 사회복지, 운동과학, 정책학 등 다학제적 접근을 통해 지역사회를 건강 개입의 기본 단위로 설정하는 방법을 배 웁니다. 특히 예방 중심의 건강관리, 만성질환 및 기능저하 예방을 위한 운동·여가 서비스, 공공과 민간의 협력 거버넌스를 구축하는 전략을 다룹니다. 학생들은 이론 학습뿐만 아니라 현장 방문, 지역 자원 맵핑(Mapping), 프로그램 기획 실습을 통해 지역사회 현안을 진단하고, 지속 가능한 건강 돌봄 모델을 직접 설계해 보는 실전적 경험을 쌓게 됩니다. 본 강좌를 이수한 학생은 다음의 역량을 갖추는 것을 목표로 합니다. 1. 이론적 이해: 커뮤니티헬스케어의 학문적 배경과 핵심 개념(탈시설화, 통합 돌봄, AIP 등)을 정의하고 설명할 수 있다. 2. 현장 진단 역량: 지역사회 건강 통계 및 공공데이터를 활용하여 특정 지역의 건강 문제를 분석하고 사회적 결정요인을 파악할 수 있다. 3. 자원 활용 및 연계: 지역사회 내 보건·복지·체육 자원을 파악(Mapping)하고, 이를 연계한 효율적인 서비스 전달 체계를 고안할 수 있다. 4. 프로그램 설계: 대상자(노인, 만성질환자 등)의 특성에 맞춰 신체적·정신적·사회적 건강을 통합적으로 관리하는 예방 중심의 프로그 램을 기획할 수 있다. 5. 다학제적 협력: 보건·복지·운동 등 다양한 분야의 전문가들과 소통하고 협력할 수 있는 거버넌스 마인드와 팀워크 능력을 함양한다.', '{"있다","프로그램","사회적","건강","지역사회","자원","돌봄","지역","운동","사례","통합","예방","커뮤니티헬스케어의","팀활동","프로그램을","설계","중심의","다학제적","협력","보건"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('520028', '미생물공정학', '자연과학대학', '자연과학대학', 0, 3, '전선', '곽주한', '미생물학을 통해 학습한 내용의 연장선으로 미생물을 이용한 산업 공정의 원리와 응용, 미생물 생리·대사, 배양공정, 생물반응기 설계 및 운전, 생물제품 생산과 분리정제, 공정제어 등을 학습한다. 본 과목은 생명과학·바이오헬스케어 및 메디컬·식품영양·환경생명공학 전공자를 대상으로 미생물 기반 산업기술(Bio-pharma, food fermentation, waste-to-value, bioenergy)을 이해하고 실제 공정에 적용 할 수 있는 능력을 기르는 것을 목표로 한다. 본 교과목은 생명과학과-응용미생물학및실험, 바이오메디컬학과-인간과미생물, 식품영양학과 식품미생물학및실험과 코드쉐어 과목 이다. - 미생물 생리·대사 이해 및 공정 설계 개념 습득 - 배양공정/생물반응기의 운영 및 scale-up 원리 학습 - 발효·효소·세포공장 기반 산업 응용 이해 - 실제 산업 문제 해결능력 및 공정 최적화 사고 훈련', '{"미생물","응용","대사","세포의","중간고사","산업","생물반응기","운전","생물반응기의","효소","생리","배양공정","설계","기반","실제","공정","생물학","기초원리의","개관","작용"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('504241', '세포생물학및실험', '자연과학대학', '자연과학대학', 0, 3, '전선', '김경원', '-본 교과목은 생명체의 기본 구조적, 기능적 단위인 세포(Cell)의 구조와 기능을 분자 수준에서 이해하고, 이를 실험적으로 확인하는 과정이다. -세포막의 구조와 물질 수송, 세포 내 소기관의 기능, 에너지 대사, 신호 전달, 세포 주기 및 사멸 등 세포 생존과 유지를 위한 핵심 메 커니즘을 학습한다. -아울러 현미경 관찰, 세포 염색 등 세포학 연구에 필수적인 실험 기법을 직접 수행함으로써 이론적 지식을 실증적으로 검증하고 기 초 연구 역량을 배양한다. -본 과목은 생물교과 교직 과정 학생의 전공 기본이수과목이다. -세포를 구성하는 거대분자와 세포 소기관의 구조 및 기능을 명확히 이해하고, 각 소기관 간의 유기적 상호작용(신호전달, 물질수송) 을 설명할 수 있다. -광학 현미경을 능숙하게 조작하여 세포의 미세 구조를 관찰하고, 실험을 통해 얻은 세포학적 데이터를 분석 및 해석할 수 있다. -생명 현상의 정교함을 탐구하는 과학적 호기심을 가지며, 실험실 안전 수칙과 연구 윤리를 준수하는 예비 연구자의 자세를 갖춘다. -또한 예비교사 교육과 관련하여 중점을 두는 요소는 연구방법론을 익히는 것과 비판적 사고 기반의 과학적 소양을 넓히는 것이다.', '{"이해한다","내용과","관련한","퀴즈","세포내","세포의","소기관의","대해","기능","세포","소포에","의한","구조와","기능을","이해하고","종류","기능에","통한","수송과","필요한"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('504243', '미생물학및실험', '자연과학대학', '자연과학대학', 0, 3, '전선', '곽주한', '미생물학에 대한 전반적인 지식과 미생물 다양성, 종류, 구조, 특성, 생리, 생태 유전학적인 성질을 이해하도록 한다. 본 강의는 강의와 실험으로 구성이 되어 있으며, 강의를 통해 미생물에 대한 일반적인 지식과 실험을 통해 미생물학 연구를 이해하도록 한다. 본 강의를 통해 미생물에 대한 일반적인 지식을 얻고 실험을 통해 미생물 실험을 익히도록 한다. 미생물의 다양성, 종류, 구조, 특성, 형태, 유전학적인 성질을 이해하며 미생물학의 지식을 습득한다. 일상 생활 속의 미생물에 대한 이해를 통해 발전된 아이디어를 얻도록 한다.', '{"미생물","강독","미생물의","물질대사","에너지","발현","구조","고균의","세균","생태계의","세균의","조절","다양성","개론","이화작용","방출과","보존","동화작용","생합성","과정에서"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('540002', '청각학개론', '자연과학대학', '자연과학대학', 0, 3, '공통전선', '한우재', '청각학을 처음 접하는 학생들에게 가장 기초가 되는 교과목으로써, 수강생들은 한학기 동안 청각학의 전반적인 범위를 이해하고 4차 산업시대에 청각학과 접목될 수 있는 여러 융합적 가능성을 이해한다. 구체적으로는 청각학의 기원, 소리의 특성 및 소리를 듣는 청 각기관을 학습하고, 관련 용어들과 더불어 다양한 청력 검사들의 기본 원리를 익힌다. 또한, 보청기, 인공와우 등의 청각기기들의 용 어와 기본 원리를 이해하고 청각치료적 중재의 개념을 확인한다. 청각학의 입문 과목으로써 본 교과목에서는 청각학의 범위 및 융합적 내용들을 전반적으로 다룬다. 본 교과목을 이수함으로써 학습 자들은 청각학에서 다루는 용어 및 기본 지식을 습득하고, 이를 청각학 관련 심화 교과목들에서 활용 및 응용할 수 있다.', '{"확인","이해한다","수업전","학습준비도","피드백","담당","교수의","강의노트","강의식","기능","그룹","구조와","관찰","인공와우의","인공와우","원리를","청각학","구성","검사","종류"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543014', '의사소통장애개론', '자연과학대학', '자연과학대학', 0, 3, '공통전선', '윤지혜', '본 교과목은 언어병리학 전공 교수 3인의 협동강의로 언어병리학 전공에서 학습하게 되는 다양한 의사소통장애의 정의와 특성에 대 한 전반적인 이해를 돕는데 목적이 있다. 수강생은 본 교과목의 수강을 통해 다음의 내용을 학습할 수 있다. 1. 여러 원인에 의해서 타인과의 의사소통에 어려움이 있는 의사소통장애의 정의에 대해 개괄적 지식을 습득한다. 2. 의사소통장애의 여러가지 유형에 대한 원인과 각 특징을 학습한다. 3. 각 하위 의사소통 장애의 평가 및 중재 방법을 학습한다. 지식 -의사소통장애 전반의 이론적 배경 및 관련 임상기초지식 습득 -의사소통장애의 하위 유형 및 특징 학습 -의사소통장애 진단도구 및 치료법 개관 기술 -임상현장에서 환자를 합리적으로 진단할 수 있는 기초적 기술 습득 -평가에 대한 적절한 해석을 바탕으로 치료계획을 수립하는 기술 -다양한 원인질환으로 발생할 수 있는 의사소통장애 환자에게 언어재활사로서 적절한 서비스를 제공할 수 있음 태도 -위에서 제시한 이론적 지식을 바탕으로 환자의 상황을 이해하고 공감할 수 있는 태도 -사회적 약자 및 타인을 배려하고 협동하는 태도 -적극적인 토론을 지향하고 논리적으로 자신의 의견을 제시할 수 있는 태도', '{"교수","있다","주교재","이해할","특징을","윤지혜","이윤경","이승진","의사소통장애의","해부","있는","대하여","지식을","의사소통장애","유형","태도","유형과","언어발달장애의","아동언어장애","정의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('504320', '식물발달생물학및실험', '자연과학대학', '자연과학대학', 0, 3, '전선', '정동훈', '식물의 발달 및 발생과정을 유전학, 생리학, 분자생물학적인 방법을 통해 이해하는 것을 목표로 한다. 종자의 발아, 뿌리발달, 잎과 줄기의 발달, 개확시기 조절, 꽃 발달, 수술 발달, 암술 발달, 수분 및 수정, 종자 발달 과정과 관련된 식물 의 전반적인 발달과정을 이해한다. 종자의 발아에서 시작하여 영양생장, 생식생장을 거친 후 노화에 이르기까지 식물의 발달단계에 관련된 생리학적, 유전학적, 분자생 물학적 지식을 습득한다. 또한, 돌연변이 자원을 활용한 실험실습을 통해 식물의 분화 및 발달에 대한 연구의 기초를 확립한다.', '{"이해한다","실험","기작을","관여하는","발달","분자유전학적","유전자들의","기능을","분화","성장과","잎의","꽃기관","식물의","발달에","배발생","과정의","개화시기조절","배우체발달","발아","수분"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('540006', '언어발달', '자연과학대학', '자연과학대학', 0, 3, '전선', '배소영', '1. 영아기부터 초등학령기를 중심으로 아이의 언어가 어떻게 발달하는 지 살펴본다. 2. 청소년기와 장년기 및 노년기의 의사소통 변화를 살펴본다. 3. 말하기 및 쓰기 과제를 통해 발화 자료를 직접 수집하여 분석하면서 언어발달 자료에 대한 구체적 경험을 쌓는다. 인간 발화의 발달적 변화를 이해한다. 어휘, 문법, 대화, 이야기, 읽기 쓰기 발달을 중심으로 언어발달을 이해한다. 실제 인간 발화를 수집하고 분석한 후 언어발달보고서를 작성하여 언어발달을 실제적으로 이해한다. 나의 언어발달 노트를 작성하여 언어발달에 관한 지식을 융합적으로 활용한다.', '{"나의","발달","언어발달","언어발달노트_","슬라이드","연습","어떻게","자료","강의자료집","발화","요약","대상자","주차","될까","이야기","쓰기","문법","의미","보기","토요일"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('540031', '유창성장애', '자연과학대학', '자연과학대학', 0, 3, '전선', '황지은', '의사소통장애의 5대 장애 중 하나인 유창성장애는 말의 흐름의 문제로 발생하는 ‘유창성 문제’를 다루는 과목이다. 이 과목에서는 유 창성장애의 원인과 이를 설명하는 다양한 이론, 특성, 평가와 치료 방법 등을 공부한다. - 유창성장애의 원인, 특성, 진전과정을 이해하고 각 대상자에 맞는 평가 실시 방법과 다양한 치료 프로그램에대해 살펴보고 학습할 수 있다. 1. 유창성장애의 원인에 관련된 다양한 이론을 이해한다. 2. 유창성장애의 특성과 진전과정을 이해한다. 3. 유창성장애 대상자에 맞는 신뢰롭고 타당한 평가 방법과 도구, 치료 방향과 기술 및 치료 프로그램등을 이해한다. 4. 평가와 치료 과정에 관한 이론과 실제를 직/간접적으로 접하여 균형잡힌 임상적 시각을 갖춘다. 5. 다양한 분야의 전문가들이 관심을 갖고 있는 ''유창성''에 관한 최신 연구들을 공부함으로써 근거기반중재를 실시할 수 있는 독립적 인 치료사로서의 자질을 갖춘다. 6. 언어치료전공생으로서 대상자 및 보호자에 대한 윤리적인 태도를 기른다. 7. 수업진행 과정에서 이루어지는 동료와 적극적으로 상호작용하며 긍정적인 관계를 맺는다. 8. 본 수업에서 이루어지는 과제, 토의/토론 등에 적극적이고 성실한 태도로 임한다.', '{"토의토론","교재","강의안","요약지","치료","아동의","말더듬","살펴본다","유창성장애의","퀴즈","주교재","학령전","학령기","청소년","비유창성","방법들을","이해하고","진단과정을","검사도구들을","성인의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('504425', '생명과학I', '자연과학대학', '자연과학대학', 0, 3, '전선', '김경원', '-본 교과목은 생명과학 전공자로서 갖추어야 할 핵심적인 생물학 기초 이론을 학습하고, 이를 실험 실습과 연계하여 생명현상의 기본 원리를 입체적으로 규명하는 것을 목표로 한다. -세포생물학, 유전학, 생리학 등 생명과학의 핵심 이론을 습득하여 생명현상의 기본 원리를 과학적 언어로 설명할 수 있다. -확립된 기초 지식을 바탕으로 분자생물학, 생화학 등 고학년의 심화 전공 교과목을 이수할 수 있는 논리적 사고력과 학문적 기초 체 력을 완성한다. -생명현상의 기본 원리(세포, 에너지, 유전)를 이해하고 이를 정확한 학술 용어로 정의 및 설명할 수 있다. -생명현상의 작동 메커니즘(Mechanism)을 분자 및 세포 수준에서 파악하고, 주요 생물학적 현상에 대해 인과관계를 중심으로 과학적 으로 추론하고 해석할 수 있다. -확립된 기초 이론을 바탕으로, 향후 심화 전공 교과목에서 다루는 난이도 높은 내용을 이해하고 수용할 수 있는 학문적 토대를 완성 한다.', '{"교수님","생명현상의","세포","목요일","시행","예정","유전자","이론을","있다","에너지","유전","생물학적","이를","원리를","한다","과학적","설명할","확립된","바탕으로","전공"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('540034', '신경언어장애', '자연과학대학', '자연과학대학', 0, 3, '전선', '윤지혜', '1.신경언어장애의 이론적 배경에 대하여 학습하고, 신경언어장애와 관련된 임상기초지식을 습득한다. 2.신경언어장애의 하위 유형 및 특징을 학습한다. 3.학생들의 종합적 사고력을 배양하여 임상현장에서 환자를 합리적으로 진단할 수 있도록 평가 도구에 대하여 학습한다. 4.평가에 대한 적절한 해석을 바탕으로 환자의 신경언어장애 특징을 파악할 수 있도록 한다. 5.적절한 치료방향을 수립하는 토대를 마련하고 치료법에 대하여 숙지한다. 지식 -신경언어장애의 이론적 배경 및 관련 임상기초지식 습득 -신경언어장애의 하위 유형 및 특징 학습 -신경언어장애 진단도구 활용법 학습 기술 -적절한 평가도구를 사용하여 임상현장에서 환자를 합리적으로 진단할 수 있는 능력 -평가에 대한 적절한 해석을 바탕으로 치료계획을 수립하고 치료하는 기술 -다양한 신경질환으로 발생할 수 있는 언어장애 환자에게 언어재활사로서 적절한 서비스를 제공할 수 있음 태도 -위에서 제시한 이론적 지식을 바탕으로 환자의 상황을 이해하고 공감할 수 있는 태도 -조별 과제를 수행하며 타인을 배려하고 협동하는 태도 -적극적인 토론을 지향하고 논리적으로 자신의 의견을 제시할 수 있는 태도', '{"학습한다","교재","실어증","인한","있는","신경학적","신경언어장애와","언어장애의","특성과","치료법을","대하여","적절한","임상기초지식","신경언어장애의","유형","태도","배부","실어증학의","동반될","전반적인"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543000', '보완대체의사소통', '자연과학대학', '자연과학대학', 0, 3, '전선', '최지은', '보완대체 의사소통(AAC; Augmentative and alternative Communication)은 말과 언어의 이해 및 표현에 어려움을 가진 사람들의 구 어를 보완하거나 대체하는 것을 말한다. 본 강의를 통해 AAC의 이론적 기초와 유형을 습득하고, 다양한 장애유형에 따른 평가와 중재전략을 익힌 후 임상현장에서 사용 가능 한 AAC 도구(high-tech/low-tech)를 제작할 수 있도록 한다. - AAC의 이론적 기초를 습득한다. - AAC 평가원리를 습득하고 각 장애군과 대상자의 특성에 따른 평가 전략을 익힌다. - AAC 중재원리를 습득하고 각 장애군과 대상자의 특성에 따른 중재전략을 익힌다. - 가상 사례를 대상으로 AAC 평가 및 중재전략을 수립하여 그에 따른 AAC 도구를 제작한다.', '{"주교재","중재","부교재","의사소통","도구","가상","따른","비도구적","상징과","도구적","상징","한국","보완대체의사소통","매뉴얼","개념과","후천성","장애인을","사례에게","가능한","제작"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('504431', '캡스톤디자인생물', '자연과학대학', '자연과학대학', 0, 3, '전선', '김경원', '1-2학년 동안 배운 전공 교과목 및 이론 등을 바탕으로, 산업체(또는 사회)가 필요로 하는 과제를 대상으로 학생들이 스스로 기획과 종합적인 문제 해결을 통해 창의성과 실무능력, 팀 웍, 리더십을 배양하도록 한다. 각 담당교수와 상의하여 연구 주제를 선정하여 진행한다. 본 수업은 (주)온생물 기업의 문제해결을 위한 과제 수행을 목표로 한다. (기업연계형-아이디어 도출) 산업체(또는 사회)가 필요로 하는 과제를 대상으로 학생들이 스스로 기획과 종합적인 문제해결을 통해 창의성과 실무능력, 팀 웍, 리 더십을 배양한다.', '{"캡스톤디자인","바탕으로","산업체","또는","필요로","하는","과제를","대상으로","학생들이","스스로","기획과","종합적인","창의성과","실무능력","한다","문제해결을","강의계획서","기획","팀별","프로젝트"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543018', '말과학', '자연과학대학', '자연과학대학', 0, 3, '전선', '이승진', '말(speech)은 의사소통의 토대가 되며, 말에 대한 이해는 의사소통과 그 장애를 보다 깊게 이해하는 기초가된다. 따라서 이 수업은 말 의 기본적인 산출 메커니즘을 이해하는 데 그 목적이 있다. 이를 위하여 조음 및 음향음성학에 관한 기초 지식을 습득하고, 말소리 산 출 및 지각의 원리를 이해하며, 한국어 말소리의 음향학적 특성을 이해하도록 한다. 아울러 언어병리학의 다양한 의사소통장애 영역에 서 말 과학의 여러 원리를 활용한 다양한 검사도구들에 대한 조망을 돕는다. 지식 -호흡, 발성, 공명, 조음의 해부 및 생리에 관한 기초 지식을 숙지하고 이해할 수 있다. -소리의 파형과 공명에 대한 음향음성학적 지식을 이해할 수 있다. -말소리의 생성 과정 및 원리를 이해할 수 있다. 기술 -한국어의 모음 및 자음의 음향음성학적 특징을 토대로 음향학적 분석을 수행할 수 있는 능력을 갖춘다. -언어병리학의 다양한 장애군에서 관찰되는 말 장애에 대해 적절한 평가도구를 선정할수 있는 능력을 갖춘다. -말과학 지식을 활용하여 말 측면에 대한 평가 결과를 해석할 수 있는 능력을 갖춘다. 태도 -말장애 분야의 전문성을 지닌 언어재활사로서의 태도를 갖춘다. -말과학 분야의 다양한 평가 도구를 활용하는 실습에 적극적으로 참여하는 태도를 갖춘다. -과학적인 방법론과 최신지견을 끊임없이 자신의 분야에 적용하고자 노력하는 전문인으로서의 태도를 함양한다.', '{"강의노트","읽어오기","주차별","교재","있다","주교재","음향학적","이해한다","음성분석","예정","사용법","소리의","활용하여","지식을","프로그램","측정할","시행할","분석을","갖춘다","말과학"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('636505', '생명과학실험', '자연과학대학', '자연과학대학', 0, 2, '전선', '김경원', '-본 교과목은 생명과학 기초 이론을 실제 실험을 통해 검증하고, 생명과학 연구에 필수적인 기초 실험 기법을 습득하는 실습 중심 수 업이다. -현미경 조작, 용액 제조, 기초 생화학 및 분자생물학적 분석법 등을 직접 수행하며, 실험 결과의 관찰, 데이터 분석, 그리고 과학적 보 고서(Lab Report) 작성 과정을 통해 예비 연구자로서 갖추어야 할 실무적 탐구 능력을 배양한다. -습득한 실험 원리와 탐구 방법론은 향후 심화 전공 과정의 이해도를 높이고, 보다 전문적인 연구 기법을 응용할 수 있는 학문적 기초 가 된다. -생명과학 연구 현장에서 보편적으로 사용되는 실험 기구의 원리를 이해하고 능숙하게 조작하는 능력을 기른다. -강의실에서 학습한 생명현상의 기본 원리를 실험을 통해 직접 확인하고 검증함으로써 지식을 입체적으로 완성한다. -실험 데이터를 논리적으로 해석하고 이를 표준화된 양식의 보고서로 작성하여 결과를 명확히 전달하는 능력을 갖춘다.', '{"실험실습","관찰","사용법","식물","관찰한다","실험","현미경","해부","세포","분열","동물","용액","제조","익힌다","원리를","원생생물","광학","동물세포","생물학","실험에서"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('636509', '바이오헬스산업특론', '자연과학대학', '자연과학대학', 0, 3, '전선', '최성훈', '- 바이오헬스 분야 산업체 취업에 필요한 정보 습득을 통해 자신의 특성에 보다 적합한 취업 준비에 도움을 주고자 함. - 다양한 바이오 산업계 세부 종류와 특징, 직종과 직무특성에 대한 정보를 제공함 - 별도의 선수 학습 내용은 없음 - 수업은 교수 작성 PPT 파일 강의와 현 재직 중 전공자 특강 예정 - 수강생의 바이오헬스분야 산업계 수요 파악 - 바이오헬스 산업계의 동향 및 주요 변화에 대한 이해 - 동 산업계 직종 및 직무 특성에 대한 정보 제공 - 현직 전공자의 특강을 통한 성공 사례 공유', '{"바이오","필요한","산업계","산업군에","바이오헬스","정보","특성에","산업군","종류","취업과","연계된","취업하기","위해","지식","혹은","기술"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543023', '영유아의사소통장애', '자연과학대학', '자연과학대학', 0, 3, '전선', '이윤경', '영유아 시기의 언어 및 의사소통 발달과 평가 및 중재 대한 이론적 기초를 마련한다. - 발달의 개념과, 발달 영역간의 상호교류적 관계를 이해한다. - 다른 영역의 발달과 관련하여 영유아 언어 및 의사소통 발달을 이해한다. - 영유아 언어 및 의사소통 평가 절차를 이해한다. - 영유아 언어 및 의사소통 중재 절차를 이해한다. - 양육자 중심의 평가 및 중재 절차를 이해한다. 지식: 영유아기 발달, 영유아기 의사소통 발달, 영유아기 의사소통 평가, 영유아기 의사소통 중재 기술: 영유아의 언어 및 의사소통 발달을 평가하고 중재하는데 필요한 실제적 기술 태도: 언어치료사로써 영유아와 가족들을 이해하고 도움을 제공하는 것과 관련된 전문가적 태도', '{"의사소통","발달","이해한다","중재","영유아","질의","응답","영유아기","영유아기의","그룹","단계","협력적","언어","발달과","이해하고","영역","과정과","사회정서적","접근법","언어치료사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543026', '언어재활관찰', '자연과학대학', '자연과학대학', 0, 3, '전선', '황수진', '수업개요 본 교과목은 언어병리학 전공 임상실습 과목으로 강의를 통해 주요 의사소통장애 평가 및 치료과정에 대한 이론적 토대를 마련하고, 다양한 유형의 의사소통장애 진단 및 치료과정을 관찰하여 언어치료실습을 위한 기초를 형성하는 것을 목표로 한다. 수강생은 임상 감 독자인 담당교수의 강의를 통해 대상자의 배경정보, 의사소통 특성, 진단/중재 목표를 이해한 후 해당 대상자의 임상적 상호작용을 직간접적으로 관찰한다. 또한 관찰을 통해 일반 아동 및 의사소통 문제를 동반한 다양한 대상자의 언어 및 의사소통 특성, 대상자와 상호작용하는 언어재활사의 임상 기술(상담, 진단, 중재)을 이해하여 사례관찰보고서를 작성할 수 있다. * 보건복지부에서 발급하는 언어재활사(2급) 국가자격시험에 응시하기 위한 필수교과목으로 실습시간 인정, 실습생의 의무 등 제반사 항은 관련 응시기준 및 <언어병리학 전공 임상실습내규>에 따라 운영된다 1. 지식 - 언어치료실습의 전반적인 과정과 실습학생의 역할을 설명할 수 있다. - 의사소통장애 초기 면담과 언어평가의 목적 및 주요 내용을 설명할 수 있다. - 의사소통장애 유형별 언어 및 의사소통 특성을 파악하고 설명할 수 있다. - 언어재활사의 임상적 상호작용의 목표와 관련 기술(전문적 기술, 치료기법)을 설명할 수 있다. 2. 기술 - 의사소통장애 대상자의 다양한 배경정보를 수집하고, 영역별로 구분하여 관찰보고서를 작성할 수 있다. - 의사소통장애 유형별 의사소통 특성을 파악하여 관찰보고서를 작성할 수 있다. - 언어재활사의 임상적인 상호작용(진단 및 치료)의 목표와 관련기술을 파악하여 관찰보고서를 작성할 수 있다. 3. 태도 - 의사소통장애 대상자 및 보호자에 대한 개인정보를 철저히 보호하고 대상자 인권을 옹호하는 태도를 지닌다. - 수업 내 관련 주제의 토론에 성실하게 참여할 수 있다. 2. 교과 목표 ■ 교과목표 - 수업의 원활한 운영을 위해 성실하게 실습할 수 있다.', '{"중재","있다","특성을","설명할","주교재","사례관찰","의사소통장애","사례관찰보고서","절차","진단","언어발달장애","동반한","의사소통장애의","고려한","목표의","아동","진단을","발달장애","해당","의사소통"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107147', '종교철학', '인문대학', '인문대학', 0, 3, '전선', '서정원', '종교철학은 종교 현상과 철학적 사유를 결합하여 종교의 본질과 역할을 학문적으로 탐구한다. 이 과정을 통해 종교와 철학 간의 공통 점과 차이를 분석하며, 다양한 관점에서 종교적 사유를 이해하고 비판적으로 고찰하여야 한다. 나아가 종교철학적 이해를 바탕으로 개인과 사회의 삶에 미치는 실천적 의미를 탐색한다. 이번 교과목은 HUSS 사업과 연계된 것으로, 인문학의 통찰과 분석을 통한 융합형 인재 양성을 추구합니다. 1. 종교에 대해서 객관적, 비판적 입장에서 접근하여 학문적 이해를 도모한다. 2. 철학의 차이, 공통점 등을 확인하여 종교철학이라는 융복합적 학문을 학습한다. 3. 종교철학의 이해가 나의 삶과 사회에 어떤 의미를 갖는지 실천적 지혜를 갖춘다. 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에서 요구하는 융합인재상에 도달하는 것을 목적으로 한다.', '{"대해서","유인물","종교의","교재","이해를","이해한다","종교적","사회의","종교에","대해","개인의","철학적","종교와","이해하고","비판적으로","철학의","학습한다","사유를","한다","실천적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543027', '언어 진단실습', '자연과학대학', '자연과학대학', 0, 3, '전선', '심희정', '본 교과목은 언어병리학 전공 임상실습 교과목으로 의사소통장애를 가진 대상자의 의사소통 능력을 평가하여 진단하고, 평가를 토대 로 계획한 장단기 언어치료(언어재활) 목표에 따라 실시한 중재의 효과를 측정하는 일련의 언어재활 과정을 이해하고 실습하는 것을 목표로 한다. 수강생은 임상감독자의 감독하에 의사소통장애 진단의 계획하고 실제로 대상자 특성을 고려한 평가를 실시하고 평가보 고서를 작성하는 진단 역량을 갖추고 장단기 치료 목표에 따라 개별/협동 언어치료 실습을 통해 예비언어재활사로서의 임상 역량을 향상시킬 수 있다. - 본 수업은 한림대학교 언어치료실에서 이루어지는 교내 언어치료실습과 연계하여 진행되며, 구체적인 실습내용은 아래와 같다. 1. 언어재활실습에 필요한 제반 과정과 임상적 기초를 습득한다. 2. 의사소통 문제를 지닌 대상자의 수준을 이해하여 적합한 검사도구와 절차를 선정하여 평가를 실시한다. 3. 임상과 관련된 각종 보고서(평가보고서, 현행수준요약표, 장단기 계획서, 회기치료계획서)의 작성방법을 이해하여 작성한다. 4. 장단기 치료 목표에 기초하여 회기 치료계획을 세우고 회기 치료를 운영한다. 5. 대상자의 평가 및 치료 내용의 효율적인 전달을 위한 보호자 상담기술을 익힌다. 6. 학생언어치료사로서의 전문적인 자세와 윤리적 태도를 갖춘다. * 보건복지부에서 발급하는 언어재활사(2급) 국가자격시험에 응시하기 위한 필수교과목으로 실습시간 인정, 실습생의 의무 등 제반사 항은 관련 응시기준 및 <언어병리학 전공 임상실습내규>에 따라 운영된다. 1. 지식 - 실습 대상자의 의사소통장애의 유형과 의사소통 특성을 설명할 수 있다. - 의사소통장애 진단을 위한 의사소통 평가 절차 및 주안점을 설명할 수 있다. - 언어진단결과에 따라 개별화된 장단기 언어치료 목표를 설명할 수 있다. - 장단기 언어치료 목표에 따른 회기 언어치료의 계획을 설명할 수 있다. 2. 교과 목표 ■ 교과목표 2. 기술 - 대상자 및 대상자의 보호자를 면담하여 대상자의 배경정보를 수집할 수 있다. - 대상자의 의사소통장애 유형 및 수준에 고려하여 언어평가를 실시할 수 있다 - 언어진단평가 결과를 해석하고 언어평가보고서를 작성할 수 있다. - 대상자의 현행수준, 강약점을 고려하여 장단기 언어치료목표를 세울 수 있다. 3. 태도 - 학생치료사로서 대상자 및 보호자에 대한 윤리적인 태도를 지닌다. - 대상자, 동료학생치료사 및 임상감독자와 긍정적인 유대관계를 형성한다. - 언어진단실습 일련의 과정과 수업에 성실하고 적극적 참여 태도를 지닌다.', '{"팀별","대상자","사례","파일","해당","영상","대상자의","언어평가","장단기","작성","이해한다","의사소통","언어평가보고서","작성방법","치료","있다","절차","계획을","설정","방법을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107299', '한국철학사', '인문대학', '인문대학', 0, 3, '전선', '김지은', '본 강의는 고조선부터 조선시대에 이르기까지 한국인이 삶의 현장에서 직면했던 시대적 과제와 그 해답을 찾아가는 사유의 궤적을 추적합니다. 각 시대의 정치·경제·사회적 배경 속에서 한국 철학이 어떻게 형성되고 전개되었는지 입체적으로 고찰합니다. 이번 교과목은 HUSS 사업과 연계된 것으로, 인문학의 통찰과 분석을 통한 융합형 인재 양성을 추구합니다. 1. 한국철학의 주요 쟁점에 대한 역사적 고찰을 통해 한국철학사의 맥락을 파악합니다. 2. 현재와 미래의 한국철학이 담당해야 할 역할과 그 전망에 대해 고민합니다.', '{"사상","조선시대","논쟁","한국철학사","흐름","검토","단군신화","고조선","원효","삼국시대","지눌","고려시대","정도전","서경덕","이황","이이","중간고사","주차","구성요소","예송"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107327', '서양철학의고전', '인문대학', '인문대학', 0, 3, '전선', '류근호', '이 과목의 목표는 고전 강독을 통해 철학적 논증의 구조를 분석하고 자신의 방식으로 재구성하는 능력을 기르는 것입니다. 그 중 특 히 이번 학기에는 윤리학에 대한 고대(플라톤), 근대(칸트), 현대(니체)의 고전을 부분적으로 강독함으로써 여러 관점들을 비교, 검토 하고자 합니다. 플라톤의 『고르기아스』, 칸트의 『도덕형이상학 정초』, 니체의 『도덕의 계보』를 부분적으로 강독하고자 합니다. 이를 통해 그들의 윤 리에 대한 서로 다른 관점을 이해하고, 다양한 철학적 저술의 스타일도 체험할 수 있으리라 기대합니다. 이 교과목은 HUSS 사업과 연 계된 것으로서, 인문학적 통찰을 바탕으로 한 융합형 인재 양성을 목표로 합니다.', '{"강독","도덕형이상학","정초","고르기아스","도덕의","계보","논문","합니다","철학적","부분적으로","중간시험","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543028', '언어재활실습-캡스톤디자인', '자연과학대학', '자연과학대학', 0, 3, '전선', '심희정', '본 교과목은 언어병리학 전공 임상실습 교과목으로 의사소통장애를 가진 대상자의 장단기 언어치료(언어재활) 목표에 따라 실시한 중 재의 효과를 측정하는 일련의 언어재활 전반과정을 이해하고 실습하는 것을 목표로 한다. 또한 의사소통대상자에게 제공한 언어치료 ( 언어재활)를 통하여 대상자의 변화 및 실습생(학생언어치료사) 스스로 자기감독의 역량을 키우고 근거기반실제(evidence based practice)의 탐색과 적용르 실습하는 데 목적이 있다. - 본 수업은 한림대학교 언어치료실에서 이루어지는 치료실습과 연계하여 진행되며, 구체적인 실습내용은 아래와 같다. 1. 언어재활실습에 필요한 제반 과정과 임상적 기초를 습득한다. 2. 임상과 관련된 각종 보고서(장단기 계획서, 회기치료계획서, 진전/종결보고서 등)의 작성방법을 습득하고 실습한다. 3. 다양한 근거기반실제를 탐색하고 실습에 활용한다. 4. 대상자의 중재효과를 측정하고 해당 내용을 발표한다. 5. 대상자의 평가 및 치료에 대하여 보호자 상담방법을 익히고 실습한다. 6. 언어재활사의 전문적인 자세와 윤리적 태도를 습득한다. * 보건복지부에서 발급하는 언어재활사(2급) 국가자격시험에 응시하기 위한 필수교과목으로 실습시간 인정, 실습생의 의무 등 제반사 항은 관련 응시기준 및 <언어병리학 전공 임상실습내규>에 따라 운영된다. 1. 지식 - 의사소통장애 대상자의 의사소통 장애 유형 및 의사소통 특성을 설명할 수 있다. - 언어임상실습에 필요한 면담 및 상담의 주요 내용과 기술을 설명할 수 있다. - 언어평가 결과에 따라 장단기 중재(언어치료)목표 수립에 대해 설명할 수 있다. - 언어임상실습 회기 중재(언어치료)의 주요 내용과 절차를 설명할 수 있다. - 대상자의 장애유형 및 의사소통 능력을 고려하여 언어치료 관련 근거기반실제(EBP)를 선정할 수 있다. 2. 기술 2. 교과 목표 ■ 교과목표 - 장단기 치료 목표에 근거가 한 회기 치료를 구성하고 대상자의 행동을 측정할 수 있다. - 대상자 행동 변화 측정 및 해석을 포함한 임상보고서(회기치료보고서, 진전보고서)를 작성할 수 있다. - 장단기 목표에 의거한 중재(언어치료) 계획을 수립하고, 계획에 따라 실행할 수 있다. - 대상자 및 보호자에게 평가 및 중재(언어치료)와 관련된 적절한 상담을 수행할 수 있다. 3. 태도 - 예비언어재활사로서 대상자 및 보호자에게 윤리적 태도를 가진다. - 실습파트너 및 실습감독자와의 긍정적 유대관계를 형성한다. - 실습 시 다양한 돌발상황에 대한 문제해결능력을 갖춘다', '{"있다","팀별","회기","치료","진전","대상자의","대상자","장단기","언어치료","종결","언어재활","의사소통","탐색","설명할","언어재활을","계획","면담","측정","작성할","계획을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107345', '한국사상현장답사', '인문대학', '인문대학', 0, 1, '전선', '최승락', '한국사상현장답사는 1학점 수업으로, 우리나라의 사상과 문화가 담긴 여러 유적을 방문하여 직접 살펴보고 견문을 넓히는 데 그 목적 이 있습니다. 출석 수업은 없으나, 자료집 준비 등과 관련하여 필요한 경우 몇 차례 모임을 가질 수 있습니다. 학점은 다음 두 과제를 통해 부여됩니다. 1) 참여 학생들은 2~3명씩 조를 이루어 방문할 유적을 미리 조사한 뒤 자료집에 실을 내용을 마련하고, 답사 현장 에 서 간략히 발표를 진행합니다. 2) 답사를 다녀온 뒤 개인별로 ppt 10장 이상의 답사 기록 및 소감(직접 찍은 사진을 포함)을 제출합니 다. 이 ppt는 가을 학술제에 자동으로 응모되며, 심사를 거쳐 상장과 상금 등이 주어질 수 있습니다. 우리나라의 사상과 문화를 삶의 현장 속에서 직접 체험하고, 그 과정에서 협동심과 공동체 정신을 기릅니다. 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에서 요구하는 융합인재상에 도달하는 것을 목적으로 합니다.', '{"직접","있습니다","답사","우리나라의","사상과","유적을","현장"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107500', '서양철학의이해', '인문대학', '인문대학', 0, 3, '전선', '강재연', '철학이란 무엇일까요? 때때로 철학은 어렵고 현실과 동떨어진 학문이라 오해되기도 합니다. 그러나 철학은 국가 제도와 사회 체계, 행동 규범, 자유와 책임, 권리와 의무 같은 우리가 당연하게 받아들이는 문제들에 대해 근원적인 사유의 토대를 제공해 왔습니다. 특 히 오늘날의 AI 시대는 무엇이 옳은지를 어떻게 분별할 것인가, 그리고 알고리즘이 어떠한 판단을 내리도록 설계해야 하는가라는 문 제들에 대해 그 어느 때보다 깊은 철학적 성찰을 요구하고 있습니다. 이 수업에서는 고대로부터 현대까지 진리, 앎, 국가, 사회, 도덕 과 윤리에 관한 서양철학의 논의를 개괄적으로 다루며, 철학이 우리 사회의 토대 형성에 어떠한 역할을 해 왔는지, 그리고 철학적으 로 사유한다는 것이 무엇인지를 살펴보고, 궁극적으로 철학이 우리의 삶에 어떤 ‘쓸모’를 지니는지를 확인할 것입니다. 이 수업은 HUSS 사업과 연계된 것으로, 인문·사회학의 통찰과 분석을 통한 융합형 인재 양성을 추구합니다. 우리 수업은 철학을 또 하나의 지식의 영역으로 다루지 않고, 지식을 생산하고 비판적으로 다루는 사유의 방법으로서 접근합니다. 수 업의 목표는 다음과 같습니다. 1. 고대에서 현대에 이르기까지 주요 서양 철학자들의 사상을 두루 접함으로써 서양철학 전반에 대한 기초적 이해를 함양한다. 2. 철학 문헌을 직접 읽고 관련된 현안들에 대해 토론함으로써 텍스트 독해력과 비판적 사고력, 토론 능력을 종합적으로 기른다. 3. 철학적 개념과 논증을 일상적 문제와 사회적 쟁점에 적용함으로써 사유를 현실 비판과 성찰의 도구로 활용하는 능력을 갖춘다. 이를 통해 본 교과목은 인문사회 융합인재양성사업에서 요구하는 융합인재상에 도달하는 것을 목적으로 합니다.', '{"철학적","사회의","토대","이해한다","이론을","근대","고대","국가의","동시대","배경을","이후","사회가","마련한","로크와","루소의","제공한","칸트의","벤담의","공리주의","비판하며"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543044', '학습장애언어재활', '자연과학대학', '자연과학대학', 0, 3, '전선', '설아영', '1. 학령기 전반적인 말, 언어, 의사소통, 읽기 및 쓰기발달에 관한 지식을 습득한다. 2. 학습장애 및 특정학습장애를 이해한다. 3. 학령기 언어발달 장애의 특성을 이해한다. 4. 학령기 언어장애의 진단평가 방법과 과정을 이해한다. 5. 학령기 언어장애 특성에 따라 적절한 치료교육 방법을 선택하고, 치료과정을 이해할 수 있다. 1. 학령기 전반적인 말 언어 의사소통 읽기 및 쓰기 발달에 관한 지식을 습득한다. 2. 학습장애, 특정학습장애를 이해한다. 3. 학령기 언어장애 및 읽기쓰기 장애의 특성을 이해한다. 4. 학령기 언어장애의 진단평가 방법과 과정을 이해한다. 5. 학령기 언어장애 아동의 특성에 따른 적절한 치료교육 방법을 이해한다.', '{"학령기","이해한다","언어장애","전반적인","언어","의사소통","읽기","관한","지식을","습득한다","학습장애","특정학습장애를","장애의","특성을","언어장애의","진단평가","방법과","과정을","특성에","적절한"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543047', '의사소통장애진단평가', '자연과학대학', '자연과학대학', 0, 3, '전선', '심희정', '본 수업은 의사소통장애 분야의 진단 및 평가에 필요한 기본 지식을 습득하고, 임상현장에서 빈번하게 사용되는 국내 표준화 검사 및 준거참조 검사를 중심으로 의사소통장애의 진단 및 평가 방법을 학습하는 것을 목표로 한다. 강의 및 협동학습을 통하여 아동기의 다양한 의사소통장애 유형을 이해하고, 의사소통장애 대상자의 연령을 및 장애유형을 고려한 검사도구 및 방법을 선정하여, 의사소통 장애 진단평가 능력을 함양할 수 있다. 1. 지식 - 의사소통장애 진단평가의 전반적 과정을 설명할 수 있다. - 의사소통장애 유형별 언어 및 의사소통 특성을 설명할 수 있다. - 의사소통장애 유형별 주요 평가 영역 및 주안점을 설명할 수 있다. - 검사지침에 기반하여 언어검사 실시 및 해석 방법을 설명할 수 있다. 2. 기술 - 의사소통 수준 및 장애유형을 고려한 평가 계획 및 검사도구를 선정할 수 있다. - 의사소통장애 관련 표준화 검사의 실시지침에 따라 검사를 실시할 수 있다. - 의사소통평가 결과를 해석하고 언어평가 보고서 작성할 수 있다. 3. 태도 - 의사소통장애 대상자 및 보호자에 대한 윤리적 태도를 가진다. - 검사실시 및 보고서 작성에 대한 성실한 태도를 가진다.', '{"있다","강의노트","이해할","절차","이해하고","진단평가","목적","의사소통장애","아동언어장애","절차를","주안점","언어검사","도구를","진단평가의","학령기","진단","설명할","수집","의사소통","과정을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107501', '제자백가의철학', '인문대학', '인문대학', 0, 3, '전선', '김지은', '춘추전국시대에 등장하여 일가를 이룬 철학자들을 ''제자백가''라고 합니다. 본 강의에서는 제자백가를 대표하는 ''공자'', ''맹자'', ''순자'', ''관자'', ''한비자'', ''장자''의 철학 사상과 그들의 원전을 함께 천천히 살펴봅니 다. 이를 통해 제자백가의 철학이 현재를 살아가는 우리에게 어떤 통찰을 제공하는지 탐구합니다. 이번 교과목은 HUSS 사업과 연계된 것으로, 인문학의 통찰과 분석을 통한 융합형 인재 양성을 추구합니다. 1. 제자백가(공자, 맹자, 순자, 관자, 한비자, 장자)의 기본 관점과 핵심 개념을 이해합니다. 2. 고전을 함께 읽으며 자신의 일상과 삶을 성찰합니다.', '{"함께","사상","읽기","맹자","순자","관자","한비자","장자","공자","논어","제자백가","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('543050', '구개열언어재활', '자연과학대학', '자연과학대학', 0, 3, '전선', '하승희', '구체적인 수업 내용은 다음과 같다. 1) 안면구개 파열의 다양한 종류 2) 인간의 얼굴과 구개 구조의 태생학적 발달의 일반적인 특징들 3) 구순구개열 아가에게서 관찰되는 섭식 문제와 해결법 4) 구순구개열을 가진 사람에게서 나타나는 일반적인 심리사회적인 문제점들 5) 연인두 부위의 해부학적, 생리적 특징들 6) 연인두 기능부전을 평가하는 진단 절차들 7) 구순구개열을 가진 사람들이 구강성형, 치과, 말, 언어문제와 관련되어 받는 주요 치료법 구개열 아동을 위한 언어평가와 치료, 상담 서비스를 적절하게 제공할 수 있는 지식과 기술을 습득한다. 구개열 언어재활 실무에 필요한 지식과 기술을 체계적으로 배양한다.', '{"구개열","대해서","유형과","익힌다","강의식","언어","구순구개열","관련된","강의노트","한림대학교","강의지원","챗봇","서비스","주차","원인","강의내용을","손글씨로","정리하고","내용과","질문"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107502', '불교와현대', '인문대학', '인문대학', 0, 3, '전선', '서정원', '현대사회를 구성하는 경제적, 과학적 전제들과 종교, 특히 불교의 관계를 학습하고, 이를 바탕으로 현대사회에서 초래된 구체적인 문 제들에 종교와 불교가 어떤 해답을 줄 수 있는지 모색한다. 이를 통해 인문학 중 가장 현대사회의 가치와 멀어보이는 종교(불교)의 접 점을 찾아 인문학적인 가치가 무엇인지 확인한다. 이번 교과목은 HUSS 사업과 연계된 것으로, 인문학의 통찰과 분석을 통한 융합형 인재 양성을 추구합니다. 1. 현대사회의 경제적, 과학적 구조(이데올로기)를 철학적 관점에서 익힌다. 2. 현대사회의 구조와 종교(불교)가 어떤 관계를 갖는지 이해한다. 3. 현대사회의 여러 문제에 대해서 해결책을 종교(불교)적으로 모색해본다. 4. 현대사회와 종교(불교)의 관련성을 다양하게 모색해 본 바를 현대사회와 일반 인문학(철학) 전반과의 관계를 모색하는 하나의 방법 론으로 정리한다. 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에서 요구하는 융합인재상에 도달하는 것을 목적으로 한다.', '{"유인물","불교","강독","현대사회의","종교","종교의","에서","현대사회와","현대사회가","구성되는","과정에서","역할","가라타니","고진","부분","관계를","이를","현대사회에서","구조","구조와"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('540071', '심리음향학', '자연과학대학', '자연과학대학', 0, 3, '전선', '한희경', '본 교과목은 심리음향학 분야에서 중요하게 다루는 다양한 기본 지식을 습득하고 관련 지식이 임상 및 연구 분야에 어떻게 적용되고 활용될 수 있는지를 이해하고 탐구하는 것을 목표로 합니다. 수강생의 자기주도 학습 분위기를 조성하고 학습 효과를 최대화하기 위하여 수업진행 방식은 강의식+토론식으로 진행될 예정입니다 . 해당 교과목 이수를 통하여, 향후 청각 분야 혹은 청각 관련 분야의 전문가로서 기본 지식을 견고히 하고 나아가 역량있는 전문가로 예비하는 것을 목표로 합니다. 본 강의의 학습목표는 다음과 같습니다. 1) 소리의 물리적/심리적 특성을 이해할 수 있다. 2) 음향신호처리 원리를 이해하고 해석할 수 있다. 3) 신호탐지이론(signal detection theory)을 이해할 수 있다. 4) 청각 지각(auditory perception) 및 양이 처리(binaural processing)의 기본 원리와 관련 이론을 이해할 수 있다. 5) 심리음향학의 임상적·연구적 의의를 발견하고 실제에 적용할 수 있다.', '{"있다","혹은","개별","팀별","이해할","음향","특성과","청각","원리를","파악할","주차","신호탐지에","영향을","미치는","신호탐지이론","자극","소리","요소","청각해부생리를","자극의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107513', '인도철학', '인문대학', '인문대학', 0, 3, '전선', '양영순', '이 강좌는 “인도철학이 왜 지금 우리에게 필요한가?”라는 질문에서 출발해, 서양철학과 중국·한국철학 사이에 가려져 잘 보이지 않았 던 인도철학의 큰 지도를 흥미롭게 펼쳐보는 수업입니다. 인도철학은 불교의 사상적 토대일 뿐 아니라, 동아시아 사상과도 깊게 연결되어 있어서 우리가 익숙한 사유의 뿌리를 새롭게 이해하 게 해줍니다. 동시에 고대 서양철학과도 놀라운 공통점과 접점이 많아, 서로 다른 철학 전통을 한 번에 비교하며 “철학은 결국 무엇을 묻는가”를 입 체적으로 바라보게 합니다. 특히 인도철학은 종교와 긴밀히 맞닿아 있으면서도, 명상과 성찰 같은 내면의 훈련을 중시하고, 한편으로는 치밀한 인식론과 논쟁의 논리학을 발전시켜 “직관과 논리”를 함께 다루는 독특한 철학 세계를 보여줍니다. 그래서 이 수업은 단순한 사상사 소개를 넘어, ‘나는 누구인가’, ‘세계는 어떻게 성립하는가’, ‘지식은 어떻게 가능한가’ 같은 질문을 따라가며 스스로의 사고를 단단하게 만들 수 있도록 돕습니다. 또한 베다와 우파니샤드의 사유, 자유사상가(슈라마나) 전통과 불교의 문제의식, 그리고 다양한 철학적 쟁점을 통해 인도 6파 철학을 차근차근 살펴보며, 학생들이 동서 철학을 통합적으로 이해하는 새로운 관점을 갖도록 안내합니다. 나아가 직접 작성한 논술문을 토대로 동료들과 소통하는 토론 수업(2-3회)을 통해, 스스로 답을 찾아가는 주체적인 사유의 즐거움과 자신감을 경험하게 될 것입니다. 이번 교과목은 HUSS 사업과 연계된 것으로, 인문학의 통찰과 분석을 통한 융합형 인재 양성을 추구합니다. 첫째, 인도 철학의 사상적 문화적 맥락 이해 둘째, 베다와 우파니샤드 2. 교과 목표 ■ 교과목표 셋째, 자유사상가(슈라마나)와 불교 넷째, 다양한 철학적 쟁점을 통한 인도 6파 철학의 이해', '{"질의응답","수업태도","태도","철학","그리고","고대","인도","우파니샤드","슈라마나","철학적","인도의","학파","인도철학은","어떻게","철학의","어떤","흐름","최초의","계시의","주차"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107514', '서양현대철학의주제들', '인문대학', '인문대학', 0, 3, '전선', '성기현', '이 수업은 서양현대철학의 주요 주제들 중 하나를 골라 한 학기 동안 심층적으로 탐구합니다. 이번 학기에 우리가 다루고자 하는 주 제는 실존주의입니다. 실존주의는 20세기 초 프랑스와 독일을 중심으로 전개되었던 철학 사조로서, 1·2차 세계대전으로 혼란스럽던 시기에 철학과 문학을 비롯한 인문학 전반에 큰 영향을 미쳤습니다. 우리는 실존주의를 대표하는 프랑스의 철학자 장 폴 사르트르의 『실존주의는 휴머니즘이다』와 『문학이란 무엇인가』 중 일부를 발췌하여 읽게 될 것입니다. 이를 통해, 실존주의적 관점에서 삶·사회· 예술을 이해하는 몇몇 개념적 도구들을 얻는 데 이번 수업의 목표가 있습니다. 이번 교과목은 HUSS 사업과 연계된 것으로, 인문학의 통찰과 분석을 통한 융합형 인재 양성을 추구합니다. 1) 실존주의 일반과 사르트르 철학을 개괄적으로 이해한다. 2) 실존, 타인, 시선, 앙가주망, 인도된 창조 등 사르트르 철학의 주요 개념들을 익힌다. 3) 학문적 텍스트를 체계적으로 읽는 방법을 배운다(천천히 분석하면서 읽기, 자신이 이해한 바를 텍스트에 비추어 확인하기, 질문과 토론을 통해 심화하기).', '{"읽기","텍스트","실존주의는","휴머니즘이다","문학이란","무엇인가","전반부","사르트르의","생애와","사상","현대프랑스철학사","이번","철학의","사르트르","프랑스","위대한","시절","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('540081', '신경과학 개론', '자연과학대학', '자연과학대학', 0, 3, '전선', '안현정', '본 교과목은 신경계의 구조와 기능에 대한 기초적인 이해를 제공하는 과목으로, 중추신경계와 말초신경계의 해부학적 구성과 생리적 작동 원리를 체계적으로 학습한다. 뉴런의 구조와 신호 전달 기전, 감각 및 운동계의 기본 경로, 뇌 주요 영역의 기능을 중심으로 신 경계 전반에 대한 개념을 다룬다. 이를 통해 학생들은 이후 전공 심화 과목에서 요구되는 신경학적 사고의 기초를 확립하게 된다. 본 교과목을 통해 학생들은 신경계의 기본 구조와 기능을 이해하고, 신경 신호 전달의 생리적 원리를 설명할 수 있으며, 감각·운동·인지 기능과 관련된 신경계의 역할을 통합적으로 이해하는 것을 목표로 한다. 또한 신경계 이상이 인간의 행동과 기능에 미치는 영향을 기초 수준에서 해석할 수 있는 능력을 기른다.', '{"구조와","기능","신경계의","신호","신경계","시냅스","중추신경계와","전달","운동계의","신경","전달의","운동","기능에","생리적","원리를","감각","기능을","학생들은","구성","말초신경계"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108203', '고고학입문', '인문대학', '인문대학', 0, 3, '전선', '이정철', '과거 사람들이 남긴 유적과 유물을 발굴하고 분석하여 옛사람들의 문화를 복원하고 설명하는 학문이 고고학이다. 본 수업에서는 고 고학의 개념과 용어, 조사 방법론, 고고학에서의 시대구분, 고고학 자료의 이해, 고고학과 학제간 연구, 고고학과 문화유산의 관계 등 을 개괄적으로 강의한다. 과거 인간 물질문화의 이해를 목표로 하는 본 강의는 고고학의 기초적인 지식을 제공한다. 고고학에 대한 기초 지식의 습득 - 고고학의 개념과 방법에 대한 초보적 이해 - 고고학 물질문화인 유적, 유구, 유물에 대한 관심 증대 - 고고학 용에 대한 기초 지식 배양 - 고고학과 문화유산에 대한 개념 설정', '{"고고학","자료","활용한","주차","수업은","중간고사로","평가함","자료의","프로젝트롤","고고학과","고고학의","프로젝트를","조사","빔프로젝트를","편년","방법의","학교","박물관","관람","고고학에서의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('544316', 'HEARING PATHO', '자연과학대학', '자연과학대학', 0, 3, '전선', '한우재', '본 교과목은 청각 및 귀 관련 주요 질환의 정의, 원인, 병태생리, 임상 증상을 체계적으로 이해하여 임상적 사고력을 함양하는 데 목표 를 둔다. 청각학 전공자로서 각 질환이 초래하는 청능장애 양상을 병인·해부생리와 연계해 설명할 수 있는 분석 역량을 기른다. 대표 적 청각 질환별로 적절한 청각학적 검사 프로토콜과 재활 방향을 스스로 도출·제시하는 임상 적용 능력을 강화한다. 강의와 퀴즈, 그 룹 활동을 통해 실제 검사 결과와 사례를 해석하고 핵심 정보를 요약·정리하는 문제 해결 및 의사소통 역량을 함양한다. 더 나아가 다 양한 청각병리 사례를 바탕으로 향후 심화 과목 및 임상실습에서 요구되는 전문성, 자기주도적 학습 태도, 팀 기반 협업 역량을 갖추 도록 한다. 첫째, 학생들은 청각 및 귀 관련 주요 질환의 정의, 원인, 병태생리, 임상 증상을 체계적으로 설명할 수 있으며, 이를 바탕으로 청각계 질환에 대한 통합적인 이해를 형성한다. ？둘째, 학생들은 각 질환이 초래하는 청능장애 양상을 청각기관의 해부생리와 연계하여 분석하고, 기도·골도 청력도, 어음청력검사, 임피던스 등 기초 청각검사 결과를 해석할 수 있다. ？셋째, 학생들은 대표적인 청각 질환별로 적절한 청각학적 검사 프로토콜을 선정하고, 임상 상황을 가정하여 검사 순서와 해석 기준 을 논리적으로 제시할 수 있다. ？넷째, 학생들은 각 질환의 특성과 환자의 청능 프로파일을 고려하여 보청기, 인공와우, 보조기기, 상담·교육 등 가능한 청각재활 방 향을 제안하고 그 근거를 설명할 수 있다. ？다섯째, 학생들은 강의, 퀴즈, 그룹 활동을 통해 제시된 실제 혹은 가상의 임상 사례를 팀 기반으로 분석하고, 질환 개요？검사 결과 ？재활 전략을 구조화하여 발표·보고하는 의사소통 및 협업 역량을 기른다. ？여섯째, 학생들은 매주 학습한 질환에 대해 스스로 학습목표를 설정·점검하고, 추가 문헌 및 자료를 탐색하여 지식을 확장함으로써 청각학 전공인으로서 자기주도적 전문성 개발 태도를 함양한다.', '{"워크시트","있다","채점","설명하고","재활","검사","토의","난청","청력도","케이스","임상","그룹","정리할","자율","청각","원인","주차","내이염","임피던스","병태생리"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('107519', '논리와사고', '인문대학', '인문대학', 0, 3, '전선', '최승락', '본 수업은 전면 영상 강의 및 절대평가로 진행됩니다. 매주 75분 ~ 120분의 수업 영상을 시청하고 매주 10문제의 연습문제를 스스 로 푸는 시간을 가집니다. 중간고사와 기말 고사는 없으며 매주 과제 점수를 투명하게 공개하니 1주차에 공개된 설문 및 수업 소개를 꼭 확인해 주세요. 논리학의 전문적 지식을 다루는 수업이라 다소 어려울 수 있지만 성적에 반영되는 모든 문제의 답은 영상과 수업 자료로 제공하니 성실히 수업을 따라오면 만족할만한 점수를 받을 수 있도록 수업을 구성하였습니다. 본 수업은 생각이나 논증을 올바르게 이해하고 분석하며 평가하는 능력인 논리적 사고(Logical Thinking)의 기술을 습득하는 것을 목표로 합니다. 역사학, 물리학, 경제학 등 개별 학문을 통해 간접적으로 사고력을 기르는 방식에서 벗어나, 논리학적 규칙과 체계를 직접적이고 명시적인 방식으로 학습함으로써 사고의 도구 자체를 연마하는 데 집중합니다. 구체적으로 연역 논증과 귀납 논증의 다양한 형식을 학습하고, 논증의 타당성과 건전성을 평가하는 연습을 수행합니다. 교수는 논 증의 형식과 기본 규칙을 예시를 통해 제시하며, 학생들은 개인별 연습과 조별 토론을 통해 실제 논증 평가 방법을 체화하게 됩니다. 특히 본 교과목은 인문사회 융합인재양성사업(HUSS)의 핵심 목표인 ‘Local C-nergy 융합인재 양성’을 실현하기 위한 교육과정의 일 환으로 설계되었습니다. 논리적 사고력을 바탕으로 지역과 사회의 복잡한 문제를 창의적으로 해결할 수 있는 기초 역량을 배양함으 로써, HUSS 사업이 추구하는 융합 인재상에 도달하는 것을 최종 목적으로 합니다. 논리적 사고 능력을 함양하기 위해 이 수업에서는 다음과 같은 기술 및 지식을 학습합니다. (1) 일상적인 대화와 전문적인 대화에서 사용되고 있는 논증 형식을 학습하고 올바른 논증이 무엇인지를 학습합니다. (2) 논증에 사용되는 기본적인 추론 규칙(문장 논리의 규칙부터 술어논리의 규칙)을 학습하고 이를 자유자재로 적용하는 연습을 합니 다. (3) 추론능력과 비판능력을 높이기 위해 연역논증과 귀납논증을 구별하는 능력을 기릅니다. (4) 일상적인 대화와 전문적인 대화에서 사용되고 있는 논리적 오류를 판단하는 능력을 기릅니다. (5) 한 학기 동안 배운 논리학의 지식을 사용해 공직적성평가(PSAT)의 언어논리 영역과 법학적성시험(LEET)의 추리추론 문제를 풀어 보는 시간을 가집니다.', '{"영상","온라인","동영상","스마트리드","강의슬라이드","교재","시청","주간","퀴즈","구글폼","문장","논리","논리적","구문론","술어논리","규칙을","추론","이고","이면","논리의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('655006', '생명윤리와환경윤리', '인문대학', '인문대학', 0, 3, '전선', '주동률', '현대 사회의 윤리적 문제들 중에서 철학적 윤리학적 차원에서도 중요하고 개인적, 사회적 차원에서 실천적 해결을 시급하게 요구하 는 두 영역, 즉 생명 윤리와 환경 관련적 문제들을 논의하고 대표적 해결책의 장단점을 검토한다. 생명과 환경윤리의 주요 문제들, 그 문제들에 대한 대표적 해결책들을 공부하고 그 문제들에 대한 학생들 자신의 합리적 의견을 형성 하는 과정에서 기초적 자원을 제공한다.', '{"유인물","안락사","문제들","대표적","문제들에","윤리학과","보편적","기회","평등과","실질적","평등","평등주의적","생명윤리","낙태의","수정란과","태아","중간고사","주차","구성요소","적극적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('544329', '이명평가및재활', '자연과학대학', '자연과학대학', 0, 3, '전선', '진인기', '수업개요 : 이명의 평가 및 재활 수행을 위한 기초 이론과 실습기회를 제공하기 위한 전공 수업입니다. 임상적으로 증명된 전통적인 방법과 더불어 최신 경향을 모두 다룰 예정입니다. 강좌 요약: 각 평가 및 재활방법에 대해 이론 학습 후, 학생들은 수업에서 다루는 임상적 문제 해결 미션 수행을 위해 실습 및 자료조 사 후 발표 및 토론 수행합니다. -이명의 병태생리, 유형, 동반 질환 및 위험요인에 대한 기초 의학·청각학 지식을 바탕으로 이명 사례를 이해·설명할 수 있는 이론 역 량을 기른다.？ -이명 환자에게 필요한 이명 인지 및 반응 관련 검사 등 평가를 계획·실시·해석할 수 있는 임상 평가 역량을 함양한다.？ -설문지, 면담, 행동관찰 등 정량·정성적 도구를 활용하여 이명이 개인의 삶의 질, 정서, 수면, 집중력 등에 미치는 영향을 다각도로 사 정할 수 있는 종합 사정 역량을 기른다.？ -평가 결과를 토대로 보청기, 이명 재훈련(사운드 테라피 포함), 상담·교육 등의 중재 방안을 설계하고, 타 전문직과의 의뢰·협력을 포 함한 맞춤형 재활 계획을 수립할 수 있는 중재 설계 역량을 기른다.？ 이명 평가 및 적합 과정에서 윤리 원칙을 준수하고, 환자 중심적 의사소통 및 교육을 통해 전문직으로서의 태도와 평생학습 역량을 함양한다', '{"이명","이명의","교재","실습보고서","최신","재활","인지","반응","정의","유병률","원인","고통","있는","역량을","지견","중재법","대해","기른다","상담","개요"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108114', '아시아고대사', '인문대학', '인문대학', 0, 3, '전선', '최주봉', '본 강의는 아시아의 고대, 특히 그 중에서도 중국의 ''고대''로 일컬어지는 선진시대부터 후한시대까지의 역사를 다룬다. 중국의 초기 문명이 어떠한 과정을 거쳐 형성되었고 고대 제국이 어떻게 성립하고 발전하였는지를 살펴봄으로써 중국 고대 문명의 성격을 대략적 으로 이해할 수 있는 기회를 제공한다. 1. 중국문명의 생성 과정과 특징에 대한 이해를 도모한다. 2. 중국 역사발전의 주체였던 제국이 어떠한 과정과 논리를 통해 형성되었는가를 규명한다. 3. 중국의 전통과 문화에 대한 전반적인 이해를 증진한다.', '{"수업참여도","중국의","시기의","고대","상나라의","성립과","멸망","붕괴","진나라의","중간고사","성립","무제","왕망","정권의","초기","어떠한","제국이","중국","과정과","이해를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('544331', '중추청각처리장애', '자연과학대학', '자연과학대학', 0, 3, '전선', '장현숙', '본 교과목은 중추청각신경계(Central Auditory System, CANS)의 해부생리학적 기전과 기능을 심층적으로 이해하고, 중추청각처리장 애(Central Auditory Processing Disorder, CAPD)의 선별, 진단 및 재활에 관한 임상적 역량을 습득하는 데 목적이 있다. 중추청각처리 장애의 정의, 병태생리, 원인에 대한 이론적 기초를 확립하고, 임상 현장에서 활용되는 다양한 선별 및 진단 평가 도구의 원리와 해석 법을 습득한다. 특히 근거 중심(Evidence-based)의 재활 전략과 청능 훈련 프로그램을 실제 사례에 적용해 봄으로써, 발달재활서비스 인력 및 청능사로서 필요한 통합적 임상 추론 능력과 실무 역량을 배양한다. 발달재활서비스 자격제공인력, 청능사 자격증 교과목임) 본 교과목은 중추청각장애의 이론적 기초, 평가 도구의 원리 및 임상 적용, 그리고 재활 전략에 대한 통합적인 이해를 목표로 한다. 1. 중추청각신경계의 구조와 기능에 대해 이해. 2. 중추청각장애의 병태생리 및 진단 기준 습득 3. 행동 및 생리 기반 평가 도구의 원리와 해석 능력 배양 4. CAPD 환자를 위한 근거기반 재활 전략의 이해와 실제 적용 능력 함양 5. 실제 사례를 바탕으로 한 통합적 임상 추론 및 재활 계획 수립', '{"중추청각처리장애","검사의","해석","진단","재활","중추청각신경계의","임상","기능","중추청각처리장애의","이분청취","시간처리","편이저잉여성","검사","양이상호","결과","전략","정의","도구의","실제","중추청각장애의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('544333', '행동청능평가', '자연과학대학', '자연과학대학', 0, 3, '전선', '장현숙', '본 과목은 청각학 전문가로서 갖추어야 할 핵심 역량인 청각 장애의 선별 및 정밀 진단 능력을 배양하는 필수 교과목이다. 강의는 청각 검사의 전체적인 체계를 이해하는 것으로 시작하여, 각 검사법의 과학적 원리, 표준화된 실시 방법, 그리고 결과 해석을 위한 이론적 기틀을 마련한다. 이론 학습에 그치지 않고, 실제 임상 장비를 활용한 직접 실습과 단계별 과제 수행을 병행하여 현장 적 응력을 극대화한다. 학기 말에는 학습한 다양한 검사 배터리(Battery)를 통합적으로 적용한 임상 사례 분석 및 전문가 프리젠테이션을 통해 종합적인 의사결정 능력을 함양한다. 본 과목의 최종 목표는 피검자의 청각 상태를 다각도로 평가하고 진단할 수 있는 임상적 전문성을 확보하는 데 있으며, 세부 목표는 다음과 같다. 1. 이론적 숙련: 순음 및 어음청각검사, 이미턴스 검사, 특수 청각검사(미로성·후미로성, 위난청 검사)의 원리를 명확히 설명할 수 있다. 2. 실무 수행 능력: 표준 가이드라인에 따라 청력 검사 기기를 정확히 조작하고, 피검자의 반응에 따른 적절한 검사 전략을 수립할 수 있다. 3. 비판적 결과 해석: 검사 결과를 종합 분석하여 난청의 유형과 정도를 판별하고, 감별 진단을 위한 핵심 지표를 도출할 수 있다. 4. 임상 소통 역량: 검사 사례를 학술적·전문적 견지에서 정리하여 발표하고, 효율적인 임상 보고서를 작성할 수 있다.', '{"해석","익힌다","목적","방법을","청력검사기의","검사","대하여","목적과","청능행동검사","미로성","후미로성","종류","기도","중이검사","검사의","해석을","임상","사례","있다","청력검사의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108213', '한국고대사의전개', '인문대학', '인문대학', 0, 3, '전선', '이윤정', '한국 고대사를 고구려·신라·백제·가야·발해로 나누어 전체적인 흐름을 파악한다. 고대사의 정치·경제·사회 등을 폭넓게 탐구하면서, 쟁 점이 되는 내용을 강의 주제로 선정하여 이와 관련된 자료를 집중적으로 살펴본다. 한국 고대사의 특징을 파악하고, 한국사에서 고대사가 가지는 의미를 이해한다.', '{"확장","한국","영토","고구려","경제","고대사","고조선","건국과","영상자료","감상","역사스페셜","백제의","전투와","발해","백제","정치","고대사의","바로","보기","유사역사와"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('544335', '행동청능평가실습', '자연과학대학', '자연과학대학', 0, 3, '전선', '이현주', '● 본 교과목은 교과목 [행동청능평가] 이론 수업과 병행하여 진행되는 실습 교과목으로 청각학 임상현장에서 필요한 행동청능평가 를 직접 실습하므로 이에 대한 임상 실무 능력을 함양하는데 목적이 있다. 또한 청능사 자격 및 발달재활사 자격 요건에 필요한 내용 범위를 다룬다. ● 본 교과목의 실습 내용은 대상자 배경정보, 이경검사, 순음청력검사, 어음청각검사, 이미턴스 검사, 미로 및 후미로성 검사 등의 방 법, 결과 해석, 보고서 작성을 포함한다. 1) 기술적 목표 ● 청력검사기기 및 이미턴스기기의 사용 방법을 익힐 수 있다. ● 순음청력검사 및 이미턴스검사의 방법, 결과해석 및 보고서 작성법을 익힐 수 있다. ● 미로성 및 후미로성 검사 등 행동청능평가의 방법, 결과해석 및 보고서 작성법을 익힐 수 있다. 2) 태도적 목표 ● 임상에서 환자를 대면했을 때 필요한 태도, 가치관, 전문성을 익힐 수 있다.', '{"검사","주교재","방법을","순음청력검사기기","익힌다","통하여","차폐","이해하고","골도","실습을","측정","기도","어음","중이검사","숙지한다","총정리를","있다","이경검사","결과","해석"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108216', '아시아근대사', '인문대학', '인문대학', 0, 3, '전선', '최병욱', '중국을 중심으로 한 아시아의 근대 역사를 살펴봄으로써 중국과 일본, 그리고 한국의 근대사를 객관적으로 조망해 보고자 한다. 이 수업을 통해 학생들은 서구열강의 침략과 이를 극복해가는 과정이 어떻게 오늘날의 정치 문화적 상황을 만들어나가게 되었는지에 대 한 역사적 인식을 갖출 수 있을 것이다. 동아시아, 나아가 세계 근대 역사의 흐름을 이해할 수 있는 역량을 키운다. 또한 학생들은 이 수업을 통해 역사적 사실을 스스로 비 판하고 자기의 관점을 정립할 수 있는 역사적 사유 능력을 키운다.', '{"대해","살펴본다","살펴보고","일본의","이후","근대","일본","그리고","중국사회의","중국과","세계","중국의","아편전쟁과","원인과","결과에","중국","페리","개항","메이지","반막부"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('544337', '청능재활실습', '자연과학대학', '자연과학대학', 0, 3, '전선', '이현주', '청각장애의 평가 및 재활과 관련된 임상실습 교육 과정을 통하여 청능재활서비스의 제공자로서의 역할과 기능을 실제 임상에 적용한 다. 청력평가, 보청기 및 증폭기기의 선별 및 착용, 청능훈련, 상담, 보고서 작성 등을 포함하는 종합적인 청각재활 서비스를 다룬다. 매주 증거기반에 입각한 청능재활 실습이 이루어지고 이에 대한 실습사례를 발표하고 함께 토의하는 방식으로 진행한다. * 본 과목은 보건복지부의 발달재활서비스의 청능재활 제공자격을 위한 필수교과목임 청능재활 계획을 수립하고, 상담, 청능 및 말지각 훈련, 의사소통 전략 훈련, 독화 훈련을 실시하며 이에 대한 청능 재활 보고서 작성 을 수행하는 능력으로, 재활 실습을 통하여 청능재활 서비스 제공자로서의 역할과 기능을 연마하는데 목표가 있다.', '{"실습을","함양한다","작성","청능재활실습","실무능력을","계획서","통하여","계획","숙지하고","청능훈련의","실제","재활","행동청능평가","방법을","방법과","작성을","목적","종류","절차를","살펴보고"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108221', '전공세미나및현장', '인문대학', '인문대학', 0, 1, '전선', '조병식', '사학전공생, 복수전공생이 국내 지역 답사를 통해 역사의 유산과 유적을 생생하게 접한다. 사전 조사와 답사자료 집 작성을 하며 역사 연구 방법의 기초를 익힌다. 학우, 교수들과 일정을 함께 하며 상호소통의 계기를 만들 수 있다. 역사 현장에서 상상력을 키우고 구체적인 사건을 스스로 탐색한다. 현장학습으로 공동체의 협업 능력을 기를 수 있다.', '{"답사","답사를","조사","작성한다","작성","사전","하며","역사","있다","지역과","장소에","대면","조별","활동","자료","자료집","얻은","지식과","경험을","종합한다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('544338', '청성유발전위평가', '자연과학대학', '자연과학대학', 0, 3, '전선', '한희경', '실제 임상 및 연구 분야에서 폭넓게 사용하고 있는 전기생리학적 검사를 직접 수행해 보고 검사결과를 기록하고 해석하는 연습을 할 수 있는 실습중심의 교과목입니다. 수강생의 주도적인 실습활동과 임상 및 연구 분야에서의 활용능력을 도모하고자, 실습 전·중·후에 실습과 관련된 중요 배경이론 및 개 념설명이 추가-확대-연계되는 방식으로 수업이 진행될 예정입니다. 본 교과목 이수를 통하여, 향후 유능한 청능사로서 혹은 청능사와 함께 일하는 다양한 분야의 전문가로서 역량을 갖출 수 있도록 예 비하는 것을 목표로 합니다. 본 강의의 학습목표는 다음과 같습니다. 1) 주요 전기생리학적 검사와 특수청각검사의 핵심 이론적 배경과 원리를 이해한다. 2) 청성유발전위평가에 사용되는 검사장비 및 검사자 조절 세팅 파라메터를 올바르게 조작하고 사용할 수 있다. 3) 청성유발전위평가의 검사 방법, 절차, 유의사항을 이해하고, 검사를 올바르게 수행할 수 있다. 4) 청성유발전위평가의 검사 결과를 정확하게 측정·기록하고, 보고서 형태로 작성할 수 있으며, 구두로 요약·설명할 수 있다. 5) 청성유발전위평가 검사 시 발생할 수 있는 문제상황에 신속하고 적절하게 대응할 수 있다. 6) 청성유발전위평가 검사의 임상적·연구적 활용방안을 모색하고 적용할 수 있다.', '{"있다","검사","검사를","절차","결과를","통하여","수행하고","해석할","실습을","환경에서","결과","실습보고서","검사에","이해하고","적합한","셋팅법을","익히고","개별","익히기","자극음"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('640055', 'MARKETING P', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김송이', 'This course provides an introduction to the core concepts and frameworks of marketing, focusing on how firms understand custo mers, create value, and compete in the marketplace. Key topics include Segmentation, Targeting, and Positioning (STP), the mark eting mix (4Ps), consumer behavior, branding, pricing, distribution, and digital marketing. Through real-world examples and applied analysis, students learn to connect marketing theory with strategic decision-making. A team-based project allows students to design a marketing strategy for a product or service, strengthening practical and analytical skills. The course equips students with a foundational understanding of marketing applicable across business fields. The objective of this course is to develop students’ ability to think strategically about markets and customers. Upon completion of the course, students will be able to assess marketing problems, make informed marketing decisions using core frameworks, an d communicate their strategic ideas effectively in both written and oral formats.', '{"and","marketing","review","what","homework","you","learned","with","ppt","files"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108416', '테마아시아사', '인문대학', '인문대학', 0, 3, '전선', '조병식', '시대를 중심으로 구분하는 동아시아사 교과목에서 다루지 못하는 주제나 현안들을 선택하여 그 역사적 맥락과 연구 동향을 검토하는 수업이다. 이 수업을 통해 학생들이 동아시아사에 대한 폭넓고 다양한 시각을 갖추기를 기대한다. 한국, 중국, 일본은 지금까지 동아시아 세계의 주요 국가로서 정치, 경제, 문화적으로 긴밀한 관계를 맺어왔다. 그 관계는 시대와 상황 에 따라 우호적이었던 때도 있지만 반목과 질시가 주를 이룰 때도 있었다. 근대 이래 국민국가를 지향하는 동아시아 각국의 역사 서 술과 역사 교육은 자국사와 세계사의 이분법 속에서 자국중심주의와 상호멸시를 강화하였고 그 결과 현재의 각종 역사, 영토 분쟁으 로 이어졌다. 본 수업은 한중일 삼국 간에 존재하는 역사 분쟁과 관련된 각종 주제를 선정하여 갈등의 원인과 전개 과정을 실증적으로 이해하는 것 을 목표로 한다. 이를 통해 학생들이 역사 분쟁의 실상을 파악하고 해결 방안을 모색해 보는 기회를 마련해 보고자 한다.', '{"사전","배부한","수업자료","참여도","동아시아","중간고사","일본","근대","상호","이해한다","인식과","둘러싼","중국","관계를","각국의","역사","삼국의","제국주의","고찰한다","내셔널리즘의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('640100', 'PRINCIPLES OF', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '조창익', 'This course entails basic economic concepts that are conventionally divided into two main aspects: microeconomics and macroec onomics. Since this course is designed for freshmen at the School of Global Studies (SGS) who are presumed to have no backgro und economics knowledge, it adopts very intuitive approach along with verbal explanation and graphical presentation to figure o ut important economic phenomena. The topics include supply and demand, price determination mechanism, market economy an d applications that constitute microeconomics part, while national income accounting and growth, inflation, money and banking, business cycles and sustainability in macroecnomics part. Students, after successfully finishing this one-semester course, will understand basic economic issues and also acquire essential s kills to analyze economic policies and outcomes. Students can understand the mechanism of how an economy works. Students can read the tables and graphs of economic phenomenon.', '{"and","with","verbal","explanation","part","ppt","files","brief","discussion","none"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108506', '전근대서양의역사', '인문대학', '인문대학', 0, 3, '전선', '류연승', '서양 고대사 (그리스-로마사) 시대사 개설 요청으로 본 강의에서는 서양 고대사를 한 학기 동안 다룬다. 고대 그리스와 로마의 역사와 문화는 현대 유럽사회의 문화적 정체성의 한 축을 형성할 정도로 지대한 영향을 끼쳤고, 그 이유에 대해서는 본 강의를 통해 알 수 있을 것이다. 고대 그리스 로마의 역사적 사건과 주요 쟁점을 파악하고, 각종 자료를 통해 그리스 로마의 문화를 알아간ㄷ.', '{"그리스","전쟁","고대","서로마","로마사","로마의","핸드아웃","서양","사료","쟁점","멸망시까지의","청동기","민주정","페르시아","펠로폰네소스","알렉산더와","헬레니","로마","초기","포에니"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680071', 'INVESTMENT A', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '조규성', 'This course is designed to provide a foundational understanding of investments. Students who master this course will acquire th e ability to understand how financial markets operate and to analyze financial assets. They will also be able to derive key implications from financial theories and understand their limitations, including portfolio theor y, asset pricing models. the efficient market hypothesis, and behavioral finance. Students learn how financial markets operate and the roles of financial securities. They also learn the benefits of diversification a nd the relationship between an asset''s systematic risk and its expected return. In addition, they gain an understanding of efficient markets and the implications of behavioral finance.', '{"lecture","notes","and","chapter","efficient","financial","the","markets","diversification","risk"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108507', '역사학자료탐구Ⅰ', '인문대학', '인문대학', 0, 3, '전필', '염정섭', '한국사의 여러 장면을 이해하는 데 중요한 관건이 되는 자료를 직접 이해하고 활용하는 능력을 키운다. 사료 분석의 토대 위에서 전 체적인 역사의 흐름을 파악하고, 합리적으로 역사를 해석하는 능력을 키운다. 또한 한국사 관련 자료를 깊이 살펴보고 그 의의를 탐 구한다. 이를 통하여 한국사 전체 흐름에 대한 올바른 해석과 체계적 이해를 도모한다. 한국사 관련 자료의 성격과 내용에 대하여 이해한다. 한국사 관련 자료 해독과 역사의 주요 흐름을 연결시켜 정합적으로 파악한다.', '{"강독","강독자료집","한문","해독의","이론과","실제","한국사","자료를","능력을","키운다","역사의","흐름을","자료집","삼국유사의","고조선","위만조선","이승휴","제왕운기","고려사","식화지"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680076', 'MICROECONO', '글로벌융합대학', '글로벌융합대학', 0, 3, '전필', '조동훈', 'This is designed as an intermediate course in Microeconomics. Knowledge of basic concepts is assumed, and new tools are devel oped to analyze individual decision making under constraints. We will look into consumer and firm maximization problems, and s ome game theory fundamentals at the end of the quarter. Most of the topics will include theoretical derivations as well as real lif e applications. Prepare the study related to the economics courses', '{"중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108514', '역사학자료탐구Ⅱ', '인문대학', '인문대학', 0, 3, '전필', '류연승', '수강생들의 사정상 영어로 된 자료(연구서 등의 2차 자료)와 영어 1차 사료 해석에 대한 학습이 수업의 목표이며, 학기가 지난 다음에 도 학생들은 각자 이 능력을 꾸준히 연마해야 할 것이다. 특히 역사가들이 주의해야 할 용어의 변천사, 번역 요령 등을 필히 익혀두어 야 한다. 역사용어의 영어 표현 어휘 숙지 영어 사료의 취급 능력 함양 고등 영어 해석 능력 함양 영어 기피증 공포증 극복', '{"영어","역사","자료","고대부터","근현대까지의","자료들","제시하여","사료에","감각","고대","중세","근현대의","각종","사료와","용어","익히기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680078', 'MACROECONO', '글로벌융합대학', '글로벌융합대학', 0, 3, '전필', '노석재', 'Students will learn how such macroeeconomic variables as GDP, CPI, unemployment rate and others are related to each other. More specifically the relationship Y=C+I+G+NX holds in the long-run where prices are fully flexible.Real interest rate and real exc hange rate play the role of coordinating this relationship. How the economy as a whole works in the short-run where prices are not fully flexible is the subject of Economic Fluctuationas and Governemnt Policy in the second semester. After learning the work ings of the economy in the long-run, we will investigate the issues associaged with economic growht. Through Solow Growth mo del we study how capital accumulation and technological progress are influcencing economic growht You should be able to understand the exact meanings of macroeconomic vocabularies. You should be able to evaluate critically the aricles and events that appear in economic newpapers.', '{"and","key","concepts","the","lecture","chapter","economic","growth","rate","real"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108517', '한국사입문', '인문대학', '인문대학', 0, 3, '전선', '염정섭', '본 강의는 인문학부 1학년 학생들이 사학 전공 가운데 한국사 분야의 공부와 연구에 대하여 갖고 있는 궁금증을 풀어주고, 문제의식 을 넓히며, 불안감을 해소시켜 주며, 한국사의 흐름과 한국사 연구방법의 실체에 정확하고 용이하게 접근할 수 있도록 도와주기 위한 과목이다. 한국사의 전체적인 흐름 가운데 특정 분야의 주요 주제(主題)를 집중적으로 검토하고 파악하는 것이 본 강의의 첫번째 목 적이다. 또한 본 강의의 두번째 목적은 한국사 연구의 방법과 의의를 작은 세부 주제(主題)와 구체적인 사료(史料) 탐구를 중심으로 정리하는 것이다. 이와 같이 본 강의를 통해 수강생들에게 지금까지 축적된 한국사 연구의 전문적인 성과를 소개하고, 또한 한국사 연구의 실질적이고 구체적인 체험의 기회를 제공한다. 특히 한국사의 전체적인 구조와 변동을 살피면서 당시 사람들이 어떻게 살아 나갔는지 찾아보고 검토한다. 그리하여 한반도와 주변지역에서 역사적으로 살아온 사람들의 삶을 이해하면서 이를 통해 동시에 오늘 날 우리 사회에서 주체적인 삶을 살아가고 역사를 이끌어 나가기 위해서 천착해야 할 과제가 무엇인지 모색할 것이다. 한국사를 전체적으로 이해하기 위한 주요 주제 및 쟁점을 검토한다. 한국사 연구와 관련된 문헌자료, 연구논저 등을 정리하는 능력을 함양한다. 한국사와 현대 한국사회를 통합적으로 이해하기 위한 발판을 마련한다.', '{"질문","한국사","조별","한국사의","쟁점","연구의","사료","풀어쓴","한국사학사","고려","조선","근대","주제","가운데","분야의","전체적인","主題","강의의","또한","방법과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680081', 'MANAGEMENT', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', 'Robinson', 'Aim: This is a course in management / business studies which explores the reasons and methods organizations use in their decis ion making. Through this course, students will be able to understand the important components of building a successful strategy , how environment affects an organization, the different strategies open to an organization, and the importance of the implemen tation of a strategy. By the end of the course, students should be able to understand and evaluate strategic options for different business situations. They should then have the confidence, knowledge and skills, to make strategic decisions. Method: This course will use a series of lectures, case studies, and discussions. Throughout the course, different industries will be studied ranging from production, retail, education, entertainment, and other services in order to get a wider perspective on how strategies can be applied in different situations. The course will briefly review some aspects of marketing, finance and managem ent. Students will be expected to carry out their own further reading in order to build on the knowledge from class. As the cours e develops, case studies will be used to understand the effects of different strategy and students will be expected to evaluate cas es and propose solutions. Course Units: The course will cover the following fundamental units: Part One - Introduction to Strategic Management 1. Strategic Leadership: Managing the Strategy Making Process for Competitive Advantage 2. External Analysis: The identification of Opportunities and Threats Part Two - The Nature of Competitive Advantage 3. Internal Analysis: Distinctive Competencies, Competitive Advantage, and Profitability 4. Building Competitive Advantage Through Functional-Level Strategy Part Three - Strategies 5. Building Competitive Advantage Through Business Level Strategy 6. Business-Level Strategy and the Industrial Environment 2. Course Objectives ■ Course Objectives 7. Strategy and Technology 8. Strategy in the Global Environment 9. Corporate-Level Strategy: Horizontal Integration, Vertical Integration, and Strategic Outsourcing 10. Corporate-Level Strategy: Related and Unrelated Diversification Part Four - Implementing Strategy 11. Corporate Performance, Governance, and Business Ethics 12. Implementing Strategy in Companies that Compete in a Single Industry 13. Implementing Strategy in Companies that Compete Across Industries and Countries By the end of the course, students should be able to understand and evaluate strategic options for different business situations. They should then have the confidence, knowledge and skills, to enter into management roles.', '{"and","the","strategy","understanding","lecture","discussion","attendance","participation","level","competitive"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108522', '도시의탄생과인간의삶', '인문대학', '인문대학', 0, 3, '전선', '문민기', '‘도시’는 많은 사람들의 생활이 이루어지는 공간으로 오늘날 인간 삶에 관계된 모든 영역이 구체화되는 곳이기도 하다. 이 수업은 HU SS 사업과 연계하여 인문·사회학의 통찰과 분석을 통한 융합형 인재 양성을 목표로 하는 교과목으로써, 다양한 도시들의 발달 과정과 역사적 사건을 살피며 도시와 인간 생활의 관계를 폭넓게 이해하는 것을 목적으로 한다. 동시에 지역 사회의 역사와 현재 직면한 문 제를 탐구하는 과정을 거친다. 또한 본 수업은 교수자의 강의 및 학생들의 개인과제로 이루어진다. 1. 도시의 형성과 발달에 대한 국내외의 사례를 검토하여 도시를 중심으로 역사를 이해한다. 2. 다양한 도시의 사례를 살핌으로써 살기 좋은 도시란 어떤 곳인가에 대한 자신의 생각을 만들어나간다. 3. 본교가 위치한 춘천시를 비롯한 기타 소도시에서의 정주 가능성과 로컬리티의 발전 가능성에 대한 아이디어를 형성해본다.', '{"교수자","도시의","우리동네","역사쓰기","특징을","도시","역사를","도시사","방법론","구상","서양","중세의","특성에","동아시아의","체크","경성과","평양의","아파트","현재","중심으로"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680091', 'EVOLVING ECO', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', 'Thomas', 'The Evolving Economies course focuses on how the global economic system came to be by understanding how the industrial rev olution occurred and that changes in the geopolitical landscape over the last 250 years has led to some countries being left behi nd. It will further explore in detail the factors which affected and are still affecting why some countries are considered underdeve loped. Additionally, the course will address the attempts made by the global community in assisting these countries. This course requires no mandatory prerequisite and will provide knowledge of factors which inhibit a country’s development. The objectives of this course are as follows: - Students will gain a greater understanding of how the global economic system developed over the last 250 years and how it h as continued to grow up to the present. - Students will be able to evaluate a country’s economic underdevelopment using the clinical economic factors. - Students will be able to discuss their opinions and evaluate how best to assist underdeveloped countries with the use of evide nce.', '{"and","the","reading","discussions","research","further","lecture","for","presentations","individual"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('108523', '한국선사고고학개론', '인문대학', '인문대학', 0, 3, '전선', '이정철', '한국의 구석기시대부터 초기 철기시대까지의 고고학 연구 결과를 물질문화의 전개 관점에서 정리해 보는 개론 강의이다. 한국 문화 의 기원과 형성 과정에 대한 고고학적 성과를 소개하고 유적과 유물을 통하여 그 양상을 검토할 수 있도록 강의가 구성된다. 구석기 문화, 신석기문화와 청동기문화, 초기 철기문화로 구분하여 각 시대의 물질문화에 대하여 상론하게 될 것이다. 또한 청동기 및 초기 철기시대와 관련된 고조선, 부여에 대해서도 소개가 이루어지며, 동북아시아의 중국, 일본 등 인접 지역 문화와의 관계가 기초적으로 다루어진다. 본 강의를 통하여 한국 선사시대 물질문화의 특징에 대하여 초보적인 식견을 가질 수 있게 될 것이다. 한국의 구석기시대~초기 철기시대까지 물질문화를 바탕으로 현재까지 다루어진 연구 방법론을 통하여 문화사적인 변화양상을 파악 한다. 또한 최근 연구의 흐름과 관련하여 고조선과 부여에 대해서도 기초적인 이해를 추구하고자 한다. * 세부목표 1: 구석기시대 석기문화의 발전에 따른 유물상의 변화 이해 * 세부목표 2: 신석기시대 물질문화의 혁명적 변화에 따른 유구, 유물상의 이해 * 세부목표 3: 청동기시대, 초기 철기시대와 고조선, 부여와의 상호 이해', '{"빔프로젝트를","활용한","자료","주차","수업은","중간고사로","평가함","문화","초기","우리나라의","신석기시대의","청동기시대의","신석기시대","변화","청동기시대","개념과","구석기시대","고조선과","선사시대의","구석기시대의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680092', 'INTERMEDIATE S', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '정득', '본 교과목은 경영과 관련된 다양한 데이타를 수집하고, 데이타의 전처리와 핸들링을 통해 데이터의 특성에 맞는 통계분석을 수행하 는데 목표를 두고 있다. 통계분석의 기초가 되는 기술통계를 학습하고, 추리통계를 통해 경영 변수들간 관계를 분석함으로 합리적인 의사결정을 도출하는 과정을 배우게 된다. 이를 통해 학생들은 경영 데이타에 대한 처리와 기본적인 분석 능력을 함양하게 된다. 본 교과목의 학습 과정을 통해 데이타에 대한 기본적인 이해와 경영 데이타를 요약하고 변수들간 관계를 분석하는 능력을 함양하게 된다. 이와 관련된 사회 패키지 통계 프로그램인 SPSS를 활용함으로 기본적인 운용을 습득하게 된다.', '{"스마트리드","수업시간","이변량","이해와","검정","경영","단변량","통계분석","경영자료에","연습","자료에","단변량과","데이터의","된다","자료의","척도와","기술통계량","형태에","따라","척도를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102215', '영시산책', '인문대학', '인문대학', 0, 3, '전선', 'CANADAS', '** Survey of English-Language Poetry (영시산책) - Semester 1, 2026. *- Time: Tues, Thurs. A (9:00~10:15 AM). *- Room: 4433. *- Prof. Ivan Canadas. *- Email: ivanxy10@gmail.com This course is an introduction to understanding poetic form, styles and development, with a specific focus on British and Am erican poetry, and some other English-speaking countries. The course provides both an introduction to poetic language and form s and a historical survey of English-language poetry of the last five centuries. We will, therefore, explore poetry from the sixteent h century to the present, covering a range of material, namely: the English Renaissance and Early Modern Periods; Poetry of the Restoration; the eighteenth-century neoclassical tradition (prim arily satire); Romantic Poetry (very late 18th C, and 19th Century, including both British and American works); the Victorian Age; major streams in the twentieth and early twenty-first centuries in the English-speaking world; popular cultural forms; and a touch on youth culture and music from 60s and 70s to the present (both poetry, and music lyrics, etc). Students should gain improved understanding of poetry and its many styles, and be able to grasp its richness and importance in English-language literature and beyond. The focus wil be both on poetic form and different trends and styles, and familiary wi th many famous examples of poetry in English. The focus of the course is to help each participant to gain familiarity with poetry, and how to analyze meaning and style, and als o to practice and improve individual skills in analysis, and on sharing and reporting views and ideas about specific poems, in ma nageable writing tasks, and through the spoken word, in in a supportive learning environment. 2. Course Objectives ■ Course Objectives The course aims to provide students with guidance, instruction, and opportunities to gain knowledge about poetic form and d ifferent trends and styles, and famous examples of poetry in English. The focus of the course is to help each of you to gain famili arity with poetry, and how to analyze meaning and style, and also to practice and improve your skills in analysis, and sharing and reporting your views and ideas about specific poems, in manageable writing tasks, and through the spoken word, in in a suppor tive learning environment. The poetry will be presented, analyzed and discussed in class, in order for students to acquire and practice skills in literary ana lysis, and especifically the technical aspects of verse form, as well as the messages presented, and the cultural and historical con ditions in which particular poems were produced. To succeed in this course, the focus is on learning to engage with poetic form and style, message and ideas, and on the quality of effort you make to organize and present your views and perspectives (the meaning and interesting aspects you find in specifi c poems, providing good detail and relevant examples from the poems themselves to support your arguments).', '{"어린이날","영시산책"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102204', '기초영어학', '인문대학', '인문대학', 0, 3, '전선', '고우리', '본 수업은 언어학의 핵심 개념과 주요 하위 분야(형태론, 통사론, 음성학, 코퍼스언어학, 전산언어학 등)를 체계적으로 학습하고, 이를 AI 시대의 언어 데이터·디지털 리터러시·영어 전공 역량과 연결하여 탐구한다. 초반부에는 언어학의 기초 개념과 이론 중심 하위 분야를 통해 “언어가 어떻게 구조화되는가”를 이해하고, 후반부에는 응용언어학·음 성학·코퍼스·전산언어학으로 확장하여 “언어를 실제 데이터/도구로 어떻게 분석하고 활용하는가”를 실습 및 프로젝트 형태로 수행한 다. 또한 생성형 AI(예: 프롬프트 설계, 커스텀 GPT 기획, 텍스트？오디오/영상 변환 도구 등)를 학습 보조 및 결과물 제작 도구로 활용 하여 분석·표현·발표 역량을 강화한다. 1. 언어학의 핵심 개념과 주요 하위 분야(형태론·통사론·음성학·코퍼스·전산언어학 등)를 이해하고, 언어 자료를 과학적으로 분석하는 기본 관점을 확립한다. 2. 실제 언어 자료(예문/코퍼스/간단 데이터)를 활용해 분석？해석？설명을 수행할 수 있는 기초 분석 역량을 기른다. 3. AI·디지털 리터러시 환경에서 언어 데이터의 특성과 한계를 비판적으로 점검하고, 학습/연구/교육 맥락에 적용하는 능력을 강화한 다. 4. 학습 과정에서 협업·학습윤리·증거 기반 논증 태도를 갖추고, 자신의 분석을 명료하게 글/발표로 전달할 수 있도록 한다.', '{"언어학","토의","문장","구조","프롬프트","음성학","응용언어학","설계","사례","언어","실제","간단","연결","의미","비교","형태소","사용","데이터","코퍼스","프로젝트"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680104', 'GLOBAL MARK', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '조창익', 'PLEASE BE ADVISED THAT THIS COURSE WILL BE TAUGHT IN KOREAN LANGUAGE! This capstone course is a method of summative evaluation in which the student is given an opportunity to demonstrate integrate d knowledge and growth in the global business major. The course will assess a student''s cognitive and intellectual growth in thei r major and also the overall academic learning experience. It will provide an opportunity for students to integrate and apply learn ing from their academic career in a comprehensive manner through the core curriculum of economics, finance, accounting, mark eting, management, human resource, and all learned fields. This course is rigorous team-based and project-oriented course. This course requires a high level of independence, time and info rmation management as well as an impeccable level of professionalism and work ethics. The nature of the Capstone course as a Senior Seminar requires a high level of independent thought, academic integrity and maturity, intellectual curiosity and exchange of ideas.A mature approach to teamwork, efficient division of labor, adherence to clear timelines and deadlines and the early res olution of potential conflicts between team members is essential.', '{"정하기","주차","팀원","논의","면담과","팀별","전반기","팀장","주제","교수","면담","담당교수와","개별적으로","정하고","이후","자료수집","분석방법","등에","대하여","최종"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102207', '글로벌영미문화:말', '인문대학', '인문대학', 0, 3, '전선', '엄미진', 'This course is designed to help students build practical English speaking skills through the exploration of American cultures. Usi ng real-life phrases and expressions, students will engage in speaking activities such as discussions, role-plays, presentations, and situational dialogues based on weekly themes. Students will practice speaking with key words and essential expressions, supported by learning tools such as YouGlish, YouTube, and ChatGPT. The course emphasizes confidence-building, natural expression, and effective communication while also improving pronunciation and intonation. Through interactive and contextualized speaking practice, students will develop both communicati ve competence and cultural awareness in English. By the end of this course, students will be able to: 1) Use basic English expressions in real-life situations 2) Speak more fluently using frequently used keywords and key phrases 3) Improve pronunciation, intonation, and speaking confidence 5) Engage in short conversations on familiar topics', '{"주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680105', 'DATA VISUALIZA', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '정득', '본 교과목은 경영자료에 대한 특성을 이해하고 Excel 프로그램을 활용하여 자료의 특성에 맞게 시각화하는데 교육목표를 둔다. 다양 한 데이터의 형태에 따라 핸들링을 수행하고 변환하여 자료를 요약하는 실증 분석과 기초통계분석을 함께 수행하여 통계분석에 대한 기초 역량을 함양하도록 한다. 1. 본 교과목의 첫 번째 목표는 다양한 경영자료를 이해하고 Excel 프로그램을 활용하여 데이터의 특성에 맞는 시각화를 수행할 수 있 는 역량을 배양한다. 2. 두 번째 목표는 데이터의 유형을 이해하고 기초적인 통계분석(기술통계)을 수행할 수 있도록 한다. 이와 같은 경영자료에 대한 시각화와 기초 분석을 학습함으로 경영자료분석에 대한 기본 능력을 습득하는데 목적이 있다.', '{"시각화","통계분석","시각화와","스마트리드","경영자료에","특성에","경영자료의","그래프","중간고사","이해하고","데이터의","맞는","수업시간","프로그램을","활용하여","역량을","한다","번째","목표는","수행할"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102345', '문학과여성', '인문대학', '인문대학', 0, 3, '전선', '김번', '영문학에서 여성, 그리고 여성에 대한 재현들이 왜 중요한 문제가 되는지를 살피고 논한다. 구체적으로는, 다양한 텍스트를 통해 영문 학사를 통해 여성이 어떻게 표상되고 자리매김되어 왔는지 그리고 거기에 어떤 사회적 힘 혹은 권력관계가 작동하는지를 논의하면서 여성 해방이 인간 해방으로 이어질 가능성을 탐색한다. 이를 위해 강독할 텍스트는 문학에 한정되지 않고 철학, 사회학 등 여러 분야 의 글에 걸칠 것이다. 남녀 관계의 역사를 개괄하는 가운데 특히 문학에서 남녀의 성차, 즉 gender의 문제가 남녀 모두의 삶에서 critical issue가 될 수밖에 없는 이유와 근거를 살피고 논한다. 이 과정에서 문학 또한 하나의 이데올로기적 힘으로서 여성 해방과 나아가 인간 해방을 위한 대 의에 어떻게 작동하는지를 비판적으로 탐색한다.', '{"여성","남녀","글쓰기의","조건","관계의","그리고","문제가","살피고","논한다","어떻게","작동하는지를","인간","탐색한다","구별","관계에","나타난","지배와","억압의","양상","물질적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('690013', '한국의생활문화', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '한혜정', '본 과정은 외국인 유학생을 대상으로 한국의 기본 예절과 의식주, 관습 및 세시풍속 등 생활 전반에 걸친 문화를 학습합니다. 이를 통 해 한국인의 삶 속에 투영된 가치관을 탐구하고, 한국인과 한국문화에 대한 올바른 이해를 도모하는 것을 목적으로 합니다. 한국의 기본 예절과 의식주, 세시풍속 등 생활 문화 전반에 관한 지식을 습득하고, 그 속에 담긴 한국인의 가치관을 체득함으로써 한 국 사회에 대한 심층적인 이해와 적응 능력을 기른다.', '{"한국의","문화","한국인의","영상","비교","예절","사진","전통","음식","체험","한복","식생활","매너","주거","일생","명절","예술과","대중문화","예절과","의식주"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102347', '영어의역사', '인문대학', '인문대학', 0, 3, '전선', '이지연', 'This course has been designed to explore the history of English language and some relevant current issues. The course provides students with the opportunity to explore and understand the spread of English and the way in which English is used and taught on a global scale and what this means for our understanding of English and language and communication more generally. This course will address key issues in Global Englishes including: - Spread of English - English as a Lingua Franca - World Englishes - Standard English language ideology - The role of English in education globally - English language policy and practice - Intercultural communication and intercultural pragmatics', '{"중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('660001', '문화산업서비스경영', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김익태', '□ 문화산업 서비스상품의 특성을 바탕으로 서비스 경영에 대한 기초 이론과 실무적 적용을 학습하는 것이 목표임 □ 서비스의 정의, 서비스 상품의 개발 및 운영, 서비스 품질 관리, 서비스 프로세스 및 공급·수요 관리 등을 다양한 문화산업 및 서비 스산업 사례를 중심으로 토의함 □ 디지털 전환(Digital Transformation) 시대에 서비스산업에 적용되는 기술과 비즈니스 모델 변화를 이해하고, 디자인 씽킹(Design Thinking) 접근을 통해 새로운 서비스 기획 및 서비스 모델을 제안·설계하는 문제해결형 학습을 병행함 □ 서비스 산업 전반에 대한 구조와 특성을 이해함 □ 서비스 기업 경영에 요구되는 핵심 이론(서비스 마케팅의 개요, 서비스 경영의 환경분석과 포지셔닝, 서비스 마케팅 믹스, 서비스 경쟁전략 및 품질관리 등)을 습득함 □ 문화산업 및 콘텐츠/관광/MICE·플랫폼 등 서비스 기반 산업에 적용 가능한 서비스 경영 기획 능력을 배양함', '{"서비스","토의","자료","관리","전략","서비스의","프로세스","고객관계","공급","디지털","마케팅","소비자","제품","고객","물리적","가격의","품질의","문화산업","개발","품질"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680200', '문화산업입문', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김선홍', '저작권의 보호를 받는 문화적 성격의 상품과 서비스(예를 들면 음악, 방송, 영화, 출판, 디자인 등)의 창조와 생산, 유통에 관련된 문화 산업 전공과정을 심화하기 위한 기초적인 학습으로서 문화산업의 기본개념과 더불어 산업데이터의 활용을 위한 기초지식 습득, 기업, 소비자, 시장의 관점에서 행동 특성을 이해하기 위한 학문내용을 학습한다 - 문화산업 입문을 위한 문화의 이해와 이를 기반으로 한 산업의 개념 정리 - 문화산업을 기반으로 데이터의 수집과 가공방법 습득 - 문화산업의 기업, 마케팅, 시장에 대한 전공지식 습득', '{"강의안","산업의","문화산업의","마케팅","데이터","그래프","문화기업의","지적재산권","소비자","시장의","문화산업","문화의","데이터의","기업","기반으로","문화와","대중화","기본개념","서비스산업의","서비스산업"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102351', '미국문학입문', '인문대학', '인문대학', 0, 3, '전선', '한경민', 'This course is an introduction to major works of American literature. We will think in particular about the various ways in which A merican authors have defined and/or justified their art. We will also look at the ways in which American “originality” might be se en both in literary form and its content or subject matter. We will also ask: what makes this body of literature “American”? How h as the idea of “America” changed over time? In what ways do racial and gender differences inflect the meanings of “America”? As we consider the thematic questions reflected in U.S. literature, we will also focus on some of the principles of literary analysis, exploring the relations between “text” and “context” and developing a vocabulary for describing and analyzing the basic element s of poetry, the short story, and the novel. To that end, we will work to learn to describe and interpret the literary arts as well as to explain how literature expresses social and cultural issues.', '{"중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680206', '문화산업데이터분석', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김익태', '□ 문화산업 분야의 조사를 함에 있어 기본인 조사기획, 조사설계 및 통계에 대한 개념을 습득함. □ 단일변량/다변량 분석기법의 원리와, 적용상황 그리고 분석결과들이 갖는 의미를 이해함. □ 이를 통해 문화산업 비즈니스의 기획능력을 향상시키는 실무역량 강화를 위한 교과목임. □ 문화산업의 비즈니스 수행시 필요한 조사의 기본적 이론과 개념을 학습하고, 이를 실제 상황에서 적용할 수 있는 실무능력의 배 양을 목표로 함. □ 조사방법론 및 통계학의 기본적 개념과 방법들을 이해하고, 실제 조사 자료들을 분석하는 방법과 결과들을 해석하며, 이를 통해 의사결정문제에 활용할 수 있는 능력을 배양함.', '{"자료","개념과","토의","참고자료","수업태도","적극성","방법론","실습자료","태도","구체적","방법들의","조사의","자료의","종류","수집","기술통계분석","상관관계","회귀분석","판별분석","요인분석"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105428', '토르플연습', '인문대학', '인문대학', 0, 3, '전선', '이리아', '수업 대상: 러시아어 중급 수준 학습자, 토르플(ТРКИ) 시험 준비생 교재: 토르플 준비 교재 및 공식 모의고사 자료 토르플 연습 1 과정은 토르플(ТРКИ) 시험 준비를 위한 과정으로, 학생들이 러시아어 능력을 평가받는 토르플 시험에 맞춰 각 영역을 균형 있게 준비할 수 있도록 돕는 것을 목표로 합니다 토르플 연습 1 과정은 토르플(ТРКИ) 시험 준비를 위한 과정으로, 학생들이 러시아어 능력을 평가받는 토르플 시험에 맞춰 각 영역을 균형 있게 준비할 수 있도록 돕는 것을 목표로 합니다', '{"자료","듣기","연습","토르플","읽기","모의","말하기","쓰기","전체","실시","유형","간단한","작성","대화","실전","독해","자기소개","주어진","주제에","대해"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102356', '실용영작문', '인문대학', '인문대학', 0, 3, '전선', '김선아', 'This course aims to examine various English writing styles that typically occur in modern society and helps students acquire lingu istic tools and cultural patterns that can be used in real-life situations. From social media posts to e-mails, resumes, and report w riting, students will be able to practice various types of English writing that are used daily in modern society. Students will learn a nd practice linguistic tools such as vocabulary and grammar that can be used in each situation as well as different cultural patter ns and literary styles. Students will be able to communicate in English by selecting appropriate cultural styles and linguistic tools for various situations. Not only will students be able to become familiar with expressions and sentence patterns that are used by native speakers, they will also be able to improve overal methods and techniques that are used in academic English.', '{"중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('680207', 'SNS커뮤니케이션', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '이현서', '본 강의는 SNS를 활용한 커뮤니케이션 이론과 전략을 중심으로 사회·문화·산업적 맥락을 분석한다. 주요 플랫폼 사례와 관련 연구 논문을 바탕으로 효과적인 메시지 전달과 상호작용 방식을 이해한다. 발표와 토론을 통해 SNS 커뮤니케이션 현상을 비판적으로 분석하는 능력을 기른다. SNS 커뮤니케이션(Social Media Communication) 과목의 교과목표는 다음과 같다: SNS의 이해: 학생들이 SNS의 발전 과정과 다양한 유형, 기능 및 특징을 이해하도록 돕는다. 커뮤니케이션 이론 적용: SNS 환경에서의 커뮤니케이션 이론을 학습하고, 실제 사례에 적용할 수 있도록 한다. 온라인 커뮤니티 분석: SNS 상의 커뮤니티와 사용자의 행동을 분석하고 이해함으로써, 상호작용의 중요성을 강조한다. 윤리적 소통: SNS 사용 시 발생할 수 있는 윤리적 문제를 인식하고, 책임 있는 소통 방법을 배운다. 비판적 사고 증진: SNS 정보의 비판적 분석과 평가 능력을 배양하여 정보의 신뢰도를 판단할 수 있는 능력을 향상시킨다.', '{"커뮤니케이션","발표주제","과제제출","개별평가","있다","대해","설명할","사례","커뮤니케이션의","전략","메시지","기업","여론","데이터","상호작용","개념과","이론에","플랫폼의","구조와","이용자"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102393', '현대영미희곡', '인문대학', '인문대학', 0, 3, '전선', 'CANADAS', '** Modern British and American Drama (현대영미희곡]), Semester 1, 2026. * Prof. Ivan Canadas (Email: ivanxy10@gmail.com). ** Lesson Time: Mon 5, 6 (1:00~2:50 PM); Wed 5 (1:00~1:50 PM) ** Room: 4435. This course is an introduction to English-language theater (main focus on British and American stage drama), primarily from the s econd half of the 20th Century, and into the 21st century. It also provides some groundwork on major developments, and on bas ic critical terms and traditions, both for context and as basic structure, features and devices on which to base your own explorati on and analysis of a stage play, as text, stage performance, or film adaptation. In looking at modern drama, we will also address the pressures and interplay between it and other audiovisual narrative and perf ormance media (i.e. the rise of film and television), as well as the contribution, shadow, and enduring influence of stage melodra ma of the nineteenth century. Dramatic genres and traditions addressed in this course, include and expressionism in theater, categories and trends in symbolis m and expressionism in theater, the range of realism, the theatre of the absurd, and postmodern developments. By these means, students gain insight into how works of drama, and the dramatic productions, engage with and address real-life social and cultu ral issues and conflicts, and the human condition. To fully understand and contextualize different currents, innovations and features in modern drama, we will also engage briefly b ut directly with representative examples of traditional, Nineteenth-Century melodrama (for its major contribution to Twentieth-Ce ntury Drama, which still influences present-day literature, film and television to a significant degree. But, of course, beyond this, we will primarily trace and explore developments in stage drama in the 20th century. Engaging with an exploring some quite fam ous and classic works (along with others, less-known but fresh and original), will serve to illustrate and exemplify developing tren ds in characterization, acting style, major themes, and social and cultural issues which brought dramatists and audiences together , in different and specific social and cultural contexts, relevant to their time and place. 2. Course Objectives ■ Course Objectives ** Students will specifically engage with the following primary material (read, watched, and discussed): *- A short teleplay to watch (accompanied by a written transcript) from classic television anthology series, The Twilight Zone: “Mr. Denton on Doomsday” (S01e03, CBS, Oct 16, 1959). *- A quick overview (esp. of Act I) of: W. H. Smith’s The Drunkard: or, The Fallen Saved (1844), a very successful, much imitate d work of classic melodrama. *- The film adaptation of Still Life (Short, One~Act Play b Noel Coward, 1936)), namely: David Lean’s celebrated film, Brief Enc ounter (1945). *- Tennessee Williams, A Streetcar Named Desire (1947); film version: (Dir. Elia Kazan, 1951). *- Very Brief look at selected material from Harold Pinter, The Birthday Party (1957; pub. 1959); film version (Dir. W. Friedkin, 1 968). *- Post-colonial (Cold War) era, satirical exploration of sexuality, gender identity and values, and the power of postmodern dra ma and performance, David Henry Hwang, M. Butterfly (1988); Film version (David Cronenberg, 1993).', '{"대체","공휴일","전국동시","지방선거일","현대영미희곡"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('691003', 'ENCOUNTERS', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', 'RAY', 'Students enrolled in this course will receive a fundamental grounding in understanding and surviving in modern Korea. This func tions as a broadening of their international perspective regarding how to interact within a culture that can at times be quite alien to their own. Through seven types of encounters, they can directly develop the tools for understanding and navigating through i t harmoniously. The purpose of this course is to quickly and efficiently familiarize international students with day-to-day life in the Republic of Ko rea as they will directly encounter it.', '{"and","about","encounters","learn","korean","quality","powerpoint","uation","effort","work"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('691004', 'FUNDAMENTA', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', 'FREY', 'This is a survey course that introduces various issues important to anyone wanting to study or engage in international business i n Korea. Some topics included are: contracts, international business law, modern Korean corporate structures, historical and philo sophical influences on modern Korean business culture, and major international corporations and their current operations in Kore a. A large amount of time is spent on philosophy in order to understand the underlying influences on modern Korea. Please note that this is a mixed class with a variety of language and existing information levels. I try to aim for a middle ground, but invariably some students will find the class a little advanced while others will find it introductory. Be aware that this course will discuss some sensitive historical and modern topics. It also requires a large amount of participation ; if you do not want to talk during class, you should not take this course. Students will learn about the philosophies, events, and cultural influences on modern Korea and how these relate to international business.', '{"discussion","and","lecture","assigned","reading","student","presentations","class","for","context"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('691005', 'KOREAN FILM', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', 'CANADAS', '** Korean Film and Literature, Semester 1, 2026. ** Lesson Time: Tues/Thurs. F (4:30~5:45 PM) ** Room: 14303. Literary and cinematic material provides insight into the soul of a vibrant, modern society and its competing cultural voices. St udents will engage with a brief selection of 20th- and 21st-century literature, including short stories and extracts from larger wor ks, as well as a variety of films from 2001 to the present, representing different genres and themes. These films comprise both cri tically acclaimed and commercially popular successes. Though necessarily eclectic, the selected material engages with modern citizens, for its appeal or entertainment value, and also f or addressing troubling themes or conflicting values. Course participant will therefore be able to gain significant cultural insight, and to appreciate how Korean literature and film reveal and resonate with the particular and local while also exemplifying their g lobal or universal relevance for international readers and film lovers. Students can expect to gain knowledge on the subject of Korean culture, society and art through famous examples of literature ( from the 1930s to the present time), and of 21st Century film. In addition, they can and to acquire improved analytical skills and practice in literary and film analysis, and, more broadly, in English-language written communication and presentation skills.', '{"엽기적인","그녀","어린이날","괴물","늑대소년"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102411', '글로벌영미문화:읽', '인문대학', '인문대학', 0, 3, '전선', '김선아', 'This course aims to help students improve reading skills by reading articles that deal with different issues and cultures. Students will be able to acquire reading comprehension skills, vocabulary, and grammar through reading, analyzing, and discussing about various topics throughout the semester. Reading is the process of absorbing the written word and it is an essential part of communication between human beings. Readi ng comprehension is the ability to process, think through and connect ideas that are expressed on paper. Therefore, this course offers students a basic and solid foundation in reading multiple types of materials for a wide range of cultural settings and is des igned to encourage students to excel in their reading endeavors while learning about and growing interest in the backgrouds of different cultures.', '{"중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('691010', 'CURRENT ISSU', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '이지연', '*Seminar Course* The Current Issues in Modern Korean Society course introduces students to issues that influence our life in this global and newly multicultural society. Students will read about and research current economic, political, social, and cultural pro blems of Korea in relation to its history, and explore how past and ongoing conflicts affect groups as well as individuals. Student registered in this course will benefit from reading and analysing a range of reading materials on various issues individual ly as well as in small groups. In addition, essential aspects of critical thinking learned in the course will associate with other cours es the students will attend later and help students assess and discuss knowledge they come across as well as challenges made b y others.', '{"and","reading","presentation","group","discussions","korea","for","attendance","participation","the"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102413', '아동영문학번역연습', '인문대학', '인문대학', 0, 3, '전선', '조비결', '영어영문학을 통해 영어능력을 향상시키고 문학적 소양을 함양해 글로벌 리더로서의 역량을 강화하는 측면에서 본 강좌 아동영문학 과 번역실습은 아동영문학에서 다루는 유년기 아동의 시선을 통해 21세기 교육의 목표인 창의력과 비판적 사고력의 역량과 번역실습 을 통해 학생들간의 협업능력과 의사소통능력의 역량을 고양시키고자한다. 본 강좌 아동영문학과 번역실습은 로이스 로리(Lois Lowry)의 기억전달자(The Giver)작품을 중심으로 유년기 아동의 시선을 통해 시 대정신과 통찰력을 얻고 21세기 교육의 목표인 창의력과 비판적 사고력을 향상시키고 팀별 토의학습활동에 기반한 번역실습을 통해 영문 번역과 영작 능력, 의사소통능력과 협업능력을 함양시키고자 한다.', '{"학생들","독해","팀별","작품","중요구문","번역","향상시키고","역량을","강좌","번역실습은","유년기","아동의","시선을","세기","교육의","목표인","창의력과","비판적","운영","방법과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('691011', 'KOREAN COM', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', 'FREY', 'This course will examine the South Korean constitution in relation to those of North Korea, the United States, and a selection of other countries''. We will discuss significant similarities and differences, the effects of World War II on subsequent constitutions, i nfluences from external powers, purposes of different styles of constitutions, and the meanings of different legal terms. A backgr ound in law is not required for this class, but is helpful. Please note that this is a mixed class with a variety of language and existing information levels. I try to aim for a middle ground, but invariably some students will find the class a little advanced while others will find it introductory. Be aware that this class requires a large amount of participation; if you do not want to talk during class, you should not take this course. Students will learn about various constitutions around the world and how they compare to the South Korean constitution. Stude nts will also practice presentation skills based on a country of their choice.', '{"discussion","constitution","and","lecture","assigned","reading","week","student","presentations","the"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102415', '영문학입문', '인문대학', '인문대학', 0, 3, '전선', '한경민', 'Introduction to Literature is designed to help students acquire the tools for understanding, appreciating, and critically analyzing v arious genres of literature including fiction, poetry, and drama. In this course you will learn some basic concepts about literary te chnique and innovation. In addition to learning to identify some of the major differences among fiction, poetry, drama, and non- fiction prose, and the qualities intrinsic to each, you will learn to identify significant questions and ideas dealt with by literary aut hors and describe how literature goes about trying to answer them. Students will also be given an opportunity to consider how li terature can be useful for grappling with complex social, cultural and historical problems. Introduction to Literature is designed to help students acquire the tools for understanding, appreciating, and critically analyzing v arious genres of literature including fiction, poetry, and drama. In this course you will learn some basic concepts about literary te chnique and innovation. In addition to learning to identify some of the major differences among fiction, poetry, drama, and non- fiction prose, and the qualities intrinsic to each, you will learn to identify significant questions and ideas dealt with by literary aut hors and describe how literature goes about trying to answer them. Students will also be given an opportunity to consider how li terature can be useful for grappling with complex social, cultural and historical problems.', '{"중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('691013', 'REGIONAL KO', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', 'QUARTON', 'This course offers an engaging, hands-on learning experience built around Problem-Based Learning (PBL). Students will actively i nvestigate real-world questions by working both independently and in collaborative teams, developing practical skills in research, analysis, and communication. At the center of the course is the Hwacheon Sancheoneo Ice Festival (얼음나라 화천산천어축제), one of Korea’s most famous win ter events. Held every January in Hwacheon-gun―just one hour north of Chuncheon―the festival attracts millions of visitors and plays a vital role in the local economy. Its global significance was highlighted when CNN named it one of the “7 Wonders of Wi nter.” Using this internationally recognized festival as a case study, students will explore how culture, media, and business interse ct in a real-world setting. Throughout the semester, students will engage with a range of academic research papers and media sources focusing on marketi ng strategies, economic impact, and media influence related to the festival. Each reading or media case presents a “problem” or s cenario that students will critically analyze, debate, and solve―first individually and then through group discussion. This approach encourages creative thinking, teamwork, and practical problem-solving skills that are highly valued in both academic and profess ional environments. The course is conducted entirely in English, and all discussions, presentations, and written assignments will be completed in Engli sh. No prior knowledge of Korean is required, making the course accessible to a wide range of students. Participants should be c omfortable communicating in English and willing to collaborate flexibly with classmates from diverse backgrounds. This course is especially recommended for media, communication, and business students, as well as any student interested in glo bal festivals, cultural events, and collaborative learning in an English-language environment. To conclude the course, students will deliver an oral research presentation on a topic of their choice related to the Hwacheon Ice Festival. Presentations may be given live in class or submitted electronically, allowing students to choose the format that best su its their strengths. Critically analyze and interpret academic research papers and media sources related to the Hwacheon Sancheoneo Ice Festival, wi th attention to marketing, economic, and media perspectives. Identify, evaluate, and synthesize relevant information to address specific research questions and real-world scenarios connected to the planning, promotion, and impact of the Hwacheon Sancheoneo Ice Festival. Develop well-reasoned responses and practical solutions to problem-based learning tasks by applying research findings, critical t hinking, and collaborative discussion. Communicate analytical insights effectively in English through written work, group discussions, and oral presentations.', '{"얼음나라","화천산천어축제"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102421', '영미문학과네트워크', '인문대학', '인문대학', 0, 3, '전선', '김용수', '이 과목은 최근 SNS의 발달로 친숙해진 네트워크 개념으로 영미문학 작품을 이해하고 분석해보는 수업이다. 연결망 분석 기법을 영 문학 작품과 작가, 제도의 이해에 적용한다. 오스카 와일드의 작품, ''살로메''를 기본 텍스트로 삼아 분석하고 토론할 것이며, 이를 통해 디지털인문학의 방법에 대해서도 학습한다. 사용하기 쉬운 소프트웨어로 실제 시각화를 진행하여 디지털 기술을 활용할 수 있는 디 지털 리터러시 능력도 함양한다. 이를 통해 한림대학교 인문사회융합인재양성사업(HUSS)에서 요구하는 융합인재로 성장할 수 있도 록 한다. - 새로운 인문학 분야인 디지털인문학의 구체적인 방법을 실제로 학습하여 디지털 기술과 영문학 이해의 접목 가능성을 이해한다. - 네트워크 분석을 통해 문학 작품과 제도에 얽혀있는 수많은 관계들로부터 통찰을 얻어내는 방법을 익힌다. - 이 과정에서 디지털 기술 활용 능력을 함양하고 인간과 컴퓨터 간 협업의 필요성을 파악한다.', '{"연결망","네트워크","작품","분석의","인물","만들기","시각화","문학","분석을","개념과","생성형","데이터셋","디지털","작품과","이를","디지털인문학의","방법을","수업계획서","도리언","그레이"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('691015', 'KOREAN DEVE', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', 'Thomas', 'This course examines Korea’s current and planned development and change for the 21st century with a key focus on sustainabilit y concerns. It specifically explores how Korea is adapting to new cultural and technological changes for concerns surrounding soc ial pressures, environmental and economic change from a sustainability perspective. In the first half of the semester, a particular f ocus will be made on energy concerns (social responsibility, government direction, new technologies), transport (existing concern s, planned schemes, new technologies), and how both relate to and can address Korea’s (air) pollution problem. In the second half of the semester, Korea''s economy will be discussed in particular relation to the decline in economic growth an d the need for sustainable solutions such as shifting away from the heavy educational focus of the country to alternative approac hes such as skill-focused education via apprenticeships or internships as well as the (prospective) need to encourage immigrant workers. Therefore, this course is differentiated from other Korean Studies Program (KSP) courses, particularly the Current Issues in Moder n Korean Society and Korean Economy: Dynamics and Future, in that sustainability is the key theme which drives this course. The objectives of this course are as follows: -Students will comprehend the challenges and concerns in the developing Korean society (both now and as it moves further into the 21st century). -Students will be able to differentiate these concerns into either social, environmental, or economical issues and find links betwe en them. -Students will gain extensive knowledge on how Korea is aiming to overcome any challenges both at present or in the future (in cluding plans for the implementation of new technology).', '{"and","the","discussions","for","korea","this","presentations","further","lecture","introductions"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('686001', 'MICE소비자이해', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김익태', '□ MICE 산업과 관련된 소비자 행동과 그 영향요인에 대한 개념과 이론들을 학습함 - 소비자 중심의 시장으로 바뀌고 있는 MICE 산업에서의 소비자 행동을 이해함 - MICE산업 관련 소비자 행동과 이에 영향을 미치는 내·외적 요인들을 파악함 □ 디지털 시대 소비자의 욕구와 정보탐색이 어떻게 바뀌고 있는지 이해함 - 디지털 기술과 함께 변화하고 있는 소비자의 욕구 및 행동들을 파악하고 새로운 시장기회를 탐색함 □ MICE 산업 관련 소비자 행동을 설명하는 이론 체계로서 인지심리학, 행동심리학의 이론들을 학습함 - 소비자의 인식, 정보처리, 태도형성 및 의사결정과정을 이해함 □ 디지털 기술이 가져온 소비자 행동의 변화를 이해함 - 디지털 기술이 등장함에 따라 변화하고 있는 문화콘텐츠에 대한 소비자들의 소비심리 및 행태들을 분석함 - 소비자 행동의 변화에 따른 문화콘텐츠 산업에서의 대응 방향에 대해 논의함', '{"소비자","토의","디지털","변화","태도","의사결정","기술과","모형","부교재","소비자의","이해함","기술이","지각","지각의","조건화","관여도","포노사피엔스의","등장","포노사피엔스","있는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('102425', '지역이야기,세계', '인문대학', '인문대학', 0, 3, '전선', '육청민', 'This course helps students become informed cultural ambassadors for their local regions (e.g., Chuncheon and Gangwon) and Ko rea as a whole. Designed as part of HUSS’s curriculum vision for regional value innovation, the course aims to strengthen student s’ practical abilities to introduce authentic local stories and cultural content in English. Through video-based lessons and interacti ve postings, students develop global communication skills while enhancing key Local C-nergy competencies. Although delivered online, the course remains highly interactive, as students submit weekly responses to guided prompts that help them build practi cal, audience-ready communication skills. By the end of the course, students will be able to: ？ Present local and Korean cultural content clearly and confidently in English to international audiences. ？ Use practical English vocabulary and expressions related to Korean places, people, foods, customs, and everyday life in both w ritten and spoken communication. ？ Craft concise, audience-ready written responses using key vocabulary from each topic. ？ Produce engaging and informative video presentations with effective English narration and subtitles. ？ Engage with local narratives and cultural assets to develop communication skills aligned with regional value innovation and str engthen key Local C-nergy competencies. ？ Apply responsible and ethical use of AI tools to support English communication, while maintaining originality and personal inp ut.', '{"and","online","posting","korean","local","cultural","life","gangwon","chuncheon","guide"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('686002', 'MICE산업론', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '윤은주', 'MICE산업에 대한 기초적인 과목으로 MICE가 무엇인지 기본적인 이해를 할 수 있도록 각 영역별 산업의 특징 및 현황에 대한 소개를 하고, 이러한 산업이 궁긍적으로 무엇을 목적으로 존재하고 앞으로 어떤 형태로 발전해야 하는지에 대해 학습한다. MICE산업의 특징 에 대한 이해, 국내외 현황, 현재 산업의 트렌드 파악을 학습 목표로 한다. - MICE산업에 대한 전반적인 이해 - MICE산업의 구조에 대한 이해 - MICE산업 국내외 현황 - MICE산업 트렌드 파악', '{"산업","컨벤션","우수","사례","구조","서비스","전시산업","인센티브","엑스포","산업의","국내외","컨벤션센터","조사","산업에","특징","트렌드","컨벤션산업","개관","컨벤션의","현대적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103101', '초급중국어연습Ⅰ', '인문대학', '인문대학', 0, 3, '전선', '염철', '본 강좌는 중국학과 1학년 1학기 과정에서 필수적으로 익혀야 할 발음, 성조 및 기본어휘와 기초문법 등을 습득시키는 데 그 목적이 있다. 중국어의 특성을 감안하여 중간고사까지는 문장학습보다 발음교육에 치중할 것이며, 중간고사 이후부터 기본문형의 학습에 들 어간다. 중국어 발음, 간체자, 기초 단어와 문법을 읽힘으로서 중국어 입문자에게 기초 회화와 문법을 전수한다.', '{"사용하여","개별","익히기","수업시간중","연습","강의안","테스트","음절","쌍음절어","변화","본문과","발음","알아보기","활용하여","공고","음절쓰기","성조의","듣기","교정","쓰기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('686009', 'MICE와DMO운영', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '윤은주', 'MICE산업분야 기초 과목으로 Destination Management Organization(DMO)에 대한 학습을 진행한다. 개최지관리운영조직으로 우리 나라 기준으로는 관광공사, 컨벤션뷰로를 의미하고, 다양한 MICE 행사의 유치 및 개발을 위한 산업 지원 역할이 어떻게 진행되는지와 개최지로써의 포지셔닝을 위한 마케팅 전략 수립에 대한 학습을 한다. 개최지 마케팅과 브랜딩에 대한 내용이 진행되므로 기초적인 마케팅, 브랜딩 수업을 제공한다 개최지 운영조직의 역할 및 수행 업무에 대한 이해 개최지 마케팅 및 브랜딩 전략 수립 및 수행 방법 이해', '{"브랜딩","개최지","마케팅","전략","국내","사례","중소도시의","해외","역할","수립","지방","지원사업","프로젝트","유치","학습을","도시별","확인","대표","도시의","기능"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('686015', '비즈니스이벤트개론', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '이화봉', '본 과정은 마이스기획경영전공의 캡스톤 수업으로 실제 마이스관련 국제기구 및 지역의 CVB(Convention Visitors Bureau)가 원하는 비즈니스이벤트 및 지역프로모션을 중심으로 개최하는 공모전에 참여하는 수업입니다. 동아시아의 대학생들과 경쟁하며, 실제 비즈니스이벤트를 만드는 기획서를 국제적인 관점에서, 창의적인 관점에서 제작하게 됩니다. 또한, 수업은 영어로 진행되고 제출문서와 서류통과시 발표 역시 영어로 진행되는 수업으로 실제 도전에 대한 의지가 있어야 하는 수 업입니다. 다양한 경험이 대학생활의 미학이라고 여기는 학생들에게 적합한 수업입니다. 대학의 수업에서 가장 큰 가치는 경험을 통한 사고의 확장임이라고 생각하는 학생들을 위한 수업입니다. - 본 교과는 마이스기획경영전공 수업으로 비즈니스이벤트의 기획공모전 참여를 통해 국제적인 시각과 경쟁을 통한 성장을 배양하게 됨 - 외국어로 결과물을 제작함으로서, 팀 공동의 목적을 외국어로 정리할 수 있는 방법에 대해 이해하게 됨 - 비즈니스이벤트를 통한 지역프로모션이 무엇인지에 대한 이해가 가능하게 됨', '{"실제","통한","영어로","상세한","수업으로","수업입니다","하는","있는","대해","팀구성","교수자의","기획제안서","비즈니스이벤트를","국제적인","관점에서","외국어로","공모전","교수자","학습자","지난"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103106', '중국어초급회화II', '인문대학', '인문대학', 0, 3, '전선', '염철', '일상 생활에서의 중국어 대화를 가능하게 함을 목표로 식사, 쇼핑, 수업, 여행, 사회이슈 등 여러 가지 분야의 대화 다룬다. 수업은 주 로 지난 수업 내용 받아쓰기나 외우기, 본문 내용 분석, 읽기, 교수와 학생의 1대1대화 등으로 진행된다. 중국어 발음, 간체자, 기초 단어와 문법을 읽힘으로서 중국어 입문자에게 기초 회화와 문법을 전수한다.', '{"대화","받아쓰기","교수의","강의와","학생과의","단어와","나는","해석","연습","연습문제풀이","익힘","대화를","날씨가","점점","추워진다","만두","빚을","아니","우리가","사람을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103113', '중국개황', '인문대학', '인문대학', 0, 3, '전선', '김민호', '이 수업은 중국의 역사와 문화, 지리와 민족, 언어와 문자, 사상과 종교, 먹거리, 명절과 풍속, 서민 생활, 대중문화, 화교 등 중국 전반 에 걸친 사항들을 개론적으로 소개하는 내용으로 구성되어 있다. 이 수업을 통해 학생들은 중국 관련 기본 상황을 잘 알고, 또 이해할 수 있게 된다. 이 교과를 이수한 학생이 중국의 문화, 정치, 역사, 언어, 음식, 사회 등 각 분야의 기초적인 상황을 이해하는 역량을 갖추게 하는 것 을 목표로 한다.', '{"조별로","자신이","맡은","부분","중국의","설명","학생들의","발표문","이에","보충","이해한다","중국","상황을","중화인민공화국","숙지한다","총정리","역사와","지리와","민족","언어와"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('686017', '지역문화이벤트기획', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '이화봉', '- 지역에서 실제로 이행되고 있는 문화이벤트를 주최하는 기관/단체와 함께 실제 적용가능한 모델링들을 학생들과 실행한다. - 지역에 대한 관심과, 문화이벤트의 효과를 이해하는 것을 근간으로 한다. - 향후 대한민국에서 지역중심으로 이벤트를 만들어 실행하는 것으로 지역문제를 논의할 수 있다. 학습자는 지역의 가능성과 문제를 인식하고, 이벤트등으로 인해 지역을 지적/문화적 공동체로 만들고 수익화하는 방식을 고민하며 지역이벤트의 연속성을 위한 지속가능한 방법을 찾으려는 노력을 하게 한다.', '{"대상","이벤트를","교수자","학습자","한다","지역의","문제를","지속가능한","방법을","이해를","특강","수업에","수업의","이벤트에","이벤트","기획자와의","만남","풀어가는","이유에","파악하는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('686021', 'MICE창업론', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '민민홍', '-<MICE창업론>은 캡스톤 디자인(종합설계) 수업 방식을 통하여 4차 산업혁명 시대에 맞는 창의적인 실무능력을 갗춘 융합형 인재를 육성함 - 창업관련 팀별 프로젝트 기반 과제수행 및 학습으로 사업 아이템 발굴, 비즈니스 모델 수립, 사업계획서 작성 등 창의력과 문제해결 능력을 향상함 - 빅데이터 분석과 ICT 기술,관광MICE 마케팅 등 다양한 이론을 활용하여 지역의 현안 문제해결, 미래 창업 및 취업에 도움되는 역 량을 제고함 - 종합적인 창의력과 업무 수행능력, 리더십 및 팀 워크를 배양하고, MICE산업과 관련된 미래 창업 아이템 발굴, 기업 및 지역의 현안 해결,및 산업발전에 도움되는 아이디어를 제시함 - 기업과 사회에서 필요로하는 다양한 실무 역량과 기술을 갖춘 융합형 인재육성을 목표로 함', '{"창업","작성","사례","관광","컨벤션","자료","방법론","스타트업","특강","비즈니스","모델","사업계획서","캡스톤","디자인","조사연구","창업관련","팀별","아이템","발굴","개요"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103226', '중국어중급회화II', '인문대학', '인문대학', 0, 3, '전선', '염철', '중급회화 1 단계를 지나 조금 더 심화적인 내용으로 중국어 대화를 가능하게 함을 목표로, 여러가지 분야의 대화를 주제로 다룬다. 주 로 캠퍼스소개, 학교생활소개, 쇼핑, 병원문진, 여행, 영화감상평, 야유회, 음식문화 등을 주제로 대화와 발표를 진행한다. 교과서를 기초로 캠퍼스소개, 학교생활소개, 쇼핑, 병원문진, 여행, 영화감상평, 야유회, 음식문화 등을 주제로 대화와 발표를 진행한 다.', '{"활용하여","문장","문법","음식문화","만들기","대화","만든","외우기","어휘와","벗꽃에","학습계획서","생성형","캠퍼스","실전","관한","상점에서의","쓰기","영화감상문","활용한","회화"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('686023', '글로벌커뮤니케이션', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '안정현', '본 교과목은 글로벌 커뮤니케이션 환경에서 활용되는 다양한 콘텐츠 유형(보도자료, 기사, SNS 포스트, 관광 홍보물, 이벤트 초청장 등)의 실전 제작을 통해 학생들이 실용적인 영어 콘텐츠 제작 역량을 기를 수 있도록 설계되었다. 수업은 영어로 진행되며, 학생들은 주차별 실습을 통해 미디어, 광고홍보, 관광, MICE 분야의 특성과 대상에 맞는 콘텐츠를 직접 기획·작성·수정하는 과정을 경험하게 된 다. 선수학습은 요구되지 않으며, 비영어권 학습자를 고려한 단계별 과제와 피드백이 제공된다. 다양한 글로벌 커뮤니케이션 맥락에서 효과적으로 활용될 수 있는 실용 콘텐츠를 영어로 기획하고 제작하는 능력을 기른다. 학생들 은 미디어, 관광, MICE, 광고홍보 등의 분야에서 요구되는 콘텐츠 유형별 구조, 언어 스타일, 대상 독자 분석 방법을 학습하며, 프로젝 트 기반 실습을 통해 실무 역량과 창의적 표현 능력을 함께 함양한다.', '{"콘텐츠","작성","기획","보도자료","관광","구성","연습","피드백","행사","제작","구조","커뮤니케이션","기사","미디어","타깃","메시지","뉴스","쓰기","인터뷰","스크립트"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103231', '중국지역연구', '인문대학', '인문대학', 0, 3, '전선', '이민숙', '중국은 광활한 영토와 다양한 민족으로 구성되어 있고, 역사적으로 여러 갈래의 문화들이 서로 섞여 지금의 중국문화가 형성되어 있 습니다. 이에 본 수업에서는 중국 각 지역의 지리적인 특징에 대한 이해를 바탕으로 중국의 역사와 문화, 문학을 함께 살펴보는데 그 의의가 있습니다. 단순한 지리 공부가 아닌 지역의 문화와 문학, 역사에 대한 이해를 높임으로써 심도있는 중국학을 할 수 있는 기반을 닦는데 그 목적 이 있습니다. 본 수업에서는 중국 각 지역의 지리적인 특징에 대한 이해를 바탕으로 중국의 역사와 문화, 문학을 함께 살펴보는데 그 의의가 있습 니다. 단순한 지리 공부가 아닌 지역의 문화와 문학, 역사에 대한 이해를 높임으로써 심도있는 중국학을 할 수 있는 기반을 닦는데 그 목적 이 있습니다. 본 교과목은 한림대학교 인문사회융합인재양성사업(HUSS) 연계 교과목으로 HUSS에서 요구하는 융합인재로 성장할 수 있도록 합니 다.', '{"교수자의","수업태도","동영상","자료","중화명승","도시","중간고사","중국","그리고","지역의","이해를","중국의","역사와","문화","중국인","사랑한","공간","도시인가","항저우","오랑캐의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('686024', '글로벌전시및MICE실무', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '이형주', 'In today’s competitive environment, simply participating in an exhibition is no longer enough to prove a company’s value on the global stage. This course teaches you how to use international exhibitions and MICE platforms as powerful engines for branding, business gro wth, and global market entry. Through real case studies from CES, IFA, GITEX, and other global trade shows, students will design an end-to-end exhibition strat egy including: - Defining participation goals - Targeting buyers and investors - Designing high-impact booths - On-site pitching & networking - Lead follow-up and post-show business development Classes are conducted in English, combining lectures, team discussions, and hands-on project work. By the end of the course, you will present a full exhibition marketing plan for a real or selected company―just like a professional . This course is ideal for students aspiring to become: - Global marketers - MICE and exhibition strategists - Startup founders preparing for international expansion - Professionals who want practical skills and strategic insight Ready to grow into a global marketing professional? Enroll now and step onto the world stage! By the end of this course, students will be able to: - Understand exhibitions and MICE as strategic business platforms beyond promotion or sales. - Define participation goals and target markets for B2B, B2C, and B2G exhibitions. - Analyze and segment global buyers and create practical buyer personas. - Design booth experiences and customer journeys aligned with brand storytelling. - Pitch and communicate effectively on site in English with global buyers and partners. - Apply outboarding strategies such as media, awards, and brand events. - Develop and present an integrated exhibition marketing plan for a real or selected company.', '{"주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103233', '중국어문법및작문', '인문대학', '인문대학', 0, 3, '전선', '이지현', '본 강좌는 플립러닝 수업으로 1시간의 온라인 동영상 수업(수 5교시, 예습) 및 2시간의 오프라인 강의실 수업(월 5-6교시, 복습 및 심 화 학습)의 방식으로 운영된다. 또한 다음을 목표로 한다. 첫째, 기존에 익힌 초중급 수준의 중국어 구문 지식을 바탕으로 중국어의 문 법 틀을 정확하게 세운다. 둘째, 세부적인 문법 지식을 정확하게 익혀 중급 이상의 문법적인 중국어 구사 능력을 키운다. 이상의 목표 를 실현하기 위하여 중국어의 전반적인 문법 특징 및 품사, 특수 구문에 관해 학습하고, 아울러 다양한 그룹활동, 발표를 통해 그간 익 힌 지식을 정확하게 전달할 수 있는 능력을 키운다. 첫째, 기존에 익힌 초중급 수준의 중국어 구문 지식을 바탕으로 폭넓은 중국어의 문법 틀을 세운다. 둘째, 세부적인 문법 지식을 폭넓 게 익혀, 중급 이상의 문법적인 중국어 구사 능력을 키운다. 셋째, 이를 바탕으로 HSK 5급(졸업기준) 수준에 도달하기 위한 기초를 마 련한다.', '{"포인트","중국어","지식을","문법","교재","조동사","부사","개사","바탕으로","중국어의","정확하게","이상의","능력을","키운다","시간의","교시","첫째","기존에","익힌","초중급"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103517', '중국어프리젠테이션', '인문대학', '인문대학', 0, 3, '전선', '조정래', '본 수업은 중국학과 졸업시험과 연계 중국어의 내실을 기하며, 창의적이고 논리적인 프리젠테이션을 돕는데 본 교과목의 목적이 있 습니다.. 강의를 통해 학생들의 발표문 작성의기본적 개념과 체계를 익히고 교수와의 개별 지도를 통해 수준 높은 중국어 프리젠테이 션 능력을 배양합니다. ■ 졸업프리젠테이션시험(한국어 포함) 준비를 할 수 있도록 지도합니다. 발표와 관련한 주제선정을 시작으로 제목 결정, 자료 조사, 개요 작성, 본문 쓰기, 결론 작성 등 글쓰기 과정과 체계적인 프리젠테이션 제작 방법을 배웁니다. 수업진행 단계에 따라 발표실습을 하고 토론과 면담을 통하여 중국어 능력을 심화시킵니다 졸업 프리젠테이션 시험(한국어 포함)을 통과하도록 발표 능력을 향상시킵니다.', '{"발표문","프리젠테이션","실제","맞게","대해","논문","발표문을","글쓰기","이해한다","작성법","서울대출판부","자료수집","발표문작성의","형식에","프리젠테이션을","해당","중국어","작성","발표주제","주제관련"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103501', '중국문화강독', '인문대학', '인문대학', 0, 3, '전선', '양태근', '1.중국어 문장 독해의 기본이 되는 어휘와 구문 이해 능력을 증진시키기 위해 다양한 문장들을 접하면서 기초 생활 표현, 문장 표현 및 독해에 필요한 기본 능력을 증진시킨다. 학습 내용 주제는 그 주에 읽게 될 문장들의 주제로 다양한 생활 속에서 접할 수 있는 깊 이 있는 이야기들로 어학 실력과 삶의 가치를 생각해 볼 수 있는 문장들로 구성되어 있다. 2.가능한 즐겁고 빠르게 중국어를 학습할 수 있도록 다양한 학습 방법을 통해 삼자경, 동시, 노래, 동화 구현 학습 및 암송, 노래대회 등 다양한 형식을 통해 학생들 스스로 중국 전통시가와 문장을 통해 중국문화의 깊이 있는 사상과 전통을 배우고 성장할 수 있는 종 합적 학습 역량 제고를 목표로 한다. 3. 중국어 교육 과정과 관련성이 깊은 중국문학의 다양한 장르 특히 詩經, 楚辭, 5언, 7언 詩와 송,원,명,청 시기별 詞 중에서 중요 작품 을 직접 읽어보고, 감상하고, 암송하면서 중국어학습법 및 교육 과정에 대한 이해를 증진한다. 중국문화의 기초인 시를 통해 문화와 중국유가, 도가사상, 삶의 태도, 인간에 대한 기본적 이해를 통해 언어학습과 문화체험을 동시에 진행한다. 1. 삼자경과 중국의 시에 대한 이해와 암송 2. 중국어 노래경연대회를 통한 중국어 자신감 3. 중국어를 통해 연극과 같은 상황극 체험을 통한 체험적 언어학습 다양한 중국어 암송과 경연대회 및 체험학습을 통해 자연스럽게 중국어를 자신의 문화처럼 받아들이는 것을 목표로 한다.', '{"중국시가","중국어","삼자경","암송","어린왕자","것을","노래","삶의","자신의","인생","시간","계획","있는","스스로","인생의","가지","경지","한다","통한","突飛猛進的讀解方法"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('769006', '탄소중립과글로벌협력', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '양기웅', '이 교과목은 파리협정 이후 기후정치가 ‘감축목표 설정’ 중심에서 ‘감축성과의 국제이전과 승인, 그리고 그에 따른 책임과 신뢰의 관 리’로 이동한 현실을 전제로, 탄소외교(Carbon Diplomacy)의 핵심 메커니즘인 파리협정 제6조(Article 6)를 국제협상과 국제법의 관점 에서 체계적으로 학습하는 세미나이다. 수업은 6.2조(협력적 접근)와 6.4조(감독기구 기반 메커니즘)의 구조적 차이를 비교하고, 승인( authorization)·상응조정(corresponding adjustment)·MRV(측정？보고？검증)·레지스트리 등 거래를 성립시키는 제도요소를 하나의 외교-법률-시장 패키지로 이해하도록 설계된다. 이 교과목은 파리협정 이후 부상한 탄소외교의 핵심 메커니즘인 파리협정 제6조(Article 6)를 국제협상 및 국제법 관점에서 이해하고, 6.2조·6.4조 체계의 차이를 바탕으로 국가 간 승인·상응조정·MRV·레지스트리 등 거래 성립 요건을 통합적으로 분석·설계할 수 있는 실무 역량을 배양하는 것을 목표로 한다.', '{"학생발표","파리협정","교수강의와","한국법제연구원","교수강의","승인","윤인숙","신기후체계","탄소","그리고","규범","상응조정","시사점","정책","한국환경연구원","이후","국가","탄소외교","탄소의","정치경제"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('769007', '기후적응과지속가능발전', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '한상민', '<기후변화 적응은 모든 살아있는 존재와 지구 공동체의 생존의 문제> ‘기후변화 적응(climate change adaptation)’이란 무엇인가? 기후변화 적응은 우리 공동체의 지속가능한 발전(ex. "기후변화와 건강", "기후변화와 식량", "기후변화와 인권", "기후변화와 젠더" 등)을 위해 왜 중요한가? 기후변화 적응을 위한 기후행동(climate action)을 위해 국제사회는 무엇을 하고 있는가? 현재 선진국과 개도국은 기후변화 적응 분야에서 어떤 정책을 수립하고 이행하고 있는가? 그 리고 기후변화 적응정책과 관련 기후행동을 통해 우리는 어떻게 지속가능한 공동체를 만들어갈 수 있는가? 본 강의는 기후변화 적응의 핵심 개념, 관련 정책 수립 및 이행 과정 그리고 실용적 정책 접근법에 대한 이해를 높이고, 기후 위기(c limate crisis)의 시기에 기후변화 적응에 대한 정책이 국제-국가-지역적 차원에서 지속가능한 발전에 어떠한 의미와 중요성을 갖는지 고찰해 본다. 특히 녹색기후기금(Green Climate Fund, GCF)의 실제 프로젝트 자료를 활용하여 다양한 ‘기후 행위자(climate actors)’와 이해당사자(stakeholders)의 참여를 기반으로 적응 프로젝트가 어떻게 수립되고 이행되고 있는지, 사례 발표와 토론을 중심으로 정 책적 시사점을 도출하고 실현가능한 대안들을 모색해 본다. [Special Topic] 일기쉽게 보는 기후적응과 그린 AI: 실제 사례를 중심으로(Green AI for Climate Adaptation: Focus on Case Studies) * 수업 활용자료: UN 지속가능발전 교육자료, UN 기후변화 교육자료, EU 적응정책 Platform, 기후변화에 관한 정부간 협의체(Intergo vernmental Panel on Climate Change: IPCC) 평가보고서, 녹색기후기금(Green Climate Fund: GCF) 프로젝트 제안서 등 다양한 정책/ 실무자료 활용 ** 학기 중 기후변화 적응 관련 전문기관 방문 및 현장학습(with 청년 기후전문가와의 Climate Interview & Talk 등) 예정 2. 교과 목표 ■ 교과목표 - 기후변화 적응(climate change adaptation)의 기본 개념 및 배경지식 이해 - 기후변화 적응과 지속가능한 발전의 관계 및 주요 분야 이해 - 기후변화 적응 분야의 정책 수립 및 이행 과정 이해 및 분석 - 선진국과 개도국의 실제 기후변화 적응정책 및 관련 프로젝트 사례 분석 - GCF 적응 프로젝트 사례 발표와 토론을 통한 정책적 시사점 도출 및 대안 모색', '{"기후변화","적응","사례","있는가","어떻게","공동체의","실제","보는","지속가능한","기후변화와","위해","정책","녹색기후기금","프로젝트","중심으로","적응은","이란","무엇인가","적응을","국제사회는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103502', '중급중국어연습I', '인문대학', '인문대학', 0, 3, '전선', '이지현', '본 강의는 초급 수준의 중국어 수업을 이수한 중국학과 2학년 1학기 학생, 혹은 그의 수준에 해당하는 타학과 학생을 대상으로 한다. 중급 수준의 구문을 집중적으로 학습하고, 이를 통해 쉽고 짧은 문장을 연속적으로 나열할 수 있는 표현력을 키워 중국 현지 적응력 을 향상시킨다. 구체적으로는 주요 어휘를 사용한 문장을 반복 연습하고 관련 문법을 이해하도록 유도한다. 이를 통해 HSK 3급을 완 성하고 그 이상의 수준을 준비하도록 돕는다. 중국 현지인과의 간단한 대화 뿐만 아니라, 특정 주제에 대해 자신의 의견을 중급 이상의 단어, 구문을 활용하여 명확하게 전달하는 것이 가능하도록 한다. 이를 통해 HSK 3급을 완성하고 그 이상의 수준을 준비하도록 돕는다.', '{"말하기","암기","테스트","주교재","필요한","경우","별도","공지","교수자의","개별","그룹","연습","내용을","연습한다","숙지한다","주차","구성요소","이를","이상의","수준의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('505570', '데이터조사기법', '정보과학대학', '정보과학대학', 0, 3, '전선', '심송용', '관심의 대상전체에서 얻고자 하는 정보를 알아내는 방법을 공부한다. 주로 유한한 관심대상 전체(모집단)에서 일부를 추출하는 방법과 그에 따른 추론에 대해서 공부한다. 단순임의표집, 층화임의 표집, 집락표집, 계통표집 등의 전통적인 표집 방법과 이들의 융합된 표집방법에 대해서 연구한다. 자료를 수집하기 위해 모집단을 대표할 수 있는 표본을 얻기 위한 다양한 조사기법을 이해하고 이에 따른 추정 및 필요한 표본수를 얻을 수 있는 역량을 배양한다.', '{"중간고사","수업시간에","배포","추정","평균과","표본수","비율","표본","층화추출법","결정","집락추출","따른","표본을","합에","계산","비율에","추론","주차","구성요소","계통추출"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('769011', '기후변화와기후정책', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '한상민', '"기후변화는 환경적 현상이지만, 기후변화 정책은 환경적 문제를 넘어 그 해결책을 통합적으로 계획하고 이행하는 지속가능한 발전 정책입니다." <기후변화와 기후정책의 이해>는 글로벌융합대학 기후변화융합전공의 ''첫걸음'' 교과목으로서, 현재 긴급한 지구적 의제로서 기후변 화의 문제를 이해하고 그 해결책을 국제적/국가적/지역적으로 모색하는 시간입니다. 본 교과목은 UN의 대표적인 기후변화 기관인 IP CC(기후변화에관한정부간협의체)의 실무그룹(Working Group)과 평가보고서(Assessment Report)의 구성에 따라, 아래와 같이 3대 핵 심분야의 주요 이슈들을 종합적이고 체계적으로 ''알기쉽게'' 다루고자 합니다. Part I. 기후변화 과학의 주요 개념과 특징적 현상에 대한 기초적 이해 Part II. 기후변화 영향, 적응, 취약성의 기본적 이해와 정책적 대응 분석 Part III. 기후변화 완화(온실가스 감축)의 기본적 이해와 정책적 대응 분석 [Special Topic: Climate Action and Green AI] 1. Geen AI vs Red AI 2. Green by AI and Green in AI? 특히 수업 참가자들은 기후행동 사례연구와 주제발표를 통해 위 핵심분야와 관련한 복합적인 기후위기 이슈들을 주실제적인 ''삶의 문제''와 공동체의 발전문제로 접근할 수 있을 것입니다. (주제분야 예시: 기후변화와 지속가능발전, 기후변화와 탄소중립도시, 기후친화적 스마트도시와 지속가능한 발전, 기후변화와 인권, 유럽의 탄소중립과 독일의 에너지자립마을, 아시아의 기후위기와 스마트농업 프로젝트, 아프리카의 기후위기와 재생에너지 프로젝트 , 글로벌 기후행동과 디지털전환 등) * 학기 중 기후변화 대응 전문기관 방문 및 현장학습 예정(with 청년 기후전문가와의 Climate Interview & Talk) ** 교과목 수업과 현장학습 등을 통해 기후변화 대응 분야의 진로 및 취업 파악 + 미래 기후전문가로서의 준비 - 기후변화의 기본 개념과 주요 특징적 현상 이해하기 - 기후변화 정책(기후정책)의 기본 개념과 주요 이슈 이해하기 - 다양한 국제적/국가적/지역적 사례연구를 통해 기후위기를 우리의 실제적인 ''삶의 문제''와 공동체의 발전문제로 인식하고 혁신적인 해결책 모색하기 - 글로벌 기후변화 전문가를 위한 기초적인 전문지식과 통합적인 접근법 Learn & Act', '{"기후변화","평가보고서","기후변화의","대응","적응","완화","기후변화와","개념과","현장학습","과학","취약성","과학의","정책적","전문기관","방문","청년","기후전문가와의","미래","과학적","환경적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103504', '중국경제론', '인문대학', '인문대학', 0, 3, '전선', '성시일', '중국경제의 중요성이 커지면서 이에 대한 관심이 높아지고 있다. 그러나 중국경제 체제 등 이론적인 이해는 상대적으로 높지 않다. 사회주의 국가인 중국의 특성에서 경제발전의 원동력이 무엇인가는 지금도 연구의 대상이다. 1978년 경제 개혁개방 이후 경제정책과 이에 따른 결과를 집중적으로 알아보고, 최근 중국경제의 이슈와 앞으로의 전망을 파악한다. 본 강의는 먼저 1990년대의 중국경제를 이론적으로 이해하도록 하고, 2000년대의 중국경제를 시사적인 과점에서 파악하는데 주안점을 둔다. - 중국경제에 대한 전반적인 지식을 얻도록 한다. - 중국경제를 경제사 관점에서 파악하여 현재의 중국경제가 형성된 배경을 이해하도록 한다. - 현재의 중국경제를 자신의 관점에서 파악하고 이해하도록 한다. - 중국경제에 대해 객관적인 분석을 할 수 있도록 한다.', '{"한다","중국","중국의","이해하도록","경제","중국경제","정책을","특히","배경을","시기의","정책의","개년","계획","파악하도록","영향을","의미와","소유제","개혁의","대외무역","국가인"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('769019', '아프리카와평화', '글로벌융합대학', '글로벌융합대학', 0, 3, '전선', '김병춘', '본 교과목은 국제정치·국제안보의 기본 개념을 토대로 아프리카 지역의 분쟁과 평화 문제를 구조적·역사적·사례 중심으로 분석하는 것을 목표로 한다. 특히 국제평화와 안보, 유엔 중심의 평화유지활동(PKO), 인도적 지원？개발？평화 연계(HDP Nexus) 등 글로벌 거 버넌스 논의를 바탕으로, 아프리카 분쟁의 특수성과 국제사회의 개입 방식, 그리고 한국의 대아프리카 평화활동 사례를 종합적으로 이해하도록 설계되었다. 본 과목을 통해 학생들은 첫째, 국제평화·안보·분쟁 개념과 이론을 체계적으로 이해하고 이를 아프리카 사례에 적용할 수 있는 이론 적 분석 역량을 함양한다. 둘째, 아프리카 국가별 분쟁 사례와 평화구축 과정을 비교·분석함으로써 복합적 분쟁 구조를 파악하는 지역 연구 및 비교분석 역량을 강화한다. 셋째, 유엔 PKO, HDP Nexus, SDGs, 기후변화와 분쟁 연계 등 최신 국제 담론을 비판적으로 검토 하여 정책 이해 및 비판적 사고 역량을 기른다. 넷째, 한국의 국제평화활동 참여사례와 현장 중심의 논의를 통해 글로벌 시민으로서 의 국제적 소통 능력과 실천적 문제해결 역량을 함양하는 것을 궁극적 교육목표로 한다. 이 과목은 국제평화와 안보 이론을 토대로 아프리카 지역의 분쟁과 평화유지·평화구축 과정을 체계적으로 이해하고 분석하는 능력을 함양하는 것을 목표로 한다. 학습자는 국제분쟁의 원인과 개입 방식, 유엔 평화유지활동(PKO)과 HDP Nexus의 적용 사례를 아프리 카 맥락에서 비판적으로 검토함으로써, 복합적 분쟁 환경을 구조적으로 분석하는 역량을 기르게 된다. 나아가 문화적 다양성과 지역 주체성을 존중하는 세계시민적 태도를 바탕으로 국제평화·안보 문제에 대한 책임 있는 인식과 정책적 사고능력을 함양하도록 한다.', '{"사례","이해한다","참여도","유엔","아프리카","자료","분쟁의","분쟁","분석한다","평화","사례를","비판적으로","다차원","분쟁과","평화유지활동","개입","한국의","실패","이전","이해하고"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103506', '한중시장분석', '인문대학', '인문대학', 0, 3, '전선', '강희모', '한국과 중국의 시장 분석은 데이터가 반드시 필요하고 습득한 데이터로 시장에 대한 올바른 판단을 하려면 분석이 필요하다. 따라서 이 교과목에서는 올바른 시장분석을 위한 분석방법을 소개한다. 처음에 데이터로 자료분석하기가 쉽지 않기에 인공지능(artifial intelligence;AI)을 활용하여 분석하는 방법을 습득한다. 우리가 사용할 AI는 OpenAi 플랫폼 회원가입하고 사용가능한 대화형 인공지능 서비스인 ChatGPT, 마이크로스프트(Micorsoft)사에서 개발한 Coplioit, 구글(Google)에서 제작한 대화형 AI 도구 Google Bard 등이다. 한국과 중국 시장을 분석할 수 있는 능력을 학습한다. 한국과 중국의 시장 분석은 데이터가 반드시 필요하고 습득한 데이터로 시장에 대한 올바른 판단을 하려면 분석이 필요하다. 따라서 이 교과목에서는 올바른 시장분석을 위한 분석방법과 결과에 대한 해석방법도 소개한다. 처음에 데이터로 자료분석하기가 쉽지 않기에 인공지능(artifial intelligence;AI)을 활용하여 분석 방법과 결과에 대한 해석방법을 습득 한다. AI로 분석과 해석을 동시에 진행할 수 있으므로 수치적 개념이 부족하더라도 부담없이 수업에 참여할 수 있다. 우리가 사용할 AI는 OpenAi 플랫폼 회원가입하고 사용가능한 대화형 인공지능 서비스인 ChatGPT, 마이크로스프트(Micorsoft)사에서 개발한 Coplioit, 구글(Google)에서 제작한 대화형 AI 도구 Google Bard 등이다.', '{"데이터","이론과","연습문제","주요학습내용에","대하여","데이터를","스프레드시트","많이","인공지능과","그래프로","요약하기","인공지능","처리","프로그램과","프로그램을","평균","올바른","도구","분석과","전달"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('701015', '바이오데이터분석', '정보과학대학', '정보과학대학', 0, 3, '전선', '유재용', '바이오데이터분석은 의학 분야에서 생성되는 다양한 데이터를 분석하는 방법을 배우는 것을 목표로 한다. 교과목에서 다룰 데이터로는 EMR (Electronic Medical Records)자료와 Image data 를 다루며, 의료정보학에서 최신의 기술을 학습한 다. 이 과목은 바이오데이터 과학 기초부터 실제 데이터를 활용한 실습까지 다룬다. 바이오데이터의 특성을 이해하고 이를 분석하기 위한 기본 원리를 학습한다 Python, R 등 데이터 분석 도구를 활용하여 데이터 전처리, 분석, 시각화 능력을 배양한다 환자 기록 데이터, 이미지, 시그널자료 등 바이오데이터에 대한 실제 적용 사례를 통해 실질적인 문제 해결 능력을 함양한다. 데이터 윤리 및 개인정보 보호와 관련된 문제를 이해한다.', '{"바이오데이터","활용한","강의자료","자료를","데이터","이미지","시그널","전자의무기록","같은","멀티모달","분석의","최신","기법","바이오데이터에","데이터를","실제","능력을","수업개요","타입","전자의무기록을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103521', '중국지역학이슈세미나', '인문대학', '인문대학', 0, 3, '전선', '홍필태', '본 강좌는 중국의 언어, 역사, 정치, 경제, 사회, 문화, 예술 등 사회 전반을 이해하는 데 필요한 기초적인 지식을 습득케 하여 동북아 지역에 대한 이해를 증진시키고 나아가 시대 변화와 기술 발전의 맥락에서 동북아 지역의 미래에 영향을 미치는 추세를 예측하며, 성 장과 지속가능성의 조화, 생활과 노동 방식의 변화, 디지털 정보와 데이터, 정체성과 새로운 소속감, 변화하는 자연과 사회적 대응 등 과 같은 사회적 변화에서 중국 지역학의 기초 지식은 물론, 심층적인 내용에 대한 흥미를 유도하여 중국 사회와 생활 문화의 기본적 인 이슈의 이해를 넘어 심도있는 연구를 수행할 수 있는 탐구능력을 배양한다. 중국 및 동북아 지역 사회와 문화를 깊이 이해하고, 비판적으로 분석할 수 있는 능력을 기르는 데 목적이 있다. 특히 중국 사회와 문 화의 기본 이슈 이해, 중국의 역사적 맥락 분석, 비판적 사고와 토론 능력 개발, 중국 정책과 국제 관계 이해, 문화적 차이와 글로벌 감 각 함양, 다양한 학문적 접근법 등 다양한 이슈 학습과 실무 적용을 통해 학생들이 중국 지역학에 대한 종합적이고 깊이 있는 이해를 갖추고, 글로벌 시대에 필요한 역량을 개발하는 데 중점을 둔다. 본 교과목은 한림대학교 인문사회융합인재양성사업(HUSS) 연계 교과목으로 HUSS에서 요구하는 융합인재로 성장할 수 있도록 한다.', '{"강의자","동영상","중국의","준비자료","조별발표","중국","이해한다","정치","해외투자","대하여","중국과","간략한","소개와","일반","대해","갈등에","역사","동북아","경제에","정치적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('103524', '동아시아영화와평론', '인문대학', '인문대학', 0, 3, '전선', '양태근', '영화라는 종합예술형식이 담고 있는 역사, 문화적 함의와 은유를 통해 동아시아 문화 이해의 지평을 넓힌다. 또한 동아시아 영화 및 평론을 보고 읽으면서 이에 대한 자신의 비평적 토론이 가능하도록 준비한다. 동아시아 영화 전반에 공통으로 드러나는 주요 주제들 과 관련한 영화를 통해 동아시아와 세계 문화의 교류 및 이해의 가능성을 탐독한다. 동아시아 영화들이 공통적으로 보여주는 핵심문제들에 대한 이해를 바탕으로 학생들이 수업 시간 동안 스스로 문제를 통해 학습하고 한 학기 동안 프로젝트를 만들어가면서 단순 지식 전달이 아닌 지식 생산과 창의적 지식 기반 역량을 창출할 수 있도록 한다. <지식 기반 역량> (Problem Based Learning) 1. 동아시아 기반 다양한 문제들에 대해, 또한 핵심 주제들에 대해 문제 중심 학습을 통한 기초 지식의 자발적 이해 2. 동아시아 영화들이 가지고 있는 핵심문제 해결을 인터넷과 토론을 통해 정리하고 자발적이고 능동적인 토론을 통해 스스로 해결하 고 핵심문제들에 다가갈 수 있는 역량을 제고한다. <기술 기반 역량> (Project Based Learning) 1. 동아시아 및 영화 분석특에 대한 이해도를 증진하며 비교 학습한다. 2. 한 학기 동아시아 영화 분석을 관통하는 해석능력과 프로젝트 중심 학습을 통해 동아시아 영화, 사회, 문화 분석 이해 역량을 개발 한다. 3. 한 학기 동안 장기적인 프로젝트를 구성한 후에 분야별 핵심 문제들의 주도적 이해와 토론을 통해 해결책을 찾으면서 학습한 문제 해결 방법을 어떻게 응용할 수 있을지를 조별 과제로 만들어 수업 과정과 연계 운용한다. 학생들 스스로 핵심 문제에 접근하고 이해 하면서 어떻게 해결할 수 있을지를 팀별 프로젝트를 통해 해결할 수 있는 자발적 학습 기반 역량을 제고할 수 있도록 한다. <태도 기반 역량> (Competitive Collaboration & Collaborative Competition Based Learning) 2. 교과 목표 ■ 교과목표 1. 조별 토론을 통해 지식 기반 역량을 제고하면서 수업 중에 제기 된 문제를 해결하고 조별 내 협업과 토론을 통해 배움의 경험이 즐 겁고 생산적임을 배우게 한다. 경쟁과 협업이 동시에 진행되면서 학생들의 창의적 도전과 배움이 가능하도록 한다.', '{"영화감상","영화","동아시아","기반","있는","어떻게","과연","지식","역량을","한다","토론을","삶을","다루는","속에서","길의","의미는","영화속에서","자아를","추구하는","과정의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('701016', '의사결정모형과응용', '정보과학대학', '정보과학대학', 0, 3, '전선', '심송용', '선택가능한 여러 가지 행동대안 중에서 객관적 기준에 근거하여 최선의 대안을 선택하는 방법을 공부하며 효용함수, 사후확률, 기대 가치, 위험분담, 의사결정나무 등의 방법 등을 이해하고 이에 따른 의사결정 과정을 이해하여 합리적 의사결정을 하는 역량을 배양한 다. 데이터 기반의 여러 가지 의사결정과정을 이해하고 이 의사결정과정을 현실에 적용할 수 있으며 이러한 의사결정과정에 따라 합리적 행동대안을 선택할 수 있도록 한다.', '{"수업시간에","배포","의사결정","중간고사","의한","기대가치","사후확률에","정리의","효용함수","주차","구성요소","표본정보의","여러","가지","최선의","위험분담","이해하고","합리적","의사결정과정을","교과목소개"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104101', '기초일본어I', '인문대학', '인문대학', 0, 3, '전선', '이광제', '기초일본어 수업에서는 ‘읽기,쓰기,말하기,듣기’ 를 균형있게 학습하며, 기초문법,문형을 익히면서 일상회화의 연습도 병행한다. 이와 더불어, 일본의 문화,역사,풍습 등 일본사회의 전반적이고,기초적인 배경지식을 확인하여 일본어,일본사회를 이해하는 것을 목표로 한 다. .문자(히라가나,카나카나)에 대한 바른 이해와 정확한 지식의 습득은 일본어 학습에 초석이 되므로 정확하게 읽고 쓸 수 있도록 한다. 문법과 문형의 학습은 지식의 습득과 실제 운용면을 고려하여 균형있게 학습함으로써 커뮤니케이션 능력을 기르도록 한다. 일상 생활에서 자주 쓰이는 표현과 인사말 등을 반복 연습하여 말할 수 있도록 한다.', '{"교재","프린트","자료","읽고","문형을","소리로","말하며","문법","학습한다","발음","문자와","自己紹介","동사의","정확하게","음도","쓴다","히라가나","문자를","장음","인칭대명사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('712000', '데이터과학입문', '정보과학대학', '정보과학대학', 0, 3, '전선', '이기원', '데이터 사이언스의 기초적인 개념과 실제 응용에 대하여 학습한다. 수학/통계학, 정보기술 및 관련 분야의 지식이 어떻게 데이터 사이언스의 기초를 이루는지 실제 데이터를 이용하여 파악한다. 세부적인 기술보다는 어떤 문제를 해결하는 데 어떤 방법을 사용하는 것이 가장 좋을지 판단하는 능력을 갖추도록 한다. 데이터과학의 기본 개념과 프로그래밍 기초 학습', '{"강의와","온라인","교재","온라인퀴즈","실습과제","제대로","데이터","그려보기","눈속임","그래프","오류","그려","생명표","국민투표","통계","시각화","비식별","랜덤화의","랜덤화","도표의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104105', '초급일본어회화I', '인문대학', '인문대학', 0, 3, '전선', 'KOSHIRO', '본 교과는 초급일본어 학습자를 대상으로 기초적인 문법과 문형을 습득(JLPT N3수준), 일본어를 실제로 응용하는 커뮤니케이션 능력 을 기르는 것을 목적으로 한다. 다양한 회화활동을 통해서 일상생활에서 실제로 쓰는 일본어 표현을 배운다. 1. 일본어 초급과정의 문법 이해 2. 일상생활에서 실제적으로 쓰이는 표현, 기초적인 일본어 회화 습득하기', '{"표현","일본어","나타내는","いくらですか","동사","旅行","여행","소집단","회화활동","얼마예요","새학기","주차","구성요소","중간고사","街角で","거리에서","동사た형","した","스피치","기초적인"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('712034', '행렬과데이터분석', '정보과학대학', '정보과학대학', 0, 3, '전선', '이재화', '본 [행렬과데이터분석] 과목은 데이터테크 전공 3수준의 전공선택 과목으로, 주로 행렬에 관한 지식과 행렬 기반의 데이터 분석 기법 을 다룬다. 이는 정형 데이터를 분석하는 기법의 기초가 되고, 실제로 학생들이 졸업 후 직업 현장에서 대부분의 데이터 분석 업무에 활용할 것으로 판단된다. 따라서 학생들이 행렬의 성질을 이해하고 이를 다룰 수 있는 능력은 데이터 처리의 기본으로, 본 [행렬과데 이터분석] 과목은 향후 역량을 키워나가는 데 아주 중요한 과목이라고 할 수 있다. 본 [행렬과데이터분석] 과목에서는 행렬을 기반으로 하는 데이터 분석 기법 중 선형 회귀(Linear Regression), 주성분 분석(Principal C omponent Analysis), 선형 판별 분석(Fisher’s Linear Discriminant Analysis)에 대한 자세한 소개, 수학적 아이디어 및 관련된 기초적인 행렬 지식을 코딩과 함께 학습한다. 이를 통해 학생들은 다양한 데이터 분석 업무에 필요한 행렬 지식 및 코딩 능력을 보유하게 되어 향후 최신 분석 기법을 이해하는 데 필요한 수리적인 기초지식을 얻게 된다.', '{"주차별","강의자료","학습한다","코딩","강의시","따로","안내함","질의","응답","문서화","관하여","행렬","동영상","분해","조별","주성분","고윳값","프로젝트","데이터","연산"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('712035', '데이터분석의수리적기초', '정보과학대학', '정보과학대학', 0, 3, '전선', '이재화', '수집된 데이터를 분석하여 필요한 정보를 얻기 위해서는 분석 기법에 대한 이해가 필수적이다. 그리고 분석 기법의 원리와 아이디어를 이해하기 위해서는 적절한 수학, 통계 지식이 선행되어야 한다. 본 과목은 데이터 분석에 꼭 필요한 수리적 기초 지식을 코딩과 함께 교육한다. 본 과목에서는 데이터 분석가가 갖춰야 할 수리적인 기초 소양을 코딩과 함께 학습한다. 특히 데이터를 표현하고 분석하는 과정을 따 라 꼭 필요한 핵심 개념을 중·고등학교 수학/확률/통계 지식에서부터 이끌어 낸다. 따라서 고등학교 과정에서 수학 과목을 선택하지 않았던 학생들도 두려움 없이 쉽게 접근할 수 있다.', '{"대하여","주차별","강의자료","강의시","따로","안내함","학습한다","필요한","데이터의","데이터에","개념인","학습한","공분산","데이터를","데이터는","어떻게","계산하기","개념을","방법에","유사한"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104116', '일본학입문I', '인문대학', '인문대학', 0, 3, '전선', '전성곤', '신입생 1학년을 위해 개설된 과목입니다. 특별히 이러한 수강생을 위해 본 강좌는 <일본 전반에 대한 기초지식>을 다룰 예정입니다. 기초지식이란 지금까지 학교 교육이나 미디어 등을 통해 갖게 된 ‘일본의 이미지’에 대한 재고를 의미하기도 합니다. 사실 우리들은 의식적 혹은 무의적으로 일본에 대한 이미지를 형성하게 되는데 그것은 학교에서의 교육에서 뿐만 아니라 미디어를 포함하는 제반 '' 문화적 생활''속에서도 내재되어 있었던 것입니다. 따라서 본 강좌에서는 전자의 관념들이 형성된 근거를 후자의 방법론을 통해 재고 해 보고, 이를 통해 스스로가 주체적으로 일본에 대한 새로운 이미지를 재구성하는데 기여하고자 합니다. 신입생을 대상으로, 일본학 전공에 필요한 기본적인 필수지식을 습득하는 동시에 스스로 일본학에 대해 소개할 수 있는 역량을 키운 는데 있습니다. 일본학이라는 이름으로 시도되는 일본연구는 일본에 대한 지식 습득뿐만 아니라 한글에서 일본어워드를 작업하는 방 법, 그리고 다층적이면서 복수적 시각을 통해 한국과 일본을 상대화하는 주체적 역량을 함께 배양하는데 있습니다.', '{"이해한다","진행한다","자료를","일본의","일본인의","파워포인트","수업시간에","퀴즈를","강의형식으로","풀어본다","배포하고","일본","본다","내용을","나타난","배포된","형식으로","배포한","지형적","나누어주는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('712036', '기계학습알고리즘', '정보과학대학', '정보과학대학', 0, 3, '전선', '이재화', '기계학습 알고리즘의 원리를 이해하기 위해서는 관련된 수학 배경 지식이 필수적이다. 본 과목에서는 ① <인공신경망>을 중심으로 필요한 수학적 배경 지식 및 알고리즘의 원리를 소개하고 ② CNN, kNN, 클러스터링(clustering), GAN(generative adversarial networ k) 등의 기계학습 알고리즘을 코딩과 함께 교육하려고 한다. 본 수업은 [생성형 AI 결합 교과목]으로, 수강생들은 학습하면서 궁금한 것을 생성형 AI를 통해 질문하여 얻은 초벌 답변을 비판적으로 검토하며 내용을 정리하고 문서화하는 능력을 키운다. 본 과목에서는 인공신경망(artificial neural network), kNN(k-nearest neighbor), 클러스터링(clustering), GAN(generative adversarial n etwork) 등의 기계학습 알고리즘을 수학적으로 이해하고 코딩과 함께 실습하고자 한다.', '{"강의자료","차시","답변을","매주","최소","필수","에게","내용에","관한","유의미한","질문","바탕으로","문서화","관하여","전반부","실습을","학습한다","신경망","조별","생성형"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104211', '일본어문법', '인문대학', '인문대학', 0, 3, '전선', '황경자', '본 교과는 일본어 초급문법을 이미 습득한 학생을 대상으로 하여, 배우는 일본어에서 실제로 쓰고, 활용하는 일본어 능력 양성을 목 표로 한다. 기초문법을 이해하고 점검하는 동시에 중급수준 이상의 문법지식을 습득하여 실천적인 독해능력, 작문능력을 양성하는 것 을 목표로 한다. 문법적인 이해를 전제로 하면서 정독보다는 다독에 중점을 둔다. 가능한 한 수업 중에는 일본어를 사용한다.(수강생 전원의 일본어 능력을 파악한 후 결정한다.) 본 과목은 일본어학의 기초적인 문법과 문형을 배양하고 일본어 회화 수업을 통해 기초적인 의사소통 능력을 학습한다. 또한 초급 일본어 학습지가 보다 쉽고 재미있게 일본어를 배울 수 있도록 효과적인 교수법(activity, pair work)등을 통해서 일본어 능력을 기룰 수 있게 하는것이 목표이다.', '{"작문","주교재","쓰기","일본어","연습","작문첨삭","표현","사용해서","문형연습","說明과結論의","작문테크닉","표현습득","과에서","문형을","첨삭","배운","자주","표현을","유사한","과의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104305', '중급일본어회화I', '인문대학', '인문대학', 0, 3, '전선', 'KOSHIRO', '본 교과는 일본어 초급 단계를 마친 학생들을 대상으로 일상생활에서 실제로 응용하는 일본어 중급 단계 회화 능력을 기르는 것을 목적으로 한다. 중급 수준(JLPT N2정도)에 필요한 문법/표현을 배우는 동시에 일반적인 토픽에 대해서 논의,프리 토킹등 다양한 회화활동을 통해서 회화 능력을 양성한다. 학기 말에는 학생 각자 자신이 정한 일본에 관련된 주제로 개인 발표를 실시한다. 1. 중급과정의 일본어 아학 능력을 종합적으로 양성한다. 2. 그룹 토론, 발표 등 다양한 황동을 통해서 실제적인 일본어 구사 능력을 습독한다. 3. 일본에 관련 된 주제로 조사한 성과를 일본어로 발표한다. (개인발표)', '{"주제","회화","문법","독해","소집단","프리토킹","어휘","질의응답","활동","회화활동","학습자","일본어","개인발표","주차","능력을","연애","교육","성공","소집단활동","필기시험"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209106', 'AI활용조사방법론', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '안창현', '본 「AI활용조사방법론」 강좌는 프롬프트 엔지니어링(PE)과 컨텍스트 엔지니어링(CE)을 사회과학적 연구 방법론의 핵심 도구로 재정 의하는 것을 목표로 한다다. 기존의 PE 교육이 주로 효율성과 생산성에 초점을 맞춘 것과 달리, 이 과정은 AI를 활용해 복잡한 사회 문제를 탐색하고 연구 질문을 체계적으로 구조화하는 방법론적 도구로 활용하는 데 목표를 둔다.. - 연구 질문(RQ)을 누구의 어떤 문제를 해결하는지에 대한 명확한 변수와 제약 조건의 집합으로 변환한다 - 설계한 프롬프트 및 워크플로우를 타인이 따라 할 수 있을 만큼 엄밀하게 문서화(PDD)하고 고급 PE 기법을 적용하여 방법론적 엄격함을 확보한다 - AI 결과물을 비판적으로 검증(RVR)하고, 그 결과가 실제로 누군가의 일이나 삶을 개선했다는 증거를 제시하며 윤리적 책임을 내재화한다 - 16주 과정은 세 가지 핵심 질문을 중심으로 구성되며, 각 질문은 학생들이 단순한 기술 사용자(User)를 넘어 AI와 지식을 공동 창조하 는 주체(Co-creator)로 전환하도록 유도하는 학습 목표가 된다. 디지털 시대의 조사연구는 AI 기반 도구와 통계 분석 능력을 필수적으로 요구한다. 본 과목은 정량적 조사방법론의 구조, 설계, 해석 능력을 학습자 스스로 체화하도록 설계되었다. 특히 본 과목의 목적은 각종 데이터 분석 및 문제 설계와 분석 능력은 물론, 통계 분석 능력과 메타인지적 연구역량을 함양하는 데 목적이 있다. 본 수업은 프로젝트 기반 학습(PBL) 및 AI 튜터 기반 학습보조 시스템을 병행하는 실습 중심 수업이다. 학생들은 AI와 협업하여 논문 을 구조화하고, 연구설계 초안을 작성하며, 통계 개념을 시각화로 이해하게 된다. 이 모든 활동은 팀별 프로젝트 및 개별 보고서와 연 동되며, 강의？실습？피드백이 반복되는 역동적 루프 기반 수업 설계로 운영된다. -이 과목은 AI 튜터를 활용하여 학생들에게 데이터 분석 및 연구 설계 능력을 배양하는 데 목적이 있습니다. -커뮤니케이션 및 미디어 심리학의 기초와 통계 분석 기법을 AI 기반 학습 환경에서 습득하고, 연구계획서를 작성하는 과정을 통해 문 제 해결 능력을 강화합니다. -AI 튜터를 활용하여 데이터를 해석하고 논문 작성법을 실습하며, 연구 시뮬레이션 도구를 활용해 비판적 사고 및 분석력을 개발합니 다. -본 교과목은 2025-1학기 AI에듀테크센터 주관 <AI튜터 특화교과목> 선정 교과목입니다. - 연구 질문(RQ)을 누구의 어떤 문제를 해결하는지에 대한 명확한 변수와 제약 조건의 집합으로 변환한다 -설계한 프롬프트 및 워크플로우를 타인이 따라 할 수 있을 만큼 엄밀하게 문서화(PDD)하고 고급 PE 기법을 적용하여 방법론적 엄격 함을 확보한다 -AI 결과물을 비판적으로 검증(RVR)하고, 그 결과가 실제로 누군가의 일이나 삶을 개선했다는 증거를 제시하며 윤리적 책임을 내재화 한다', '{"패턴","설계","데이터","복잡한","방법론적","사고","사용하여","질문","고급","활용하여","형식","프롬프트","문제를","기반","능력을","제약","하고","적용하여","검증","통계"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104404', '일본문화독해I', '인문대학', '인문대학', 0, 3, '전선', '조수일', '초급 단계의 어법 및 어휘 문형을 익힌 일본어 학습자들이 문화(언어, 사회)와 관련된 다양한 장르의 현대어 문장을 접함으로써, 일본 어 문장은 물론 일본문화와 일본인의 사고방식에 대한 이해능력을 배양할 수 있다. ① 일본인의 생활방식과 문화를 소재로 한 탄탄하고 체계적인 문장을 통해 일본어 어휘력과 독해력 및 사고력을 키운다. ② 다양한 문장 읽기를 통해 복잡한 문법과 유사표현에 대한 문법지식을 배양한다. ③ 일본문화와 일본인의 사고방식에 대한 이해능력을 함양한다.', '{"튜터","일본의","주차","일본","이해한다","일본인의","교재","知っていますか日本のこと","學ぼう","話そう","日本事情","改訂版","있다","파악한다","특징","퀴즈풀기","설명할","영상","역사와","그룹토론"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209108', 'DIGITAL MEDIA,', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '백지연', '본 과목의 목표는 다음과 같다. - Digital Media, AI, and Society 각각이 무엇인지 배웁니다. - Digital Media, AI, and Society가 어떤 관계를 가지고 있는지 배웁니다. - 그리고 위의 배움이 내 인생과 무슨 상관이 있는지를 생각해봅니다. - 이러한 배움들을 가지고 나는 무엇을 할 수 있는지, 또 해야만 하는지를 고민해봅니다. - 최종적으로 그 생각들을 소박하게라도 실행해봅니다. 본 과목의 목표는 Digital Media, AI, and Society 각각에 대한 이해를 바탕으로 이들이 어떤 관계를 가지고 있는지 학습하고 미디어 전공자로서의 비판적 이해를 도모하는 것에 있다. 또한, 빠르게 발전하는 미디어 기술들을 활용하고 나의 생활과 학업에 사용할 수 있는 방법을 함께 익히고자 한다.', '{"데이터","개인","조별","활동","간단실습","노트북","패드","지참하면","좋습니다","중간고사","도구","사용해서","가지고","있는지","미디어","특징","변화","전체","들으며","따라하기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104427', '일본문학의이해', '인문대학', '인문대학', 0, 3, '전선', '서정완', '1)일본의 문학, 문화를 중심으로 역사학이나 대중문화까지 포함한 다양한 분야에서 일본에 대한 이해를 도모하는 데 역점을 둡니다. 2)지직의 단순 주입은 지양하고, 수강생이 주체적으로 한국과 일본에 대해서 생각하는 지향하고 유도합니다. 즉 ''내 생각, 내 의견''을 갖기 위한 과정이라 생각하면 됩니다. 3)강의 구성은 담당교수 주도 하에 교수의 설명+학생의 발표와 토론+체험학습+일본 대학생과의 교류를 통해서 입체적인 일본 이해 를 도모합니다. 4)이를 위해서 수강생의 적극적인 참여의식이 필요합니다. 일본의 역사와 대중문화까지 포함한 광범위한 문화와 사회를 중심으로 일본과 일본인을 이해하고 분석하는 시각과 능력을 함양하는 것이 목표이나, 구체적으로는 1)강의와 발표를 통한 지식의 확충과 시각의 개발을 통한 능력 배양, 2)직접적인 체험학습을 통한 감각과 교감의 축적 3)일본 대학생과의 교류프로그램을 통한 서로를 이해하고 우리/나를 설명하는 소통을 통한 입체적이고 글로벌한 감각을 키우는 것을 도모한다.', '{"참조","바람","수강생이","일본","작품","대해서","통해서","번째","등에","이해를","일본문학","작가","본문에","자발적으로","토의를","있도록","하고","아니라","있는","내용을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209205', '영상제작입문', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '이황석', '영제제작과 작법이라는 넓은 영역의 실무를 다루는 교과목의 특성상, 수업 내용은 여러 분야에 걸쳐 있습니다. 이와 같은 이유로 촬영 및 영상 편집은 메토링으로 진행되면 영상스토리텔링 작법은 강의와 토론 수업으로 이원화하여 진행합니다. 본 과목은 영상제 작 분야에서 일하고자 하는 전공자들에게 우선시해야 할 기초적인 지식과 실무능력을 습득하는데 중점을 두고 있습니다. 이는 매우 선행적인 작업이 될 것이며, 영상제작에 처음 접한다는 전제하에 수업이 진행됩니다. 조별과제 수행: 1차 조별과제: 영상문법 매뉴얼 활용 뮤비 제작 2차 조별과제: 바이럴 영상 텍스트 분석 조별 발표 영상 촬영, 편집의 기초적인 실무를 익힘은 물론 영상문법 및 영상언어습득, 영상스토리텔링의 제요소에 대해 분석해 보고 그 작법을 습득하는데 목적이 있다. 구체적인 항목으로 먼저 지식부분에서는 영상문법과 영상언어에 대해 이해할 수 있다 다음으로 기술 파트는 기본촬영실습(조별로 뮤 비형식의 영상문법 매뉴얼 북 제작)과 기본 편집실습을 멘토링수업으로 진행한다. 이와 같은 실무적인 활동을 통해 현장에 바로 사 용할 수 있는 기술을 습득하는데 목표를 둔다. 마지막으로 수업을 통해 미래에 미디어 종사할 인재로서 요구되는 태도를 조별 활동을 통해 슴득하고 자기주도적으로 수행하는 인재를 양성하는데 그 목표를 둔다.', '{"조별","대해","병행한다","영상","분석을","텍스트","교수자가","정리하는","방식의","강의를","바이럴","시도한다","통한","영상문법","영상스토리텔링의","수업을","발표를","수행한다","같은","조별과제"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209627', '디지털미디어의글쓰기', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '고규홍', '목적 - 디지털 시대의 글쓰기 환경의 변화 이해. - 효과적인 글쓰기 방법의 기초 능력 습득. - 기교가 아니라 기초 능력 중시. 개요 - 디지털 미디어를 발표 매체로 설정. - 가능한 모든 장르의 글쓰기 실습. - 디지털 미디어를 통한 컨텐츠 발표의 효과 검토. 디지털시대에 알맞춤한 글쓰기 역량 강화', '{"강의와","글쓰기","글쓰기의","개요","절차","주제","구성","디지털","변화","설정","쓰기","사례","작성","구체적","설명과","묘사","독서","좋은","읽기와","비평"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104507', '일본문예독해', '인문대학', '인문대학', 0, 3, '전선', '서정완', '일본문예독해는 주로 문예 분야와 기타 관련 분야 글을 교재로 삼아 자립적인 일본어 독해 능력을 키우는 것을 목적으로 합니다. 구체적으로는 일본어 원문과 사전이 주어지면 상당한 부분 자력으로 독해 가능한 ''자립적 독해 능력''을 키우는 것을 목적으로 하며, 이 강의는 이를 훈련하고 연습하는 과정입니다. 이러한 목적을 달성하기 위해서는 수강생 스스로의 열의가 필요합니다. 구체적으로는 시험과 성적을 위한 공부를 넘어서 내 능력을 향상시키고 실력을 키우려는 열의가 필요합니다. -일본문예독해는 문학과 예술 분야를 중심으로는 하되, 다양한 글을 대상으로 일본어 원문을 분석하고 그 내용을 음미하고 나아가서 비평까지 할 수 있는 훈련을 위한 과목입니다. -일본학과 (복수)전공자로서 갖추어야 할 일본어 독해능력을 양성하는 과정이며, 여기에는 수강생의 적극적인 태도가 요구됩니다. -단어 중심의 학습에서 벗어나서 글과 가까워지고 글에 담긴 내용을 이해하기 위한 학습법을 지향합니다. -중장기적으로 원문과 사전이 주어지면 번역을 할 수 있는 능력을 키우는 것을 목표로 하며, 여기에는 일본어는 물론이고 국어에 대 한 순발력과 표현력 향상도 포함됩니다.', '{"교재","독해","교수가","질의","학생이","의견을","답하는","사전찾기를","통한","의견","학생의","포함","공유","작문","첨삭","질의응답","일본어","최종","작문과제","부과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209359', '미디어법과윤리', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '최영재', '(이 수업은 <플립러닝> 수업으로, 절대평가로 학점을 부여합니다. 즉, 열심히 하여, 학습 목표를 달성하면 모든 학생이 A학점을 받을 수 있고, 그러기를 기대합니다.) 미디어에 실리는 내용은 파급효과가 상당하기 때문에 언론의 자유만큼이나 언론의 책임도 요구된다. 자칫 부주의한 처신으로 상상할 수도 없을 만큼의 책임을 져야 할 일이 있으므로 미디어 종사자가 되려는 사람은 필히 미디어 관련 법과 윤리를 공부해두어야 한다. 또한 미디어 종사자가 하는 일은 결국 헌법 제21조 표현의 자유를 구현하여 공익을 실현하는 공적 서비스라고 할 수 있는데, 그 과정 에서 정치세력과 자본, 군중의 부당한 자유 억압과 통제 시도, 그리고 돈과 권력, 명예욕에 굴복하도록 하는 환난과 유혹이 끊임없이 발생한다. 이에 대응하여 법치과 민주주의 규범을 준수하고 의롭고 윤리적인 삶을 살아내는 역량을 기르는 것이 미디어 법과 윤리를 공부하는 주요 목적이다. 이 수업은 미디어 종사자가 되려고 하는 사람이 알아 두어야 할 미디어법과 윤리의 내용을 파악하고 응용하는 도움을 주기 위해 개설 한 것이다. 매우 실용적이고 현실적이며, 실질적인 내용을 학습하게 될 것이다 1. 표현과 언론 자유의 중요성과 한계에 대해 이해하고 ‘리걸 마인드(legal mind)’, 윤리의식(ethical conscience) 을 습득한다. 2. 명예훼손, 프라이버시, 저작권, 인공지능 등 커뮤니케이션과 연관된 다양한 법률적 이슈에 대해 탐구한다. 3. 비교법적 관점에서 다른 국가의 미디어 법제와 판례를 살펴보고 이해한다. 4. 전통적인 언론법 뿐만 아니라 디지털, AI 시대의 뉴미디어 관련법에 대해서도 통찰력을 기른다.', '{"미디어","표현의","명예훼손","자유","침해","규제","광고","저작권","한계","언론자유와","이슈","초상권","권리와","제도","개념과","자유와","상업적","허위정보","책임","종사자가"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104509', '일어통번역기초', '인문대학', '인문대학', 0, 3, '전선', '전은정', '-일정 수준의 일본어 학습을 수행한 학습자를 대상으로 통/번역에 필요한 지식과 기술을 교육합니다. -일본어 고급 표현을 비롯하여 한국어와 일본어의 일대일 대응이 아닌 문맥을 이해하고 원문을 정확하게 전달할 수 있도록 합니다. 1. 일본어 능력 향상 2. 번역 기술 체득 3. 통역 기술 체득', '{"번역","통번역","텍스트를","메모리","순차통역","문장구역","일본어","텍스트","기술","체득","중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209576', '디지털영상편집1:', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '이황석', '프리미어를 활용한 영상 편집의 기본 실습과 다양한 매체에 응용된 영상 텍스트를 분석함으로써 영상 제작에 관한 실무 능력과 분석 능력을 배양한다. 이와 같은 과정을 통하여 현재의 디지털 제작 환경의 영상 편집실무에 적극적으로 대처할 수 있는 인재를 양성하고 자 한다. # 본 수업은 온, 오프라인 혼합형 수업으로 개설됩니다. 온라인 수업으론 프리미어 실무를 오푸라인 수업에서는 영상편집의 노하우를 중심으로한 영상텍스트분석 수업을 진행합니다. # 온라인 프리미어 수업의 경우, 온라인의 특성상 학생들이 안일하게 수강할 수 있다는 점이 우려됩니다. 해서 본 교과목의 경우 특 별히 개별 수업마다 매번 복습과제를 수행합니다. 사실 오프라인 강좌에서도 수업마다 수강생들은 제시된 미션을 완수해야 하고, 교 수자가 강의실 현장에서 확인하고 있습니다. 따라서 온라인 수업이라고 더 과제가 많은 것도 아닙니다. 그런데도 수업마다 제시된 미 션을 수행하고 복습과제를 업로드하는 것은 수강생들이나 교수자 모두 신경이 많이 쓰이는 일입니다. 이 점을 숙지하시고 수강을 고 려하시길 바랍니다. 우선 영상편집에 대한 이론 및 실습 영역에서 학생들에게 우선시해야 할 기초적인 부분을 습득하는 데 중점을 두고자 합니다. 이로써 기본적인 컷 편집은 물론, 현장에서 자주 요구되는 모션작업이나 합성작업 등 프리미어를 활용한 다양한 영상표현에 능동적으로 대 처할 수 있는 실무형 인재를 배양하는데 그 목표를 두고 있습니다. 한편, 본 교과목을 성실하게 수강한 학생들은 학기를 마친 후 영상 텍스트를 분석하는 기본적인 원리와 방법을 숙지할 수 있으며, 이 는 곧바로 현장에서 요구되는 레퍼런스 영상을 선별할 수 있는 실무 능력과 연결됩니다.', '{"출결","쪽지","준비된","페이퍼","영상자료","텍스트","영상","성실도","프리미어","관한","분석을","다큐멘터리","활용하여","수행한다","대해","프리미어를","프로젝트","작업","응용","연습한다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104512', '비즈니스일본어', '인문대학', '인문대학', 0, 3, '전선', '황경자', '일본은 한국의 최대 무역 거래국이자 투자대상국이며 한국 또한 일본의 중요한 투자유치국이며 무역 거래국이다.그 중요성이 강조되 고 있는 상황에서 한국과 일본의 거래관습과 시장의 특상을 학습한다.이를 통해 상대국의 시장 및 거래특성을 파악하여 비지니스 마 인드를 고취하는것을 목적으로 한다.또한 비지니스에 필요한 일본어 능력을 높이는 동시에 일본인과 일를 하면서 발생할 수 있는 마찰을 인식하고 해결하는 능력을 양성하는 것을 목적으로 한다. 1.일본어을 실재로 응용하는 커뮤니케이션 능력을 학습함으로써 실제 일본인들의 문화를 이해하는데 도움을 준다. 2.일본어를 실생활에 밀접한 내용으로 실전에 응용할 수 있도록 지도함으로써 장래 일본인과 자연스럽게 대화할 수 있다.', '{"표현을","연습문제","습득한다","주교재","말하기","연습","비즈니스","사내에서","발송하는","거래처","거래처에","문서를","교수","프린트","전화를","작성할때","명함교환","전화대응","사람이","회사를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('104513', '일본경제와동아시', '인문대학', '인문대학', 0, 3, '전선', '김웅기', '본 강의는 일본 경제의 발전 과정을 에도시대 상업자본의 태동부터 현대의 ''잃어버린 30년''까지 통사적(Diachronic)으로 조망하되, 단 순한 역사적 사실의 나열을 지양하고 ''정치경제학적 심층 분석''에 주안점을 둔다. 특히 전후 일본의 경제부흥이 ''냉전(Cold War)''과 '' 미국의 전략적 개입'' 하에 설계된 ''배상 비즈니스(Reparations Business)''였음을 규명하고, 나아가 ''만주국'' 경영모델이 기시 노부스케 등 ''만주 인맥''을 통해 한국의 산업화(청구권자금)에 이식된 과정을 문헌강독을 통해 추적한다. 수강생은 지정된 논문과 1차사료(조약 문, 회고록, 외교문서)를 강독하고 비평문(Critical Review)을 작성하게 될 것이며, 이를 통해 동아시아 경제 질서의 구조적 기원을 파 악하는 것을 목적으로 한다. 일본경제사 및 이와 연관되는 동아시아와의 관계성을 기초 단계부터 이해함으로써 1. 다양한 경제현상이 사람들의 삶을 규정하게 된 점과 2. 근현대 일본의 사회경제가 동아시아 각 지역과 밀접한 관계를 맺어 왔음을 확인하며, 3. 또한 한국을 비롯한 동아시아 국가들 또한 일본의 경제적 선택으로 인해 긍정적 또는 부정적으로 영향을 받아왔으며, 이에 어떻게 대처해 나가고자 했는지 등에 관하여 고찰하고자 한다.', '{"이해하기","대해","토의","일본의","동아시아","교수자의","년대","일본","시사적","문제를","담은","일본경제","기사","경제관계","검토하기","산업화","경제","경제적","근대화","과정에"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209712', '방송미디어론', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '강명현', '현대인에게 방송이란 무엇인가? 본 강의의 목적은 방송이 현대사회에서 차지하는 사회적 의미를 바탕으로 방송의 개념, 방송과 사회 와의 관계, 그리고 수용자로서 방송을 어떻게 이용할 것인가를 모색해 보기 위한 데 있다. 수강생들은 현대 방송과 관련한 다양한 이 슈를 체계적으로 분석함으로써 현대사회에서 차지하는 방송의 본질적 의미를 이해합니다. 또한 방송산업의 현황을 파악함으로써 향 후 방송영상 분야의 진로 설정에 도움이 되는 정보를 제공하게 됩니다. - 방송이 현대 사회에서 차지하는 사회적 영향력을 이해함 - 방송산업의 구조를 파악함으로써 방송영상 분야의 진로를 모색함 - 방송 편성 및 기획에 대한 실무적 능력을 배양함', '{"방송","방송의","방송과","역사","방송산업의","조사","차지하는","편성","방송이","현대사회에서","사회적","의미를","파악함으로써","방송영상","분야의","세계","한국","방송제도와","공영방송","상업방송"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105018', '시사일어와미디어', '인문대학', '인문대학', 0, 3, '전선', '전은정', '미디어 리터러시를 통해 다양한 매체에서 제공되는 정보를 비판적으로 분석하고 올바른 일본어 사용을 판단할 수 있는 능력 향상을 목표로 합니다. 이는 단순한 언어 학습을 넘어 일본어와 일본 사회에 대한 깊은 이해를 도모하여 취업 및 진학 등에 필수적인 역량을 갖추는 데 기여할 것입니다. 1. 미디어 리터러시를 통해 정보의 비판적 분석 및 올바른 언어 사용 판단 능력 향상 2. 잘못된 일본어 사용을 인지하고 이를 수정 및 습득하는 능력 강화 3. 변화하는 미디어 환경 소게서 일본어뿐만아니라 일본 사회를 올바르게 이해하는 능력 증진 4. 취업 및 전문 통번역 교육 진학에 필요한 기초 역량을 함양하여 실무와 학업에 도움이 되는 교육 제공', '{"일본","기사","동일","용어","방식","언론사별","비료","사건에","언론사","선택","표현","현상에","한일","미디어","리터러시를","올바른","일본어","사용을","언어","취업"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209729', 'AI미디어세미나', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '이재길', '본 강의는 인공지능 기술이 작동하는 원리를 이해하고, 인공지능 기술의 확대가 미디어와 콘텐츠에 어떠한 영향을 미치고 있는지 조 감한다. 학생들은 인공지능 기술이 콘텐츠 제작에 활용되는 양상을 살펴보며 인공지능 기술이 미칠 수 있는 다양한 영향에 대해 폭넓게 토의 한다. * 본 수업은 디지털미디어콘텐츠개론 (2023년 1학기), 인공지능미디어세미나(2024년 1학기) 수업과 동일한 수업입니다. 본 강의는 인공지능 기술이 작동하는 원리를 이해하고, 인공지능 기술의 확대가 미디어와 콘텐츠에 어떠한 영향을 미치고 있는지 조 감한다. 학생들은 인공지능 기술이 콘텐츠 제작에 활용되는 양상을 살펴보며 인공지능 기술이 미칠 수 있는 다양한 영향에 대해 폭넓 게 토의한다.', '{"인공지능","기술이","기술의","활용되는","작동하는","원리를","양상을","대해","살펴보고","살펴본다","미디어","알고리즘으로","가능한","한계점에","콘텐츠를","제작하는데","이해한다","인공지능과","학기","강의는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105019', '일본지역의이해', '인문대학', '인문대학', 0, 3, '전선', '김웅기', '본 강의는 일종의 ''일본 지역 전문 컨설팅 펌(Firm)''으로 전환하여 운영할 것이다. 일본을 단일한 국가가 아닌, 47개 도도부현(都道府縣)의 다양한 욕망과 이해관계가 충돌하는 다층적 공간으로 파악하고, ''로컬리티(Locality)의 정치경제학'' 관점에서 ''도쿄 일극 집중''과 ''지방 소멸''의 구조적 원인을 심층 진단한다. 수업 운영에 있어 담당 교수는 인구 감소와 재정난 등 난제에 봉착한 지자체의 ''클라이언트'' 역할을, 수강생은 데이터에 기반해 해결 책을 제안하는 ''주니어 컨설턴트'' 역할을 수행한다. 단순 지식 암기는 생성형 AI에게 맡긴다. 대신 수강생은 일본 내각부의 RESAS(지 역경제분석시스템) 빅데이터와 AI를 조력자(Co-pilot)로 활용하여, 검색으로는 알 수 없는 현장의 ''진짜 문제(Deep Context)''를 발굴하 고 실질적인 해결책(Action Plan)을 도출하는 통찰력을 기르게 될 것이다. 나아가 오키나와 기지 문제, 재일코리안 집거지 등 특수 지역의 심층 이슈를 탐구하고, *일본자치체국제화협회(CLAIR)와의 연계를 통 해 일본 지자체 공무원 및 JET 프로그램 등 관련 분야로의 진로를 구체적으로 모색한다. (*섭외 가능 시) [지식] 일본의 지정학적 다양성과 중앙(도쿄)-지방 간의 예산 및 권력 갈등 구조(3할 자치, 고향세 등)를 설명할 수 있다. [분석] RESAS(지역경제분석시스템) 등 공공 빅데이터를 활용하여 특정 지자체의 인구 유출, 산업 구조, 재정 현황을 정량적으로 분석 하고 시각화할 수 있다. [창의/기획] 소멸 위기 지역의 특성(Locality)을 고려한 실효성 있는 ''지역 재생 정책''을 기획하고 예산안이 포함된 제안서를 작성할 수 있다. [진로설계] 일본 지자체의 현장 행정을 이해하고, 국제교류원(CIR) 등 일본 지역 사회 전문가로서의 진로 포트폴리오를 구축한다.', '{"자료","일본","지역","데이터","담당","지자체","오사카","오키나와","도시","기지","비교","도쿄","지방","소멸","인구","지자체의","이해한다","성공","재정","프로그램"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105109', '초급러시아어회화', '인문대학', '인문대학', 0, 3, '전선', '이리아', '본 강의는 러시아로 가는 길 1 단계 교재를 바탕으로 초급 학습자가 기초적인 러시아어 회화 능력을 습득할 수 있도록 설계되었습니 다. 학생들은 다음과 같은 목표를 달성할 수 있습니다: 평가 방식: 출석 10%, 과제 10%, 쪽지 시험 20% 중간고사 30%, 기말고사 30% 수업 방식: 롤플레이, 듣기 및 말하기 연습, 그룹 활동 1. 러시아어 기초 문자 및 발음 습득 o 키릴 문자(알파벳)를 익히고 올바른 발음을 연습한다. o 러시아어의 강세와 억양 규칙을 이해한다. 2. 일상 생활에서 사용되는 기본 회화 표현 습득 o 인사, 자기소개, 가족 소개, 국적 및 직업 표현하기 o 시간과 날짜 말하기, 길 찾기, 쇼핑, 식당 주문 등 실생활에서 자주 사용하는 표현 학습 3. 러시아어 기초 문법 및 문장 구조 익히기 o 명사 성(남성, 여성, 중성)과 변화형 이해 o 기본 동사 변형과 시제(현재, 과거, 미래) 활용 o 기본적인 문장 구조(주어+동사+목적어)를 익히고 간단한 문장을 만들 수 있도록 연습 4. 듣기 및 말하기 능력 향상 o 러시아어 기본 표현을 듣고 이해할 수 있도록 훈련 o 간단한 질문과 대답을 자연스럽게 할 수 있도록 연습 o 상황별 롤플레이를 통해 실제 회화에서 사용할 수 있는 능력 강화 5. 러시아 문화 이해 및 응용 능력 기르기 2. 교과 목표 ■ 교과목표 o 러시아의 기본적인 문화, 예절, 생활 방식 학습 o 러시아인의 인사법, 식사 예절, 축제 등 문화적 배경을 반영한 회화 연습 수업이 끝난 후 학생들은 간단한 러시아어 회화를 할 수 있으며, 러시아에서 기본적인 의사소통을 원활하게 할 수 있는 수준에 도달 하게 됩니다.', '{"교과서","Урок","러시아어","쪽지","있도록","연습","회화","방식","중간고사","말하기","기본적인","간단한","학생들은","듣기","문자","익히고","표현","문장","구조","동사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209902', '커뮤니케이션개론', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '정지영', '커뮤니케이션은 인류와 사회 발전의 근간이다. 그리고 현대 사회의 커뮤니케이션은 전적으로 미디어를 기반으로 이루어진다. 개인과 사회의 모든 영역이 미디어를 중심으로 양상을 달리하며 발전해나가고 있다. 그렇다면 우리는 커뮤니케이션, 미디어에 대해서 얼마나 알고 있을까, 얼만큼 알아야 할까. 본 강의는 커뮤니케이션과 미디어의 기본 개념에서 출발하여 커뮤니케이션 연구와 효과이론, 저널 리즘과 방송에 대한 이해 등을 두루 살펴본다. 이를 통해 미디어로 살아가는 우리 개인과 사회의 모습을 학술적으로 이해하고 전문적 인 식견을 키우도록 한다. 그리고 과제를 통해 우리의 미디어 이용 행태를 고찰하고 지금 우리 사회에서 중요한 미디어 관련 이슈에 대한 비판적 이해를 키우도록 한다. 본 강의는 미디어 학문의 기본적인 이해를 높이고자 한다. 이를 위해서 커뮤니케이션과 미디어에 대한 개념, 이론, 관점 등을 숙지하 고 미디어를 기반으로 이루어지는 개인의 일상과 사회의 현상에 대한 비판적 시각을 함양하도록 한다. 또 다양한 미디어 관련 분야에 대한 지식을 쌓으며 스스로 각자의 세부적인 관심 분야를 탐색해나갈 수 있도록 한다.', '{"프로젝트","미디어","커뮤니케이션","안내","효과","주제","논의","한다","퀴즈","사회의","미디어에","매스","매스미디어","개인과제","환경의","변화와","발달","미디어를","커뮤니케이션과","방송에"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209911', 'AI활용지역언론콘텐츠', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '최영재', '<AI를 활용하여 지역 언론의 뉴스콘텐츠 제작 문제를 해결해 보는 수업> * 이 수업은 지역 문제해결형 수업으로, 절대평가로 학점을 부여합니다. (열심히 한 만큼 모든 학생이 A학점을 받을 수 있기를 기대합 니다) - 이 수업은 강원일보 등 지역언론에 ‘AI 저널리즘 리빙랩’을 설치하고 리빙랩에 교수와 학생, 기자들이 참여하여, 1) AI활용한 기사, 사진, 그랙픽을 생산하여 지면에 반영하는 실험을 수행합니다. - 이 수업은 미디어스쿨, AI융합연구원, 강원일보 등 지역언론과 협력 체제로 진행됩니다. - 프로젝트 결과물은 강원일보 등 지역언론의 기사, 그래픽, 동영상 등 언론 콘텐츠 형태, 그리고 AI 저널리즘 실습 수업 모델 창출로 나타나 지역언론과 지역대학 교육 발전을 위해 활용될 것입니다. - AI 활용한 뉴스 콘텐츠 제작 프로젝트 수행 역량 체득 - AI 저널리즘, AI 리터러시에 대한 전문적인 식견 함양', '{"제작","언론","기사","콘텐츠","연구주제","저널리즘","그래픽","동영상","지역언론","프로젝트","조사","수업은","강원일보","지역","학점을","활용한","지역언론과","발견하기","저널리즘과","정하기"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105111', '러시아문화', '인문대학', '인문대학', 0, 3, '전선', '박혜경', '이 수업은 러시아 지리, 역사, 정치, 경제, 종교 등 러시아에 관한 다양하면서도 전반적인 지식을 습득하게 하는 데 목적이 있다. 각 주 제별로 러시아적 특수성과 상황을 살펴봄으로써 학생들은 러시아에 관한 개략적이지만 폭넓은 지식을 습득할 수 있을 것이다. 이 수 업은 학생들이 이후 주제별 심화학습을 하는 데 도움이 될 것이며, 향후 전공과 관련된 본인의 관심사와 진로를 모색해 볼 수 있을 것 이다. 또한 한림대학교 인문사회융합인재양성사업에서 요구하는 융합인재로 성장할 수 있도록 한다. 본 교과는 러시학과 학생들이 졸업 후 진로를 탐색하고 준비하는 과정에서 자신의 적성과 관심을 확인하고 진로를 결정하는 데 도움 을 주는 것을 목표로 한다. 유사한 관심을 공유한 학생들이 함께 조별 과제를 준비함으로써 진로 준비를 위한 더 풍부하고 자세한 자 료들을 공유하고 협업의 자세를 배울 수 있다.', '{"러시아","교수의","학생들의","역사","경제","러시아의","세기","민족","소비에트","고려인","정교","민속","지리","정치","러시아에","관한","학생들이","진로를","지식을","하는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300006', '미디어스토리텔링이다', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '송현주', '모든 미디어 콘텐츠는 스토리를 담고 있다. 미디어 콘텐츠 자체가 곧 미디어스토리텔링이다. 이 강의는 미디어 스토리를 기획하고 제 작하는 능력을 배양하기 위해 개설됐다. 수강생들은 다양한 미디어의 양식과 콘텐츠의 유형 등에 공통적으로 적용 가능한 미디어 스 토리텔링 기법을 학습한다. 1. 미디어 스토리텔링 기법에 대한 이해 2. 미디어 스토리텔링 기법을 적용한 미디어 스토리 분석 3. 미디어 스토리 기획과 제작을 위한 기초 역량 배양', '{"첨부된","강의계획서","참고","미디어","스토리를","기법을","스토리텔링","스토리","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105205', '중급러시아어회화', '인문대학', '인문대학', 0, 3, '전선', '이리아', '과목명: 중급 러시아어 회화 수업 대상: 초급 과정 수료자 또는 기본적인 러시아어 문법과 어휘를 익힌 학습자 교재: 러시아로 가는 길 2 단계, 중급 러시아어 회화 교재 + 보충 자료 제공 수업 목표 실생활 회화 능력 향상 ？ 자연스럽게 러시아어로 의사소통 복잡한 문장 표현 익히기 ？ 다양한 문법 구조 활용 러시아 문화와 사회 이해 ？ 러시아어권 국가의 생활 방식 습득 듣기, 말하기, 읽기, 쓰기 균형 학습 ？ 실전 활용 능력 강화 본 교과는 중급 수준의 러시아어 회화를 익히고 실생활에서 자연스럽게 사용할 수 있도록 돕는 것을 목표로 합니다. 이 교과 목표를 통해 학생들은 단순한 문장 암기에서 벗어나, 자연스럽고 유창한 러시아어 회화 능력을 갖춘 실력자로 성장할 수 있도록 합니다. 이를 위해 지식, 기술, 태도 측면에서 다음과 같은 목표를 설정합니다.', '{"교과서","자료","표현","조격","전치격","러시아어","회화","대격","생격","여격","중급","교재","자연스럽게","문장","있도록","합니다","목표를","시간의","소유의","중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300010', '디지털영상편집2:', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '이황석', '영상편집 2: 애프터 이펙트, 본 강좌는 어도비 애프터 이펙트 실무 교육에 중점을 둔다. 애프터 이펙트 기본 인터페이스의 이해부터 모션애니메이션,특수효과, 타이포 그래픽 작업에 이르기까지, 기초에서 시작하여 실무에 응용할 수 있는 수준을 목표로 한 학기 동안 임펙트있게 실습수업 위주의 교육이 수행된다. 애프터 이펙트를 활용한 기초적인 영상효과의 기본 실습을 통해 실무 능력과 분석능력을 배양시킨다. 이러한 과정을 통하여 현재의 디지털 제작 환경의 영상제작실무에 적극적으로 대처할 수 있는 예비인력을 양성하고자 한다.', '{"테크닉","애프터","특수효과","애프터이펙트","마스터","모션","키프레임","애니메이션","마스크","레이어","타이포응용","이펙트","인터페이스의","있는","기본인터페이스의","에프터이펙트","이ㅔㄱ트","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105221', '러시아사입문', '인문대학', '인문대학', 0, 3, '전선', '이광태', '본 강좌는 러시아의 역사 전개를 파악함으로써 러시아가 갖는 세계사적 위치를 가늠하는 데 그 목적을 둔다. 러시아는 세계사의 측 면에서 매우 중요한 국가이다. 서양사의 경우 유럽 문명의 중심지가 지중해에서 대서양 지역으로 이동하면서 상대적으로 동유럽을 기반으로 하는 슬라브 문명의 발전이 대서양 문명과 균형 관계를 이뤄왔다. 동양사의 경우 몽골 제국의 러시아 지배와 함께 러시아와 아시아 사이 장벽이 허물어지고 오히려 러시아의 북아시아 진출의 문호가 개방되는 효과를 낳았다. 러시아는 해양 세력 이외 아시아 의 유럽 접촉의 또 다른 통로로 작용해왔다. 이러한 러시아 갖는 역사적 중요성은 우리나라도 예외가 아니다. 구한말과 일제 강점기, 그리고 한국전쟁과 그 이후에 이르기까지 러시아가 한반도에 미친 영향력은 그 이전 시기 중국의 그것에 필적할만하다고 해도 과언이 아니다. 이러한 실제적 영향력에도 불구 하고 많은 경우 러시아에 대한 전반적인 무지와 편견이 우리가 처한 현 상황을 제대로 파악하지 못하는 원인 가운데 하나로 작용하고 있다고 할 수 있다. 본 강좌는 근현대사 이전 시기 러시아 전통 사회의 역사적 전개를 파악함으로써 러시아에 대한 기본적 이해의 향 상을 도모한다. 또한 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에서 요구하는 융합인재상에 도달하는 것을 목적으로 한다. ● 키예프 루시로부터 19세기 초에 이르기까지 러시아의 역사 전개 발전 및 작동 기제를 이해한다. ● 세계사 속 러시아가 차지하는 비중과 의의를 이해한다. ● 러시아와 아시아 간 역사적 상호 영향 관계를 파악한다.', '{"강의와","자료","러시아","루시의","몽골","러시아의","모스크바","공국의","세의","시대","표트르","역사적","키예프","발전과","몽골의","타타르의","멍에","이반","개혁","중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105411', '러시아문학개론', '인문대학', '인문대학', 0, 3, '전선', '박혜경', '러시아 근현대 문학은 세계 문학사에서 매우 중요한 의미를 가지고 있다. 유럽 문학의 변방에서 시작해 19세기에는 세계 문학사에서 가장 위대한 작가들을 배출하였으며, 20세기 소비에트 문학 역시 문학의 새로운 영역을 열어놓았기 때문이다. 본 강의는 러시아 문학 작품을 직접 읽어봄으로써 러시아 문학의 풍부한 유산을 직접 경험하는 데 목적이 있다. 세계 문학사에서 중요한 부분을 차지했던 1 9세기와 20세기 러시아의 대표적인 작가들과 그들의 주요 작품을 중심으로 러시아의 역사, 지성사와 연관시켜 살펴봄으로써 러시아 인들의 정신세계, 풍부한 예술적 역량을 배울 수 있다. 19세기는 러시아 문학이 독창성과 자주성을 획득하고 유럽 문학계를 주도했던 시기로서 매우 중요한 작가와 작품들을 배출했으며, 20세기는 다양한 문학적 실험을 반영한 흥미로운 작품들을 탄생시킨 시대로서, 이러한 점들에 주목하여 작품을 읽고 분석해 나갈 것이다. 러시아 문학은 방대한 분량, 장황한 문체, 형이상학적 주제 등으로 이해하기 어렵다는 평가를 받고 있다. 본 교과에서는 러시아 문화 사와 지성사에 대한 지식을 바탕으로 개별 작가와 작품을 분석함으로써 러시아문학의 깊이와 의미를 이해하는 데 목표가 있다. 이 수 업을 통해 학생들은 철학적, 형이상학적 주제가 문학 작품을 통해 어떻게 구현되는 지 배울 수 있으며, 깊은 독서를 함으로써 사고와 지성의 깊이가 깊어지는 것을 경험하게 될 것이다. 또한 논리적이고 창의적인 글쓰기도 배울 수 있을 것이다.', '{"러시아","문학","세계","세기","작품","사실주의","사실주의의","도스토예프스키","파스테르나크","있다","문학의","위대한","소비에트","작품을","유럽","문학사","전기","대표적","작가","고골의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300019', '한류문화산업의이해', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '노광우', '이 수업을 통해 강의 참여자들이 최근 한류 현상과 이와 관련된 문화 산업의 특성, 그리고 관련된 이론과 학술적 개념을 이해한다. 학 기 초에는 한류의 역사적 전개, 장르, 이해를 위한 학술적 개념을 익히고, 학기말에는 케이팝과 팬덤, 그리고 그와 관련된 문화, 기술, 산업적 쟁점을 조별 발표를 통해 파악한다. 이 과목을 통해 강의참여자는 문화산업의 특성을 이해하게 된다. 이를 통해 문화산업계, 특히 한류 관련 업계로 진출할 경우, 한류가 국제적 현상임과 동시에 문화콘텐츠를 생산하는 이들이 이해하면 좋은 기술적, 산업적 환경에 관한 지식을 미리 파악한다.', '{"관해","문화","조별","중간과제","이해한다","학술적","관람","또는","관광","아이돌","한류의","발표를","소재","한국","영화","파악하는","작성한다","한류와","스크린","케이팝"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300043', 'AI와미디어리터러시', '미디어스쿨', '미디어스쿨', 0, 3, '공통전선', '최영재', 'This course examines artificial intelligence (AI) both as an evolving technology and as a medium of communication and culture. We will analyze how AI systems work and how they transform the way we read, write, create, communicate, and verify informatio n. Students will learn the core concepts and mechanisms behind modern AI systems and develop hands-on AI usage skills to enh ance their learning and research. At the same time, we critically explore AI’s positive contributions and its potential harms (such a s bias and misinformation), along with strategies to mitigate these issues. By the end of the course, students will be able to use AI tools effectively, think critically about AI-generated content, and understand the broader societal impacts of AI. By the end of the semester, students will be equipped not only to use AI effectively and ethically but also to question its influence on truth, cre ativity, and democracy in the digital age. [For Your Information] This course is designated as a Flipped Learning course, where Grades will be assigned based on an absolute evaluation system, n ot a relative grading curve. In other words, if all students work diligently and meet the course objectives, it is possible for everyo ne to receive an A grade. In addition, both the instructor and students will have access to AI-powered tutors and teaching assistants developed by Hallym University, which provide support and guidance throughout the course. 이 수업은 인공지능(AI)을 진화하는 기술이자 소통과 문화의 매체로서 함께 탐구한다. 본 수업에서는 AI 시스템이 어떻게 작동하는지 를 분석하고, 그것이 우리가 읽고, 쓰고, 창작하고, 소통하며, 정보를 검증하는 방식에 어떤 변화를 가져오는지를 살펴본다. 학생들은 현대 AI 시스템의 핵심 개념과 작동 메커니즘을 이해하고, 학습과 연구를 향상시키기 위한 실천적 AI 활용 역량을 기르게 된다. 동시에, AI가 제공하는 긍정적 기여뿐 아니라 편향, 허위정보와 같은 잠재적 위험을 비판적으로 검토하고, 이러한 문제를 완화하기 위 한 전략도 함께 탐구한다. 수업을 마칠 무렵 학생들은 AI 도구를 효과적으로 활용할 수 있을 뿐 아니라, AI가 생성한 콘텐츠를 비판적 으로 평가하고, AI가 사회 전반에 미치는 영향을 이해할 수 있게 된다. 더 나아가 학기 말에는 AI를 효과적이고 윤리적으로 사용하는 능력뿐만 아니라, 디지털 시대에 진실, 창의성, 민주주의에 미치는 AI의 영향을 질문하고 성찰할 수 있는 역량을 갖추게 될 것이다. [참고 사항] 본 수업은 플립드 러닝(Flipped Learning)으로 지정된 수업이며, 성적은 상대평가가 아닌 절대평가 방식으로 부여된다. 즉, 수강생 모 두가 성실히 학습하고 수업 목표를 달성할 경우, 모든 학생이 A학점을 받을 수 있다. 또한 본 수업은 ''AI활용 지정 수업''으로, 한림대학교에서 개발한 AI 튜터 및 AI 조교 시스템을 활용하며, 이를 통해 교수자와 수강생 모두가 수업 전반에서 AI의 지원과 도움을 받을 수 있다. Course Objectives 1. Understand core concepts and functions of AI and generative AI. 2. Apply AI tools responsibly in writing, media production, and research. 3. Evaluate AI outputs for accuracy, bias, and ethics. 4. Explore AI’s social, cultural, and policy implications. Learning Outcomes 1. Explain how modern (gen)AI systems work & where they fail. 2. Apply AI tools ethically for writing, analysis, and media production with full disclosure. 3. Evaluate outputs for accuracy, bias, provenance, and safety using checklists. 4. Analyze societal, policy, and newsroom implications using current evidence.', '{"주차","구성요소","수업은","아니라","으로","함께","탐구한다","학생들은","역량을","된다","미치는","영향을","수강생","받을","있다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105436', '러시아정치경제론', '인문대학', '인문대학', 0, 3, '전선', '원석범', '이 수업은 현대 러시아의 정치와 경제를 전반적으로 이해해 보는 것을 목표로 한다. 러시아의 역사적 배경과 제도적 특징을 바탕으로 , 오늘날 러시아 사회가 어떤 방식으로 운영되고 있는지를 살펴본다. 강의에서는 정치 구조와 권력 운영, 주요 정책 방향, 경제 구조와 산업의 특징, 대외 관계의 흐름을 사례 중심으로 다룬다. 이를 통해 수강생들이 현대 러시아의 현실을 보다 구체적으로 이해할 수 있도록 돕는다. 본 수업은 러시아 사회의 전반적인 모습과 정치·경제의 큰 흐름을 부담 없이 파악하도록 구성된 개관형 강의이다. 본 교과목은 러시아의 정치와 경제가 전반적으로 어떻게 운영되고 있는지를 이해하는 것을 목표로 한다. 러시아의 정치체제와 경제 구조, 주요 정책과 대외 관계를 살펴보며, 현대 러시아의 현실을 균형 있게 바라볼 수 있는 기본적인 이해 와 판단 능력을 기른다.', '{"러시아","요약문","이해한다","권력","구조","정치","관계","구조적","구조와","제정","특징을","운영","러시아의","경제","국가","소련","연방","정치적","방식을","방식"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209304', '한국언론사', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '최영재', '(이 수업은 <플립러닝> 수업으로, 절대평가로 학점을 부여합니다. 즉, 열심히 하여, 학습 목표를 달성하면 모든 학생이 A학점을 받을 수 있고, 그러기를 기대합니다.) 이 수업은 ‘가장 재미있고 유익한 한국 언론사 수업’을 지향합니다.. 영국의 역사학자, E.H. Carr는 “역사란 현재와 과거 사이의 끊임없는 대화”라고 했다. 이 수업은 현재 한국 언론의 문제에 대해 과거 언론역사에게 말을 걸어보고 대화를 나눠 보는 시도이다. 우리는 과거 언론역사와 대 화하면서 현재의 언론을 배우고, 또한 현재 언론에 비추어 과거 언론역사를 생생하게 살아 있는 것으로 배우게 될 것이다. 첫째, 이 수업은 현재 한국 언론의 미덕과 문제의 근원을 과거 언론역사에서 찾는 작업을 수행한다. 이를 통해 현재 한국 언론의 문제 를 역사적 맥락에서 이해함으로써 보다 근본적인 문제해결 방법을 모색할 수 있기를 기대한다. 또한 과거 한국 언론 역사를 보다 진 실에 가깝게 이해하고 해석할 수 있게 되기를 기대한다. 둘째, 이 수업은 모든 것을 스토리텔링, ‘서사의 힘’으로 이끌어 간다. 개화기부터 최근 유투브 SNS 환경까지 한국언론의 역사를 화석 같은 지식이 아니라 살아있는 이야기로 이해하고 각 시기의 한국 언론사가 지금의 한국 사회와 한국 사람들, 그리고 내 자신에게 어 떤 영향을 미쳤는지 생각해 보고, 그 생각을 새로운 스토리로 만들어 본다. 이 수업에서 생성되는 ‘한국언론사 스토리텔링’은 우리의 말과 글, 콘텐츠 제작에 요긴하게 활용되고, 또한 다른 종류의 스토리텔링과 융합하여 새로운 스토리텔링을 창출하게 되기를 기대한 다. 이 수업은 흥미진진하고 매우 실용적일 것이다. 현재의 한국언론의 문제를 과거의 사례에서 찾아 분석하고 스토리텔링으로 풀어보는 재미를 느끼게 되기를 기대한다. <교과목표> 1. 현재 한국 언론 문제에 비추어 과거 언론 역사 이해하고 나의 한국언론사 지식 쌓기 2. 언론사적 맥락에서 현재 한국언론의 문제해결 방법 찾아 보기 3. 한국언론사와 한국언론의 문제해결에 관한 ‘한국언론사 스토리텔링’ 능력 기르기 이 수업을 성공적으로 마친 학생은 “한국언론사 공부가 나에게 어떤 영향을 주었는가”에 대한 긍정적이고 실질적인 답변을 할 수 있 을 것이다. 2. 교과 목표 ■ 교과목표 (E.H. Carr는 케임브리지 대학교의 한 역사학 수업에서 "페르시아 전쟁의 집필이 헤로도토스에게 어떤 영향을 주었는가"라는 색다른 시선에 감명을 받고, 역사철학에 대한 고민을 시작했다)', '{"언론","한국","언론의","나에게","과거","현재","한국언론의","역사가","오늘날","언론과","영향은","수업은","한국언론사","개화기","민주주의","기원과","한국언론","미치는","무엇인","무엇인가"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209370', 'AI스튜디오사진', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '조상미', 'AI스튜디오 사진은 사진의 본질인 빛을 이해하면서 AI를 창의적 도구로 활용하는 능력을 기르는데 초점을 맞춥니다. 스튜디오 조명의 물리적 원리(광학)를이해하고 구현하며, 촬영된 원본 소스를 AI로 분석하고 확장하여 AI하이브리드 스튜디오사진의 워크플로우를 익힙니다. 이 수업은 스튜디오사진의 입문자를 위한 기초수업입니다. 빛을 읽어내고 빛을 활용하며 라이팅의 기본을 익힙니다. 입문자 수업이기에 매우 기초적인 조명의 종류, 효과와 사용법, 조명악세서리들을 천천히 알아갑니다. 그와 더불어 소소한 제품촬영부터 (뷰티촬영과 프로필촬영을 통한) 인물촬영까지 스스로 빛을 창조해내는 전문가로서의 능력을 습 득할 수 있습니다. 촬영된 원본 소스를 가지고 AI로 분석하고 확장하는 하이브리드 워크플로우를 익힙니다. 기술적 제약을 넘어선 창의적인 미디어 컨텐츠 제작 역량을 확보할 수 있습니다.', '{"프린트","체크","과제및","조명","가상세트","사용법","촬영실습","스튜디오","악세서리","컨트롤","스튜디오조명","촬영노트","오브제촬영","확장","창의력","구현","리플렉터","프롬프트","빛을","소프트박스"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105441', '러시아와동양', '인문대학', '인문대학', 0, 3, '전선', '원석범', '본 강의는 러시아와 동양의 관계를 중심으로 러시아의 역사, 문화, 사회, 공간적 특성을 폭넓게 이해하는 것을 목표로 하는 개관형 수 업이다. 러시아 문명 속에 형성되어 온 동양적 요소를 생활문화, 종교와 세계관, 예술과 문학, 시베리아와 아시아 지역, 그리고 현대 국제관계 의 맥락에서 살펴본다. 강의에서는 지도와 도시, 문화와 지역 사례를 활용하여 러시아의 동양적 면모를 구체적으로 살펴보고, 이를 통해 러시아 사회와 문명 의 성격을 보다 쉽게 이해하도록 돕는다. 본 수업은 러시아를 다층적인 역사와 문화를 지닌 사회로 인식하고, 현실적인 관점에서 바라볼 수 있는 시각을 제공한다. 본 교과목은 러시아 문명과 사회를 동양과의 관계 속에서 이해하는 것을 목표로 한다. 러시아의 역사, 문화, 종교, 예술, 지역과 도시, 그리고 아시아 국가들과의 관계를 살펴보며, 러시아가 유럽과 동양이 만나는 공간에서 형성된 복합적 문명임을 이해한다. 이를 통해 수강생들이 러시아와 동양에 대한 고정관념을 넘어, 러시아를 보다 넓고 입체적인 시각에서 바라볼 수 있도록 한다.', '{"이해한다","요약문","러시아","러시아의","동양적","관계를","역사","아시아","시베리아","협력","러시아와","속에","국가들과의","중앙아시아","유라시아","나타난","동양성","특징을","이슬람","시베리아의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209378', '뉴스작성기초1', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '심훈', '인쇄 매체의 뉴스 제작에 있어 가장 기본이 되는 스트레이트 기사 작성은 언론사를 지망하는 예비 언론인들이 가장 먼저 익혀야 하는 대상이다. 본 강의에서는 스트레이트 기사 작성에 대한 학생들의 이해를 전반적으로 높이는 차원에서 방문, 동정, 부음, 연설/강연, 사고, 범죄 등 다양한 소재에 대한 단문 기사 작성법에 대해 학습하는 것을 목표로 삼는다. ‘취재 보도 문장 연습 I’에서는 먼저 간략하게 뉴스에 관한 배경 지식을 전달한 다음, 뉴스 작성의 근간이 되는 맞춤법에서부터, 띄어 쓰기, 엉터리 문장 죽이기, 문장 부호 사용법 등을 거쳐 기사 작성의 ABC에 속하는 인사, 동정, 부음, 방문 기사는 물론, 사건, 사고 등 에 이르기까지 차근차근 기사 작성법에 대해 배우게 된다.', '{"기사","사고","살인","방문","동정","부음","교통","화재","강도","연설","부고","취재","문장","뉴스","가장","되는","스트레이트","먼저","작성법에","대해"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209373', '보도사진', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '조상미', '사진매체의 기초적인 지식을 이해를 바탕으로 특히 보도사진에 대한 집중적 이해를 도모합니다. 이론적인 내용보다는 실기 위주의 수업으로 사진촬영과 보도에 관련된 기술적인 내용과 촬영능력을 향상시킵니다.그와 더불어 보돠 진의 사회적 의미 생산과정에대한 이해 , 윤리적 측면 등 다양한 측면에서 접근합니다. 카메라의 기초적인 부분인 캐논6d로 진행하지만, 개별촬영에는 주로 스마트폰과 개별카메라를 사용할 예정입니다. 개별카메라(DSLR 혹은 미러리스)를 가지고 있다면 지참하여 수업에 참가하면 좋습니다. 보도사진 수업을 통하여 사진이라는 매체가 사회속에서 어떻게 작용하는지 이해하고 기술적인 측면에서는 사진자체를 습득하고 카 메라의 기술적인 능력을 향상시킵니다. 사진 전체 범위를 다루기보다는 "보도사진"이라는 특정분야를 중심으로 진행되는 수업은 그 목적에 맞게 촬영능력을 확보합니다. 카메라의 기초적인 부분인 캐논6d로 진행하지만, 개별촬영에는 주로 스마트폰과 개별카메라를 사용할 예정입니다. (스마트폰의 수동모드 촬영능력확대할 예정) 개별카메라(DSLR 혹은 미러리스)를 가지고 있다면 지참하여 수업에 참가하면 좋습니다.', '{"보도사진으로서의","촬영방식","촬영기법","촬영과제","역할과","사용결과에","카메라의","카메라소개","카메라","사용법에","기초적인","기술적인","스마트폰의","수동모드","이해를","촬영능력을","향상시킵니다","부분인","캐논","진행하지만"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105442', '초급러시아어실습', '인문대학', '인문대학', 0, 4, '전선', '홍택규', '- 교과과정 개편 전 “초급러시아어1” 강좌와 “러시아어실습1” 강좌에서 다루던 내용을 함께 통합하여 다루는 강좌. 3시수의 이론 수 업과 2시수의 실습 시간으로 이루어짐. - 이론 수업 3시간 동안은 러시아어를 처음 접하는 학생들을 대상으로 초급 수준의 러시아어 문법을 가르치는 시간이며, 실습 2시간 은 이론 시간에 배운 문법 내용을 계속 반복 적용함으로써 러시아어 발음, 음절구조, 억양, 어휘, 문장표현 등이 학습자의 ‘몸에 붙도 록’ 집중. - 러시아어는 한국어와는 형태적으로, 언어유형론적으로 너무나도 다른 언어이므로, 문법과 형태구조에 대한 체계적 학습이 선행되 어야 하고, 또 이를 바탕으로 발음, 억양, 듣기, 말하기와 같은 언어학습의 실제적인 측면도 같이 병행되어야 하는바, 이렇게 이론수업 과 실습수업을 한 강좌로 묶어 학습하는 것이 가장 효과적. - 러시아어 문법을 다루는 이론 수업 3시간은 전임교수(홍택규)가, 실습 2시간은 강사선생님이 담당. 러시아어를 처음 배우는 학생들 이 잘 따라올 수 있도록 수업시간에 배운 내용을 계속 점검하고, 반복하는 식의 수업이 될 것임. - 초급 수준 러시아어 문법의 체계적인 학습과 더불어, 발음, 억양, 작문, 듣기, 말하기 등 실제적인 언어학습에 필요한 제 분야를 ‘몸 으로 습득하는’ 것을 목표로 함. - 러시아어 초급문법은 일 년에 걸쳐 완성되는 만큼, 1학기 강좌인 “초급러시아어실습1”에서는 그 절반에 해당하는 분량을 다룸(명사, 형용사의 격 표현, 동사의 현재, 과거, 미래시제, 완료상/불완료상, 소유 및 시간 표현). - 하지만, 러시아어는 한국어와는 전혀 다른 유형의 언어인 만큼 처음에 언어학습의 기초를 세우는 문법을 제대로 소화하는 것이 매 우 중요한 까닭에, 특별히 1학기 강좌에서는 이 점에 집중할 것임. 지식: 초급 수준의 러시아어 지식을 습득한다. 기술: 초급 수준의 러시아어 읽기과 듣기, 말하기와 작문을 할 수 있다. 태도: 꾸준하고도 성실한 자세로 인내심을 가지고 배운다.', '{"러시아어","주교재와","자료","본과","있다","표현","시간","형용사의","동사현재시제","습득해","구현할","동사","만들","문장","속에서","명사","초급","억양","변화를","변화형"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209374', 'TV뉴스와영상저널', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '전영재', '현대 사회는 방송뉴스와 유튜브 콘텐츠의 영향력이 점점 커지고 있다. 스토리텔링(storytelling)이 강조되는 디지털미디어 지형에서 사실(fact)을 다루는 저널리즘의 입지는 무한 경쟁시대를 맞고 있다. 방송뉴스는 여전히 경쟁력이 뛰어난 콘텐츠이다. 특히 TV뉴스는 제작 측면에서 완성도가 가장 높은 콘탠츠로 그 영향력과 파괴력은 강하다. 이 강의는 방송기자나 신문기자를 꿈꾸는 학생들에게 어떻게 하면 텔레비전 뉴스 기사를 잘 쓸 수 있을까, 어떻게 하면 전달력 높은 텔레비전 뉴스와 유튜브 콘텐츠를 잘 만들 수 있을까를 기초부터 가르친다. 특히 지난 33년동안 각종 사건사고는 물론 강원도청을 비롯해 교육청,강원지방경찰청, 춘천지검과 법원 등을 출입하며 취재 현장에 서 방송 보도한 방송기자 출신 교수가 현장감과 방송보도의 실제를 수강학생 한명 한명에게 맞춤형으로 지도한다. 방송현장 뉴스의 경험과 이론을 겸비한 최고의 방송기자 ABC를 가르친다, 단신기사 쓰는 기초부터 리포팅기사 쓰는 법을 반복적인 학습을 통해 배우 고 익힌다. 방송뉴스의 궁금한 모든 것을 배우고 익힐 수 있도록 실습 위추로 강의하고 지도한다. 또한 수강학생들이 스스로 수습기자가 되어 아이템 발굴과 기사작성, 쵤영과 편집,오디오 더빙 등을 직접하며 텔레비전 뉴스 제작 시스템을 이해하고 취재 방법을 익힌다 교수는 보도국장의 역할을 담당하고 , 프로그램 기획, 기사 작성 및 리포트 제작 과정을 지도한다. 특히 TV뉴스 제작과정을 기반으로 기사쓰기와 리포팅하기,영상촬영과 편집, 인터뷰기법과 스탠드업(stand up) 등 TV뉴스제작에 꼭 필요한 지식과 방법을 배운다 AI 시대 휴머니즘을 구현할 수 있는 방송 언론인 육성 - 기후위기 시대 지구를 사랑할 수 있는 언론인 육성 - 뉴스 기획과 작성, 취재와 기사작성, 촬영과 편집, 인터뷰와 현장감 넘치는 스탠드업 등 제작기법 숙지 - 동영상 중심으로 오디오와 CG 등 멀티미디어적 요소를 입체적 활용능력 향상 - AI저널리즘과 가짜뉴스레 대한 비판적 안목 향상 - 빠르게 변화하는 디지털 기술의 흐름을 이해하고 미디어 환경 특성을 이해화고 이를 제작에 접목시킬 수 있다.', '{"뉴스","제작","편집","이해하기","있다","특히","텔레비전","지도한다","리포트","텔레비젼","텔레비젼의","시스템과","리포트기사작성","주교재","자료","학생들의","유튜브","높은","어떻게","하면"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('105444', '중급러시아어실습', '인문대학', '인문대학', 0, 4, '전선', '홍택규', '- 교과과정 개편 전 “중급러시아어1” 강좌와 “러시아어문법연습1” 강좌에서 다루던 내용을 함께 통합하여 다루는 강좌. 3시수의 이론 수업과 2시수의 실습 시간으로 이루어짐. - 이론 수업 3시간 동안은 러시아어를 처음 접하는 학생들을 대상으로 중급 수준의 러시아어 문법과 독해, 작문 능력을 갖추도록 가 르치는 시간이며, 실습 2시간은 이론 시간에 배운 문법, 독해, 작문 실력이 ‘몸에 잘 붙을 수 있도록’ 해당 과에서 다룬 내용을 중심으 로, 문법연습문제를 실전적으로 계속 풀게 됨. - 다시 말해, 이론 수업 3시간은 중급 문법, 독해, 작문을 다루며, 실습 수업 2시간은 문법연습문제 풀이를 통해, 러시아어 능력을 실전 화하고자 함. 러시아어 문법을 다루는 이론 수업 3시간은 전임교수(홍택규)가, 실습 2시간은 강사선생님(최문정)이 담당. - 러시아어는 한국어와는 형태적으로, 언어유형론적으로 너무나도 다른 언어이므로, 문법과 형태구조에 대한 체계적 학습이 선행되 어야 하고, 또 이를 바탕으로 발음, 억양, 듣기, 말하기와 같은 언어학습의 실제적인 측면도 같이 병행되어야 하는바, 이렇게 이론수업 과 실습수업을 한 강좌로 묶어 학습하는 것이 가장 효과적. - 중급 수준의 러시아어 능력을 전반적으로 다 갖추기 위해, 문법, 독해, 작문, 말하기, 듣기 등 언어학습의 제 영역을 다 다루는 강좌 로, 먼저 이론 수업에서 문법, 독해, 작문 관련 내용을 충실히 소화한 후, 실습 수업에서 이를 적용, 실전화하는 수업. - 본 강좌와 함께 2학기에 개설되는 “중급러시아어실습2” 강좌까지 온전히 소화하게 되면, 러시아어 문법에서 알아야 하는 제반 내용 은 다 다루게 돼, 그 이후로는 어느 정도 러시아어 학습을 자기주도적으로 진행할 수 있는 단계까지 오리리라 기대. - 1학기에 개설되는 본 “중급러시아어실습1” 강좌에서는 각 과별로 표준화된 어휘구문들의 학습과 별도로, 동사 상의 복잡한 용례들, -ся 동사의 제 용례들, 관계대명사, 형동사, 부동사 구문 등을 학습.', '{"동사들","러시아어","독해","시간은","작문","문법","용례들","형동사","피동","차이","표현","내용을","다루는","중급","능력을","ся","동사의","관계대명사","구문","첫걸음"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('655008', '재난의역사와치유', '인문대학', '인문대학', 0, 3, '전선', '문민기', '사회가 발전하고 변화함에 따라 ‘재난’도 복잡다단해졌다. 과거에는 자연재난만을 의미했다면 현재는 사회재난이라는 범주 아래 다양 한 형태의 재난들이 포함된다. 재난이 발생하는 원인과 그로 인한 피해, 복구 과정과 재난 이후의 삶은 역사의 다양한 모습들을 보여 주는 창이라 할 수 있다. 이 수업은 재난의 역사, 기억과 치유 과정을 살핌으로써 현재의 생활과 사회를 돌아보는 것을 목적으로 한다. 본 수업은 교수자의 강의 및 학생들의 과제 발표로 이루어진다. 1. 재난의 개념과 분류에 대해 확인하고, 각 사례에 대한 역사적 지식을 학습한다. 2. 다양한 자료를 독해하는 능력을 기르고, 이를 비판적으로 검토한다. 3. 기억과 치유의 방식을 토론하고 고민함으로써 현재의 문제를 인식하고 해결방안을 찾는 시각을 기른다.', '{"자료","독해","재난","인한","역사적","기억과","자연재난","사회적","참사","발생한","치유","개념과","재난의","따른","부실공사","사건에","선박","참사를","인해","재난이"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208201', '성격심리학', '사회과학대학', '사회과학대학', 0, 3, '전선', '이주일', '성격 심리학은 임상심리학, 조직심리학, 사회심리학 및 발달심리학 등의 교차지점에 있는 영역으로서 세부 전공을 공부하기 전에 기 본으로 공부해야 하는 영역이라 할 수 있습니다. 일반인이 생각하는 심리학은 무엇인가에 대해 가장 가까이 답을 할 수 있게 하고 그 답에 포함되는 내용을 찾고자 하는 과정으로 구성된 강좌라 생각합니다. 본 강좌는 많은 성격 심리학 강좌에서 흔히 진행하는 방식 대로 그동안 밝혀진 성격이론을 하나씩 다루는 방식은 지양하고자 합니다. 그 보다는 이런 이론을 기본 바탕으로 하되 개인들간 성격 의 차이, 좀더 구체적으로는 개인간에 생각, 감정인식등에 차이가 발생하고 일상행동에 그런 차이가 적용되는 과정과 기제에 대한 과학적 분석과 탐구및 자신에대한 적용을 목표로 합니다. 본 강좌에서는 주로 2학년에 진입하는 심리학과생을 대상으로 하여 성격 심리학의 기본 개념과 최근동향을 이해하고 성격심리학 연구에서 다루는 기본적인 연구주제들을 살펴보고자 구성되었습니다. 또한 성격심리학에서 다루는 기본적인 개념들을 토대로 자신의 성격을 분석하고, 주변 사람들에 대한 분석을 해봄으로써, 자신과 자기 주 변에 이의 타당성을 확인해보고, 자신을 돌아보고 발전시킬 기회를 가지고자 합니다. 심리학을 처음 듣는 수강생은 이해하기 어려울 수 있으며, 수업중 제시되는 과제수행에 어려움을 겪을 수도 있으니 이런 어려움을 극복할 자신이 있는 학생들이 수강신청하기 바랍 니다. ^^ -성격심리학에 대한 제반 이론을 이해한다. -성격심리학 분야의 최근 관심사나 연구주제가 무엇인지 이해한다. -본인의 성격의 주요 특징이 무엇인지를 성격심리학의 주제별로 이해한다. -심리학을 연구한다는 것이 무엇이고, 심리학과에서 잘 적응하는 데 무엇이 필요한지를 체험한다. -팀으로 과제를 수행하는 것이 무엇이고, 어떤 과정이 필요하며 어떤 역학관계가 생기는 지를 경험한다.', '{"나의","성격","성격의","어떤","차이","자기","무엇이고","나는","성격특질","좋은","성격특성","또는","것인가","정체성","성격간의","관계","성별과","남녀간의","다루는","합니다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209387', '시사다큐와비주얼스토리텔링', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '김성환', '1. 시사다큐가 무엇인 지를 이해하고 다큐 제작 과정의 이론적 기초와 실습 경험을 제공한다. 2. 사회, 역사적 현안에 대한 비판적 시각을 키우고 창의적인 영상 스토리텔링의 능력을 강화함으로써 독자적으로 다큐 작품을 기획하고 제작할 수 있는 역량을 배양한다. 3. 특히 온라인 플랫폼이 확대되고 크리에이터 개개인의 영향력이 커지고 있는 미디어 시장에서 영상 콘텐츠의 강자가 될 수 있도록 폭넓은 이론과 실무 능력을 갖추는데 수업의 목적이 있다. 시사다큐의 기획과 제작을 통해 영상 콘텐츠의 강자가 되자! 1. 시사다큐멘터리의 본질과 역사 이해 2. 제작 과정의 이론적 기초와 실습 경험 제공 3. 비판적 시각과 창의적 스토리텔링 능력 강화 4. 독자적 영상 콘텐츠 기획 및 제작 역량 배양', '{"제작","다큐","영상","점검","알아본다","시사","시청","기획안","강의와","영상시청","시청하기","아이디어","제출과","후반","콘텐츠","콘텐츠의","다큐의","영상의","특성을","인터뷰"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208205', '생리심리학', '사회과학대학', '사회과학대학', 0, 3, '전선', '진주희', '1. 뇌의 해부학적 구조 및 기능을 이해하고, 대뇌 기능과 인간의 행동 간의 관계를 학습함으로써, 뇌 손상이 심리 과정(주의, 언어, 기 억, 시공간 기능, 판단 및 정서 등)에 어떠한 영향을 주는지에 대해서 배운다. 2. 임상 현장에서 접할 수 있는 실제 신경심리평가 방식과 사례를 접목하여 임상신경심리학의 기초 지식을 배운다. 1. 뇌의 해부학적 구조 및 기능을 이해하고, 대뇌 기능과 인간의 행동 간의 관계를 학습한다. 2. 뇌 손상이 인간의 심리적 과정(주의, 언어, 기억, 시공간 기능, 판단 및 정서 등)에 미치는 영향에 대해 학습한다. 3. 인지, 정서 및 행동 장애가 증상으로 나타나는 주요 신경학적 장애에 대해 학습한다.', '{"퀴즈","슬라이드","신경심리학의","구조","대뇌","기능","뇌와","행동의","관여하는","장애","없음","시공간","신경해부학","구조와","기능적","전기적","활동","주의력에","기억","뇌의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209388', '취재보도실습', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '주영기', '- 이 수업은 수강생들이 실제로 기자가 되어 기획회의, 취재, 기사 작성 등의 저널리즘 활동을 수행하는 것을 주 내용으로 한다. - 통상적인 취재 및 기사 작성 연습을 넘어, 기사 아이템 기획 단계에서 △단순한 발생 사실의 전달 뉴스가 아니라 이슈 탐사의 성격이 강한 아이템으로 발전시키기 위해 대학생기자와 교수 데스크가 기초취재-보고-협의 조정의 과정(기획회의)을 거치고, 기사에 필요한 팩트를 가장 잘 아는 적합한 취재원을 대면/비대면으로 접촉하여 필요한 팩트를 수집, 그 결과를 보고하고, 추가 취 재 방향 제시, 추가 수집 등의 활동을 진행하고(취재), 학생 기자가 기사 틀을 잡고 데스크가 조정 방향을 제안하고 기자가 다시 기사 살을 붙여 초안을 뉴스룸(다음 카페)에 올리며 이에 대해 데스크가 보완사항을 제시하고 기자가 최종 마무리 기사를 올리는 작업(기사 작성)을 진행 하는 프로젝트형 수업임. (처음 실제 취재를 한다는 것이 어령게 느껴질 수있지만 자전거를 ？음 탈 때 뒤에서 누군가 잡아주는 역할을 데스크가 해주며 함께 자전거를 탄다는 느낌으로 수업에 참여하기 바람.) - 수업 결과는 ‘한림미디어랩 The H’에 올라가고 <오마이뉴스> 등 일선 매체에도 게재됨. - 기사 취재 및 작성 과정에서 1대1 방식의 지도가 이루어지며, 학생기자는 수정 내용을 면밀히 검토하는 것이 기사 실력향상의 중 요 포인트임이 강조됨. - 언론을 지향하는 학생은 물론, 홍보 분야, 방송작가와 같이 사실에 입각한 글쓰기 능력이 필요한 학생의 문장 실력 배양과, 기명 기사 게재를 통한 포트폴리오 축적 차원에서도 수강이 권장됨. 2. 교과 목표 ■ 교과목표 - 이 수업은 ①취재 및 기사작성 능력을 일선 뉴스매체 장기 인턴 기자 수준으로 끌어올리고, ②사회문제 발굴 및 개선방향 제시 역할을 하는 (탐사)기자의 존재가치 체험을 목표로 함.', '{"수업계획서","파일","참조","기사","취재","작성","기자가","데스크가","필요한","수업은","기획회의","등의","활동을","팩트를","수집","추가","제시","하는","것이","자전거를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208213', '사회심리학', '사회과학대학', '사회과학대학', 0, 3, '전선', '이정원', '사회심리학은 자신과 타인에 대한 사람들의 사고, 감정 및 행동의 원인과 결과에 대해 연구하는 학문입니다. 본 강의에서 여러분들은 한 학기 동안 사회 장면에서 인간의 행동과 마음에 대한 다양한 개념과 이론들을 학습하게 될 것입니다. 그리고 사회심리학적 개념 과 이론을 통하여 인간과 사회에 대한 이해를 확장시켜나가는 것을 목표로 합니다. 사회심리학의 이론과 개념을 학습하여, 인간과 사회에 대한 이해를 증진한다', '{"이해한다","교안","대해","어떻게","영향을","사람들이","타인의","행동에","사회적","편견의","사람들의","인간의","어떠한","자기","나타나는","동기","태도","집단","본질이","무엇이며"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209394', '스튜디오연출과촬영', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '김동규', '1. (TV)스튜디오 제작 - 방송영상콘텐츠의 대부분을 차지하는 핵심적인 제작방식으로 2 대 이상의 카메라(멀티 카메라)를 사용하여 스튜디오에서 제작 - 연출(PD), 작가, 카메라감독(카메라맨), 기술감독, 음향감독, 조명감독 등 다양한 분야의 직능과 협업 - 대담, 토크쇼, 토론, 버라이어티 쇼 등의 형식으로 영상미를 추구하기 보다는 다양하고 극적인 짜임새와 구성으로 대중의 흥미를 유도 2. <스튜디오 연출과 촬영>수업은 4개 조로 나누어 연출팀, 촬영팀, 기술팀, 출연팀 등 직능을 나누어 조별로 순환 담당하며 TV스튜 디오 제작실습을 시행 3. 우리 수업의 구체적 목표 역량 - 매스커뮤니케이션의 이해력 : 방송영상콘텐츠를 기획, 제작하고 유통(송출)하는 일련의 과정은 커뮤니케이션 모델 ‘SMCRE’ 모델에 적용될 수 있음, 따라서 영상콘텐츠 제작은 콘텐츠를 통해 얻고자 하는 뚜렷한 목적(효과)를 상정하고 그것을 극대화하기 위해 메시지를 어떤 내용과 형식으로 가공할 것인가에 대해 고민하는 과정과 그 결과임 - 창의적 기획력 : 방송영상콘텐츠는 불특정 다수, 곧 대중을 수용자로 하는 메시지. 따라서 대중들의 관심과 주목을 받기 위해서 영상 콘텐츠는 대중적이면서도 창의적으로 제작해야 함. 이것은 방송영상콘텐츠의 제목과 제작방식, 형식 등에서 창의적이어야 한다는 의미이기도 하지만 한편으로는 대중들이 쉽게 이해할 수 있도록 제작해야 한다 는 것임. 이 수업을 통해 단기적으로 창의적 기획력을 키울 수는 없지만 그것의 중요성, 그리고 제작기획서 형식의 필요성 등에 대한 이해를 할 수 있게 됨 - 협업과 소통력 : 방송영상콘텐의 제작 과정은 기획-촬영-편집-(녹음)-종합편집의 과정을 거치게 됨. 방송영상콘텐츠 중 스튜디오 제 작은 절대로 혼자 제작하는 경우는 없고 대개는 연출, 촬영, 편집, 작가 등의 여러 직능에 필요한 사람들이 협업을 해야 함. 여기에서 중요한 것은 연출자의 기획의도를 충분히 이해하고 그것이 충분히 반영된 콘텐츠를 만들기 위해 협력하는 것. 연출자는 방송영상콘텐츠 제작의 전 과정을 책임지고 이끌어가지만 제작진의 지도자는 아님. 제작진도 연출자의 지시와 요구대로 움직이는 사람들이 아니라 적극적으로 방송 영상콘텐츠의 완성도를 위해 연출자를 지원하는 사람들임. 따라서 서로간의 소통은 무엇보다 중요하며 이 수업을 통해 우리는 각 직능의 협업에 대해 이해하고 소통력을 키우게 될 것임 - 기획력 : . 역사, 정치, 사회, 문화 등에 대한 폭넓고 다양한 관심사를 바탕으로 제작자로서 제작하고자 하는 영상콘텐츠의 소재 선택, 구성, 제작 여건, 기대 효과 등을 고려하여 기획할 수 있음 - 소통 및 협업 능력 : . 스튜디오 제작은 연출 촬영 기술 등 각 직능별 다수의 제작진으로 구성되어 분명하고 원활한 소통과 상호존중을 기반으로 한 협 업이 필수이므로 반복되는 제작실습과정에서 소통과 협업 능력을 기를 수 있음 - 방송영상콘텐츠 제작 실무 능력 : . 방송영상콘텐츠는 불특정 다수에게 전달하고 유통시키기위한 목적으로 제작되는 것으로 일정한 수준의 품질을 유지하여야 하며 그 내용과 기법이 독특하고 창의적이되 대중 들에게 공감을 얻을 수 있어야 하므로 촬영, 편집, 녹음 등 전 제작과정에서 기술적, 심미적 실무 역량을 경험하고 키울 수 있음 - 방송환경에 대한 이해도 : 본 수업의 방송영상콘텐츠는 ''TV방송'' 콘텐츠의 다수를 차지하는 스튜디오 제작이므로 우리나라 방송사와 방송환경, 방송영상콘텐 츠의 특성 등에 대한 이해도를 높일 수 있음', '{"스튜디오","제작","연출","카메라","기술","시스템","촬영","출연","방송사","견학","있음","구성","하는","방송영상콘텐츠","제작의","방송","현장","협업","따라서","위해"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209564', '영상이론', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '류재형', '본 강좌는 영화, TV 드라마 및 디지털 콘텐츠 등에 등장하는 영상언어를 살펴보면서 관련 이론을 학습하는 것을 목표로 합니다. 따라 서 핵심적인 영상이론의 학습과 관련 영상물을 통한 예증이 병행되어질 것입니다. 전체 강의의 흐름은 주요 이론 및 개념에 대한 소 개가 이루어진 후에 비디오클립을 통해 확인하는 형식이 될 것이며, 학기말에 수업시간에 배운 이론을 영상에 적용하여 분석하는 팀 발표가 수행될 것입니다. 본 강좌를 수강하시면 기본적인 영상언어의 작동 원리를 이해하고, 그것에 대한 이론적 논의가 어떻게 이루 어져 왔는지 파악하게 될 것입니다. 또한 영상콘텐츠에 대해 이론을 적용, 분석, 발표함으로써 매체 비평의 역량을 함양하게 될 것입 니다. 영상콘텐츠의 언어 및 관련 이론의 학습을 통해 영상 비평의 토대를 함양하며 나아가 직업 현장에서의 영상 제작 및 매체 비평에 대 한 책임감을 고취한다. 지식: 영상콘텐츠의 스타일적 구성 요소 및 관련 이론에 대한 지식을 이해하고 사례 분석을 통해 의미 해석 및 비평 능력을 함양한다. 기술: 영상콘텐츠에 대한 지식을 기반으로 제작 현장에서의 사용 및 응용 능력을 함양한다. 태도: 영상 분석 및 제작 현장에서의 성실하고 진지한 태도를 함양하며 대중 앞에서의 명쾌하고 자연스러운 발표 능력을 함양한다.', '{"있을","수도","영상","능력을","함양한다","수업시간에","영화","분석을","업로드하는","파일","사용하는","슬라이드","있으며","사전","예고가","없을","있습니다","이해하고","대해","의미"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208214', '인지심리학', '사회과학대학', '사회과학대학', 0, 3, '전선', '정혜선', '인지심리학(cognitive psychology)은 심리학의 기초과목으로 마음을 이해하는 기본 틀을 제공합니다. 임상, 상담, 신경, 조직, 사회, 지 각, 범죄 등 심리학의 여러 분야는 물론 사회과학 및 공학의 여러 분야(예, 인공지능, 산업디자인, 교육심리, 언어청각, 광고, 행동경제 학 등)을 이해하는 데 핵심적인 역할을 하고 있습니다. 본 수업에서는 인간 인지를 중심으로 인지(cognition)란 무엇인지, 어떠한 방법 을 사용하여 연구되는지, 지각, 주의, 기억, 언어, 문제 해결 등 마음 속에서 일어나는 다양한 인지 작용에 대해서 공부합니다. 본 수업은 이러닝/원격수업으로 중간/기말 고사를 제외하고는 스마트리드(SMARTLead)의 동영상을 기반으로 진행됩니다. 주요 학습 활동은 다음과 같습니다. 1) 강의동영상 시청 2) 성찰과제 중요! 본 수업에서는 학습 및 교수 활동 지원을 위해서 AI 도구가 사용될 예정입니다. 크게 다음의 두가지 활동이 계획되어 있습니다. 어느 도구가 어떤 방식으로 사용될지는 추후 공지 예정입니다. ？ 학습 활동 지원: 수업 내용에 대한 학습자 질문에 대한 답변 또는 기타 예복습 활동을 지원하는 데 AI가 활용될 예정입니다. ？ 평가 활동 지원: 성찰과제 채점에 인공지능 도구가 사용될 수 있습니다(사용되지 않을 수도 있습니다) 시스템 개발 및 연구 목적으로 AI 튜터 사용 기록과 수업의 활동과 결과물(예, 성적, 질문 & 성찰 과제 제출 내역)이 수집&이용됩니다 . 수집된 자료는 모두 익명으로 처리되나, AI도구 사용에 불편을 느끼거나 자료 수집에 참여하고 싶지 않은 경우 본 수업의 수강을 권 하지 않습니다. [참고] 최종 수업 계획은 개강 후 확정됩니다. 2. 교과 목표 ■ 교과목표 인간 인지(cognition)를 중심으로 인지가 무엇인지, 어떠한 방법으로 연구되는지, 어떠한 영역이 존재하는지를 이해합니다. 인지의 대 표적인 영역인 지각, 주의, 기억, 언어, 문제 해결 등과 관련된 개념과 연구 결과를 살펴보고 이것이 마음의 작동에 가지는 함의를 이 해하고 활용할 수 있는 역량을 기르는 것이 교과목의 목표입니다.', '{"교재","성찰과제","지각","주의","장기기억","장기기억의","유형","인출","있습니다","언어","용량","감각기억","작업기억","오기억","지식","심상과","단계","문제해결","판단과","의사결정"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209713', '영상문화론', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '류재형', '이 강좌는 대중문화 및 영상문화의 의미를 이해하고 그에 대한 미디어의 영향을 살펴보는 동시에 영화, 텔레비전, 동영상 콘텐츠 등 구체적인 영상 콘텐츠의 의미를 이해하는 이론적 방법론을 학습하는 것을 목표로 합니다. 핵심적인 문화연구 이론, 특수효과 이론, 장 르 이론의 학습과 영상물을 통한 예증이 병행되어질 것이며, 강의의 흐름은 주요 이론 및 개념에 대한 소개가 이루어진 후 동영상 클 립을 통해 확인하는 형식이 될 것입니다. 본 강좌를 수강하시면 영상 콘텐츠를 주요 키워드로 하는 대중문화의 개념과 작동 원리를 이해하고, 그것에 대한 이론적 논의가 어떻게 이루어져 왔는지 파악하게 될 것이며, 다양한 영상 콘텐츠에 대해 이론을 적용, 분석해 봄으로써 대중문화 비평의 역량을 함양하게 될 것입니다. 대중문화 및 영상문화가 의미하는 바를 이해한 후 영상 콘텐츠가 대중문화 형성에 미치는 영향을 숙지함으로써 향후 미디어 콘텐츠 산업을 이끌 인재들에게 영상문화와 관련한 기본 소양과 책임 의식을 고양한다.', '{"있을","수도","업로드하는","파일","사용하는","슬라이드","있으며","사전","예고가","없을","있습니다","수업시간에","이해한다","영상","학습하고","영상문화의","영화","의미를","시간에","문화적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300023', '미디어평글쓰기기초', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '심훈', '다양한 종류의 대상들을 평함에 있어 수강생들은 스스로가 띄어쓰기, 오탈자, 엉터리 문장 줄이기, 짧게 쓰기, 일관성 있게 쓰기 등에 대한 글쓰기 기술을 향상시키는 동시에, 자신만의 글을 쓰는 법을 체계적으로 배우게 될 것 이다. 본 강의는 자신만의 시각으로 신선하고 재미있는 비평 글을 쓸 수 있도록 지도하는데 주안점을 두고 있다. 이에 따라 수강생들은 다 양한 대상들을 주관적이지만 공감을 불러 일으킬 수 있게 쓰는 법을 배우게 될 것이다.', '{"쓰기","줄이기","단어들","도서","띄어쓰기","문장","탈자","이하로","길이","피해야","취해야","영화","일관성","대상들을","수강생들은","있게","자신만의","글을","쓰는","법을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208215', '이상심리학', '사회과학대학', '사회과학대학', 0, 3, '전선', '조용래', '이상심리학의 학문적 성격, 기본 개념과 주요 이론을 숙지하고, 각 정신장애별로 주요 증상 및 임상적 특징, 원인론 및 치료이론 등을 교육함으로써 수강생 본인과 주위 사람들, 그리고 일상생활, 학교현장이나 임상현장에서 접할 수 있는 사람들의 이상행동과 정신장애 를 체계적으로 이해하고, 전문상담교사, 임상심리전문가, 상담심리전문가, 청소년상담사 등 전문인력으로 성장하는데 필요한 역량을 함양하도록 돕는다. 우리 학과의 전문상담교사 교직이수 학생들의 인재상은 청소년 정신건강에 대한 전문적 역량을 갖춘 상담교사이 다. 이상심리학의 학문적 성격, 기본 개념과 주요 이론들을 숙지하고, 각 정신장애별로 주요 증상 및 임상적 특징, 원인론 및 치료이론 등 을 학습함으로써 일상생활이나 임상현장에서 접할 수 있는 자신과 주위 사람들의 이상행동과 정신장애를 체계적으로 이해하고, 임상 심리학이나 상담심리학의 전문역량에 필요한 기초 지식과 기술을 함양하도록 돕는다.', '{"입장","장애","이상심리학의","불안장애","수면","각성장애","성기능장애","이론적","조현병","기타","정신장애","이상행동의","분류와","강박","주차","구성요소","외상","스트레스","사건","신체증상"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209721', '영상콘텐츠특강', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '류재형', '본 특강은 한국영화와 세계영화의 주요 흐름들을 역사와 문화의 상관관계를 통해 이해하는 데에 그 목적이 있습니다. 1부(중간고사 이전)에서는 한국영화에서의 시대별 영화운동/사조에 대한 학습이 이루어질 것이며 2부(중간고사 이후)에서는 국가별 뉴웨이브에 대 한 고찰이 이어질 것입니다. 개별 강의의 흐름은 역사와 영화사에 대한 설명이 이루어진 후에 주요 영화를 통해 그 내용을 확인하는 형식이 될 것입니다. 본 강좌를 수강하시면 한국영화와 세계영화의 시대적 흐름을 이해하고, 그것이 당대 사회와 문화의 제 측면들과 어떤 관련성을 가지는지 파악하게 될 것입니다. 역사 및 영화에 대한 비판적 사고 역량을 함양하고 이를 바탕으로 영화에 대한 역사 적 비평(historical criticism) 역량을 함양할 것입니다. 한국영화 및 세계영화의 흐름을 역사와 문화의 상관관계를 통해 살펴봄으로써 영화 및 영화사와 사회, 문화와의 관련성을 이해한다. 나아가 직업 현장의 준비를 위해 영상 제작에 대한 배경 지식을 함양하고 영화의 역사 비평을 위한 분석 능력을 제고한다.', '{"있을","수도","있습니다","이해한다","업로드하는","파일","수업시간에","사용하는","슬라이드","있으며","사전","예고가","없을","사회문화적","영화","세계영화의","한국영화의","흐름","와의","관계를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208305', '조직과인간행동', '사회과학대학', '사회과학대학', 0, 3, '전선', '김태웅', '사람은 살아가면서 필연적으로 여러 조직(단체)에 소속되게 됩니다. 조직과 인간행동(조직심리학)은 그러한 조직들이 어떻게 형성되 고 조직 내에서 개인이 보이는 행동과 그 원인 등 다양한 역동에 대해서 다루는 과목입니다. 본 강좌는 과목의 이름처럼 모든 수강생 들이 하나의 조직(팀)에 소속되어 조별 토의와 발표를 중심으로 진행됩니다. 구체적으로는 우리가 조직에 동화되는 과정, 조직을 생산적으로 또는 반생산적으로 이끄는 행동, 직장 내 스트레스의 영향, 효과적인 리더십과 조직의 문화는 무엇이며 이는 어떻게 생겨나는지 등에 대해 학습합니다. 수업을 통해 때로는 조직을 이끄는 한 명의 리더로서, 때로는 구성원 중의 한 명으로서 조직 내에서 더 많이 행복을 느끼고 효과적으 로 기능할 수 있는 방법에 대해 고민하고 그러한 기술을 함양하는 것을 목표로 합니다. - 조직심리학 관련 기본 개념과 이론, 연구들에 대해 이해한다. - 조직심리학 분야의 최근 관심사나 연구주제가 무엇인지 이해한다. - 다양한 사람들이 함께 하는 다양한 형태의 ''조직''에서 나타나는 문제에는 무엇이 있는지 학습한다. - 조직 상황에서 발생할 수 있는 문제들을 이해하고 대처방안을 학습한다. - 조직 상황에서 나타나는 주요 사례들을 분석할 수 있다. - 다양한 형태의 조직 상황에서 (가족, 친구, 팀 프로젝트 등) 조직심리학을 일상생활에 적용할 수 있다.', '{"토의","조직","주제","내용에","조별","이해와","주차","교수","질의","강의안을","기반으로","적용을","활용하여","주제인","생성","교수자가","설정한","주제와","비교","검토"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209802', 'AI와그래픽인포메이션', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '심훈', '무료 플랜인 Canva 인포그래픽 템플릿 및 간단한 차트와 Piktochart AI를 대상 도구로 활용한다. 이와 함께 Google Charts 또는 기본 스프레드시트 차트 (데이터 시각화 기초)를 활용하며, 일반 LLM인 AI 텍스트 도구와 무료/프리티어 이미지 생성 도구를 간단하게 활 용하는 법을 배운다. 본 수업에서는 인포그래픽의 개념과 역사, 그리고 디자인 원리를 이해하는 것을 목표로 한다. 이와 함께, 본 과목에서는 AI 도구 (텍스 트 생성, 이미지 생성, 레이아웃 보조)를 활용해 데이터, 아이디어를 시각 스토리로 변환하는 능력을 기른다. 본 과목에서는 필요에 따 라 Canva (템플릿 기반의 인포그래픽, 프레젠테이션 제작), Piktochart (데이터 중심 차트·리포트 인포그래픽에 강점이 있음), Venngag e (인포그래픽 생성 기능과 다양한 템플릿 구비) 등 주요 인포그래픽 제작 툴을 사용해 뉴스, 데이터 기반의 인포그래픽을 기획하고 제작하는 것을 돕는다. 이와 함께 본 수업에서는 상황에 맞춰 ChatGPT/Perplexity 등 텍스트·아이디어용 AI, DALL·E 등 이미지 생성 AI 를 소개할 예정이다. 강의 개요:', '{"인포그래픽","데이터","생성","차트","시각화","최종","텍스트","제작","개인","기반","윤리","템플릿","이와","함께","이미지","도구를","보조","프로젝트","무료","수업에서는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208308', '심리학주제특강', '사회과학대학', '사회과학대학', 0, 3, '전선', '최정욱', '본 강의는 R을 활용한 심리학 데이터 분석 기법을 습득하고, 분석 결과를 적절히 해석하는 능력을 함양하는 것을 목표로 한다. 본 강 의에서는 R의 기초 개념을 시작으로 심리학 데이터 분석에 필요한 데이터 전처리, 분석, 결과 해석 및 시각화 등 전반적인 분석 과정 을 다룬다. 또한 제공되는 데이터를 활용한 실습을 통해 실제 분석 상황에서 요구되는 실무적 역량을 기를 수 있도록 한다. - R의 문법과 데이터 유형에 대해 이해한다. - Rstudio 사용법을 익히고, 심리학 데이터를 전처리하는 능력을 기른다. - 적절한 분석 방법을 선택하는 능력을 기른다. - 분석 결과를 적절히 해석하는 능력을 기른다. - 심리학 데이터 분석의 기초적 지식 및 기술 기반을 다진다.', '{"데이터","강의안","유형","결과","해석","활용한","사용법","전처리","시각화","심리학","능력을","인덱싱","함수","반복문","조작","기술통계","상관분석","단순회귀분석","전반적인","기른다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208331', '졸업논문연구', '사회과학대학', '사회과학대학', 0, 3, '전선', '서동기', '졸업논문을 쓰고자 하는 학생들에게 전공별로 지도교수를 배정하여 논문지도를 받으면서 논문을 쓸 수 있도록 함. 이를 위해 논문 주 제에 따라 지도교수를 선정하고 각 지도교수의 지도하에 한학기동안 논문을 쓰고 이 과정을 얼마나 충실히 이행하였는지를 평가하고 자 함. 논문 작성법에 대한 지도 및 졸업후 보고서 작성에 필요한 과정을 이수하도록 하는데 목적이 있 논문을 기획하고 데이터를 수집하고 분석하여 논문을 완성하는 과정을 배우고 실천한다', '{"논문","각자","논문의","요약","논문을","지도교수별로","필요시","작성","결과","과정을","지도교수를","선정된","지도교수와","미팅을","추진","일정","확정","공유","상세한","논문계획안"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208333', '심리학입문', '사회과학대학', '사회과학대학', 0, 3, '전선', '서동기', '본 수업은 심리학의 본질과 학문적 특성, 방법론, 그리고 다양한 심리학 연구(세부 전공)영역에 관하여 개관함으로써 심리학을 전공하 는 학생들이 전공 학문의 기초를 닦는데 도움을 주고자 한다. 특히, 각 연구영역별로 기초 이론, 기본 개념들과 주요 연구결과들을 소 개하며, 이를 통하여 수강생 자신과 다른 사람들을 이해하는데 도움을 얻을 수 있을 것으로 기대한다. 본 과목은 심리학 전반에 대한 개괄적인 지식을 습득하는 것으로 목표로 한다. 본 과목을 수강함으로써 과학적 심리학의 본질, 역사, 방법론 및 주요 연구결과들을 습득할 수 있다. 과학적으로 사람의 마음과 행동을 이해하는데 도움되는 지식과 기술을 습득하고 이를 적용할 수 있는 인재상을 구현하는데 기초가 되는 과목이며, 이후의 전공 심화 학습을 위한 안내자 역할도 수행하게 된다.', '{"주교재","교수","관하여","배운다","임선영","정신장애의","심리학","최훈","서동기","어떻게","행동","사회적","이해한다","치료","기억","그리고","전공","심리학의","방법론","도움을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300029', '영상매체기초:연출', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '김동규', '1. 영상매체(영상미디어)는 메시지를 영상콘텐츠로 제작하여 전달하는 매체로 이른 바 ''레거시 미디어''라고 일컫는'' 텔레비전''이 대표 적입니다,지금의 스마트 미디어 시대에서는 인터넷만 연결되면 언제 어디서나 영상콘텐츠를 소비할 수 있는 유력한 동영상콘텐츠 플 랫폼인 ''유튜브''가 또 다른 대표적인 예입니다. ''영상콘텐츠''는 영상을 주로 하면서 음성과 음향, 음악 등을 보조적표현방법으로 하여 제작자의 의도가 반영된 계획된 효과를 얻기 위해 제작되는 메시지입니다. 따라서 영상콘텐츠를 어떻게 만들것인지에 대한 기획과 제작 과정의 관리, 제작 후의 활용 등을 포괄한 것이 연출이라고 볼 수 있으 며 촬영은 제작과정의 가장 핵심적이고 중요한 요소이다. 이 수업에서는 연출의도를 잘 표현하기 위한 수단으로서 ''촬영''의 기초를 중심으로 다루고자 합니다. 다만, ''촬영''은 단순히 카메라를 조작해서 영상을 얻는 행위 만을 말하지 않고 그 이전에 ''무엇을 왜, 어떻게''찍어야 하는가를 결정하는 기획과 연출이 포함됩니다. 따라서 촬영 기법과 영상문법 등 촬영 영상이론 뿐 만 아니 라 연출의 결과로서 영상물 제작까지 수업에서 진행할 것입니다. -> 학교 보유 촬영 장비를 중심으로 한 찰영 실습 위주 수업 2.구체적 목표 역량 - 창의적 기획력 : 영상매체를 통해 전달하고자 하는 메시지를 어떻게 창의적으로 구성할 것인가? - 대중 소통력 : 커뮤니케이션을 위한 메시지는 특정한 효과를 얻고자 하는 것으로 대중의 기호와 경향을 잘 분석하고 반영할 수 있 어야 한다. - 공적 책임 : 표현의 자유를 누리되 지켜야 할 타인의 권리, 기본권, 언어 생활 등을 고려하여야 한다. - 지식 : 영상콘텐츠를 제작하는 것은 커뮤니케이션 활동의 일부임을 이해하게 함 - 기술 : 영상콘텐츠를 제작하기 위한 촬영 기초 이론과 촬영 장비별 기능을 이해하고 조작 할 수 있음 - 태도 : 영상제작은 창작이므로 꾸준하게 새로운 것을 생각해 내려고 하는 창의적 태도를 길러 냄', '{"촬영","캠코더","영상","파나소닉","이해하기","카메라","만들기","영상콘텐츠를","법칙","이론에","풍경","영상에세이","현장","있는","영상콘텐츠","등을","어떻게","영상문법","하는","장비별"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300034', '디지털플랫폼과뉴미디어', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '정지영', '4차 산업혁명 시대에 미디어 기술은 더 급속하게 발전하고 있다. 스마트 미디어에 이어 인공지능(AI)의 등장과 확산은 이용자들의 뉴 스 이용 행태를 크게 바꿔놓았다. 다양한 매체에서 뉴스가 실시간 생산되며, 그 형태와 전달 방식도 다양해졌다. 또, 전문 언론인만이 아니라 일반인도 적극적으로 뉴스 생산을 하고 있고, 이용자들의 반응도 즉각적으로 표현 및 공유되고 있다. 이와 같이 미디어 환경 의 변화와 뉴스 생산·유통·소비의 진화는 전통적인 뉴스 생산과 소비의 의미를 해체시키고, 거대한 양의 뉴스가 일상 곳곳에 침투하여 상호작용을 일으키고 있다. 이러한 상황에서 뉴스가 담고 있는 메시지 등을 올바르게 이해하고 가치를 따져볼 수 있는 역량은 매우 중요하다. 따라서 본 강의에서는 4차 산업혁명 시대의 뉴스 이용 행태와 영향 등을 이해하고, 뉴스분석법을 익혀 현명한 뉴스 바로보 기가 가능케 하도록 한다. 나아가 뉴스 안과 밖에서 발생하고 있는 다양한 이슈를 파악하고, 이에 지혜롭게 대응하는 방안을 모색하 는 뉴스 리터러시 역량을 키운다. 스마트 미디어의 등장에 이어 4차 산업혁명, 인공지능 개발 이후에 급변하는 뉴스 생산.유통.소비 행태를 구체적으로 파악하고 뉴스 의 제 의미를 되짚어서 민주시민사회에서 필요한 뉴스와 뉴스 제작자로서의 기초 역량을 함양한다. 이를 바탕으로 다양한 뉴스 기반 의 이슈를 분석하고 구체적인 논의를 이어가면서 저널리즘의 가치를 실현하는 뉴스 제작자가 될 수 있는 역량을 키우도록 한다.', '{"뉴스","활동","리터러시","미디어","뉴스의","플랫폼과","퀴즈","생산","있는","중간평가","안내","산업혁명","있다","뉴스가","시대의","역량을","뉴스와","스마트","이어","인공지능"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208337', '범죄심리학', '사회과학대학', '사회과학대학', 0, 3, '전선', '이정원', '범죄심리학은 범죄, 특히 범죄자의 심리적 측면을 다루는 학문입니다. 한 학기 동안 범죄행동의 심리학적 이론과 개념을 학습하고, 이 를 통하여 범죄를 개인의 측면에서, 그리고 사회의 측면에서 바라볼 수 있는 지식과 안목을 배양하는 것을 목표로 합니다. 범죄심리학의 주요 이론 및 개념에 대해 학습하는 것을 목표로 하고 있습니다', '{"이해한다","대해","유형","범죄","특성에","심리적","정의","특성을","범죄자","프로파일링","묻지마","유형과","범죄자의","학습하고","그리고","범죄심리학이","어떠한","학문인지","범죄심리학","측면에서"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202411', '종교사회학', '사회과학대학', '사회과학대학', 0, 3, '전선', '엄한진', '본 강좌는 한편으로는 종교사회학이 다루어 온 고전적인 주제들과 주요 저작들을 소개하고, 다른 한편으로는 근본주의, 신종교운동 등 종교에 대한 학문적 관심의 부활의 배경이 된 현대종교변동의 주요 현상들을 살펴본다. 종교에 대한 사회학적 접근에 앞서 종교 자체에 대한 개괄적인 소개가 있고 세속화, 종교조직, 종교성, 종교와 정치, 종교와 경제 등 종교사회학의 주요 주제를 학습한 후 한국 의 사례를 다룬다. 누구나의 관심거리인 종교에 대해 과학적으로 바라보는 능력을 키운다.', '{"종교","종교와","엄한진","한국의","한국","종교의","옮김","막스","베버","종교에","자료","극우","사회학적","종교성","경제","개념에","뉴에이지","황선명","종로서적","현암사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300037', '단편미디어스토리텔링', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '송현주', '<단편 미디어스토리의 구상과 집필>은 선수과목으로 <미디어스토리텔링기초>를 수강한 학생들을 대상으로 합니다. 미디어스토리 에 대한 분석과 비평에 그치지 않고 단편 미디어스토리(10분 내외)를 구상하고 집필·완성합니다. 이를 통해 미디어 콘텐츠 제작할 수 있는 능력, 장편 미디어스토리를 구상하고 집필할 수 있는 능력을 배양합니다. <단편 미디어스토리의 구상과 집필>은 선수과목으로 <미디어스토리텔링기초>를 수강한 학생들을 대상으로 합니다. 미디어스토리 에 대한 분석과 비평에 그치지 않고 단편 미디어스토리(10분 내외)를 구상하고 집필·완성합니다. 이를 통해 미디어 콘텐츠 제작할 수 있는 능력, 장편 미디어스토리를 구상하고 집필할 수 있는 능력을 배양합니다.', '{"단편","미디어스토리","집필","구상하고","있는","미디어스토리의","구상과","선수과목으로","미디어스토리텔링기초","수강한","학생들을","대상으로","합니다","분석과","비평에","그치지","않고","내외","완성합니다","이를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208413', '청소년심리', '사회과학대학', '사회과학대학', 0, 3, '전선', '오충광', '청소년은 신체적 변화와 더불어 심리적, 사회적 변화가 크게 일어나는 시기이다. 이러한 청소년의 변화에 대한 스스로의 이해가 부 족할 때 청소년은 혼란에 빠지게 되고, 주변사람들과 갈등을 경험하게 된다. 이러한 청소년의 심리적 혼란과 주변사람과의 갈등은 발 달단계에서 일시적으로 나타나기도 하고, 오랜 시간 지속되기도 한다. 따라서 본 강의를 통해 청소년들의 다양한 심리적, 사회적 특 성과 어려움에 대해 이해하고, 효과적인 상담으로 심리적 어려움을 도와줄 수 있는 방법을 익힌다. 특히 교직이수 학생들의 경우, 아 동 및 청소년의 인지적, 심리사회적, 신체 및 행동적 발달적 특성과 문제, 문제상황에 대한 효과적인 상담방법에 대한 지식을 습득한 다. 이러한 과정을 통해 향후 전문상담교사로서 학생상담 및 진로지도를 전문적으로 수행할 수 있는 역량을 갖추도록 한다. 우리 학 과의 교원 인재상은 청소년 정신건강에 대해 전문성을 갖춘 상담교사입니다. 청소년이 겪는 개인적, 사회적 갈등을 이론적으로 이해하고, 이에 대한 효과적인 개입방법을 숙달한다. 교직이수 학생의 경우, 청소년 의 심리적 특성을 이해하여, 학생지도 및 상담에 적용할 수 있도록 한다.', '{"청소년","상담","조별과제","이해한다","이해하고","익힌다","심리적","청소년심리학","사회적","청소년상담","대해","상담의","청소년의","한다","효과적인","과정을","변화하는","장과","보충자료","청소년이"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208416', '심리학연구의기초', '사회과학대학', '사회과학대학', 0, 3, '전선', '최훈', '심리학의 핵심이 무엇이라고 생각하십니까? 심리학의 핵심은 ''연구방법론''입니다. 한림대학교 심리학과에서는 이 연구방법에 중점을 두어 교육하고 있고, 이는 타 대학의 심리학과와 비교했을 때, 한림대 심리학과의 큰 장점으로 알려져 있습니다. 본 수업은 심리학을 연구하기 위해 필요한 기초 기술을 익히는 기회를 제공하기 위해 설계되었습니다. 몇 년간의 심리학 연구방법론의 강의에서 학생들이 호소하는 가장 어려운 부분이 심리학 연구에 대한 이론을 알겠는데, 그 이론을 실 질적으로 구현하는 방법에 대해서 너무 어렵다는 것이었습니다. 특히, 주로 컴퓨터를 통해서 진행되는 심리학 연구의 특성상 컴퓨터 와 관련된 기술 부족이 학업을 저해한다는 평이 많았습니다. 그래서 본 수업은 심리학을 전혀 모르는 신입생들에게 가장 기초적인 기술을 알려 주려는 목적을 가지고 있습니다. 심리학 연구에서 설계를 하고 데이터를 모집하는 데 사용되는 네이버나 구글 설문지, 더 나아가 컴퓨터로 심리학 실험을 진행할 수 있는 PsychoPy, 수집된 데이터를 분석하는 데 필요한 Excel 및 SPSS, (가능하면 R programming) 분석한 결과를 보고하는 데 필요한 한글 및 PPT을 심리학 연구 진행과 함께 알아 보려고 합니다. 본 수업은 앞으로 심리학을 전공하는 학부생으로서 기본적인 연구 프로젝트를 수행하는 데 필요한 아주 기초적인 기술에 대해 익히 는 것을 그 목표로 한다. (지식) 심리학 연구의 기본적인 개념과 심리학 연구를 수행하는 필요한 기본적인 지식을 얻게 된다. (기술) 심리학 연구를 통해 데이터를 얻고, 분석하고 그 내용을 발표하는 데 필요한 기초적인 기술들을 얻게 된다. (태도) 전문적인 심리학 연구를 읽고 이해하는데 두려움이 없는 태도를 갖게 된다.', '{"실험","집단","심리학","결과","필요한","설계","수업은","심리학을","기초적인","데이터를","기본적인","연구를","된다","심리학의","있습니다","위해","기술을","가장","이론을","연구의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('300040', '영화분석세미나', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '이황석', '본 강좌는 교수자의 지도 아래 특정한 영화를 선정하여, 학기 동안 수강생들과 함께 토론과 발표를 통해서 한 영화텍스트를 집중적으 로 분석하는 블록세미나형식의 수업입니다. 본 수업을 수강하기 위한 선수과목으로는 영상미학과 비평, 영화와 클래식 중 한 개 이상 수강한 학생으로 제한합니다. 이는 제시된 선수과목을 수강한 이들 중, 보다 진전된 방식의 세미나수업에 참여하기를 희망하는 학생 들을 대상으로 개설된 강좌이기 때문입니다. 따라서 수업의 난이도는 비교적 높은 편이며, 영화영상학과 관련 대학원진학을 계획하는 학생이거나 혹은 영화분석 관련하여 진로를 고민하는 고학년생을 위한 수업입니다. 현대적 의미에서 텍스트론은 다양한 해석을 용인합니다.. 하지만 텍스트를 분석한다는 것은 일정한 훈련을 필요로 합니다. 그만큼 고 도의 집중력을 요하는 과정이 수반되어야 만이 하나의 텍스트를 분석할 수 있습니다. 본 수업은 특정 영화를 토론형식으로 분석해 봄 으로써 수강생들로 하여금 영화텍스트분석의 방법론을 귀납적으로 습득하게 하는데 그 목적을 두고 있습니다. 한 학기동안 십여 편 의 영화를 선정하여 블록세미나 형식의 집중력 있는 토론수업을 통해 매시간 심도 있는 텍스트분석을 시도합니다. 앞서 교과목 개요에서 설명한 바와 같이, 영화영상 관련 학업을 이어갈 계획을 가지고 있거나 또는 영화분석에 관련된 진로를 생각하 고 있는 학생들에게 전문적으로 영화를 해석하는 능력을 세미나형식의 수업을 통해 배양하기 위한 강좌입니다. 따라서 정해진 선수 과목을 통하여 일정수준에 도달한 학생들에게 강의식 수업에서 가질 수 있는 갈증을 풀어주고, 세미나를 통해 주도적으로 문제를 해 결해나가는 방법을 습득하는 장을 만들어준다는데 그 목적이 있습니다. 더불어 그 과정을 통하여 바로 학업과 실무에 적응할 수 있는 인재를 양성하는데 그 목표를 두고 있습니다.', '{"상동","토론수업","영화","시청","참여도","교수자와","면담수업을","수행한","팁별로","교수자가","제시한","조별","블록세미나","있는","영화를","있습니다","영화미학의","양상과","사례","교수자의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202318', '문화사회학', '사회과학대학', '사회과학대학', 0, 3, '전선', '김정환', '문화에 대한 사회학(sociology of culture)이자 문화적 사회학(cultural sociology)으로서의 문화사회학의 주요 이론과 쟁점을 살펴봄으 로써 정치, 경제와는 구별되는 문화의 작동논리를 이해하고 현실을 탐구하는 사회학적 사고의 지평을 넓히기 위한 과목입니다. 이번 학기에는 ‘성장, 발전, 성숙’을 주제로 삼아 수업을 진행합니다. 더 나은 존재가 되어 더 나은 삶을 살아가겠다는 문화적 열망이 사회 속에서 어떤 양상으로 전개되며, 어떤 귀결을 가져오는지 살펴볼 것입니다. 이러한 탐구를 통해 현대 한국인, 그리고 자기 자신이 문 화적 존재로서 무엇을 추구하며 어떤 삶을 살아왔는지 돌아보고, 이러한 성찰 작업 자체가 고도의 문화적 활동임을 인지하도록 합니 다. 수업개요 참고', '{"삶을","문화적","정치","어떤","사회학","나은","이러한","도입","문화란","무엇인가","문제가","되는가","문화","문학과","과학","말과","자유","한나","아렌트","지식"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209515', '비주얼콘텐츠포트폴리오', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '김성환', '임플로언서(Employee+Influencer)라는 말이 생길 정도로 온라인 채널을 가진 1인 크리에이터는 취업 시장에서 강력한 경쟁력을 가진다. 또 좋아하는 일을 하면서 소득을 얻기도 한다. 이 수업은 온라인 콘텐츠 제작과 채널 운영 전략을 제공함으로써 학생들이 1인 크리에이터로 성장하는 것을 돕는 것을 목적으로 한다. 학생들은 자연스럽게 포트폴리오를 완성할 수 있고 경쟁력 있는 커리어 전략을 세울 수 있을 것이다. 1. 유튜브와 인스타, 틱톡 등 온라인 플랫폼의 특성과 차이점 그리고 콘텐츠 트렌드를 이해한다. 2. 시각적 스토리텔링 기법과 숏폼 등 온라인 콘첸츠의 제작 기술을 익힌다. 3. 자신만의 콘텐츠를 기획·제작해 채널을 운영하고, 채널 성과를 분석해 본다. 4. 결과물을 포트폴리오 형태로 정리해 취업 자료로 축적하고 자신의 브랜딩에 활용한다.', '{"콘텐츠","영상","제작","강의와","기획","리포트","채널","전략","개인","온라인","콘텐츠의","운영","포트폴리오","기법","비주얼","발표와","개설과","성과","특성과","작성"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208418', '심리상담의기초', '사회과학대학', '사회과학대학', 0, 3, '전선', '임선영', '본 과목은 심리학 전공생을 대상으로 상담 및 임상심리학의 공통 지식인 심리상담 이론과 기법 등을 학습하는 것을 목표로 합니다. 상담 및 심리치료의 기본 개념, 주요 심리치료이론, 심리상담의 다양한 주제 및 형태, 상담의 과정 및 기법 등에 관한 기본적이면서 핵 심적인 내용을 개관합니다. 따라서 향후 상담/임상심리학, 혹은 정신건강 분야의 전문가가 되고자 하는 학생들은 본 수업이 필수교과목임을 인지하기 바랍니다. 또한 본 교과목을 통해 교직이수 학생들의 경우, 학생심리상담을 위한 상담이론과 기초기술을 습득하여 향후 전문상교사로서 학생상 담 및 진로지도를 전문적으로 수행할 수 있는 역량을 갖추도록 합니다. 우리 학과의 교원 인재상은 청소년 정신건강에 대해 전문성을 갖춘 상담교사입니다. 본 교과는 상담심리학이라는 세부 심리학 분야의 기초적 이론을 학습하는 것을 목표로 합니다. 구체적으로, 상담심리의 기본 개념, 주요 심리상담이론, 상담의 다양한 주제 및 형태, 상담의 과정 및 기법 등에 관한 기본수준의 내용 을 학습합니다.', '{"이해한다","상담의","상담이론의","대해","심리적","인간관","있다","상담","기법","문제에","인지행동적","방법을","집단상담의","정신분석적","동영상","치료방법에","기본개념","설명할","가족상담의","성격이론"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209661', '게임기획실무', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '장한진', '본 교과는 게임과의 인터랙션을 위해 필요한 지식과 실무 능력을 학습합니다. 구체적으로 게임제작을 하는데 있어 필요한 게임 시나리오 및 스토리, 게임디자인 등의 개념을 게임실무와 게임개론을 통해 학습하여 게임기획서를 작성합니다. 게임기획에 필요한 게임개론과 게임의 시나리오, 디자인 등의 전체적인 게임의 시스템, UI/UX, 레벨 디자인, 밸런싱 설계를 기획하고 게임을 직접 구현할 수 있는 게임엔진을 활용하여 간단한 프로토타입의 게임을 구현합니다.', '{"게임","게임의","게임을","온오프라인","스마트캠퍼스","필요한","게임기획서를","프로토타입의","실습강의","게임기획서","시나리오","등의","디자인","게임제작개론","역사","플랫폼","게임제작실무의","게임제작에","기초실습","유니티"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208419', '심리평가및실습', '사회과학대학', '사회과학대학', 0, 3, '전선', '진주희', '심리학 전공자로서 반드시 숙지하고 있어야 할 심리검사의 기본적인 제작과정과 심리검사가 갖추어야 할 필수조건, 심리검사의 종류, 검사실시 및 해석방법에 대하여 강의와 실습(Wechsler 지능검사, MMPl-2, 신경심리검사)을 통해서 학습한다. 심리검사에 대한 기본적인 지식과 심리검사의 종류를 학습하고, 심리검사를 실시, 채점, 해석하여 심리평가보고서를 작성하는 기술을 습득함으로써 학생들이 심리검사의 실시와 해석에 있어 전문성이 요구됨을 인지하고 심리검사에 대한 존중과 자신감을 갖도록 한다 .', '{"실시","심리검사의","자료","심리평가의","최신","흐름","해석","강의와","학습한다","채점","종류","매뉴얼","익힌다","지능검사","역사와","작성","신경심리평가의","작성법을","성격검사의","대하여"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208422', '심리측정', '사회과학대학', '사회과학대학', 0, 3, '전선', '서동기', '직접 관찰할 수 없는 인간의 성격, 행동, 태도를 측정하는 심리검사도구를 학생들 스스로 개발할 수 있게 하여 현장에서 적용할 수 있 는 역량을 키운다. 학생들이 직접 개발한 심리검사 개발 내용을 학회에서 발표하여 자신의 역량을 평가할 수 있다. 본 과목은 심리측정에 대한 전반적인 지식을 배우는 과목으로서 수강생이 심리검사 개발에 필요한 통계적인 방법을 배우고 심리검사 개발 전문가로서 갖추어야 할 심리검사에 대한 지식, 통계방법을 이용한 분석 기술, 그리고 검사개발자의 태도, 검사 개발을 위한 창 의적이고 비판적인 사고, 발표를 통한 협업과 표현력을 고양하기 위한 목적으로 개설되었다.', '{"노트","검사","조별발표","개발","평가의","목적","설문지","이해하기","문항분석","검사문항의","요인분석","측정","심리검사","이용한","직접","역량을","심리측정학의","심리검사와","검사와","교제"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469007', '양자역학', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '공통전선', '박두재', '- 전공 교과과정의 원활한 수강을 위해 양자역학적 개념 이해를 증진하고, 대표적인 주요 문제에 대한 풀이를 통해 응용력을 함양함 - 연구 및 실습과정에서 필요한 필수지식을 함양하고 응용할 수 있는 능력을 함양함 -양자역학의 핵심 개념인 Wave-particle Duality, Wavefunction, eigenvalue-eigenfunction, operator Measurement conjecture, Supe rposition Principle, Hilbert Space를 이해하고 수학적 방법을 통해 물리학적 현상에 적용함 -Tunneling process, 무한우물 문제, 스핀 동역학, Two level system, band formation, density matrix/transfer matrix, Quantum entan glement/EPR pardox, Fermi-Dirac distribution 등 반도체/디스플레이 분야에 적용되는 대표적인 양자역학 문제 풀이 과정을 학습함', '{"자체","자료","숙제","주교재","양자역학의","대표적","확장","고전","패러독스와","해석","벡터","에너지","스핀","물리학의","개념의","정의","보조","교재","상태함수와","힐베르트"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209675', '엔터테인먼트콘텐츠', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '강혜원', '엔터테인먼트 콘텐츠 이해: 음악, 패션, 출판, 미술 등 엔터테인먼트 장르 간 경계가 사라지는 시대의 콘텐츠 기획을 이해한다. 큐레이션 역량: 문화 콘텐츠를 선별, 편집, 재해석하여 새로운 맥락을 부여하는 큐레이션 능력을 기른다. 문화적 감수성: 동시대 엔터테인먼트 트렌드와 취향 공동체를 이해하고 분석하는 안목을 기른다. 시각 스토리텔링: 인스타그램을 활용한 시각적 내러티브 구성 능력을 습득한다. 로컬 문화 재해석: 춘천과 강원 지역의 문화예술 자원을 콘텐츠로 재발견한다. 협업 및 팀워크: 기획부터 제작, 피드백까지 전 과정을 협업으로 경험한다. 문화 사업화: 엔터테인먼트 콘텐츠를 기반으로 한 실제 비즈니스 모델을 설계한다 본 과목은 음악, 패션, 출판, 미술, 공연 등 엔터테인먼트 콘텐츠를 중심으로 소셜미디어 콘텐츠를 제작해보는 것을 목표로 한다. 학생 들은 인스타그램을 메인 플랫폼으로 활용하여 특정 문화 장르를 큐레이션하고 재해석하는 콘텐츠 계정을 기획하고 운영한다. 엔터테 인먼트 산업의 장르 경계가 허물어지는 시대에 문화 콘텐츠 기획 능력을 기르고, 선별과 편집을 통해 새로운 의미를 창출하는 큐레이 터로서의 안목을 개발한다. 케이팝, 드라마, 웹툰, 게임, 페스티벌, 출판, 인디 문화, 패션 등 학생들이 관심 있는 엔터테인먼트 영역, 춘 천과 강원 지역의 문화예술 자원을 활용하는 로컬콘텐츠 등 폭넓은 엔터테인먼트 영역에서 주제를 선정하여 깊이 있게 탐구한다. 팀 단위 협업을 통해 파일럿 콘텐츠를 실제 제작하고, 동료 평가와 이용자 반응을 분석하여 실무능력을 함양하는 현장형 프로젝트 수업 을 지향한다. * 서울국제무용영화제 연계활동 팀 별도 선발예정 , KOSAC(대학생광고대전) 등 외부 공모전 등을 염두에둔 프로젝트 진행 가능 *기획안 작성 및 콘텐츠 제작에 대한 기초적인 지식과 경험이 있는 학생을 대상으로 운영함', '{"엔터테인먼트","문화","콘텐츠","콘텐츠를","패션","출판","능력을","음악","미술","장르","경계가","큐레이션","새로운","기른다","안목을","인스타그램을","강원","지역의","문화예술","자원을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209686', 'AI DIGITAL GRA', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '안창현', '- 각종 영상 및 이미지 제작에서 주로 사용되는 디자인 도구의 기초 능력 습득 - 이미지 편집툴 학습에 대한 두려움을 낮추고 누구나 배울수 있다는 효능감 배양 - Affinity v3 Masterclass: Adobe 툴 유료 구독 없이 Adobe 디자인 툴 3종세트 (일러스트레이터, 포토샵, 인디자인)에서 할 수 있는 전 문 디자인 능력 기초 습득 - 각종 예제 및 실습을 반복학습하여 결과물 중심의 수업 운영 - 생성형 AI 이미지 + 프롬프트 엔지니어링 + 바이브 코딩 + 바이브 디자인을 결합한 디자인 + 코딩 혼합의 하이브리드 AI 엔지니어 /디자이너 능력 양성 - Affinity v3 + Canva를 활용한 디지털 그래픽 디자인 전문작업: 포토샵, 일러스트레이터, 인디자인 3종 세트를 합친 전문 그래픽 작 업을 어도비 툴 없이도 누구나 할 수 있다. - AI 기반 디자인 활용: Text to Image prompting, 바이브 코딩, 바이브 디자인 및 프롬프트/에이전트 엔지니어링을 동원한 디자이너 + 프로그래머 하이브리드 융합형 인재를 지향 - 취업 포트폴리오를 염두한 실무 프로젝트 경험: 실습 결과물이 곧바로 취업 포트폴리오로 연결될 수 있는 레벨의 실전 프로젝트 과 제', '{"디자인","일러스트레이터","바이브","그래픽","이미지","코딩","각종","누구나","포토샵","인디자인","있는","프롬프트","하이브리드","디자이너","취업","프로젝트","포토샵과","기능","중간고사","주차"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208434', '심리검사의이해', '사회과학대학', '사회과학대학', 0, 3, '전선', '송민지', '심리평가의 과정(심리검사를 통해서 얻어진 정보를 중심으로 하여 면담, 행동관찰, 개인력 등의 자료를 참조하여 종합적인 평가를 내 리는 전문적인 과정)에 핵심적인 자료를 제공하는 심리검사에 대한 기본적인 지식과 종류에 대해서 학습한다. 심리검사에 대한 기본적인 지식과 심리검사의 종류를 학습하고 심리평가에서 심리검사의 역할에 대해서 이해한다.', '{"해석","개관","학습한다","종류","실시","심리검사의","대해서","검사의","타당도의","지능검사의","역사와","적성","흥미","검사에","신경심리평가의","아동","청소년","심리평가의","등의","자료를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('208435', '심리학현장실습1', '사회과학대학', '사회과학대학', 0, 3, '전선', '진주희', '1. 실제 심리학 관련 현장 (병원, 상담기관, 기업 등)에서의 경험을 통해 이론적 지식을 통합하고, 심리학자로서의 진로를 탐색하며, 실 무 역량을 강화한다. 2. 사전 지정된 심리학 관련 기관(병원, 상담센터, 기업 등)에서 지정된 시간 동안 현장 실습을 성실히 이수한 경우 학점으로 인정한다. 3. 실습 후 실습 경험에 대한 발표 및 보고서 작성을 통해 경험을 성찰하고, 심리학도의 직업윤리 및 역할에 대한 이해를 심화한다. 1. 심리학 이론의 실제 적용 경험 - 심리학 전공 수업에서 습득한 지식을 실무에 적용함으로써 이론과 실제 간의 연계를 경험한다. 2. 심리학 직업군에 대한 이해와 진로 탐색 기회 제공 - 다양한 실습 기관에서의 실무 경험을 통해 심리학 관련 진로(임상심리사, 상담사, 연구원 등)에 대한 실질적인 이해를 돕는다. 3. 심리학도로서의 직업윤리 및 책임 의식 함양 - 실습 과정에서 요구되는 기본 태도, 대인 관계 능력, 윤리적 판단력을 갖추고, 전문가로서의 정체성을 형성한다.', '{"사례","심리학","경험","진로","실제","현장","경험을","사례에","가능한","기관","전공","탐색","윤리적","병원","실무의","임상","영역","질의응답","동료","자기평가"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209708', '인터랙션디자인', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '노기영', '디지털콘텐츠는 사용하는 사람과 둘러싼 환경에 따라 적절한 사용경험(user experience)을 제공할수 있어야 한다. 터치, 음성, 동작인 식등 다양한 인터페이스의 개발과 구현으로 콘텐츠기획과 제작에서 사용자와의 인터랙션이 매우 중요한 과제가 되었다. 이교과목은 미디어테크놀로지의 인터랙션의 탐구를 통해 사용자경험을 디자인하는 것이 무엇인지 어떠한 요소가 중요한지를 기초적으로 이해하 고 학습하게 된다. 지식 - 교과목을 통해 HCI와 인터랙션디자인에 대해서 지식을 얻게 됩니다. - 교과목을 통해 인터랙티브미디어와 인터랙션디자인에 대해서 이해를 하게 됩니다. 기술 - 스마트폰, 모바일게임, 인터넷쇼핑등 다양한 인터랙티브미디어의 사용자인터페이스를 이해하고 평가할수 능력을 갖추게 됩니다. 태도 - 인터랙션디자인의 기초개념을 통한 사용자중심 미디어와 인터페이스 디자인에 대해 관심을 갖도록 합니다. - 사회적 약자를 위한 미디어 디자인과 인터페이스 디자인을 위한 방법에 대한 우선적 관심을 갖게 됩니다. - 우리사회의 미디어의 미래에 대해서 인간적 관점에서 파악하게 되고 긍정적인 사고를 갖게 됩니다.', '{"개요","인터페이스","무엇인가","인터랙션디자인의","디자인","사용자경험","인터랙션디자인이란","인터랙션디자인과","인터랙션","유형","됩니다","무엇을","디자인과","이해와","개념화","개념적","모델","주차","구성요소","데이터"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202102', '사회조사방법론', '사회과학대학', '사회과학대학', 0, 3, '전선', '김영범', '이 강좌는 사회 과학적 연구에서 중시되는 연구 방법론 중의 하나인 사회 조사 방법론을 다룬다. 사회 조사는 사람들의 행동과 생각 을 포함한 다양한 사회 현상을 설명하기 위해 경험적 증거를 모으는 것이다. 사회 조사 방법론은 사회 조사를 과학적으로 수행하고 결론을 도출하는 방법 전반에 관한 논의를 뜻한다. 다룰 세부 주제는 대략 다음과 같다: 연구의 과정, 요소, 연구 방법, 자료 수집 방법, 질문지 설계, 표집(표본 추출), 측정, 척도, 분석, 조 사 관리, 보고서 작성 등. 이러한 대주제들을 기초로 수강생들의 이해도에 따라 소주제들이 가감될 것이다. 이러한 교과 과정은 이후 사회 과학 방법론을 통계적 분석 방법 등 더욱 높은 수준에서 공부할 계획, 사회 조사 분석사 자격증 준비 등에 도움이 될 것이다. 이 강좌는 사실상 사회학 전공 학생들에게 사회 통계, 분석 실습 관련 강좌의 선수 학습 내용이 되기도 한다. 사회조사는 사회생활을 체계적으로 관찰하여 이들 가운데 일정한 유형을 찾아내고 이해하려는 목적을 갖는다. 본 수업은 과학적 이 해를 위한 방법과 절차를 학습함으로써 연구자로서, 그리고 타인의 연구를 이용하는 소비자로서 학생들의 능력을 배양하는 것을 그 목적으로 한다.', '{"자료","이해한다","교재","질적","방법을","주차","논리와","아래","참조","조사","절차를","무엇인가","양적","방법의","탐구의","고려해야","탐구와","표집의","논리","학습한다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209722', '캐릭터디자인기획', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '권재웅', '-타 분야와의 연계성이 높은 캐릭터 산업에 대한 이해를 도모. -캐릭터에 대한 자체적 기획 능력을 키울 기반 구축. -이론과 실무를 균형 있게 다루고자 한다. -따라서 이론 수업이지만 이론과 함께 실습에 해당되는 과정이 포함되어 있음. -지식: 캐릭터 산업 전반 및 캐릭터 기획 과정에 대한 이해 -기술: 캐릭터 동향에 대한 분석 능력 양성 및 캐릭터 기획에 대한 경험 축적 -태도: 캐릭터 기획 관련 과정의 참여 성실도', '{"캐릭터","캐디기","교수제작","강의자료","가이드북","기획","캐릭터의","사례","개념과","기획과","분석을","통한","유형","변천과","성공사례","기호와","의미작용론","설정","개발","구성"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209734', '영화론', '미디어스쿨', '미디어스쿨', 0, 3, '전선', '박승현', '영화는 탄생 이후 장편의 시대를 맞이하면서 이야기를 구성하는 매체가 되었다. 이후 영화는 산업이 되었고 또한 예술이 되었다. 이 강좌는 영화의 산업적 측면과 예술적 측면 모두에 대한 이해를 높이는 데 초점을 맞추고 있다. 산업적 측면은 제작, 배급, 그리고 상영 부문을 모두 아울러서 논의를 진행하고자 한다. 또한 영화는 이야기를 구성하고 전달하는 매체라는 데 초점을 맞추어 스토리 구성을 둘러싼 특성을 리뷰하고 논의를 진행하고자 한다. 이 강좌의 목적은 영화의 산업적 측면과 예술적 측면에 대한 이해를 높이는 데 있다. 이를 위한 구체적 강의의 개요는 이야기 구성을 통해 내용과 의미를 생성하고 유포하는 매체라는 점에 주목하여 내러티브의 형식적 체계, 할리우드 고전주의 스타일과 해당 스타일 이 아닌 형태의 것, 내러티브의 분열적 특성 등에 대한 논의를 진행하고자 한다. 스토리 구성의 역사적 측면, 주요한 변화와 쟁점, 관 객에게 주어진 이해의 형태 등에 대한 이해를 높이고자 한다. 그리고 산업적 영역을 다루면서 스튜디오 시스템을 둘러싼 산업의 구조 및 변화 그리고 산업 내 영역 별 특징, 그리고 최근의 트렌드 등의 산업적 측면을 전반적으로 다루고 이해를 높이고자 한다.', '{"강의계획서를","참고할","산업적","한다","이해를","그리고","영화는","논의를","진행하고자","이후","이야기를","되었다","또한","영화의","측면과","예술적","높이는","초점을","있다","매체라는"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202106', '인구와세대의사회학', '사회과학대학', '사회과학대학', 0, 3, '전선', '김영범', '인구변동은 사회의 변화를 촉발하는 기본적인 요인 중 하나로 미래를 예측하고 대비하기 위해서는 인구 변화를 인식하고 그 영향을 이해하는 것이 매우 중요하다. 본 수업에서는 인구변동의 구성 요소인 출생, 사망, 이동의 과정을 이해하고 이를 바탕으로 다양한 사 회현상을 이해하는 역량을 축적한다. 본 수업을 통해 인구 변천의 역사적 과정을 이해하고, 출생, 사망, 혼인 등 인구학의 기본 요인과 관련된 사회, 구조적 원인을 학습한 다. 특히 현재 직면하고 있는 가장 큰 사회 변동 요인 중 하나인 인구 고령화의 추세와 그로 인한 사회적 영향을 학습한다. 인구 변동의 기본 요인을 이해한다. 인구학의 기본 개념과 측정 방식을 이해한다 고령사회의 추세와 그 영향을 이해한다. 출생 사망관련 요인과 그 변화 내용을 이해한다 인구 변동이 소득불평등, 건강불평등 등 사회현상과 어떻게 관련되어 있는지 이해한다', '{"인구","게시판","자료","학습한다","살펴보고","자료를","영향을","이론을","경험","이에","이해한다","어떻게","사망","한국","변동에","구성요인","무엇인지","사회의","출생","이를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202138', '사회학원론', '사회과학대학', '사회과학대학', 0, 3, '전선', '엄한진', '사회학 입문과정으로서, 사회학과 신입생들을 대상으로 설계된 전공 필수 교과목이다. 사회학의 연구대상과 연구방법, 사회학사와 현 대 사회이론, 사회학 각 영역별(문화, 인구, 환경, 젠더와 가족, 산업과 노동, 계급과 불평등, 다문화, 사회운동 등)의 주요 쟁점들을 학 습한다. 이 강의를 통해 학생들은 사회학 전공자로서 가져야 할 기본적인 소양을 쌓고 이후 전공심화 학습을 위한 기초 역량을 갖춘 다. 사회학이라는 학문의 기본을 익히기 위해 필요한 이론과 현실을 종합적으로 소개하는 것을 목표로 한다.', '{"교수","엄한진","사회학","김영범","게시판","자료","김미영","아젠다","김정환","문화","인구","환경","가족","노동","불평등","사회운동","질의응답","현대사회","국가","복지"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469003', '공학수학2', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '공통전선', '이종완', '공학수학은 반도체.디스플레이스쿨에서 배우게 되는 여러가지 기초 교과목(전자기학, 양자역학, 열물리, 고체물리학 등)들의 수학적 기반을 다루는 교과목이다. 공학에서 다루는 여러가지 물리를 이해하는 가장 확실한 방법이 수학이라는 언어를 통하여 얻는 것이다. 여기에는 벡터 개념과 행렬 그리고 복소수와 푸리에 급수등을 들 수 있다. 아울러 모든 물리 법칙들이 미분 방정식으로 표현되기 때 문에 상미분 방정식과 편미분 방정식을 배우게 된다. 따라서 공학수학2에서는 상미분 방정식 중에서도 1, 2계 미분 방정식 그리고 미 분 방정식의 급수해에 대해서 알아본다. 또한 벡터 다음으로 중요한 수학적 도구인 행렬을 다룬다. 다음 항목들을 배우게 된다. - 1계 미분방정식 - 2계 미분방정식 - 미분방정식의 급수해 - 행렬과 1차 연립방정식', '{"일반","퀴즈","연습문제","미분방정식","연립방정식","방정식","행렬과","행렬","미분방정식의","급수해","응용","비제차","배우게","선형","여러가지","교과목","수학적","다루는","벡터","그리고"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202217', '젠더와사회', '사회과학대학', '사회과학대학', 0, 3, '전선', '김하영', '본 강의는 젠더를 개인의 문제가 아닌 사회 규범과 제도, 그리고 권력관계 속에서 이해함으로써 사회구조에 대한 비판적 인식을 함양 하는 데에 목적이 있다. 이를 위해, 페미니즘 이론과 개념을 학습하고 젠더 관련 쟁점들을 토론하여 다양한 위치에서 경험되는 불평 등을 이해할 수 있다. 본 강의의 전반부에서는 페미니즘 이론과 개념을 학습하여 젠더 불평등을 독해하는 데에 필요한 기본 틀을 이해할 수 있다. 본 강의 의 후반부에서는 젠더에 관한 쟁점들을 토론함으로써 성평등한 사회로 나아가기 위한 대안을 모색할 수 있다. 본 강의의 목표는 현대 사회를 살아가는 사람들의 삶과 경험을 이해함으로써 스스로가 가진 특권과 소수성을 비판적으로 성찰하는 데에 있다. 이를 통해, 타인이 겪는 차별과 배제가 무엇인지 이해하고, 더 나은 사회로 나아가기 위한 대안은 무엇인지를 제시할 수 있 다.', '{"있다","등에","바탕으로","참여하는","횟수에","따라","참여도","점수에","반영","학습할","내용을","비판적으로","무엇인지","자료를","독해한","개별적으로","발표한다","별도의","자료","개념을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469004', '반도체기초공정', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '공통전선', '장문규', '반도체 공정에서 가장 기초가 되는 진공 개념에 대하여 학습하고, 박막을 형성하고, 박막재료의 전기적, 기계적 특성을 이해하는 반도 체 공정의 가장 기초 교과목으로, 진공의 원리, 진공 장비의 기초, 박막재료 증착법 (스퍼터링, 화학기상법등), 물성평가법 등에 대한 강의 한 내용을 학습함. 나노공정을 본격적으로 다루기 위한 기초이론을 학습하는 교과목으로 학부 1학년에서 일반 물리, 일반 화학, 일반 수학 및 공학수학 등의 기초 교과목의 사전 수강을 추천 함. 수업은 강의와 과제로 이루어지며, 2회의 시험 (60%)과 과제(20%) 및 출석 (20%)으로 평가한다. 반도체 공정을 수행하기 위하여 필요한 기초 지식을 습득하는 것을 목표로 한다. 청정실의 구성, 청정실 사용방법, 진공 게이지 및 펌 프의 원리, 플라즈마 및 스퍼터링을 이용한 박막 증착법 및 이를 분석하는 방법에 대하여 이해한다.', '{"진공","일반","반도체","가장","대하여","교과목으로","증착법"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202303', '환경사회학', '사회과학대학', '사회과학대학', 0, 3, '전선', '김미영', '본 수업의 목표는 사회와 자연의 상호작용에 대한 환경사회학적 논의를 이해하고 환경문제의 구조적 원인과 해결방안을 스스로 찾을 수 있는 능력을 키우는 것이다. 환경문제의 현황을 여러 사례를 통해 살펴보고, 환경문제의 발생 원인을 환경사회학 이론을 통해 체 계적으로 분석해본다. 나아가 위험사회, 환경정의, 생태민주주의 등 주요 개념들을 살펴보고, 기존 사회학 이론과 접점을 찾아본다. 강 의 후반에는 최근의 환경 정책의 수단과 환경문제의 해결방안에 대한 논의들을 살펴보고, 합리적인 실천 방안을 모색한다. 본 강의는 환경사회학 이론과 관련 논의를 통해 자연과 인간, 자연과 사회의 상호작용에 대해 이해하는 눈을 키우고 더 나아가 지속 가능한 위환경문제의 해결방안을 모색해보는 것을 목표로 한다.', '{"환경","환경문제의","환경과","정책의","인가","성장의","한계","환경문제는","발생하는가","원인","지구환경문제의","역사","관계","에너지","전환","환경적","환경행동의","개념과","살펴보고","환경정의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202315', '정치사회학', '사회과학대학', '사회과학대학', 0, 3, '전선', '최윤재', '본 수업은 정당정치, 민주주의, 시민사회 중심의 정치사회학을 출발점으로 삼되, 그 분석 범위를 한층 확장하는 데 목적이 있다. 전통 적인 정치사회학은 민주주의의 성장, 시민사회의 형성, 정당정치의 제도화, 신자유주의의 확산과 같은 거시적 축을 중심으로 정치의 영역을 설명해 왔다. 이러한 접근은 정치가 작동하는 구조적 조건을 이해하는 데 중요한 통찰을 제공해 왔으나, 정치가 일상적 인간 관계 속에서 어떻게 형성·재생산되는지에 대해서는 상대적으로 충분히 포착하지 못한 한계도 지닌다. 본 수업은 정치란 국가나 제도에 국한된 것이 아니라, 개인과 개인 사이의 관계, 소집단 내부의 역학, 집합의 형성과 해체 과정 속에 서도 끊임없이 생성되는 사회적 관계라는 문제의식에서 출발한다. 이를 위해 정치사상의 고전과 사회학의 고전 이론을 토대로 정치 와 권력의 개념을 검토하되, 특정 이론 하나에 종속되기보다는 다양한 이론적 관점을 비교·검토하며 정치사회학의 다층적 성격을 드 러내는 데 초점을 둔다. 이와 동시에, 현대 사회에서 권력이 가장 일상적이고 제도적으로 작동하는 대표적 장치로서 관료제와 제도적 권력의 문제를 중요한 분석 대상으로 다룬다. 이를 통해 수강생들은 정치가 추상적인 제도의 문제가 아니라, 자신이 속한 관계와 사 회 속에서 이미 작동하고 있는 현실임을 이해하게 될 것이다. ？ 학습자는 정치사회학의 주요 이론과 개념을 바탕으로, 정치가 개인의 일상적 인간관계에서부터 집단, 국가, 세계질서에 이르기까 지 어떻게 형성되고 작동하는지를 사회학적 관점에서 이해하고 설명할 수 있다. ？ 학습자는 정치적 현상을 단일한 원인이나 단순한 인과관계로 환원하지 않고, 미시와 거시, 구조와 행위, 사조와 이념이 상호 조응 하는 복합적 과정으로 분석하는 관점을 습득할 수 있다. ？ 학습자는 본 수업을 통해 정치와 사회에 대한 비판적 사고력을 기르고, 자신의 경험과 사회적 현실을 정치사회학적으로 해석하여 논리적으로 표현할 수 있다.', '{"어떻게","정치","주차","정치적","국가","정치가","이를","살펴본다","논의를","권력이","주차에서는","과정을","권력과","시장","특히","알고리즘이","알고리즘","넘어","미래","공공성의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469011', '표면분석기기및응용', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '공통전선', '이종완', '반도체와 디스플레이 분야에서 사용되는 여러 가지 소재들과 다양한 공정들에 따라 소자의 특성이 변하고 있다. 이와 같은 특성 변화 는 물질의 표면과 계면에서 일어나는 여러 가지 물리,화학적 변화에 그 근거를 두고 있다. 이와 같은 변화를 규명하기 위해서는 표면 분석기기를 이용하여 표면이나 계면의 물성을 필히 알아야 한다. 본 교과목에서는 물질의 표면과 대표적인 5개의 표면분석기기(XPS, AES, SIMS, RBS, AFM)에 대해서 자세히 알아본다. 표면분석기기에 대한 지식은 반도체나 디스플레이를 전공하거나 연구 및 개발하는 공학자들에게는 필수적이다. 아울러 표면분석기기를 직접 다루는 공학자의 길을 밟을 수도 있다. 이 교과목을 통해 학습자는 다음과 같은 항목들을 습득하게 된다: 1. 표면과학 개론 2. 실험조건 및 장치 3. 표면의 기하학적 구조 및 전자상태 4. 입자와 표면과의 상호작용 5. XPS: X-ray Photoelectron Spectroscopy (X-선 광전자 분광법) 6. AES: Auger Electron Spectroscopy (오제이 전자 분광법) 7. SIMS: Secondary Ion Mass Spectrometry (이차 이온 질량 분석법) 8. RBS: Rutherford Backscattering Spectroscopy (러더포드 후방산란 분광법) 9. AFM: Atomic Force Microscopy (원자힘 현미경) 10. 응용: 분석 사례', '{"강의록","과제물","분광법","광전자","표면분석","서론","화학의","세계","표면분석기술","이용한","응용_","표면과학","전자","이차","러더포드","후방산란","물질의","장치","분석사례","양자물리학"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202502', '청소년활동', '사회과학대학', '사회과학대학', 0, 3, '전선', '전성원', '1. 청소년활동의 개념 및 이론을 이해한다. 2. 청소년활동의 원리를 이해한다. 3. 청소년활동에 대한 접근방법을 이해한다. 4. 청소년활동의 지도방법에 관한 실제를 이해한다. 5. 실제 현장에서 일어나는 청소년활동을 어떻게 지도하고 있는지 직접 경험하고 연습하는 기회를 갖는다. 청소년의 긍정적 성장과 성공적인 성인기로서의 삶을 준비하는 청소년화 함께하고자 하는 청소년 지도사로서 갖추어야 할 전문지식 을 습득하고, 청소년활동과 관련된 전문지식과 실천적 안목을 함양하여, 시대적 변화의 흐름에 맞추어 청소년의 능동적인 참여를 유 도할 수 있는 청소년지도사로서 성장할 수 있도록 하고자 함이다', '{"청소년활동의","청소년","청소년활동","구두평가","실제","개념과","디지털","논술퀴즈","청소년의","영역","구성요소","스포츠활동","실체","이해한다","변화와","특성과","청소년활동지도자의","유형","청소년활동시설","프로그램의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469014', '콜로키움2', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 1, '공통전선', '장문규', '반도체 및 디스플레이, 더나아가 양자기술 분야의 각계 전문가로 부터 현재의 기술을 소개하는 교과목으로 학생들은 최신의 기술 트 랜드를 배울 수 있다. 학생들은 수업 후 A4지 한장 분량의 내용을 요약하여서 수업 후 제출하여야 함. 반도체 및 디스플레이, 더나아가 양자기술 분야의 각계 전문가로 부터 현재의 기술을 소개하는 교과목 따라서, 최신 기술 동향 파악 및 진로에 활용이 주요 목표임', '{"콜로키움","반도체","디스플레이","더나아가","양자기술","분야의","각계","전문가로","부터","현재의","기술을","소개하는","학생들은","기술","참고자료","특이사항","없음","주재","주재별","발표자료"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202512', '사회학명저읽기', '사회과학대학', '사회과학대학', 0, 3, '전선', '엄한진', '본 교과목은 사회현상에 대한 사회학적 접근을 잘 보여주고 학생들의 관심에 부합하며 가독성이 높은 명저 3권을 선정해 학생들의 발표와 사전 리뷰를 활용하는 토론 등으로 진행하는 수업으로 독서모임과 같은 방식으로 운영된다. 학술적인 서적 읽기, 읽으면서 소감과 질문 만들기, 수업시간에 토론에 참여하기, 자신만의 방식의 책 소개글 작성해보기', '{"저작","자료","질문","저자","발제","교재","쪽지","사회학","답변","학생들의","잡변","중간고사","사회힉"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469016', '회로이론및실습', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '공통전선', '윤영준', '반도체/디스플레이 공학 분야에 처음 입문한 공학도가 회로의 기초 개념을 정확하게 이해하고, 단순한 회로뿐만 아니라 복잡한 회로 까지 정확하게 해석할 수 있는 기본 및 응용 능력을 기를 수 있도록 한다. - 회로의 기본소자인 저항 (R), 인덕터 (L), 커패시터 (C) 및 전원 등 수동 소자와 능동 소자의 개념 및 전류와 전압의 수학적 관계를 이 용하여 직류 회로 및 nodal/mesh 해석 등에 관한 역량을 확보한다. - 학습한 내용을 기반으로 SPICE 실습을 통해 회로 해석 (simulation) 역량을 확보한다. 회로 이론에 대한 지식을 습득하여 반도체/디스플레이 공학에 필요한 전기 회로 해석 역량을 확보한다. 반도체/디스플레이 공학의 기초가 되는 전기 회로의 해석에 필요한 기본 이론 지식 함양 - 회로의 기본소자인 저항 (R), 인덕터 (L), 커패시터 (C) 및 전원 등 수동 소자와 능동 소자의 개념 이해 - 전류와 전압의 수학적 관계를 이용하여 직류 회로 및 nodal/mesh 해석 이해', '{"자료","예정","회로","회로의","반도체","해석","중간고사","퀴즈","디스플레이","역량을","확보한다","정확하게","기본소자인","저항","인덕터","커패시터","전원","수동","소자와","능동"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203222', '지역사회복지론', '사회과학대학', '사회과학대학', 0, 3, '공통전선', '서인해', '지역사회복지론은 지역사회를 개입의 단위로 삼는 사회복지의 다양한 접근법들을 섭렵하되, 특히 전문적 지역사회실천의 과정에 관 한 이론과 기술의 학습에 역점을 두는 교과목이다. 따라서 지역사회 및 그 구성원들이 지니는 사회적 문제와 욕구의 해결에 관여하 는 사회복지사가 갖추어야 할 자질과 역량을 키우는 데 필요한 내용으로 교과목을 구성한다. 이를 위해서 지역사회복지 관련 주요개념과 역사 및 기초이론 등에 대한 이해를 비롯하여, 전문적 지역사회복지실천의 원칙, 모형, 과정, 기술 및 사회복지사의 역할 등 전문적 접근에 필요한 핵심사항들을 전반부에서 다룬다. 이어서 후반부에서는 변화하는 지역사 회 현실과 그것이 담고 있는 문제 및 욕구를 규명하고, 거기에 대응하는 아양한 지역사회복지 접근법 및 추진체계들을 비판적으로 검 토하면서, 전반부에서 학습한 내용을 지역사회복지 실천현장의 실제사례에 적용함으로써 합당한 대안을 강구해 보도록 한다. 1. 지역사회복지와 관련된 개념, 역사, 이론 및 실천기술을 습득한다. 2. 우리나라 지역사회복지 실천기관 및 조직에 대해서 이해한다. 3. 우리나라 지역사회복지의 실천현장에서 나타나는 다양한 이슈를 이해하고 분석하는 능력을 배양한다.', '{"오정수","조활동","지역사회복지","지역사회복지의","실천현장에","역사","요약","거시적","강의와","지역사회","기술","지역사회복지실천의","우리나라","지역사회복지실천","현장의","주차","구성요소","지역사회복지실천모델의","지역사회실천모델","실천의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('202529', '공간과 일상의 사회학', '사회과학대학', '사회과학대학', 0, 3, '전선', '김미영', '- 본 수업은 우리 주변의 일상 공간에 대한 문화사회학적 분석을 시도한다. - 수업에서 다루는 공간은 특정한 경계나 지역적 범주를 말하는 것이 아니다. 대신 그것은 ‘공간소’(空間素)의 개념에서 출발한다(김홍 중, 2012 참조). 공간소는 더 이상 나눌 수 없는 공간의 기본단위로서, 거의 동일한 구조를 갖고 있으며, 곳곳에 편재하면서 유사한 기 능을 수행하는 일종의 공간적 ‘장치’(dispositif)다. 아파트, 백화점, 호텔, 광장, 공장, 박물관, 미술관, 공연장, 기차역, 지하철, 카페, 편 의점, 노래방, 공항 등이 도시의 대표적 공간소이다. - 이 수업에서는 편의상 공간을 주거 공간, 식음(食飮) 공간, 숙박 공간, 소비 공간, 모빌리티 공간, 지식·문화공간, 노동 공간으로 대별 하고, 이들을 대표하는 몇 가지 공간소에 대해 집중적으로 살펴보고자 한다. 1) 공간 사회학의 기초적인 이론과 개념을 습득함으로써, 풍부한 감수성과 예리한 통찰력으로 도시 공간을 해석하는 능력을 함양함 2) 우리 시대 사회과학의 ‘공간적 전환’(spatial turn)을 우리가 살고 있는 도시적 삶의 구체적 장소 통해 개괄함', '{"공간","사회학적","이해와","해석","공간에","식음","모빌리티","카페","주거","숙박","소비","지식","공간적","일상성","라이프스타일과","레스토랑","문화","일상","공간의","아파트"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('502206', '전자기학I', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '공통전선', '박두재', '나노과학기술 전반에서 필수 기초 지식인 전자기학 관련 기초 지식 습득을 목적으로 함. 특히 연구 및 산업 현장에서 주로 활용되는 지식 위주로 문제 풀이 중심의 학습을 통해 실무 적용성을 강화하며, 시각적 이해를 위한 다양한 도구를 활용여 이해도를 높임. 전자기학의 기초지식 함양 1. ''장''의 개념 이해 2. 전기장 내에서의 전하의 반응 이해 3. 경계조건이 주어진 시스템에서의 전기장 4. 자기장의 이해 5. 자기장 내 전하의 반응 6. 전기장 내 움직이는 전하의 반응', '{"주교재","연습문제","전기장","물질","내의","해결법","좌표계","전기장의","전하","중간고사","대체","자기","전하의","자기장","구면","법칙을","이용한","산출","때의","전기장과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469202', '디스플레이공정', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '전선', '박재훈', '과거 브라운관 한가지로 대표되던 디스플레이 제품에 크기, 무게, 두께, 화면의 선명성, 저소비 전력 등의 다양한 요구는 기술개발과 디스플레이 시스템 발달의 원천이었다. 또한 현대인들은 더욱 간편하고 기능이 다양하고 값이 싸고, 질이 좋은 전자 제품을 원하게 되었으며, 특히 휴대성이 고도화된 정보 장치를 요구하게 되었다. 이러한 기술적, 사회적 요구에 따라 정보표시장치 영역에서 평판디 스플레이는 전체 디스플레이 시장을 주도하게 되었으며, 그 기술은 최첨단 반도체 기술을 바탕으로 물리, 전기, 전자, 기계, 재료, 화학 등의 다양한 학문의 응용과 기술개발에 근거를 두고있다. 따라서 QLED, OLED 등 첨단 디스플레이 산업의 역량 인재로 성장할 수 있도록 본 과목은 디스플레이 장치의 개념, 원리, 공정, 제조 장치에 이르는 핵심 과정을 학습하도록 한다. - 평판 디스플레이 개념 이해 - 디스플레이 구조 및 원리 이해 - 디스플레이 제조 공정 및 제조 기술 이해 - 차세대 디스플레이 기술 이해', '{"디스플레이","공정","강의록","기술","제조","구조","유기","발광","평판","패널","터치","스크린","반도체","회로","구동","액정","동작원리","플렉시블","시스템","재료"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203101', '사회복지학개론', '사회과학대학', '사회과학대학', 0, 3, '공통전선', '권종희', '사회복지학 개론의 교육목표는 사회복지의 개념, 가치, 역사, 실천방법 등 사회복지 전반을 이해하고, 사회복지사로서의 기본 자질을 기르는 것이다. 주요교육목표는 첫째, 사회복지의 개념과 목적, 영역, 분야를 이해하고 설명할 수 있다. 둘째, 사회복지의 가치와 윤리, 역사적 발달 과 정을 파악한다, 셋째, 사회복지 실천의 개념, 목표, 기본원칙 및 실제 적용방법을 습득한다. 넷째, 지역사회복지, 사례관리, 정책 행정 등 다양한 분야를 이해 한다. 다섯째, 현대사회복지의 쟁점과 발전방향 탐색, 전문성 향상이다. 교과목표 첫째, 사회복지의 개념과 이론, 역사, 가치를 체계적으로 이해한다. 둘째, 사회복지에 대한 전문적 시각과 비판적 사고력을 함양한다. 셋째, 사회복지 실천의 개념, 목표, 기본원칙 및 실제 적용방법을 습득한다. 넷째, 지역사회복지, 사례관리, 정책 행정 등 다양한 분야를 이해 하고 적용한다. 다섯째, 현대사회복지의 쟁점과 과제를 분석하고 발전방향에 대해 모색한다.', '{"있다","이해하고","대해","사회복지의","사회복지","설명할","적용할","개념과","복지국가의","아동복지의","욕구에","조별발표","조별","역사","실천의","구성요소","조사와","중간고사","자원봉사활동의","발달배경"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469203', '나노포토닉스', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '전선', '이종민', '최첨단 반도체 공정기술로 구현된 10 nm급 대면적 나노패턴을 사용하여 기존 광학계에서는 원리적으로 구현 불가능했던 소자들이 (예: 초고감도 SERS 센서, 메타렌즈, 양자광원 등...) 출현하고 있다. 본 교과목은 이들의 원리(특성 분석), 공정 방법, 응용에 대해 통합 적으로 살펴보는 것이 목표이다. 이를 통해 학생들이 미래 반도체 산업 분야 진출을 준비하기 위해 필요한 내용을 학습할 것이다. - 수업 관련 내용에 대한 최신 동향 파악을 위해 관련 분야 논문에 대해 학생 발표를 진행하여 심도 있는 지식 함양을 추구한다. - 본 과목은 첨단산업 인재양성 부트캠프 사업의 일환으로 산업계 전문가가 교육과정에 참여한다. - 나노구조 주변의 전자기장 여기현상 이해 - 표면플라즈몬 광학계의 이해 - 양자점의 원리, 제조방법, 광학적 특성 및 응용 분야 - 상기 내용과 관련한 연구동향 파악능력 함양 - 기타 나노광학 첨단연구동향 파악능력 함양', '{"중간고사","단일","양자점의","자료","표면","광원","대해","분야","플라즈몬에","기초이론","국소","산업에서","사용되는","공정","제조방법","나노포토닉스","반도체","위해","파악능력","표면플라즈몬의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203115', '사회복지실천론', '사회과학대학', '사회과학대학', 0, 3, '공통전필', '고정애', '1. 사회복지의 실천의 목적과 기초이론을 이해한다. 2. 사회복지 실천의 가치와 윤리를 이해한다. 3. 사회복지사의 다양한 역할을 이해한다. 4. 클라이언트와의 관계형성 방법과 면접기술을 습득한다. 5. 사회복지 실천과정과 개입방법을 이해한다. 6. 현장실습을 통해 사회복지 실천, 특히 사례관리방법을 연습한다. I. 교과목에서 목표로 하는 지식 1. 사회복지의 목적과 기초이론 2. 사회복지의 가치 및 실천윤리 3. 사회복지발달의 역사 4. 사회복지사의 다양한 역할 5. 클라이언트의 관계형성 방법과 면접/상담법 6. 사회복지실천의 과정 7. 사례관리 8. 현장실습 II. 교과목에서 목표로 하는 기술 1. 사회복지사의 다양한 역할수향을 위한 기술 2. 클라이언트와의 관계형성기술 3. 면접과 상담기술 4. 사회복지실천과정에 필요한 실천기술 2. 교과 목표 ■ 교과목표 5. 사례관리기술 III. 교과목을 수강하는 학생의 태도 1. 사회복지실천지식과 기술을 능동적으로 학습하기 위한 주도성, 창의성 2. 예비사회복지사로서의 자아성찰 3. 소그룹활동에서 동료학생을 배려하는 협동심과 적극적으로 참여하려는 태도 4. 현장사례실습에서의 성실성과 수퍼바이저로부터 배우려는 수용적인 태도 5. 클라이언트를 위한 열의와 비밀보장, 윤리의식', '{"사회복지","이해한다","롤플레이","실천의","교과서","사회복지실천과정","윤리와","실천과정","개입","가치","역사","사회복지실천의","특징을","가치를","특강","면접의","주차","사회복지의","사회복지사의","사례관리"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469210', '디스플레이재료물성', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '전선', '박재훈', '전자재료는 국가 주력산업인 반도체, 디스플레이, 센서 기술과 밀접한 관계에 있으며, 화학, 물리학, 재료공학 및 전기/전자공학 등 폭 넓은 학문 분야에서 주요 교과목으로 운영되고 있음. 따라서 반도체디스플레이스쿨의 디스플레이전공 심화 학습이 시작하는 3학년을 대상으로 ‘디스플레이재료물성’ 과목을 통해 디스플레이 재료의 발광 현상 및 소자의 동작 원리를 이해하는데 필요한 물성분야 교육 을 수행하고자 함. 이로써 반도체디스플레이스쿨의 디스플레이전공 교육 과정을 체계화 시킬 수 있을 것으로 기대됨. 본 강의에서는 반도체/디스플레이 공학의 입문 과정으로써 고전 물리학과 양자역학에 기초하여 금속, 절연체, 반도체 물질의 성질을 학습하고 이로써 전자의 거동과 현상, 광학적 현상을 이해하고자 한다.', '{"강의록","현상","에너지","디스플레이","물질의","분자","거동","에너지적","전자","응용","반도체","전기","광학적","고체의","고체","결정의","고체내의","소자","방출","현상과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203116', '사회복지현장실습', '사회과학대학', '사회과학대학', 0, 3, '공통전선', '이아영', '1. 사회복지실천, 사회복지정책, 사회복지행정 등 학교에서 배운 이론을 사회복지실천현장에서 실습을 통해 경험함으로써 이론과 현 장을 연결한다. 2. 다양한 사회복지기관의 행정과 프로그램 실천을 통해 문제해결 방법과 사회복지 현장의 실태를 이해한다. 3. 사회복지사의 역할 및 가치를 인식하고 본인의 전공 적합성을 검토한다. 1. 사회복지실천, 사회복지정책, 사회복지행정 등 학교에서 배운 이론을 사회복지실천현장에서 실습을 통해 경험함으로써 이론과 현 장을 연결한다. 2. 다양한 사회복지기관의 행정과 프로그램 실천을 통해 문제해결 방법과 사회복지 현장의 실태를 이해한다. 3. 사회복지사의 역할 및 가치를 인식하고 본인의 전공 적합성을 검토한다.', '{"단계","사회복지실습에서의","실제","기술","사회복지현장실습","사회복지실천","사회복지정책","사회복지행정","학교에서","배운","이론을","사회복지실천현장에서","실습을","경험함으로써","이론과","장을","연결한다","사회복지기관의","행정과","프로그램"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469209', '반도체분석장비부품', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '전선', '박두재', '반도체 및 디스플레이 시험 평가 및 검증에 활용되는 기초광기구, 특히 광다이오드, PMT, CCD, LED 등 산업현장에서 널리 쓰이는 광 기구의 작동원리, 시장에서 활용되는 주요 제품 특성 분석 등을 통해 국내 소재/부품/장비 산업에 필요한 실무적 인재를 양성 - 오실로스코프, 전압 발생기, 광다이오드, PMT, CCD, LED, 각종 레이저, 분광기 등 시험 평가 장비에 사용되는 기초 광기구의 작동원 리를 학습함 - 산업적으로 응용되는 기초 광기구들의 specification data를 분석함으로써, 각 광기구들의 응용 범위를 학습하고 산업 분야에 따른 적용 사례를 학습함으로써 실무적 활용 능력을 함양함', '{"교안","작동원리","제품","레이저","스펙","강의교안","광다이오드","비교분석","학생발표","특수","중간고사","분광기","광다이오드의","비교","활용분야","분야","미소광량분석","레이저의","활용되는","실무적"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203203', '사회복지정책론', '사회과학대학', '사회과학대학', 0, 3, '공통전필', '최균', '사회복지정책의 개념, 가치 및 이념, 역사, 구조 등을 이해하고, 경제와 복지와의 관계, 사회복지제도체계의 구성원리와 특징 등을 검 토한다. 또한 이를 바탕으로 복지국가를 지향하는 우리 사회에 적합한 사회복지모형을 설계한다. 사회복지정책에 관한 이해 도모', '{"사회복지정책의","구조","가치","역사","사상","사회복지정책발달론","복지이념","복지국가론","구성요소","등을","주차","중간고사","복지국가위기론","복지국가재편론","복지국가의","미래","대상","급여","재정","전달체계"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469301', '반도체공학1', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '전선', '장문규', '반도체 공학의 기초가 되는 내용으로 반도체 밴드 이론, 도핑, 다이오드 등의 내용을 학습한다. 반도체 공학 1의 학습 내용을 바탕으로 반도체공학 2의 후분부 내용을 학습하도록 설계되어 있음. 따라서, 반도체공학 1을 이수하고 반도체공학2를 이수하기를 추천함. -반도체의 이론적인 내용의 전반부 학습 -주요 학습 내용 : 밴드 이론 : 진성, 외인성 반도체 : 도핑 : 다이오드', '{"반도체","내용을","반도체공학","반도체의","외인성","판서","밴드","도핑","다이오드","밴드이론","진성반도체"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469302', '반도체부품개론', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '전선', '윤영준', '반도체 부품 (VLSI; Very Large Scale Intergrated Circuit) 설계의 핵심 이론과 실무 지식의 이해 - 반도체 회로의 기본 동작 원리와 특성 이해 (최소한의 수식만 제시) - MOSFET, CMOS inverter, Static/Dynamic Logic Gate, Sequential Logic Gate, Memory 회로 설계 반도체 부품 (VLSI; Very Large Scale Intergrated Circuit) 설계의 핵심 이론과 실무 역량 확보 - 반도체 회로의 기본 동작 원리와 특성 이해 (최소한의 수식만 제시) - MOSFET, CMOS inverter, Static/Dynamic Logic Gate, Sequential Logic Gate, Memory 회로 설계', '{"공유","반도체","동작","회로의","설계","집적회로","제조","지연","논리","회로","개요","공정","구성과","구조","구조와","시간","전달","게이트","사용되는","이를"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203302', '사회복지행정론', '사회과학대학', '사회과학대학', 0, 3, '공통전선', '최유석', '사회복지정책 및 실천이 실제로 이루어지는 과정은 다양한 행정적 지원에 의해서 가능하다. 정책대상자와 클라이언트에 대한 효과적 인 개입을 뒷받침하는 행정에 대한 이해는 필수적이다. 이 강의에서는 조직이론, 기관관리의 영역을 소개한다. 향후 사회복지기관 관 리자로서 효과적인 기관운영을 가능케하는 행정 및 조직운영에 관한 이해를 증진하고 관리능력을 개발하는 것이 이 강의의 목적이다 . 사회복지기관 관리자로서 필요한 기초적인 기관관리 지식과 기술을 습득한다.', '{"프로그램","조직이론","사회복지행정의","서비스","관리","사회복지기관","사회복지","전달체계","리더쉽과","의사결정","인사관리","재정관리","중간고사","주차","구성요소","기획","복지","홍보"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('469313', '포토공정실습', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '전선', '이종민', '포토공정실습은 반도체 및 나노소자 제조의 핵심 기술인 포토리소그래피(Photolithography)를 이론과 실습을 통해 체계적으로 학습 하는 교과목이다. 본 교과목에서는 렌즈와 거울을 이용한 프로젝션 광학계의 기본 원리, UV 광원의 특성, 포토레지스트(Photoresist) 의 화학적·물리적 거동을 이론적으로 이해하고, 이를 실제 공정에 적용하는 능력을 배양하는 것을 목표로 한다. 이론 수업에서는 해상도, 초점 심도, 수차, 노광 파장 등 광학적 설계 변수와 포토공정 조건 간의 상관관계를 다루며, 실습 수업에서는 마스크 정렬, 스핀 코팅, 소프트 베이크, UV 노광, 현상 및 패턴 관찰에 이르는 일련의 포토리소그래피 공정을 학생들이 직접 수행한 다. 이를 통해 학생들은 반도체 및 마이크로·나노 패터닝 공정의 실제 흐름을 경험하고, 공정 조건 변화가 패턴 품질에 미치는 영향을 분 석할 수 있는 실무 역량을 갖추게 된다. 본 교과목은 향후 반도체 공정, 디스플레이, MEMS, 나노소자 및 바이오칩 분야로의 확장 학 습을 위한 기초 실습 과목으로 설계되었다. 본 과목은 첨단산업 인재양성 부트캠프 사업의 일환으로 산업계 전문가가 교육과정에 참여한다. 본 교과목은 반도체 소자 제작의 핵심 단계인 포토리소그래피(Photolithography)의 원리와 공정 절차를 이해하고, 이를 실습을 통해 체득하는 것을 목표로 한다. 학생들은 포토레지스트 감광 원리, 노광·현상 과정, 마스크 정렬 및 패터닝 기술을 학습하며, 클린룸에서 스핀 코터, 마스크 얼라이너, 현상기 등을 활용해 미세 패턴을 직접 제작한다. 이를 통해 포토공정에 사용되는 광학·전자 부품의 작동 원리와 장비 특성을 이해하고, 반도체 소재·부품·장비(소부장) 분야에서 요구 되는 공정 운용 및 평가 실무 능력을 함양한다.', '{"노광","공정","광학","패턴","포토리소그래피","장비","능력을","중간고사","이해하고","이를","실제","회절","메커니즘을","설명할","기른다","반도체","핵심","해상도","포토공정","마스크"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203319', '프로그램개발과평', '사회과학대학', '사회과학대학', 0, 3, '공통전선', '서인해', '사회복지 프로그램은 사회복지 실천과정에서 문제해결 도구로서 매우 중요하다. 본 과목은 학생들에게 사회복지 프로그램 개발과 평가과정에 필요한 지식과 이론을 습득하게 하고, 이를 토대로 프로그램 개발과 평가과정을 실제적으로 연습할 수 있는 기회를 가지 게 한다. 이 과목을 통해서 배우는 구체적인 수업내용은 프로그램 개발과 평가의 역사, 프로그램 및 프로그램 구성의 기본적인 특징, 프로그램 개발에 적용될 수 있는 다양한 개발모형과 관련된 이론과 기술이다. 또한 수업시간에 편성된 조활동을 통해서 학생들은 사 회복지실천 현장에서 실제적으로 수행되고 있는 사회복지 프로그램 제안서작성을 작성하는 기회를 가짐으로서 사회복지사로서의 프 로그램 개발과 평가활동을 수행할 수 있는 역량을 배양한다. 사회복지 프로그램 제안서를 디자인하는 과정에서 ChatGPT적용하여 프 로그램 개발활동에서 AI활용능력을 강화한다. 1. 사회복지 프로그램 개발과 평가와 관련된 개념, 역사, 이론 및 실천기술을 습득한다. 2. 사회복지 프로그램 개발 제안서를 작성할 수 있는 기술을 습득한다. 3. 사회복지 프로그램 개발과정에서 AI활용 능력을 습득한다.', '{"프로그램","사회복지","제안서","석가탄신일","비봉축전","교수강의자료","프로그램의","개발과","강의자료","개발","이해한다","조활동","한다","평가의","강사의","구성요소","작성방법을","학습한다","작성법","활용에"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203206', '빈곤론', '사회과학대학', '사회과학대학', 0, 3, '전선', '조준용', '[주의] 본 교과목은 15주 수업 중 10주간을 팀프로젝트 및 협업, 발표를 중심으로 이루어지는 역량중심 인증교과목이다. 따라서 개인 발표와 팀프로젝트에 대한 기대 수준이 높고, 평가 기준도 이를 반영한다. 이러한 강의진행이 본인과 맞지 않을 경우 성적이 현저히 낮게 되므로, 수강 신청을 재고할 것을 권한다. 본 과목은 우리사회의 빈곤에 대한 현황과 이론을 습득하고, 문제해결을 위한 정책적 실천역량을 향상하는 것을 목표로 한다. 본 과 목은 사회복지 전공자를 위해 개설된 과목이며, 교양수업이 아니다. 본 과목은 애초 자기주도형 학습으로 개발되었으며, 2019년 역 량중심 실러버스 인증 교과목으로 발전하였고, 2023년 재인증 되었다. 주된 교수법은 팀(Team) 주도 학습(TBL)과 프로젝트(Project) 발표 및 토론으로 이루어진다. 본 과목을 수강하는 모든 학생들은 매주 사전에 디자인된 토론과 발표에 참가하고, 10주 이상 팀 모임 을 진행하여, 문제해결을 위한 집합적 노력을 구조화하는 과정을 경험한다. 자신의 의견을 발표하거나 팀과 협력하는 능력은 본 과목 에서 매우 중요하다. 참고로 이러한 발표의 중요성에 대해 이전 수강생은 다음과 같은 강의 평가를 남기기도 하였다. "발표가 자신없는 사람은 많이 생각해보고 들으세요" (2023년 수강생 중). "해야할 것들이 많은 편이라..." (2025년 수강생 중). 따라서 본 과목에 관심이 있는 사람들은, 반드시 강의 첫날 강의실에 출석하여 수업 소개를 듣고, 팀 중심의 수업 운영 방식과 발표 역량을 중시하는 본 과목이 본인의 기대와 맞는지 확인해야 한다. 경험적으로 강의소개를 듣지 않는 학생들의 경우, 수업 적응에 어 려움을 겪곤 하였다 한편, 교수자는 모든 팀에 속하여 팀 모임을 활성화하며, 학생들이 주도성을 발휘할 수 있도록 돕는다. 또한 빈곤과 관련된 주요 최신 현황과 혁신적 정책에 대한 최신 정보를 제공하여, 다양하고 집중도 높은 콘텐츠를 수업시간에 활용한다. 이를 통해, 궁극적으로 사회 복지현장에서 사회복지사로서, 빈곤의 다차원성에 대한 사정(assessment) 능력과 정책 활용 역량을 극대화할 수 있다. (교과목의 소개) - 1주차가 지난 후에, 수강인원 수와 팀구성 수에 따라 주차별 과업에 대한 미세 수정이 있을 수 있음 1. 사회복지의 가장 오래된 주제인 빈곤에 대한 개념과 이론, 그리고 그 실제를 총체적으로 파악하고, 정책적 접근을 통한 해결노력을 팀활동을 통해 학습한다. 보다 구체적으로 다차원적인 빈곤문제에 대한 개념적 접근을 바탕으로, 빈곤문제의 발생원인에 대한 이론 적 이해, 빈곤 현황에 대한 객관적 이해, 빈곤한 삶에 대한 현상학적 이해를 추구한다. 이를 바탕으로, 현대사회의 빈곤문제의 해결을 위한 혁신적 빈곤정책을 자기주도적으로 탐구해가며, 미래적 빈곤문제를 다룰 수 있는 빈곤전문가로서의 역량을 키우는 것을 목표 로 한다. 2. 본 교과목은 자기주도형 역량중심 교과목으로서, TBL 방식에 따라, 빈곤해결을 위한 정책들을 심도깊게 분석하여 제시하는 팀프로 젝트를 진행한다. 매시간 개별 발표/토론 활동을 가장 중시한다. 팀활동은 대형강의실 혹은 TBL 강의실 등 워크샵 환경에서 이루어지 며, 9개의 팀으로 구성된다 (팀원 수는 수강 인원에 따라 변경 가능하다). 팀활동의 주도성과 토론활동이 큰 평가기준이 된다. 교수자 도 팀에 소속되어, 프로젝트를 진행을 위한 팀구성과 논의 구조 과정에 함께 하며, 내부 평가를 진행한다. 3. 주차별 세부 수업 내용을 요약하면, 우선 빈곤과 불평등의 개념과 측정에 대한 학습이 필요한데, 3주차까지 학생들의 개별 발표와 교수자의 강의를 중심으로 진행한다. 이후 4주차 주제인 빈곤을 설명하는 이론부터는 조별 활동과 토론을 병행하며, 이후 9주차 세계 1. 교과목 개요 ■ 수업개요 의 빈곤까지, 발표와 토론을 병행하여 진행한다. 토론과 발표 이후에는 총 4차례에 걸처, 그 내용을 개별 Executive Summary 로 작성 한다. 9주차 후반부터는 교수자가 빈곤층의 자립과 자활을 지지하는 사회투자 이론과 이에 기반한 혁신적인 빈곤정책에 대한 프로젝 트를 소개한다. 수강생들은 혁신 빈곤정책 프로젝트를 통해 빈곤에 대한 실천적 접근 능력을 키우고, 더 나아가 다양한 빈곤 현상에 대해 정책가로서의 자질을 함양하며, 토론과 실전 응용 그리고 대안적 정책방향에 대한 논의를 진행한다. 이 모든 과정을 통해 빈곤 을 해결하기 위한 실천가이자 정책가로서의 자질을 함양하고, 빈곤층 개인의 미시적 측면과 국가 거시정책 맥락에서 빈곤문제를 동 시에 볼 수 있는 역량을 키우는 것을 목표로 하고 있다. 본 강의를 통해 수강생들은 빈곤이라는 사회적 위험의 다차원적 속성을 이해하고, 빈곤 문제를 사회정책이라는 집합적 노력을 통해 해결하는 기제를 배운다. 팀 중심 프로젝트 활동과 적극적인 발표 / 토론 과정을 통해, 남들 앞에서 주제에 대한 정리된 생각을 논리적으로 제시하는 능력을 키 우고, 복지 현장의 정책 전문가로서의 자질과 역량을 갖춘다.', '{"대해","진행한다","교수자의","빈곤","있다","토론을","프로젝트","설계된","빈곤의","개별","질문에","이에","발표를","평가를","한국의","정책","노병일","불평등","김태성","팀토론"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('513035', '에너지소재', '반도체·디스플레이공학과', '반도체·디스플레이공학과', 0, 3, '전선', '박재훈', '에너지 공학이란 에너지의 정의와 역사, 환경, 에너지원별 소비구조 현황 및 전망을 소개하고 전통적 에너지원인 석유, 가스의 탐사 개발기술, 생산현황 및 전반에 대해 학습하는 분야임. 에너지 공학을 학습하기 위해서는 유체역학, 열전달, 열역학 등을 기본으로 하 여 에너지 변환과 에너지 이용 기술에 관한 이론, 열역학 사이클 및 열기관 해석, 대체 에너지 이용을 다루는 기술 등을 학습하는 요 구됨. 본 과목에서는 에너지 산업을 이해하고 전기 에너지 기술과 관련한 사항을 학습함. 본 과목을 에너지 공학 분야 중 전기 에너지와 연관한 이론과 기술에 대한 학습을 목표로 함. 학습자는 향후 전기/태양광/신재생에너 지 분야의 자격증 취득에 필요한 역량을 쌓을 수 있으며, 강전 반도체 기술에 대해서도 학습할 수 있음.', '{"에너지","강의록","전력","전기","전기와","재료","회로와","시스템","전자와","계통의","전지","에너지의","기술에","에너지와","반도체","정의와","역사","학습하는","열역학","등을"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713000', '디지털인문예술입문', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '김용수', '디지털인문예술전공의 전반을 소개하고 가볍게 경험하는 기초 과목이다. 이론보다는 실습 위주로 디지털 기술 및 소프트웨어 활용 기법 등을 초보적인 수준에서 학습한다. 디지털 기술의 의미에 대한 이해와 함께 실제 인문예술 분야 학습과 프로젝트에 활용할 수 있는 간단한 생성형 AI, 소프트웨어, 분석 도구도 익히고, 이를 활용하여 디지털 프로젝트를 진행한다. 인문사회융합인재양성사업(HU SS) 사업과 연계하여 인문·사회학의 통찰과 분석을 통한 융합형 인재 양성에 이바지한다. - 디지털인문예술 전공 과정에 대한 전반적인 이해 - 텍스트 분석과 데이터 시각화 등 기본적인 분석 방법론에 대한 이해 - 생성형 AI와 각종 디지털 도구, 소프트웨어를 활용할 수 있는 디지털 리터러시 능력', '{"프로젝트","시각화","구글","데이터","생성형","디지털","웹사이트","관계망","제작","텍스트","도구","클래스룸","소프트웨어","활용할","있는","드라이브","만들기","드라이브와","크롬","스프레드시트"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203303', '사회보장론', '사회과학대학', '사회과학대학', 0, 3, '전선', '석재은', '1. 사회적 위험과 사회보장의 필요성에 대한 이해에 기반한 사회보장 기본지식 습득 2. 인구구조, 산업구조, 노동형태, 가족, 젠더레짐의 변화에 대응한 사회보장의 변화에 대한 이해에 기반한 사회보장의 역동성 파악 3. 다양한 사회보장의 유형과 사회보장의 방식의 특성에 대한 이해를 통한 사회보장정책의 분석역량 습득 4. 현행 개별 사회보장제도에 대한 분석적 이해역량 습득 5. 새로운 사회보장체계에 대한 전망과 분석적 이해역량 습득 1. 복지국가에 있어서 사회보장의 위치와 중요성에 대한 이해 증진 2. 사회보장의 개념, 등장 배경, 원리, 다양한 제도 형태에 대한 기본 지식 습득 3. 국내외 사회보장제도에 대한 이해 및 분석 능력 배양 4. 사회보장제도가 경제와 사회에 미치는 영향에 대한 이해 5. 한국에 있어서 경제·사회 구조의 변화와 사회보장의 전망', '{"원리와","사회보장의","산재보험의","건강보험제도의","구성요소","공공부조제도의","고용보험제도의","역사","경제적","공적연금의","유형","주차","실업보상제도의","발전과정","공공부조의","국민연금제도","국민연금제도의","국민기초생활보장제도","복지국가의","기능과"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713010', '디지털디자인1', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '신동주', 'HUSS 사업과 연계하여 지역의 혁신 가치 창출을 위한 교과목으로 디자이너가 갖추어야 하는 필수 기초 지식을 습득하고 시각적 디 자인 기본 요소들을 체계적으로 경험해본다. 타이포그래피, 일러스트레이션 등을 사용목적과 환경 등의 특성과 맥락을 이해하며 독창 적으로 표현해 보며 디자인의 목적성과 디자인이 담아내야할 기능과 심미성을 익힌다. - 디자인 기초로서의 조형요소와 원리를 디지털 도구와 실재 그래픽 도구들의 활용능력을 이용하여 표현할 수 있다. - 비주얼 커뮤니케이션의 기초가 되는 타이포그래피와 일러스트레이션을 상황에 맞게 시각화해 본다. - 디지털 환경을 이해하고, 창의적 발상을 다양한 방법을 통해 콘셉 설정 및 구체적인 결과물을 제작한다. - 인문·사회학의 통찰과 분석을 통한 융합형 인재 양성을 위한 교과목으로 시각적 환경을 비판적 사고를 통해 재고해본다.', '{"제작한다","자신을","이용한","결과물","패턴을","주제를","디자인의","표현할","결과물을","색을","폰트를","정해","효과적으로","나타낼","있는","만든다","생성","이해하고","이해한다","자기소개"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203315', '청소년복지론', '사회과학대학', '사회과학대학', 0, 3, '전선', '최정원', '본 강의는 청소년기의 발달적 특성과 이를 둘러싼 개인·가족·학교·지역사회·사회구조적 환경을 이해하고, 청소년이 직면한 다양한 문 제와 욕구에 대한 복지적 대응을 학습하는 것을 목적으로 한다. 청소년복지의 개념, 관련 법·정책과 전달체계를 살펴보고, 위기청소년, 학교 밖 청소년, 빈곤·차별·폭력 등 주요 이슈에 대한 예방 및 개입 전략을 다룬다. 이를 통해 예비 사회복지사로서 청소년을 권리의 주체로 인식하고, 현장 실천과 정책을 비판적으로 연결할 수 있는 기초적 이해와 실천적 관점을 함양한다. 청소년기의 발달적 특성과 청소년을 둘러싼 사회·환경적 맥락을 이해한다. 청소년복지의 개념, 관련 법·정책 및 전달체계를 체계적으로 학습한다. 위기청소년, 학교 밖 청소년 등 다양한 청소년 문제를 복지적 관점에서 분석한다. 청소년에 대한 개입 기술을 습득한다. 청소년을 권리의 주체로 인식하는 관점을 형성한다. 청소년복지 실천과 정책을 비판적으로 연결할 수 있는 기초 역량을 함양한다.', '{"질의응답","있다","주차별","참여도","이해하고","청소년","소규모","발제","청소년과","대해","개입","설명할","접근방법을","도출할","청소년복지","예방","발달적","특징과","원인","실태"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713014', 'UX디자인', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '김성우', 'UX 디자인 수업에서는 경험 디자인 (experience design)의 주요 3개 세부 영역 (UX, 서비스 디자인, 고객 경험) 중 가장 기본이 되는 UX (사용자 경험, User Experience)를 디자인 하는 데에 필요한 기초적인 이론 및 실무 지식을 학습 이 강의의 목표는 경험 디자인 (experience design)의 주요 세부 영역 중 하나인 UX 디자인의 이론 및 실무 지식을 학습하여 졸업 후 UX 디자이너, UX 기획자, 인터랙션 디자이너(UI 디자이너), 프론트엔드 (Front-end) 기획자, 상품 기획에서의 고객 경험 담당자 등의 관련 직종에 진출할 수 있는 역량을 함양하고자 함', '{"디자인","경험","정의","가치","가지","원칙","팀활동","프로세스","필요한","디자이너","세부","영역","고객","지식을","기획자","분야의","중요도","차이점","정의와","로서의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('513002', '재료과학개론I', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '박종민', 'To understand the basic fundamentals of materials science and engineering on a level appropriate for university students who ha ve completed their freshmen calculus, chemistry, and physics courses with experiments. To understand the basic fundamentals of Materials science and engineering', '{"understand","the","homework","and","phase","transformations","structure","crystal","dislocations","strengthening"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203316', '가족복지론', '사회과학대학', '사회과학대학', 0, 3, '전선', '고윤순', '1. 가족의 변화 및 변화에 관한 관점이해 2. 다양한 가족 문제 및 원인 이해 3. 가족문제를 위한 다양한 사정방법 이해 4. 가족문제를 위한 개입 방법 이해 5. 가족상담, 가족치료 모델 중 해결중심단기치료 간략히 이해 6. 가족정책에 대한 이해 7. 가족 문제 혹은 가족 형태에 대한 소그룹 프로젝트 제작 및 발표 가. 현대 가족의 변화와 가족문제를 이해하고 계속적으로 연구하는 방법 배양 나. 가족문제를 사정하는 방법 교육 다. 가족문제를 해결하기 위한 사회복지개입 방법 교육 라. 가족문제해결을 위한 가족복지 정책이해 및 개선방안 연구 마. 가족문제릉 위한 가족상담법 (해결중심가족치료법) 교육 바. 다양한 가족문제와 개입에 대한 소그룹 연구활동 시행 및 발표 사. 발표자료 제작, 발표, 토론 능력 배양', '{"소그룹","설명할","있다","교수","가족","강의자료","양식","가족의","발표자료","소그룹이","만든","동영상을","발표하고","토론한다","관한","기말과제","대해서","가족형태","문제에","가족복지"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203317', '의료사회복지론', '사회과학대학', '사회과학대학', 0, 3, '전선', '이아영', '본 교과목은 의료사회복지실천에 필요한 이론 및 지식과 기술, 윤리적 태도를 습득하는데 목적이 있다. 이를 위해 건강의 사회적 결 정요인에 대하여 이해하고, 의료사회복지 실천모델, 실천과정과 보건의료 및 의료보장정책을 학습함으로써 사회복지사로서의 역량을 향상한다. 또한, 구체적인 임상 사례를 통하여 실제적인 이해를 높이고자 한다. 1. 의료사회복지실천에 필요한 지식과 기술을 습득한다. 2. 구체적인 임상 사례에 지식과 기술을 적용해본다. 3. 의료의 사회적 환경에 대한 이해를 높인다. 4. 의료현장에서의 윤리적 책임과 딜레마에 대해 논의한다.', '{"주교재","의료사회복지의","실제","의료사회복지실천","강의자료","의료사회복지실천의","지식과","의료사회복지실천에","필요한","윤리적","사회적","구체적인","임상","이해를","기술을","개관","역사","관점과","모델","실천"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713016', '한국문화와콘텐츠', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '남혜원', '본 수업은 한국문화 전반을 이해하고, 오늘날 콘텐츠 산업 속에서 이것이 어떻게 계승되고 발현되는지 파악하는 것을 목표로 한다. 특히 글로벌 시장을 대상으로 우리 콘텐츠의 활발한 생산과 소비가 이루어지고 있는 지금, 우리의 서사와 감정을 공유하는 데 한국문 화가 갖는 영향력과 가치에 주목한다. 이를 바탕으로 한국문화를 활용한 기존의 콘텐츠 개발 사례를 분석하여 앞으로 새로운 콘텐츠 개발로 나아갈 방안을 함께 모색하고자 한다. - 콘텐츠 산업 속에서 한국문화가 갖는 개념과 의미를 학습한다. 따라서 오늘날 다양한 매체를 통해 전 세계로 생산·소비되는 콘텐츠 개발에서 한국문화의 활용이 갖는 가치와 영향력을 이해할 수 있다. - 한국문화의 역사와 갈래·양상 등을 학습하고, 이를 활용한 콘텐츠들을 조사해서 분석한다. 따라서 콘텐츠 개발에서 문화 원형으로 활용되는 우리 삶의 특징 전반을 파악하고, 기존 콘텐츠의 강점과 약정, 성공과 실패 요인 등을 알 수 있다. - 한국문화를 활용한 새로운 콘텐츠를 직접 기획해 본다. 따라서 콘텐츠 개발의 차원에서 한국문화에 대한 새로운 접근을 모색하고, 우리 문화의 현대적 의미와 역할을 발견할 수 있다. - 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에서 요구하는 융합인재상에 도달하는 것을 목적으로 한다.', '{"콘텐츠","한국문화","새로운","기획","산업","한국문화의","조별","한다","우리","갖는","이를","활용한","따라서","있다","양상","콘텐츠를","한국문화에","전반적인","전반을","오늘날"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713026', '문화원형과 고전', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '서주희', '다가오는 미래는 분명 희소성이 높은 것을 요구하는 시대가 올 것이다. 그런 가운데 ''나'' 라는 존재를 입증할 수 있는 가장 유일한 방 법은 각자의 고유한 문화유산을 내세우는 일이다. 그런 의미에서 본 교과목은 한국문화콘텐츠를 기반으로 한국문화의 역사, 생활, 장인정신 등 한국문화의 원형에 대한 개념을 이해하 고 이를 바탕으로 글로벌 맥락에서 효과적으로 소통하고 문화를 전파하는 역량을 기르는 것을 목표로 한다. 이 강의는 한국문화가 다 른 문화, 다른 인종, 디지털 기술과 어떻게 관계를 맺고 융화할 수 있는지에 대해 교수자의 국내외 문화현장의 취재경험을 통해 학습 자 개개인이 한국문화의 원형을 이해하고 이를 바탕으로 한국문화콘텐츠를 효과적으로 전달하는 스토리텔링 기술을 향상시키는데 수업의 목표가 있다. 1. 한국문화의 원형이라고 할 수 있는 한국문화의 역사, 생활, 장인정신에 대한 개념을 이해할 수 있다. 2. 전통공예, 설화, 역사적 이야기 등 한국문화의 원형을 바탕으로 재해석된 한국문화콘텐츠를 살펴볼 수 있다. 3. 본 교과목은 한국문화의 원형을 기반으로 창의적인 한국문화콘텐츠를 재해석, 재생산 할 수 있는 융합인재상에 도달하는 것을 목 적으로 한다.', '{"기획안","있다","팀별","대해","질의응답","설명할","팀프로젝트","피드백","한국문화의","초안","포스터","전시","설명","구성요소","바탕으로","구성","수정","높은","한국문화콘텐츠를","구체적으로"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203318', '복지국가론', '사회과학대학', '사회과학대학', 0, 3, '전선', '최유석', '이 과목에서는 한국과 서구 복지국가의 발전과 재편과정에 대한 이해를 기반으로 복지국가 발전을 위한 비판적 사고능력을 개발하는 것을 목표로 한다. 복지국가의 개념, 기원, 발전, 재편을 비롯해 최근 복지국가 변화를 배울 것이다. 국가마다 상이한 복지국가의 유 형과 특징을 살펴보고, 복지국가와 노동시장, 경제성장 간의 관련성을 탐색할 것이다. 한국 복지국가의 발전과정과 특성에 대한 쟁점 을 살펴보고, 한국 복지정책의 발전방향을 모색하는 능력을 개발하는 것이 이 강의의 목표이다. 현대 복지국가의 성격과 발전과정, 쟁점을 살펴보고, 한국 사회복지의 현실과 쟁점에 대한 토론을 진행한다. 서구와 한국 복지국가 비 교를 통해 한국 복지국가의 성취와 한계를 이해하고, 발전방향을 모색할 수 있는 역량을 개발한다.', '{"질의응답","복지국가의","토론참여","정도","이해한다","학생토론","복지국가","한국","살펴보고","대해","무엇인지","발전에","민영화","서구","복지정책의","성취와","기원과","관한","복지국가에","약술형"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713028', '디지털문화콘텐츠', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '송한나', '마케팅은 시장의 요구와 밀접한 관계를 맺으며, 제품의 구상단계부터 생산, 유통, 판매 등 모든 과정에 관련된다. 마케팅의 개념은 생 산자 중심에서 소비자 중심으로 변화해왔으며, 기술적으로는 디지털 중심의 마케팅방법이 크게 발전하고 있다. 문화예술 분야에서도 이러한 흐름은 거스를 수 없으며, 마케팅 커뮤니케이션은 대중이 문화예술을 향유하기 위한 필수적인 과정으로 인식되고 있다. 이 수업에서는 문화예술 마케팅 커뮤니케이션 방법에 대한 이해와 더불어 디지털 마케팅의 유형과 특징에 대해 중점적으로 다루며, 디지털 마케팅의 대표적인 도구인 구글 애널리틱스의 기초 활용방법에 대해 학습한다. 이러한 지식을 바탕으로 공연, 미술, 음악 등 관심있는 문화예술분야에 대한 마케팅 플랜을 수립하는 실습 프로젝트를 진행하여 학습 내용을 체화함으로써, 디지털마케터로서 문 화예술분야에 진출할 수 있는 기본적인 역량을 습득할 수 있을 것이다. 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에 서 요구하는 융합인재상에 도달하는 것을 목적으로 한다. 디지털마케팅의 개념과 도구의 활용법을 익히고, 문화예술 시장을 위한 마케팅 플랜을 기획하고 적용할 수 있는 역량을 기른다.', '{"마케팅","자료","배포","프로젝트","이해하기","구글","구성요인","사례","디지털","문화예술","애널리틱스","문화예술마케팅","전략","고객","마케팅의","커뮤니케이션","전환","데이터의","종류","데이터야"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203511', '정신 건강론', '사회과학대학', '사회과학대학', 0, 3, '전선', '고정애', '본 교과에서는 증가하고 있는 현대인의 환경적 스트레스와 정신건강의 관계, 다양한정신건강의 문제와 질환(장애), 생애주기에 따른 정신건강의 문제를 이해하고 사회복지실천과의 관계를 이해함으로써 정신건강증진을 위한 기본적인 지식과 실천역량을 습득하는 데 목적을 둔다. 1. 현대인의 환경적 스트레스와 정신건강의 의미를 이해한다. 2. 인간 생애주기에 따른 정신건강의 문제와 문제해결을 위한 접근방법을 습득한다. 3. 대표적인 정신장애의 진단과 특징에 대하여 이해한다.', '{"정신건강의","주교재","주요정신건강","문제의","조별발표","부가자료","발달단계","스트레스와","정신건강","현대인의","환경적","문제와","생애주기에","따른","이해한다","강의계획서","학생소개","수업개관","정신건강과","주요개념"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203422', '노인요양보장론', '사회과학대학', '사회과학대학', 0, 3, '전선', '석재은', '돌봄과 사회적돌봄의 이해 노인건강돌봄을 둘러싼 사회적 과제와 관련 제도의 이해 통합돌봄의 이해(돌봄통합지원) 장기요양정책의 목표에 대한 이해 장기요양제도의 설계, 현황, 쟁점에 대한 이해 돌봄 정의와 돌봄민주주의 이해 장기요양욕구(long-term care need)를 가진 노인의 특성을 이해하고, 장기요양욕구를 가진 노인들을 위한 사회적 지원체계인 장기요 양서비스 체계와 장기요양정책의 다양한 측면을 이해함으로써 장기요양서비스를 관리하고 제공하는 전문인력으로서 양성한다. 구체적으로 장기요양제도의 목표와 수단, 전략에 대한 명확한 이해를 도움으로써 장기요양제도에 대한 사회적 기대와 임무를 명확 히 이해하도록 돕는데 그 목적이 있다. 사회보장제도로서의 장기요양제도의 공공적 성격과 역할을 명확히 인식하고, 장기요양핵심 주체들의 바람직한 관계속에서 선순환 체계 형성 방향을 이해하며, 장기요양제도를 구성하는 욕구평가 및 급여의 구성, 장기요양수가 설정 구조, 장기요양서비스 질 평가 목표 및 내용을 명확히 이해함 으로써, 장기요양제도의 정책목표와 정책수단 및 전략에 대한 심층적 이해를 가질 수 있도록 하는데 그 목적이 있다 지역사회통합돌봄에 대한 이해 돌봄과 사회적돌봄의 이해 돌봄 정의와 돌봄민주주의 이해 노인건강돌봄을 둘러싼 사회적 과제와 관련 제도의 이해 장기요양정책의 목표에 대한 이해 장기요양제도의 설계, 현황, 쟁점에 대한 이해 장기요양욕구(long-term care need)를 가진 노인의 특성을 이해하고, 장기요양욕구를 가진 노인들을 위한 사회적 지원체계인 장기요 2. 교과 목표 ■ 교과목표 양서비스 체계와 장기요양정책의 다양한 측면을 이해함으로써 장기요양서비스를 관리하고 제공하는 전문인력으로서 양성한다. 구체적으로 장기요양제도의 목표와 수단, 전략에 대한 명확한 이해를 도움으로써 장기요양제도에 대한 사회적 기대와 임무를 명확 히 이해하도록 돕는데 그 목적이 있다. 사회보장제도로서의 장기요양제도의 공공적 성격과 역할을 명확히 인식하고, 장기요양핵심 주체들의 바람직한 관계속에서 선순환 체계 형성 방향을 이해하며, 장기요양제도를 구성하는 욕구평가 및 급여의 구성, 장기요양수가 설정 구조, 장기요양서비스 질 평가 목표 및 내용을 명확히 이해함 으로써, 장기요양제도의 정책목표와 정책수단 및 전략에 대한 심층적 이해를 가질 수 있도록 하는데 그 목적이 있다 지역사회통합돌봄에 대한 이해', '{"요양","고령친화사업","장기요양정책의","장기요양제도의","돌봄","노인장기요양서비스","개발","사회적","노인장기요양보장의","노인장기요양보장","노인장기요양","통계","_장기요양보험_공공성_강화방안","장기요양정책","가진","전략에","이해를","목적이","있다","명확히"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713032', '문화콘텐츠기초', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '서주희', '본 교과목은 한류대중문화의 이해에 있어 한국문화콘텐츠의 기본개념과 동향을 이해하고, 이를 분석하는 능력을 기르는데 목적을 둔 다. 전통을 바탕으로 현대적으로 재해석되는 한국문화콘텐츠는 전시, 영화, 드라마, 게임, 웹툰 등 다양한 대중문화매체를 통해 활용된 다. 본 강좌에서는 다양한 대중매체를 통해 보여지는 한국문화콘텐츠의 특수성과 보편성을 탐구하고, 다양한 한국문화콘텐츠의 기획 사례와 스토리텔링 기법을 학습한다. 아울러 교수자의 한국문화콘텐츠 현장에서의 실무경험을 핵심자산으로 삼아 전통과 현대, 글로 벌, 한국의 장인(Artisan)을 깊이있게 탐구하며, 한국문화콘텐츠를 살아있는 과정으로 바라보는 것을 이 수업의 목적으로 한다. 1. 한국문화콘텐츠의 동향및 전망에 대해 학습할 수 있다. 2. 전통을 바탕으로 현대적으로 재해석 한 다양한 한국문화콘텐츠 사례를 접하고 이를 통해 학습자만의 차별화된 한국문화콘텐츠 기 획안을 작성하고 말 할 수 있다. 3. 본 교과목을 이수함으로써 창의적이고 도전적인 미래융합인재상에 도달하는 것을 목적으로 한다.', '{"팀별","있다","한국문화콘텐츠","기획안","질의응답","피드백","프로젝트","대해","한국문화콘텐츠의","바탕으로","설명할","기획안의","선정","작품","구성","기획안을","초안","전시","영화","한국의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713037', 'AI디자인', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '송한나', '인공지능은 최근 매우 빠른 속도로 발전하여 창의적인 작업에서도 큰 변화를 가져오고 있다. 지금까지의 디자인 프로세스에서 사용 된 디지털 도구는 인간이 생각한 아이디어를 구현하는 용도로 사용되었으나, 생성AI가 등장한 이후에는 AI와 인간이 함께 대화하고 협업하면서 새로운 아이디어를 전개하는 방향으로 디자인 프로세스가 발전하고 있다. 브랜드 디자인은 마켓 리서치를 바탕으로 비주 얼 디자인이 함께 이뤄지는 분야로서, 디자인 제작 과정 전반에 걸쳐 생성AI 도구의 활용도가 매우 높은 분야이다. 이 수업을 통해 브 랜드 디자인의 원리와 프로세스에 대해 학습하고, 챗GPT와 미드저니, 어도비 소프트웨어 등 다양한 AI 도구를 활용하여 리서치에 기 반한 브랜드 디자인 역량을 습득하는 것을 목표로 한다. 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에서 요구하는 융 합인재상에 도달하는 것을 목적으로 한다. 브랜드 디자인의 원리와 프로세스에 대해 이해하고, 다양한 AI도구를 활용한 디자인 역량을 기른다.', '{"브랜드","자료","배포","디자인","콘셉트","브랜드의","시장","콘셉트에","구체적으로","접근하라","경험","경험의","핵심","요소","미드저니","만들기","프롬프트","리포트","매우","있다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('203606', '지역사회돌봄관리론', '사회과학대학', '사회과학대학', 0, 3, '전선', '이강', '" 지역사회 돌봄관리 ( Community Care Management) " 1) 교과목 설명 - 한국의 초고령사회 진입과 커뮤니티케어 사회서비스 정책 확대 (2026년 3월 돌봄통합지원법 전국 시행))에 따라 관련 사회복지 현장에서 필요로 하는 역량있는 전문가 양성을 목적으로 합니다. - 지역사회의 보건의료-요양-주거-복지-ICT 돌봄 서비스 및 자원을 수요자 중심으로 연계·조정하여 맞춤형 통합서비스를 제공함으 로써 돌봄의 연속성을 보장하는 역할을 수행하는 스마트 돌봄 케어매니저가 갖추어야 할 기초 지식, 기술과 방법, 수행단계별 과업의 지식을 학습합니다. - 또한 돌봄 현장 실습을 통해 수행과정(욕구사정-케어플랜-실행-평가)에서 필요한 실무 능력을 배양함을 목적으로 합니다. 케어매 니지먼트 전문인력 양성을 위해 대학과 돌봄 현장의 서비스 분야별 전문가의 공동 협력 강의 및 실습지도 방법을 적용합니다. 2) 교과 목표 역량 * 보건의료-요양-주거-복지-ICT 돌봄 서비스 및 자원을 수요자 중심으로 연계 및 조정하여 맞춤형 통합서비스를 제공함으로써 돌봄 의 연속성을 보장할 수 있는 역량을 갖춘 케어매니저 양성 (1) 커뮤니티케어 정책의 이해 : 도입 배경, 필요성, 개념과 특징 (2) 통합 돌봄의 이해 : 다학제·다직종 협력 - 노인 질환 이해와 예방 및 건강관리, 노인 영양관리, 노인 신체활동증진, ICT 적용 돌봄서비스 (3) 케어매니지먼트 수행 단계별 지식과 기술·방법 및 실무 능력 배양 - 포괄적인 사정(Assessment), 케어플랜 수립, 실행 (연계·조정 등) 및 모니터링, 평가 3) 졸업 후 다음 분야의 진로 설계에 필요한 커리큘럼으로 구성됩니다. - 건강보험공단 장기요양직, 지자체의 xhdgkqehfqha 전담 부서 공무원, 노인 돌봄 기관, 노인복지관, 스마트 케어 기업, 노인 보건의 료 관련 분야, 장기요양 통합재가기관, 노인 요양원 등 1) 통합돌봄 정책의 이해와 현장 활용 능력 강화 - 도입 배경, 필요성, 개념과 특징 2) 다학제·다직종 협력 접근의 이해와 역량 강화 - 노인 질환 이해와 예방 및 건강관리, 노인 영양관리, 노인 신체활동증진 , ICT 적용 돌봄서비스 3) 케어매니지먼트 수행 단계별 지식과 기술·방법 및 실무 능력 배양 (1) 좋은 돌봄과 관계 형성 : 공감의 이해와 능력 증진 (2) 면접 능력 향상 (3) 포괄적인 사정(Assessment) 능력 키우기 (4) 케어플랜 수립 능력 키우기 (5) 커뮤니티케어 네트워크 이해와 실행역량 키우기 (6) 실행 (연계·조정 등) 및 모니터링 및 평가 능력 키우기', '{"현장","케어매니지먼트","이해와","노인","지식","기술과","실행","가이드라인","연계","이해도","참여도","욕구사정","사례","조정","참고자료","서비스","케어플랜","협력","다학제","다직종"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713039', '스토리텔링창작실습', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '김지현', '본 강의는 문화콘텐츠의 특수성을 반영한 스토리텔링을 실습하여 학생 개인의 전문성을 기르는 것을 목표로 한다. 이를 위해 학기의 대부분은 팀 프로젝트를 중심으로 진행한다. 팀, 개인 실습을 통해 스토리텔링의 이론에 대한 이해 증진과 과제물 비교하며 소통하기( Storytelling)에 대한 기초적 소양을 채우고 응용력을 키울 수 있을 것이다. 1. 문화산업의 기초역량인 스토리텔링에 대한 이해를 습득하고 응용할 수 있다. 2. 팀 프로젝트를 통해 디자인 제작 및 기획에 대한 전반적인 이해를 높힌다. 3. 지역문화콘텐츠를 재료(data)로 이야기(story) 활용과 디자인(design) 표현을 기획 및 창작할 수 있는 능력을 키운다. 4. 이를 통해 인문사회 융합인재양성사업(HUSS)에서 요구하는 융합인재상에 도달하는 것을 목적으로 한다.', '{"스토리텔링","스마트리드","첨부교안","자율","작품","스토리텔링을","제작","것을","한다","이를","프로젝트를","이해를","디자인","스토리텔링이란","정의","필요성","사용","사례들을","토론함","팀플로"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('201436', '정치학', '사회과학대학', '사회과학대학', 0, 3, '전선', '김인영', '- 개요: 정치학을 처음 배우는 전공학생, 복수전공, 부전공, 일반학생들에게 정치의 기본지식을 제공하는 과목임. - 목적: 고대에서부터 현대까지 ‘정치’(政治, politics)의 의미는 지대하다. 본 강의는 국내정치와 국제정치의 기본 틀을 이해하는 것을 목적으로 함. - 내용: 국내정치의 작동 원칙인 자유민주주의와 대의민주주의 기관인 정당, 국회와 정부구조를 이해하고, 국제정치의 본질인 국익 과 안보(security), 외교(diplomacy), 전쟁과 평화(war and peace)에 대한 기본 지식을 습득함. 본 강의는 국내정치와 국제정치의 기본 틀과 기초 이론을 이해하고 정치 현상을 분석할 수 있는 능력을 키우는 것을 목표로 함.', '{"김인영","서울대","예정","강의실","국제정치","권력구조","패권","경쟁","이상우","정치의","근대","정치사상","홉스와","로크","자유주의와","자유민주주의","현실주의","자유주의","환경과","국제정치의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713043', '디지털디자인3', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '이은솔', '1. UX/UI개선 프로젝트를 수행해보며 사용자 경험 디자인에 대한 이해부터 완성까지 full process를 체험할 수 있으며, 개선 전략을 바탕으로 다양한 환경에서의 디바이스를 고려한 app및 서비스 UI를 설계해 볼 수 있다, 2. 실무와 근접한 수준의 프로젝트를 개별 또는 팀으로 수행함으로써 직무와 직결된 프로세스를 간접체험 할 수 있다. * 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에서 요구하는 융합인재상에 도달하는것을 목적으로 한다. * 서비스를 만들어내기까지의 과정에 필요한 서비스 기획부터 UX디자인 설계 프로세스를 직접 참여하고 경험해봄으로서 사용자 중 심의 UX를 고려한 서비스를 발견하고 UI를 기획 제작 할 수 있다. * 사용성을 고려한 UI구조에 대한 기획을 기반으로 실제 사용자들이 서비스를 이용 시 기능적인 요소들을 유용하게 사용할 수 있도록 컨텐츠에 맞게 시각적으로 UI디자인을 할 수 있다. * 개별적으로 아이데이션한 서비스에 맞는 디자인 컨셉을 설정 한 후 UI디자인을 진행하며, 이를 실제 서비스로 구현 시 사용자들이 어떠한 경험을 할 수 있는지 확인 할 수 있도록 프로토타입을 제작한다. * 이후 포트폴리오등에 활용할 수 있도록 UI디자인 및 프로토타이핑 툴을 활용하여 완성도 있는 UI제작을 구현한다.', '{"디자인","직접","교강사가","준비한","자료","제작","사용자","프로토타이핑","서비스","설계","개선점","와이어프레임","디자인의","수립","구조","반영한","개선","있다","개요와","프로세스"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('201501', '민주주의', '사회과학대학', '사회과학대학', 0, 3, '전선', '김인영', '현대 사회의 가장 중요한 정치이념이자 정치체제인 민주주의(democracy)를 이해함. 주주의란 무엇인가, 아테네 민주주의를 유지하기 위한 조건은 무엇이고, 자유민주주의란 무엇인가를 배움. 민주주의로의 이행은 어떻게 가능했는지, 한국의 민주주의는 어떻게 전개되었으며, 어떻게 공고화와 심화가 가능한지를 이론과 역 사 속에서 이해함. 민주주의와 자본주의·경제성장, 민주주의와 평화의 관계를 알아보고, 대의민주주의와 직접민주주의 비교 및 최근의 ‘민주주의 역행’ 이슈를 고찰함. 민주주의란 무엇인지, 민주주의 정치란 무엇인지, 생활 속의 민주주의는 어떻게 실천 가능한지를 이해하고 고찰함.', '{"민주주의","강정인","임혁백","민주주의와","세계의","김인영","예정","자유민주주의란","강의실","조별","러시아","중국","중동","가능성","후퇴","민주주의로의","자본주의","어떻게","민주주의란","이행"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('201534', '국제정치의이해', '사회과학대학', '사회과학대학', 0, 3, '전선', '채지혜', 'ㅇ 본 과목은 국제정치 현상을 체계적으로 이해하고 분석할 수 있는 이론적 틀을 습득하는 것을 목표로 합니다. ㅇ 국제정치학은 현실과 이론을 연결하는 학문으로서, 일상적으로 접하는 국제뉴스와 사건들을 현상으로만 인식하는 것이 아니라, 이 론적 렌즈를 통해 분석하고 설명할 수 있는 능력을 배양합니다. ㅇ 수업은 ''현상→이론→현실 적용’의 순환적 학습 구조로 설계되었습니다. 먼저 현실의 국제정치 현상을 관찰하고, 이를 설명할 수 있는 다양한 이론적 관점들을 학습한 후, 다시 현실 문제에 이론을 적용하여 분석하는 과정을 반복합니다. ㅇ 학습자는 이론과 현실 사이의 유기적 연결고리를 형성하고, 국제정치를 바라보는 비판적이고 분석적인 시각을 함양하게 됩니다. ㅇ 국제정치학은 세계를 이해하는 창입니다. 함께 배우고, 질문하고, 토론하며, 국제정치를 바라보는 여러분만의 시각을 형성해 나가 시기를 기대합니다. ㅇ 본 과목의 핵심 목표는 국제정치학의 기본 사고 틀(framework) 형성입니다. 구체적으로는 다음과 같은 목표를 설정합니다. - [이론적 기초] 국제정치학의 주요 패러다임(현실주의, 자유주의, 구성주의 등)의 핵심 개념과 논리를 이해합니다. - [분석적 사고] 국제정치 현상을 다양한 이론적 관점에서 분석하고, 이론과 현실을 연결한 설명력을 키웁니다. - [학문적 기초] 학술적 문헌 읽기, 비판적 사고, 논리적 글쓰기 등 기초 학문 역량을 배양합니다.', '{"핵심","현실주의","이해한다","학습노트","사례","문헌","리뷰","강의자료","이론적","학습한다","국제정치","자유주의","발췌문","파악한다","정체성","국제정치의","민족","구성주의","가정","국가"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('713046', '지역혁신연구방법론', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '한수미', '본 수업에서는 빅데이터 시대에 지역 문제를 발굴하고 해결하기 위한 실증적 연구방법을 학습합니다. 설문조사, 인터뷰, 그리고 통계 분석의 과정을 AI 도구와 구글 코랩을 활용하여 실습하며, 실제 지역 이슈를 다루는 팀 프로젝트를 수행합니다. 무엇보다도 3-4학년 대상으로 기획자, 마케터, UX 디자이너 등 데이터 기반 의사결정이 필요한 직무에 필수적인 리서치 역량을 배양합니다. 이를 통해 본 교과목은 인문사회 융합인재양성사업(HUSS)에서 요구하는 융합인재상에 도달하는 것을 목적으로 합니다. 이 수업을 통해 학습자는: ■ 지식: 지역혁신연구에 필요한 설문조사, 인터뷰, 통계분석 방법론의 원리를 설명할 수 있다. ■ 기술: 데이터를 수집·정리·분석·시각화하고, 연구 결과를 효과적으로 전달할 수 있다. ■ 태도: 데이터 기반 의사결정의 중요성을 인식하고, 지역문제에 대한 실증적·비판적 접근 태도를 갖출 수 있다.', '{"데이터","방법론","설문조사","설계","시각화","프로젝트","중급","인터뷰","지역이슈","조사","설문","실시","기획","있다","지역","실증적","기반","필요한","계획서","인터뷰조사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715001', '레저스포츠관광론', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '최경호', '레저스포츠관광은 레저스포츠 참여를 기반으로 관광활동이 결합된 분야로, 레저스포츠관광 시설, 프로그램, 상품, 가격 전략, 일반 관 광상품과의 연계 등 다양한 요소로 구성되는 유망 산업이다. 이 분야는 세계 관광시장에서 높은 비중을 차지하고 있으며, 북미·유럽 선진국을 중심으로 성장해 왔고, 향후 중국·일본·한국 및 동남아시아 신흥국을 중심으로 시장 확대와 고용 창출 효과가 지속적으로 증 가할 것으로 전망되고 있다. 이러한 산업 환경 변화에 따라 국내에서도 레저스포츠관광 분야의 전문 인력 양성에 대한 산업적 수요가 빠르게 확대되고 있다. 본 교과목은 레저스포츠관광에 대한 이론적 이해를 기반으로 하되, 지역 내 레저스포츠관광 프로젝트와 연계한 실천적 학습을 통해 산업 현장에서 요구되는 기획·운영 역량을 함양하는 데 중점을 둔다. 특히 프로젝트 중심 수업을 통해 레저스포츠와 관광의 기능과 역할을 통합적으로 이해하고, 신아이디어와 IT 환경에 능동적으로 대응할 수 있는 미래 관광산업 맞춤형 인재 양성을 목표로 한다. 이 를 통해 정부 및 강원도의 전략산업인 관광산업에 기여할 수 있는 현장실무형 전문 인력을 양성하고자 한다. 본 교과목은 레저스포츠관광에 대한 개념적 이해를 토대로, 해당 분야에서 나타나는 경제적·사회적·문화적·환경적 효과를 종합적으로 분석하는 데 목적이 있다. 이를 위해 레저스포츠관광객의 행동 특성을 이해하고, 레저스포츠관광 시스템을 구성하는 핵심 요소인 관 광객, 목적지, 사업체 간의 상호작용과 역할을 중점적으로 학습한다. 또한 레저스포츠관광에 대한 전반적인 이해를 바탕으로 연구조사, 마케팅, 경영, 개발, 정책 수립, 전문 인력 양성 등 다양한 적용 분 야를 심도 있게 다루며, 이론과 실무를 연계한 분석 역량을 함양하고자 한다. 아울러 국내·외 레저스포츠관광의 최신 동향과 주요 이 슈를 분석함으로써 지속가능한 레저스포츠관광의 발전 방향을 전망하는 능력을 기르는 것을 목표로 한다. 2. 교과 목표 ■ 교과목표 본 강의는 강의식 수업과 프로젝트 중심 수업을 병행하여 운영되며, 수강생들은 이론적 학습을 바탕으로 국내·외 레저스포츠관광 동 향을 분석하고, 지역 내 레저스포츠관광 자원을 활용한 아이템 발굴 및 기획을 수행하게 된다. 특히 1p 분량의 기획서를 포함한 프로 젝트를 통해 레저스포츠관광 프로그램의 기획과정을 직접 경험함으로써 현장 적용이 가능한 실무 역량을 체계적으로 강화하는 것을 지향한다.', '{"있다","레저스포츠관광","질의응답","레저스포츠관광의","이해하고","설명할","레저","운영","기획서","스포츠","관광객","레저스포츠","기획","방향을","지역","프로젝트","시청","개념과","관광","이해한다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207601', '인사행정론', '사회과학대학', '사회과학대학', 0, 3, '전선', '최창현', '본 교과는 정부목표를 효율적으로 달성하기 위한 인사행정에 대한 기본적 개념과 이론에 대하여 학습하고, 엽관제, 실적제, 계급제와 직위분류제, 임용, 교육훈련, 동기부여, 공무원의 행동규범, 부패 등 구체적인 인사제도에 대해 파악하도록 한다. 이를 통해 인사행정 의 기능을 이해하고 인적자원 관리능력을 함양하고, 나아가 효율적인 인사행정을 수행 할 수 있는 발전적 방향을 모색한다. 본 수업을 통하여 1.인사행정의 개념과 중요성을 이해한다. 2.인사행정의 이론과 제도적 발달에 대해 전반적인 학습을 한다. 3.공무원의 임용, 퇴직, 관리와 관련된 인사기법 및 인사행정 개혁에 대해 학습한다.', '{"인사행정의","계급제와","직위분류제","교육훈련","동기부여","행동규범","대해","개념과","엽관제","임용","공무원의","한다","인사행정","인사체계의","유형","생각해볼","철의","삼각형과","관료마피아","공직"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715002', '식음료경영론', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '지수', '식음료 사업의 기본이 되는 호텔산업을 바탕으로 하여, 식음료산업에 대한 전반적인 이해와, 경영.관리에 대한 깊이 있는 토의와 실무 에 관한 공부를 기본으로 하며, 경영 과정에 필요한 다양한 마케팅 기법 또한 함께 연구함. 4차 산업을 거치며 현대 사회는 서비스, 커뮤니케이션 그리고 마케팅이 중요시 되고 있다. 그래서 이번 강의에서는 대한민국의 중요 한 미래 먹거리 관광 산업과 관광산업에서 가장 중요시 되는 호텔 산업을 바탕으로하여, 식음료경영에 대한 전반적인 실무 경영 능력 과 함께 서비스 마케팅 요소를 공부 할 것이다.', '{"교재","자료","포함","관리","마케팅","서비스","가장","식음료","식음료경영에","식음료경영에서","중요한","축의","하나인","전반적인","이해와","경영","관한","커뮤니케이션","되는","함께"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207603', '조직행정론', '사회과학대학', '사회과학대학', 0, 3, '전선', '정용남', '이 과목은 조직구조와 조직인의 행태에 대한 학습을 통해 학생들의 조직관리 능력을 배양하려는 목적이 있다. 조직구조 측면에서는 조직의 구조와 기능에 영향을 미치는 외부 환경, 조직 성공을 결정하는 요소, 조직의 구조와 설계 이슈를 다루게 되며, 조직행태와 관 련해서는 동기부여, 리더십, 갈등관리, 커뮤니케이션 방법 등을 다룰 것이다. 행정학 분야의 필수 핵심 과목으로 인접 사회과학(사회 학, 심리학, 경영학 등)의 연계과목으로서도 중요한 위치를 차지하고 있다. 특별히 공공기관의 수요 기반 NCS(국가직무능력표준) 지 정 과목으로 공공인재융합전공과 정치행정학과의 코드쉐어 과목으로 운영된다. 이번 학기부터 조직 사례 분석에 초점을 맞춰 플립 러닝(절대평가) 방식으로 수업을 진행하게 된다. 이 과목을 통해서 학생들은 조직분석 및 조직설계, 의사소통 및 리더십 관련 역량을 배양할 수 있을 것이다.', '{"조직의","조직","리더십","조직구조론","과목으로","있다","구조와","것이다","종류와","유형","조직이론의","발달사","조직환경","관리","조직가치와","주제","중간고사","주차","구성요소","조직형태"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715003', '관광의이해', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '전진희', 'This course provides an overview of the tourism industry, including its components, impacts, and significance. Students will explo re key concepts, trends, and challenges in tourism, gaining foundational knowledge to understand the dynamic nature of this glo bal industry By the end of this course, students will be able to: - Define tourism and its core components. - Identify the economic, social, cultural, and environmental impacts of tourism. - Analyze key trends and challenges in tourism development. - Understand the roles of stakeholders in the tourism industry. - Explore the decision-making process of tourists.', '{"관광경영론","수업을","수강했거나","동시","수강하고","있는","학생은","없습니다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207618', '지방행정론', '사회과학대학', '사회과학대학', 0, 3, '전선', '정용남', '지방화 시대에 학생들이 지방행정에 대해 체계적으로 이해할 수 있도록 지방자치의 본질, 중앙정부와 지방정부의 관계, 지방자치단체 의 조직, 지방자치단체의 계층과 구역, 지방재정 그리고 주민참여와 지방 거버넌스 개념을 다룬다. 학생들은 이 과목 수강을 통해 지 방의 관점에서 국가 정치와 중앙 정부의 행정에 대해서 보다 깊이 이해할 수 있을 것이다. 공무원시험을 준비하는 학생들에게 도움이 되는 과목이며, 정치행정학과와 공공인재융합전공의 코드쉐어(공통과목)로 운영된다. 지방행정에 대한 깊이있는 이해를 위해 학생들 이 관심을 가지는 지방자치단체에 대한 사례분석에 초점을 두며, 플립러닝(절대평가) 방식으로 강의가 진행된다. 이 과목을 통해서 학생들은 풀뿌리 민주주의에 대한 이해, 주민 참여 행정, 중앙과 지방 관계에 대해 폭넓은 지식을 갖출 수 있게 된 다.', '{"지방","관계","지방재정","중앙","정부간","사무배분","지방화","지방자치단체","계층과","구역","지방행정에","대해","이해할","학생들은","지방분권","주민참여","정치","중간고사","주차","구성요소"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207630', '정책분석론', '사회과학대학', '사회과학대학', 0, 3, '전선', '정용남', '좋은 정책을 만들기 위한 정책 문제 분석, 대안의 탐색 및 선택과 관련된 기존의 다양한 기법(시계열, 비용편익분석, 회귀분석, 델파이, AHP 등) 및 실제를 배운다. 정치행정학과와 공공인재융합의 코드쉐어 과목으로 과목 수강을 통해 학생들은 정부 정책에 대한 심도 있는 이해와 분석이 가능하다. 이 과목을 통해서 학생들은 정책 문제 분석, 대안 탐색, 예측 능력을 배양하게 된다.', '{"동영상","문제풀이","현장보충","분석기법","비용편익분석","정책","탐색","기법","예측기법","대안","정책이슈","평가이슈","대안의","시계열","회귀분석","델파이","학생들은","정책분석의","정책문제","문제구조화"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715016', '지속가능한관광(종합설계)', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '이시은', '지속가능한 관광은 관광산업의 지속가능성을 위한 이론을 학습하고, 기후변화와 오버투어리즘, 지방소멸 등 변화하는 환경 속에서 관 광이 나아가야 할 방향을 탐구함. 특히 실제 사례 분석과 토론, 프로젝트 기획을 통해 실무 역량을 키워나갈 수 있음 강의와 토론으로 비판적 사고 및 문제해결 역량을 키울 수 있고, 캡스톤 디자인과 연계해 ESG기반 비지니스 모델설계로 실무역량을 키울 수 있음', '{"관광","조별토론","토론결과","팀활동","지속가능한","프로젝트","동영상","시청","사례","관광의","배경","투어리즘","수용력","중간고사","가치","오버투어리즘","기반","역량을","있음","키울"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207664', '국경과다크투어', '사회과학대학', '사회과학대학', 0, 3, '전선', '김재한', 'Students explore many sites of bordering, including the Korean Demilitarized Zone (DMZ). Borders vary according to the times: pre-modern, modern, and post-modern. Borders may also be classified into demarcation, del imitation, periphery, or march according to their characteristics: whether they are edge or boundary, and whether they are wall or route. Students study armistices, demilitarized zones, border barriers, and peace parks as four modes of buffer zones. Peace park s over the world can be classified into five groups: commemoration and reminiscence of the past, celebration of existing harmon y, international ecological sanctuaries, post-reconciliation projects, and an end to border disputes. Both the quality of the ecological environment and security are public goods. Because these goods are non-rival, different parties share a common interest in producing them. However, because these goods are non-exclusive, there are collective action proble ms in sharing the costs of producing them. Security is pursued by individual nations or alliances while the quality of the ecologic al environment is pursued across nations. Certainly, issues concerning the ecological environment and security may or may not b e reciprocal or overlap. Conceptually, there are three different causal relationships between ecology and security. First, the improvement of security may make the ecological environment better in such cases as detente followed by environmental cooperation, while the degeneration of security deteriorates ecology in such cases as war. Second, a military confrontation may restore natural ecological systems in such cases as the Korean DMZ. Third, ecological cooperation can result in politico-military cooperation while environmental confl ict can instigate military conflict. Though the causal path from ecology to security is limited, it needs to be considered as a mean s to build up security and confidence as long as there is no alternative available. A peace park may belong to the third category. A peace park may be set up for the purpose of making peace as well as keeping peace. Typical peace parks are located on dispu ted borders and their ecological values may be conserved together by the concerned parties. The other part of the course is about the Korean DMZ. Students examine the specificity of the Korean Peninsula (the evolution o f the Japanese occupation, the start of inter-Korean division, the Korean War, the Korean Armistice Agreement, and the solidificat ion of inter-Korean division in chronological order). The Korean DMZ is a typical place along which its visitors still observe the co ld war tension. The Korean DMZ, which was established as a buffer zone for peace, has been militarized and fortified. Such buffer zones may cause war or deter it. The historical significance and economic value of the Korean DMZ are also discussed. Students observe and analyze conflictual borders with concepts and practices, suggesting some policy implications for dark touris m. Several tours are provided to students. Most tours last less than three hours during class hours. Examples include the DMZ O bservation Deck (Chilseong Observatory) and the Memorial Hall for Ethiopian Veterans in the Korean War. One-day tours are also possible if most students of the course wish. Border regions are glocal sites where global and local attributes coexist. Foreign visitors to Korea often list the border region bet ween North and South Korea as a top tourist destination. The local government of Gangwon Province, which prioritizes the touri sm industry, has attempted to encourage the development of local tourism products by offering various facilitation tours and su bsidizing large travel agencies, but these efforts have been unsuccessful. Recognizing this context, the curriculum focuses on bot h theory and practice. Lecture contents that cannot be easily imitated by other universities will provide students with a differentia ted competitive edge.', '{"the","and","dmz","korean","borders","are","border","peace","security","ecological"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715024', '항공운송서비스론', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '윤덕화', '항공운송사업은 인적, 물적 교류의 매개수단으로서, 글로벌 시대에 사는 우리에게는 꼭 필요한 부분이다. 관광산업이 발전함에 따라 그 중요성이 더욱 커지고 있으며, 항공사는 관광기업의 대표주자로 관광업에 있어서도 핵심적 위치를 차지하고 있다. 본 과목에서는 가까운 미래에 항공서비스 직무에 종사하게 될 학생들이 반드시 알아두어야 할 항공운송서비스의 경영이론 및 항공전문지식을 학습 한다. 더불어 기본 실무 지식들을 학습하여 항공사에 종사하기 위해 필요한 자질과 태도를 함양한다. 본 과목에서는 가까운 미래에 항공서비스 직무에 종사하게 될 학생들이 반드시 알아두어야 할, 항공운송서비스의 경영이론 및 항공 전문지식을 학습한다. 더불어 기본 실무 지식들을 학습하여 항공사에 종사하기 위해 필요한 자질과 태도를 함양한다. 지식 : 항공운송서비스의 경영이론 및 항공전문지식에 대해 설명할 수 있다. 기술 : 항공운송서비스 직무에 맞는 언어적/비언어적 커뮤니케이션 기술을 활용할 수 있다. 태도 : 항공운송서비스 종사자에게 필요한 서비스 마인드와 전문적인 자세를 갖춘다.', '{"있다","항공사","설명할","대해","통한","향상심화학습","교수강의","인터넷","모든","강의자료는","스마트리드에","공유합니다","토론과제","검색","토론을","서비스","정의에","마케팅","커뮤니케이션","대해서"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715025', '관광조사방법', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '김도희', '본 교과목은 마케팅조사를 위한 기초적인 지식을 습득하고, 실제적인 조사문제 해결을 위해서 SPSS(사회과학을 위한 통계패티지)를 활용하여 기본적인 통계기술 습득을 목적으로 하고 있다. 즉, 본 수업은 문제설정, 조사설계, 자료수집 방법, 데이타수집, 자료분석 및 해석, 보고서 작성 등 마케팅 조사를 위한 기본적인 내용을 학습하고 통계프로그램을 활용하여 마케팅 조사문제를 해결하는 능력 배 양을 목표로 한다. 조사방법론의 기본과정으로 문제설정, 조사설계, 자료수집, 샘플선정, 자료분석 및 해석, 보고서 작성의 마케팅조사의 전 과정에 대한 이해를 도모하고, 통계프로그램(SPSS)를 활용하여 마케팅 조사 문제를 해결하는 능력 배양 자료수집 경험, 데이타 코딩방법 습득, 기본적인 통계기법(차이분석, 분산분석, 상관분석, 회귀분석 등) 학습', '{"통계기법","자료분석","설문지","표본추출","분산분석","상관분석","조사목적의","설정","조사디자인","탐험조사","기술조사","인과관계조사","자료와","정성조사","서베이법과","관찰법","관찰기록지","개발","측정의","중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207665', '캡스톤디자인-MIS', '사회과학대학', '사회과학대학', 0, 3, '전선', '장윤정', '본 교과목은 MICE 산업(Meetings, Incentives, Conventions, Exhibitions)을 단순한 산업 또는 비즈니스 영역이 아닌, 문화적 가치 창출 과 공공정책, 거버넌스가 결합된 융합적 분야로 이해하고 분석하는 것을 목표로 한다. 정치·행정학적 관점에서 MICE 산업이 도시·지 역 발전, 문화정책, 공공？민간 협력, 글로벌 네트워킹과 어떠한 방식으로 연결되는지를 이론과 사례를 통해 탐구한다. 본 강의는 100% 영어로 운영되며, 내·외국인 학생이 함께 참여하는 혼합 수업 환경에서 강의, 사례 분석, 토론, 워크숍 중심으로 진행 된다. 학기 전반부에는 MICE 산업의 구조와 글로벌 동향, 문화·정책·거버넌스 이론을 중심으로 분석적 기초를 형성하고, 학기 후반부 에는 캡스톤 디자인 프로젝트를 통해 미래형 MICE 시나리오를 설계·발표함으로써 실천적 문제 해결 역량과 글로벌 소통 능력을 함양 한다. This course examines the MICE industry (Meetings, Incentives, Conventions, and Exhibitions) as an integrated field where cultural value creation, public policy, and governance intersect. From a political and administrative perspective, the course explores how MICE functions in relation to urban and regional development, cultural policy, public？private collaboration, and global networkin g. Conducted entirely in English, the course brings together domestic and international students in a mixed classroom environment. The first half of the semester builds analytical foundations through lectures and case studies, while the second half adopts a cap stone design format in which students develop and present future-oriented MICE scenarios, strengthening practical problem-solv ing skills and global communication competence. 2. 교과 목표 ■ 교과목표 본 교과목의 목표는 학습자가 MICE 산업을 문화적·정책적·거버넌스적 관점에서 비판적으로 해석하고, 이를 바탕으로 미래 사회에 요 구되는 MICE 전략과 모델을 주도적으로 설계할 수 있는 역량을 기르는 데 있다. 학습자는 단순한 사례 이해를 넘어, 문화적 의미와 공공적 가치, 이해관계자 간 협력 구조를 고려하여 MICE 현상을 분석하고 문제를 구조화하는 능력을 함양한다. 또한 캡스톤 디자인 기반의 팀 프로젝트를 통해 정책 분석, 시나리오 기획, 전략적 의사결정 과정을 경험함으로써, 실제 정책·산업 환 경에 적용 가능한 MICE 기획 역량과 실행 논리를 개발한다. 이 과정에서 영어를 활용한 전문적 토론과 발표, 디지털·AI 도구를 활용한 분석 및 기획 능력을 강화하며, 다문화적 협업 환경 속에서 책임 있는 의사결정과 창의적 문제 해결 태도를 형성하는 것을 목표로 한 다. The objective of this course is to enable students to critically interpret the MICE industry through cultural, policy, and governance perspectives and to independently design strategic MICE models suited to future societal needs. Students develop the ability to analyze MICE phenomena by considering cultural meaning, public value, and stakeholder collaboration, moving beyond descripti ve case understanding toward structured problem framing. Through a capstone design-based team project, students experience policy analysis, scenario planning, and strategic decision-ma king processes, thereby cultivating practical competencies applicable to real-world policy and industry contexts. The course furthe r aims to strengthen professional English communication, digital and AI-assisted planning skills, and responsible, creative proble m-solving attitudes within a multicultural and collaborative learning environment.', '{"시나리오","사례","산업","그룹","미래형","워크숍","설계","산업의","활동지","최종안","또는","글로벌","강의록","자료","주차","구성요소","초안","팀별","문화정책","협력"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207666', '선거와지역사회', '사회과학대학', '사회과학대학', 0, 3, '전선', '김재한', '선거라는 시공간을 통해 지역사회 문제해결을 연습한다. 2026학년도 수업의 경우, 시·도지사 및 교육감 예비후보자등록 신청(2월 3일 부터), 각 후보자의 공약 준비, 각 후보자의 선거운동, 후보자 토론회, 사전투표(5월 29일 및 30일), 투표(6월 3일), 선거비용 보전신청 마감(6월 15일)까지 이르는 제9회 전국동시지방선거 일정 속에서 지역사회 문제를 실질적으로 해결해보는 현장 관찰 중심의 융합 수 업이다. - 자유민주주의 선거의 의미, 선거제도의 효과, 유권자의 투표행태, 정치인의 선거전략, 선거 결과의 예측, 후보 공약의 기능, 선거관리 의 방향, 선거의 지역문제 해결 및 한계 등을 이해한다. 특히 지역사회 문제가 선거 과정에 어떻게 해결될 수 있는지에 대해 학습한다. - 수강생이 직접 체득할 수 있는 문제 상황 속에서 개념과 원리를 학습하고 또 실제 상황에 적용하여 자신의 것으로 만든다. - 개별 지식보다 융합 지식의 함양을 목표로 하며, 삶에서 자기주도적 태도를 형성한다. - 수강생이 ‘수동적 학생으로부터 능동적 시민’으로 바뀔 수 있도록 교육하는 한편, 학생들과 함께 로컬 시민정치행정을 관찰하고 지 역 문제의 해결을 시도해본다. 졸업 후 지역사회를 매개로 활동하는 데에 필요한 학습과 성찰의 기회를 제공한다. 수강생은 현장에 근거를 둔 시민민주주의, 마을민주주의, 생활정치, 풀뿌리 등을 학습 또는 경험할 것으로 기대한다.', '{"지역사회","선거","선거의","지역문제","문제와","공약","후보자","토론회","선거제도의","효과","유권자의","투표행태","정치인의","선거관리","기간","후보자의","속에서","융합","등을","수강생이"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715029', '스마트관광', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '송화성', '관광산업의 디지털 전환에 대응하기 위해 인공지능, 빅데이터 등 스마트 기술을 활용한 관광의 개념과 실제사례를 이해하고, 빅데이 터를 기반으로 한 지역현황 이해와 함께 지역관광의 활성화를 위한 스마트관광 활용방안을 모색하고자 함 스마트 관광에 대한 이해 및 새로운 스마트 관광 아이디어 구상을 해보는 것을 목표로 함. 이에 (1) 스마트 관광에 대한 기본 지식을 배우고 (2) 스마트관광이 필요한 지역과 관련 관광 분야를 찾아보고자 함', '{"스마트","디지털","관광","스토리텔링","지역","지역관광의","아이디어","퀴즈","관광에","개별소개","조구성","로컬의","만남","기술의","현실과","전환","관광요소","기술","융합","토의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207667', '글로컬공동체와유네스코', '사회과학대학', '사회과학대학', 0, 3, '전선', '김재한', '공동체 내에서는 조화와 평화가 쉽게 작동할 것으로 기대되어, 국제 분쟁의 해결책으로 국제공동체 설립이 언급된다. 유라시아를 아 우르는 국제공동체가 설립되지 않았고 역내 국가 간 갈등도 완화되지 못하고 있다. 이 수업에서는 글로컬공동체를 탈근대적 국제공 동체로 이해한다. 글로컬공동체의 시간적 선례로 고대 동북아시아 질서부터 탐구하며, 공간적 선례로는 유럽연합(EU) 및 동남아국가 연합(ASEAN)을 탐구한다. 첫째, 글로컬 개념에 대한 정확한 이해이다. 글로컬대학 사업을 수행하고 있는 본교 정책에 맞춰 신설되는 교과목이다. 국제공동체는 국경을 넘는 초국경을 전제하고, 따라서 국제공동체 설립은 탈국가화와 그 궤를 함께한다. 국제공동체는 탈국가화이자 탈제국화로 접 근할 수 있다. 로컬과 글로벌이 함께하는 이른바 글로컬공동체이다. 둘째, 국제평화 및 번영에 대한 이해이다. 유라시아에서는 국제공동체가 구축되지 않았고, 역내 국가 간 갈등도 완화되지 않았다. 이 러한 문제에 대한 정확한 진단과 처방이 필요하다. 수강생들은 국제공동체의 선례와 함께 글로컬공동체에 대해 분석하고 구상해 볼 것이다. 셋째, 국제공동체 관련 다양한 정보는 인터넷, 생성형 AI 등에서 쉽게 찾을 수 있으므로 관련 정보를 학습자에게 주입하는 것은 교과 목표가 아니다. 대신에 공동체 구축 원리의 이해가 교과 목표이다. 공동체 구축의 원리는 한반도를 넘어 전 세계의 특정 지역, 나아가 서 세계공동체 설립에도 적용될 수 있을 것이다. 넷째, 미래의 평화 및 공동체 설립은 젊은 세대에게 달려 있는데, 다양한 가치관이 서로 양립할 수 있는 글로컬공동체에 대해 젊은 세 대가 성찰해봄으로써 보다 나은 세계를 만든다는 교과 목표도 있다.', '{"강의안","글로컬공동체","국제공동체","공동체","유라시아","동아시아","글로컬공동체와","있다","고대","생성형","교과","쉽게","국제공동체가","않았고","역내","국가","갈등도","완화되지","정확한","이해이다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715032', '로컬문화관광콘텐츠', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '송화성', '본 수업은 지역의 자원성을 활용한 문화, 역사, 축제, 음식, 종교, 예술, 커뮤니티 등 다양한 로컬문화관광 콘텐츠를 발굴하고자 함 프로젝트형 수업이 아닌 문제해결의 일환으로 특정 지역(춘천시, 시흥시 등)을 대상으로 교수 강의와 외부 전문가와 연계한 컨설팅 을 제공하여 문화관광콘텐츠에 대한 이해를 향상시키고 관심을 갖게 하고자 함 본 강의를 통해 학생들은 (1) 문화관광 및 문화관광콘텐츠 개념, 특성 및 유형 등을 이해하며, (2) 지역(로컬)의 자원성에 기반한 관광 자원을 찾고 이를 콘텐츠로 구성하여 표현하는 훈련을 통해 관광콘텐츠기획자로서 기본 소양을 갖추게 하고자 함', '{"토의","로컬문화관광콘텐츠","문화관광","지역","특강","현장답사","기획","컨설팅","검토","유산관광","인터뷰","있는","팀별","논의","콘텐츠","아이디어","조별","하고자","강의소개","강의계획서"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('207668', '20세기동아시아의전쟁과평화', '사회과학대학', '사회과학대학', 0, 3, '전선', '이삼성', '20세기로의 전환기로부터 제2차 세계대전 후 오늘에 이르는 120여년의 동아시아에서 전쟁과 평화의 문제를 조명합니다. 20세기 전반기 동아시아의 제국-식민지 질서와 전쟁 유산의 역사적 특성, 그리고 아시아-태평양전쟁과 중국내전 및 한국전쟁의 결과 로 구성된 전후 동아시아 국제질서의 고유성과 연속성을 탐구합니다. 20세기 전반기와 후반기를 사건들에 대한 인식과 함께 그 전체 적 구조에 대한 개념적 접근을 시도합니다. 지난 120년의 기간 동아시아 질서에 대한 이 수업의 주제를 구성하는 테마는 크게 두 가지입니다. 전쟁과 평화라는 테마, 그리고 인 권과 민주주의라는 테마입니다. 이 수업에서 전쟁과 평화의 구조는 ''동아시아 제국체제'' 그리고 ''동아시아 대분단체제''라는 개념틀을 통해서 접근합니다. 인권과 민주주의의 문제는 ''전체주의와 반공 파시즘'', 그리고 그 극복이라는 개념틀을 통해서 조명을 시도합니다 . 다만 그 두 테마는 상호연관되어 있으며 많은 점에서 불가분할 수 있습니다. 전쟁과 평화의 문제는 나라들 사이의 지정학적 긴장, 정치사회적 체제와 이념의 간극으로 인한 긴장, 그리고 역사문제로 인한 ''역사심 리적 긴장''이라는 개념으로 접근합니다. 이 가운데 지정학적 긴장의 차원은 국력(군사력과 경제력이 중심에 있는)의 상대적 발전의 추 세라는 문제가 그 핵심적인 요소의 하나입니다. 아울러 주요 국가들 사이의 상호 정책의 패턴을 볼 필요가 있습니다. 이러한 점들을 염두에 두고 이 수업에서 전후 동아시아 질서의 구조와 그 전개, 그리고 오늘 한국을 포함한 동아시아 사회들이 직면 한 숙제들과 딜레머를 토론합니다. 20세기 전반에 걸친 동아시아 국제질서의 구조와 역사적 전개를 약 10여개의 테마를 중심으로 조명하고 토론합니다.', '{"동아시아","교수의","강의와","교수","그리고","세기","제국체제의","전후","국제질서의","전쟁과","동아시아의","구조와","세계대전과","이후","태평양전쟁","전쟁의","대분단체제의","년대","동아시아에서","평화의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('715035', '관광리빙랩(캡스톤디자인)', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '송화성', '지역사회와 연계하여 지역관광현안을 논의하고 대안을 찾는 현장중심적 문제해결 프로젝트를 진행하여 지역에 대한 관심 제고와 함께 자기 주도형 학습 능력을 함양하는 것을 목표로 한다. 학생들은 기획자(Planner)이자 방문객(Users)으로서 문제점을 파악하고 지 역관광 현안 이해 당사자(공공기관, 민간 및 지역주민 등)와 함께 해결방안을 모색하는 협력적 프로젝트를 추진한다. 지역사회와 연계하여 지역관광현안을 논의하고 대안을 찾는 현장중심적 문제해결 프로젝트 진행을 통해 지역에 대한 관심 제고와 함 께 자기 주도형 학습 능력 함양 (대상지: 시흥시, 춘천시, 고성군 중 택 1 예정)', '{"토의","리빙랩","사례","현장답사","문제점","관계자","기획","답사","실험","조별","관광의","쟁점","리빙랩의","중간고사","면담","관광리빙랩","운영과정","현장실험","통한","대상지"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('716000', '의약신소재특강', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '이찬희', '1. 다양한 분야에서 현재 활발하게 일하고 계신 젊은 연자들을 모시고 자유롭게 토의할 수 있는 기회를 가진다. 2. 가장 최신의 연구 동향을 파악하여 신소재 개발 및 기초 의과학 연구에 활용할 수 있는 방안을 자유롭게 논의한다. 생명과학과 기초의학, 의학과 관련된 다양한 분야의 전문가들의 강연을 듣고 앞으로 진행할 연구, 신소재 개발에 활용함을 목표로 함.', '{"모시고","분야의","듣고","전문가들을","의견을","토의한다","전문가","리스트는","추후공지함","자유롭게","있는","신소재"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209111', '커뮤니케이션입문', '사회과학대학', '사회과학대학', 0, 3, '전선', '박동진', '이 과목은 광고홍보학과의 필수 기초 교과목으로서 본 과목을 통해 여러분은 광고홍보학을 전공하는데 필요한 기초 개념과 이론들 을 학습하게 될 것입니다. 이 개념과 이론들은 여러분의 전공 수업은 물론 심화 학습을 위한 기반을 제공할 것입니다. * 본수업은 광고홍보학과 신입생 및 편입생을 대상으로 진행되는 수업입니다. 본 수업을 통해 여러분은 다음의 것을 이해해야 합니다. ㅇ 커뮤니케이션이란 무엇인가? ㅇ 커뮤니케이션 이론은 왜 중요한가? ㅇ 커뮤니케이션 이론은 현상을 어떻게 설명하고 예측하는가? ㅇ 커뮤니케이션 이론의 가정과 한계는 무엇인가?', '{"교재","강의자료","스마트캠퍼스","커뮤니케이션","스마트","캠퍼스","자료","주차","구성요소","모델","여러분은","개념과","것입니다","무엇인가","이론은","교과목","우리는","이론을","공부해야","하나"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('716018', 'GMP와의약품생', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '홍희선', 'GMP란 무엇이며 의약품 제조 시 GMP 환경의 필요성을 이해한다. 전반적인 의약품 생산 공정에 대하여 공부하며 의약품 제조 시의 품질 관리 등에 대한 유효성, 안전성 및 안정성 시험 등의 중요성을 이해하며 의약품 분석법에 대하여 공부한다. 실제로 의약품 제조 에 적용되는 공정, 시설 및 시스템의 구성에 대하여 의약품의 종류에 따른 적용되는 GMP 기준에 대하여 학습한다. 1. 의약품 및 관련 GMP 운영 및 규정 이해를 통한 의약품 생산 관리 역량 2. GMP 문서 작성 및 관리 역량 3. 의약품 제품 설계, 개발 및 품질 관리/보증, 인증 관리 역량 4. GMP 규정에 적합한 제품 개발 공정 설계 및 운영 관리 역량 5. GMP 적합 의약품 제조소 시설 설계 및 관리 역량 6. GMP 기준 관리 자격증 취득 역량 7. 글로벌 GMP 규정 이해 및 인증 관리 역량 8. 의사 소통 역량', '{"관리","구성","의약품","규정","제조","품질관리","제품","정의","의약품의","품질","시설","기준서","밸리데이션","기준","공정","종류","고려사항","밸리데이션의","생물학적","보증"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209112', '광고홍보조사방법론', '사회과학대학', '사회과학대학', 0, 3, '전필', '홍석민', 'Research Methodology will introduce students to social science research techniques as they have been applied to Advertising, M arketing, media, consumer behavior, and attitude research. The course has been developed to (1)acquaint students with the minant research methods and statistics used in Advertising, marketing, and mass communication (2)familiarize students with rese arch as a disicipline (3)guide students through the process of conceiving, organizing, executing, analyzing, and reporting survey r esearch, content anlysis,experiments, focus groups, and other research methods (4)demonstrate how to identify potential advertis ing and marketing problems and opportunities and research solutions. 조사방법론수업을 통해 학생들은 광고홍보분야에 필수적인 소비자의 이해를 높일 수 있으며, 다양한 조사방법론을 통해 데이터를 바 라보는 안목을 높이고, 통계분석을 이해하기 위한 통계에 대한 기초지식을 습득하여 취업후 필요한 기획서작성에 필요한 기초지식을 함양한다. 통계에 대한 이해를 습득', '{"강의노트","주교재와","토막시험","통계에","신뢰도와","타당도","이해탐구","연구와","윤리","온라인","인터넷을","주차","구성요소","기초통계에","모수통계","이해하기","이해를","기초지식을","필요한","과학의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209401', '광고개론', '사회과학대학', '사회과학대학', 0, 3, '전선', '송영아', '본 교과목은 Belch & Belch의 Advertising and Promotion: An Integrated Marketing Communications Perspective를 기반으로 광고 및 통합마케팅커뮤니케이션(IMC)의 이론적 체계와 전략적 실행 과정을 이해하는 것을 목표로 한다. 광고의 역할, 소비자 의사결정과 정, 크리에이티브 전략, 매체전략, 디지털 광고, 브랜드 커뮤니케이션 전략 등을 통합적으로 학습하며 실무적 문제 해결 역량을 강화 한다. 지식 광고 및 IMC의 개념과 이론적 기반을 설명할 수 있다. 소비자 정보처리과정과 설득이론을 이해하고 광고 전략에 적용할 수 있다. 크리에이티브 전략과 매체 전략의 구조를 이해한다. 디지털 광고 및 통합 브랜드 커뮤니케이션의 최신 흐름을 설명할 수 있다. 기술 광고 캠페인 목표에 따른 전략적 메시지 구조를 설계할 수 있다. 타깃 분석을 기반으로 IMC 캠페인 전략을 수립할 수 있다. 실제 광고 사례를 이론적 틀을 활용하여 분석할 수 있다. 태도 광고의 사회적 책임과 윤리적 쟁점을 비판적으로 성찰한다. 소비자 관점에서 브랜드 커뮤니케이션을 사고하는 태도를 기른다.', '{"광고","있다","이해한다","설명할","전략","소비자","구조를","커뮤니케이션","전략과","매체","유형","과정을","광고의","브랜드","전략의","메시지","전략적","크리에이티브","디지털","캠페인"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('513022', '나노소재및공정', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '박종민', 'This course provides the principles and applications of various nanomaterials. This course aims to obtain an overall understandin g of the phenomena occurring in nanoscale materials, an understanding of the size effect on the physical, chemical, and mechani cal properties of materials, and technologies for the synthesis, characterization, and application of nanomaterials. Finally, this course provides insight into the combination of concepts between the different disciplines from which nanotechnolo gy emerged, such as chemistry (synthesis and modification of nanomaterials), physics (rules of the nanoworld and principles of a nalytical methods), biology (all those proteins and microorganisms), medicine (drug delivery and diagnostics), and engineering (d evice and material design). 본 교과목에서는 다양한 나노물질의 제조원리, 특성과 그 응용에 대해 학습한다. 본 교과목에서는 나노물질에서 일어나는 현상에 대 해 전반적으로 이해하고, 물질의 크기가 물리적, 화학적, 기계적 성질에 미치는 영향에 대해 이해하며, 다양한 나노물질의 합성, 특성 분석 및 응용분야 기술에 대해 습득하는 것을 목표로 한다. 최종적으로는 나노기술이 사용될 수 있는 화학, 물리학, 생물학, 의학, 공 학분야 간의 융합적 통찰을 제공하는 것을 목표로 한다. At the end of this course, students will be able to - understand the fundamentals of nanomaterial physics and fabrication technologies - understand the size effect on the properties of nanomaterials - have an insight into the applications of nanomaterials in various nanotechnology', '{"대해","교과목에서는","나노물질의","것을","목표로","한다"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209441', '광고카피작성I', '사회과학대학', '사회과학대학', 0, 3, '전선', '박선미', '광고 카피라이팅은 광고 비즈니스의 기본을 의미하는 ‘광고’, 그리고 ‘아이디어 발상’, 언어표현의 ‘라이팅’의 3개 영역을 포괄하는 과 목이다. 따라서 이 과목은 광고의 기본 개념을 이해하고 광고기획, 광고전략, 광고 크리에이티브의 기본 지식을 습득함은 물론 아이디 어 발상에서 전개, 언어의 기술을 통한 광고의 최종적 표현능력을 기르는데 초점을 맞추고 논리적 사고 전개를 통한 창의적 표현에 집중한다. 특히 미디어 광고 카피라이팅(글쓰기)의 기본에 중점을 두고 실습을 강화한다. 예비 광고인이 갖춰야 할 카피라이팅에 대한 기본지식을 습득함은 AI시대에 맞춰 카피라이팅의 기본기를 다지는 것에 목표를 둔다. 영상 광고 카피라이팅에서 지면, 인터넷(SNS/ e-commerce)에 이르기 까지 변화무쌍한 미디어 환경에 대처하고 에세이, 홍보기사, C M Song, Testimonial 등 다양한 글쓰기 영역으로 카피라이팅을 확장하는 실습을 겸비한다. 카피 아이디어 발상과 라이팅의 숙달을 위해 매 시간 카피라이팅 과제와 발표가 주어진다.', '{"카피라이팅","통한","카피라이팅의","광고","글쓰기","브랜드","사례를","이해한다","컨셉","캠페인","기술을","대해","아이디어","하는","테크닉","인간","어떻게","실습한다","기업","이해하고"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('513024', '의생명공학개론', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '박민', 'This course aims the understanding of the basic biochemistry, medical diagnosis. Various kinds of analytical methods for the med ical diagnosis including immunboassays, biosensors will be introduced. The structures of protein, DNA and their expressing mech anisms will be also introduced. 1. Introduction to bio-nano technology 2. Materials from biology: DNA & RNA 3. Materials from biology: Protein & peptide: function & structures 4. Introduction to enzymes: fuction & structure 5. Kinetic models & application of enzymes 6. Immunochemistry 7. Protein analysis 8. Expression of peptide & proteins 9. Recombinant technology', '{"protein","dna","and","analysis","rna","proteins","enzymes","applications","introduction","expression"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209490', '크리에이티브전략', '사회과학대학', '사회과학대학', 0, 3, '전선', '박선미', '광고 크리에이티브 전략은 실제 광고 현장에서 활동하는 다양한 크리에이터들의 관점에서 크리에이티브를 생산해 내는 전반적인 과 정을 배움으로써 현장에 대한 이해와 비즈니스의 기본지식을 습득하는 과목이다. 미디어 환경의 급변화에 따라 영역이 확대된 광고 영역을 살펴보며 다양한 장르의 광고 크리에이티브 산업을 포괄적으로 이해하고 본인의 적성을 발견하고 광고 산업 분야의 진로 탐색에 도움을 준다. 1. 미디어 환경의 변화에 따라 다양해진 광고 크리에이티브에 대한 기본지식을 습득한다 2. 광고 크리에이티브 전반에 대한 개념을 이해하고 프로세스를 익힌다 3. 자발적인 광고인의 자세로 생각하고, 그 생각을 커뮤니케이션 한다 4. 크리에이티브 분야로 진로를 희망하는 학생들에게 본인의 적성을 파악하고 진로를 탐색하고 그에 따른 필요 역량을 사전에 준비하 도록 한다', '{"광고","사례","크리에이티브","대해","사례를","미디어","컨셉","브리프","미디어에","중심으로","광고에","배운다","디지털","이해를","전반적","브랜딩의","실제","현장에서","관점에서","이해와"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209499', '광고홍보그래픽커뮤니케이션', '사회과학대학', '사회과학대학', 0, 3, '전선', '안보영', '현대의 디지털 비즈니스 플랫폼에서 아이콘, 타이포그래피 등 시각적인 그래픽 디자인 요소는 핵심적인 역할을 합니다. 광고, 마케팅, 브랜딩, 유튜브, 소셜 미디어 등 다양한 플랫폼에서 사용자의 눈길을 끄는 매력적인 콘텐츠를 제작하는 것은 매우 경쟁 력 있는 능력입니다. 광고기초그래픽 강의를 통해 일러스트레이션과 포토샵을 배우는 것은 현대 비즈니스에서 시각적인 콘텐츠를 효 과적으로 제작하고 활용하는 역량을 키우는 좋은 방법입니다. 이런 역량은 사용자에게 원하는 메시지를 강력하게 전달하고 관심을 끌어내며, 사용자와의 소통부터 브랜드 인식까지 다양한 영역에서 유용하게 활용될 것입니다. * 그래픽 디자인 제작의 프로세스를 이해하고, 기획과 아이디어 발전을 통해 디자인 실무 능력을 키웁니다. * Illustrator, Photoshop과 같은 그래픽 디자인 프로그램을 연습하여 시각적인 표현 능력을 향상시킵니다.', '{"디자인","익히기","질의응답","설명","시범","예제실습","예제를","통한","오브젝트","프로젝트","의견조율","시안","색상","메뉴","툴의","사용법","문자","질의","응답","도구"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('513026', '신소재특강I', '미래융합스쿨', '미래융합스쿨', 0, 2, '전선', '박종민', '융합신소재공학전공의 최종 응용분야인 바이오메디컬엔지니어링의 전문 지식을 함양하기 위하여, 바이오메디컬 엔지니어링 전분야 에 걸친 국내외 전문가들의 특강을 수강하고 관련 내용들을 자기주도형으로 학습한다. 본 교과목은 강의실에서 외부전문가들의 특강을 듣고, 해당 분야에 대한 보고서를 작성 제출하도록하여 청취를 통한 내용 파악 능력 및 자료 조사를 통한 자료 요약 능력을 배양한다. 바이오메디컬엔지니어링 분야 국내외 전문가들의 특강을 통해 전공 분야의 이해를 심화한다.', '{"특강을","외부","연사","초청","특강","국내외","전문가들의","통한","자료","중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('513032', '재료유기화학', '미래융합스쿨', '미래융합스쿨', 0, 3, '전선', '박민', 'This course aims the understanding of the properties of organic and biochemical materials. Various kinds of organic compounds and their reactions will be introduced. Chemical and physical properties of various functional groups will be introduced to unders tanding of the fundamental biochemical materials such as proteins, enzymes, nucleic acids, antibodies. 1. Definition and nomenclature of organic molecules 2. Physical and chemical characteristics of alkanes, alkenes, and alkynes 3. Properties of benzenes and its derivatives 4. Properties of alcohols, ethers, and thiols 5. Streochemistry 6. Understanding of acids and bases 7. Properties of amines, carbonyls, and carboxylic acids', '{"중간고사"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('209503', '설득커뮤니케이션', '사회과학대학', '사회과학대학', 0, 3, '전선', '윤태일', '광고 홍보는 마케팅 프로모션의 일환이면서 동시에 설득 커뮤니케이션의 한 영역으로 간주된다. 이 과목은 커뮤니케이션 이론의 관점에서 광고 홍보의 설득적 구조를 이해하고 현실에 적용시킬 수 있도록 함으로써, 예비 광고홍보 전문가로서의 자세를 함양하고자 한다. - 광고홍보에 필요한 설득 커뮤니케이션의 기본 개념과 이론을 깊이 있게 이해하고 실무 현장에서 적용할 수 있다.', '{"설득컴의","이해하고","자료","강의록","영상","설득컴","수사학적","적용한다","원리를","설득전략에","기초이론을","전략을","이론적으로","분석한다","계통의","기초이론","심리원칙을","설득전략을","분석하고","심리원칙"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('210001', '광고홍보사례분석', '사회과학대학', '사회과학대학', 0, 3, '전선', '송영아', '이 수업은 다양한 광고홍보 사례연구 보고서를 분석하여 관련 개념과 이론을 논의하고 해당 개념과 이론이 실제 상황에서 어떻게 적 용, 확장, 혹은 조정되는지 논의하는 데 그 목적이 있습니다. 이와 더불어 직접 광고홍보 관련 사례를 개발하고 그에 대한 사례 연구를 수행하며 시장상황을 다각도로 탐구하는 기회를 제공하고자 합니다. 다양한 광고홍보 사례연구 보고서를 분석하여 관련 개념과 이론을 논의하고 해당 개념과 이론이 실제 상황에서 어떻게 적용, 확장, 혹은 조정되는지 논의하는 데 그 목적이 있습니다. 이와 더불어 직접 광고홍보 관련 사례를 개발하고 그에 대한 사례 연구를 수행하 며 시장상황을 다각도로 탐구하는 기회를 제공하고자 합니다.', '{"사례","개발","요약","면담","광고홍보","개념과","교수자","개인","활용한","사례연구","보고서를","분석하여","이론을","논의하고","해당","이론이","실제","상황에서","어떻게","확장"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('210002', '프리젠테이션실습', '사회과학대학', '사회과학대학', 0, 3, '전선', '박동진', 'ㅇ 광고홍보 전문가가 되기 위해서는 기획력, 분석력, 창의력과 더불어 소통(발표) 능력이 요구된다. ㅇ 본 과목은 다양한 광고홍보 프레젠테이션 실습을 통해 학생 개개인의 소통(발표) 능력을 향상시키기 위해 마련되었다. ㅇ 소통(발표) 능력은 타고난 것이 아니라 연습을 통해 충분히 계발될 수 있다. ㅇ 본 과목을 통해 학생들은 발표에 대한 자신감과 더불어 자신의 생각을 정리해서 전달할 수 있는 역량을 키우게 될 것이다. ㅇ자신의 생각을 정리해서 효과적으로 전달하는 능력 배양 ㅇ발표에 대한 자신감 획득 ㅇ타인의 발표에 대한 평가 및 분석 능력 배양 ㅇ경쟁PT 성공을 위한 노하우 습득', '{"소통","광고홍보","더불어","발표에","생각을","정리해서","중간고사","주차","구성요소","애드캠프","전국","대학생","대회","리뷰","질문","반대","대응법","영어"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('210006', '캡스톤디자인-디지털광고', '사회과학대학', '사회과학대학', 0, 3, '전선', '김찬', '최근의 변화하는 광고시장은 기존의 영상매체 광고에서 디지털 광고의 비중이 급격하게 증가하고 있습니다.그중에서도 유튜브 광고 는 커다란 흐름으로 자리 잡고 있으며 그 비중은 점차 커지고 있다고 판단됩니다. 이에 학생들에게 디지털 광고의 이론 및 실습과 더 불어 유튜브 채널 개설을 목표로 유튜브 컨텐츠 제작 실습을 진행 하려고 합니다.강의 초반에는 디지털 영상 제작에 관한 강의를 중 심으로 하여 실제 케이스를 통한 디지털 광고에 대한 이해를 향상 시키고 강의 후반에는 직접 콘텐츠를 제작함으로써 전반적인 유튜 브 제작에 대한 과정을 이해하고 체득할 수 있을것 입니다. 조별로 완성된 제작컨텐츠는 유튜브채널 광대들에 업로드 할 예정입니다. https://www.youtube.com/@gwangdaes 그리고 이번학기는 학생들의 촬영조명에 대한 강의를 추가하여 실제작에 도움이 되게 하겠습니다 강의 전반부는 이론 중심으로 후반부는 실기 중심으로 진행할 예정이며 실제 제작과정을 통하여 광고 제작의 프로세스와 이헤를 높 이는데 중점을 둘 예정입니다. 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 2. 교과 목표 ■ 교과목표 전반적인 디지털 광고의 이해도 향상및 유튜브 제작실습을 통한 유튜브 채널 개설', '{"광고","디지털","교과","교과목표","유튜브","영상","영상자료","해외","협의","자료","촬영","조별로","리뷰","채널","컨텐츠","통한","노트와","촬영의","렌즈의","종류"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('210008', '소셜미디어와광고홍보', '사회과학대학', '사회과학대학', 0, 3, '전선', '최정화', '본 수업은 소셜미디어의 특성과 운영원리에 대한 이해를 바탕으로 소셜미디어마케팅 기획 및 운용 전략을 습득하는 것을 목표로 한 다. 소셜미디어는 브랜드 인지도 향상, 핵심 소비자 확인, 소비자와의 관계형성, 판매촉진 등을 위해 현대의 마케터 및 광고홍보전문 가에게 필수적인 커뮤니케이션도구가 되었다. 본 수업에서는 소셜미디어 운영 및 관리의 기본 원칙과 소셜미디어 운영 시뮬레이션, 그리고 가상의 고객을 위한 소셜미디어 컨텐츠 작성실습을 통해 소셜미디어마케팅을 위한 실질적인 경험을 제공할 것이다 기업이나 기관의 광고홍보 매체로서의 소셜미디어 운영을 기획하고, 실행하고, 평가하는 과정을 학습함', '{"소셜미디어","소셜미디어컨텐츠","전략","기획","매체","운영","기말프로젝트","콘텐츠","활동","광고홍보","진단조사","설정","스케줄링","블로그","카드뉴스","이미지","영상콘텐츠","중간고사","작성","개별과제"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('210011', '디지털커머스와프로모션', '사회과학대학', '사회과학대학', 0, 3, '전선', '최윤정', '디지털상의 커머스와 광고의 관계성, 핵심 개념, 실무를 이해. 데이터를 활용하여 효과적인 디지털 프로모션을 기획하고 실행할 수 있는 역량함양. 이것을 브랜딩과 역으로 연결 시키는 사고력을 갖추게 함. 실제 커머스의 적용 사례등을 통해 현장감 있는 지식을 공유하고 가장 최신 트랜드와 미래 예측 모델을 탐구 할 수 있게 함. 실무 중심 워크샵 통해 공유된 지식을 적용하여 내재화 하게 함. 디지털 커머스와 퍼포먼스 광고의 [핵심 개념 &UX] 실무 사례와 모의 퍼포먼스 광고통한 [숫자 분석] 데이터 중심 프로모션을 브랜딩과 [연결하는 사고력]', '{"디지털","사례","광고","퍼포먼스","프로모션","커머스","전략","도출","고객","실사례","시대","머신러닝","기반","브랜드","설계","데이터","브랜딩","전략과","커머스와","광고의"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('210012', 'AI광고제작실습', '사회과학대학', '사회과학대학', 0, 3, '전선', '박장춘', '본 과목은 광고홍보학과 학생들이 생성형 AI 도구를 사용하여 광고 기획·제작의 전 과정에 전략적으로 활용할 수 있는 실무 역량을 키우는 것을 목표로 한다. 단순한 도구 사용법 습득을 넘어, ''인간이 시작하고 인간이 마무리한다(Humans begin, humans conclude)''는 원칙 아래 AI를 창의적 증폭 도구로 활용하는 Heuristic Prompting 방법론을 훈련한다. ChatGPT, Claude, Midjourney, Runway, Suno AI 등 최신 멀티모달 AI 도구를 활용하여 광고 기획, 카피, 비주얼, 영상, 음악, 캠페인 기획서 등을 실제로 제작하고, 최종적으로는 실제 브랜드 또는 사회 문제를 대상으로 한 통합 AI 광고캠페인을 완성한다. - 생성형 AI의 작동 원리와 광고 산업에서의 역할을 체계적으로 이해한다. - 광고 기획·카피라이팅·비주얼·영상·음악 등 전 제작 단계에 AI 도구를 전략적으로 적용할 수 있다. - Heuristic Prompting을 통해 AI를 창의적 파트너로 활용하되 인간의 기획력과 감각을 중심에 두는 작업 방식을 체화한다. - AI 생성 콘텐츠의 윤리, 저작권, 공시 기준 등 실무적 이슈를 이해하고 책임감 있는 창작자로 성장한다. - 팀 프로젝트를 통해 통합 AI 광고캠페인을 완성하고 포트폴리오로 발전시킨다.', '{"활용한","있다","생성형","영상","강의와","피드백","제작","이해하고","기획서","이미지","영상화","활용하여","생성","광고","개요","도구","멀티모달","수정","기반","작성법"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('900398', '소비자행동원론', '사회과학대학', '사회과학대학', 0, 3, '전선', '최정화', '본 교과목은 마케터와 광고홍보 전문가들이 소비자를 이해하는데 있어서 필요한 개념과 이론을 가르치는데 목적이 있다. 이 수업을 통해서 학생들은 현대 소비자의 욕구, 동기, 의사결정 과정, 그리고 사회 문화적 요인과 소비자 행동과의 관계를 탐색할 것 이다. 비자 행동과 심리에 관한 기본 개념과 이론을 학습하고 이를 마케팅과 광고홍보 전략 도출에 활용할 수 있도록 한다', '{"소비자","행동의","요인","내적","환경적","동기","의사결정","광고홍보","개념과","이론을","관한","인지","자아","성격","태도","중간고사","주차","구성요소","구매","사용"}') ON CONFLICT DO NOTHING;
INSERT INTO courses (id, course_name, department, dept_id, grade_level, credits, category, professor, description_full, keywords) VALUES ('905004', '디지털미디어플래닝', '사회과학대학', '사회과학대학', 0, 3, '전선', '오종현', '이 수업은 광고대행사의 핵심 직무 중 하나인 디지털 미디어 플래너의 역할과 책임을 이해하고, 전문 역량의 기초를 체계적으로 다지 는 것을 목표로 합니다. 디지털 미디어 환경의 트렌드와 주요 플랫폼(구글, 유튜브, 네이버, 카카오 등)의 특성을 학습하며, 이를 바탕으로 전략적 미디어 플래 닝 방법론을 익힙니다. 또한 프로젝트 요구사항 분석부터 데이터 기반 타겟팅, 예산 할당 등 실무에서 요구되는 기술을 실습을 통해 강화합니다. 수업은 최신 캠페인 사례 연구와 트렌드 세미나를 포함하여 학생들이 변화하는 디지털 광고 환경을 효과적으로 이해하고, 실제 문제 해결 능력을 키우는 데 초점을 맞춥니다. 이를 통해 학생들은 이론적 지식과 실질적 역량을 겸비한 미디어 플래너로서의 기본기를 갖 추게 됩니다. 지식 1. 유튜브를 중심으로 디지털 미디어 플랫폼의 특성과 광고 전략을 이해한다. 2. 브랜딩 캠페인의 기본 개념과 효과적인 미디어 플래닝 접근 방식을 학습한다. 기술 1. 코리안클릭, 리서치애드, KADD 등의 데이터 분석 도구를 활용해 타겟팅 및 성과 평가를 수행하는 역량을 습득한다. 2. 광고 목표와 타겟에 맞는 미디어 믹스를 설계하고, 최적의 캠페인 전략을 수립하는 실무 능력을 기른다. 태도 1. 실무 중심의 사례와 프로젝트 경험을 통해 문제 해결 능력과 주도적인 자세를 배양한다. 2. 디지털 미디어 환경의 변화에 민감하게 반응하며 지속적으로 학습하고 성장하려는 태도를 함양한다.', '{"미디어","디지털","프로젝트","플래닝","광고","타겟팅","활용한","프로세스","유튜브","깅의","주차별","공지","수업은","이해하고","환경의","이를","데이터","캠페인","능력을","역량을"}') ON CONFLICT DO NOTHING;

