INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53735672', '[정규직] 서비스의 성장을 설계할백엔드 개발자', '(주)블루더스', '{"Jira","Notion"}', '[정규직] 서비스의 성장을 설계할 백엔드 개발자모집분야백엔드 개발 및 프로젝트 운영(1명)📋 업종IT 솔루션 및 AI 기반 비즈니스 플랫폼 개발📋 직소프트웨어 엔지니어 / 테크니컬 프로젝트 매니저 (Technical PM Track)📋 주요업무Core Development: 확장성을 고려한 백엔드 시스템 설계 및 API 개발Product Ownership: 기획 단계 참여를 통한 기술적 실현 가능성 검토 및 로직 제안Project Management: 효율적인 협업을 위한 프로젝트 일정 관리 및 기술 문서화Service Improvement: 사용자 피드백 기반의 서비스 개선 프로젝트 발굴 및 실행📋 이런 분과 함께하고 싶습니다백엔드 개발에 대한 탄탄한 기초 지식을 갖추신 분내 코드가 비즈니스에 어떤 영향을 미치는지 궁금해하며, 능동적으로 질문하는 분개발 효율을 높이기 위한 문서화 및 커뮤니케이션 도구 활용에 거부감이 없는 분정해진 명세서대로 코드를 짜는 것에 그치지 않고, ''왜 이 기능이 필요한가''를 함께 고민하며 프로젝트의 시작과 끝을 책임져보고 싶은 야심 찬 신입 분들의 지원을 기다립니다.📋 자격요건• 신입 / 경력 1년 이상 ~ 3년 이하• 대학교졸업(4년)이상📋 이런 경험이 있다면 더 좋습니다!1. 프로젝트 리딩 및 협업 경험학업 및 개인 프로젝트에서 팀장(Leader) 또는 PM 역할을 맡아 프로젝트를 완수한 경험이 있는 분서로 다른 의견을 조율하여 결론을 도출하고, 이를 바탕으로 실행 계획을 세워본 경험이 있는 분Slack, Jira, Notion 등 협업 툴을 활용해 업무를 체계적으로 기록하고 공유하는 것을 즐기시는 분2. 서비스 기획 및 비즈니스 마인드개발 이전에 "이 서비스가 왜 필요한가"에 대해 고민하고, 기획안이나 요구사항 정의서를 직접 작성해 본 경험이 있는 분기술적 한계에 부딪혔을 때 포기하기보다 비즈니스적으로 대안을 찾아 제안해 본 경험이 있는 분본인이 만든 결과물에 대해 사용자 피드백을 받고 이를 반영하여 지속적으로 개선(Update) 해 본 경험이 있는 분3. 기술적 커뮤니케이션 능력자신의 기술적 의사결정 과정을 논리적으로 설명하고, 비개발 직군도 이해할 수 있도록 비즈니스 언어로 변환하여 소통할 수 있는 분코드 리뷰나 문서화를 통해 동료의 성장에 기여하고 업무 효율을 높이는 데 보람을 느끼시는 분4. 기타새로운 기술 트렌드나 비즈니스 모델에 호기심이 많고, 이를 실제 업무나 프로젝트에 적용해 보려는 시도를 즐기시는 분창업 경험이 있거나 초기 스타트업의 성장 과정을 함께 고민해 본 경험이 있는 분🏠 근무조건 • 고용형태 : 정규직 • 급여 : 면접 후 결정 • 근무지 : 서울 마포구 토정로 265-7 공간찬넬빌딩 3층 2호 • 근무일수/시간 : 🎁 복지 및 혜택🚀 채용절차 접수기간 : 2026-04-27 12시 ~ 2026-05-15 24시 제출서류 : 사람인 온라인 이력서 접수방법 : 사람인 입사지원 전형절차 : 서류전형 → 1차면접 → 최종합격🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.


    var i;

    var showQuickLogin = function () {
        if (window.top.Saramin && window.top.Saramin.showQuickLogin) {
            window.top.Saramin.showQuickLogin();
        }
    };

    window.onload = function () {
        var frames = document.getElementsByTagName("iframe");
        for (i = 0; i < frames.length; i++) {
            if(frames[i].src.indexOf(''?'') > -1) {
                frames[i].src = frames[i].src.replace(''autoplay=1'', ''autoplay=0'');
                frames[i].src += ''&wmode=transparent'';
            } else {
                frames[i].src += ''?wmode=transparent'';
            }

        }
        var embedes = document.getElementsByTagName("embed");
        for (i = 0; i < embedes.length; i++) {
            embedes[i].wmode = ''transparent'';
        }

        var aList = document.querySelectorAll(''a,area'');
        var aLength = aList.length;

        for (i = 0; i < aLength; i++) {
            var aLink = aList[i];
            var href = aLink.getAttribute(''href'') || '''';

            if (href.indexOf(''mailto:'') !== -1 || href.indexOf(''tel:'') !== -1 || href.match(''#(.*)'') !== null) {
                continue;
            }

            aLink.setAttribute(''target'', ''_blank'');
        }

        var aTagList = document.querySelectorAll(''a,area'');
        for (i = 0; i < aTagList.length; i++ ){
            aTagList[i].addEventListener(''mousedown'', function (e) {
                var item = e.currentTarget;
                var href = item.getAttribute(''href'') || '''';

                Saramin.checkUpdateHomepage(href);
            });
        }

        if (window.top.JobsView) {
            window.top.JobsView.revealMail(document.getElementsByClassName("enc_mail"));
        } else if (window.top.revealMail) {
            window.top.revealMail(document.getElementsByClassName("enc_mail"))
        }
    };

    var Saramin = {};
    Saramin.checkUpdateHomepage = function(href) {
        var isFile = false,
            urlLastSpiceByDot = href.split(''.'').pop().toLowerCase(),
            fileExtWord = [''hwp'', ''doc'', ''docx'', ''ppt'', ''pptx'', ''pdf'', ''xls'', ''xlsx'', ''rtf'', ''gul''],
            fileExtCompress = [''zip'', ''alz'', ''rar'', ''lzh'', ''arj'', ''egg'', ''tar'', ''sit''],
            fileExtImageFlash = [''jpg'', ''gif'', ''png'', ''psd'', ''fla'', ''ai'', ''jpe'', ''jpeg'', ''tif'', ''tiff'', ''pcx'', ''swf''],
            fileExt;

        fileExt = fileExtWord.concat(fileExtCompress).concat(fileExtImageFlash);
        isFile = (fileExt.indexOf(urlLastSpiceByDot) !== -1);

        if (href != '''' && isFile === false && href.indexOf(''mailto:'') === -1
            && href.indexOf(''pds.saramin.co.kr'') === -1 && href.indexOf(''uf.daum.net'') === -1 && href.indexOf(''drive.google.com'') === -1
        ) {
            try {
                Saramin.updateHomepageLink(''53735672'', ''homepage'');
            } catch (e) {}
        }
    };
    Saramin.updateHomepageLink = function(rec_idx, form_gb) {
        var i = new Image();
        i.src    = "/zf_user/track-apply-form/update-homepage-apply-form-cnt-ajax?rec_idx=" + rec_idx + "&form_gb=" + form_gb + ''&'' + "t_category=&t_content=&t_ref=&t_ref_content=";
        i.onload = function () {};
    };


    /*
    isImgLoad = function (img) {
        if (!img.complete) {
            return false;
        }

        if (img.naturalWidth === 0) {
            return false;
        }

        return true;
    };

    setTimeout(function () {
        var tagList = document.querySelector(".user_content").querySelectorAll(''img'');
        var tagListLength = tagList.length;

        for (var i = 0; i < tagListLength; i++) {
            var item = tagList[i];
            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', '백엔드 개발자', 3) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53790432', '주식회사 루덴스에서백엔드 개발자/서버관리자를 찾고 있어요', '(주)루덴스', '{"Docker","MySQL","PostgreSQL","AWS","CI/CD","JAVA","C#"}', '백엔드 개발자 / 서버관리자📋 주요업무• 유저 생성 콘텐츠(UGC)의 호스팅, 관리, 배포 및 검색 역할을 하는 서버를 만들고 관리해요.• 유저 정보 및 유저가 만든 창작물, 마켓플레이스에 대한 백엔드가 필요해요.📋 자격요건• 경력 무관 (신입 지원 가능)• 학력무관• Docker • MySQL/PostgreSQL• AWS• CI/CD📋 우대사항• JAVA• C#• Unity🏠 근무조건 • 고용형태 : 계약직 3개월(정규직 전환 가능) • 급여 : 월급 220만원 • 근무지 : 서울 마포구 서강대길 22, 서강창업나루, 재택근무 가능 • 근무일수/시간 : 🎁 복지 및 혜택• 업무에 필요한 장비를 지원해드려요• 자유로운 분위기에서 협업할 수 있어요• 성장에 도움 되는 학습을 지원해드려요• 유연하게 일정 조율하며 일할 수 있어요• 안정적인 개발·운영 환경을 제공해요🚀 채용절차 접수기간 : 2026-05-04 14시 ~ 2026-05-15 24시 제출서류 : 사람인 온라인 이력서, • 사람인 온라인 이력서 • 자기 소개서• 포트폴리오 접수방법 : 사람인 입사지원 전형절차 : 서류전형 → 과제평가 → 면접평가 → 최종합격🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.


