            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', 'UI 개발자', 5) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53800708', '산업 자동화 UI/데이터 통합 신입 개발자 모집', '에스엔아이티씨(주)', '{"javascript","Python","SQL"}', '산업 자동화 UI/데이터 통합 신입 개발자 모집에스엔아이티씨(주)는 완성도 높은 엔지니어링 통합 역량과 시스템 설계 및 컨설팅 전문성을 기반으로 4차 산업혁명에 대응하는 Smart Factory, Datacenter, 식품 및 음료 산업 등 다양한 분야에서 기술 기반의 자동화 솔루션과 전문 서비스를 제공하는 엔지니어링 회사입니다.당사는 축적된 산업 경험과 전문 지식을 바탕으로 고객 맞춤형 시스템을 구축하고 있으며 이러한 현장을 함께 경험하며 성장할 신입 개발자를 모집합니다.산업 자동화 UI/데이터 통합 개발자담당 업무- 산업 설비 및 환경 데이터를 시각화하는 모니터링/제어 화면 개발- OPC UA / MQTT / Modbus 등 통신 기반 시스템 연동- 사용자 인터페이스 동작을 위한 스크립트 로직 구현 (javascript, Python 등)- SQL 기반 DB 연동을 통해 주요 데이터를 통합 구성 및 처리- 고객 요구사항 분석 및 UI/UX 설계 반영- 개발 완료 후 현장 시운전 및 시스템 테스트 지원자격 요건주요업무담당업무ㆍ     - 학력 : 전문학사 이상     - SCADA 또는 HMI 솔루션 개발 경험     - javascript, Python 등 스크립트 언어 중 하나 이상 사용 가능     - SQL 기반 데이터베이스 처리 경험     - 산업 자동화 및 통신 프로토콜 (OPC UA, Modbus, MQTT 등)에 대한 학습 의지우대사항우대 사항- 컴퓨터공학, 정보통신, 자동화 관련 전공자- 프로그래밍 전문 교육기관 수료자- 관련 캡스톤, 공모전, 학부 프로젝트 수행 경험- 실시간 데이터 처리 및 설비 시각화에 대한 관심 보유자- 전기 및 네트워크 등 관련 기초 기술 지식 보유자근무 조건     - 고용 형태 : 정규직 (수습기간 3개월)     - 근무지 : 본사 및 프로젝트 현장 (출장 포함)     - 근무시간 주 5일 ( 08:30 ~ 17:30 )     - 급여 : 면접 후 협의     - 근무지역 : (14488) 경기 부천시 원미구 길주로411번길 20, 춘의 디아크원 - 서울 7호선 춘의 에서 200m 이내함께 성장할 여러분을 기다립니다에스엔아이티씨(주)는 신입 개발자의 성장 경로와 기술 습득을 지원하는 체계적인 교육 환경을 제공합니다. 단순한 개발을 넘어 현장 중심의 실전 경험을 통해 산업 자동화 전문가로 함께 성장해 나가실 분들의 많은 지원 바랍니다.전형절차 서류전형 1차면접 최종합격접수기간 및 방법ㆍ접수기간:2026년 5월 6일 (수) 09시 ~ 2026년 7월 5일 (일) 24시ㆍ접수방법:사람인 입사지원ㆍ이력서양식:사람인 온라인 이력서ㆍ제출서류:유의사항ㆍ학력, 성별, 연령을 보지않는 블라인드 채용입니다. ㆍ입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.ㆍ모집분야별로 마감일이 상이할 수 있으니 유의하시길 바랍니다.\


