        }

        if (img.naturalWidth === 0) {
            return false;
        }

        return true;
    };

    setTimeout(function () {
        var tagList = document.querySelector(".user_content").querySelectorAll(''img'');
        var tagListLength = tagList.length;

        for (var i = 0; i < tagListLength; i++) {
            var item = tagList[i];
            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', '프론트엔드 개발자', 6) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53533981', '[경력]프론트엔드 개발자모집', '(주)인피아드', '{"Vue","React","REST","HTML","CSS","JavaScript","ios","Git","TypeScript","Next.js","CI/CD","AWS","GCP"}', '[경력] 프론트엔드 개발자 모집 모집분야프론트엔트 개발자(1명)📋 주요업무- 웹 서비스 신규 기능 개발 및 기존 기능 개선- Vue.js 와 React 기반의 UI 컴포넌트 개발- REST API 연동- 상태 관리(Pinia / Vuex / zustand 등) 및 전역 스토어 설계- 반응형 UI, 사용자 경험(UX) 개선- 성능 최적화 및 웹 접근성 개선- 디자이너, 백엔드 개발자, PM과 협업하여 제품 고도화📋 자격요건• 경력 2년 이상• 대학졸업(2,3년)이상- 웹 프론트엔드 개발 경력 3년 이상- HTML/CSS/JavaScript(ES6+)에 대한 이해- Vue.js 실무 경험- SPA 구조와 컴포넌트 기반 아키텍처 이해- 비동기 처리(fetch/axios) 및 API 연동 경험- Git을 활용한 협업 경험- 브라우저 렌더링 원리, 스타일링 기본(Responsive Web) 이해📋 우대사항- TypeScript 사용 경험- Vue 3 + Composition API 또는 React + Hooks 실무 경험- Next.js / Nuxt.js 경험- Vite 설정 경험- 디자인 시스템 구축 경험- Three.js / WebGL / Canvas 경험- 테스트 코드(Jest, Vitest 등) 작성 경험- 클라우드 환경(CI/CD, AWS, GCP 등) 이해- B2C 서비스 개발 경험 🏠 근무조건• 고용형태 : 정규직 • 급여 : 면접 후 결정 • 근무지 : 경기 안양시 동안구 관양동 792-2 평촌스마트베이 A-1805• 근무요일/시간 : 주 5일(월~금) 09:00~18:00 🎁 복지 및 혜택 🚀 채용절차접수기간 : 2026-04-04 15시 ~ 채용시제출서류 : 사람인 온라인 이력서접수방법 : 사람인 입사지원전형절차 : 서류전형 → 1차면접 → 최종합격🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.


