INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53706697', '데이터 분석가(경력)', '(주)더블다운인터액티브', '{"css","SQL","Python"}', '/* 폰트 로드: Pretendard 전용 */
