    /* 레이아웃 및 줄 간격 최적화 */
    .job-posting { 
        font-family: ''Pretendard'', -apple-system, BlinkMacSystemFont, system-ui, Roboto, sans-serif; 
        color: #333; 
        line-height: 1.5; 
        max-width: 900px; 
        margin: 0 auto; 
    }
    .job-posting p { margin: 0 0 8px 0; }
    
    .section-title { 
