    .company-names span { 
        font-family: ''Pretendard'', sans-serif !important; 
        font-weight: 800; /* Gmarket 대체: 가장 두꺼운 굵기 */
        font-size: 28px; 
        line-height: 1.2;
    }
    .company-dug { color: #8dc63f; }
    .company-ddi { color: #002060; }
    
    .header-section h2 { 
        font-family: ''Pretendard'', sans-serif; 
        font-weight: 700; 
        font-size: 26px; 
        margin: 0; 
        line-height: 1.4; 
        color: #333; 
    }
    
    .benefit-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(340px, 1fr)); gap: 20px; }
    .benefit-card { 
        background: #ffffff; 
        border: 1px solid #e0e5e4; 
        border-radius: 20px; 
        padding: 25px; 
        box-shadow: 0 8px 25px rgba(0,0,0,0.02); 
        transition: all 0.3s ease; 
        position: relative; 
        overflow: hidden; 
    }
    .benefit-card::before { 
        content: ''''; 
        position: absolute; 
        top: 0; 
        left: 0; 
        width: 100%; 
        height: 4px; 
        background: #008272; 
        transform: scaleX(0); 
        transition: transform 0.3s ease; 
    }
    .benefit-card:hover { transform: translateY(-8px); box-shadow: 0 15px 35px rgba(0, 130, 114, 0.08); border-color: #cce6e3; }
    .benefit-card:hover::before { transform: scaleX(1); }
    
    .card-icon { font-size: 36px; margin-bottom: 12px; display: inline-block; }
    .card-title { font-size: 19px; font-weight: 800; margin-bottom: 15px; color: #111; }
    .card-list { list-style: none; padding: 0; margin: 0; }
    .card-list li { position: relative; padding-left: 18px; margin-bottom: 8px; font-size: 15px; color: #555; }
    .card-list li::before { 
        content: ''''; 
        position: absolute; 
        left: 0; 
        top: 8px; 
        width: 5px; 
        height: 5px; 
        border-radius: 50%; 
        background-color: #008272; 
    }
    
    .highlight { font-weight: 700; color: #005a4f; box-shadow: inset 0 -8px 0 #d9efec; }
    .content-img { width: 100%; max-width: 840px; display: block; margin: 0 auto 10px auto; border-radius: 8px; }
    .qa-section { text-align: center; margin-top: 20px; }

    @media (max-width: 768px) {
        .benefit-grid { grid-template-columns: 1fr; }
