    setTimeout(function () {
        var tagList = document.querySelector(".user_content").querySelectorAll(''img'');
        var tagListLength = tagList.length;

        for (var i = 0; i < tagListLength; i++) {
            var item = tagList[i];
            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', '보안 엔지니어', 12) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53762661', '(주)연무기술정보보안 엔지니어모집(경력 무관)', '(주)연무기술', '{"네트워크","보안관제","ISMS"}', '(주)연무기술 정보보안 엔지니어 모집(경력 무관)  모집분야정보보안 엔지니어 신입 / 경력직📋 주요업무• 공공기관(정부부처/지자체/연구기관/교육기관) • 정보보안 유지보수 및 기술지원• 보안장비 납품설치 구축 유지보수 정기점검 장애처리📋 자격요건• 신입 / 경력 (연수 무관)• 학력무관, 졸업 예정자 지원가능• 신입 / 경력직 • 학력무관, 졸업예정자 가능• 보안관련 자격증 소지자 우대• 팀워크와 소통 능력 중요• 문제 해결에 적극적인 자세 필요• 공공기관 출입에 결격사유가 없어야 합니다 (신원조회)📋 우대사항• 전공: 전기/전자공학, 컴퓨터/시스템공학• 보유역량: 해당직무 인턴경력, 운전가능자, 해당직무 알바경험, 해당직무 근무경험• 자격증: 정보보안기사, 정보처리기사🏠 근무조건• 고용형태 : 정규직(수습 2개월)  • 급여 : 면접 후 결정• 근무지 : 대전 유성구 대덕대로590번길 11-14 (주)연무기술  🎁 복지 및 혜택• 급여제도 : 장기근속수당, 4대 보험, 퇴직금• 조직 문화 : 자유로운 연차사용• 선물 : 생일선물/파티, 명절선물/귀향비• 리프레시 : 반차, 남성출산휴가, 육아휴직, 근로자의날 휴무, 공휴일 휴무, 연차, 경조휴가제, 포상휴가• 교육/생활 : 교육비 지원, 사우회(경조사회), 자격증취득지원• 출퇴근 : 기숙사 운영, 주차장제공🚀 채용절차접수기간 : 2026-04-29 16시 ~ 2026-05-29 24시제출서류 : 사람인 온라인 이력서접수방법 : 사람인 입사지원전형절차 : 서류전형 → 1차면접 → 최종합격🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.


    var i;

    var showQuickLogin = function () {
