    setTimeout(function () {
        var tagList = document.querySelector(".user_content").querySelectorAll(''img'');
        var tagListLength = tagList.length;

        for (var i = 0; i < tagListLength; i++) {
            var item = tagList[i];
            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', '정보보안 엔지니어', 10) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53619291', 'DevOps 엔지니어/정보 보안 운영 관리 엔지니어', '(주)이스트게임즈', '{"Linux","CI/CD","Python","Terraform","Docker","Kubernetes","Git","Jenkins","SIEM","AWS","PHP","C#","CISSP","ELK"}', 'DevOps 엔지니어/정보 보안 엔지니어 모집분야이스트게임즈를 소개합니다이스트게임즈는 2005년 카발 온라인을 시작으로 카발 모바일, 고양이 다방 등 국내 외에 다양한 게임을 서비스해온 게임 제작 전문 기업입니다. 오랜 경험을 바탕으로 한 탄탄한 개발력과 서비스 노하우로 지금 이 순간에도 다양한 신작 개발과 서비스 연구를 계속해 나가고 있습니다. "게임의 본질은 재미와 즐거움이다." 이스트게임즈는 게임을 통해 더 많은 사람들이 `즐거움`과 `재미`를 찾는 세상을 꿈꿉니다. 세상에 없는 새로운 게임으로 더 큰 즐거움을 나누기 위한 이스트게임즈의 도전은 계속되며, 이 도전에 함께할 인재를 모집합니다. [급여 정보]이스트게임즈는 게임 업계 최고 대우를 지향합니다.[DevOps 엔지니어]- 신입 급여 (대졸 기준): 학력/실력에 따라 4,776 ~ 5,616만원 (명절상여 포함) + 스톡옵션 1 ~ 5만주- 경력 급여: 경력에 따라 5,184만원~ (명절상여 포함) + 스톡옵션 1 ~ 10만주[정보 보안 운영 관리 엔지니어]- 신입 급여 (대졸 기준): 학력/실력에 따라 4,536 ~ 5,616만원 (명절상여 포함) + 스톡옵션 1 ~ 5만주- 경력 급여: 경력에 따라 4,944만원~ (명절상여 포함) + 스톡옵션 1 ~ 10만주📋 Devops 엔지니어[담당업무]- 클라우드 및 온프레미스 기반의 게임 서비스 환경 구축 및 운영 (네트워크, 시스템, DB)- Linux/Windows 기반 시스템의 안정적인 운영 및 성능 관리- 성능 지표 분석을 통한 시스템 및 애플리케이션 최적화- CI/CD 파이프라인 구축 및 관리, 자동화 시스템 설계 및 구현- 클라우드와 온프레미스 간 하이브리드 환경 통합 및 관리- 보안 중심 설계 및 운영을 통한 네트워크 및 시스템 보호 [자격요건]- 클라우드 서비스 및 온프레미스 환경에 대한 깊은 이해와 실무 경험- 서버 OS(Linux, Windows)에 대한 높은 관심과 상세한 지식 보유- 네트워크 관련 깊은 이해와 경험 (TCP/IP, L2~L7)- 필수 애플리케이션(Web, WAS, DB)에 대한 이해- 스크립트 및 자동화 프로그래밍 지식 (Bash, Python 등)- 멀티 클라우드 환경 관리 및 클라우드 네이티브 기술 활용 경험[우대조건]- 게임 서비스 인프라 구축/운영/최적화 경험- 클라우드 및 온프레미스 통합 프로젝트 경험- IaC(Infrastructure as Code) 및 컨테이너화 도구 사용 경험 (Terraform, Ansible, Docker, Kubernetes 등)- 오픈소스 및 클라우드 기반 프로젝트 경험- 인프라 및 서비스 자동화를 위한 도구 경험 (GitLab CI/CD, Jenkins 등)- 네트워크 및 시스템 보안 구성과 SIEM, IDS/IPS 사용 경험- 서버 및 네트워크 관련 자격증 (AWS Certified Solutions Architect, RHCE, CCNA등) 보유[이런 분을 기대합니다]- 최신 기술 트렌드에 관심이 많고, 이를 업무에 적극적으로 반영하는 자세를 가지신 분- 문제 해결에 대한 창의적 접근을 즐기며, 효율적인 자동화와 최적화에 관심이 많으신 분- 팀워크와 협업을 중시하며, 다양한 팀과의 원활한 소통이 가능하신 분- 함께 성장할 유능한 DevOps 엔지니어를 기다립니다. 많은 지원 바랍니다!📋 정보 보안 운영 관리 엔지니어[담당업무]- 보안 관제 운영(각종 보안 이벤트 로그 분석 활동 및 대응)- 침해사고 대응 및 예방 활동(웹 취약점 진단, 각종 해킹 시도 분석)- 각종 보안 시스템 구축 및 운영 관리(IPS, 웹 방화벽)- 업무 자동화 툴 개발(Python , Bash, PHP, C# 등) [자격요건]- 정보 시스템에 대한 기본적 이해도가 높은 분(Windows, Linux, DB, Network등)- 보안 관제 및 침해 사고 대응 및 분석이 가능한 분- 보안 시스템(IPS, 웹방화벽 등) 운영 경험이 있는 분- 침투 테스트 경험이 있는 분- 웹 취약점 진단이 가능한 분[우대조건]- 정보보안기사 자격증을 보유한 분- CISSP 자격증을 보유한 분- 오픈소스를 활용한 보안 시스템 구축 경험이 있는 분- 통합보안로그 관리 시스템 운영 경험이 있는 분(ELK 등)🏠 근무조건• 고용형태 : 정규직(수습 3개월) • 급여 - 신입 급여 (대졸 기준): 학력/실력에 따라 4,776 ~ 5,616만원 (명절상여 포함) + 스톡옵션 1 ~ 5만주 - 경력 급여: 경력에 따라 5,184만원~ (명절상여 포함) + 스톡옵션 1 ~ 10만주• 근무지 : 서울 서초구 서초동 1464-30 이스트빌딩 5층 🎁 복지 및 혜택이스트게임즈의 생활을 공개합니다즐거운 사람이 재미있는 게임을 만들 수 있다는 생각으로 임직원의 Work & Life 밸런스를 위해 노력합니다. [Fun, In and out]즐거운 게임은 즐겁게 일하는 사람들 손에서 나옵니다.이스트게임즈는 즐겁게 일할 수 있는 환경을 제공하기 위해 노력합니다 사내 카페테리아 (편안한 휴식 시간을 위한 우리만의 전용 공간)- 회사 근처 유명 카페 입점- 제조 음료 할인 및 베이커리 판매- 층별 스낵바 운영축하 이벤트 (즐거운 날, 더 즐거울 수 있도록!)- 졸업, 수습 종료 축하 이벤트- 자녀 초등학교 입학 축하 이벤트- 장기근속 축하 리프레시 휴가 지원 [Life, In and out]우리는 회사의 구성원이기 전에 한 가족의 구성원입니다.이스트게임즈는 보다 풍요롭고 행복한 회사 생활을 위해 가족과의 행복한 삶을 지원합니다. 가족 친화 제도 (행복한 가정, 행복한 회사)- 출산 축하 선물, 육아 수당- 소노, 한화 리조트 지원- 제주캠퍼스 게스트룸 지원- 경조사 휴가, 경조금 지원건강 관리 지원 (그 누구도 아프지 않도록)- 건강검진 및 휴가 지원- 병가 및 단체상해보험, 실손의료보험주택 자금 지원 제도 (안정된 주거환경에서 생활할 수 있도록)- 월세 지원- 전세대출이자 지원- 주택담보대출이자 지원- 이사비 지원 [Freedom, with Responsibility]오늘도 열심히 일한 당신! 자유롭게 게임하고, 자유롭게 휴가쓰고, 자유롭게 퇴근하세요. 자기 주도적인 업무 환경 (업무에 몰입할 수 있도록!)- 시차출퇴근제- 원격근무 지원- 시간 연차 제도(2시간 단위)- 기여에 따른 차등 보상제게임 캐시 지원 (게임 개발을 위한 플레이 경험은 필수!)- 자사 게임 캐시 지원자기계발 지원 (성장하고 싶은 당신에게)- 어학교육비, 정규교육과정 학비 지원- 외부 교육 및 세미나 지원- 이스트책방 운영, 도서 지원- 금융상품 가입 지원(과학기술인공제회 협약) 앞으로 이스트게임즈의 인사 및 복지제도는 계속해서 발전할 예정입니다.🚀 채용절차접수기간 : 2026-04-14 10시 ~ 2026-06-13 24시제출서류 : 자유양식 이력서접수방법 : 홈페이지 지원전형절차 : 서류전형 → 필기시험&실무면접 → 최종면접 → 최종합격 🛎️ 유의사항- 자유양식의 이력서(필수), 포트폴리오를 첨부하여 제출해주세요.- 입사지원 서류에 허위기재 사실이 발견될 경우, 전형 진행과 입사가 취소될 수 있습니다.- 해외여행 결격 사유가 없는 분 (남자의 경우 병역필 또는 면제자)- 모든 모집 부문에서 국가보훈대상자 및 장애인은 관련 법령에 의거하여 가산점을 부여하고 있습니다.- 입사지원자께서는 전/현직 직장의 영업 비밀을 침해하는 일이 없도록 각별히 유의하시기 바랍니다.


    var i;

    var showQuickLogin = function () {
        if (window.top.Saramin && window.top.Saramin.showQuickLogin) {
            window.top.Saramin.showQuickLogin();
        }
    };

    window.onload = function () {
        var frames = document.getElementsByTagName("iframe");
        for (i = 0; i < frames.length; i++) {
            if(frames[i].src.indexOf(''?'') > -1) {
                frames[i].src = frames[i].src.replace(''autoplay=1'', ''autoplay=0'');
                frames[i].src += ''&wmode=transparent'';
            } else {
                frames[i].src += ''?wmode=transparent'';
            }

        }
        var embedes = document.getElementsByTagName("embed");
        for (i = 0; i < embedes.length; i++) {
            embedes[i].wmode = ''transparent'';
        }

        var aList = document.querySelectorAll(''a,area'');
        var aLength = aList.length;

        for (i = 0; i < aLength; i++) {
            var aLink = aList[i];
            var href = aLink.getAttribute(''href'') || '''';

            if (href.indexOf(''mailto:'') !== -1 || href.indexOf(''tel:'') !== -1 || href.match(''#(.*)'') !== null) {
                continue;
            }

            aLink.setAttribute(''target'', ''_blank'');
        }

        var aTagList = document.querySelectorAll(''a,area'');
        for (i = 0; i < aTagList.length; i++ ){
            aTagList[i].addEventListener(''mousedown'', function (e) {
                var item = e.currentTarget;
                var href = item.getAttribute(''href'') || '''';

                Saramin.checkUpdateHomepage(href);
            });
        }

        if (window.top.JobsView) {
            window.top.JobsView.revealMail(document.getElementsByClassName("enc_mail"));
        } else if (window.top.revealMail) {
            window.top.revealMail(document.getElementsByClassName("enc_mail"))
        }
    };

    var Saramin = {};
    Saramin.checkUpdateHomepage = function(href) {
        var isFile = false,
            urlLastSpiceByDot = href.split(''.'').pop().toLowerCase(),
            fileExtWord = [''hwp'', ''doc'', ''docx'', ''ppt'', ''pptx'', ''pdf'', ''xls'', ''xlsx'', ''rtf'', ''gul''],
            fileExtCompress = [''zip'', ''alz'', ''rar'', ''lzh'', ''arj'', ''egg'', ''tar'', ''sit''],
            fileExtImageFlash = [''jpg'', ''gif'', ''png'', ''psd'', ''fla'', ''ai'', ''jpe'', ''jpeg'', ''tif'', ''tiff'', ''pcx'', ''swf''],
            fileExt;

        fileExt = fileExtWord.concat(fileExtCompress).concat(fileExtImageFlash);
        isFile = (fileExt.indexOf(urlLastSpiceByDot) !== -1);

        if (href != '''' && isFile === false && href.indexOf(''mailto:'') === -1
            && href.indexOf(''pds.saramin.co.kr'') === -1 && href.indexOf(''uf.daum.net'') === -1 && href.indexOf(''drive.google.com'') === -1
        ) {
            try {
                Saramin.updateHomepageLink(''53619291'', ''homepage'');
            } catch (e) {}
        }
    };
    Saramin.updateHomepageLink = function(rec_idx, form_gb) {
        var i = new Image();
        i.src    = "/zf_user/track-apply-form/update-homepage-apply-form-cnt-ajax?rec_idx=" + rec_idx + "&form_gb=" + form_gb + ''&'' + "t_category=&t_content=&t_ref=&t_ref_content=";
        i.onload = function () {};
    };


    /*
    isImgLoad = function (img) {
        if (!img.complete) {
            return false;
        }

        if (img.naturalWidth === 0) {
            return false;
        }

        return true;
    };

    setTimeout(function () {
        var tagList = document.querySelector(".user_content").querySelectorAll(''img'');
        var tagListLength = tagList.length;

        for (var i = 0; i < tagListLength; i++) {
            var item = tagList[i];
            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', '정보보안 엔지니어', 10) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53396763', '[신입/경력] 정보보안 컨설턴트를 모집합니다.', '(주)엘앤제이테크', '{"ISMS"}', '[신입/경력] 정보보안 컨설턴트를 모집합니다.모집분야정보보안컨설팅 취약점 진단/ 관리컨설티 (신입 / 경(0명)📋 주요업무• 공공/민간 정보보안 컨설팅• ISMS-P/ISO27001 등 인증 컨설팅 • 국가정보원, 개인정보보호위원회 등 보안감사 대비• 정보시스템 취약점 진단 등 • 컨설팅팀 부서 소속으로 함께할 예정이에요.📋 자격요건• 신입 / 경력 1년 이상• 대학졸업(2,3년)이상📋 우대사항• 자격증: 정보처리기사, 정보보안기사, 정보보안산업기사🏠 근무조건 • 고용형태 : 정규직(수습 3개월) • 급여 : 면접 후 결정 • 근무지 : 서울 구로구 디지털로 272 한신아이티타워 611호 • 근무일수/시간 : 주 5일(월~금) 09:00~18:00🎁 복지 및 혜택• 급여제도 : 우수사원포상, 퇴직금, 야근수당, 휴일(특근)수당, 4대 보험• 근무 환경 : 회의실🚀 채용절차 접수기간 : 2026-03-20 15시 ~ 상시 제출서류 : 사람인 온라인 이력서, 포트폴리오(필요 시). 접수방법 : 사람인 입사지원 전형절차 : 서류전형 → 면접 → 최종합격🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.


