INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53687426', '클라우드보안 컨설턴트채용 (GRC/금융/거버넌스)', '메가존클라우드(주)', '{"ISMS","CISSP"}', '클라우드그램 채용공고<font color="#0a9cbb"></font>
                        

                        
                 포지션명
                        
담당업무
                        
  자격요건 및 우대사항
                        

        
시니어 보안 컨설턴트(GRC)(경력 7년 ~ 20년)근무지: 메가존산학연센터
                        
· 컨설팅 프로젝트 리딩 및 팀원 역량 강화· 정보보호 관리체계(ISMS-P, ISO27001) 수립· 보안 수준 진단, 정책 수립 및 위험평가 수행· 컨설팅 결과 보고서 작성 및 고객 대응[자격요건]· 정보보호 또는 IT 컨설팅 경력 7년 이상· 인증 컨설팅 프로젝트 PM 수행 경험· 정보보호 관련 법규 및 규제 전문 지식 보유[우대사항]· ISMS-P/ISO27001 심사원 및 CISA/CISSP 보유· 컨설팅 펌 또는 대형 IT 서비스 기업 근무 경험· 퍼블릭 클라우드 보안 컨설팅 및 OT 보안 경험주니어 보안 컨설턴트(GRC)(신입 ~ 5년)근무지: 메가존산학연센터
                        
· ISMS-P, ISO 등 기술적 취약점 진단 수행· 온프레미스/클라우드 보안 점검 및 대응 수립· 취약점 진단 및 자동 위협분석 리포트 작성[자격요건]· 보고서 작성 능력 및 원활한 고객 커뮤니케이션· 퍼블릭 클라우드, 시스템 및 솔루션 보안 이해[우대사항]· 정보보안기사, CISA, CISSP 등 자격증 보유· 정보보안 컨설팅 경력 2년 이상· 모의해킹/침투 테스트 및 침해사고 대응 경험· 금융권 정보보호 또는 취약점 진단 경험금융 보안 컨설턴트(FSI)(신입 ~ 5년)근무지: 메가존산학연센터
                        
· 클라우드 및 정보보호 관련 보안성 심의 대응· 금융/핀테크 클라우드 이용 및 인허가 컨설팅· GenAI 안전 활용 및 퍼블릭 클라우드 보안성 검토[자격요건]· 보고서 작성 및 비즈니스 관점 소통 능력· 퍼블릭 클라우드 및 온프레미스 보안 이해[우대사항]· 금융회사 개인정보/정보보호 담당 경험· ISMS-P, ISO, PCI-DSS 인증심사 대응 경험· CISA, CISSP, ISMS-P 등 관련 자격증 보유※ 근무지 주소: 경기도 과천시 과천대로7길 74 (갈현동, 메가존산학연센터)- 고용형태 : 정규직 (정규직 전환을 위한 평가기간 3개월 계약직 운영) - 보훈대상자(취업보호대상자) 및 장애인은 관련 법령에 의거 우대됩니다.- 사업부서에 따라 상세 근무지는 다를 수 있습니다. 
                        

                        

                        



    var i;

    var showQuickLogin = function () {
        if (window.top.Saramin && window.top.Saramin.showQuickLogin) {
            window.top.Saramin.showQuickLogin();
        }
    };

    window.onload = function () {
        var frames = document.getElementsByTagName("iframe");
        for (i = 0; i < frames.length; i++) {
            if(frames[i].src.indexOf(''?'') > -1) {
                frames[i].src = frames[i].src.replace(''autoplay=1'', ''autoplay=0'');
                frames[i].src += ''&wmode=transparent'';
            } else {
                frames[i].src += ''?wmode=transparent'';
            }

        }
        var embedes = document.getElementsByTagName("embed");
        for (i = 0; i < embedes.length; i++) {
            embedes[i].wmode = ''transparent'';
        }

        var aList = document.querySelectorAll(''a,area'');
        var aLength = aList.length;

        for (i = 0; i < aLength; i++) {
            var aLink = aList[i];
            var href = aLink.getAttribute(''href'') || '''';

            if (href.indexOf(''mailto:'') !== -1 || href.indexOf(''tel:'') !== -1 || href.match(''#(.*)'') !== null) {
                continue;
            }

            aLink.setAttribute(''target'', ''_blank'');
        }

        var aTagList = document.querySelectorAll(''a,area'');
        for (i = 0; i < aTagList.length; i++ ){
            aTagList[i].addEventListener(''mousedown'', function (e) {
                var item = e.currentTarget;
                var href = item.getAttribute(''href'') || '''';

                Saramin.checkUpdateHomepage(href);
            });
        }

        if (window.top.JobsView) {
            window.top.JobsView.revealMail(document.getElementsByClassName("enc_mail"));
        } else if (window.top.revealMail) {
            window.top.revealMail(document.getElementsByClassName("enc_mail"))
        }
    };

    var Saramin = {};
    Saramin.checkUpdateHomepage = function(href) {
        var isFile = false,
            urlLastSpiceByDot = href.split(''.'').pop().toLowerCase(),
            fileExtWord = [''hwp'', ''doc'', ''docx'', ''ppt'', ''pptx'', ''pdf'', ''xls'', ''xlsx'', ''rtf'', ''gul''],
            fileExtCompress = [''zip'', ''alz'', ''rar'', ''lzh'', ''arj'', ''egg'', ''tar'', ''sit''],
            fileExtImageFlash = [''jpg'', ''gif'', ''png'', ''psd'', ''fla'', ''ai'', ''jpe'', ''jpeg'', ''tif'', ''tiff'', ''pcx'', ''swf''],
            fileExt;

        fileExt = fileExtWord.concat(fileExtCompress).concat(fileExtImageFlash);
        isFile = (fileExt.indexOf(urlLastSpiceByDot) !== -1);

        if (href != '''' && isFile === false && href.indexOf(''mailto:'') === -1
            && href.indexOf(''pds.saramin.co.kr'') === -1 && href.indexOf(''uf.daum.net'') === -1 && href.indexOf(''drive.google.com'') === -1
        ) {
            try {
                Saramin.updateHomepageLink(''53687426'', ''homepage'');
            } catch (e) {}
        }
    };
    Saramin.updateHomepageLink = function(rec_idx, form_gb) {
        var i = new Image();
        i.src    = "/zf_user/track-apply-form/update-homepage-apply-form-cnt-ajax?rec_idx=" + rec_idx + "&form_gb=" + form_gb + ''&'' + "t_category=&t_content=&t_ref=&t_ref_content=";
        i.onload = function () {};
    };


    /*
    isImgLoad = function (img) {
        if (!img.complete) {
            return false;
        }

        if (img.naturalWidth === 0) {
            return false;
        }

        return true;
    };

    setTimeout(function () {
        var tagList = document.querySelector(".user_content").querySelectorAll(''img'');
        var tagListLength = tagList.length;

        for (var i = 0; i < tagListLength; i++) {
            var item = tagList[i];
            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', '보안 컨설턴트', 11) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53697031', '[테라시큐어] 정보보안 컨설턴트경력 모집', '(주)테라시큐어', '{"ISMS"}', '[테라시큐어] 정보보안 컨설턴트 경력 모집모집분야정보보안 컨설팅 및 ISMS(ISMS-P) 인증 컨설팅(2명)📋 주요업무• 정보보호 및 관리체계  - 정보보호 및 개인정보보호 컨설팅  - 국내외 컴플라이언스 분석 및 가이드  - ISMS, ISMS-P, ISO270001등 보안 인증 심사 지원 📋 자격요건• 경력 5년 이상• 대학교졸업(4년)이상 📋 우대사항• 정보보안 컨설팅 프로젝트 PM 또는 수행 경험 있으신분• IT/정보보안 관련 자격을 보유하신 분  (정보보안기사, 정보처리기사, ISMS-P/ISO27001 심사원, CPPG 등)🏠 근무조건 • 고용형태 : 정규직(수습 3개월) • 급여 : 면접 후 결정 • 근무지 : 서울 영등포구 영신로 166 • 근무일수/시간 : 🎁 복지 및 혜택🚀 채용절차 접수기간 : 2026-04-22 12시 ~ 채용시 제출서류 : 사람인 온라인 이력서 접수방법 : 사람인 입사지원 전형절차 : 서류전형 → 1차면접 → 최종합격🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.


