INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53584638', 'Android 기반 Chromium 커스텀 브라우저 개발자 채용', '(주)와이즈플러스', '{"Android","Java","Kotlin","C++"}', 'Android 기반 Chromium 커스텀 브라우저 개발자 채용WisePlus와 함께 기술의 새 시대를 열어갈 동료를 찾습니다!모집부문 및 상세내용공통 자격요건ㆍ학력 : 대졸 이상 (4년)Chromium 커스텀 브라우저 개발자 0명주요업무담당업무ㆍ지원자격ㆍ경력 : 무관 (신입도 지원 가능)주요 업무 - Chromium 소스를 기반으로 한 Android 브라우저 앱 개발 - Android WebView 및 Native UI 커스터마이징 - 음성 명령 기반 키 이벤트 처리 - 미디어 세션, 데스크톱 모드 등 기능 확장 - 커스텀 URL 라우팅, User-Agent 설정 등 기능 구현우대 사항

 - Android 플랫폼에서의 앱 개발 경험 (Java 또는 Kotlin) - Chromium, WebView 또는 유사한 렌더링 엔진에 대한 이해 또는 사용 경험 - Widevine, DRM, MediaCodec 관련 경험 - Open source 프로젝트 기반 개발 경험 - Browser 개발 및 표준 프로토콜에 대한 경험 - Android에서 외부 하드웨어 또는 백그라운드 서비스와의 연동 경험 - 다양한 역할을 수행할 수 있는 유연성과 학습 능력 - C, C++, Java 중 최소 2개 이상의 언어를 사용한 개발 경험
            ㆍ기타 필수 사항
        우대사항근무조건ㆍ근무형태:정규직(수습기간)-3개월ㆍ근무일시:ㆍ근무지역:(13493) 경기 성남시 분당구 판교역로 230, B동 702호 - 신분당선 판교 에서 800m 이내전형절차 서류전형 1차면접 최종합격접수기간 및 방법ㆍ접수기간:상시채용ㆍ접수방법:사람인 입사지원ㆍ이력서양식:사람인 온라인 이력서ㆍ제출서류:유의사항ㆍ학력, 성별, 연령을 보지않는 블라인드 채용입니다. ㆍ입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.ㆍ모집분야별로 마감일이 상이할 수 있으니 유의하시길 바랍니다.


    var i;

    var showQuickLogin = function () {
        if (window.top.Saramin && window.top.Saramin.showQuickLogin) {
            window.top.Saramin.showQuickLogin();
        }
    };

    window.onload = function () {
        var frames = document.getElementsByTagName("iframe");
        for (i = 0; i < frames.length; i++) {
            if(frames[i].src.indexOf(''?'') > -1) {
                frames[i].src = frames[i].src.replace(''autoplay=1'', ''autoplay=0'');
                frames[i].src += ''&wmode=transparent'';
            } else {
                frames[i].src += ''?wmode=transparent'';
            }

        }
        var embedes = document.getElementsByTagName("embed");
        for (i = 0; i < embedes.length; i++) {
            embedes[i].wmode = ''transparent'';
        }

        var aList = document.querySelectorAll(''a,area'');
        var aLength = aList.length;

        for (i = 0; i < aLength; i++) {
            var aLink = aList[i];
            var href = aLink.getAttribute(''href'') || '''';

            if (href.indexOf(''mailto:'') !== -1 || href.indexOf(''tel:'') !== -1 || href.match(''#(.*)'') !== null) {
                continue;
            }

            aLink.setAttribute(''target'', ''_blank'');
        }

        var aTagList = document.querySelectorAll(''a,area'');
        for (i = 0; i < aTagList.length; i++ ){
            aTagList[i].addEventListener(''mousedown'', function (e) {
                var item = e.currentTarget;
                var href = item.getAttribute(''href'') || '''';

                Saramin.checkUpdateHomepage(href);
            });
        }

        if (window.top.JobsView) {
            window.top.JobsView.revealMail(document.getElementsByClassName("enc_mail"));
        } else if (window.top.revealMail) {
            window.top.revealMail(document.getElementsByClassName("enc_mail"))
        }
    };

    var Saramin = {};
    Saramin.checkUpdateHomepage = function(href) {
        var isFile = false,
            urlLastSpiceByDot = href.split(''.'').pop().toLowerCase(),
            fileExtWord = [''hwp'', ''doc'', ''docx'', ''ppt'', ''pptx'', ''pdf'', ''xls'', ''xlsx'', ''rtf'', ''gul''],
            fileExtCompress = [''zip'', ''alz'', ''rar'', ''lzh'', ''arj'', ''egg'', ''tar'', ''sit''],
            fileExtImageFlash = [''jpg'', ''gif'', ''png'', ''psd'', ''fla'', ''ai'', ''jpe'', ''jpeg'', ''tif'', ''tiff'', ''pcx'', ''swf''],
            fileExt;

        fileExt = fileExtWord.concat(fileExtCompress).concat(fileExtImageFlash);
        isFile = (fileExt.indexOf(urlLastSpiceByDot) !== -1);

        if (href != '''' && isFile === false && href.indexOf(''mailto:'') === -1
            && href.indexOf(''pds.saramin.co.kr'') === -1 && href.indexOf(''uf.daum.net'') === -1 && href.indexOf(''drive.google.com'') === -1
        ) {
            try {
                Saramin.updateHomepageLink(''53584638'', ''homepage'');
            } catch (e) {}
        }
    };
    Saramin.updateHomepageLink = function(rec_idx, form_gb) {
        var i = new Image();
        i.src    = "/zf_user/track-apply-form/update-homepage-apply-form-cnt-ajax?rec_idx=" + rec_idx + "&form_gb=" + form_gb + ''&'' + "t_category=&t_content=&t_ref=&t_ref_content=";
        i.onload = function () {};
    };


    /*
    isImgLoad = function (img) {
        if (!img.complete) {
            return false;
        }

        if (img.naturalWidth === 0) {
            return false;
        }

        return true;
    };

    setTimeout(function () {
        var tagList = document.querySelector(".user_content").querySelectorAll(''img'');
        var tagListLength = tagList.length;

        for (var i = 0; i < tagListLength; i++) {
            var item = tagList[i];
            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', 'Android 개발자', 13) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53504043', 'Android 안드로이드 커널/드라이버 개발자 채용', '(주)아스트노바', '{"Android","SoC","Linux","C++","JAVA","Git","Jenkins","Jira"}', 'Android 안드로이드 커널/드라이버 개발자 채용 모집분야Android 안드로이드 커널 개발자 구인(1명)📋 주요업무아스트노바 | Android 커널/드라이버 개발자 채용“AI 공간 사운드와 영상 처리의 경계를 무너뜨리는 기술 기업, 아스트노바”아스트노바는 글로벌 TV 제조사들과 함께 사운드 기술의 미래를 실제 디바이스 위에 구현하고 있습니다.이제 우리는 오디오와 비디오가 동시에 최적화된 SoC 환경을 만들기 위해AOSP 커널 및 HAL 계층부터 설계를 책임질 Android 커널 개발자를 찾습니다.  포지션: Android 커널 및 HAL 개발자 (Audio/Video SoC 최적화)근무형태: 정규직 / 계약직 협의 가능근무지: 서울 가산동 디지털 단지 본사 경력: AOSP 개발 경력 3년 이상  주요 업무Android 기반 Audio/Video HAL 개발 및 커스터마이징AudioFlinger, SurfaceFlinger 및 MediaCodec 레벨 디바이스 드라이버 최적화SoC 기반 TV 및 STB 디바이스의 커널 포팅 및 시스템 브링업Audio/Video Codec 및 DSP 인터페이스 연동 (ALSA / OMX 등)HDMI, SPDIF, I2S, eARC 등 디지털 오디오/비디오 인터페이스 설계내부 AI 오디오 엔진과 커널 연동 구조 설계 및 디버깅 자격 요건Android AOSP 기반 커널 구조 및 디바이스 드라이버 개발 경험 (2년 이상)Audio HAL 또는 Video HAL 구현 경험Linux 커널, AudioFlinger, Media HAL 구조에 대한 깊은 이해ALSA, ION, V4L2(Video4Linux) 등 멀티미디어 서브시스템 이해C/C++ / JAVA능숙, 커널 디버깅 및 로그 분석 가능자  우대 사항MediaTek, Amlogic, Qualcomm, Realtek 기반 SoC 커스터마이징 경험HDMI, SPDIF, MIPI CSI/DSI 등 영상 입출력 처리 경험Android TV/OTT 박스 제품 출하 경험Android NDK, HIDL, AIDL 등 시스템 계층 연동 경험GPU/NPU 연산 최적화 및 디바이스 트리 구성 경험Git, Jenkins, Jira 기반의 협업 환경 사용 경험  우리는 이런 분을 찾습니다단순한 "디바이스 bring-up"이 아니라, 미디어 처리의 본질을 다루고 싶은 사람영상과 음향의 하드웨어, OS, AI 알고리즘이 맞물리는 복합 구조에 도전하고 싶은 개발자문제를 구조적으로 해석하고, 직접 재설계하는 경험을 즐기는 엔지니어“이건 안드로이드 커널로 해결해야 합니다.”라고 말할 수 있는 확신과 책임을 가진 사람  아스트노바는AI 기반 실시간 사운드 분리, 트래킹, 몰입형 오디오 생성 시스템을 보유하고 있으며자체 AI SoC 및 Embedded Audio/Video 플랫폼을 준비중  지원 방법자유 양식 이력서 (포트폴리오, GitHub 등 포함 가능)제출처: astnova@astnova.com기술 면접은 온라인/오프라인 모두 가능하며, 실무 중심으로 진행됩니다 “AI 기반 오디오+비디오 기술의 가장 깊은 층을 다룰 사람을 찾습니다.”사운드와 영상이 결합된 미래를 커널부터 설계할 당신의 도전을 기다립니다. 📋 자격요건• 경력 3년 이상• 대학교졸업(4년)이상🏠 근무조건• 고용형태 : 계약직 12개월(정규직 전환 가능)• 급여 : 면접 후 결정 • 근무지 : 서울 금천구 디지털로10길 78, 910호 🎁 복지 및 혜택 🚀 채용절차접수기간 : 2026-04-01 17시 ~ 채용시제출서류 : 사람인 온라인 이력서접수방법 : 사람인 입사지원전형절차 : 서류전형 → 1차면접 → 2차면접 → 합격 및 채용🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.• 모집분야별로 마감일이 상이할 수 있으니 유의하시길 바랍니다.


