INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53486115', '[연구소] 의료장비 Android 기반 앱 개발자 모집합니다.(경력직)', '(주)새한엔케이앤디', '{"네트워크","Android","Kotlin","Java","iOS"}', '[이미지 기반 공고] [연구소] 의료장비 Android 기반 앱 개발자 모집합니다.(경력직)', 'Android 개발자', 13) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53773203', '[(주)아이젝스] 안드로이드&ios 개발자채용 공고', '(주)아이젝스', '{"ios","iOS","Android","Java","Kotlin","REST","Swift"}', '[(주)아이젝스] 안드로이드&ios 개발자 채용 공고 모집분야안드로이드 & iOS 개발자(2명)📋 주요업무모집분야• 안드로이드 OS 개발(Android MDM 및 기기 관리 솔루션)• ios OS 개발(ios MDM 및 기기 관리 솔루션) 담당업무• 신규 MDM 솔루션 서비스 개발 및 유지보수 -앱 등록 및 배포, 삭제 관리 -로그인 인증으로 계정 및 그룹 관리 -원격 공장초기화, 사용 중지, 화면 잠금 -원격 A/S 진행 내역 모니터링 시스템 구축 • 모니터링 및 보고-기기 실시간 사용 현황 모니터링-하드웨어 정보, 설치된 앱 취합-특정 앱 사용 통계 수집 및 분석 • 보안 관련 기능 개발-승인 없는 앱 차단-사이트 블랙리스트 적용 및 유해사이트 차단-위치 추적 및 시간별 위치 모니터링-외부 저장매체 접근 차단 • 통신 기능 개발-서버를 통해 실시간 정책 관리-사용자 및 모니터링 정보를 서버에 전달 자격요건 및 우대사항• 안드로이드 개발자 (경력 5년 이상)-Java/Kotlin 기반 안드로이드 앱 개발 경험-AOSP(Android Open Source Project) 이해 및 활용 경험-MDM 관련 API 및 보안 관련 지식 보유-네트워크, 데이터베이스, RESTful API 연동에 대한 이해] • iOS 개발자 (경력 5년 이상)-Swift/Objective-C 기반 iOS 앱 개발 경험-Apple MDM 관련 프로토콜 및 정책 이해-Cocoa Touch Framework 활용 및 보안 관련 지식 보유-APNs, 서버 연동, 인증/권한 관리 구현 경험 • 공통 우대 사항-MDM 솔루션 또는 기기 관리 시스템 개발 유경험자-Google Play Store / Apple App Store 앱 출시 및 운영 경험자-보안 및 개인정보 보호 관련 프로젝트 경험-대규모 사용자/조직 구조를 대상으로 한 서비스 운영 노하우-문제 해결 능력이 뛰어나고, 기획·디자인·QA 등 타 부서와 협업 경험이 풍부하신 분 • 기술 연구소 Agent 팀 부서 소속, 주임연구원/선임연구원/책임연구원 직급으로 함께할 예정이에요.📋 자격요건• 경력 5년 이상• 대학졸업(2,3년)이상, 졸업 예정자 지원가능📋 우대사항• 전공: 공학계열• 보유역량: 해당직무 근무경험🏠 근무조건• 고용형태 : 정규직(수습 3개월)  • 급여 : 면접 후 결정 • 근무지 : 서울 금천구 가산디지털1로 168 우림라이온스밸리 B동 10층 1001호~1003호 • 근무요일/시간 : 주 5일(월~금) 09:00~18:00 🎁 복지 및 혜택• 교육/생활 : 창립일행사, 간식 제공, 음료제공(차,커피)• 리프레시 : 연차, 경조휴가제, 반차, 근로자의날 휴무, 육아휴직• 급여제도 : 장기근속자 포상, 퇴직금, 4대 보험• 근무 환경 : 회의실, 사무용품 지급🚀 채용절차접수기간 : 2026-04-30 15시 ~ 2026-05-31 24시제출서류 : 사람인 온라인 이력서접수방법 : 사람인 입사지원전형절차 : 서류전형 → 1차면접 → 최종합격🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.• 모집분야별로 마감일이 상이할 수 있으니 유의하시길 바랍니다.


    var i;

    var showQuickLogin = function () {
        if (window.top.Saramin && window.top.Saramin.showQuickLogin) {
            window.top.Saramin.showQuickLogin();
        }
    };

    window.onload = function () {
        var frames = document.getElementsByTagName("iframe");
        for (i = 0; i < frames.length; i++) {
            if(frames[i].src.indexOf(''?'') > -1) {
                frames[i].src = frames[i].src.replace(''autoplay=1'', ''autoplay=0'');
                frames[i].src += ''&wmode=transparent'';
            } else {
                frames[i].src += ''?wmode=transparent'';
            }

        }
        var embedes = document.getElementsByTagName("embed");
        for (i = 0; i < embedes.length; i++) {
            embedes[i].wmode = ''transparent'';
        }

        var aList = document.querySelectorAll(''a,area'');
        var aLength = aList.length;

        for (i = 0; i < aLength; i++) {
            var aLink = aList[i];
            var href = aLink.getAttribute(''href'') || '''';

            if (href.indexOf(''mailto:'') !== -1 || href.indexOf(''tel:'') !== -1 || href.match(''#(.*)'') !== null) {
                continue;
            }

            aLink.setAttribute(''target'', ''_blank'');
        }

        var aTagList = document.querySelectorAll(''a,area'');
        for (i = 0; i < aTagList.length; i++ ){
            aTagList[i].addEventListener(''mousedown'', function (e) {
                var item = e.currentTarget;
                var href = item.getAttribute(''href'') || '''';

                Saramin.checkUpdateHomepage(href);
            });
        }

        if (window.top.JobsView) {
            window.top.JobsView.revealMail(document.getElementsByClassName("enc_mail"));
        } else if (window.top.revealMail) {
            window.top.revealMail(document.getElementsByClassName("enc_mail"))
        }
    };

    var Saramin = {};
    Saramin.checkUpdateHomepage = function(href) {
        var isFile = false,
            urlLastSpiceByDot = href.split(''.'').pop().toLowerCase(),
            fileExtWord = [''hwp'', ''doc'', ''docx'', ''ppt'', ''pptx'', ''pdf'', ''xls'', ''xlsx'', ''rtf'', ''gul''],
            fileExtCompress = [''zip'', ''alz'', ''rar'', ''lzh'', ''arj'', ''egg'', ''tar'', ''sit''],
            fileExtImageFlash = [''jpg'', ''gif'', ''png'', ''psd'', ''fla'', ''ai'', ''jpe'', ''jpeg'', ''tif'', ''tiff'', ''pcx'', ''swf''],
            fileExt;

        fileExt = fileExtWord.concat(fileExtCompress).concat(fileExtImageFlash);
        isFile = (fileExt.indexOf(urlLastSpiceByDot) !== -1);

        if (href != '''' && isFile === false && href.indexOf(''mailto:'') === -1
            && href.indexOf(''pds.saramin.co.kr'') === -1 && href.indexOf(''uf.daum.net'') === -1 && href.indexOf(''drive.google.com'') === -1
        ) {
            try {
                Saramin.updateHomepageLink(''53773203'', ''homepage'');
            } catch (e) {}
        }
    };
    Saramin.updateHomepageLink = function(rec_idx, form_gb) {
        var i = new Image();
        i.src    = "/zf_user/track-apply-form/update-homepage-apply-form-cnt-ajax?rec_idx=" + rec_idx + "&form_gb=" + form_gb + ''&'' + "t_category=&t_content=&t_ref=&t_ref_content=";
        i.onload = function () {};
    };


    /*
    isImgLoad = function (img) {
        if (!img.complete) {
            return false;
        }

        if (img.naturalWidth === 0) {
            return false;
        }

        return true;
    };

    setTimeout(function () {
        var tagList = document.querySelector(".user_content").querySelectorAll(''img'');
        var tagListLength = tagList.length;

        for (var i = 0; i < tagListLength; i++) {
            var item = tagList[i];
            if (!isImgLoad(item)) {
                item.setAttribute(''src'', '''');
                item.parentElement.removeChild(item);

                if (document.execCommand) {
                    document.execCommand("Stop", false);
                }

                if (window.stop) {
                    window.stop();
                }
            }
        }
    }, 10000);
    */', 'iOS 개발자', 14) ON CONFLICT DO NOTHING;
INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53820701', 'iOS 개발자채용', '(주)참슬테크', '{"iOS","Swift"}', 'iOS 개발자 채용모집분야iOS 개발자 채용📋 주요업무• iOS 개발자 - 아이폰 앱 신규 기능 개발  - 아이폰 앱 개선 개발 업무📋 자격요건• 경력 8년 이상• 대학졸업(2,3년)이상• 전공 : 전산학, 컴퓨터공학, 응용소프트웨어공학, 정보통신공학 등• Swift 언어 능숙자: 최신 Swift 문법과 UI 프레임워크 활용 능력• 데이터 연동 및 최적화: 서버와 데이터를 주고받고, 끊김 없이 화면에  보여주는 기술📋 우대사항• 앱스토어 출시 및 운영 경험, 최신 디자인 트렌드에 대한 높은 이해도• BLE  개발 경험자🏠 근무조건 • 고용형태 : 정규직(수습 3개월) • 급여 : 면접 후 결정 • 근무지 : 서울 영등포구 양평로 149 선유도 우림라이온스밸리 A 806호 • 근무요일/시간 : 주 5일 (월~금) 08:30~17:30🎁 복지 및 혜택• 교육/생활 : 워크샵, 신규 입사자 교육(OJT), 야유회 / 체육대회• 리프레시 : 연차• 급여제도 : 퇴직연금, 장기근속자 포상, 우수사원포상, 4대 보험• 조직 문화 : 자유복장🚀 채용절차 접수기간 : 2026-05-07 16시 ~ 채용시 제출서류 : 사람인 온라인 이력서 접수방법 : 사람인 입사지원 전형절차 : 서류전형 → 1차 면접 → 2차 면접(필요 시) → 최종합격🛎️ 유의사항• 입사지원 서류에 허위사실이 발견될 경우, 채용확정 이후라도 채용이 취소될 수 있습니다.


