INSERT INTO job_postings (rec_idx, title, company, skills, detail_text, search_keyword, category_id) VALUES ('53776048', '모바일 앱 개발자(신입)', '지그키', '{"Android","Flutter","iOS","Kotlin","React","Swift","REST","Git"}', '모바일 앱 개발자(신입)        
    
    
                
            
